INSERT INTO `papers` (`id`, `name`, `description`, `created_at`) VALUES (62, '进阶版第20套', '教育公共基础笔试 · 进阶版第20套', '2026-11-10 11:49:30');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1, 1, 1, 'judge', 0.6, '某小学数学老师教学乘法时，先让学生用加法算 3 + 3 + 3 + 3 = 12，再引入乘法 3×4 = 12。这种从加法到乘法的学习属于下位学习。', '[["A","正确"],["B","错误"]]', '["A"]', '乘法是几个相同加数连加的简便运算，是加法概念下的派生类属概念。学生在已掌握加法的基础上学习乘法，新概念从属于原有概念，属于奥苏贝尔所说的下位学习（派生类属学习）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2, 1, 2, 'judge', 0.6, '高一学生小柯在“学医还是学文”之间犹豫：父母希望他学医，他自己热爱文学，两个目标都想得到却只能选择其一。小柯面临的这种心理冲突属于趋避冲突。', '[["A","正确"],["B","错误"]]', '["B"]', '两个都想要的目标只能择其一，属于双趋冲突（接近—接近型冲突）。趋避冲突是指同一个目标同时具有吸引力和排斥力；双避冲突是两个目标都想回避却必须选择其一。题干把双趋冲突误判为趋避冲突。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3, 1, 3, 'judge', 0.6, '某中学物理老师在学生回答与预设答案不同时，总是追问“你为什么这样想”，要求学生说明理由和依据。这种做法有利于培养学生的批判性思维。', '[["A","正确"],["B","错误"]]', '["A"]', '批判性思维要求学生对观点进行理性审视、有根据地思考和论证。教师持续追问理由和依据，能促使学生不盲从结论、学会用证据支持观点。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (4, 1, 4, 'judge', 0.6, '小学六年级学生小芳学完百分数后，能用百分数表示折扣、利率等生活中的比例关系。这种把课堂知识用于新情境的表现体现了学习迁移。', '[["A","正确"],["B","错误"]]', '["A"]', '学习迁移是指一种学习对另一种学习的影响。学生把课堂上获得的百分数知识运用到折扣、利率等陌生的生活情境中，属于知识在新情境中的正迁移。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (5, 1, 5, 'judge', 0.6, '某市教育局在评估中发现某校向学生统一推销教辅资料并收取费用，遂责令学校立即整改、退还费用。该教育局的处理于法有据。', '[["A","正确"],["B","错误"]]', '["A"]', '依据《中华人民共和国义务教育法》第二十五条，学校不得违反国家规定收取费用，不得以向学生推销或者变相推销商品、服务等方式谋取利益；《中小学教师违反职业道德行为处理办法》也明令禁止教师强制或变相强制学生订购教辅。教育行政部门有权责令改正、退还费用。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (6, 1, 6, 'judge', 0.6, '某小学教师为提高成绩，每天布置大量重复性抄写作业，多数学生要写到深夜。该做法违反了“双减”政策关于作业总量和时长调控的要求。', '[["A","正确"],["B","错误"]]', '["A"]', '《关于进一步减轻义务教育阶段学生作业负担和校外培训负担的意见》要求小学三至六年级书面作业平均完成时间不超过60分钟，并鼓励布置分层、弹性和个性化作业，避免机械重复训练。大量重复性抄写加重了学生负担。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (7, 1, 7, 'judge', 0.6, '英语考试中，小明做阅读理解时先快速浏览全文把握结构，再带着题目回读相关段落。小明运用的主要是元认知策略。', '[["A","正确"],["B","错误"]]', '["A"]', '先浏览全文以确定阅读目标和重点，属于元认知策略中的计划策略；带着问题有针对性地回读、随时检验自己是否读懂，属于监控策略。二者均属元认知策略。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (8, 1, 8, 'judge', 0.6, '心理辅导老师把辅导中获悉的学生家庭变故等隐私，当作谈资告诉了其他任课教师。该做法侵犯了学生的隐私权。', '[["A","正确"],["B","错误"]]', '["A"]', '《中华人民共和国未成年人保护法》第四条规定处理未成年人事项应当保护未成年人隐私权和个人信息。心理辅导记录涉及未成年人个人隐私，未经本人及其监护人同意不得向无关人员披露。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (9, 1, 9, 'judge', 0.6, '某初中教师试行翻转课堂：基础知识由学生课前借助微课自学，课堂主要用于答疑、探究和协作练习。这种模式有利于培养学生的自主学习能力。', '[["A","正确"],["B","错误"]]', '["A"]', '翻转课堂把知识传授前移到课前由学生自主完成，课堂则转向深度学习与合作探究，客观上要求并锻炼学生自我规划、自我监控的学习能力。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (10, 1, 10, 'judge', 0.6, '某小学教师以成绩差为由，长期安排一名学生单独坐在教室最后一排。该做法没有侵犯学生的合法权益。', '[["A","正确"],["B","错误"]]', '["B"]', '依据《中华人民共和国义务教育法》和《未成年人保护法》，学生在入学、升学等方面依法享有平等权利，其人格尊严应受尊重。因成绩差而将学生孤立地安排在最后一排，带有歧视和标签意味，侵犯了学生的平等受教育权和人格尊严。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (11, 1, 11, 'judge', 0.6, '某中学组织学生停课参加某商家开业庆典以烘托人气，并接受了商家支付的“活动费”。学校认为这属于正常的社会实践活动，于法不悖。', '[["A","正确"],["B","错误"]]', '["B"]', '《中华人民共和国义务教育法》第二十五条明确禁止学校以向学生推销或者变相推销商品、服务等方式谋取利益。组织学生参加商业庆典并收取费用，既影响正常教学秩序，又属利用学生牟利的违法行为。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (12, 1, 12, 'judge', 0.6, '语文老师教一篇新课文时，先让学生默读感知，再指名朗读体会情感，最后组织讨论、归纳主旨。这一安排符合由感知到理解、再到表达的认识规律。', '[["A","正确"],["B","错误"]]', '["A"]', '默读侧重整体感知文本，朗读深化情感体验，讨论与归纳则推动理解走向理性概括和口头表达。整个过程由感性到理性、由输入到输出，符合学生认识发展的一般规律。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (13, 1, 13, 'judge', 0.6, '校运动会上，一名学生在已被检查过的场地内比赛时，因突发阵雨导致场地湿滑而摔伤。学校赛前检查了场地并作了安全提醒，其已尽到教育管理职责，不承担侵权责任。', '[["A","正确"],["B","错误"]]', '["A"]', '依据《中华人民共和国民法典》第一千一百九十九条、第一千二百条及《学生伤害事故处理办法》，学校对学生伤害承担过错责任。学校赛前检查场地、进行安全教育，对突发阵雨这一难以预见的情形没有过错，故依法不承担侵权责任。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (14, 1, 14, 'judge', 0.6, '某初中教师利用午休时间为学习困难学生义务辅导，分文未取。该教师的行为违反了严禁有偿补课的规定。', '[["A","正确"],["B","错误"]]', '["B"]', '《严禁中小学校和在职中小学教师有偿补课的规定》所禁止的是组织、参与有偿补课或收受费用的行为。该教师利用休息时间免费辅导学生，不具有有偿性，不属于有偿补课。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (15, 1, 15, 'judge', 0.6, '某县建立义务教育优质均衡发展督导评估机制，把校际差距、随迁子女入学、教师交流等情况纳入对政府履行教育职责的考核。这种做法不利于扩大校际差距，也不是推进义务教育均衡的重要抓手。', '[["A","正确"],["B","错误"]]', '["B"]', '依据《义务教育优质均衡发展县（市、区）评估认定标准》和教育督导条例，对县级政府开展义务教育优质均衡发展督导评估，把资源配置、校际差距、教师交流等纳入考核，正是推动义务教育优质均衡、督促政府履职的重要制度安排。题干否定其作用。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (16, 1, 16, 'judge', 0.6, '根据皮亚杰的认知发展阶段理论，能够进行假设—演绎推理、抽象逻辑思维的中学生，其认知发展处于具体运算阶段。', '[["A","正确"],["B","错误"]]', '["B"]', '皮亚杰认知发展理论中，具体运算阶段（约7—11岁）的儿童虽获得守恒概念，但思维仍需具体事物支持；能够脱离具体情境进行假设—演绎推理和抽象逻辑思维，是形式运算阶段（约11岁以后）的典型特征。题干阶段归属错误。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (17, 1, 17, 'judge', 0.6, '班主任只指定几名成绩优秀、能力强的学生长期固定担任班干部，认为这样班级管理更高效，其他学生无需参与。这体现了面向全体学生的教育理念。', '[["A","正确"],["B","错误"]]', '["B"]', '素质教育要求面向全体学生，促进每一名学生主动发展。只让少数优秀学生长期固定担任班干部，剥夺了多数学生参与班级管理、获得锻炼的机会，是面向少数学生的做法，违背了面向全体学生的教育理念。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (18, 1, 18, 'judge', 0.6, '学生设计出有创意的物理实验方案，教师担心“耽误复习、影响考试成绩”，不予表扬也不推荐其参加科技创新比赛。该做法有利于培养学生的创新精神和实践能力。', '[["A","正确"],["B","错误"]]', '["B"]', '培养创新精神和实践能力是素质教育的重点。教师对学生的创新设计持消极态度、不予鼓励和支持，会挫伤学生探究与创造的积极性，与素质教育要求背道而驰。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (19, 1, 19, 'judge', 0.6, '学生在解几何题时能够举一反三，把刚学的一种证明方法灵活用于多道变式题。这说明其产生了正迁移。', '[["A","正确"],["B","错误"]]', '["A"]', '正迁移是指先前学习对后继学习产生积极的促进作用。学生把习得的证明方法成功运用到同类变式题中，促进了新问题的解决，属于正迁移。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (20, 1, 20, 'judge', 0.6, '某市教育局明确要求学校不得把考试成绩排名作为评价学生的唯一依据。这一要求体现了多元化评价的理念。', '[["A","正确"],["B","错误"]]', '["A"]', '《深化新时代教育评价改革总体方案》要求创新过程性评价方法、完善综合素质评价体系，改变以分数给学生贴标签的做法。不以成绩排名为唯一依据，正体现了评价内容、方式和主体的多元化。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (21, 1, 21, 'judge', 0.6, '学生在课堂上提出与教材不同的看法，任课教师为维护教材权威和课堂秩序，当即予以否定并提醒其他学生不要效仿。该做法有利于保护学生的好奇心和求知欲。', '[["A","正确"],["B","错误"]]', '["B"]', '好奇心和求知欲是创造性思维的起点。教师对学生的异见简单否定、当众压制，会造成紧张的心理氛围，使学生不敢质疑，损害其探究兴趣和批判精神；正确做法是肯定独立思考并引导辨析求证。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (22, 1, 22, 'judge', 0.6, '小丽学习时总等老师给出标准答案，不习惯主动质疑和探究。从建构主义学习理论看，她需要转变为知识的主动建构者。', '[["A","正确"],["B","错误"]]', '["A"]', '建构主义认为，学习不是知识由教师向学生的单向传递，而是学生在原有经验基础上主动建构意义的过程。被动等待答案难以实现深层理解，小丽应主动探究、合作建构。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (23, 1, 23, 'judge', 0.6, '学生每次作业没达到教师要求，都要被点名批评并罚重做。学生为了不被批评，不得不认真完成作业。从强化理论看，教师的批评在这里起到了正强化的作用，这种说法是正确的。', '[["A","正确"],["B","错误"]]', '["B"]', '正强化是行为发生后呈现愉快刺激以提高行为概率。批评是学生力图回避的厌恶刺激，学生为逃避或避免批评而认真完成作业，属于负强化（撤销厌恶刺激的预期）或惩罚情境，并非正强化。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (24, 1, 24, 'judge', 0.6, '某小学把一名受警告处分学生的姓名、班级和处分决定在全校大会上宣读，并张贴于公告栏。学校认为这是正当的警示教育，不构成侵权。', '[["A","正确"],["B","错误"]]', '["B"]', '《中华人民共和国未成年人保护法》要求保护未成年人的人格尊严和隐私权、个人信息。对违纪学生的处分应在必要范围内告知本人及其监护人，公开宣读、张贴处分决定带有示众羞辱性质，会使学生的违纪信息被不当扩散，侵犯其人格尊严和隐私权。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (25, 1, 25, 'judge', 0.6, '教师节来临，某班家长委员会凑钱为班主任购买了一条名牌项链，班主任认为家长的好意不便推辞，便收下了。该做法符合教师职业行为准则。', '[["A","正确"],["B","错误"]]', '["B"]', '《新时代中小学教师职业行为十项准则》和《中小学教师违反职业道德行为处理办法》明确要求教师坚守廉洁自律，不得收受学生及家长赠送的可能影响公正执行公务的礼品礼金。项链价值较高，班主任应当婉言谢绝。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (26, 1, 26, 'judge', 0.6, '某初中教师每节课都以系统讲授为主，把知识完整讲透并要求学生认真听讲记笔记，几乎不安排自主学习和合作探究。与问题导向、自主探究的教学相比，这种全程系统讲授更能突出学生的主体地位。', '[["A","正确"],["B","错误"]]', '["B"]', '系统讲授以教师活动为主，学生主要是被动接受；问题导向教学通过自主学习、合作探究让学生主动建构知识，更能突出学生的主体地位。题中全程讲授、缺少学生主动参与，反而是教师主体而非学生主体。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (27, 1, 27, 'judge', 0.6, '考试失利后，小强认为“题太难、运气差”，自己怎么努力也没用，于是愈发消沉。他的这种反应符合习得性无助的表现。', '[["A","正确"],["B","错误"]]', '["A"]', '习得性无助是指个体反复经历失败后，形成无论怎样努力都无法控制结果的信念，进而产生逃避、放弃等反应。小强把失败外归因并断定努力无用、情绪消沉，正是习得性无助的典型表现。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (28, 1, 28, 'judge', 0.6, '学生把连续几次考试失利都归因于“自己天生脑子笨”，并认为再努力也改变不了。这种归因会增强其后续学习的坚持性。', '[["A","正确"],["B","错误"]]', '["B"]', '“天生脑子笨”属于内部、稳定、不可控的能力归因。依据韦纳归因理论，把失败稳定地归于能力不足，会降低自我效能感和成功预期，导致放弃努力，而非增强坚持性。教师应引导其归因于努力、方法等可控因素。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (29, 1, 29, 'judge', 0.6, '化学实验中学生如实记录了一个与预期不符的现象，教师以“不在考试范围内”为由要求其删除记录。该做法有利于培养学生的科学精神。', '[["A","正确"],["B","错误"]]', '["B"]', '实事求是、尊重证据是科学精神的核心。教师要求学生删除真实的意外记录，违背了严谨求实的治学态度，也错失了引导学生分析异常现象的教育契机。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (30, 1, 30, 'judge', 0.6, '2024年8月26日，中共中央、国务院印发《关于弘扬教育家精神加强新时代高素质专业化教师队伍建设的意见》。该文件将教育家精神凝练为“心有大我、至诚报国”等十个方面，其中“勤学笃行、求是创新的躬耕态度”要求教师严谨笃学、求真创造。', '[["A","正确"],["B","错误"]]', '["A"]', '该文件确由中共中央、国务院于2024年8月26日印发，全称为《关于弘扬教育家精神加强新时代高素质专业化教师队伍建设的意见》。教育家精神包括心有大我至诚报国、言为士则行为世范、启智润心因材施教、勤学笃行求是创新、乐教爱生甘于奉献、胸怀天下以文化人等十个方面，题干时间、文件名和对躬耕态度的表述均正确。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (31, 1, 31, 'single', 1.0, '三年级数学老师教学面积时，先让学生用手掌量课桌面，再用方格纸量，最后引出面积公式。这一教学过程体现了（　）', '[["A","从理论到实践的顺序原则"],["B","从一般到个别的演绎过程"],["C","从具体到抽象的认识规律"],["D","从抽象到具体的认识规律"]]', '["C"]', '手掌测量是具体操作，方格纸是半抽象的表象工具，面积公式是抽象概括。教学沿着动作感知—表象—概念的路径推进，体现了从具体到抽象的认识规律。A项“顺序原则”强调由浅入深、由易到难的组织顺序，与题意不完全吻合；B项方向相反（从一般到个别属于演绎，而题干是从个别到一般）；D项方向也相反。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (32, 1, 32, 'single', 1.0, '小明学习英语语法时，常把英语和汉语的句式放在一起比较，找出二者的异同。他运用的学习策略主要是（　）', '[["A","复述策略"],["B","精细加工策略中的比较法"],["C","组织策略中的归类法"],["D","元认知策略中的监控策略"]]', '["B"]', '比较法是精细加工策略的重要方法，通过对易混知识逐项对照异同，加深理解和辨别。将中英语法进行对比正是比较法的运用。复述侧重重复巩固，组织侧重归类建网，元认知侧重对学习过程的计划与监控，均不贴切。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (33, 1, 33, 'single', 1.0, '物理兴趣小组探究单摆周期时，几名中学生先提出“周期可能与摆长、摆锤质量、释放角度都有关”的猜想，再固定其他条件、每次只改变一个变量，分别设计实验加以检验。依据皮亚杰的认知发展阶段理论，这种系统的假设—演绎推理表明他们处于（　）', '[["A","感知运动阶段"],["B","具体运算阶段"],["C","前运算阶段"],["D","形式运算阶段"]]', '["D"]', '皮亚杰通过钟摆实验等研究发现，形式运算阶段（约11岁以后）的个体能够针对问题提出多种假设，并运用控制变量、假设—演绎的方法系统验证。前三个阶段（感知运动、前运算、具体运算）的儿童尚不能脱离具体情境进行严密的假设检验。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (34, 1, 34, 'single', 1.0, '物理教师在讲浮力前先问：“为什么铁块沉入水中，而钢铁造的轮船却能浮在水面？”以激发学生的求知欲。该导入方式属于（　）', '[["A","直接导入"],["B","故事导入"],["C","复习导入"],["D","问题导入"]]', '["D"]', '教师围绕教学内容设置悬念性问题，使学生产生认知冲突和探究愿望，属于问题导入（设疑导入）。复习导入依托旧知，故事导入借助故事情境，直接导入则开门见山点明课题，均与题干不同。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (35, 1, 35, 'single', 1.0, '某生因考试取得进步，被老师在班上当众表扬，此后他学习更加努力。按班杜拉的强化分类，该生受到的强化属于（　）', '[["A","自我强化"],["B","替代强化"],["C","负强化"],["D","直接强化"]]', '["D"]', '直接强化是指学习者本人的行为因直接得到外部强化而增强。该生自己的进步行为直接受到教师表扬，属于直接强化。替代强化是观察他人受奖惩而受影响，自我强化是依据自己的标准自我奖惩，负强化是撤销厌恶刺激以增加行为。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (36, 1, 36, 'single', 1.0, '某市明确要求义务教育阶段学校招生不得采取笔试、面试或任何变相形式的知识性考查。这一要求主要在于维护（　）', '[["A","学校分层教学的自主权"],["B","民办学校优先招生的权利"],["C","适龄儿童免试就近入学的权利"],["D","学校依法自主招生的权利"]]', '["C"]', '《中华人民共和国义务教育法》第十二条规定，适龄儿童、少年免试入学，地方各级人民政府应当保障其在户籍所在地学校就近入学。禁止入学考试和面试，目的在于维护免试就近入学原则和教育公平。B、D项与免试入学要求无关，民办学校招生同样纳入免试入学规范管理。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (37, 1, 37, 'single', 1.0, '学生在化学方程式配平中反复出错。下列做法中，最有利于从根本上解决问题的是（　）', '[["A","先引导学生理解质量守恒定律再学配平"],["B","让学生熟记配平口诀和典型例题"],["C","降低要求，暂不要求掌握配平"],["D","增加抄写和重复练习的数量"]]', '["A"]', '配平的依据是质量守恒定律。学生理解反应前后原子种类、数目不变的本质后，才能在新情境中灵活配平，这属于有意义学习，能从根本上减少错误。机械重复和背诵口诀只形成暂时的技能，回避难点则不能解决问题。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (38, 1, 38, 'single', 1.0, '初二学生小杰总认为同学和老师都在注意自己的发型和穿着，因而在集体活动中格外紧张、不敢表现。这种“感到自己是他人关注中心”的心理属于（　）', '[["A","客体永久性"],["B","假想的观众"],["C","守恒观念"],["D","思维的不可逆性"]]', '["B"]', '青少年自我中心思维的典型表现之一是“假想的观众”，即总觉得自己处在他人关注的焦点，因而过分在意自己的外表和行为。不可逆性、缺乏守恒是前运算阶段儿童的特点，客体永久性形成于感知运动阶段，均与题干不符。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (39, 1, 39, 'single', 1.0, '学生解题时习惯于沿用同一种思路，想不到其他途径，思维明显缺乏变通。教师应着重培养其（　）', '[["A","观察力的敏锐性"],["B","思维的流畅性"],["C","注意力的稳定性"],["D","思维的变通性（灵活性）"]]', '["D"]', '发散思维具有流畅性、变通性和独创性三个特征。只能用一种方法、不能多角度转换思路，反映变通性不足，应通过一题多解、条件变式等训练加以培养。流畅性强调单位时间内观念的数量，注意、观察品质与题干问题不对应。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (40, 1, 40, 'single', 1.0, '学校要求教师每学期至少精读一本教育专著并撰写读书笔记。这一要求直接体现的师德规范是（　）', '[["A","终身学习"],["B","为人师表"],["C","爱岗敬业"],["D","关爱学生"]]', '["A"]', '《中小学教师职业道德规范》中的“终身学习”要求教师崇尚科学精神、树立终身学习理念、拓宽知识视野、更新知识结构。持续研读专业著作、撰写笔记是教师专业自我更新的典型表现。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (41, 1, 41, 'single', 1.0, '数学课上，老师讲“果实”时既举苹果、花生等可食用的例子，也举棉籽、橡子等不可直接食用的例子，并对比“果实与根、茎”。这些变化正例与反例的运用主要是为了促进学生（　）', '[["A","产生学习迁移"],["B","对概念的变式掌握"],["C","形成操作技能"],["D","机械识记定义"]]', '["B"]', '变式是指变换概念的非本质特征、保持本质特征不变的各类正例，配合反例比较，可帮助学生排除无关特征、准确概括概念的本质属性。机械识记不强调例证比较；操作技能、学习迁移与题干例证设计的直接目的不符。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (42, 1, 42, 'single', 1.0, '学生在学习新概念时，总是主动寻找它与已有知识之间的内在联系。按奥苏贝尔的理论，这种学习属于（　）', '[["A","有意义学习"],["B","机械学习"],["C","发现学习"],["D","信号学习"]]', '["A"]', '有意义学习的实质是符号所代表的新知识与学习者认知结构中已有的适当观念建立非人为的、实质性的联系。学生主动把新旧知识联系起来，正是有意义学习的表现。机械学习缺乏这种联系，发现学习强调知识获得的方式，信号学习属于较低级的学习层次。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (43, 1, 43, 'single', 1.0, '学生小雯学习十分刻苦，但总把考试成绩归结为题目难易、临场运气等自己无法左右的因素。依据韦纳的成败归因理论，这些因素主要属于（　）', '[["A","外部、不可控的因素"],["B","内部、可控的因素"],["C","内部、稳定的因素"],["D","内部、不稳定的因素"]]', '["A"]', '韦纳把归因分为内外源、稳定性、可控性三个维度。任务难度属外部、稳定、不可控，运气属外部、不稳定、不可控，二者共同点是外部且不可控。努力才是内部、不稳定、可控因素，能力是内部、稳定、不可控因素。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (44, 1, 44, 'single', 1.0, '课间，两名七年级学生聊起为什么而学。泽宇说：“我学几何完全是因为图形证明太有意思了，越想越入迷，搞不懂就睡不着。”他既没想着拿名次，也不为换取表扬。按照奥苏贝尔对学校情境中成就动机成分的划分，泽宇身上占主导的是（　）', '[["A","附属内驱力"],["B","认知内驱力"],["C","生理需要驱动"],["D","自我提高内驱力"]]', '["B"]', '认知内驱力是一种指向学习任务本身、以求知和解决问题为满足的内部动机，在有意义学习中是最重要、最稳定的动机。泽宇因几何本身的趣味而主动钻研、不计名次表扬，正属认知内驱力。自我提高内驱力指向由成就带来的地位与自尊，附属内驱力指向获得长者和同伴赞许。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (45, 1, 45, 'single', 1.0, '教师先呈现一个真实问题，让学生带着问题研读教材、查找资料，再在讨论中形成认识。这种教学的主要理论基础是（　）', '[["A","认知—接受学习理论"],["B","建构主义学习理论"],["C","行为主义学习理论"],["D","人本主义学习理论"]]', '["B"]', '建构主义强调学习的情境性和主动建构性，主张通过真实问题情境中的探究、协作与会话，由学生自主建构知识意义。基于问题、借助资料和讨论的教学与此高度一致。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (46, 1, 46, 'single', 1.0, '某小学将消防安全、应急疏散演练纳入学校安全管理制度，规定每学期至少组织一次。学校开展安全教育和应急演练的直接部门规章依据是（　）', '[["A","《中华人民共和国民办教育促进法》"],["B","《中华人民共和国高等教育法》"],["C","《中小学幼儿园安全管理办法》"],["D","《中华人民共和国学位条例》"]]', '["C"]', '《中小学幼儿园安全管理办法》（教育部等部门发布）明确规定，学校应当对学生开展消防安全、交通安全等安全教育，制定应急预案并定期组织应急演练，是中小学开展疏散演练最直接的规范依据。A、B、D项均不针对中小学日常安全管理与演练。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (47, 1, 47, 'single', 1.0, '每逢数学考试前，某生就出现头痛、肚子痛、心慌出汗等症状，进入考场后注意力难以集中，考试结束症状随即缓解。该生最可能的问题是（　）', '[["A","躯体器质性疾病"],["B","一般性厌学情绪"],["C","考试焦虑"],["D","注意缺陷多动障碍"]]', '["C"]', '考试焦虑是在一定应试情境下，受个体认知评价、人格倾向等影响而产生的以担忧为特征、伴有生理唤醒的心理状态，躯体化症状随考试情境出现和消退是其典型表现。器质性疾病不会随考试结束而缓解，注意缺陷障碍具有跨情境的持续性。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (48, 1, 48, 'single', 1.0, '学生苦练硬笔书法一段时间后，最初进步明显，但随后连续几周成绩似乎停滞不前，再练也难有提高，甚至出现烦躁情绪。这种练习中期出现的成绩暂时停顿现象，在心理学上称为（　）', '[["A","功能固着现象"],["B","高原现象"],["C","迁移现象"],["D","遗忘现象"]]', '["B"]', '在操作技能形成过程中，练习中期常出现成绩提升暂时停顿、甚至略有下降的现象，称为“高原现象”，其成因包括旧动作结构需要改造、练习方法不当、兴趣和动机下降等。迁移是学习之间的相互影响，遗忘是记忆内容的消退，功能固着属于问题解决中的思维障碍。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (49, 1, 49, 'single', 1.0, '期末复习时，小周把英语单词分散在两周内每天记忆20分钟，而不是考前一天连续背4小时。这种安排主要利用了（　）', '[["A","集中复习优于分散复习的规律"],["B","倒摄抑制的作用"],["C","艾宾浩斯遗忘先快后慢的规律"],["D","高原现象的规律"]]', '["C"]', '艾宾浩斯遗忘曲线表明遗忘进程先快后慢、先多后少，因此应及时复习、合理分散复习时间，在大规模遗忘发生前加以巩固。一般情况下分散复习效果优于集中复习；倒摄抑制指后学材料对先学材料的干扰；高原现象是技能练习中期出现的暂时停顿。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (50, 1, 50, 'single', 1.0, '某中学开设生涯规划课程，引导学生认识自己的兴趣、能力与价值观，了解职业世界并规划发展方向。该课程在德育内容上主要属于（　）', '[["A","人生观与生涯发展指导"],["B","美育中的审美教育"],["C","劳动技术教育中的技能训练"],["D","智育中的思维训练"]]', '["A"]', '德育包括理想信念、社会主义核心价值观、生涯规划等内容。生涯规划教育帮助学生认识自我、明确人生目标，属于德育中的人生观、价值观教育和人生（生涯）发展指导。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (51, 1, 51, 'single', 1.0, '校篮球赛中，一名学生在正常对抗中落地受伤。赛前学校进行了专项安全教育、检查了场地并配备了校医。依法学校（　）', '[["A","无论有无过错均应补偿"],["B","已尽到教育管理职责，不承担侵权责任"],["C","应与对方学生平均分担损失"],["D","应承担全部赔偿责任"]]', '["B"]', '依据《民法典》第一千二百条，限制民事行为能力人在学校学习、生活期间受到人身损害，学校未尽到教育、管理职责的才承担责任。学校已开展安全教育、检查场地、配备医护人员，对正常竞技中的意外受伤没有过错，故不承担侵权责任。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (52, 1, 52, 'single', 1.0, '某教师因几名学生未完成作业，罚他们到操场上跑十圈，致使一名学生体力不支晕倒。该教师的行为属于（　）', '[["A","体罚，侵犯学生身体权和健康权"],["B","合法的教育惩戒"],["C","一般性的课堂管理措施"],["D","正常的体育锻炼"]]', '["A"]', '《中小学教育惩戒规则（试行）》允许的惩戒不包括超越学生身心承受能力的体力惩罚。罚跑十圈直接造成身体痛苦和伤害，属于体罚而非法惩戒，侵犯了学生的身体权、健康权。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (53, 1, 53, 'single', 1.0, '市场监管和教育行政部门联合检查时，发现某校食堂操作间卫生不达标、留样不规范，遂责令其限期改正。该执法行为（　）', '[["A","只能在发生食物中毒后实施"],["B","于法有据，是履行食品安全监管职责"],["C","应完全交由学校家委会处理"],["D","属于越权干预学校自主经营"]]', '["B"]', '依据《中华人民共和国食品安全法》和《学校食品安全与营养健康管理规定》，学校食堂实行预防为主、风险管理原则，教育、市场监管部门依法负有日常监督检查职责。事前责令限期整改正是依法履职。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (54, 1, 54, 'single', 1.0, '自习课上，教师发现一名学生正用手机玩游戏。最恰当的处理方式是（　）', '[["A","暂时代为保管，课后归还并进行教育引导"],["B","当着全班的面摔毁手机以示警戒"],["C","立即将学生逐出教室反思"],["D","当场将手机没收并永久不予归还"]]', '["A"]', '依据中小学学生手机管理相关规定，学生违规带入或使用手机的，学校可统一保管并及时告知家长。教师暂时代管、课后归还并辅以教育，既维护课堂秩序，又尊重学生财产权和人格尊严。没收不还、逐出教室、损毁财物均缺乏法律依据并可能侵权。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (55, 1, 55, 'single', 1.0, '中共中央、国务院《深化新时代教育评价改革总体方案》要求改革学生评价。下列做法中，不符合该方案方向的是（　）', '[["A","坚决改变以分数给学生贴标签的做法"],["B","健全学生综合素质评价体系"],["C","完善德智体美劳过程性评价"],["D","把升学率作为评价学校办学质量的唯一指标"]]', '["D"]', '《深化新时代教育评价改革总体方案》（2020年印发）提出坚决纠正片面追求升学率倾向，不得把升学率作为评价学校、教师和学生的唯一依据，强调过程性评价和综合素质评价。D项正是方案要破除的做法。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (56, 1, 56, 'single', 1.0, '创造思维训练课上，教师给出钳子、绳子等材料，要求学生想办法同时够到从天花板垂下的两根相距较远、无法一手同时抓住的绳子。多数学生只把钳子看作夹持工具，想不到可把它系在绳端当作摆锤，晃动绳子后趁机抓住。这一现象主要说明问题解决受到（　）', '[["A","功能固着的影响"],["B","学习动机的影响"],["C","原型启发的影响"],["D","正迁移的影响"]]', '["A"]', '功能固着是指个体只看到事物惯常的功能而看不到它其他可能用途的现象。学生只认定钳子是夹持工具，想不到它可作摆锤，这是梅尔双绳实验所揭示的功能固着。原型启发是从其他事物中找到解决问题的途径，正迁移和学习动机与该现象无关。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (57, 1, 57, 'single', 1.0, '班上的小亮打碎了教室里1只杯子后主动认错；小杰为偷吃糖果打碎了10只杯子却谎称不是自己干的。问“哪个孩子更不好、应受更重惩罚”时，小学三年级学生大多认为小杰更坏、因为打碎了10只杯子。依据皮亚杰道德发展阶段理论，这些学生的判断主要处于（　）', '[["A","他律道德阶段"],["B","自律道德阶段"],["C","公正道德阶段"],["D","前道德阶段"]]', '["A"]', '皮亚杰通过对偶故事研究发现，他律道德阶段（约5—8岁）的儿童根据行为的客观后果数量判断责任，而不考虑行为动机；自律阶段儿童才会结合主观动机判断。只看打碎杯子数量、忽视说谎与偷拿动机，属于他律道德阶段的特点。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (58, 1, 58, 'single', 1.0, '某班在校内劳动实践基地上劳动课，教师事先讲解了工具的安全使用方法并示范操作，一名学生仍未按要求握持工具，不慎被划伤。事后学校及时送医并通知家长。依法学校（　）', '[["A","应承担全部赔偿责任"],["B","已尽到教育、管理和保护职责，不承担侵权责任"],["C","无论有无过错都必须给予赔偿"],["D","应与任课教师平均分担损失"]]', '["B"]', '依据《民法典》第一千二百条和《学生伤害事故处理办法》，限制民事行为能力人在校受到人身损害，学校承担过错责任。教师已进行安全教育和操作示范、学校事后及时救助，对学生违反操作规程造成的自伤没有过错，故不承担侵权责任。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (59, 1, 59, 'single', 1.0, '课堂上，数学老师要求学生一边听讲一边在草稿本上记录关键步骤，多数学生能较好地同时完成两项任务。这主要体现了注意的（　）', '[["A","注意的稳定性"],["B","注意的转移"],["C","注意的分配"],["D","注意的范围"]]', '["C"]', '注意的分配是指个体在同一时间内把注意指向两种或两种以上的对象或活动。边听讲边记录要求学生在听和写之间合理分配注意。注意范围强调同一瞬间把握对象的数量，稳定性强调持续时间，转移强调根据任务主动把注意从一个对象转向另一个对象。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (60, 1, 60, 'single', 1.0, '一位中学教师持续跟踪本学科研究进展，把经过筛选的最新科研成果转化为教学案例，帮助学生了解学科前沿。这主要体现了（　）', '[["A","教师把科研任务转嫁给学生"],["B","以研究取代常规课堂教学"],["C","教学完全脱离教材体系"],["D","教学内容与学术研究相结合"]]', '["D"]', '教师把学科前沿成果筛选、转化为适切的教学素材，体现了科研与教学相长，有利于拓宽学生视野、培养科学素养。A项把科研成果转化曲解为“转嫁任务”，与教师主动筛选转化的行为不符；B项将科研促教绝对化为“取代课堂教学”，C项则完全否定教材体系，均与题干事实相悖。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (61, 1, 61, 'single', 1.0, '复习化学时，某生把零散的物质按“单质—化合物—混合物”的类别整理成表格，再把各类物质的性质、制法和用途归并到一起记忆。该学习策略主要属于（　）', '[["A","元认知策略中的计划策略"],["B","复述策略"],["C","精细加工策略中的记忆术"],["D","组织策略中的归类法"]]', '["D"]', '组织策略是对学习材料进行加工，按照其内在联系加以归类、整理，形成清晰认知结构的策略。该生按物质分类建表、归并性质与用途，正是归类法的典型运用。复述侧重重复巩固，记忆术侧重人为联想以增强保持，计划策略侧重对学习活动的预先安排。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (62, 1, 62, 'single', 1.0, '部分学生习惯于机械背诵，对知识不求甚解，遇到变式题就出错。教师应着重引导其（　）', '[["A","加大机械重复的遍数"],["B","放弃记忆，只做难题"],["C","在理解的基础上进行有意义学习"],["D","延长每次记忆的时间"]]', '["C"]', '机械学习获得的知识难以迁移，变式题出错的根源是没有理解知识的实质和内在联系。教师应帮助学生把新知识纳入已有认知结构，开展有意义学习，并辅以变式练习。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (63, 1, 63, 'single', 1.0, '升入初中后，小芸在家长帮助下制定学习计划时，会主动预估某项任务大约需要多长时间，并据此安排先后顺序。这种对认知活动的预先规划属于（　）', '[["A","资源管理策略中的时间管理"],["B","元认知计划策略"],["C","复述策略"],["D","精加工策略"]]', '["B"]', '元认知策略包括计划、监控和调节策略。在认知活动开始前设置目标、预估任务难度与时间、安排学习步骤，属于元认知计划策略。复述策略侧重重复保持信息，精加工策略侧重为信息增加意义，时间管理策略侧重对学习时间资源的统筹，均不直接指向对认知过程的预先规划。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (64, 1, 64, 'single', 1.0, '某校在防治校园欺凌中建立早期预警机制。下列做法中，不属于早期预警措施的是（　）', '[["A","定期开展心理健康普查并建立重点关注台账"],["B","仅在发生严重伤害事件后再介入处理"],["C","畅通学生、家长欺凌线索报告渠道"],["D","通过日常观察和同伴关系调查识别风险信号"]]', '["B"]', '早期预警强调关口前移，通过心理筛查、风险排查、线索报告和主题教育等主动发现隐患。事后处理是末端应对而非预防预警。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (65, 1, 65, 'single', 1.0, '一位教师在教学后记中写道：“今天进度偏快，部分学生来不及思考，下次应放慢节奏，多留讨论时间。”这主要反映了教师的（　）', '[["A","关注学情并自觉改进教学的反思意识"],["B","只关注教学进度完成情况"],["C","对学生差异的无条件迁就"],["D","以个人经验否定教学计划"]]', '["A"]', '教师依据课堂上观察到的学习状态审视教学，并提出针对性的调整方案，属于教学反思，体现了以学定教和持续改进的专业意识。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (66, 1, 66, 'single', 1.0, '一名学生因家境困难而自卑，很少与同学交往。班主任一方面关心鼓励他、协助其申请助学金，另一方面引导同学在小组活动中主动接纳他。该做法体现了（　）', '[["A","以经济资助代替思想教育"],["B","关爱学生与集体教育相结合"],["C","只依靠班集体进行教育"],["D","把学生的家庭情况公开通报"]]', '["B"]', '教师个人的关爱与帮扶解决了学生的实际困难和心理压力，组织同伴互助则发挥了集体的教育力量，两者结合帮助学生走出自卑，符合关爱学生与集体教育相结合的要求。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (67, 1, 67, 'single', 1.0, '一名学生因沉迷手机游戏导致成绩明显下降、上课精神不振。班主任较恰当的做法是（　）', '[["A","不经学生同意直接查阅其手机全部内容"],["B","把问题完全推给家长，学校不再过问"],["C","了解原因，引导其认识危害并共同制定合理用机计划"],["D","当众严厉训斥并永久禁止其接触手机"]]', '["C"]', '手机沉迷的成因复杂，简单禁止或放任都难以奏效。教师应在尊重学生的基础上了解需求、讲清危害，与学生、家长协商制定可执行的用机规则，并以丰富的活动转移注意。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (68, 1, 68, 'single', 1.0, '作文基础薄弱的学生，在老师系统指导和同伴互助下，能独立完成此前无法完成的800字议论文；脱离帮助后，他仍只能写约500字。维果斯基把“独立解决问题的实际水平”与“成人指导下可达到的水平”之间的差距称为（　）', '[["A","关键期"],["B","学习准备状态"],["C","最近发展区"],["D","认知风格差异"]]', '["C"]', '维果斯基提出的最近发展区，是指儿童独立解决问题所确定的现有发展水平，与在成人指导或与有能力同伴合作下解决问题所达到的潜在发展水平之间的差距，教学应着眼于“跳一跳、摘桃子”。关键期强调特定能力发展的最佳时机，认知风格、学习准备均不描述这一差距。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (69, 1, 69, 'single', 1.0, '课堂上一名学生对教材结论提出有依据的质疑。教师最恰当的回应是（　）', '[["A","暂时回避，课后单独批评"],["B","以维护教材权威为由不予讨论"],["C","提醒学生只需记住考试结论"],["D","肯定质疑精神，组织学生辨析求证"]]', '["D"]', '面对有价值的质疑，教师应发扬教学民主，把质疑转化为教学资源，引导学生寻找证据、辨析论证，既解决问题又培养批判精神。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (70, 1, 70, 'single', 1.0, '某市推行“阳光招生”，要求招生计划、程序、结果全程公开，接受社会监督。这一做法主要有利于（　）', '[["A","维护教育公平，保障群众的知情权和监督权"],["B","扩大学校的招生自由裁量权"],["C","弱化教育行政部门的监管责任"],["D","以社会评价替代教育评价"]]', '["A"]', '招生信息公开把入学机会置于社会监督之下，有助于遏制“掐尖招生”“条子生”等违规行为，保障入学机会公平和群众的知情权、监督权。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (71, 1, 71, 'single', 1.0, '学生把ambulance（救护车）谐音联想为“俺不能死”来记忆单词。这种记忆方法属于（　）', '[["A","复述策略"],["B","精细加工策略中的谐音联想法"],["C","组织策略中的纲要法"],["D","元认知策略中的调节策略"]]', '["B"]', '谐音联想法是借助读音相似把抽象、无意义材料转化为有意义表象的精细加工策略。复述、组织、元认知策略的功能与题干方法不符。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (72, 1, 72, 'single', 1.0, '学生作文普遍空洞，教师分析后发现主要原因是生活观察和体验不足。下列做法中最有针对性的是（　）', '[["A","以抄写优美句段代替写作训练"],["B","要求学生大量背诵优秀作文模板"],["C","降低字数和立意要求"],["D","组织观察、实践活动，丰富直接经验和写作素材"]]', '["D"]', '写作是对生活经验加工表达的过程。“无米下锅”靠套模板、抄句段无法根治，组织观察与实践活动可充实感性经验，解决素材贫乏的根源问题。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (73, 1, 73, 'single', 1.0, '一位教师坚持每周撰写教学反思，系统记录成功经验、问题教训和改进设想，三年后教学水平显著提升。这一专业发展途径主要是（　）', '[["A","脱产学历进修"],["B","单纯依靠专家讲座"],["C","自我反思与行动研究"],["D","同事之间的随机闲谈"]]', '["C"]', '波斯纳提出“教师成长 = 经验 + 反思”。持续、系统地反思教学并据以改进，是教师立足岗位的自我教育和行动研究，是专业发展最直接的途径之一。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (74, 1, 74, 'single', 1.0, '春游中，一名学生在自由活动时违反事先反复强调的安全要求，与同学追逐打闹致自己摔伤。学校事前勘察了路线、进行了安全教育并安排足够教师跟班。依法学校（　）', '[["A","已尽到教育管理职责，不承担侵权责任"],["B","只要发生在校外活动中就须担责"],["C","应与受伤学生平均分担损失"],["D","应承担全部赔偿责任"]]', '["A"]', '依据《学生伤害事故处理办法》和《民法典》相关规定，学校责任以过错为前提。学校履行了安全教育、路线勘查和人员配备义务，损害由学生违反纪律的自险行为造成，学校没有过错，故不承担侵权责任。B项将校外活动一律归责，C项无法律依据要求平均分摊，D项全额赔偿更无事实与法律基础。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (75, 1, 75, 'single', 1.0, '学生计算能力正常，却常常不会做应用题，主要问题在于读不懂题意、抓不住数量关系。教师应优先培养其（　）', '[["A","阅读理解与关键信息提取能力"],["B","机械背诵公式的能力"],["C","几何作图能力"],["D","计算的速度和准确率"]]', '["A"]', '应用题解题的前提是理解文字情境、识别已知条件与问题、抽象出数量关系。困难出在题意理解环节，就应通过说题、画示意图、圈画关键词等方式提高阅读理解和信息提取能力。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (76, 1, 76, 'single', 1.0, '教师注意发现每名学生身上的闪光点，及时给予具体的肯定和鼓励，学生的自信心和完成任务的坚持性明显增强。这种做法主要是通过提升（　）发挥作用的。', '[["A","流体智力水平"],["B","学习兴趣的广度"],["C","认知风格的灵活性"],["D","自我效能感"]]', '["D"]', '自我效能感是个体对自己能否成功完成某一任务的信念，成败经验和他人的积极评价是其重要来源。具体、真诚的肯定能帮助学生积累成功体验，提高自我效能感。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (77, 1, 77, 'single', 1.0, '某校把师德师风考核结果作为教师年度考核、职称评聘和评优奖励的首要标准，实行师德失范“一票否决”。这一做法体现了（　）', '[["A","以科研论文数量主导考核"],["B","以学历层次决定教师待遇"],["C","把师德师风作为评价教师第一标准"],["D","以教学成绩为核心的评价导向"]]', '["C"]', '《深化新时代教育评价改革总体方案》和《关于加强和改进新时代师德师风建设的意见》均强调把师德师风作为教师评价的第一标准，落实师德失范“一票否决”。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (78, 1, 78, 'single', 1.0, '学英语时，小梅先掌握的汉语拼音发音，常使她把英语字母读成拼音；经过一段时间练习后，新学的英语拼读又偶尔干扰她认读拼音。前一种情形主要属于（　）', '[["A","消退抑制"],["B","前摄抑制"],["C","超限抑制"],["D","倒摄抑制"]]', '["B"]', '先学习的材料对识记和回忆后学习材料的干扰称前摄抑制；后学习的材料对保持先学习材料的干扰称倒摄抑制。汉语拼音先学并干扰英语认读，属于前摄抑制。题干后半句英语反过来干扰拼音才是倒摄抑制，应注意二者的时间顺序。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (79, 1, 79, 'single', 1.0, '一名家庭经济困难学生产生辍学念头，班主任多次家访劝学，协助其申请助学金和社会资助，最终帮助其安心完成学业。该做法主要体现了教师（　）', '[["A","控辍保学、保障适龄儿童接受义务教育的责任"],["B","管理学校财务的行政责任"],["C","开展教育科学研究的责任"],["D","提高班级升学率的教学责任"]]', '["A"]', '《中华人民共和国义务教育法》要求政府、学校、家庭共同做好控辍保学工作，发现学生辍学应及时劝返并帮助解决实际困难。班主任劝学并协助资助，是落实控辍保学责任的体现。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (80, 1, 80, 'single', 1.0, '某市推进教育数字化，支持学校建设智慧课堂，利用大数据开展学情诊断、推送分层学习资源。这一举措的主要价值在于（　）', '[["A","减少学校对教学管理的投入"],["B","用信息技术完全取代教师"],["C","赋能因材施教，提高教学质量"],["D","统一拉平所有学生的学习进度"]]', '["C"]', '《教育强国建设规划纲要（2024—2035年）》强调建设教育数字化体系。智慧课堂和学情数据分析有助于精准把握差异、提供个性化资源，赋能因材施教和质量提升，但技术是辅助手段，不能取代教师。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (81, 1, 81, 'multi', 1.6, '某小学深化课程改革，采取了下列措施：开设可供选择的兴趣选修课、推行项目式学习、实行多元过程性评价、鼓励教师合作开发校本课程。这些措施体现的新课程理念有（　）', '[["A","课程结构的选择性"],["B","项目式学习意味着完全取消教师讲授和系统知识学习"],["C","把学生考试成绩作为唯一衡量标准"],["D","评价主体与方式的多元化"],["E","校本课程只能由校外专家开发，教师只负责执行"]]', '["A","D"]', 'A正确：开设可供选择的兴趣选修课体现了课程结构的选择性，照顾学生差异。B错误：项目式学习倡导自主、合作、探究，但并不否定必要的教师讲授和系统知识学习，二者应有机结合。D正确：多元过程性评价体现评价主体和方式多元化。C错误：以分数为唯一标准是新课改要破除的甄别式评价。E错误：教师是课程的建设者和开发者，可以参与校本课程开发。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (82, 1, 82, 'multi', 1.6, '学习中，不同问题可以采用不同的学习策略：上课容易走神时需要加强注意的自我监控；记不住零散知识点时需要精加工和及时复习；不会写作文时需要增加观察体验并借鉴范文结构。下列对应正确的有（　）', '[["A","上课走神——运用元认知监控策略，及时调节注意"],["B","记不住知识点——适当运用复述、精加工和组织策略并及时复习"],["C","学习困难只能靠延长学习时间、增加重复遍数解决"],["D","不会写作文——丰富直接经验，运用读写结合的方法"],["E","只要学习策略足够好，就可以忽略学习动机和原有知识基础"]]', '["A","B","D"]', 'A正确：对注意和理解过程的自我觉察、及时调节属于元认知监控策略。B正确：针对零散知识，复述、精细加工、归类组织并依据遗忘规律及时复习是有效方法。D正确：写作困难常源于直接经验不足，应通过观察实践和范文借鉴加以解决。C错误：机械延长时间、简单重复忽视理解和策略运用，效率低下。E错误：策略运用受学习动机、原有知识基础等因素制约，不能脱离这些条件孤立发挥作用。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (83, 1, 83, 'multi', 1.6, '某班主任在班级管理中采取了下列做法：实行值日班长轮流制、定期召开班会讨论班级事务、建立班级公约和岗位责任制、对违纪学生只靠罚抄课文处理。其中符合现代班级管理理念的有（　）', '[["A","实行值日班长轮流制，让学生在参与中学会自治"],["B","定期召开班会讨论班级事务，发挥学生的主体作用"],["C","建立班级公约和岗位责任制，实现班级管理的制度化"],["D","对违纪学生一律罚抄课文，以加重学生负担来维持纪律"],["E","班级事务完全由班主任一人决定，学生只需服从执行"]]', '["A","B","C"]', 'A、B、C正确：轮流管理、班会民主议事、公约与岗位责任制体现了学生主体、民主参与和自主管理的现代班级管理理念。D错误：罚抄课文属于变相体罚和机械惩罚，既不符合教育惩戒要求，也不能从根本上引导学生自律。E错误：班主任独断专行会压抑学生的主动性和责任感，不符合班级民主管理方向。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (84, 1, 84, 'multi', 1.6, '某校六年级两名学生在课间追逐打闹，教师多次提醒后，一名学生仍将同学推倒致其骨折。关于学校责任的认定，下列说法正确的有（　）', '[["A","学校是否承担责任，以其是否尽到教育、管理职责为判断标准"],["B","学校已进行必要的安全教育和管理且无过错的，不承担侵权责任"],["C","有过错的学生监护人依法承担相应的侵权责任"],["D","伤害发生在校园内，学校无论有无过错都必须承担全部赔偿责任"],["E","学校应当及时救助受伤害学生，并告知其监护人"]]', '["A","B","C","E"]', '依据《民法典》第一千二百条和《学生伤害事故处理办法》，限制民事行为能力人在校受到人身损害，学校承担过错责任，以是否尽到教育、管理职责为判断标准（A、B正确）；加害学生一方有过错的，由其监护人依法承担相应责任（C正确）；学校还负有及时救助、告知监护人的法定义务（E正确）。D错误：校园内发生伤害并不导致学校当然全责，归责仍以过错为要件。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (85, 1, 85, 'multi', 1.6, '某市对学校课后服务工作提出要求：服务内容要多样化，要尊重学生和家长的自主选择，要为学习有困难的学生提供辅导，不得利用课后服务时间统一讲授新课。这些要求符合（　）', '[["A","满足学生多样化发展需求"],["B","尊重学生和家长的自愿选择"],["C","对学习困难学生进行必要的学业帮扶"],["D","借课后服务之名集体补课、增加学生负担"],["E","把课后服务办成统一的新课教学"]]', '["A","B","C"]', 'A正确：多样化内容有助于发展兴趣特长、促进全面发展。B正确：课后服务坚持学生自愿、家长自愿原则。C正确：对学习有困难的学生进行答疑辅导是课后服务的重要内容。D、E错误：依据“双减”政策，课后服务不得变成集体补课或讲授新课，不得加重学生课业负担。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (86, 1, 86, 'multi', 1.6, '一位语文教师经常运用情境教学。下列属于情境教学法基本特征的有（　）', '[["A","以生动具体的形象激发学生的情感体验"],["B","课堂中只允许学生体验，不进行任何理性概括和知识讲授"],["C","教师只作旁观，完全不加以引导和点拨"],["D","创设与教学内容相适应的真实或模拟情境"],["E","情境越离奇、越脱离学生生活，教学效果越好"]]', '["A","D"]', '情境教学（以李吉林情境教育为代表）以“形真、情切、意远、理寓其中”为特点：A正确，借助生动具体的形象唤起情感体验；D正确，强调围绕教学内容创设真实或模拟的情境。B错误：情境教学主张情知交融、在体验基础上引导概括，并不排斥理性认识和必要讲授。C错误：教师要适时引导、点拨、升华，而非放任旁观。E错误：情境应贴近学生已有生活经验和认知水平，脱离生活反而妨碍理解。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (87, 1, 87, 'multi', 1.6, '某校组织学生乘大巴参加校外实践活动，途中因其他车辆违章变道发生交通事故，造成学生受伤，学校大巴驾驶员和随车教师并无过错。关于责任承担，下列说法正确的有（　）', '[["A","学生有权依法获得赔偿"],["B","事故责任应由违章车辆一方依法承担"],["C","学校已尽到组织管理和安全保障义务的，不承担侵权责任"],["D","只要发生在校外活动中，学校就应承担全部责任"],["E","学校应及时救助受伤学生并告知其监护人"]]', '["A","B","C","E"]', '依据《民法典》侵权责任编和《学生伤害事故处理办法》，学生伤害事故责任以过错为原则。本案由第三方违章造成，应由责任方承担赔偿；学校无过错则不承担侵权责任，但仍负有及时救助、告知和报告义务，A、B、C、E正确。D错误：学校责任不依“校外”这一地点当然成立，而取决于是否尽到教育、管理职责。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (88, 1, 88, 'multi', 1.6, '某校校园文化节安排了经典诵读、民族歌舞表演、传统手工艺制作和民族文化展板等活动。这些活动的育人价值在于（　）', '[["A","增进学生对中华优秀传统文化的认同"],["B","促进民族团结教育和文化理解"],["C","在实践体验中提高学生的审美和动手能力"],["D","文化节只是娱乐活动，与育人目标无关"],["E","丰富校园文化生活，营造良好的隐性课程环境"]]', '["A","B","C","E"]', '传统文化展示有助于文化认同与文化自信（A）；民族歌舞、民族文化内容可渗透民族团结教育（B）；表演与手工艺制作能发展审美和实践能力（C）；丰富的校园文化本身构成隐性课程，发挥潜移默化的育人作用（E）。D错误：校园文化活动是学校教育和隐性课程的重要载体，具有明确的育人功能。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (89, 1, 89, 'multi', 1.6, '一位教师反思后发现自己“讲得太多、学生参与太少”，于是调整教学：增加课堂提问与讨论、设计小组合作任务、留出学生练习和展示时间。这种调整符合（　）', '[["A","启发性教学原则"],["B","教师主导与学生主体相统一的规律"],["C","以学生活动完全取代教师讲授"],["D","调动学生学习的主动性"],["E","促进学生从学会走向会学"]]', '["A","B","D","E"]', '增加提问讨论、合作探究体现启发性原则（A）和教师主导作用与学生主体作用相统一的教学规律（B）；学生在提问、讨论和展示中由被动接受转为主动参与，有利于调动学习主动性（D）；教师由“教会知识”转向引导学生掌握方法，促进学生从“学会”走向“会学”（E）。C错误：强调学生主体并不否定教师必要的讲授与引导，讲授法在系统传授知识方面仍有不可替代的价值。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (90, 1, 90, 'multi', 1.6, '某市要求学校改革学生评价：不以分数作为评价学生的唯一依据、关注学生成长过程、重视学生的自我反思与同伴互评。这体现的评价理念有（　）', '[["A","评价内容的综合化，关注德智体美劳全面发展"],["B","评价方式的过程化与多元化"],["C","评价主体的多元化，强调学生参与"],["D","以甄别和选拔为唯一目的的评价观"],["E","发挥评价促进学生发展的教育功能"]]', '["A","B","C","E"]', '不以分数为唯一依据体现评价内容综合化（A）；关注成长过程、采用多元方式体现过程性、多元化评价（B）；自我反思与同伴互评体现评价主体多元（C）；改革的落脚点是促进发展（E）。D错误：甄别选拔是传统评价的突出功能，发展性评价强调激励、诊断与改进，反对“为了选拔而评价”。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (91, 10, 1, 'judge', 0.6, '美术课上，陈老师教学生画水墨画时，先示范基本笔法让学生临摹，再让学生自由创作。有教师认为，这种从模仿到创作的过程说明操作技能只能靠机械模仿形成，动觉控制和反复练习对技能形成没有实际意义。', '[["A","正确"],["B","错误"]]', '["B"]', '操作技能的形成一般经历操作定向、操作模仿、操作整合和操作熟练四个阶段，模仿只是其中一个环节。随着练习推进，动作控制逐步由视觉控制为主转向动觉控制为主，动作趋于协调、自动化，才能最终形成熟练技能。把技能形成简单等同于机械模仿、否认动觉控制和练习的作用，是对操作技能形成规律的误解。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (92, 10, 2, 'judge', 0.6, '某校在推进素质教育时提出，素质教育就是多开音乐、美术等活动课、让学生轻松一点，学科知识教学可以相应放松。这一认识准确把握了素质教育的内涵。', '[["A","正确"],["B","错误"]]', '["B"]', '素质教育是以全面提高全体学生的基本素质为根本目的，以尊重学生主体性和主动精神、注重开发人的智慧潜能、形成人的健全个性为根本特征的教育。它贯穿于德智体美劳各育和全部教育教学活动，并非简单等同于增加艺体活动课、放松学科教学。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (93, 10, 3, 'judge', 0.6, '某中学结合学校武术特色和学生兴趣，将国家课程《体育与健康》中部分课时进行校本化重组，开发了“武术健体”校本化实施模块。有教师据此认为，学校对国家课程进行校本化实施，就等于开发了校本课程。', '[["A","正确"],["B","错误"]]', '["B"]', '国家课程的校本化实施，是学校在保证国家课程基本要求的前提下，对国家课程进行适应性再加工，其性质、目标和主体内容不变；校本课程则是学校自主开发、自主实施的课程。二者在开发主体、课程性质和管理权限上均不同。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (94, 10, 4, 'judge', 0.6, '生物课上王老师先让学生观察不同类型的叶子然后引导学生归纳出叶子的共同特征最后引入光合作用的概念。这种从具体到一般的思维方式属于归纳推理。', '[["A","正确"],["B","错误"]]', '["A"]', '从观察不同类型叶子（具体事例）到归纳共同特征（一般规律），是从具体到一般的归纳推理过程。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (95, 10, 5, 'judge', 0.6, '某市教育局要求辖区内所有学校建立学生成长记录袋记录学生在校期间学业进步品德发展特长展示等方面的资料。这一做法体现了过程性评价的理念。', '[["A","正确"],["B","错误"]]', '["A"]', '成长记录袋记录学生发展过程而非只看最终结果，体现了过程性评价的理念。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (96, 10, 6, 'judge', 0.6, '初三学生小红在学习英语时采用了一种方法：她会把新学的单词和已经知道的近义词反义词放在一起进行对比记忆。小红运用的学习策略属于组织策略。', '[["A","正确"],["B","错误"]]', '["B"]', '将单词和近义词反义词对比记忆更接近精细加工策略中的比较法而非组织策略。组织策略侧重建构知识的层级结构。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (97, 10, 7, 'judge', 0.6, '遗传素质是人的身心发展的生理前提，因此遗传素质能够决定人的发展，教育和环境的影响无足轻重。', '[["A","正确"],["B","错误"]]', '["B"]', '遗传素质是人的身心发展的生理前提，为人的发展提供可能性，但不能决定人的发展。个体发展的水平、方向和成就主要是在后天环境（含教育）影响下，通过个体实践活动实现的，学校教育起主导作用。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (98, 10, 8, 'judge', 0.6, '环境对人的影响是自发、零散的，但人并不是被动接受环境的影响，个体在接受环境影响时具有主观能动性。', '[["A","正确"],["B","错误"]]', '["A"]', '环境对人的影响具有自发性、零散性，但人对环境的反映是能动的反映。个体在接受环境影响的同时发挥主观能动性，在改造客观世界的过程中发展自身。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (99, 10, 9, 'judge', 0.6, '某县教育局在一次学校评估中发现某学校存在使用危房教学的情况。该局立即责令该校停止使用危房并限期整改。该局的做法有法律依据。', '[["A","正确"],["B","错误"]]', '["A"]', '教育法和相关安全法规要求学校校舍必须符合安全标准。使用危房教学存在安全隐患，教育行政部门有权责令整改。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (100, 10, 10, 'judge', 0.6, '确立教育目的既要依据社会发展的需要，也要考虑受教育者个人的兴趣、爱好和发展需要，是社会需要与个人需要的统一。', '[["A","正确"],["B","错误"]]', '["A"]', '确立教育目的的依据包括社会的政治、经济、文化发展需要，也包括受教育者身心发展规律及其兴趣、爱好和个性发展需要。个人本位与社会本位割裂任何一方都是片面的，教育目的是二者的辩证统一。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (101, 10, 11, 'judge', 0.6, '某小学一名学生在科学课上提出了一个与教材不同的观点。科学老师认真倾听了学生的观点并与全班同学一起讨论验证最终发现学生的观点有一定的道理。这位老师的做法体现了新课程倡导的民主平等的师生关系。', '[["A","正确"],["B","错误"]]', '["A"]', '认真倾听学生观点并一起讨论验证体现了教师尊重学生与学生平等对话的民主师生关系。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (102, 10, 12, 'judge', 0.6, '初一学生小杰在学完负数的概念后发现自己对数的认识从只有正数和零扩展到了包括负数在内的更广范围。从认知发展的角度看小杰的认知结构发生了同化。', '[["A","正确"],["B","错误"]]', '["B"]', '同化是把新知识纳入已有认知结构而不改变原有结构。小杰对数的认识从正数和零扩展到包括负数，这是改变了原有认知结构的范围，属于顺应而非同化。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (103, 10, 13, 'judge', 0.6, '教学过程不是教师把知识直接移植给学生的过程，学生不是被动接受知识的容器，而是在教师引导下主动建构知识的主体。', '[["A","正确"],["B","错误"]]', '["A"]', '教学过程是教师主导与学生主体相统一的过程。学生是学习的主人，知识只有经过学生自身的主动加工才能被理解和掌握，把学生视为被动接受知识的容器属于注入式教学观。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (104, 10, 14, 'judge', 0.6, '教学认识走的是一条认识的捷径，因此学生获得知识可以完全省略感性经验这一环节。', '[["A","正确"],["B","错误"]]', '["B"]', '教学过程具有简捷性，学生学习经过选择和提炼的间接经验，走的是认识捷径。但认识的一般规律仍起作用，学生掌握间接经验要以一定的直接经验（感性认识）为基础，否则容易死记硬背、理解不深。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (105, 10, 15, 'judge', 0.6, '高中生小芳在选择大学专业时既想选自己喜欢的文学专业又担心就业前景。这种心理冲突属于双趋冲突。', '[["A","正确"],["B","错误"]]', '["B"]', '双趋冲突是两个都想要的目标只能选其一。小芳既想选文学专业又担心就业，这是同一个目标（文学专业）既有吸引力又有排斥力的冲突，属于趋避冲突而非双趋冲突。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (106, 10, 16, 'judge', 0.6, '个体身心发展具有个别差异性，这要求教育者针对学生的不同特点因材施教，而不是对同一年龄段的所有学生实行统一进度、统一要求、统一评价。', '[["A","正确"],["B","错误"]]', '["A"]', '个别差异性是指不同个体在发展速度、优势领域、个性特点等方面存在差异，它要求教育坚持因材施教，针对学生差异分层要求、分类指导。“一刀切”“齐步走”恰恰违背了个别差异性规律。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (107, 10, 17, 'judge', 0.6, '某中学一名教师利用课余时间编写了一本教辅材料并以个人名义出版发行获得了稿酬。该教师的行为违反了教师法关于教师不得从事有偿补课的规定。', '[["A","正确"],["B","错误"]]', '["B"]', '编写教辅材料出版发行获得稿酬属于合法的知识产权收益，与有偿补课不同。有偿补课是指教师对学生进行收费补习教学。编写出版教辅是合法的创造性劳动。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (108, 10, 18, 'judge', 0.6, '在教学中只要把知识系统地讲清楚、讲准确，学生的思想品德自然就会形成，不需要专门的德育。', '[["A","正确"],["B","错误"]]', '["B"]', '掌握知识是提高思想品德认识的基础，但思想品德的形成还需要情感陶冶、意志锻炼、信念确立和行为习惯养成。传授知识并不必然带来思想品德的提高，教学的教育性规律要求教师自觉挖掘教材思想性、言传身教。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (109, 10, 19, 'judge', 0.6, '广义的学习只发生在学校课堂上，专指学生有计划、有组织地掌握科学文化知识的活动。', '[["A","正确"],["B","错误"]]', '["B"]', '广义的学习是指人和动物在生活过程中，凭借经验而产生的行为或行为潜能的相对持久的变化。它贯穿日常生活、工作、交往等各种情境。狭义的学习才专指学生在教师指导下有目的、有计划、有组织地掌握知识技能的过程。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (110, 10, 20, 'judge', 0.6, '负强化就是呈现一个厌恶刺激来降低行为发生的概率，它与惩罚在含义上完全相同。', '[["A","正确"],["B","错误"]]', '["B"]', '负强化是通过撤销厌恶刺激来提高行为在将来发生的概率，属于强化的一种；惩罚则是通过呈现厌恶刺激或撤销愉快刺激来降低行为发生概率。二者目的相反：负强化是增加行为，惩罚是减少行为。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (111, 10, 21, 'judge', 0.6, '某中学在期中教学检查中要求每位教师提交教学反思日志。一位老教师说我都教了二十年了还写什么反思。这位老教师的说法符合终身学习的职业道德要求。', '[["A","正确"],["B","错误"]]', '["B"]', '终身学习要求教师不管教龄多长都要不断反思和学习。教了二十年的老教师更需要反思以不断更新教育理念和教学方法。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (112, 10, 22, 'judge', 0.6, '某小学四年级的语文老师在教学古诗词时让学生先了解诗人的生平背景再读诗最后体会诗人的情感。这种从作者到作品再到情感的教学顺序体现了由浅入深的教学逻辑。', '[["A","正确"],["B","错误"]]', '["A"]', '从了解背景（知识层面）到读诗（理解层面）到体会情感（感悟层面）是由浅入深的教学逻辑，符合循序渐进原则。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (113, 10, 23, 'judge', 0.6, '某小学教师当着全班学生的面，让未交作业的小林站到讲台旁，用教鞭抽打其手心三下以示惩戒。该教师的行为属于正常教育惩戒，不构成体罚。', '[["A","正确"],["B","错误"]]', '["B"]', '正常教育惩戒以制止违纪、批评教育为限度，不得实施击打、刺扎等造成身体痛苦的行为。用教鞭抽打学生手心属于直接造成身体痛苦的体罚行为，已超出合法教育惩戒的边界。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (114, 10, 24, 'judge', 0.6, '某小学一名学生在参加学校组织的运动会时扭伤了脚踝。学校及时送医并通知了家长。学校的做法符合学生伤害事故处理的有关要求。', '[["A","正确"],["B","错误"]]', '["A"]', '学生在校期间受伤学校及时送医并通知家长，符合学生伤害事故处理办法的要求。学校采取了及时有效的救助措施。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (115, 10, 25, 'judge', 0.6, '转化后进生不能只靠学习上加班加点、反复补课，而应在摸清成因的基础上，从学习习惯、心理品质、思想品德等方面综合施策，促进其全面发展。', '[["A","正确"],["B","错误"]]', '["A"]', '后进生的形成往往是学习、心理、行为、家庭等多方面因素长期作用的结果，转化工作应坚持全面发展观点，长善救失、综合治理。只抓成绩、反复补课是片面的。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (116, 10, 26, 'judge', 0.6, '初中地理课上老师让学生用地球仪观察不同国家的地理位置和地形特征。老师运用的直观手段属于实物直观。', '[["A","正确"],["B","错误"]]', '["B"]', '地球仪是地球的模型不是实物本身，属于模象直观而非实物直观。实物直观是直接观察实物本身如实地考察。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (117, 10, 27, 'judge', 0.6, '小学三年级学生小明在做数学题时发现如果用凑十法计算8加7先把7分成2和5然后8加2等于10再加5等于15比直接算快多了。小明自己发现了一种简便算法这种学习属于发现学习。', '[["A","正确"],["B","错误"]]', '["A"]', '小明通过自己的思考发现了简便算法而不是由老师直接告知，属于发现学习。发现学习强调学生通过自己的探索和发现来获得知识。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (118, 10, 28, 'judge', 0.6, '某中学一名教师在教学过程中经常引用最新的教育政策文件来佐证自己的观点帮助学生了解教育改革的方向。这种做法有利于培养学生关注教育时事的能力。', '[["A","正确"],["B","错误"]]', '["A"]', '引用最新政策文件让学生了解教育改革方向有助于培养学生关注教育时事的习惯和能力。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (119, 10, 29, 'judge', 0.6, '某小学一名学生因为家庭搬迁转到了新学校。新班主任主动安排了同学帮助他熟悉环境并在学习上进行帮助。班主任的做法体现了班集体的教育功能。', '[["A","正确"],["B","错误"]]', '["A"]', '安排同学帮助转学生熟悉环境利用班集体的力量促进新成员融入，体现了班集体的教育功能和集体教育原则。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (120, 10, 30, 'judge', 0.6, '某市教育局在全市中小学推行教师轮岗制度让城区优秀教师定期到农村学校支教。这一制度有利于促进义务教育均衡发展。', '[["A","正确"],["B","错误"]]', '["A"]', '教师轮岗让优质师资向农村流动有利于缩小城乡教育差距，促进义务教育均衡发展。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (121, 10, 31, 'single', 1.0, '某小学在教学生认识面积时先让学生用手掌测量课桌大小再用方格纸测量最后引入面积的概念和公式。这种从具体操作到抽象概念的教学体现了（　）', '[["A","学生的学习以间接经验为主，不需要任何直接经验"],["B","教学应遵循直观性原则，从学生的感性经验出发逐步引导其形成理性认识"],["C","教学应以学生自学为主，教师只需提供学习材料"],["D","面积概念应由教师直接讲授，无需学生动手操作"]]', '["B"]', '从手掌测量（具体操作）到方格纸测量（半抽象）再到面积公式（抽象概念），体现了教学应遵循直观性原则，从学生的直接感知和感性经验出发，逐步引导其形成抽象的理性认识。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (122, 10, 32, 'single', 1.0, '在我国教育法律体系中，被称为教育领域“母法”、规定教育根本制度并为其他教育法律法规提供立法依据的是（　）', '[["A","《中华人民共和国义务教育法》"],["B","《中华人民共和国教育法》"],["C","《中华人民共和国高等教育法》"],["D","《中华人民共和国职业教育法》"]]', '["B"]', '《中华人民共和国教育法》是我国教育工作的根本大法，对教育基本制度、学校、教师、受教育者、教育投入等作出总体规定，是制定其他教育法律、法规的依据，被称为教育领域的“母法”。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (123, 10, 33, 'single', 1.0, '初二学生小芳在学习中总是喜欢一个人安静地思考问题不太愿意参加小组讨论。从认知风格来看小芳最可能属于（　）', '[["A","场依存型"],["B","场独立型"],["C","冲动型"],["D","沉思型"]]', '["B"]', '场独立型认知风格的人倾向于依据内在参照加工信息，善于独立思考和独立判断，不容易受外部环境干扰，喜欢独处思考。小芳喜欢独自安静思考、不愿参加小组讨论，符合场独立型的特征。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (124, 10, 34, 'single', 1.0, '某小学老师在教学乘法分配律时先让学生计算(3+5)×4和3×4+5×4然后让学生比较两个结果是否相同。老师运用的教学方法是（　）', '[["A","讲授法"],["B","演示法"],["C","练习法"],["D","引导发现法"]]', '["D"]', '教师先让学生分别计算，再引导学生比较两个结果、自己发现规律，是教师创设问题情境、引导学生独立发现知识的方法，属于引导发现法。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (125, 10, 35, 'single', 1.0, '某中学要求每位学生每学期至少完成20小时的志愿服务并记录在成长档案中。这一要求体现了（　）', '[["A","长善救失原则"],["B","因材施教原则"],["C","实践育人"],["D","循序渐进原则"]]', '["C"]', '学校要求学生完成志愿服务并记录在成长档案中，是将知识学习与社会服务实践相结合，体现了实践育人的教育理念。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (126, 10, 36, 'single', 1.0, '初三学生小明在中考复习中制定了详细的学习计划，但执行两天后发现任务排得太满、根本完不成，于是他没有调整计划，仍照旧硬撑，结果越落越多、信心受挫。从学习策略看，小明最缺乏的是（　）', '[["A","复述策略：对重点知识反复诵读直到记牢"],["B","精加工策略：用口诀、联想为新知识赋予意义"],["C","元认知调节策略：根据执行反馈及时调整计划与节奏"],["D","资源管理策略：与同学约定固定时间结伴自习"]]', '["C"]', '元认知策略包括计划、监控和调节。小明发现计划脱离实际后，不能依据反馈重新评估并调整复习节奏，属于元认知调节策略的缺失。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (127, 10, 37, 'single', 1.0, '工作三年的初中英语教师林某申请利用暑假到高校参加为期四周的外语教学法研修班，学校以“教学任务重、人手紧”为由不予批准，并表示不参加也不影响续聘。依据《中华人民共和国教师法》关于教师权利的规定，下列说法正确的是（　）', '[["A","教师参加进修或其他方式的培训是一项法定权利，学校应为其行使提供便利，该做法与法律要求不符"],["B","教师是否参加业务培训完全由学校单方决定，教师没有决定权"],["C","教师只有在教学成绩排名靠后时才需要进修培训"],["D","参加校外培训属于教师个人消费行为，与法定权利无关"]]', '["A"]', '《中华人民共和国教师法》第七条规定，教师享有“参加进修或者其他方式的培训”的权利。学校应在合理安排工作的基础上为教师业务进修提供便利，简单以人手紧张为由一概不予批准，与保障教师法定权利的要求不符。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (128, 10, 38, 'single', 1.0, '某中学一名学生在物理实验中发现了一个与教材描述不同的实验现象并如实报告。老师的恰当做法是（　）', '[["A","批评该学生不尊重教材权威，要求其在实验报告中修正结论"],["B","肯定学生如实报告的科学态度，引导全班分析差异产生的原因"],["C","忽略这一现象，按照教材内容继续完成实验"],["D","该学生课后自行查找原因，不占用课堂时间"]]', '["B"]', '学生在实验中发现与教材不同的现象并如实报告，体现了求真的科学精神。教师应当肯定学生实事求是的态度，保护其好奇心和探究欲，同时引导全班分析差异产生的原因。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (129, 10, 39, 'single', 1.0, '初一学生小宇做几何证明题时，能脱离具体图形，用假设和符号推理讨论“若平行、则角相等”一类命题，并能思考自己推理中可能出现的漏洞。依据皮亚杰的认知发展阶段理论，小宇最可能处于（　）', '[["A","形式运算阶段"],["B","具体运算阶段"],["C","前运算阶段"],["D","感知运动阶段"]]', '["A"]', '形式运算阶段（约11岁以后）的个体能进行假设一演绎推理、抽象逻辑推理和命题思维，并能对自己的思维进行反思。小宇脱离具体图形、用假设和符号进行证明推理，正是形式运算阶段的典型特征。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (130, 10, 40, 'single', 1.0, '某小学开展了我是小小讲解员活动让学生为学校来访的客人讲解校园文化和历史。这种活动（　）', '[["A","有利于培养学生的语言表达能力和社会交往能力"],["B","增加了学生的课业负担，不利于减轻学习压力"],["C","违反了学校安全管理规定，不应组织学生接触外来人员"],["D","只是少数优秀学生的展示机会，不具有教育公平性"]]', '["A"]', '小小讲解员活动让学生在真实社交情境中组织语言、表达观点、与客人互动，有利于培养学生的语言表达能力、社会交往能力和自信心，是综合实践活动的重要形式。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (131, 10, 41, 'single', 1.0, '初一学生小亮在学完有理数的运算后能够将有理数的运算规则应用到实际问题中去解决。从加涅的学习结果分类来看这属于（　）', '[["A","言语信息学习"],["B","智慧技能学习"],["C","认知策略学习"],["D","态度学习"]]', '["B"]', '加涅将学习结果分为五类：言语信息、智慧技能、认知策略、动作技能和态度。有理数的运算规则属于概念和规则，将这些规则应用到实际问题中解决，属于智慧技能学习。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (132, 10, 42, 'single', 1.0, '某中学在教学管理中要求教师对每次考试的成绩进行分析找出薄弱环节并制定改进措施。这一要求体现了教学评价的（　）', '[["A","导向功能：以评价标准引导教师改进教学方向"],["B","鉴定功能：对教师教学水平做出等级评定"],["C","诊断功能：通过分析发现教学中的薄弱环节并制定改进措施"],["D","管理功能：作为教师绩效考核的唯一依据"]]', '["C"]', '教师对考试成绩进行分析、找出薄弱环节并制定改进措施，体现了教学评价的诊断功能。诊断功能是指通过评价发现教学中存在的问题和不足，为改进教学提供依据。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (133, 10, 43, 'single', 1.0, '解数学应用题时，有的学生习惯先通读全题、对照题目给出的条件一步步列式，容易受题目中多余条件干扰；有的学生则能迅速跳出无关叙述，直接抓住数量关系，但小组讨论时常常忽视同伴提供的解题线索。这种认知方式差异属于（　）', '[["A","辐合型与发散型"],["B","冲动型与沉思型"],["C","场独立型与场依存型"],["D","表层加工与深层加工"]]', '["C"]', '威特金依据人对外部环境线索的依赖程度，把认知方式分为场独立型与场依存型：场依存者以外在参照加工信息，易受题中多余条件等背景干扰；场独立者以自身内在参照加工，能排除无关因素抓住结构。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (134, 10, 44, 'single', 1.0, '某市教育局在推进集团化办学过程中将优质学校与薄弱学校结成教育集团共享管理和教学资源。这一举措的主要目的是（　）', '[["A","提高薄弱学校的升学率"],["B","减少优质学校的招生名额"],["C","统一所有学校的办学风格和课程设置"],["D","促进义务教育优质均衡发展，扩大优质教育资源覆盖面"]]', '["D"]', '集团化办学将优质学校与薄弱学校结成教育集团，共享管理和教学资源，其核心目的是促进义务教育优质均衡发展，通过优质教育资源的辐射和共享，缩小校际差距。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (135, 10, 45, 'single', 1.0, '教学生字“休”时，安老师告诉学生：“一个人靠在树旁，就是在休息。”学生很快记住了字形和字义。这种学习与（　）的学习理论观点最为吻合。', '[["A","托尔曼的符号学习理论"],["B","巴甫洛夫的经典性条件作用理论"],["C","桑代克的试误说"],["D","苛勒的完形—顿悟说"]]', '["D"]', '教师用“一个人靠在树旁就是休息”的方式讲解“休”字，引导学生突然领会字形与字义之间的整体关系，是对情境关系的突然理解，符合苛勒的完形—顿悟说。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (136, 10, 46, 'single', 1.0, '某小学三年级学生在做数学题时总是忘记进位。老师发现后针对性地设计了专门的进位练习。老师的做法体现了（　）', '[["A","组织和培养班集体"],["B","评定学生操行"],["C","协调校内外教育力量"],["D","针对学生的个别差异因材施教"]]', '["D"]', '班主任发现学生在数学计算中总是忘记进位这一具体问题，针对性地设计专门练习，体现了班主任在日常教学中关注学生的个别差异，因材施教地帮助学生克服学习困难。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (137, 10, 47, 'single', 1.0, '某中学开展校园读书月活动，要求学生每天安排20分钟自由阅读，并在阅读计划本上记录每日阅读时长、每周对照月初制定的阅读目标检查完成情况，适时调整下周安排。学生在这一活动中主要运用的学习策略是（　）', '[["A","复述策略，通过反复诵读加深对文本的机械记忆"],["B","元认知策略中的计划与监控策略，确立目标、自我检查并调节学习安排"],["C","精加工策略，通过联想和做笔记把新旧知识建立深层联系"],["D","组织策略，把阅读材料按主题归类形成知识结构网络图"]]', '["B"]', '学生月初制定阅读目标，每日记录阅读时长，每周对照目标检查完成情况并调整下周安排，体现了元认知策略中的计划策略和监控策略以及调节策略。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (138, 10, 48, 'single', 1.0, '小林熟练掌握骑自行车后，学骑电动车几乎没有困难；但他习惯用拼音输入法，刚学五笔输入法时，手指总不自觉地去敲拼音对应的键。关于迁移，下列判断正确的是（　）', '[["A","骑自行车对骑电动车是正迁移，拼音输入对五笔输入是负迁移"],["B","骑自行车对骑电动车是负迁移，拼音输入对五笔输入是正迁移"],["C","两者都是正迁移"],["D","两者都是逆向迁移"]]', '["A"]', '一种学习对另一种学习起促进作用为正迁移，起干扰、阻碍作用为负迁移。骑车经验有助于掌握电动车的平衡与车把操作，属正迁移；拼音按键习惯干扰五笔字形输入，属负迁移。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (139, 10, 49, 'single', 1.0, '某小学老师在教学分数乘法时先让学生回忆整数乘法的含义再引入分数乘法。这种从已知到未知的教学体现了（　）', '[["A","量力性原则（最近发展区）"],["B","因材施教原则"],["C","启发性原则"],["D","巩固性原则"]]', '["D"]', '先让学生回忆整数乘法的含义（已知），再引入分数乘法（未知），是在学生已有知识基础上建构新知识，体现了巩固性原则：温故而知新。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (140, 10, 50, 'single', 1.0, '某中学一名学生在考试中取得了好成绩老师公开表扬后全班的学习热情都提高了。从班杜拉的理论来看这体现了（　）', '[["A","直接强化"],["B","自我强化"],["C","负强化"],["D","替代强化"]]', '["D"]', '班杜拉的社会学习理论提出，观察者看到榜样受到强化后，自身相应行为的发生概率也会提高，这称为替代强化。老师公开表扬取得好成绩的学生，全班学习热情提高，正是替代强化的典型表现。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (141, 10, 51, 'single', 1.0, '体育课上，学生练习立定跳远的初期，动作僵硬、全身肌肉紧张，多余动作多，常需老师逐拍提示；经过两周分解与完整练习，多数学生动作趋于协调，能根据起跳线自动调整步点。这一变化主要反映了操作技能形成中（　）', '[["A","由操作模仿向操作熟练发展"],["B","由操作熟练向操作定向倒退"],["C","由心智技能向操作技能转化"],["D","由操作整合直接跃过模仿阶段"]]', '["A"]', '操作技能形成经历操作定向、操作模仿、操作整合、操作熟练四个阶段。练习初期靠教师逐拍提示、动作紧张多余，属操作模仿阶段；反复练习后动作协调、能根据情境自动调节，逐步进入操作整合并向操作熟练发展。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (142, 10, 52, 'single', 1.0, '某小学四年级的班主任在处理两名学生矛盾时让双方各自说出自己的感受和想法然后引导他们找到双方都能接受的解决方案。班主任的做法运用了（　）', '[["A","由课程的忠实执行者转变为课程的唯一决定者"],["B","由学生发展的引路人转变为教学结果的旁观者"],["C","由教学活动的组织者转变为课堂纪律的监督者"],["D","由知识的传授者转变为学生学习的促进者和引导者"]]', '["D"]', '班主任让矛盾双方各自说出感受和想法，再引导他们自主找到双方都能接受的解决方案，体现了新课程改革下教师由知识的传授者转变为学生学习的促进者和引导者的角色要求。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (143, 10, 53, 'single', 1.0, '小周背历史知识点时发现：通读一遍很快就忘，而采用“先理解线索、合上书尝试回忆、想不起来再翻书”的方式，记得又快又牢。这种学习策略主要是（　）', '[["A","复述与元认知监控相结合的策略"],["B","只要反复出声朗读的策略"],["C","把知识整理成层级网络的组织策略"],["D","谐音联想法"]]', '["A"]', '尝试回忆（主动提取）与重读相结合的方法称复习中的自我检查，提取尝试本身是一种精细复述，同时学生根据“想不想得起来”监控掌握程度、决定重读内容，兼有元认知监控的作用。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (144, 10, 54, 'single', 1.0, '某教师因学生作业多次未完成，责令该生在教室后墙站立听课一整天，并在其脸上贴写有“懒”字的纸条。依据《中华人民共和国义务教育法》和《未成年人保护法》，该行为主要侵犯了学生的（　）', '[["A","受教育权"],["B","人格尊严权"],["C","财产权"],["D","通信自由权"]]', '["B"]', '教师应当尊重学生人格，不得对学生实施体罚、变相体罚或者其他侮辱人格尊严的行为。罚站一整天属于变相体罚，贴侮辱性纸条直接贬低学生人格，主要侵犯的是人格尊严权。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (145, 10, 55, 'single', 1.0, '某初中一名学生因为家庭困难产生了辍学的念头。班主任了解情况后主动帮助其申请了助学金并与家长沟通说服其支持孩子继续上学。班主任的做法体现了（　）', '[["A","爱岗敬业"],["B","为人师表"],["C","关爱学生"],["D","终身学习"]]', '["C"]', '班主任主动了解学生辍学原因，帮助申请助学金并与家长沟通说服其支持孩子上学，体现了关爱学生的职业道德；关心爱护全体学生，不让学生因家庭困难而失学。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (146, 10, 56, 'single', 1.0, '做“用六根火柴拼出四个等边三角形”的题目时，很多学生只在桌面上摆，怎么也拼不出；当同伴把火柴立起来在空间中搭成正四面体时，大家才恍然大悟。此前阻碍学生解题的主要因素是（　）', '[["A","功能固着"],["B","问题情境的空间表征限制（定势）"],["C","知识经验不足"],["D","动机过弱"]]', '["B"]', '学生默认火柴只能在平面桌面上摆放，是受既有经验和问题表征方式束缚形成的定势，限制了向三维空间寻找解法。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (147, 10, 57, 'single', 1.0, '某市教育局发文要求中小学不得在节假日和寒暑假组织集体补课。这一规定（　）', '[["A","侵犯了教师的休息权，教师有权在假期自主安排"],["B","有利于保障学生和教师的休息权，促进身心健康"],["C","违反了学校办学自主权，教育局无权干预学校教学安排"],["D","会导致教学质量下降，不利于学生升学"]]', '["B"]', '禁止节假日和寒暑假集体补课，有利于保障学生和教师法定的休息权，让学生有时间休息调整、发展兴趣爱好，让教师有时间休整和备课，促进师生身心健康。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (148, 10, 58, 'single', 1.0, '某小学老师在教学时采用了合作学习的方式。下列哪项不是合作学习成功的关键要素？（　）', '[["A","积极的相互依赖：小组成员目标一致、荣辱与共"],["B","个体责任：每个成员都承担明确的学习任务"],["C","由组长一人完成所有任务以确保效率"],["D","面对面的促进性互动：成员间相互鼓励、互相帮助"]]', '["C"]', '合作学习成功的关键要素包括：积极的相互依赖、个体责任、面对面的促进性互动、社交技能和小组自评。由组长一人完成所有任务恰恰违背了合作学习的核心理念。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (149, 10, 59, 'single', 1.0, '课间，几个学生围着一块橡皮争论：晓晨说橡皮"软软的、能擦掉铅笔印"，子涵说它"是长方形、淡黄色"，还有学生补充"用力掰会断、搓一搓会掉渣"。综合他们的描述，学生主要是通过（　）来认识这块橡皮的。', '[["A","多种感官参与，形成对事物属性的完整知觉"],["B","仅靠书本上关于橡皮的定义间接认识"],["C","反复背诵\\"橡皮\\"二字的写法来认识"],["D","等待教师直接给出橡皮的全部特征"]]', '["A"]', '学生通过触觉（软）、视觉（长方形、淡黄）、操作（断、搓掉渣）等多种感官活动，从颜色、形状、质地、功能等多方面反映橡皮的整体属性，属于运用多种感官形成知觉的过程。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (150, 10, 60, 'single', 1.0, '某小学体育课上，教师组织学生进行篮球比赛，学生小强在正常抢球过程中与同学相撞受伤。教师课前已讲解动作规范并全程在场组织管理，事故发生后及时救助并通知家长。依据《学生伤害事故处理办法》，对这一意外，学校（　）', '[["A","承担全部赔偿责任，因为伤害发生在校内"],["B","不承担法律责任，这属于学校已履行相应职责情形下的意外"],["C","由体育教师个人承担刑事责任"],["D","由与其相撞的同学承担全部责任"]]', '["B"]', '《学生伤害事故处理办法》第十二条规定，在对抗性或者具有风险性的体育竞赛活动中发生意外伤害，学校已履行了相应教育、管理职责，行为并无不当的，不承担法律责任。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (151, 10, 61, 'single', 1.0, '某中学晚自习后，学生小周在学校侧门附近被一名与学校无关的社会人员赵某无故殴打致伤。经查，该校侧门保安脱岗、监控损坏已久，外人可随意进出。对小周的人身损害，下列说法正确的是（　）', '[["A","应由赵某独自承担全部责任，学校在任何情况下都不承担责任"],["B","应由学校承担全部赔偿责任，赵某不承担责任"],["C","小周系放学后在校门外受伤，只能由其监护人自行承担损失"],["D","由打人者赵某承担侵权责任，学校因未尽管理职责承担相应的补充责任"]]', '["D"]', '依据《民法典》第1201条及《学生伤害事故处理办法》，校外人员赵某无故殴打学生，应由打人者赵某承担侵权责任；学校侧门保安擅离职守、未尽管理职责，对损害发生存在过错，应承担相应的补充责任。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (152, 10, 62, 'single', 1.0, '某小学教师孙某在家长微信群中发布了多名学生的考试成绩及排名。家长向学校反映后，学校要求孙某撤回相关信息。学校的做法（　）', '[["A","错误，家长有权在群内了解全体学生的成绩以便横向比较"],["B","错误，教师发布学生成绩属于正常教学管理，学校无权干涉"],["C","正确，但学校应先将成绩排名在校园公告栏公示再撤回"],["D","正确，公开成绩排名涉及学生隐私与个人信息，应予保护"]]', '["D"]', '学生的考试成绩及排名属于不愿为他人知晓的私密信息和个人信息，受法律保护。教师在家长群公开发布多名学生成绩及排名，可能伤害成绩落后学生的自尊，也侵犯学生隐私权和个人信息权益。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (153, 10, 63, 'single', 1.0, '某中学一名教师在教学反思中写道：今天我讲的内容学生好像没听懂下次我要换一种方式。这位教师的反思属于（　）', '[["A","脱产攻读与教学实践相互替代"],["B","完全依赖专家讲座的单向灌输"],["C","实践—反思—再实践，在真实教学情境中持续改进"],["D","以学历提升作为专业发展的唯一途径"]]', '["C"]', '教师专业发展具有实践导向和反思性特征，强调在真实教学情境中通过“实践—反思—再实践”不断积累实践性知识，校本研修、同伴互助、行动研究是重要途径。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (154, 10, 64, 'single', 1.0, '早读课上，小林为记住一篇要求背诵的课文，采用反复朗读、逐段尝试背诵并及时对照原文纠正错漏的方法。这种学习策略主要属于（　）。', '[["A","精加工策略"],["B","组织策略"],["C","复述策略"],["D","资源管理策略"]]', '["C"]', '反复朗读、逐段尝试背诵并对照原文纠正错漏，是通过重复识记加深记忆痕迹，属于复述策略。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (155, 10, 65, 'single', 1.0, '2025年教育部提出要实施基础教育课程教学改革深化行动。下列属于该行动重点任务的有：①推进核心素养导向的课程建设 ②深化教学方式改革 ③完善教育评价体系 ④取消所有考试（　）', '[["A","①②③"],["B","①②④"],["C","①③④"],["D","②③④"]]', '["A"]', '2025年教育部基础教育课程教学改革深化行动的重点任务包括：①推进核心素养导向的课程建设；②深化教学方式和评价改革；③推进教育数字化转型赋能教学。④取消所有考试不属于改革任务。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (156, 10, 66, 'single', 1.0, '某中学一名班主任发现班上有名学生最近学习成绩下降且情绪低落。班主任主动找该学生谈话了解情况后与家长取得联系共同商讨帮助方案。班主任的做法体现了（　）', '[["A","爱岗敬业"],["B","教书育人"],["C","关爱学生"],["D","为人师表"]]', '["C"]', '班主任发现学生成绩下降、情绪低落，主动谈话了解情况并与家长取得联系，体现了对学生身心状况的关心爱护，符合《中小学教师职业道德规范》中关爱学生的要求。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (157, 10, 67, 'single', 1.0, '一次重要考试后，小吴把成绩大幅下滑归结为“自己天生就不是学习的料，再努力也没用”，此后上课经常走神、作业也不愿完成。教师最恰当的引导是（　）。', '[["A","帮助他把归因从能力不足转向努力程度、学习方法等可控因素"],["B","认同他的判断，劝他把目标转向对成绩要求不高的方向"],["C","告诉他题目太难是全班的共同问题，不必在意这次成绩"],["D","指出主要是运气不好，下次考试自然会考好"]]', '["A"]', '依据韦纳归因理论，能力属于内部、稳定、不可控因素，把失败稳定归因于能力不足会形成习得性无助，削弱学习动机。教师应引导学生归因于努力程度、学习方法等内部、可控因素，增强自我效能感。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (158, 10, 68, 'single', 1.0, '某中学一名教师因为学生未完成作业而对该学生说：你这样就别来上学了。该教师的言行（　）。', '[["A","合法，教师有权决定是否让学生继续上课"],["B","合法，未完成作业的学生不影响其他同学学习"],["C","不合法，侵犯了学生的受教育权和人格尊严"],["D","合法，但应事先通知家长"]]', '["C"]', '教师因学生未完成作业而说你就别来上学了，属于以言语方式剥夺学生受教育权的行为，违反了《中华人民共和国义务教育法》第二十七条对违反学校管理制度的学生学校应当予以批评教育不得开除的规定。同时，侮辱性言语也侵犯了学生的人格尊严权。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (159, 10, 69, 'single', 1.0, '某小学一名老师在教学反思中写道：这节课我讲了太多学生自主探究的时间不够。下次我要把至少一半的时间留给学生。这位教师的反思说明他意识到了（　）', '[["A","教师应减少讲授时间，增加学生自主探究和合作交流的时间"],["B","教师应把知识讲得更详细，确保每个学生都能听懂"],["C","教师应统一教学进度，所有学生按同一节奏学习"],["D","教师应增加课堂练习量，用大量练习巩固知识"]]', '["A"]', '教师反思讲了太多学生自主探究时间不够，说明教师意识到课堂应以学生为中心，减少教师讲授时间，增加学生自主探究和合作交流的机会，让学生在做中学、在探究中建构知识。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (160, 10, 70, 'single', 1.0, '物理老师发现：平时小测验，班里几位基础薄弱的学生成绩总不理想；而在一次难度适中、组织严密的校级竞赛中，他们因适度紧张、注意力高度集中，反而发挥出比平时更高的水平。这一现象最适宜用下列哪一原理解释？（　）', '[["A","耶克斯—多德森定律，中等动机水平最有利于完成难度适中的任务"],["B","强化原理，外部奖励越多学习效果越好"],["C","迁移规律，两种学习任务越相似越容易迁移"],["D","遗忘规律，间隔时间越短保持效果越好"]]', '["A"]', '耶克斯一多德森定律表明，动机强度与工作效率之间呈倒U形关系，中等强度的动机最有利于任务完成；且任务难度不同，最佳动机水平不同，较难任务需要相对更低的动机唤醒。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (161, 10, 71, 'single', 1.0, '某初中学生在学习历史时把重要历史事件按照时间顺序整理成了一份年代表。学生运用的学习策略属于（　）', '[["A","复述策略"],["B","精加工策略"],["C","组织策略"],["D","资源管理策略"]]', '["C"]', '把重要历史事件按时间顺序整理成年代表，是对学习材料进行系统化整理，建立事件之间的时间顺序关系，属于组织策略。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (162, 10, 72, 'single', 1.0, '某小学一名学生因为害怕被批评而认真学习。按照科尔伯格的道德发展阶段该学生的道德水平最可能处于（　）', '[["A","以避免惩罚、服从权威为定向"],["B","以相对功利、个人利益交换为定向"],["C","以寻求认可、成为“好孩子”为定向"],["D","以社会契约、法律可经民主程序修正为定向"]]', '["A"]', '学生因为害怕被批评而认真学习，其行为动机是避免惩罚（批评），属于前习俗水平的惩罚与服从定向阶段。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (163, 10, 73, 'single', 1.0, '某中学一名教师坚持每天写教学日记记录教学中的成功经验和失败教训三年后他的教学水平有了显著提高。这位教师的专业发展主要依靠（　）', '[["A","脱产进修"],["B","校本研修"],["C","学历提升"],["D","实践反思"]]', '["D"]', '教师坚持每天写教学日记，记录教学中的成功经验和失败教训，在真实教学情境中持续反思和改进，属于实践反思型的教师专业发展途径。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (164, 10, 74, 'single', 1.0, '复习历史时，教师建议学生不要只机械摘抄笔记，而要用自己的话把课文复述一遍、把新知识与已学事件进行比较联系。这种学习策略主要属于（　）', '[["A","组织策略：列提纲并画出知识之间的层级关系"],["B","复述策略：划出重点并反复大声朗读"],["C","精加工策略：用自己的话讲解并把新旧知识联系起来"],["D","资源管理策略：把学习环境布置得安静舒适、排除干扰"]]', '["C"]', '精加工策略是把新信息与已有知识建立深层联系、增加信息意义的策略，如用自己的话解释、讲给他人听、生成类比、联系已有知识等。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (165, 10, 75, 'single', 1.0, '教师王某认为学校对其年度考核结果不公正、扣发绩效工资侵犯了自身合法权益，向学校提出异议后未获满意答复。依据《中华人民共和国教师法》，王某可以采取的法定救济途径是（　）', '[["A","向教育行政部门提出申诉"],["B","直接组织学生罢课施压"],["C","在网络上公开学生隐私以引起关注"],["D","拒绝承担任何教育教学工作"]]', '["A"]', '《中华人民共和国教师法》第三十九条规定，教师对学校或者其他教育机构侵犯其合法权益的，或者对学校或者其他教育机构作出的处理不服的，可以向教育行政部门提出申诉。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (166, 10, 76, 'single', 1.0, '某初中物理老师在教学浮力时先让学生猜测不同物体在水中的沉浮情况再做实验验证。当实验结果与猜测不同时学生们表现出了强烈的探究欲望。老师运用的教学策略是（　）', '[["A","先行组织者策略"],["B","认知冲突与认知失衡：当新知识与学生已有认知矛盾时会激发探究动机"],["C","机械学习"],["D","接受学习"]]', '["B"]', '教师先让学生猜测沉浮情况，再做实验验证，当实验结果与猜测不同时，学生产生认知冲突，从而激发强烈的探究欲望。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (167, 10, 77, 'single', 1.0, '某初中数学教师休完产假回校后，学校以"岗位已满、学科教师富余"为由，未与本人协商，便通知她下学期改任宿管员，工资待遇按工勤岗位发放。该教师表示不愿接受，学校遂口头告知将解除其聘用关系。学校的这一做法（　）', '[["A","正确，学校有权根据教学需要随时调整教师的工作岗位"],["B","错误，变更聘用合同约定的岗位应与教师协商一致，学校单方调岗并口头解除聘用关系于法无据"],["C","正确，只要工资照常发放，学校可以不经协商调整任何岗位"],["D","错误，学校任何情况下都不能与教师解除聘用关系"]]', '["B"]', '依据《中华人民共和国教师法》和《事业单位人事管理条例》，教师与学校签订聘用合同后，双方应按合同约定履行；变更岗位、报酬等合同约定事项须经双方协商一致。学校未经协商单方将教师调至工勤岗位并以口头方式解除聘用关系，程序和实体均无法律依据。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (168, 10, 78, 'single', 1.0, '某小学老师在教学时善于运用正面引导而不是简单批评。当学生犯错时她总是先肯定做得好的方面再指出不足。这种做法体现了（　）', '[["A","严格要求与尊重信任相结合原则"],["B","长善救失原则"],["C","因材施教原则"],["D","疏导原则"]]', '["D"]', '教师先肯定学生做得好的方面再指出不足，以正面引导代替简单批评，体现了疏导原则：循循善诱、以理服人、因势利导、以表扬激励为主。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (169, 10, 79, 'single', 1.0, '初三学生小海因一学期内多次打架、扰乱课堂，校务会研究后决定将其除名、注销学籍，劝其自谋出路。小海尚在接受九年义务教育期间，对该校务会决定的合法性判断正确的是（　）', '[["A","除名决定有效，品行不良学生可被学校清理出门以保证升学率"],["B","除名决定无效，义务教育阶段学校不得以任何理由开除学生，应坚持教育为主"],["C","除名决定效力待定，只要家长签字认可即可生效"],["D","除名决定有效，但须改为勒令退学的名义"]]', '["B"]', '《中华人民共和国义务教育法》第二十七条规定，对违反学校管理制度的学生，学校应当予以批评教育，不得开除。“除名、注销学籍、勒令退学”实质都是剥夺未成年学生接受义务教育的机会，与该条强制性规定相抵触，决定自始无效。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (170, 10, 80, 'single', 1.0, '某中学一名教师在教学过程中发现一名学生总是在课堂上睡觉。经过了解该学生每天要帮父母做农活到深夜导致睡眠不足。教师最恰当的做法是（　）', '[["A","课堂上当面批评该学生不遵守纪律，并罚站一节课以警示其他同学"],["B","私下了解情况后给予关心，与家长沟通合理安排家务与作息，并在学业上提供适当帮助"],["C","不加过问，认为睡觉是学生自己的事，学校只负责课堂教学"],["D","直接要求家长不让孩子再做家务，否则将该学生交学校德育处处理"]]', '["B"]', '学生上课睡觉的背后是帮父母做农活导致睡眠不足，教师首先应尊重和关爱学生，私下了解原因而非公开批评；其次要主动与家长沟通，争取家长配合合理安排孩子的作息与家务；同时在学业上给予理解和适当帮助。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (171, 10, 81, 'multi', 1.6, '某小学在推进课程改革中采取了以下措施：开设可供学生自主选择的选修课程、开展研究性学习。这些措施共同体现了（　）', '[["A","课程结构的选择性与多样性"],["B","学习方式向自主、合作、探究转变"],["C","以统一考试分数作为衡量学生的唯一标准"],["D","取消学科课程，全面代之以活动课程"],["E","课程管理由学校自主决定，不再执行国家课程方案"]]', '["A","B"]', '开设选修课程增强了课程结构的选择性与多样性，体现课程结构改革方向。研究性学习强调学生自主探究，体现学习方式向自主、合作、探究转变。C项以考试分数为唯一标准正是新课改要纠正的；D项新课改优化课程结构而非取消学科课程；E项我国实行国家、地方、学校三级课程管理，学校课程必须以执行国家课程方案为前提。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (172, 10, 82, 'multi', 1.6, '某初中学生在学习中遇到以下困难：英语单词记不住、数学公式不理解、作文没有思路。教师分别指导学生选用恰当的学习策略，下列匹配合理的有（　）', '[["A","记忆英语单词可运用谐音联想、关键词法等精加工策略"],["B","理解数学公式可运用组织策略，画出公式间联系的知识网络"],["C","写作文可运用元认知策略，先列提纲计划、写作中监控、写完检查"],["D","三类困难都只靠反复朗读抄写的复述策略即可解决"],["E","英语单词也可通过分散复习、尝试回忆等复述策略加以巩固"]]', '["A","B","C","E"]', 'A项谐音联想、关键词法通过赋予材料意义帮助记忆，属精加工策略。B项用图表、网络梳理公式间的关系属组织策略，有助于理解而非死记。C项写作前列计划、写作中监控、完成后评价修改，是元认知策略的典型运用。E项单词记忆需要精加工与复述配合，分散复习、尝试回忆是有效的复述方法。D项不选：不同学习任务、不同问题应选用不同策略，把所有困难都交给机械复述是错误做法。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (173, 10, 83, 'multi', 1.6, '班主任发现，学生在不同情境下对同一知识点的掌握表现差异很大。下列说法符合学习迁移与知识应用规律的有（　）', '[["A","情境越陌生，已有知识对解决问题越不起任何作用"],["B","只要练习量足够大，任何知识都能自动迁移到所有新情境"],["C","学生在相似情境中能自动迁移，说明产生了低通路迁移"],["D","让学习者在与实际应用相近的情境中完成任务，有助于所学知识的提取和运用"],["E","教师应引导学生概括出一般原理，以促进高通路迁移"]]', '["C","D","E"]', 'C项在大量变式练习后技能在相似情境中自动激活，属低通路迁移。D项在与应用相近的情境中练习，知识更易被激活提取，体现情境性迁移的观点。E项高通路迁移需要学习者有意识地抽象概括一般原理并迁移到新情境，教师引导概括是关键。A项陌生情境中已有知识仍可通过类比、原理迁移发挥作用。B项迁移受情境相似性、概括水平和元认知等制约，机械重复不等于自动迁移。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (174, 10, 84, 'multi', 1.6, '新教师小陈在入职培训时想弄明白自己依法可以做什么。依据《中华人民共和国教师法》，下列属于教师依法享有的权利的有（　）', '[["A","开展教育教学活动、进行教育教学改革和实验"],["B","从事科学研究、学术交流，参加专业的学术团体"],["C","指导学生的学习和发展，评定学生的品行和学业成绩"],["D","按时获取工资报酬，享受国家规定的福利待遇"],["E","对违纪学生实施体罚或者变相体罚以维护课堂纪律"]]', '["A","B","C","D"]', '《中华人民共和国教师法》第七条规定教师享有教育教学权、科学研究与学术交流权、指导评价权、获取工资报酬和享受国家规定福利待遇的权利，此外还有民主管理权、进修培训权等。E项体罚和变相体罚为《中华人民共和国义务教育法》《中华人民共和国未成年人保护法》明令禁止，不仅不是教师权利，反而是不可触碰的法律红线。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (175, 10, 85, 'multi', 1.6, '教龄三年的钟老师在教学日志中列出下学期改进计划。依据《中小学教师职业道德规范（2008年修订）》对“爱岗敬业”的要求，下列计划恰当的有（　）', '[["A","对所教两个班的作业全批全改，对典型错误集中讲评并跟踪订正"],["B","每学期至少听8节指导教师的课，针对自身短板参加专题研修"],["C","认为教材教法已经熟悉，备课沿用三年前的旧教案即可"],["D","主动承担学校社团指导任务，认真准备每次活动方案"],["E","把写教学反思、参加教研活动视为额外负担，能推就推"]]', '["A","B","D"]', '爱岗敬业要求教师忠诚于人民教育事业，勤恳敬业，甘为人梯，乐于奉献，对工作高度负责。A项全批全改、跟踪订正体现对教学工作高度负责。B项坚持听课、研修改进，体现勤恳敬业和专业提升。D项主动承担社团指导并认真准备，体现乐于奉献、对工作负责。C项长期照搬旧教案不更新，违背认真备课和与时俱进的要求。E项把教研反思当负担、推诿敷衍，与敬业精神相悖。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (176, 10, 86, 'multi', 1.6, '某初中教师在综合实践课中采用项目式学习，让学生围绕“社区垃圾分类”项目分组调研、设计方案并展示成果。下列属于项目式学习典型特征的有（　）', '[["A","教师系统讲授、学生被动接受为主要活动方式"],["B","以学生为中心，强调在做中学"],["C","学习成果通常以作品、方案或报告等形式公开展示"],["D","围绕一个真实的驱动性问题持续探究"],["E","往往需要综合运用多学科知识与方法"]]', '["B","C","D","E"]', '项目式学习的典型特征包括：以学生为中心、在真实任务中做中学（B），以驱动性问题组织持续探究（D），最终形成公开的作品或成果并进行展示评价（C），任务常具跨学科性（E）。A项教师全程讲授、学生被动接受是传统授受式教学的特征。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (177, 10, 87, 'multi', 1.6, '课间，学生小吴在校园道路上骑自行车时不慎撞伤同学小王。经查明，事发路段设有“校内禁止骑车”的明显标志，学校平时也进行过交通安全教育，但事发时并无教职工在该路段巡查。关于赔偿责任，下列说法正确的有（　）', '[["A","小吴实施了致害行为，其监护人应依法承担相应的侵权赔偿责任"],["B","学校在现场管理上存在疏漏，如有过错应承担与其过错相应的责任"],["C","小王自身无过错，应由其自行承担全部损失"],["D","无论各方有无过错，学校都应承担全部赔偿责任"],["E","应根据小吴一方与学校各自的过错程度，按比例确定责任"]]', '["A","B","E"]', 'A项小吴的行为直接造成损害，依《中华人民共和国民法典》第一千一百八十八条，限制民事行为能力人造成他人损害的，由监护人承担侵权责任。B项学校虽设标志、开展教育，但事发时无人巡查，现场管理存在一定疏漏，依《民法典》第一千二百条，学校未尽教育、管理职责的部分承担相应责任。E项多方过错时应按各自过错程度确定责任比例。C项小王无过错，不应自担全部损失。D项限制民事行为能力人受侵害适用过错责任，学校并非当然全责。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (178, 10, 88, 'multi', 1.6, '14岁的初二学生小林父母长期在外务工，他随祖父母生活，近来经常旷课去网吧，还在校外向低年级学生索要财物。学校发现后拟协同各方处理。依据《中华人民共和国预防未成年人犯罪法》，下列做法正确的有（　）', '[["A","学校建立学生欺凌和不良行为的排查、教育管理制度"],["B","对旷课学生，学校及时联系其父母或其他监护人"],["C","对有严重不良行为的学生，可以决定开除学籍，移交公安机关处理"],["D","由公安机关依法对有严重不良行为的未成年人进行矫治教育"],["E","居委会、学校、家庭相互配合，共同做好干预和帮教工作"]]', '["A","B","D","E"]', 'A项《预防未成年人犯罪法》要求学校建立学生欺凌防控和不良行为管理教育制度。B项旷课属于不良行为，学校应当及时联系监护人加强管教。D项对向他人索要财物等严重不良行为，由公安机关采取矫治教育等措施。E项预防未成年人犯罪坚持预防为主、提前干预，要求家庭、学校、社会协同帮教。C项对接受义务教育的未成年学生不得开除学籍。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (179, 10, 89, 'multi', 1.6, '物理教师在教学中发现学生常把生活经验直接套用到物理问题上导致错误。依据学习迁移理论，下列做法中能有效促进正迁移、减少负迁移的有（　）。', '[["A","让学生完全脱离生活经验，只背诵教材上的结论"],["B","在教学中只讲结论、省去变式和练习环节，让学生记住即可答题"],["C","重视变式练习，让学生在不同情境中运用同一原理"],["D","讲清新知识与已有经验之间的相同点和本质区别，帮助学生精确分化"],["E","加强学习方法的指导，培养学生的迁移意识"]]', '["C","D","E"]', '促进正迁移的条件包括：通过变式练习在多种情境中运用同一原理（C），讲清新旧知识的相同点与本质区别、帮助经验精确分化（D），加强学习方法指导、培养迁移意识（E）。A项脱离生活经验、机械背诵既不符合学习规律，也不利于迁移。B项只讲结论、省去变式练习会导致知识无法在新情境中提取和辨别。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (180, 10, 90, 'multi', 1.6, '初三学生普遍面临升学压力。下列做法有助于科学缓解学生考试压力、维护心理健康的有（　）', '[["A","开展心理健康讲座，教授放松训练和时间管理等压力应对技巧"],["B","引导学生合理归因，正确看待考试与分数"],["C","要求学生取消一切休息娱乐，把全部时间用于刷题"],["D","用“考不上重点高中人生就完了”等说法激励学生抓紧复习"],["E","公开排名并张榜公布每次测验成绩，以竞争督促学生进步"]]', '["A","B"]', 'A项心理健康讲座与放松、时间管理训练能提升学生应对技能，是学校心理健康教育的常规有效做法。B项合理归因、理性看待考试，可纠正不合理信念，降低考试焦虑。C项取消休息、持续刷题会造成身心透支。D项夸大考试后果的说法会加重学生心理负担。E项公开排名张榜容易伤害学生自尊、加剧焦虑。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (541, 2, 1, 'judge', 0.6, '数学课上，王老师以一次函数图像为铺垫引出二次函数。这种由已知到未知的安排体现了巩固性原则。', '[["A","正确"],["B","错误"]]', '["B"]', '由已知到未知、由旧引新体现的是循序渐进原则，即按学科逻辑和学生认知顺序逐步推进。巩固性原则强调的是对已学知识的及时复习与牢固保持，并非按顺序推进新内容。题干把循序渐进错标为巩固性。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (542, 2, 2, 'judge', 0.6, '某中学开设书法、陶艺等选修课，期末以作品展示代替笔试。这说明课程评价只能是质性评价。', '[["A","正确"],["B","错误"]]', '["B"]', '质性评价与量化评价各有优势，新课改倡导质性评价与量化评价相结合，而非用质性评价完全取代量化评价。该校以作品展示代替笔试属于质性评价的一种形式，但不能由此得出课程评价只能是质性评价的结论。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (543, 2, 3, 'judge', 0.6, '班主任李老师推行优点银行制度，让学生每周记录同学优点、月末评选。这主要体现了长善救失原则。', '[["A","正确"],["B","错误"]]', '["A"]', '依靠积极因素、克服消极因素（长善救失）原则要求教育者善于发现学生身上的闪光点，调动其积极性，以优点克服缺点。李老师让同学互相记录优点、评选发现美的眼睛，正是引导学生在他人身上发现积极因素，以正向激励促进品德发展，体现了长善救失原则。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (544, 2, 4, 'judge', 0.6, '新教师张老师每天备课到深夜，反复听老教师的课并请教研员听课指导。这体现了教师劳动的广延性。', '[["A","正确"],["B","错误"]]', '["B"]', '教师劳动的广延性指教育影响的空间范围广——没有严格的时空界限，校内外、课内外都可能发挥教育作用。而张老师备课到深夜、反复听课改进等行为，体现的是教师劳动的复杂性和创造性（因材施教、不断钻研），并非广延性。题干混淆了概念。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (545, 2, 5, 'judge', 0.6, '校长在培训中强调，学校可对国家课程任意改造，校本课程无需符合国家课程方案。这符合三级课程管理体制。', '[["A","正确"],["B","错误"]]', '["B"]', '三级课程管理下学校确实拥有课程开发和校本实施的自主权，但校本化改造不得违背国家课程方案的基本要求，校本课程也须在国家课程计划框架内设置。题干把自主权绝对化，主张任意改造、无需符合国家方案，故说法错误。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (546, 2, 6, 'judge', 0.6, '班主任张老师先组织全班共定公约与目标，候选人经活动展示后由全班民选班委会。这有利于班集体形成。', '[["A","正确"],["B","错误"]]', '["A"]', '班集体的形成需要经历确定奋斗目标、建立核心骨干、形成集体舆论和班风等阶段。张老师先让全班共同制定公约和目标（确定奋斗目标），再民主选举班干部（建立核心骨干），整个过程体现了民主参与，有助于增强学生的集体归属感和责任感，有利于班集体的形成与培养。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (547, 2, 7, 'judge', 0.6, '班里双胞胎遗传相近，性格却一外向一内敛。李老师据此认为环境和教育在人的发展中起决定性作用。', '[["A","正确"],["B","错误"]]', '["B"]', '遗传为个体发展提供了可能性，但不能决定发展方向。双胞胎在性格上的差异，体现了遗传相同条件下环境和个体主观能动性带来的差异。然而，学校教育在人的发展中起主导作用，并非决定性作用——个体的主观能动性才是发展的决定性因素。李老师将环境和教育说成决定性因素，夸大了其作用。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (548, 2, 8, 'judge', 0.6, '语文公开课上，李老师让学生为课文配两幅对比插图。教研员认为这把两门学科并列整合，属于综合课程。', '[["A","正确"],["B","错误"]]', '["B"]', '配插图虽涉及美术，但美术只是理解课文的手段，活动仍以语文内容为核心并由学生动手完成，体现的是学科课程与活动课程的融合，并非把语文、美术并列整合而成的综合课程。教研员判断错误。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (549, 2, 9, 'judge', 0.6, '物理课讲完浮力，王老师借学生兴趣追问死海为何托住人，留作课后探究。这说明教学是预设与生成统一的过程。', '[["A","正确"],["B","错误"]]', '["A"]', '教学过程既是教师有目的、有计划地预设的过程，也是在师生互动中不断生成的过程。王老师按预设完成教学任务后，敏锐地抓住学生的兴趣点生成新的探究问题将课堂教学向课外延伸，体现了预设与生成的辩证统一。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (550, 2, 10, 'judge', 0.6, '科学课实验中，小明把等量水倒入粗细两杯，总说细高杯水多。老师据此判断他已获守恒、进入具体运算阶段。', '[["A","正确"],["B","错误"]]', '["B"]', '被杯子外形迷惑、不能判断水量相等，说明小明尚未形成守恒概念，认知仍处于具体运算阶段之前的前运算阶段。教师从不守恒的表现反判其已进入具体运算阶段结论错误。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (551, 2, 11, 'judge', 0.6, '英语课上，李老师用积分奖励学生答问、助人。她认为这属于巴甫洛夫经典条件作用原理的运用。', '[["A","正确"],["B","错误"]]', '["B"]', '积分是在目标行为出现之后给予的愉快刺激，用以提高该行为再次发生的概率，属于斯金纳操作性条件作用中的正强化；经典条件作用需要中性刺激与无条件刺激反复结合建立反应，本题并无此机制。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (552, 2, 12, 'judge', 0.6, '小杰常不吃早饭、上课精神不振，张老师帮他吃上免费早餐后专注度提升。马斯洛认为，生理需要满足后求知需要才可能成为优势需要。', '[["A","正确"],["B","错误"]]', '["A"]', '马斯洛需要层次理论将人的需要由低到高分为生理需要、安全需要、归属与爱的需要、尊重需要、求知需要、审美需要和自我实现需要。低层次需要满足后高层次需要才会出现。小杰的生理需要（吃饱）得到满足后，才有余力追求求知需要（专心学习）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (553, 2, 13, 'judge', 0.6, '学生小雨期中备考时制定计划、记录任务完成，做数学卷每题后都回头检查。她主要使用的是元认知策略。', '[["A","正确"],["B","错误"]]', '["A"]', '元认知策略是学习者对自身认知过程进行计划、监控和调节的策略。小雨制定复习计划属于计划策略，做题时回头检查属于监控策略，记录完成情况属于调节策略——三者都是元认知策略的具体表现。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (554, 2, 14, 'judge', 0.6, '小红没考好，说题目太偏、全班都没考好。班主任认为她归因于任务难度易生羞愧感、不利于激发动力。', '[["A","正确"],["B","错误"]]', '["B"]', '韦纳归因理论将成败归因分为能力、努力、任务难度、运气等维度。任务难度属于外部、稳定、不可控因素。将失败归因于任务难度，产生的情绪主要是气愤和无奈，而非羞愧感。产生羞愧感的归因方式是将失败归因于能力不足（内部、稳定、不可控因素）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (555, 2, 15, 'judge', 0.6, '历史课上，张老师让学生借助民国报纸等材料，站在当时市民角度讨论生活变化。这体现了建构主义学习观。', '[["A","正确"],["B","错误"]]', '["A"]', '建构主义学习观认为，知识不是通过教师传授得到的，而是学习者在一定情境下借助他人帮助、利用学习资料通过意义建构获得的。张老师没有直接讲授结论，而是提供原始材料让学生在情境中合作探究、主动建构知识，最后再由教师提升总结，充分体现了建构主义以学生为中心的学习观。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (556, 2, 16, 'judge', 0.6, '学生小杰学法语时借英语语法相似上手很快，却总带英语口音难纠正。从迁移看，前者正迁移、后者负迁移。', '[["A","正确"],["B","错误"]]', '["A"]', '正迁移指一种学习对另一种学习产生积极促进作用；负迁移指一种学习对另一种学习产生消极干扰作用。小杰利用英语语法相似性快速学习法语语法，是已有知识对新学习的促进，属正迁移；英语发音习惯干扰法语元音的正确发音，是已有知识对新学习的干扰，属负迁移。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (557, 2, 17, 'judge', 0.6, '班里同学背的古诗词一周就忘大半，班主任建议考前集中突击背十遍，认为依据遗忘先快后慢规律这样效果更好。', '[["A","正确"],["B","错误"]]', '["B"]', '遗忘先快后慢的规律要求学习之后及时复习、间隔分散地巩固，分散复习的效果优于考前集中突击。班主任把集中突击说成符合该规律，方法与规律相悖。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (558, 2, 18, 'judge', 0.6, '道法课上讨论朋友作弊该不该揭发。科尔伯格认为，回答必须守规则、即使失去朋友也揭发的学生处于习俗水平。', '[["A","正确"],["B","错误"]]', '["A"]', '科尔伯格道德发展理论中，习俗水平的特征是个体着眼于社会的期望和规则来判断行为对错。规则必须遵守的回答体现了对法律与秩序定向（习俗水平第四阶段）的认同——行为正确与否取决于是否遵守社会规则和维持社会秩序。前习俗水平关注惩罚和利益，后习俗水平关注普遍伦理原则，此回答明显属于习俗水平。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (559, 2, 19, 'judge', 0.6, '小晨老师从不当众批评学生、也不提纪律要求，班级日渐散漫。这属于放任型领导导致的松散型课堂气氛。', '[["A","正确"],["B","错误"]]', '["A"]', '勒温的教师领导方式分为专制型、民主型和放任型三种。放任型领导的特征是教师对学生不加约束、放任自流，缺乏有效的组织和管理。小晨老师虽然态度温和、不批评学生，但缺乏必要的纪律要求和管理手段，导致纪律散漫、作业完成率下降，形成了消极松散的课堂气氛。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (560, 2, 20, 'judge', 0.6, '王老师翻看小雨未上锁的日记后，在班会上公开其早恋内容。她认为出于教育好意就不算侵犯隐私权。', '[["A","正确"],["B","错误"]]', '["B"]', '隐私权是公民享有的私人生活安宁与私人信息秘密依法受到保护、不被他人非法侵扰的权利。未成年学生同样享有隐私权。班主任未经允许翻看学生日记并在班上公开其中内容，构成了对学生隐私权的侵犯。即使出于教育目的，也不能以此为由侵犯学生的合法权利。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (561, 2, 21, 'judge', 0.6, '李老师在教研会上的发言获期刊刊发邀请，她自主决定是否发表，认为依教师法这属于民主管理权。', '[["A","正确"],["B","错误"]]', '["B"]', '自主决定科研成果是否发表属于教师的学术研究权，即从事科学研究、学术交流、在学术活动中发表意见的权利；民主管理权是指对学校教育教学、管理工作提出意见建议、参与教职工代表大会等。题干张冠李戴。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (562, 2, 22, 'judge', 0.6, '篮球课前张老师讲安全事项并做热身，小明抢球时碰撞骨折，设施合格且其全程在场。学校应承担过错推定责任。', '[["A","正确"],["B","错误"]]', '["B"]', '《民法典》第1176条规定了自甘风险规则：自愿参加具有一定风险的文体活动，因其他参加者的行为受到损害的，受害人不得请求其他参加者承担侵权责任，但其他参加者对损害的发生有故意或重大过失的除外。同时，学校已尽到安全教育和管理职责（讲解注意事项、热身示范、全程在场、设施合格），不存在过错，不应承担侵权责任。本题并非适用过错推定，而是学校已尽到管理职责不承担责任。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (563, 2, 23, 'judge', 0.6, '随迁学生小雨到成都读初二，某中学以学位紧张为由要求缴借读费后方可入学。依现行法律，该校做法合法。', '[["A","正确"],["B","错误"]]', '["B"]', '《义务教育法》规定，适龄儿童、少年免试入学，地方各级人民政府应当保障适龄儿童、少年在户籍所在地学校就近入学。对于随迁子女，明确规定其在父母或其他法定监护人工作或居住地接受义务教育的，当地人民政府应当为其提供平等接受义务教育的条件。学校向随迁子女收取借读费的做法违反了义务教育法的平等入学原则。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (564, 2, 24, 'judge', 0.6, '初三班主任劝成绩靠后的学生转职高，被拒后要求他们在家自习。该班主任侵犯了学生的受教育权。', '[["A","正确"],["B","错误"]]', '["A"]', '受教育权是学生的基本权利，包括参加教育教学计划安排的各种活动、使用教育教学设施等权利。班主任劝说学生转学和要求学生在家自习，实质上剥夺了学生在校接受教育的权利，构成了对受教育权的侵犯。教师不得以成绩差为由拒绝学生在校学习。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (565, 2, 25, 'judge', 0.6, '李老师不服学校处分提出申诉，教育局经查认为处分不当，直接撤销原处分。这符合教师申诉制度规定。', '[["A","正确"],["B","错误"]]', '["A"]', '《教师法》第三十九条规定，教师对学校或者其他教育机构侵犯其合法权益的，或者对学校或者其他教育机构作出的处理不服的，可以向教育行政部门提出申诉。教育行政部门应当在接到申诉的三十日内作出处理。教育局作为主管部门受理申诉后，经审查认定处分不当，有权作出撤销或变更的处理决定。这符合教师申诉制度的程序规定。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (566, 2, 26, 'judge', 0.6, '小晨上课走神，王老师当众骂他笨，课后又罚抄课文20遍。这违反了关爱学生和教书育人的师德要求。', '[["A","正确"],["B","错误"]]', '["A"]', '关爱学生要求教师关心爱护全体学生，尊重学生人格，平等公正对待学生，不讽刺、挖苦、歧视学生，不体罚或变相体罚学生。王老师当众辱骂学生是讽刺挖苦行为罚抄20遍属于变相体罚，违反了关爱学生的师德规范。教书育人要求遵循教育规律，实施素质教育，循循善诱，王老师的做法也违反了这一要求。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (567, 2, 27, 'judge', 0.6, '家长考前送购物卡请班主任评分关照，李老师婉言谢绝、坚持按真实水平评分。这践行了为人师表规范。', '[["A","正确"],["B","错误"]]', '["A"]', '为人师表要求教师坚守高尚情操，知荣明耻，严于律己，以身作则，自觉抵制不良风气。《新时代中小学教师职业行为十项准则》也明确要求坚守廉洁自律，不得索要、收受学生及家长财物。李老师拒绝家长礼品、坚持公正评价，体现了廉洁自律和为人师表的师德要求。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (568, 2, 28, 'judge', 0.6, '张老师针对善逻辑、善形象、爱动手三类学生设计三种活动供选择。这体现了新课改尊重个体差异的学生观。', '[["A","正确"],["B","错误"]]', '["A"]', '新课改的学生观强调学生是独特的人，每个学生都有自身的独特性，要因材施教。张老师针对不同认知风格的学生设计不同的学习活动，体现了尊重学生个体差异因势利导的教育理念，符合新课改以人为本、关注学生差异的学生观。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (569, 2, 29, 'judge', 0.6, '从教20年的王老师坚持参加研修、阅读期刊、学习信息技术辅助教学。这体现了终身学习的师德要求。', '[["A","正确"],["B","错误"]]', '["A"]', '终身学习是教师专业发展的不竭动力。时代发展要求教师不断更新知识结构、提升专业素养。王老师主动参加研修、阅读期刊、学习新技术，体现了终身学习的师德要求。教师职业具有复杂性、创造性等特点，只有持续学习才能适应教育变革的需要。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (570, 2, 30, 'judge', 0.6, '某校教师会上，校长传达：2024年全国教育大会提出教育具有政治、经济、战略三大属性。这一表述正确。', '[["A","正确"],["B","错误"]]', '["B"]', '2024年全国教育大会概括的教育三大属性是政治属性、人民属性、战略属性，并无经济属性。题干用经济属性偷换了人民属性，表述错误。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (571, 2, 31, 'single', 1.0, '城区某优质中学在新生入学教育时，校长介绍了学校的办学理念：让每个学生都成为最好的自己。这一理念体现了教育目的价值取向中的（　）', '[["A","社会本位论"],["B","个人本位论"],["C","文化本位论"],["D","生活本位论"]]', '["B"]', '个人本位论强调教育目的应从个人本性、需要出发，认为教育的目的在于促进个人的自我实现和个性发展。让每个学生都成为最好的自己，强调个体发展和自我实现，属于个人本位论的价值取向。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (572, 2, 32, 'single', 1.0, '初二年级开展研学旅行活动，王老师带领学生参观都江堰水利工程后，要求学生用数学知识计算堰体的倾斜角度和水流量。这种教学安排主要体现了（　）', '[["A","直观性原则"],["B","理论联系实际原则"],["C","量力性原则"],["D","巩固性原则"]]', '["B"]', '理论联系实际原则要求教学要以基础知识为主导，引导学生从理论与实际的结合上去理解知识，并运用知识去分析、解决实际问题。王老师让学生参观后用数学知识计算水利工程参数，将书本知识与生产实践结合，体现了理论联系实际原则。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (573, 2, 33, 'single', 1.0, '某校推行翻转课堂模式：学生课前观看教学视频完成知识学习，课上则进行讨论、实验和答疑。从教学过程的角度看，这种做法主要改变了（　）', '[["A","教学评价的标准"],["B","教学目标"],["C","教学内容的逻辑顺序"],["D","知识传授与内化的时间顺序"]]', '["D"]', '传统教学模式中，知识传授在课堂上完成（教师讲授），知识内化在课后完成（学生练习）。翻转课堂将知识传授前置到课前（视频学习），课堂上则进行深度讨论和实践（知识内化），改变了知识传授与内化的时间顺序，但教学目标、内容逻辑和评价标准并未根本改变。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (574, 2, 34, 'single', 1.0, '初三数学课上，张老师发现小明对几何证明题特别感兴趣，经常主动挑战难题；而小红对代数计算更擅长，但对几何证明感到吃力。根据加德纳的多元智力理论，这说明（　）', '[["A","几何证明只考查逻辑数学智力"],["B","小明的智力水平高于小红"],["C","两人的智力类型不同，各有优势领域"],["D","小红不具备学习几何的能力"]]', '["C"]', '加德纳多元智力理论认为人的智力是多元的，每个人在不同智力维度上有不同的优势组合。小明在空间智力方面较强（几何证明），小红可能在逻辑数学智力方面较强（代数计算），这是智力类型的差异，不是智力水平的高低之分。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (575, 2, 35, 'single', 1.0, '某校在课程设计中将劳动教育融入各学科：语文课学写劳动日记、数学课测量校园面积、生物课种植蔬菜。这种课程设计思路体现了全面发展教育中（　）', '[["A","五育之间的相互渗透与融合"],["B","智育的独特性"],["C","体育的基础地位"],["D","德育与其他各育的关系"]]', '["A"]', '全面发展教育由德智体美劳五育构成，它们之间不是割裂的，而是相互渗透、相互促进的。该校将劳动教育融入各学科教学，体现了五育融合的理念——劳动教育不是孤立的课程，而是与其他各育有机结合，共同促进学生全面发展。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (576, 2, 36, 'single', 1.0, '初二语文课上，李老师讲《孔乙己》时问：孔乙己穿着长衫却站着喝酒，这个细节说明了什么？学生纷纷回答后，李老师追问：如果让你用一个词概括孔乙己的社会处境，你会用哪个词？学生的回答涉及了阶层、尴尬、边缘等。李老师的提问策略主要体现了（　）', '[["A","记忆性提问"],["B","理解性提问"],["C","分析性提问"],["D","评价性提问"]]', '["C"]', '分析性提问要求学生分解信息、找出各部分之间的关系、推断因果关系或进行分析归类。李老师先让学生理解细节含义（基础理解），再要求用一个词概括社会处境（分析综合），这需要学生分析人物处境、提取关键特征、进行概括归纳，属于分析性提问层次。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (577, 2, 37, 'single', 1.0, '某中学初二(3)班近期连续出现课间追逐打闹导致受伤的情况。班主任李老师决定召开主题班会，让同学们自己讨论制定课间行为规范，并选举安全监督员。这种做法体现了德育的（　）', '[["A","情感陶冶法"],["B","说服教育法"],["C","道德修养法"],["D","品德评价法"]]', '["C"]', '道德修养法（自我教育法）是学生在教师引导下自觉地进行自我反省、自我约束和自我完善的方法。李老师让学生自己讨论制定规范并选举监督员，调动了学生的主体性和自觉性，通过自我教育来实现行为改善。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (578, 2, 38, 'single', 1.0, '城区某初中在初一年级开设了一门跨学科课程，将物理、化学、生物中的相关内容整合为主题式学习单元。从课程类型看，这门课程属于（　）', '[["A","分科课程"],["B","隐性课程"],["C","活动课程"],["D","综合课程"]]', '["D"]', '综合课程是把有内在联系的不同学科内容合并在一起而形成的课程。该校将物理、化学、生物相关内容整合为主题式学习单元，打破了学科界限，将多门学科知识融合，属于综合课程。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (579, 2, 39, 'single', 1.0, '王老师在班级推行小组合作学习制度，每个小组4-6人，设有组长、记录员、发言人等角色，每周轮换。期中评比时，以小组平均成绩作为加分依据。这一制度设计中最能体现集体教育与个别教育相结合原则的是（　）', '[["A","角色轮换制度"],["B","小组人数限制"],["C","每周评比制度"],["D","小组平均成绩加分"]]', '["D"]', '集体教育与个别教育相结合原则（马卡连柯平行教育影响）要求通过集体来教育个人，又通过个人的教育来影响集体。以小组平均成绩作为加分依据，促使每位学生都要为集体做贡献，同时优等生会帮助后进生，形成集体影响个人、个人影响集体的良性互动。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (580, 2, 40, 'single', 1.0, '某校新来了一位校长，他发现学校教研活动流于形式，老师们各自为政。于是校长推行了年级学科备课组制度，每周固定时间集体备课、互相听课评课。从教育研究方法的角度看，校长推动的这种校本教研主要属于（　）', '[["A","行动研究法"],["B","观察法"],["C","调查法"],["D","实验法"]]', '["A"]', '行动研究法是教师针对教育实践中存在的问题，在实际工作中进行研究，边研究边行动，以改进教育实践的方法。集体备课、互相听课评课是典型的校本行动研究——教师围绕教学实际问题，在实践中研究、在研究中改进，目的是提高教学质量。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (581, 2, 41, 'single', 1.0, '李老师发现班上有几个学生经常课间欺负一个性格内向的同学。她分别找了这几个学生谈话：先肯定了他们在体育方面的特长，然后引导他们思考如果被欺负的人会是什么感受，最后安排他们和那个同学一起做运动会准备工作。李老师运用的德育原则是（　）', '[["A","导向性原则与教育影响一致性原则"],["B","长善救失与尊重学生、严格要求相结合"],["C","因材施教与知行统一原则"],["D","疏导原则与正面教育原则"]]', '["B"]', '李老师先肯定学生体育特长（依靠积极因素克服消极因素，即长善救失），再引导换位思考（尊重学生人格，不简单批评），最后安排合作任务（在尊重基础上提出行为改进要求，即严格要求）。整个过程体现了长善救失与尊重学生、严格要求相结合的原则。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (582, 2, 42, 'single', 1.0, '某校初二开设了校园记者站、机器人社团、辩论队等10多个社团，学生每周有2课时参与社团活动。从课外校外教育的角度看，这些社团活动的主要特点是（　）', '[["A","系统性、计划性、封闭性"],["B","自愿性、灵活性、多样性"],["C","学科性、基础性、普及性"],["D","强制性、统一性、标准化"]]', '["B"]', '课外校外教育是指在课程计划之外，由学校有组织或利用校外力量对学生实施的各种教育活动。其特点是自愿参加、形式灵活、内容丰富多样。校园记者站、机器人社团、辩论队等社团活动正体现了自愿性、灵活性和多样性。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (583, 2, 43, 'single', 1.0, '张老师在批改作业时发现，班上有一类学生总是机械地抄写例题格式，一旦题目变形就无从下手。从教学过程规律的角度分析，这类学生主要缺乏（　）', '[["A","理解教材的环节"],["B","运用知识的环节"],["C","感知教材的环节"],["D","巩固知识的环节"]]', '["A"]', '教学过程中理解教材是形成概念、掌握规律的关键环节。学生机械抄写例题格式、题目变形就无所适从，说明他们只停留在记忆表面形式，没有真正理解知识背后的原理和规律，即缺乏理解教材这一环节。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (584, 2, 44, 'single', 1.0, '城区某中学在教师考核中，将师德表现作为第一标准，实行师德一票否决制。这一做法的直接政策依据是（　）', '[["A","《中华人民共和国教师法》"],["B","《中小学教师职业道德规范》及师德考核相关文件"],["C","《中华人民共和国教育法》"],["D","《新时代中小学教师职业行为十项准则》"]]', '["B"]', '教育部印发的《关于建立健全中小学师德建设长效机制的意见》等文件明确规定，将师德表现作为教师考核、聘任和评价的首要内容，实行师德一票否决制。虽然《教师法》和《十项准则》都涉及师德，但师德一票否决制的直接政策依据是师德考核相关的专门文件。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (585, 2, 45, 'single', 1.0, '某校进行教学改革实验：在初二年级两个平行班中，甲班采用项目式学习（PBL），乙班维持传统教学。一学期后比较两班的综合能力测评成绩。这种研究方法的核心特征是（　）', '[["A","对个别对象进行长期追踪研究"],["B","通过问卷和访谈收集数据"],["C","在自然情境中进行参与式观察"],["D","控制无关变量、操纵自变量以考察因果关系"]]', '["D"]', '教育实验法的核心特征是控制无关变量、有目的地操纵自变量（教学方法），观察因变量（综合能力成绩）的变化，以揭示教育现象中的因果关系。该校在两个平行班中进行对比实验，甲班接受PBL处理、乙班为对照组，正体现了实验法的核心特征。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (586, 2, 46, 'single', 1.0, '初三年级面临中考压力，学校决定在每周三下午开设一节体育活动课。但部分家长认为这会挤占学习时间，向学校反映。校长回复：教育部明确规定中小学生每天校内体育活动时间不少于1小时，这也是全面发展教育的组成部分。校长的回复体现了对（　）的坚持。', '[["A","智育优先于体育的原则"],["B","应试教育的现实需要"],["C","五育并举、全面发展的教育方针"],["D","家长需求优先的原则"]]', '["C"]', '校长的回复体现了对五育并举、全面发展教育方针的坚持。体育是全面发展教育的重要组成部分，教育部对体育活动时间有明确规定。校长不因中考压力而取消体育课，说明其坚持德智体美劳全面发展的教育方针，不因应试而忽视体育。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (587, 2, 47, 'single', 1.0, '初一男生小明在做数学题时，总是先看课本例题再模仿做题，很少尝试用不同方法。老师鼓励他一题多解后，他开始主动探索多种解题思路。从学习策略的角度看，老师培养的是小明的（　）', '[["A","元认知策略"],["B","组织策略"],["C","复述策略"],["D","精加工策略"]]', '["D"]', '精加工策略是指通过对学习材料进行深入分析、推理、比较等方式，增加新信息的意义，促进理解和记忆。一题多解要求学生从不同角度分析问题、探索多种解题方法，这正是精加工策略的运用——深入加工信息、寻找多种联系。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (588, 2, 48, 'single', 1.0, '初二女生小雨参加学校演讲比赛前，心跳加速、手心出汗、大脑一片空白。心理辅导老师教她深呼吸放松法，并让她在模拟考试场景中反复练习演讲，逐渐降低焦虑反应。这种辅导方法属于（　）', '[["A","系统脱敏法"],["B","合理情绪疗法"],["C","自由联想法"],["D","厌恶疗法"]]', '["A"]', '系统脱敏法是通过逐步呈现引发焦虑的刺激，同时配合放松训练，使个体对刺激的焦虑反应逐渐减弱直至消除的方法。辅导老师让小雨在模拟考试场景中反复练习（逐步暴露于焦虑情境），同时配合深呼吸放松（对抗焦虑），正是系统脱敏法的典型运用。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (589, 2, 49, 'single', 1.0, '小杰在学习了哺乳动物的概念后，再学习鲸鱼是哺乳动物这个新知识。奥苏贝尔认为，这种学习属于（　）', '[["A","上位学习"],["B","下位学习"],["C","发现学习"],["D","并列结合学习"]]', '["B"]', '奥苏贝尔将有意义学习分为上位学习、下位学习和并列结合学习。下位学习（类属学习）是指新学习的知识是已有的上位概念的具体化或特例。小杰已掌握哺乳动物的概念（上位），再学习鲸鱼是哺乳动物（下位具体实例），属于下位学习。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (590, 2, 50, 'single', 1.0, '初三化学课上，张老师在讲解元素周期表时，让学生自己绘制周期表并标注元素性质规律。从信息加工的角度看，学生绘制周期表的过程主要运用了（　）', '[["A","资源管理策略"],["B","复述策略"],["C","精加工策略"],["D","组织策略"]]', '["D"]', '组织策略是对学习材料进行归类、整理，形成有序的知识结构。绘制元素周期表需要学生将零散的元素按照原子序数、性质规律进行有序排列和归类，形成系统化的知识结构，这正是组织策略的典型运用。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (591, 2, 51, 'single', 1.0, '小明在物理课上学了杠杆原理后，回家看到开门时门把手的位置设计，联想到杠杆原理。从迁移的角度看，这种现象属于（　）', '[["A","顺向负迁移"],["B","逆向负迁移"],["C","逆向正迁移"],["D","顺向正迁移"]]', '["D"]', '顺向迁移是指先前学习对后继学习的影响；逆向迁移是后继学习对先前学习的影响。正迁移是积极促进，负迁移是消极干扰。小明先学了杠杆原理（先前学习），再用它来理解门把手设计（后继学习），且产生了积极帮助，属于顺向正迁移。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (592, 2, 52, 'single', 1.0, '张老师发现班上有几个学生总是说“我太笨了，再怎么学也考不好”。从归因理论看，这些学生将失败归因于（　），这种归因容易导致习得性无助。', '[["A","任务太难"],["B","运气不好"],["C","能力不足"],["D","努力不够"]]', '["C"]', '韦纳归因理论中，能力属于内部、稳定、不可控因素。将失败归因于能力不足（我太笨了），会让学生觉得失败是不可改变的，从而丧失信心、放弃努力，导致习得性无助。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (593, 2, 53, 'single', 1.0, '初一女生小红性格内向，在班上很少与同学交流。班主任李老师观察发现，小红在美术课上画画时非常专注，作品也很有创意。李老师决定让小红负责班级黑板报的绘画部分。李老师的做法依据的是（　）', '[["A","埃里克森人格发展理论"],["B","最近发展区理论"],["C","加德纳多元智力理论"],["D","认知风格差异理论"]]', '["C"]', '加德纳多元智力理论认为人有多种智力，包括语言、逻辑数学、空间、音乐、身体运动、人际交往、内省、自然观察等。小红虽然内向（人际交往智力可能不突出），但在绘画方面表现出色（空间智力突出）。李老师让小红负责黑板报绘画，发挥了她的优势智力，体现了多元智力理论因材施教的思想。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (594, 2, 54, 'single', 1.0, '初三数学复习课上，张老师在讲完一道经典题型后，要求学生反复朗读解题步骤并默写关键公式，然后同桌互相检查背诵效果。从学习策略的角度看，这种反复朗读和默写的方法主要属于（　）', '[["A","精加工策略"],["B","复述策略"],["C","组织策略"],["D","元认知策略"]]', '["B"]', '复述策略是通过反复重复学习材料来保持记忆的策略，包括反复朗读、抄写、默写等。张老师让学生反复朗读解题步骤并默写关键公式，通过重复来巩固记忆，属于典型的复述策略。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (595, 2, 55, 'single', 1.0, '初二男生小晨原本对学习没有兴趣，但在一次科技比赛中获奖后，开始主动阅读科普书籍、参加创新实验。张老师认为这是激发小晨学习动机的好时机，便在班上表扬了他，并推荐他参加区级科技创新大赛。张老师运用的动机激发方法是（　）', '[["A","利用反馈信息"],["B","进行学习目的教育"],["C","创设问题情境"],["D","恰当运用奖励与竞争"]]', '["D"]', '张老师通过表扬（奖励）和推荐参加更高级别比赛（引入竞争机会）来激发小晨的学习动机。小晨在科技比赛中获奖获得了成就感，张老师的表扬进一步强化了这种积极体验，推荐参赛则引入了新的竞争目标。这属于恰当运用奖励与竞争来激发动机。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (596, 2, 56, 'single', 1.0, '初二英语课上，李老师讲解过去完成时时，先让学生回忆已经学过的过去式，再对比两者区别。从奥苏贝尔有意义学习的角度看，李老师的做法是为了（　）', '[["A","复习旧课以节省教学时间"],["B","降低教学难度以适应差生"],["C","增加学习材料的趣味性"],["D","激活学生认知结构中的相关旧知识作为锚点"]]', '["D"]', '奥苏贝尔认为有意义学习的关键是学习者认知结构中必须具有适当的起因定作用的观念（锚点）。李老师让学生先回忆过去式（激活已有知识），再与过去完成时对比（建立新旧知识联系），正是利用已有认知结构中的相关知识作为锚点，促进新知识的有意义学习。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (597, 2, 57, 'single', 1.0, '初三学生小雨在解一道几何综合题时，想了很久都没有思路。后来她放下题目去跑步，回来时突然想到了解题方法。这种现象在问题解决过程中属于（　）', '[["A","准备阶段"],["B","酝酿阶段"],["C","豁朗阶段"],["D","验证阶段"]]', '["C"]', '问题解决的心理过程分为四个阶段：准备阶段（发现问题、明确问题）、酝酿阶段（尝试各种方法但未解决）、豁朗阶段（也叫顿悟阶段，突然找到解决方法）、验证阶段（检验solution是否正确）。小雨放下题目后突然想到解法，属于豁朗阶段（顿悟）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (598, 2, 58, 'single', 1.0, '初二物理课上，张老师用吹风机向上吹乒乓球，球悬在空中不掉下来，让学生解释原因。学生纷纷用流体力学知识解释。从教学设计的角度看，张老师这个演示实验的主要目的是（　）', '[["A","创设问题情境，激发认知冲突"],["B","训练操作技能"],["C","验证实验结论"],["D","复习旧知识"]]', '["A"]', '张老师用吹风机吹乒乓球悬空的演示，制造了一个出乎学生直觉的现象（认知冲突），引发学生思考和探究欲望。从教学设计角度看，这是典型的创设问题情境——通过新奇现象激发学生的认知冲突和探究动机，为后续教学做好铺垫。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (599, 2, 59, 'single', 1.0, '初二女生小红原本对化学不感兴趣，但在一次实验课上看到镁条燃烧发出耀眼白光后，产生了强烈的好奇心，开始主动阅读化学科普书籍。从学习动机的分类看，小红这种动机属于（　）', '[["A","附属内驱力"],["B","认知内驱力"],["C","外部动机"],["D","自我提高内驱力"]]', '["B"]', '奥苏贝尔将学校情境中的成就动机分为认知内驱力、自我提高内驱力和附属内驱力。认知内驱力是指个体渴望获得知识、理解和掌握问题的需要，是一种内部动机。小红因对实验现象产生好奇心而主动阅读科普书籍，是出于对知识本身的兴趣和求知欲，属于认知内驱力。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (600, 2, 60, 'single', 1.0, '初三男生小明在班级里总是很活跃，但学习成绩一般。班主任发现他在组织班级活动时表现出很强的领导能力和协调能力。从加德纳的理论看，小明在（　）智力方面有优势。', '[["A","人际交往智力"],["B","语言智力"],["C","逻辑数学智力"],["D","内省智力"]]', '["A"]', '加德纳多元智力理论中，人际交往智力是指理解他人、与人有效交往的能力。小明虽然学习成绩一般（逻辑数学智力可能不突出），但在组织活动中表现出领导能力和协调能力，这正是人际交往智力的体现——善于理解他人需求、协调人际关系、有效组织团队。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (601, 2, 61, 'single', 1.0, '初二女生小雨在数学考试中遇到一道难题，想了很久做不出来，于是先跳过去做后面的题。最后又回来重新思考这道题，终于做出来了。从元认知策略的角度看，小雨的做法体现了（　）', '[["A","资源管理策略"],["B","调节策略"],["C","监控策略"],["D","计划策略"]]', '["B"]', '元认知策略包括计划、监控和调节策略。调节策略是指根据监控结果，对学习活动进行调整和修正。小雨在做不出难题时先跳过（调整做题顺序），最后再回来重新思考（根据时间情况进行调整），体现了根据监控结果对学习策略进行调整的调节策略。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (602, 2, 62, 'single', 1.0, '初三英语课上，李老师让学生分组完成一个项目：设计一份英文旅游指南。每个小组需要查阅资料、分工合作、制作海报并进行口头汇报。从建构主义的角度看，这种教学方式的核心理念是（　）', '[["A","教师是知识的传授者"],["B","学习是被动接受外部信息的过程"],["C","教学应以讲授为主、练习为辅"],["D","学生在真实情境中通过合作主动建构知识"]]', '["D"]', '建构主义强调学习是学习者在一定情境下借助他人帮助，通过意义建构获得的。李老师让学生分组完成真实项目（真实情境），需要查阅资料、分工合作（社会互动和协作），最终制作和汇报（主动建构），体现了建构主义以学生为中心、在真实情境中通过合作主动建构知识的核心理念。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (603, 2, 63, 'single', 1.0, '初二男生小杰在一次小组讨论中提出了一个与教材不同的观点，同学们纷纷反对。李老师没有直接否定，而是让小杰说明理由，然后引导全班讨论两种观点的优劣。李老师的做法有利于培养学生的（　）', '[["A","形象思维"],["B","创造性思维"],["C","直觉思维"],["D","聚合思维"]]', '["B"]', '创造性思维的特征包括流畅性、变通性和独特性。李老师鼓励小杰提出不同观点（独特性），引导全班讨论两种观点的优劣（多角度思考、变通性），这种教学方式有利于培养学生的发散思维和创造性思维。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (604, 2, 64, 'single', 1.0, '初三女生小红最近情绪低落，经常一个人发呆，成绩也明显下降。班主任张老师找她谈话得知，她父母最近在闹离婚，她觉得是自己不够好导致的。从心理辅导的角度看，张老师首先应该做的是（　）', '[["A","告诉她父母离婚与她无关，纠正其不合理认知"],["B","批评她父母不负责任"],["C","让她把精力转移到学习上"],["D","建议她转学到其他学校"]]', '["A"]', '小红认为父母离婚是自己不够好导致的，这是一种不合理认知（自我归因错误）。心理辅导首先要做的是帮助她认识到父母离婚是成年人的决定，与她无关，纠正这种不合理的自我归因。批评父母、转移注意力或转学都不能解决根本问题。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (605, 2, 65, 'single', 1.0, '初二男生小明在课堂上经常走神，李老师发现他在看窗外的鸟。李老师没有批评他，而是在讲生态平衡时特意请小明分享他观察到的鸟类行为。从此小明对生物课产生了浓厚兴趣。李老师的做法体现了课堂管理中的（　）', '[["A","替代活动策略"],["B","将问题行为转化为教学资源"],["C","惩罚策略"],["D","直接控制策略"]]', '["B"]', '李老师没有直接制止或批评小明的走神行为，而是巧妙地将他观察鸟类的行为与教学内容结合起来，请他分享观察经验，既尊重了学生的兴趣，又将问题行为转化为有价值的教学资源，还激发了他对生物课的兴趣。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (606, 2, 66, 'single', 1.0, '初三学生小雨发现，自己在安静环境中学习效率最高，而在嘈杂环境中容易分心。于是她选择每天在图书馆自习。从学习策略的分类看，小雨的做法属于（　）', '[["A","资源管理策略中的环境管理策略"],["B","元认知策略"],["C","精加工策略"],["D","认知策略"]]', '["A"]', '资源管理策略包括时间管理、环境管理、努力管理和学业求助等策略。小雨根据自己的学习特点选择安静的图书馆作为学习场所，是对学习环境的主动管理，属于资源管理策略中的环境管理策略。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (607, 2, 67, 'single', 1.0, '新任班主任小晨老师刚入职时，最关心的是学生是否喜欢自己、同事如何评价自己。从福勒的教师成长阶段理论看，小晨老师处于（　）', '[["A","关注自我阶段"],["B","关注情境阶段"],["C","关注学生阶段"],["D","关注生存阶段"]]', '["D"]', '福勒将教师成长分为三个阶段：关注生存阶段（关注自己能否被接纳、学生和同事的评价）、关注情境阶段（关注教学情境、如班级规模、时间压力等）、关注学生阶段（关注学生个体差异、因材施教）。小晨老师最关心学生是否喜欢自己、同事如何评价，属于典型的关注生存阶段。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (608, 2, 68, 'single', 1.0, '某中学初二学生小杰在课间与其他同学追逐打闹时，不慎将同桌小明的课桌碰倒，桌上的水杯砸到小明脚背造成软组织挫伤。事后查明当天值班老师因临时开会离开了10分钟。关于小明的伤害，应承担主要赔偿责任的是（　）', '[["A","值班老师和学校共同承担"],["B","学校"],["C","小杰的监护人"],["D","小明自己"]]', '["C"]', '根据《民法典》第1188条，无民事行为能力人、限制民事行为能力人造成他人损害的，由监护人承担侵权责任。小杰是直接侵权人，其监护人应承担主要赔偿责任。学校虽然值班老师离开10分钟存在一定管理疏漏，但直接致害行为是小杰造成的，主要责任在小杰的监护人。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (609, 2, 69, 'single', 1.0, '李老师因对学校给予的行政处分不服，拟依法提出申诉。依据《教师法》，其申诉的受理机关应当是（　）', '[["A","主管的教育行政部门"],["B","人民法院"],["C","当地人民政府"],["D","学校教职工代表大会"]]', '["A"]', '《教师法》第三十九条规定，教师对学校或者其他教育机构侵犯其合法权益的，或者对学校或者其他教育机构作出的处理不服的，可以向教育行政部门提出申诉。教育行政部门是教师申诉的法定受理机关。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (610, 2, 70, 'single', 1.0, '城区某中学拟采购一批教学设备，总金额超过政府规定的公开招标数额。学校决定采用竞争性谈判方式进行采购。依据相关法律，该采购行为应当遵循的基本原则是（　）', '[["A","优先选择价格最低的供应商"],["B","公开透明、公平竞争、公正和诚实信用"],["C","由校长个人决定供应商"],["D","学校自主决定即可"]]', '["B"]', '根据《政府采购法》及相关规定，政府采购应当遵循公开透明原则、公平竞争原则、公正原则和诚实信用原则。学校使用财政性资金采购教学设备超过规定数额的属于政府采购，必须遵循这些基本原则。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (611, 2, 71, 'single', 1.0, '初三班主任王老师在一次班级安全检查中，发现学生小杰的书包里有一把管制刀具。王老师应该采取的正确做法是（　）', '[["A","当场没收并严厉批评小杰"],["B","当作没看见，避免激化矛盾"],["C","收缴后及时报告学校并通知家长，必要时报告公安机关"],["D","让全班同学对小杰进行批评教育"]]', '["C"]', '根据《未成年人保护法》和《预防未成年人犯罪法》的相关规定，学校发现学生携带管制刀具等危险物品的，应当立即制止并收缴，同时报告学校、通知监护人，必要时应当报告公安机关。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (612, 2, 72, 'single', 1.0, '某中学在期中考试后将学生成绩排名公布在学校公告栏。家长认为此举侵犯了学生的合法权益。学校的做法主要侵犯了学生的（　）', '[["A","受教育权"],["B","财产权"],["C","隐私权"],["D","人格尊严权"]]', '["C"]', '学生成绩属于学生的个人信息，学校未经学生同意将其成绩公开展示，侵犯了学生的隐私权。根据教育部相关规定，学校不得公开学生考试成绩排名。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (613, 2, 73, 'single', 1.0, '初二学生小红在校期间突发急病，班主任李老师立即拨打120并通知家长，同时护送小红到医院。但医院诊断后认为学校食堂午餐存在卫生问题导致食物中毒。关于小红的医疗费用，下列说法正确的是（　）', '[["A","全部由学校承担"],["B","学校食堂如果确实存在卫生问题，学校应承担相应赔偿责任"],["C","由食堂承包商独立承担，学校不承担责任"],["D","全部由小红的家长承担"]]', '["B"]', '根据《学生伤害事故处理办法》和《侵权责任法》相关规定，学校提供的食品、药品等不符合国家标准或行业标准导致学生伤害的，学校应依法承担相应的赔偿责任。食堂是学校管理范围内的设施，如果学校食堂确实存在卫生问题，学校应当承担赔偿责任。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (614, 2, 74, 'single', 1.0, '张老师在课堂上发现学生小明在玩手机，遂将手机没收并摔碎。事后小明家长要求张老师赔偿。从法律角度分析，下列说法正确的是（　）', '[["A","张老师可以暂时保管手机，但无权损毁学生的个人财产"],["B","张老师可以自行处置学生手机"],["C","张老师有权没收手机，摔碎也合理"],["D","小明在课堂玩手机在先，损失自负"]]', '["A"]', '教师对课堂上使用手机的学生可以进行管理，有权暂时保管（没收）手机以维护课堂秩序。但手机属于学生的个人财产，教师无权损毁。根据《民法典》，故意损毁他人财物应当承担赔偿责任。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (615, 2, 75, 'single', 1.0, '某校学生在参加学校组织的校外实践活动中受伤，家长要求学校赔偿。学校辩称活动已经委托给旅行社组织，应由旅行社负责。依据相关法律，下列说法正确的是（　）', '[["A","学校已将活动委托旅行社，不承担任何责任"],["B","旅行社负全部责任"],["C","学校组织校外活动，即使委托第三方仍需承担管理职责"],["D","学生自己承担风险"]]', '["C"]', '学校组织校外活动，对学生负有安全教育和管理保护的职责。即使将部分活动委托给旅行社等第三方，学校仍不能免除对学生的安全管理职责。如果学校在组织过程中存在过错，仍应承担相应的法律责任。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (616, 2, 76, 'single', 1.0, '李老师因对学校将其年度考核定为不合格不服，先向学校提出申诉，学校维持原决定。李老师又向县教育局申诉，教育局维持了学校决定。李老师仍不服，可以采取的法律救济途径是（　）', '[["A","向人民法院提起民事诉讼"],["B","向市教育局再次申诉"],["C","通过媒体曝光施压"],["D","依法提起行政复议或行政诉讼"]]', '["D"]', '教师对学校处理决定和教育行政部门的申诉处理决定不服的，可以依法提起行政复议或行政诉讼。这是教师权利救济的法定途径。向市教育局再次申诉没有法律依据；民事诉讼适用于平等主体之间的民事纠纷；通过媒体曝光不是合法的法律救济途径。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (617, 2, 77, 'single', 1.0, '某中学初三学生小杰（15周岁）多次旷课去网吧，学校多次教育无效后，对其作出开除学籍的处分。小杰父母认为学校无权开除义务教育阶段的学生。依据《义务教育法》，下列说法正确的是（　）', '[["A","学校有权开除严重违纪的学生"],["B","经教育行政部门批准可以开除"],["C","义务教育阶段学校不得开除学生，但可给予其他处分"],["D","学校可以先开除再劝其转入其他学校"]]', '["C"]', '《义务教育法》第二十七条明确规定：对违反学校管理制度的学生，学校应当予以批评教育，不得开除。这是因为义务教育具有强制性，适龄儿童和少年必须接受义务教育，学校不得以任何理由剥夺学生接受义务教育的权利。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (618, 2, 78, 'single', 1.0, '张老师在教改中尝试让每个学生都有机会在课堂上展示自己的作品。她说：每个学生都有自己的闪光点，我们要善于发现并肯定他们。张老师的话体现了新课改评价理念中的（　）', '[["A","发展性评价"],["B","终结性评价"],["C","选拔性评价"],["D","甄别性评价"]]', '["A"]', '新课改倡导发展性评价理念，强调评价的目的是促进学生发展，而非甄别选拔。让每个学生展示作品、善于发现并肯定每个学生的闪光点，体现了发展性评价关注学生进步、鼓励每个学生发展的理念。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (619, 2, 79, 'single', 1.0, '城区某中学李老师从教15年，教学成绩一直优秀。他坚持每学期参加省级以上培训、阅读最新教育期刊、学习信息技术。他说：教师不能只靠经验吃饭，必须与时俱进。李老师的做法集中体现了教师职业道德中的（　）', '[["A","爱岗敬业"],["B","终身学习"],["C","为人师表"],["D","爱国守法"]]', '["B"]', '终身学习是教师专业发展的不竭动力，要求教师崇尚科学精神，树立终身学习理念，拓宽知识视野，更新知识结构。李老师坚持参加培训、阅读期刊、学习新技术体现了持续学习、与时俱进的专业追求。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (620, 2, 80, 'single', 1.0, '王老师在备课中注重将课程标准中的核心素养目标转化为具体的教学活动。她在教案中明确标注每个环节对应的素养维度。王老师的做法体现了新课程标准实施中的（　）', '[["A","课程标准可以灵活调整不必严格执行"],["B","教学活动应以教师讲授为中心"],["C","教学目标设计应从知识本位转向素养本位"],["D","核心素养只适用于高中阶段的课程"]]', '["C"]', '新课程标准强调核心素养导向，要求教学目标从知识本位转向素养本位，将核心素养的培养融入教学全过程。王老师在备课中将素养目标转化为具体教学活动并标注对应维度，正是落实素养本位教学目标设计的体现。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (621, 2, 81, 'multi', 1.6, '某校初二班主任王老师在处理学生之间的矛盾时，遵循了疏导原则。下列做法中，符合疏导原则要求的有（　）', '[["A","直接判定谁对谁错，要求道歉"],["B","引导学生换位思考，理解对方的感受"],["C","在全班公开批评犯错的学生以做效尤"],["D","先让双方分别陈述事情经过，耐心倾听"],["E","用事实和道理帮助学生认识问题"]]', '["B","D","E"]', '疏导原则（循循善诱原则）要求教师讲明道理、疏导思想，因势利导、以理服人。D耐心倾听是疏导的前提（了解事实），B引导换位思考是以理服人的方式，E用事实和道理帮助学生是疏导的核心。A直接判定对错不给学生自我认识的机会，C公开批评可能伤害学生自尊，均不符合疏导原则。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (622, 2, 82, 'multi', 1.6, '城区某优质初中推行课堂教学改革，要求教师在教学设计中体现启发性原则。下列教学行为中，体现启发性原则的有（　）', '[["A","王老师通过演示实验引发学生思考后再揭示原理"],["B","赵老师用苏格拉底式提问引导学生逐步推导出结论"],["C","刘老师让学生先预习教材，课上只做练习题"],["D","李老师直接告诉学生标准答案并要求背诵"],["E","张老师抛出开放性问题让学生分组讨论后再总结"]]', '["A","B","E"]', '启发性原则要求教师调动学生学习的主动性，引导他们独立思考、积极探索。E开放性问题+讨论+总结体现了引导学生主动思考；A演示实验引发思考再揭示原理体现了不愤不启；B苏格拉底式提问是启发式教学的经典方法。D直接告知答案并背诵违背启发性，C只做练习不讲启发也违背启发性。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (623, 2, 83, 'multi', 1.6, '初二男生小杰最近学习状态不佳，班主任李老师通过观察和分析，发现他存在学习动机不足的问题。李老师可以采取的激发学习动机的措施有（　）', '[["A","在全班排名中突出小杰的排名下降以激发紧迫感"],["B","引导小杰将失败归因于努力不够而非能力不足"],["C","为小杰提供具体的学习方法指导"],["D","帮助小杰发现学习与自身兴趣的关联"],["E","为小杰设置适当难度的学习目标，让他体验成功"]]', '["B","C","D","E"]', 'E设置适当目标体验成功符合自我效能感理论；B引导正确归因符合韦纳归因理论；D发现学习与兴趣关联属于内部动机激发；C学习方法指导可以增强学生的学业自信心。A在全班公开排名可能增加焦虑，且属于外部压力而非真正的动机激发，方式不当。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (624, 2, 84, 'multi', 1.6, '初三学生小雨在历史课上学习鸦片战争时，老师引导她联系之前学过的清朝闭关锁国政策和世界工业革命背景来理解战争爆发的必然性。这种教学方式涉及的迁移类型有（　）', '[["A","逆向迁移"],["B","一般迁移"],["C","具体迁移"],["D","顺向迁移"],["E","垂直迁移"]]', '["D","E"]', '先学的知识（闭关锁国政策、工业革命）影响后学的知识（鸦片战争），属于顺向迁移。从一般性背景知识（政策、革命）到具体历史事件（战争），属于从一般到具体的垂直迁移（纵向迁移）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (625, 2, 85, 'multi', 1.6, '城区某中学心理辅导室接待了一位因考试焦虑前来求助的初二女生小红。心理辅导老师可以采用的正确做法有（　）', '[["A","建立良好的辅导关系，营造安全的倾诉环境"],["B","强制要求小红参加更多模拟考试以适应考试"],["C","教给小红放松训练的方法以缓解紧张情绪"],["D","告诉小红考试焦虑是正常的，不需要处理"],["E","帮助小红识别导致焦虑的不合理信念"]]', '["A","C","E"]', 'A建立良好辅导关系是心理辅导的前提和基础；E识别不合理信念是认知行为辅导的关键步骤；C放松训练是缓解焦虑的有效技术。D忽视了考试焦虑对学生的负面影响，不处理可能导致问题加重；B强制模拟考试可能加重焦虑，违背心理辅导的自愿原则。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (626, 2, 86, 'multi', 1.6, '初二学生小杰在校期间的下列权利中，属于《未成年人保护法》明确规定的学校保护内容的有（　）', '[["A","对学校处分不服提出申诉"],["B","人格尊严不受侵犯"],["C","个人隐私不受非法查看"],["D","参加教育教学计划安排的各种活动"],["E","在课堂自由选择是否听课"]]', '["A","B","C","D"]', 'D参加教育教学活动是受教育权的内容；A提出申诉是学生的法定权利；B人格尊严不受侵犯是人身权的重要内容；C个人隐私不受非法查看是隐私权的保护内容。E在课堂自由选择是否听课不符合学生的义务——学生有遵守学校管理制度的义务。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (627, 2, 87, 'multi', 1.6, '某中学发生学生伤害事故后，学校在处理过程中应当遵循的原则有（　）', '[["A","立即通知受伤害学生的监护人"],["B","依法配合相关部门进行事故调查"],["C","根据过错程度承担相应责任"],["D","及时救助受伤害学生"],["E","隐瞒事故真相以保护学校声誉"]]', '["A","B","C","D"]', '根据《学生伤害事故处理办法》，学校在学生伤害事故发生后应当：及时救助受伤害学生（D）；通知受伤害学生的监护人（A）；依法配合事故调查（B）；根据过错程度承担相应责任（C）。E隐瞒事故真相是违法行为，违反了事故报告的法定义务，可能承担更严重的法律责任。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (628, 2, 88, 'multi', 1.6, '城区某中学在新教师入职培训中，校长特别强调了十项准则的核心要求。下列教师日常行为中，直接体现《新时代中小学教师职业行为十项准则》明确要求的有（　）', '[["A","发现学生行为异常时及时与家长沟通"],["B","在课堂上向学生传播中华优秀传统文化"],["C","公平对待每一位学生，不因成绩好坏区别对待"],["D","自觉抵制有偿补课，不接受家长礼品礼金"],["E","利用课余时间举办有偿补习班"]]', '["A","B","C","D"]', 'B符合传播优秀文化的要求；C符合秉持公平诚信的要求；A符合关心爱护学生、加强安全防范的要求；D符合坚守廉洁自律、规范从教行为的要求。E利用课余时间举办有偿补习班违反了十项准则中规范从教行为的规定，严禁有偿补课。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (629, 2, 89, 'multi', 1.6, '城区某中学在推进新课改过程中，要求教师转变教学观念。下列做法中，符合新课改教学观转变要求的有（　）', '[["A","提倡自主、合作、探究的学习方式"],["B","从重结论轻过程转向重结论的同时更重过程"],["C","教学应由关注学科转向关注人"],["D","从教育者为中心转向学习者为中心"],["E","教师应该教教材而非用教材教"]]', '["A","B","C","D"]', '新课改教学观的转变包括：从教育者为中心转向学习者为中心（D）；从重结论轻过程转向重结论更重过程（B）；从关注学科转向关注人（C）；提倡自主合作探究学习方式（A）。E说法错误，新课改要求教师是用教材教而非教教材。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (630, 2, 90, 'multi', 1.6, '2024年全国教育大会提出了建设教育强国的战略目标。关于教育强国的建设要求，下列说法正确的有（　）', '[["A","要坚持立德树人作为教育的根本任务"],["B","教育的三大属性是政治属性、人民属性和战略属性"],["C","要构建教育科技人才一体推进的体制机制"],["D","教育强国建设只需要扩大教育规模即可"],["E","建成教育强国是先导任务、坚实基础、战略支撑"]]', '["A","B","C","E"]', 'E正确，教育强国是先导任务、坚实基础、战略支撑；B正确，2024年教育大会提出三大属性；A正确，立德树人是教育根本任务；C正确，大会强调教育科技人才一体推进。D错误，教育强国建设不仅仅是扩大规模，更重要的是提高质量、优化结构、促进公平。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (631, 3, 1, 'judge', 0.6, '座谈时赵老师说：陶行知办晓庄学校主张“教学做合一”，今天带农村娃搞实践照样管用。', '[["A","正确"],["B","错误"]]', '["A"]', '陶行知是我国伟大的人民教育家，提出“生活即教育”“社会即学校”“教学做合一”等主张，强调教育与生产生活结合、在实践中学习。他的乡村教育思想对今天的农村学校开展实践教育仍有重要指导意义。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (632, 3, 2, 'judge', 0.6, '刘校长说：学生出校门不等于学习结束，学校要用闲置校舍办好家长学校和夜校。', '[["A","正确"],["B","错误"]]', '["A"]', '终身教育思想强调教育贯穿人的一生，不限于学校教育阶段，学校应向社会开放、为成人继续学习提供条件。刘校长引导师生树立终身学习观念并利用学校资源开展成人教育，符合终身教育思想。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (633, 3, 3, 'judge', 0.6, '产业园升级后政府出钱翻新机房，又发文规定学校办学方向。赵老师说：这些都由生产力决定。', '[["A","正确"],["B","错误"]]', '["B"]', '题干把两件事都归因于生产力，混淆了生产力与政治经济制度的不同作用：生产力发展主要为教育提供物质条件并制约人才规格与教育结构，机房换新体现的是生产力的物质基础作用；而决定教育领导权、教育目的与办学方向的是政治经济制度。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (634, 3, 4, 'judge', 0.6, '陈老师把九年级压轴大题给初一学生天天练，说这是遵循循序渐进原则。', '[["A","正确"],["B","错误"]]', '["B"]', '陈老师混淆了循序渐进原则与个体身心发展的阶段性规律。把九年级难题强加给初一学生，超出该年龄阶段的发展水平，属“一刀切”、违背阶段性；循序渐进强调按学科逻辑与认识顺序由浅入深。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (635, 3, 5, 'judge', 0.6, '陈老师在固定教室对全班按统一课表上课、留同样作业，这是个别教学制。', '[["A","正确"],["B","错误"]]', '["B"]', '按固定班级、固定课表对全班集体上课，是班级授课制，具有“班、课、时”的特点；个别教学制是教师对个别学生分别施教，无固定班级和统一课表。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (636, 3, 6, 'judge', 0.6, '刘老师说：任何教育活动都离不开教育者、受教育者和教育影响，三者缺一不可。', '[["A","正确"],["B","错误"]]', '["A"]', '教育活动的基本要素包括教育者、受教育者和教育影响（教育媒介，含教育内容与教育手段），三者相互联系、相互作用，缺一不可。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (637, 3, 7, 'judge', 0.6, '小磊插话遭训斥后反而更多，陈老师改在其安静时表扬。同事说：训斥是惩罚，表扬才是正强化。', '[["A","正确"],["B","错误"]]', '["B"]', '区分强化与惩罚要看行为概率的变化，不能只看刺激是愉快还是厌恶。厉声训斥呈现了刺激却使插话概率提高，对插话而言属于正强化而非惩罚；安静时受表扬使安静增多才是正强化。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (638, 3, 8, 'judge', 0.6, '子轩总考前突击，赵老师指导他初学后尽早、分次复习，并在刚能背诵后再适当追加练习。', '[["A","正确"],["B","错误"]]', '["A"]', '艾宾浩斯遗忘规律表明遗忘先快后慢，应及时、分散复习；在恰好能背诵后继续学习（过度学习，一般以 150% 左右为佳）可提高保持效果、减少遗忘。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (639, 3, 9, 'judge', 0.6, '小浩两次月考失利后说“我天生不是学数学的料”。陈老师说：归因为能力不足，会更激励他奋起直追。', '[["A","正确"],["B","错误"]]', '["B"]', '依据韦纳成败归因理论，能力是内部、稳定、不可控因素，把失败归因于能力容易产生习得性无助、降低后续努力程度，而不是激励其奋起直追。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (640, 3, 10, 'judge', 0.6, '梓涵不敢报名演讲赛，刘老师让她先在小组讲并肯定她，又让她看水平相近同学成功的视频。', '[["A","正确"],["B","错误"]]', '["A"]', '自我效能感由班杜拉提出，其影响因素包括个人自身成败经验、替代经验、言语劝说和情绪唤醒。刘老师让梓涵获得小组内成功经验、观看相似榜样成功、给予积极评价，从多方面提高其自我效能感。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (641, 3, 11, 'judge', 0.6, '一诺看到子轩帮同学值日受表扬，第二天便默默整理图书角。刘老师说：这是替代强化。', '[["A","正确"],["B","错误"]]', '["A"]', '班杜拉社会学习理论认为，个体可通过观察他人（榜样）的行为及其强化结果而习得新行为，即替代强化。一诺观察到子轩助人受表扬后表现出同类行为，正是观察学习与替代强化的体现。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (642, 3, 12, 'judge', 0.6, '小磊原以为“会飞的都是鸟”，在城郊湿地看到蝙蝠后把它也归入会飞的鸟。刘老师说这属于顺应。', '[["A","正确"],["B","错误"]]', '["B"]', '小磊没有改变“会飞的都是鸟”这一原有认知结构，而是把蝙蝠强行纳入原有图式，属于同化；顺应应是修改原有认识、承认会飞的不一定是鸟。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (643, 3, 13, 'judge', 0.6, '陈老师说：学生先学“直角”“锐角”再学“角”，概括水平相同，这属于水平迁移。', '[["A","正确"],["B","错误"]]', '["B"]', '“角”是一般概念，“直角”“锐角”是其从属概念，二者抽象概括水平不同，它们之间的迁移属于垂直（纵向）迁移；水平迁移发生在概括水平相同的经验之间。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (644, 3, 14, 'judge', 0.6, '小婷做英语阅读时先看题目再读文章，没读懂就重读。赵老师说：这属于复述策略。', '[["A","正确"],["B","错误"]]', '["B"]', '读前安排方法、读中监控理解、不懂时回读调节，是对自身认知过程的计划、监控与调节，属于元认知策略；复述策略是为保持信息而对材料进行重复识记。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (645, 3, 15, 'judge', 0.6, '自习课上，子轩见同学都安静做题、班干部投来提醒目光，便不再讲话。这主要是任务促成的纪律。', '[["A","正确"],["B","错误"]]', '["B"]', '子轩是因同辈集体的学习氛围、舆论和班干部提醒的压力而守纪，属于集体促成的纪律；任务促成的纪律是由某一特定任务的要求所促成。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (646, 3, 16, 'judge', 0.6, '陈老师近来总觉精疲力竭，对学生提问懒得回应，还怀疑当老师的意义。刘校长说这是职业倦怠。', '[["A","正确"],["B","错误"]]', '["A"]', '职业倦怠是个体在长期工作压力下产生的情绪耗竭、去人性化（对服务对象冷漠）和个人成就感低落的综合症状。陈老师的表现符合其主要特征。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (647, 3, 17, 'judge', 0.6, '刘老师提醒外甥：想当中小学老师，光有大学毕业证不够，须先依法取得教师资格。', '[["A","正确"],["B","错误"]]', '["A"]', '我国实行教师资格制度，中国公民在各级各类学校和其他教育机构中专门从事教育教学工作，应当依法取得教师资格。大学毕业证不能替代教师资格。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (648, 3, 18, 'judge', 0.6, '小磊数学只考42分，陈老师令其在教室后站整节课，还在他额头贴“笨”字条。这侵犯了人格尊严。', '[["A","正确"],["B","错误"]]', '["A"]', '人格尊严权是公民的基本权利，《义务教育法》明确禁止体罚、变相体罚及其他侮辱人格尊严的行为。罚站整节课属变相体罚，贴“笨”字纸条属侮辱人格。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (649, 3, 19, 'judge', 0.6, '陈老师说：“我只要课讲得好，春游护导都是行政的事，与我无关。”刘老师说这是他的正当权利。', '[["A","正确"],["B","错误"]]', '["B"]', '《教师法》规定，教师有义务制止有害于学生的行为，在教育教学活动中保障学生安全，该义务面向全体教师，并非只是行政人员职责。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (650, 3, 20, 'judge', 0.6, '周末父亲骑电动车带小浩闯红灯被汽车撞伤。赵老师对家长说：学生出了校外事故，学校也要担主要责任。', '[["A","正确"],["B","错误"]]', '["B"]', '依据《学生伤害事故处理办法》，节假日等学校工作时间以外、学生由监护人带领发生的事故，学校行为并无不当的不承担责任。本案损害由家长违规造成、学校无过错。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (651, 3, 21, 'judge', 0.6, '陈老师在班会上当众朗读小婷日记里的家庭矛盾，还拍照发家长群。刘老师说：为教育目的这不侵犯隐私。', '[["A","正确"],["B","错误"]]', '["B"]', '未成年人的日记属于个人隐私，未经本人或监护人同意不得擅自披露、宣扬；即便出于教育目的，公开宣读并拍照扩散仍构成对隐私权的侵犯。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (652, 3, 22, 'judge', 0.6, '从教二十年的刘老师仍参加信息技术培训，学用思维导图辅助教学，说不能只靠老教案。', '[["A","正确"],["B","错误"]]', '["A"]', '《中小学教师职业道德规范》要求教师“终身学习”，树立优良学风，不断更新知识结构、潜心钻研业务。刘老师主动学习新技术、改进教学，体现了终身学习的要求。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (653, 3, 23, 'judge', 0.6, '降温天陈老师见梓涵穿得单薄发抖，把自家孩子的外套给她披上，还记下尺码说改天再送棉衣。', '[["A","正确"],["B","错误"]]', '["A"]', '“关爱学生”是师德的灵魂，要求教师关心爱护全体学生，尊重学生人格，对学生严慈相济。陈老师体察学生冷暖、主动给予帮助，体现了对学生的关爱。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (654, 3, 24, 'judge', 0.6, '赵老师要求学生不说脏话、不乱扔垃圾，自己谈吐文明，看到走廊纸屑也弯腰捡起。', '[["A","正确"],["B","错误"]]', '["A"]', '“为人师表”是教师职业的内在要求，教师要以身作则、言传身教，以高尚人格为学生树立榜样。赵老师要求学生做到的自己先做到，体现了为人师表。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (655, 3, 25, 'judge', 0.6, '教师节一诺家长给陈老师发来1000元转账，陈老师欣然收下，说这是家长的正常心意。', '[["A","正确"],["B","错误"]]', '["B"]', '《中小学教师职业道德规范》和《新时代中小学教师职业行为十项准则》要求教师廉洁从教，不得收受学生及家长财物。陈老师收下转账违背廉洁自律要求。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (656, 3, 26, 'judge', 0.6, '小赵每天转两趟班车赶到城郊学校，几年从未迟到缺课，还利用午休义务补差。这体现爱岗敬业。', '[["A","正确"],["B","错误"]]', '["A"]', '爱岗敬业是教师职业的本质要求，要求教师忠诚教育事业、勤恳敬业、乐于奉献，对工作高度负责。小赵克服通勤困难、坚守岗位并主动补差，体现了爱岗敬业。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (657, 3, 27, 'judge', 0.6, '同事转发未经证实的涉校谣言说“转着玩没事”，小赵也跟着转发，认为业余网络言行不受准则约束。', '[["A","正确"],["B","错误"]]', '["B"]', '《新时代中小学教师职业行为十项准则》要求教师自觉爱国守法，不得通过网络等渠道转发错误观点或违法不良信息，教师的网络言行同样受准则约束。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (658, 3, 28, 'judge', 0.6, '学生父母离异、情绪低落，陈老师主动关心、安排同伴互助，联系家长疏导，且不在班上声张其隐私。', '[["A","正确"],["B","错误"]]', '["A"]', '关爱学生要求教师关心爱护全体学生，尊重学生人格，保护学生隐私，对学生严慈相济。陈老师关注学生情绪、保护隐私并协调家校力量，正体现关爱学生。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (659, 3, 29, 'judge', 0.6, '赵老师承诺“进步五名以上寒假作业减半”，还让德育活动停课让给考试科目。这符合教书育人要求。', '[["A","正确"],["B","错误"]]', '["B"]', '教书育人要求教师实施素质教育、培养学生良好品行、促进学生全面发展，不以分数作为评价学生的唯一标准。赵老师挤占德育活动、唯分数导向，恰恰违背教书育人。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (660, 3, 30, 'judge', 0.6, '小磊总说“脑子笨、再努力也没用”，受挫后连会做的题也不愿试。赵老师说这会持续损害其动机、认知和情绪。', '[["A","正确"],["B","错误"]]', '["A"]', '习得性无助指个体在反复经历失败与不可控情境后，形成无论怎样努力都无法改变结果的信念，进而表现出动机降低、认知障碍和情绪失调，甚至逃避原本能完成的任务。小磊的表现符合习得性无助。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (661, 3, 31, 'single', 1.0, '陈老师讲生物课时，先带学生到学校蔬菜基地观察叶片、采集标本，再回到课堂讲光合作用。这种把直接经验与间接经验结合的做法，主要遵循的教学原则是（　）', '[["A","因材施教原则"],["B","直观性原则"],["C","巩固性原则"],["D","量力性原则"]]', '["B"]', '直观性原则要求通过学生观察所学事物或教师语言的形象描述，使学生获得丰富感性认识，从而理解书本知识。陈老师先带学生实地观察、再讲理论，主要体现直观性原则。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (662, 3, 32, 'single', 1.0, '赵老师给学生讲“因材施教”时举例：孔子对冉求和子路问的同一个问题“闻斯行诸”，给出了截然不同的回答——让冉求“闻斯行之”，却劝子路“有父兄在，如之何其闻斯行之”。孔子这样做主要依据的是学生（　）', '[["A","家庭出身不同"],["B","性格特点不同"],["C","年龄大小不同"],["D","智力高低不同"]]', '["B"]', '冉求性格退缩，孔子鼓励他进取；子路性格莽撞好胜，孔子让他谨慎、多问父兄。同一问题相反回答，依据的是两人性格（气质、行为倾向）不同，是因材施教的经典范例。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (663, 3, 33, 'single', 1.0, '刘老师带学生学完“压强”后，布置他们回家调查家中菜刀磨刃、图钉按压等现象并尝试解释。这一教学环节最能体现的教学原则是（　）', '[["A","理论联系实际原则"],["B","循序渐进原则"],["C","巩固性原则"],["D","启发性原则"]]', '["A"]', '理论联系实际原则要求教学以学习基础知识为主导，从理论与实际的联系中理解知识、运用知识分析解决问题。刘老师让学生用压强原理解释生活用具中的现象，最能体现理论联系实际原则。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (664, 3, 34, 'single', 1.0, '陈老师给八年级上课，讲解语法点时发现大部分学生一脸茫然，立即放慢节奏，换了几个贴近校园生活的例句重新讲解，确认多数学生点头后再往下推进。陈老师这一做法最能体现（　）', '[["A","导向性原则"],["B","直观性原则"],["C","巩固性原则"],["D","量力性原则"]]', '["D"]', '量力性原则（可接受性原则）指教学的内容、方法、分量和进度要适合学生的身心发展水平，使学生能够接受，同时有一定难度、需要经过努力才能掌握。陈老师根据学生实际反应调整进度和讲法，最能体现量力性原则。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (665, 3, 35, 'single', 1.0, '学校要求科任教师每节课用三五分钟回顾上节要点，单元结束安排整理复习。赵老师解释说：“学过的东西不及时回头，很快就会生疏。”这些要求主要贯彻的教学原则是（　）', '[["A","启发性原则"],["B","因材施教原则"],["C","循序渐进原则"],["D","巩固性原则"]]', '["D"]', '巩固性原则要求教学引导学生在理解的基础上牢固掌握知识和技能，长久保持，需要时能准确再现。课前提要、单元复习旨在及时巩固、防止遗忘，主要体现巩固性原则。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (666, 3, 36, 'single', 1.0, '陈老师上《背影》时，从字词到段落、再到全篇主旨逐层推进，要求学生每一步过关后再进入下一步。这一安排主要遵循的教学原则是（　）', '[["A","循序渐进原则"],["B","理论联系实际原则"],["C","启发性原则"],["D","巩固性原则"]]', '["A"]', '循序渐进原则（系统性原则）要求按学科逻辑系统和学生认识发展顺序进行教学，由浅入深、由易到难、由简到繁。陈老师由字词到段落再到主旨逐层推进，主要体现循序渐进原则。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (667, 3, 37, 'single', 1.0, '刘老师在历史课上讲“科技是第一生产力”，同时介绍两弹一星元勋隐姓埋名、报效祖国的事迹，学生深受感染。这一教学安排主要体现了（　）', '[["A","量力性原则"],["B","科学性与思想性相统一原则"],["C","因材施教原则"],["D","启发性原则"]]', '["B"]', '科学性与思想性（教育性）相统一原则要求在传授科学知识的同时，结合知识内在的思想因素对学生进行思想品德教育。刘老师讲知识又讲科学家报国事迹，最能体现该原则。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (668, 3, 38, 'single', 1.0, '赵老师在教学中运用演示法，把实物、教具展示给学生看。下列做法中，符合演示法运用要求的是（　）', '[["A","教具越多越好，全程堆满讲台"],["B","演示结束直接下课，不与讲授结合"],["C","学生自己看即可，教师无需讲解"],["D","让学生明确观察目的，引导其抓住关键特征"]]', '["D"]', '运用演示法要做好演示前准备，使学生明确演示目的、要求与过程；演示中引导学生综合运用各种感官全面、细致观察，抓住主要特征并及时讲解，演示后与讲授谈话结合归纳。其余三项均违背演示法规范。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (669, 3, 39, 'single', 1.0, '城郊中学提出“让每一个学生在原有基础上都得到发展，不以分数排名作为评价学生的唯一尺度”，还为基础薄弱学生开辅导课、为有特长的学生搭建展示平台。这一办学追求最能体现（　）', '[["A","终身教育"],["B","应试教育"],["C","精英教育"],["D","素质教育"]]', '["D"]', '素质教育以提高国民素质为根本宗旨，面向全体学生，促进学生全面发展与主动发展，注重创新精神和实践能力，不以分数作为评价学生的唯一标准。该校做法最能体现素质教育。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (670, 3, 40, 'single', 1.0, '班里一名学生基础差、习惯差，同事劝刘老师“别在他身上费工夫”。刘老师却说：“每个孩子都有被好好教育的权利，我不能放弃任何一个。”她坚持长期跟进，该生逐渐转变。刘老师的认识和做法集中体现了（　）', '[["A","教育应按成绩区别对待"],["B","教育以升学率为中心"],["C","教育要面向全体学生"],["D","教育主要面向优等生"]]', '["C"]', '素质教育面向全体学生，依法保障适龄儿童少年接受教育的权利，尊重每个学生，努力开发每个学生的特长和潜能，反对只重视少数尖子生、放弃后进生。刘老师不放弃任何一个学生，集中体现面向全体。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (671, 3, 41, 'single', 1.0, '陈老师的课表从早排到晚，白天上课、批改，晚上还要回复家长消息、处理班级突发情况，工作很难用八小时框定。这主要体现了教师劳动的（　）', '[["A","创造性"],["B","长期性"],["C","间接性"],["D","连续性和广延性"]]', '["D"]', '教师劳动的连续性指时间上没有严格的上下班界限，广延性指空间上没有限定的劳动场所，校内校外、课内课外都要进行教育工作。陈老师从早到晚、家校两头忙碌，主要体现连续性与广延性。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (672, 3, 42, 'single', 1.0, '刘老师真心关爱学生，学生也愿意亲近她、信任她，课堂气氛融洽。这种师生关系类型主要属于（　）', '[["A","民主型"],["B","专制型"],["C","对立型"],["D","放任型"]]', '["A"]', '民主型师生关系中，教师热爱、尊重、信任学生，学生尊敬教师、乐于接受指导，师生关系融洽、课堂气氛活跃。刘老师与学生相互尊重亲近，属于民主型。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (673, 3, 43, 'single', 1.0, '关于“教学”这一概念，下列理解正确的是（　）', '[["A","教学与智育是完全等同的概念"],["B","教学是在教育目的规范下，教师教与学生学共同组成的双边活动"],["C","教学专指课堂上的讲授活动"],["D","教学就是教师单向传授知识的活动"]]', '["B"]', '教学是在教育目的规范下、由教师的教与学生的学共同组成的一种双边教育活动，是学校进行全面发展的基本途径。它不是教师单向活动，不限于课堂讲授，与智育既有联系又有区别，不能等同。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (674, 3, 44, 'single', 1.0, '德国教育家赫尔巴特提出“我想不到有任何无教学的教育，正如相反方面，我不承认有任何无教育的教学”。这句话集中揭示了教学过程具有（　）', '[["A","直接经验与间接经验相统一的规律"],["B","教学永远具有教育性的规律"],["C","教师主导与学生主体相统一的规律"],["D","掌握知识与发展能力相统一的规律"]]', '["B"]', '赫尔巴特首次明确提出“教育性教学”原则，指出教学总要服务于一定的思想品德教育，传授知识与思想教育相统一。题干名言集中揭示了教学的教育性规律。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (675, 3, 45, 'single', 1.0, '赵老师通过“饿猫开迷笼”实验向学生说明学习的过程。该实验的提出者认为，学习的实质是（　）', '[["A","情境与反应之间形成联结"],["B","形成认知结构"],["C","顿悟关系"],["D","建构意义"]]', '["A"]', '桑代克通过饿猫开迷笼实验提出试误说，认为学习的实质是经过试误在刺激（情境）与反应之间形成联结，联结是通过反复尝试错误而建立的。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (676, 3, 46, 'single', 1.0, '刘老师上课时，对认真听讲、积极发言的学生及时给予肯定，对干扰课堂的行为不随意“接茬”强化。她运用的学习理论主要是（　）', '[["A","认知结构学习理论"],["B","经典条件作用理论"],["C","完形一顿悟说"],["D","操作性条件作用理论"]]', '["D"]', '斯金纳操作性条件作用理论强调用强化塑造期望行为、用消退（不予强化）减少不良行为。刘老师及时肯定好行为、不强化干扰行为，主要运用该理论。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (677, 3, 47, 'single', 1.0, '陈老师鼓励学生像小科学家一样，自己动手操作、提出假设并检验，而不是直接把结论告诉学生。这一教学主张主要体现了（　）', '[["A","布鲁纳的认知结构学习理论"],["B","学生的行为主义观点"],["C","桑代克的试误说"],["D","巴甫洛夫的条件作用理论"]]', '["A"]', '布鲁纳提倡发现学习，主张让学生独立思考、提出假设、亲自探索，主动发现知识结构和原理，教师不直接呈现结论。陈老师的做法主要体现布鲁纳的理论。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (678, 3, 48, 'single', 1.0, '刘老师课堂上善于营造真诚、接纳的氛围，鼓励学生根据自己的兴趣选择学习内容、对自己的学习负责。这主要体现了（　）', '[["A","行为主义学习理论"],["B","罗杰斯的人本主义学习理论"],["C","建构主义学习理论"],["D","认知主义学习理论"]]', '["B"]', '罗杰斯人本主义学习理论主张以学生为中心，教师作为学习的促进者，提供真诚、无条件积极关注和同理心的氛围，让学生自由学习、自我实现。刘老师的做法主要体现人本主义。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (679, 3, 49, 'single', 1.0, '陈老师让学生分组围绕真实问题讨论，允许不同见解，重视学生在原有经验基础上生成理解。这主要体现了（　）', '[["A","形式训练说"],["B","建构主义学习理论"],["C","试误说"],["D","经典条件作用理论"]]', '["B"]', '建构主义强调学习的主动建构性、社会互动性和情境性，认为学生在原有经验基础上，通过协作对话在真实情境中建构意义。陈老师组织小组围绕真实问题讨论、尊重不同理解，主要体现建构主义。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (680, 3, 50, 'single', 1.0, '子轩为弄懂一道难题，主动查阅资料、反复演算，解出后特别有成就感。促使他这样做的内部动力，在心理学上称为（　）', '[["A","学习策略"],["B","学习习惯"],["C","学习迁移"],["D","学习动机"]]', '["D"]', '学习动机是引发和维持个体学习活动、并将学习活动指向一定学习目标的动力机制，包括学习需要和学习期待。子轩主动钻研、坚持解题的内部动力即学习动机。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (681, 3, 51, 'single', 1.0, '一诺这次没考好，她说：“这次没考好是因为我复习方法不对、练习量不够，调整后下次能进步。”按照韦纳归因理论，她的归因因素主要属于（　）', '[["A","内部、稳定、不可控"],["B","外部、稳定、不可控"],["C","内部、不稳定、可控"],["D","外部、不稳定、不可控"]]', '["C"]', '韦纳把成败归因分为能力、努力、任务难度、运气等因素。一诺归因于方法和练习（努力及可调整的方法），努力属内部、不稳定、可控因素。这种归因有利于激发后续学习。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (682, 3, 52, 'single', 1.0, '陈老师让学生先学骑自行车、再学骑电动车，发现学生学得很快，因为平衡和操控经验可以用上。这种学习间的相互影响称为（　）', '[["A","学习动机"],["B","学习焦虑"],["C","学习迁移"],["D","学习定势"]]', '["C"]', '学习迁移也称训练迁移，指一种学习对另一种学习的影响，或习得经验对完成其他活动的影响。骑自行车的平衡操控经验促进学骑电动车，属于学习迁移。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (683, 3, 53, 'single', 1.0, '赵老师向学生介绍迁移理论时说：“有理论认为，只要官能通过训练得到发展，迁移就会自动发生。”这一理论是（　）', '[["A","共同要素说"],["B","关系转换说"],["C","概括化理论"],["D","形式训练说"]]', '["D"]', '形式训练说以官能心理学为基础，认为心理官能经训练得到提高后可无条件迁移到其他学习中去，迁移是自动发生的。题干所述正是形式训练说。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (684, 3, 54, 'single', 1.0, '小婷复习时把一课中零散的知识点按内在联系列成提纲、画出结构图。她运用的学习策略主要是（　）', '[["A","组织策略"],["B","资源管理策略"],["C","复述策略"],["D","精加工策略"]]', '["A"]', '组织策略是整合所学新知识之间、新旧知识之间的内在联系，形成新的知识结构，如列提纲、画结构图、归类等。小婷列提纲、画结构图，主要运用组织策略。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (685, 3, 55, 'single', 1.0, '赵老师问学生“纸除了写字还能做什么”，有学生说“当尺子、做漏斗、折扇子、吸水”，还有学生把纸揉成团当填充物。能迅速说出纸的多种非常规用途，主要反映了思维的（　）', '[["A","流畅性"],["B","深刻性"],["C","变通性"],["D","独创性"]]', '["C"]', '创造性思维的特征包括流畅性（数量多）、变通性（灵活性，能跨越不同类别）、独创性（新奇独特）。学生能跨越书写、工具、吸水、填充等不同功能类别，主要反映变通性。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (686, 3, 56, 'single', 1.0, '刘老师参加工作后，始终自觉拥护国家教育方针，依法履行教师职责，在课堂和网络上都注意自己的言行，不发表、转发违背国家法律和政策的言论。刘老师的上述表现主要体现了教师职业道德规范中的（　）', '[["A","爱岗敬业"],["B","关爱学生"],["C","终身学习"],["D","爱国守法"]]', '["D"]', '爱国守法是教师职业的基本要求，要求教师热爱祖国、热爱人民，拥护党的领导和社会主义制度，全面贯彻国家教育方针，自觉遵守教育法律法规，依法履行教师职责权利。刘老师依法履职、规范言行，主要体现爱国守法。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (687, 3, 57, 'single', 1.0, '陈老师给学生制定学习目标时使用“识记、理解、运用、分析”等表述来描述预期学习结果。这套认知领域教育目标分类的提出者是（　）', '[["A","布卢姆"],["B","加涅"],["C","奥苏贝尔"],["D","布鲁纳"]]', '["A"]', '布卢姆等人将教育目标分为认知、情感、动作技能三大领域，认知领域由低到高分为识记（知识）、领会、运用、分析、综合、评价。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (688, 3, 58, 'single', 1.0, '陈老师发现：先学汉语拼音的学生初学英语字母时常读混，而熟练掌握英语字母后再看拼音偶尔也会“串味”。对这两种现象，下列分析正确的是（　）', '[["A","前者是逆向负迁移，后者是顺向正迁移"],["B","两者都是顺向正迁移"],["C","两者都是垂直正迁移"],["D","前者是顺向负迁移，后者是逆向负迁移"]]', '["D"]', '先前学习对后继学习的影响为顺向迁移，反之为逆向迁移；起干扰作用为负迁移。先学拼音干扰后学字母，是顺向负迁移；后学字母又反过来影响已学拼音，是逆向负迁移。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (689, 3, 59, 'single', 1.0, '小磊练习投篮，起初动作僵硬、顺手不顾脚；反复练习后动作逐渐协调；到比赛时已能在防守干扰下稳定命中。下列对其技能发展的分析，正确的是（　）', '[["A","依次经历了操作熟练、操作整合、操作模仿阶段"],["B","依次经历了操作模仿、操作整合、操作熟练阶段"],["C","三个阶段之间界限分明、不可逾越"],["D","依次经历了操作定向、操作整合、操作熟练阶段"]]', '["B"]', '操作技能形成包括操作定向、操作模仿、操作整合、操作熟练四个阶段。题干描述了从模仿时动作顾此失彼、到整合后协调、再到熟练后稳定应变的过程，体现模仿—整合—熟练；各阶段并非截然分开。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (690, 3, 60, 'single', 1.0, '实验课上，老师给每组一根蜡烛、一盒图钉、一盒火柴，要求把蜡烛固定在墙上且蜡油不滴到桌面。多数学生想不到装图钉的盒子本身可作为烛台底座。学生受阻的主要心理因素是（　）', '[["A","正迁移"],["B","功能固着"],["C","创造性想象"],["D","原型启发"]]', '["B"]', '功能固着指个体只看到事物的惯常功能，而看不到它可能具有的其他功能。学生只把图钉盒看作“容器”，想不到它可充当固定蜡烛的底座，正是功能固着的表现。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (691, 3, 61, 'single', 1.0, '面对吵闹的课堂，赵老师没有高声压制，而是先表扬安静学习的小组，再停顿片刻环视全班，等教室安静后才继续讲课，课后再单独找带头讲话的学生了解原因。对其做法的分析，正确的是（　）', '[["A","表扬安静小组对讲话者构成替代强化，停顿环视是在运用非言语线索提示"],["B","高声训斥才是唯一有效的课堂管理方式"],["C","该做法只重预防，没有体现问题行为的矫正"],["D","课后找学生谈话会削弱纪律的严肃性，不应采用"]]', '["A"]', '教师表扬守纪小组，使违纪学生观察到守纪行为受肯定，属替代强化；停顿、环视属于最小干预的非言语提示；课后谈话则是在查明原因后矫正问题行为。赵老师综合运用预防、提示与矫正。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (692, 3, 62, 'single', 1.0, '同样面对学生答错问题，刘老师想“他答错说明我刚才没讲透，我换个讲法再试试”，随后调整教学；陈老师想“这学生就是笨、不认真”，便让其站着听讲。下列分析正确的是（　）', '[["A","刘老师具有较高的个人教学效能感，陈老师的归因易导致消极期待"],["B","两位老师的教学效能感相同，对学生的影响也相同"],["C","陈老师的做法能更有效地促进学生进步"],["D","教师的归因方式与学生发展没有关系"]]', '["A"]', '个人教学效能感高的教师相信自己能教好学生，倾向从自身教学找原因并调整策略；把失败简单归于学生“笨”，会形成消极教师期望，伤害学生自尊。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (693, 3, 63, 'single', 1.0, '赵老师尝试让学生自主管理课堂：先由师生共同讨论制定课堂规则，再让学生轮流担任“值日班长”记录并提醒违纪情况，课后依规则自我小结。一学期后，班上违纪现象明显减少。这一变化主要说明（　）', '[["A","课堂纪律只能依靠学生自发形成"],["B","规则一旦制定就不再需要教师引导"],["C","学生把外部规则逐步内化为自我约束，自我促成的纪律得到发展"],["D","教师放弃了课堂管理的全部责任"]]', '["C"]', '自我促成的纪律（自律）是个体将外部纪律要求内化为自觉行为准则后形成的，是课堂纪律管理的最终目标。学生参与立规、轮流管理、依规则自省，体现了从教师、集体促成的纪律向自我促成的纪律发展。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (694, 3, 64, 'single', 1.0, '某乡镇企业以“赞助费”名义向辖区内初中收取费用，学校拒绝并上报。按照《义务教育法》，实施义务教育（　）', '[["A","不收学费、杂费"],["B","由学校自定收费标准"],["C","可向家长收取教育附加费"],["D","可以按学期收取学费"]]', '["A"]', '《义务教育法》明确规定，国家实行九年义务教育制度，义务教育是国家必须予以保障的公益性事业，实施义务教育不收学费、杂费。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (695, 3, 65, 'single', 1.0, '刘老师正常开展课堂教学改革，却被学校以“不服从安排”为由停课。刘老师认为自己依法开展教育教学、进行教学实验的权利受到侵犯。教师的这一权利是（　）', '[["A","学术研究权"],["B","民主管理权"],["C","教育教学权"],["D","指导评价权"]]', '["C"]', '《教师法》规定教师享有进行教育教学活动、开展教育教学改革和实验的权利，即教育教学权；学术研究权侧重科研学术活动，指导评价权侧重评定学生，民主管理权侧重参与学校管理。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (696, 3, 66, 'single', 1.0, '体育课上，体育老师按教学规范讲解动作并组织练习，学生小磊在老师转身指导他人时，故意违反动作要领打闹，致同学受伤。对学校责任的认定，下列说法正确的是（　）', '[["A","学校已尽教育管理职责且无不当，不承担事故责任"],["B","学校应承担全部赔偿责任"],["C","体育老师个人应承担全部责任"],["D","学校与受伤学生平均分担损失"]]', '["A"]', '根据《学生伤害事故处理办法》，学生或者其监护人有过错、学校已履行相应职责且行为并无不当的，学校不承担法律责任。本案老师依规教学，损害系小磊故意违规打闹造成，学校不承担事故责任。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (697, 3, 67, 'single', 1.0, '学校门卫管理松散，校外人员混入校园将学生一诺打伤后逃逸，无力全额赔偿。经查，学校在安全管理上明显存在疏漏。对一诺所受损害，下列说法正确的是（　）', '[["A","学校应承担全部责任"],["B","由学生自行承担损失"],["C","学校没有任何责任"],["D","由直接侵权人承担责任，学校承担相应的补充责任"]]', '["D"]', '无民事行为能力人或限制民事行为能力人在学校受到校外第三人人身损害，由第三人承担侵权责任；学校未尽到管理职责的，承担相应的补充责任。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (698, 3, 68, 'single', 1.0, '赵老师对学校扣发其绩效工资不服，与学校协商不成。他依法维护自身权益，最先可向（　）提出申诉。', '[["A","人民检察院"],["B","人民法院"],["C","教育行政部门"],["D","公安机关"]]', '["C"]', '《教师法》规定，教师对学校或者其他教育机构侵犯其合法权益，或者对处理不服的，可以向教育行政部门提出申诉，教育行政部门应在接到申诉的三十日内作出处理。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (699, 3, 69, 'single', 1.0, '陈老师在教学中既传授知识，又注重培养学生良好品行和学习习惯，还根据学生特点引导其全面发展。这主要体现了教师职业道德规范中的（　）', '[["A","爱国守法"],["B","教书育人"],["C","关爱学生"],["D","为人师表"]]', '["B"]', '教书育人是教师的天职，要求遵循教育规律、实施素质教育，循循善诱、诲人不倦、因材施教，培养学生良好品行、激发创新精神、促进全面发展。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (700, 3, 70, 'single', 1.0, '赵老师过去把自己定位为“知识的唯一讲授者”，新课改后她更多地设计学习活动、组织合作探究、为学生答疑引路。她的角色转变方向是（　）', '[["A","由课程的建设者转变为课程的旁观者"],["B","从学生学习的促进者退化为课堂的控制者"],["C","由知识的传授者转变为学生学习的促进者和引导者"],["D","由教学的研究者转变为教材的执行者"]]', '["C"]', '新课改教师观要求教师从知识传授者转变为学生学习的促进者、引导者，成为教育教学的研究者、课程的建设者和开发者、社区型开放教师。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (701, 3, 71, 'single', 1.0, '刘老师刚接手七年级（3）班时，学生彼此陌生，对班级事务多持观望态度，班级活动主要靠他逐项安排。一段时间后，学生在共同筹备运动会中逐渐热络，开始出现几个热心同学主动帮他组织。按班集体形成的一般过程，该班当前最可能处于（　）', '[["A","核心初步形成阶段"],["B","发展阶段"],["C","成熟阶段"],["D","组建阶段"]]', '["A"]', '班集体形成一般经历组建、核心初步形成、发展、成熟等阶段。组建阶段学生彼此陌生、班级靠班主任管理；在共同活动中涌现积极分子并形成班级骨干，标志进入核心初步形成阶段。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (702, 3, 72, 'single', 1.0, '赵老师为“激励后进”，把班上几名学生的测验成绩及排名发到了家长群，还在办公室翻看学生暂存的日记并将内容转述给其他老师。对赵老师行为的评价，正确的是（　）', '[["A","只要是为了提高成绩，教师可随意公开学生信息"],["B","方式欠妥，但目的正当，不构成侵权"],["C","学生在学校没有隐私可言"],["D","公开成绩排名、宣扬日记内容，可能侵犯学生的隐私权等人格权益"]]', '["D"]', '未成年人享有隐私权等人格权利，其个人信息和私人活动受法律保护。公开学生成绩排名、擅自翻看并宣扬日记内容，可能侵犯学生隐私权及人格尊严，教师应采用适当方式反馈学业情况。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (703, 3, 73, 'single', 1.0, '法治学习课上列举三种情形：某校长挪用寄宿生生活补助被判处有期徒刑；某教师体罚学生被给予行政处分；某学校违法向学生收取费用被责令退还。三种情形对应的法律责任依次主要是（　）', '[["A","行政责任、民事责任、刑事责任"],["B","民事责任、刑事责任、行政责任"],["C","刑事责任、行政责任、行政责任"],["D","刑事责任、民事责任、追究责任"]]', '["C"]', '教育法律责任主要有行政责任、民事责任和刑事责任。判处有期徒刑属刑罚，对应刑事责任；行政处分、责令退还违法收费均属行政责任范畴。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (704, 3, 74, 'single', 1.0, '刘老师接手“问题班”后，没有急于抓成绩，而是先与学生共同讨论“我们想拥有一个怎样的班”，确立了班级目标；接着在运动会、值周等活动中培养骨干、健全组织，又引导大家把共识写成班规并坚持执行，班级风气逐步好转。刘老师建设班集体的上述做法中，贯穿始终、具有导向和推动作用的首要环节是（　）', '[["A","增加课外作业数量"],["B","建立严格的考试排名制度"],["C","由教师包办班级一切事务"],["D","确立班集体的共同奋斗目标"]]', '["D"]', '培养良好班集体的措施包括：确立共同奋斗目标、建立班集体核心与组织、建立健全规章制度、组织多样教育活动、培养正确舆论与良好班风。其中共同目标是班集体形成的条件和前进的动力，具有导向作用，是首要环节。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (705, 3, 75, 'single', 1.0, '陈老师发现小浩最近作业潦草、上课走神，经了解是父母在外打工、他随祖父母生活，家中缺少学习督促。陈老师没有简单批评，而是先肯定他想学好的愿望，再帮他制定可操作的每日计划并安排同伴互助。一段时间后小浩状态好转。陈老师这一做法主要利用了（　）', '[["A","教师期望效应"],["B","单纯的外部惩罚"],["C","罗森塔尔效应中教师的积极期待与支持"],["D","机械的重复训练"]]', '["C"]', '教师期望效应（罗森塔尔效应/皮格马利翁效应）指教师的积极期望会通过态度、行为传递给学生，促使学生朝期望方向发展。陈老师相信小浩、给予具体支持与正向期待，使学生状态改善。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (706, 3, 76, 'single', 1.0, '赵老师讲“最近发展区”时举例：小婷独立完成几何证明有些吃力，但在同学提示和老师追问下能够完成。赵老师据此安排教学时，最恰当的做法是（　）', '[["A","直接按最高难度教学，要求其独立完成"],["B","在其独立水平与经帮助可达到的水平之间设置“跳一跳够得着”的任务，并适时提供支架"],["C","放弃要求，等其自行成熟"],["D","只教她已经完全掌握的内容"]]', '["B"]', '维果斯基提出最近发展区，即儿童现有发展水平（独立完成任务）与潜在发展水平（在成人或同伴帮助下完成任务）之间的差距。教学应着眼最近发展区，提供适度帮助（“支架”），走在发展前面。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (707, 3, 77, 'single', 1.0, '刘老师注意到：小婷习惯先整体通读、把握框架后再细看细节；小浩则喜欢逐项抠知识点、按部就班地学。两人方法不同，却都能取得好成绩。这种学习者在加工信息时表现出的习惯性偏好属于（　）', '[["A","性格的善恶差异"],["B","智力水平差异"],["C","认知方式（认知风格）差异"],["D","气质类型的高低之分"]]', '["C"]', '认知风格（认知方式）指个体在感知、记忆、思维等认知活动中偏爱的信息加工方式，如场独立型与场依存型、沉思型与冲动型、整体型与序列型等，主要反映加工方式偏好，无好坏之分。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (708, 3, 78, 'single', 1.0, '备课检查时，教导主任发现陈老师的教案除了知识点与技能要求，还写明了学生要经历的探究过程、要形成的态度与价值判断。陈老师解释：“备一节课，不能只盯着要记住什么。”这种备课思路体现了新课程的（　）', '[["A","三维目标：知识与技能、过程与方法、情感态度与价值观"],["B","只重知识记忆的单一目标"],["C","以甄别选拔为核心的目标"],["D","取消知识要求的目标"]]', '["A"]', '新课程改革倡导三维目标，即知识与技能、过程与方法、情感态度与价值观的统一，强调学生在获得知识的同时学会学习、形成积极情感与正确价值观。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (709, 3, 79, 'single', 1.0, '城郊初中根据章程自主设置校内组织机构、聘任教师并实施奖励或处分，同时对本校设施和经费依法进行管理使用。学校依法享有的这些权利，在法律性质上属于（　）', '[["A","学校作为法人或法律授权主体依法享有的办学自主权"],["B","不受任何法律约束的自由"],["C","校长个人的任意处分权"],["D","师生个人的财产权"]]', '["A"]', '《教育法》规定学校及其他教育机构有权按照章程自主管理，组织实施教育教学活动，招收学生，对受教育者进行学籍管理、奖励或处分，聘任教师及其他职工并实施奖励处分，管理和使用本单位设施与经费等。这些权利属于学校依法享有的办学自主权。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (710, 3, 80, 'single', 1.0, '学校组织师德演讲，赵老师在发言中说：“教师的威信，不靠声色俱厉，而靠自身品德、学识和言行赢得学生发自内心的敬重。”这强调的是教师职业道德中的（　）', '[["A","敷衍塞责"],["B","有偿补课"],["C","只重分数"],["D","为人师表、以身作则"]]', '["D"]', '为人师表是教师职业的内在要求，教师要以身作则、言传身教，以高尚人格、真才实学和文明言行影响学生，从而赢得学生尊重。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (711, 3, 81, 'multi', 1.6, '赵老师带学生做数学探究题时发现，同一道题有的组很快找到思路、有的组卡壳很久。影响学生问题解决的主要因素有（　）', '[["A","已有的知识经验"],["B","原型启发"],["C","定势与功能固着"],["D","问题情境（问题的呈现方式）"],["E","情绪与动机状态（情绪越紧张、动机越强，解题效果必然越好）"]]', '["A","B","C","D"]', '影响问题解决的因素主要有问题情境、定势与功能固着、原型启发、已有知识经验、情绪动机状态及个体智力性格等。E前半正确、后半错误：过度紧张和过强动机反而降低解题效率，动机强度与效率呈倒U型关系。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (712, 3, 82, 'multi', 1.6, '针对班里学习动力不足的情况，陈老师想科学地激发学生的学习动机。下列做法恰当的有（　）', '[["A","频繁按分数公开排名，用羞辱和攀比逼迫学生努力"],["B","正确指导学生对成败结果进行归因"],["C","创设有启发性的问题情境，实施启发式教学"],["D","妥善、适度地进行奖励与批评"],["E","根据作业难度，适当控制学生的动机激起水平"]]', '["B","C","D","E"]', '激发学习动机可通过创设问题情境、正确归因训练、妥善奖惩、根据作业难度控制动机水平、维护自我效能感等。A项以排名羞辱施压，损害自尊和内部动机，做法错误。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (713, 3, 83, 'multi', 1.6, '新教师小刘向赵老师请教：“要完成好一学期的教学工作，具体要抓好哪几个基本环节？”赵老师的下列回答中，属于教学工作基本环节的有（　）', '[["A","学生升学与就业指导"],["B","作业的布置与批改"],["C","课外辅导"],["D","备好课"],["E","上好课"]]', '["B","C","D","E"]', '教师教学工作报告五个基本环节：备课、上课、作业的布置与批改、课外辅导、学业成绩的检查与评定。A项升学就业指导不属于教学工作基本环节。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (714, 3, 84, 'multi', 1.6, '小浩头脑聪明但爱冲动，常为“讲义气”跟同学起冲突，还违反纪律。赵老师处理时的下列做法中，符合德育要求的有（　）', '[["A","在全班同学面前翻出他以前犯过的所有错误进行羞辱"],["B","与他约法三章，明确规矩，违反了按约定承担责任"],["C","把他叫到办公室罚站一上午，不许他解释事情经过"],["D","指出他讲义气、敢担当的优点，引导他把这份担当用在帮助同学上"],["E","先耐心听他把事情经过说完，再因势利导讲清道理"]]', '["B","D","E"]', 'D体现依靠积极因素克服消极因素（长善救失）；E先倾听、再引导，体现疏导原则，尊重学生；B把正面引导与规则约束结合，符合尊重学生与严格要求相结合。C罚站不许申辩、A翻旧账羞辱，违背疏导、尊重学生和人格尊严要求。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (715, 3, 85, 'multi', 1.6, '刘老师接手一个松散班级，想把它建设成良好班集体。她需要着手做好的工作有（　）', '[["A","选拔和培养班干部、积极分子，建立班集体核心队伍"],["B","组织多种多样的班级活动，增强集体凝聚力"],["C","培养正确的集体舆论和良好的班风"],["D","提出共同的奋斗目标"],["E","用高压手段压制一切不同意见"]]', '["A","B","C","D"]', '培养良好班集体要：确定共同奋斗目标、建立得力的班集体核心、建立班集体正常秩序、组织形式多样的教育活动、培养正确舆论和良好班风。E高压压制违背民主管理，错误。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (716, 3, 86, 'multi', 1.6, '赵老师向学生宣讲受教育权。下列内容中，属于学生受教育权的有（　）', '[["A","对学校给予的处分不服，向有关部门提出申诉"],["B","自行决定中途辍学，随时放弃接受义务教育"],["C","按照国家有关规定获得奖学金、贷学金、助学金"],["D","在学业成绩和品行上获得公正评价，完成规定学业后获得相应的学业证书"],["E","参加教育教学计划安排的各种活动，使用教育教学设施、设备、图书资料"]]', '["A","C","D","E"]', '《教育法》规定受教育者享有参加教学活动并使用教育资源、获得奖贷助学金、获得公正评价与学业证书、申诉起诉等权利。B项错误：接受义务教育既是权利也是法定义务，不得随意辍学。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (717, 3, 87, 'multi', 1.6, '学校开展安全隐患排查与案例学习。根据《学生伤害事故处理办法》，下列情形中，学校应当依法承担相应责任的有（　）', '[["A","学校校舍、场地存在明显不安全因素，未及时维修或未设警示标志"],["B","学校组织学生参加活动，未进行相应安全教育或未采取必要安全措施"],["C","教师体罚或变相体罚学生，或在工作中擅离岗位"],["D","学生有特异体质、特定疾病，学校不知道且难于知道"],["E","学生自杀、自伤，学校已履行相应职责、行为并无不当"]]', '["A","B","C"]', '学校有过错（未尽教育、管理、保护职责）造成事故的应担责：A属设施不安全，C属教师违法、失职，B属组织活动未尽安全义务。D、E两种情形学校并无过错，依法不承担事故责任。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (718, 3, 88, 'multi', 1.6, '城郊初中在依法办学自查中，对照《教育法》梳理学校应当履行的义务。下列属于学校及其他教育机构应当履行义务的有（　）', '[["A","拒绝任何形式的监督，自行决定一切事务"],["B","维护受教育者、教师及其他职工的合法权益"],["C","以适当方式为受教育者及其监护人了解学业成绩及其他有关情况提供便利"],["D","遵守法律、法规"],["E","贯彻国家教育方针，执行国家教育教学标准，保证教育教学质量"]]', '["B","C","D","E"]', '《教育法》规定学校及其他教育机构应履行：遵守法律法规；贯彻国家教育方针、执行国家教育教学标准、保证教育教学质量；维护受教育者、教师及其他职工合法权益；以适当方式为受教育者及其监护人了解学业成绩等提供便利；遵照规定收取费用并公开收费项目；依法接受监督等。A拒绝监督违法。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (719, 3, 89, 'multi', 1.6, '赵老师把一节课的目标写成：学生能说出光合作用的原料和产物，能解释各条件的作用，能运用原理分析增产措施，并尝试设计简单的对照实验。从布卢姆认知领域教育目标分类看，这组目标涉及的层次有（　）', '[["A","分析"],["B","运用"],["C","领会（理解）"],["D","仅停留在机械记忆"],["E","知识（识记）"]]', '["A","B","C","E"]', '布卢姆将认知领域目标由低到高分为知识、领会、运用、分析、综合、评价。“说出原料产物”属知识，“解释作用”属领会，“运用原理分析增产”属运用，“设计对照实验”涉及分析乃至综合。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (720, 3, 90, 'multi', 1.6, '复习“技能的学习”时，刘老师结合学生书写、实验操作等训练总结规律。下列关于操作技能形成与练习规律的表述，正确的有（　）', '[["A","技能一经形成便不会出现任何退步"],["B","练习成绩总的趋势是进步，但会存在起伏波动"],["C","动作的熟练依赖反复练习，与反馈和示范无关"],["D","练习初期成绩进步通常较快，之后可能出现成绩暂时停顿的“高原现象”"],["E","适当的分散练习往往优于连续的集中练习"]]', '["B","D","E"]', '操作技能的练习曲线表明：总趋势是进步、但存在起伏，初期进步快，中期可能出现“高原现象”；合理安排练习（分散练习常优于集中练习）、提供准确示范与及时反馈，有助于技能形成。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (721, 4, 1, 'judge', 0.6, '备课组争论时，周老师提出：“办学校、设课程都是有了人以后才有的事，一旦人类消失，教育也就无从谈起。”', '[["A","正确"],["B","错误"]]', '["A"]', '周老师的说法点明了教育的永恒性：教育是人类社会特有的现象，与人类社会共始终，人类社会存在教育就存在，人类社会消亡教育才随之消失。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (722, 4, 2, 'judge', 0.6, '郑老师在家长会上说：“孩子有没有出息，学校这几年的教育最关键，家里怎么养、自己肯不肯努力都在其次。”', '[["A","正确"],["B","错误"]]', '["B"]', '人的发展受遗传、环境（含家庭）、学校教育和个体主观能动性共同制约，学校教育在其中起主导作用而非唯一决定作用。郑老师片面夸大学校教育、忽视家庭环境和学生主观能动性。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (723, 4, 3, 'judge', 0.6, '吴老师教汉语拼音时，先让学生认单韵母，再学声母，最后才练习音节拼读，从不一开始就让学生直接拼读句子。', '[["A","正确"],["B","错误"]]', '["A"]', '吴老师由简到繁、由易到难安排教学内容，符合个体身心发展的顺序性规律。教育必须循序渐进，不能“揠苗助长”、一步到位。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (724, 4, 4, 'judge', 0.6, '学校讨论提质方案，郑老师主张：“要办让人民满意的教育，就得集中资源抓少数尖子生的成绩，这才叫高质量。”', '[["A","正确"],["B","错误"]]', '["B"]', '素质教育是面向全体学生、促进学生全面发展和主动发展的教育，以提高国民素质为根本宗旨。只抓少数尖子生、放弃多数学生，违背了素质教育面向全体学生的基本内涵。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (725, 4, 5, 'judge', 0.6, '周老师的语文课常常要把没批改完的作业本带回家，晚上继续批改、写评语，第二天一早再带回学校发给学生。', '[["A","正确"],["B","错误"]]', '["A"]', '周老师的做法体现了教师劳动的连续性（时间上没有严格的上下班界限）和广延性（空间上校内外均为劳动场所）。教师劳动没有明确的时间和空间界限。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (726, 4, 6, 'judge', 0.6, '吴老师认为：“一个班几十名学生按统一课表、统一进度上课，能高效地大面积培养学生，这是班级授课制最突出的优点。”', '[["A","正确"],["B","错误"]]', '["A"]', '班级授课制把学生按年龄和程度编成固定班级，按统一课表和进度分科上课，有利于经济有效地大面积培养人才、扩大教学规模、提高教学效率，这是其突出优点。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (727, 4, 7, 'judge', 0.6, '阳阳爱劳动却爱上课讲话，周老师设“值日小岗位”扬其所长，再引导他改掉讲话的毛病。', '[["A","正确"],["B","错误"]]', '["A"]', '长善救失原则要求教育者善于依靠、发扬学生自身的积极因素（爱劳动、有责任心），调动其自我教育的积极性，克服消极因素（上课讲话）。周老师的做法正体现了这一原则。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (728, 4, 8, 'judge', 0.6, '郑老师教育学生时总说：“道理你们不必多问，照着我说的做就行。”他很少给学生摆事实、讲道理的机会。', '[["A","正确"],["B","错误"]]', '["B"]', '郑老师违背了德育的疏导原则。疏导原则要求循循善诱、以理服人，通过摆事实、讲道理，提高学生思想认识，反对简单压制、以力服人。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (729, 4, 9, 'judge', 0.6, '吴老师在班上说：“我是班主任，班规班纪我说了算，同学们只要服从管理，不必参与讨论。”', '[["A","正确"],["B","错误"]]', '["B"]', '班级管理应实行民主管理，尊重学生的主体地位，调动学生参与班级建设的积极性，让学生在参与中学会自我教育、自我管理。班主任一言堂、只要求服从，违背了班级民主管理的要求。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (730, 4, 10, 'judge', 0.6, '一年级朵朵觉得，随风转动的小风车“知道”自己在给大家表演，还会偷偷开心。', '[["A","正确"],["B","错误"]]', '["A"]', '朵朵处于皮亚杰所说的前运算阶段，这一阶段儿童具有泛灵论（万物有灵）特点，认为外界一切事物都是有生命、有意识、有情感的。她觉得风车有知有觉，正是泛灵论的表现。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (731, 4, 11, 'judge', 0.6, '三年级乐乐转学后怕交不到朋友，周老师安排他与热心同桌结对、加入兴趣小组，帮他融入集体、建立勤奋自信。', '[["A","正确"],["B","错误"]]', '["A"]', '小学阶段儿童处于埃里克森人格发展理论的“勤奋感对自卑感”阶段，同伴接纳和在集体中获得胜任感十分重要。周老师帮助乐乐融入集体、获得归属与自信，有利于其形成勤奋感、避免自卑感。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (732, 4, 12, 'judge', 0.6, '郑老师把橡皮泥捏成细长条，问朵朵哪份多，她回答：“长长的这份多！”', '[["A","正确"],["B","错误"]]', '["A"]', '朵朵处于皮亚杰所说的前运算阶段，尚未获得守恒概念，不能认识到物体形状改变后总量不变，只根据长度等单一维度作出判断，表现为不守恒。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (733, 4, 13, 'judge', 0.6, '豆豆每次看见同桌主动帮同学捡文具被老师表扬，自己也学着主动帮助别人。周老师说这是他通过观察榜样习得的行为。', '[["A","正确"],["B","错误"]]', '["A"]', '豆豆的表现符合班杜拉社会学习理论（观察学习理论）：个体可以通过观察他人（榜样）的行为及其结果（受到表扬这一替代强化）而习得新行为，不必事事亲身尝试。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (734, 4, 14, 'judge', 0.6, '糖糖解出一道难题后特别开心，觉得自己很能干。郑老师在学习动机分析表上，把这份“解出难题的成就感”归为外部学习动机。', '[["A","正确"],["B","错误"]]', '["B"]', '由学习活动本身带来的兴趣、成就感、求知欲等属于内部学习动机；外部学习动机指向学习活动之外的诱因，如奖励、分数、表扬等。糖糖因解出难题获得的成就感源于学习本身，应属内部动机。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (735, 4, 15, 'judge', 0.6, '欣欣先学了汉语拼音，再读英语单词时常把英文字母读成拼音，比如把“b”读成“玻”。', '[["A","正确"],["B","错误"]]', '["A"]', '欣欣先前学习的汉语拼音干扰、阻碍了她对英语字母读音的学习，属于学习迁移中的负迁移（一种学习对另一种学习产生消极影响、造成混淆）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (736, 4, 16, 'judge', 0.6, '阳阳背课文总是当天读得滚瓜烂熟，过两天就忘得差不多。吴老师提醒他：遗忘往往先快后慢，学完后要及时、分散地复习。', '[["A","正确"],["B","错误"]]', '["A"]', '艾宾浩斯遗忘规律表明，遗忘在学习之后立即开始，且进程不均衡，呈现先快后慢、先多后少的特点。吴老师据此提醒学生及时复习、分散复习。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (737, 4, 17, 'judge', 0.6, '豆豆读课外书时，遇到不认识的“蝴蝶”两个字，会先跳过去继续读，读完一段再回头根据插图和上下文猜意思。', '[["A","正确"],["B","错误"]]', '["A"]', '豆豆在阅读中根据阅读进程和理解情况，自觉调整阅读方法（先跳过、再借助插图和上下文推测词义），这是对自身认知活动的监控与调节，属于元认知策略。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (738, 4, 18, 'judge', 0.6, '糖糖判断行为好坏主要看会不会挨罚，郑老师却说她处于科尔伯格所说的后习俗水平。', '[["A","正确"],["B","错误"]]', '["B"]', '以是否受到惩罚、是否服从权威来判断行为好坏，属于科尔伯格道德发展阶段理论中前习俗水平的惩罚与服从定向阶段，而非后习俗水平（后习俗水平以普遍伦理原则、社会契约等为判断标准）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (739, 4, 19, 'judge', 0.6, '吴老师在讲教育法时告诉学生：“国务院制定的教育行政法规，效力高于全国人大常委会制定的教育法律。”', '[["A","正确"],["B","错误"]]', '["B"]', '在我国教育法的效力层级中，宪法具有最高法律效力，其次是全国人大及其常委会制定的教育法律，再次才是国务院制定的教育行政法规。行政法规不得与法律相抵触，吴老师颠倒了二者的效力层级。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (740, 4, 20, 'judge', 0.6, '按规定，适龄儿童、少年原则上在户籍所在地学校就近免试入学，地方不得设置任何形式的入学考试来挑选学生。', '[["A","正确"],["B","错误"]]', '["A"]', '《义务教育法》规定，适龄儿童、少年免试入学，地方各级人民政府应当保障其在户籍所在地学校就近入学。学校和有关部门不得采取考试、测试等方式选拔学生。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (741, 4, 21, 'judge', 0.6, '周老师工作后想参加教育局组织的骨干教师脱产研修，但校长以教学任务重为由不批准。周老师认为校长侵犯了自己的法定权利。', '[["A","正确"],["B","错误"]]', '["A"]', '《教师法》规定教师享有参加进修或者其他方式培训的权利。校长无正当理由一概不批准教师参加业务研修，侵犯了教师的进修培训权，周老师的主张有法律依据。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (742, 4, 22, 'judge', 0.6, '郑老师为“激励”学生，未经家长同意，就把朵朵写的检讨书和家庭情况记录拍照发到了班级家长群里。', '[["A","正确"],["B","错误"]]', '["B"]', '未成年人的个人隐私和个人信息受法律保护，任何组织和个人不得披露。检讨书和家庭情况涉及朵朵的隐私，郑老师未经监护人同意公之于众，侵犯了学生的隐私权和个人信息权益。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (743, 4, 23, 'judge', 0.6, '学生不听劝阻擅自攀爬围墙摔伤，吴老师却说：“只要在校园里受的伤，学校无论有无过错都得全赔。”', '[["A","正确"],["B","错误"]]', '["B"]', '学生伤害事故适用过错责任原则，学校尽到教育、管理职责且无过错的，不承担或不全部承担责任；学生或监护人有过错的，由其承担相应责任。吴老师“无论有无过错都全赔”的说法没有法律依据。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (744, 4, 24, 'judge', 0.6, '周老师对学校作出的记过处分不服，他可以依照《教师法》的规定，向教育行政部门提出申诉。', '[["A","正确"],["B","错误"]]', '["A"]', '《教师法》规定，教师对学校或者其他教育机构侵犯其合法权益，或者对其作出的处理不服的，可以向教育行政部门提出申诉，教育行政部门应在法定期限内作出处理。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (745, 4, 25, 'judge', 0.6, '乐乐生病落下功课，情绪低落，吴老师利用午休耐心给他补课，还鼓励他慢慢来、不要着急。', '[["A","正确"],["B","错误"]]', '["A"]', '吴老师关心爱护学生、保护学生身心健康，对学生严慈相济，体现了《中小学教师职业道德规范》（2008）中“关爱学生”的要求。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (746, 4, 26, 'judge', 0.6, '郑老师在自己家里组织班上学生进行有偿补课，按课时收费。他认为“在校外、在自己家里补，不算违规”。', '[["A","正确"],["B","错误"]]', '["B"]', '《新时代中小学教师职业行为十项准则》和师德规范明确禁止教师组织、参与有偿补课，或在校外培训机构兼职兼薪，不论地点是否在校内、是否在自己家中。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (747, 4, 27, 'judge', 0.6, '吴老师坚持认为：“学生是正在成长、还不成熟的人，犯错在所难免，教育就是要容许学生在错误中学习和发展。”', '[["A","正确"],["B","错误"]]', '["A"]', '这体现了新课程改革“以人为本”的学生观：学生是发展的人，身心发展尚未成熟，具有巨大的发展潜能，犯错误是成长过程中的正常现象，教师应宽容、引导而非简单否定。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (748, 4, 28, 'judge', 0.6, '某小学把期中考试成绩排名表张贴在校门口，并将排名逐一发送给全体家长。学校认为这符合“双减”加强学业管理的要求。', '[["A","正确"],["B","错误"]]', '["B"]', '“双减”和中小学考试管理规定明确要求，考试成绩以等级方式呈现，不得公布学生成绩和排名，不得按成绩分班、排座位。学校张贴并群发成绩排名，违反规定。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (749, 4, 29, 'judge', 0.6, '周老师备数学课时，除了钻研教材和课程标准，还认真分析班里每名学生的基础和常见错误，再据此设计分层练习。', '[["A","正确"],["B","错误"]]', '["A"]', '周老师既备教材、备课标，又备学生、备教法，依据学情设计教学，符合教学工作基本环节中“备课”的要求，也体现了因材施教的思想。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (750, 4, 30, 'judge', 0.6, '郑老师认为：“小学德育主要靠日常行为习惯的养成，不必太看重道德认识，学生只要行为表现好就行。”', '[["A","正确"],["B","错误"]]', '["B"]', '品德结构包括道德认识、道德情感、道德意志和道德行为，四者相互联系、缺一不可，德育应促进学生知、情、意、行全面协调发展。郑老师重行为、轻认识，割裂了品德结构。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (751, 4, 31, 'single', 1.0, '周老师给新教师做培训时说：“同样是教《三字经》，古代私塾强调背诵伦理纲常，今天的课堂则引导学生批判地理解其中的文化内涵。”这一差异最能说明教育具有（　）', '[["A","继承性"],["B","历史性"],["C","永恒性"],["D","长期性"]]', '["B"]', '教育的历史性是指教育随社会历史的发展而变化，在不同社会或同一社会的不同历史阶段，教育的性质、目的、内容各不相同。古今教《三字经》的目的和方式不同，体现了历史性。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (752, 4, 32, 'single', 1.0, '吴老师主张“生活即教育”“社会即学校”，常带学生到社区、菜市场识字、观察、做调查。他这种教育思想直接受到下列哪位教育家的影响？（　）', '[["A","陶行知"],["B","孔子"],["C","赫尔巴特"],["D","杜威"]]', '["A"]', '陶行知提出“生活即教育”“社会即学校”“教学做合一”的生活教育理论，与吴老师做法一致。杜威提出“教育即生活”“学校即社会”，表述和侧重点与陶行知不同，是主要干扰项。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (753, 4, 33, 'single', 1.0, '某小学近年新添了录播教室、平板电脑和丰富的数字教学资源，课堂教学方式随之发生明显变化。这一事实主要说明（　）', '[["A","文化传统决定教育内容的选择"],["B","生产力发展水平制约教育的内容和手段"],["C","人口数量决定教育发展规模"],["D","政治经济制度决定教育的领导权"]]', '["B"]', '生产力发展为教育提供物质技术条件，制约教育的发展规模、速度以及教学内容、方法和手段。数字设备和资源进入课堂带来教学方式变化，正说明生产力制约教育手段。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (754, 4, 34, 'single', 1.0, '一年级和六年级的学生同在校运动会上，班主任却用很不一样的方式做赛前动员：对一年级学生多用鼓励、示范和具体小任务，对六年级学生则讲清规则、团队责任并让他们自主分工。这种差别对待主要依据的是个体身心发展的（　）', '[["A","不平衡性"],["B","顺序性"],["C","互补性"],["D","阶段性"]]', '["D"]', '阶段性是指个体在不同年龄阶段有不同的总体特征和主要矛盾，面临不同的发展任务，教育不能“一刀切”“齐步走”。针对低年级与高年级学生采用不同的动员方式，依据的是阶段性。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (755, 4, 35, 'single', 1.0, '郑老师发现，乐乐空间想象强但表达偏弱，欣欣则语言表达生动却计算粗心。郑老师据此为两人设计了不同的训练重点。这主要遵循了个体身心发展的（　）', '[["A","不平衡性"],["B","顺序性"],["C","个别差异性"],["D","阶段性"]]', '["C"]', '个别差异性是指不同个体在发展的优势领域、速度、水平和个性倾向等方面存在差异，教育应因材施教。郑老师针对乐乐和欣欣的不同特点确定不同训练重点，遵循的是个别差异性。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (756, 4, 36, 'single', 1.0, '在讨论“教育为什么人服务”时，周老师认为教育应当首先培养和完善健全的个人，个人的价值高于社会的价值。周老师的观点倾向于（　）', '[["A","个人本位论"],["B","社会本位论"],["C","文化本位论"],["D","生活本位论"]]', '["A"]', '个人本位论主张教育目的应从个人需要出发，强调个人价值高于社会价值，教育的根本在于使人的本性、本能得到自然发展。周老师的观点符合个人本位论。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (757, 4, 37, 'single', 1.0, '某小学在落实“五育并举”时，把劳动课、体育课和美育活动都并入语文、数学课，理由是“只要成绩好，其他方面自然会好”。这种做法主要错在忽视了全面发展教育各组成部分的（　）', '[["A","先后顺序性"],["B","相对独立性"],["C","绝对对立性"],["D","相互替代性"]]', '["B"]', '全面发展教育由德、智、体、美、劳五育组成，各育都有特定内涵和独特功能，具有相对独立性，不能相互取代；同时又相互联系、相互促进。用智育吞并其他各育，忽视了各育的相对独立性。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (758, 4, 38, 'single', 1.0, '吴老师讲《狼牙山五壮士》时声情并茂，讲到英雄跳崖处眼含热泪，学生深受感染。这最能体现教师劳动的哪一特点？（　）', '[["A","复杂性"],["B","创造性"],["C","示范性"],["D","长期性"]]', '["C"]', '示范性是指教师的言行举止、思想情感、态度作风都会成为学生模仿的对象，对学生产生潜移默化的影响。吴老师以自身真挚的情感感染学生，体现了教师劳动的示范性。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (759, 4, 39, 'single', 1.0, '郑老师遇事常与学生商量，尊重学生意见，班级氛围平等、融洽，学生既愿意亲近他，又能认真完成学习任务。这种师生关系属于（　）', '[["A","权威型"],["B","放任型"],["C","民主型"],["D","专制型"]]', '["C"]', '民主型师生关系中，教师尊重、信任学生，遇事与学生平等商议，严格要求与尊重相结合，师生关系融洽，学生学习积极性高。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (760, 4, 40, 'single', 1.0, '周老师在科学课上让学生围绕“校园植物为什么秋天落叶”自主观察、记录、讨论，而不是系统讲授书本结论。从课程内容组织方式看，这类课程更接近（　）', '[["A","必修课程"],["B","学科课程"],["C","隐性课程"],["D","活动课程"]]', '["D"]', '活动课程（经验课程）以儿童从事某种活动的兴趣和动机为中心，主张通过亲身体验、探究实践获得直接经验。周老师让学生在观察、讨论中学习，具有活动课程的特征。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (761, 4, 41, 'single', 1.0, '吴老师设计课程时，依次确定目标、选择和组织经验、评价结果，围绕预设目标系统展开。这种经典课程开发模式的提出者是（　）', '[["A","布鲁纳"],["B","杜威"],["C","苏霍姆林斯基"],["D","泰勒"]]', '["D"]', '泰勒在《课程与教学的基本原理》中提出了以目标为中心的课程开发模式，即“泰勒原理”，包括确定目标、选择经验、组织经验、评价结果四个基本问题。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (762, 4, 42, 'single', 1.0, '数学课上，郑老师不直接告诉学生长方形面积公式，而是给出若干小正方形，让学生自己摆一摆、数一数，自己发现“长×宽”的道理。郑老师这样做主要是为了（　）', '[["A","让学生记住更多公式"],["B","减轻教师讲课负担"],["C","引导学生独立思考、主动探究"],["D","保证教学进度整齐划一"]]', '["C"]', '郑老师不直接给结论，而是提供材料让学生动手操作、自己发现规律，旨在调动学生主动性，引导其独立思考、主动探究，体现了启发性教学原则。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (763, 4, 43, 'single', 1.0, '周老师讲“分数的初步认识”时，先拿出一个苹果当场切成两半，再让学生用圆形纸片折一折，表示出二分之一。周老师主要贯彻的教学原则是（　）', '[["A","直观性原则"],["B","巩固性原则"],["C","循序渐进原则"],["D","因材施教原则"]]', '["A"]', '直观性原则要求利用学生的多种感官和已有经验，通过实物、模型、操作等丰富感性认识，帮助理解抽象知识。周老师切苹果、折纸片让学生直观感知“二分之一”，体现了直观性原则。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (764, 4, 44, 'single', 1.0, '吴老师教《桂林山水》时，播放漓江风光视频，配上音乐和自己有感情的朗读，把学生“带入”山水情境之中。他运用的教学方法主要是（　）', '[["A","讲授法"],["B","讨论法"],["C","情境教学法"],["D","练习法"]]', '["C"]', '情境教学法是指教师有目的地创设生动具体、富有情感色彩的场景，引起学生一定的态度体验，帮助其理解教材、发展心理机能的方法。吴老师借助视频、音乐和朗读创设山水情境，运用的是情境教学法。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (765, 4, 45, 'single', 1.0, '教育心理学成为一门独立学科，有其标志性的著作与事件。一般认为，使教育心理学成为独立学科、被尊为“教育心理学之父”的学者及其著作是（　）', '[["A","皮亚杰《儿童心理学》"],["B","华生《行为主义者眼中的心理学》"],["C","桑代克与《教育心理学》"],["D","乌申斯基《人是教育的对象》"]]', '["C"]', '1903年桑代克出版《教育心理学》，后扩充为三卷本，奠定了教育心理学的基础，使其成为一门独立学科，桑代克被誉为“教育心理学之父”。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (766, 4, 46, 'single', 1.0, '幼儿园大班的朵朵做“三座山”实验时，坐在自己的位置上，只能描述出自己这一侧看到的山的样子，认为对面的娃娃看到的和她一样。朵朵的表现说明她思维具有（　）', '[["A","自我中心性"],["B","守恒性"],["C","可逆性"],["D","抽象逻辑性"]]', '["A"]', '皮亚杰通过“三座山”实验证明，前运算阶段儿童思维具有自我中心性，难以站在他人立场看问题，认为别人的观点和自己相同。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (767, 4, 47, 'single', 1.0, '四年级的阳阳能在头脑中把“3 + 5 = 8”反过来推成“8 - 5 = 3”，还能理解把同样多的水从细杯倒进粗杯总量不变。这表明他已进入皮亚杰所说的（　）', '[["A","感知运动阶段"],["B","具体运算阶段"],["C","前运算阶段"],["D","形式运算阶段"]]', '["B"]', '具体运算阶段（约7—11岁）儿童形成了守恒概念，思维具有可逆性，能进行具体的逻辑推理和群集运算。阳阳理解可逆关系和液体守恒，符合具体运算阶段特征。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (768, 4, 48, 'single', 1.0, '郑老师发现学生独立完成“鸡兔同笼”问题有困难，就先给出表格、提示“先假设全是鸡”，并在学生逐步掌握后撤去提示。这种帮助学生跨越“独立水平与潜在水平之间差距”的做法体现了（　）', '[["A","经典条件作用"],["B","支架式教学"],["C","发现学习"],["D","程序教学"]]', '["B"]', '支架式教学源于维果斯基的最近发展区理论：教师在学生现有发展水平与潜在发展水平之间提供适当的“支架”（提示、表格等），帮助其完成独立时无法完成的任务，并在能力提高后逐渐撤除支架。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (769, 4, 49, 'single', 1.0, '做阅读理解时，欣欣不太受教师和同伴意见影响，能依据自己的分析独立判断；而朵朵则更多参照老师的态度和同学的反应来确定答案。两人的差异主要属于（　）', '[["A","智力水平差异"],["B","性格气质差异"],["C","学习动机差异"],["D","认知方式差异（场独立与场依存）"]]', '["D"]', '场独立型的人倾向于以自身内部参照进行判断，不易受外界因素干扰；场依存型的人倾向于以外部参照为依据，易受他人态度和环境影响。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (770, 4, 50, 'single', 1.0, '豆豆作业完成得好，吴老师就奖他一枚“守纪星”；他一上课随意讲话，吴老师就取消他已得的一枚星。吴老师运用“奖星”和“取消星”分别属于（　）', '[["A","消退与正强化"],["B","负强化与消退"],["C","正强化与惩罚"],["D","正强化与负强化"]]', '["C"]', '呈现愉快刺激（奖星）以增加良好行为发生概率，属于正强化；撤销愉快刺激（取消已得的星）以抑制不良行为，属于惩罚中的取消性惩罚（反应代价）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (771, 4, 51, 'single', 1.0, '郑老师教语文，不是先讲结论，而是让学生围绕一个主题自己搜集材料、形成自己的理解，他强调让学生掌握学科的基本结构、自己去发现。这一教学主张最接近（　）', '[["A","桑代克的试误说"],["B","奥苏贝尔的接受学习理论"],["C","罗杰斯的自由学习观"],["D","布鲁纳的认知一结构学习理论"]]', '["D"]', '布鲁纳强调学习的实质是主动形成认知结构，主张让学生掌握学科基本结构，提倡发现学习。郑老师让学生自主搜集材料、自己发现理解，符合布鲁纳的理论。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (772, 4, 52, 'single', 1.0, '周老师讲授新科学概念前，先唤起学生已有的生活经验，再用准确的讲解把新概念与学生原有知识建立起非人为的、实质性的联系。周老师所追求的学习类型是（　）', '[["A","有意义的接受学习"],["B","试误学习"],["C","观察学习"],["D","机械的接受学习"]]', '["A"]', '奥苏贝尔认为，有意义学习是将新知识与学习者认知结构中已有观念建立起非人为的、实质性的联系；学生主要通过接受方式获得系统知识。周老师联系学生已有经验讲解新概念，属于有意义的接受学习。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (773, 4, 53, 'single', 1.0, '吴老师坚信每个学生都有自我实现的倾向，课堂上营造真诚、接纳、理解的氛围，以学生为中心组织学习活动。这一主张集中体现了（　）', '[["A","行为主义学习理论"],["B","建构主义学习理论"],["C","认知主义学习理论"],["D","人本主义学习理论"]]', '["D"]', '罗杰斯为代表的人本主义学习理论强调人的自我实现潜能，主张以学生为中心，建立真诚、尊重、无条件积极关注和共情理解的师生关系，营造自由宽松的学习氛围。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (774, 4, 54, 'single', 1.0, '郑老师布置“我们的小区”项目学习，学生分组从自己的经验出发，调查、访谈、合作解决真实问题，对同一问题形成不同但合理的理解。这种学习观主要属于（　）', '[["A","形式训练说"],["B","经典条件作用理论"],["C","认知结构迁移理论"],["D","建构主义学习理论"]]', '["D"]', '建构主义强调学习是学生在已有经验基础上主动建构意义的过程，重视真实情境、合作学习和多元理解。郑老师的项目学习让学生在真实任务中合作探究、自主建构，符合建构主义主张。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (775, 4, 55, 'single', 1.0, '糖糖家里突遭变故，整日闷闷不乐、上课走神，连最爱的绘画活动也不愿参加。周老师判断，她的需要长期停留在较低层次、未能得到满足，较高层次的需要就难以产生这一分析所依据的理论是（　）', '[["A","韦纳归因理论"],["B","马斯洛需要层次理论"],["C","自我效能感理论"],["D","阿特金森成就动机理论"]]', '["B"]', '马斯洛将人的需要由低到高分为生理、安全、归属与爱、尊重、认知、审美和自我实现等层次，认为低级需要基本满足后才会追求高级需要。糖糖因家庭变故安全归属需要受挫而影响学习兴趣，周老师依据的是需要层次理论。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (776, 4, 56, 'single', 1.0, '乐乐数学没考好，他对周老师说：“都怪我平时太懒、不够努力，要是肯下功夫，下次一定能考好。”按照韦纳成败归因理论，乐乐的归因特点是（　）', '[["A","外部、不稳定、不可控"],["B","内部、不稳定、可控"],["C","内部、稳定、不可控"],["D","外部、稳定、不可控"]]', '["B"]', '韦纳将成败归为能力、努力、任务难度、运气等因素。努力程度属于内部的、不稳定的、可控的因素。乐乐把没考好归于努力不足，有利于激发其后续学习。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (777, 4, 57, 'single', 1.0, '豆豆原本不敢上台发言，周老师先让他在小组里说，再在他获得成功体验后鼓励他：“你准备得很充分，完全有能力讲好。”豆豆逐渐相信自己能完成发言任务。周老师重点培养的是豆豆的（　）', '[["A","从众倾向"],["B","认知内驱力"],["C","成就需要"],["D","自我效能感"]]', '["D"]', '自我效能感由班杜拉提出，指个体对自己能否成功完成某一成就行为的主观判断。成功经验、言语劝说等是重要影响因素。周老师通过成功体验和鼓励让豆豆相信“我能行”，培养的是自我效能感。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (778, 4, 58, 'single', 1.0, '阳阳学会了用“凑十法”计算20以内进位加法，后来学习100以内进位加法时，也自觉运用凑整的思路。这种已有学习对后续学习的促进属于（　）', '[["A","逆向负迁移"],["B","顺向正迁移"],["C","顺向负迁移"],["D","逆向正迁移"]]', '["B"]', '先前学习对后继学习产生影响为顺向迁移，起促进作用为正迁移。阳阳先前掌握的凑十思路促进了后续学习，属于顺向正迁移。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (779, 4, 59, 'single', 1.0, '吴老师先让学生掌握“整数加法”，再引导他们学习“有理数加法”。从迁移内容的抽象概括水平看，这种由较低抽象层次的知识向较高抽象层次知识的迁移属于（　）', '[["A","垂直迁移"],["B","具体迁移"],["C","水平迁移"],["D","一般迁移"]]', '["A"]', '垂直迁移（纵向迁移）指处于不同抽象、概括水平的经验之间的相互影响，包括自下而上和自上而下。由“整数加法”到上位的“有理数加法”是不同概括水平间的迁移，属于垂直迁移。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (780, 4, 60, 'single', 1.0, '郑老师认为“题海无涯苦作舟”，让学生把一首古诗抄写五十遍。研究表明，适当的过度学习有助于保持，但学习的熟练程度达到（　）时记忆效果最好，超过则可能出现报酬递减。', '[["A","150%"],["B","300%"],["C","200%"],["D","100%"]]', '["A"]', '过度学习是指在达到刚好能背诵之后继续学习。研究表明，学习的熟练程度达到 150%（即过度学习 50%）时记忆效果最佳；超过这一限度，效果并不递增，还可能引起厌倦和疲劳。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (781, 4, 61, 'single', 1.0, '朵朵读课文时，一边读一边给自己提问题：“这一段的中心句是哪句？作者为什么这样写？”还会在重点句旁画出问号。她运用的学习策略主要是（　）', '[["A","资源管理策略"],["B","复述策略"],["C","组织策略"],["D","精加工策略"]]', '["D"]', '精加工策略是把新信息与已有知识联系起来，以增加新信息意义的策略，如提问、做笔记、画线批注、利用背景知识等。朵朵边读边自我提问、批注，属于精加工策略。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (782, 4, 62, 'single', 1.0, '复习科学单元时，阳阳把零散的知识按“动物—植物—微生物”归类，并画出层级关系图来帮助记忆。他主要运用了（　）', '[["A","时间管理策略"],["B","组织策略"],["C","复述策略"],["D","元认知策略"]]', '["B"]', '组织策略是整合所学新知识之间、新旧知识之间的内在联系，形成新的知识结构的策略，如归类、列提纲、画关系图等。阳阳归类知识、画层级图，属于组织策略。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (783, 4, 63, 'single', 1.0, '实验课上，吴老师发给每组一盒回形针、一根蜡烛和一盒火柴，让学生想办法把蜡烛固定在墙上。许多学生只想到火柴盒装火柴，想不到它还能当烛台。影响这些学生问题解决的主要因素是（　）', '[["A","功能固着"],["B","原型启发"],["C","自我中心"],["D","正迁移"]]', '["A"]', '功能固着是指人们把某种功能赋予某一物体的倾向，只看到它通常的用途，而看不到它可能具有的其他功能，从而影响问题的灵活解决。学生只把火柴盒当容器、想不到它还能做烛台，正是功能固着。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (784, 4, 64, 'single', 1.0, '周老师鼓励学生在解决问题时想出尽可能多、尽可能新奇的答案，哪怕暂时不评价对错。这种训练最直接指向创造性思维的（　）', '[["A","独创性"],["B","流畅性"],["C","敏捷性"],["D","变通性"]]', '["B"]', '创造性思维的主要特征包括流畅性、变通性（灵活性）和独创性。流畅性指在规定时间内产生观念数量的多少；鼓励“尽可能多”地产生答案首先训练的是流畅性。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (785, 4, 65, 'single', 1.0, '在我国，有权制定《中华人民共和国义务教育法》这类教育法律的国家机关是（　）', '[["A","教育部"],["B","全国人民代表大会及其常务委员会"],["C","省级人民代表大会"],["D","国务院"]]', '["B"]', '教育法律由全国人民代表大会及其常务委员会制定，属于教育法渊源中效力仅次于宪法的“法律”。国务院制定行政法规，教育部制定部门规章，省级人大制定地方性法规。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (786, 4, 66, 'single', 1.0, '某培训机构未取得办学许可证即擅自挂牌招生、开课办学。教育行政部门依法责令其停止办学、退还所收费用。这种处理主要针对的是违反（　）的行为。', '[["A","教师资格制度"],["B","国家教育考试制度"],["C","学业证书制度"],["D","学校设立条件和审批制度"]]', '["D"]', '设立学校及其他教育机构必须具备法定条件，并经主管机关批准、取得办学许可。未经审批、未取得办学许可证擅自办学，违反学校设立条件和审批制度，主管部门可责令停止办学、退还费用。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (787, 4, 67, 'single', 1.0, '郑老师被学校无正当理由扣减了绩效工资，他与学校交涉未果。按照《教师法》，维护其“按时获取工资报酬、享受国家规定的福利待遇”这一权利，首先可以通过的法定途径是（　）', '[["A","向消费者协会投诉"],["B","直接向人民法院提起民事诉讼"],["C","向公安机关报案"],["D","向教育行政部门提出教师申诉"]]', '["D"]', '获取劳动报酬和福利待遇是教师的法定权利。教师对学校侵犯其合法权益或对处理不服的，可依《教师法》向教育行政部门提出申诉。此属内部人事、待遇争议，一般先走教师申诉途径。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (788, 4, 68, 'single', 1.0, '五年级学生阳阳上课经常插嘴，班主任一气之下令其整节课站在教室外面走廊，不许听课。该教师的做法主要侵犯了学生的（　）', '[["A","受教育权"],["B","名誉权"],["C","人身自由权"],["D","财产权"]]', '["A"]', '受教育权是学生最主要的权利，参加教育教学计划安排的各种活动、使用教育教学设施设备是其重要内容。把学生逐出教室、剥夺其听课机会，直接侵犯了学生的受教育权。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (789, 4, 69, 'single', 1.0, '父母或其他监护人对未成年人的健康成长负有首要责任，应当创造良好、和睦的家庭环境。这一责任在未成年人保护体系中属于（　）', '[["A","司法保护"],["B","家庭保护"],["C","社会保护"],["D","学校保护"]]', '["B"]', '未成年人保护法规定了家庭、学校、社会、网络、政府、司法六大保护，其中家庭保护是第一位的，父母或其他监护人应履行监护职责和抚养义务，为未成年人健康成长创造良好家庭环境。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (790, 4, 70, 'single', 1.0, '周老师在家访中发现，学生欣欣身上有疑似被家长殴打留下的伤痕，精神也很恐惧。依法，周老师作为学校工作人员负有强制报告义务，应当立即（　）', '[["A","在家长会上公开讨论此事"],["B","为保护家庭声誉替其保密"],["C","向公安、民政、教育等有关部门报告"],["D","要求欣欣书面保证不对外说"]]', '["C"]', '《未成年人保护法》确立强制报告制度：国家机关、居委会、村委会、密切接触未成年人的单位及其工作人员，在工作中发现未成年人身心健康受到侵害、疑似受到侵害或面临其他危险情形的，应当立即向公安、民政、教育等部门报告。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (791, 4, 71, 'single', 1.0, '学生在校期间，校外人员擅自闯入校园将学生豆豆打伤，经查学校门卫管理和应急处置存在明显疏漏。对豆豆的损害，下列责任认定正确的是（　）', '[["A","由学生家长自行承担"],["B","由闯入的第三人承担侵权责任，学校承担相应的补充责任"],["C","应由学校承担全部赔偿责任，第三人不担责"],["D","学校与第三人平均分担损失"]]', '["B"]', '《民法典》规定，无民事行为能力人或限制民事行为能力人在学校学习、生活期间受到学校以外的第三人人身损害的，由第三人承担侵权责任；学校未尽到管理职责的，承担相应的补充责任。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (792, 4, 72, 'single', 1.0, '教师吴老师认为教育局对其作出的一项具体行政行为侵犯自身合法权益，欲寻求救济。下列关于行政复议申请期限的说法，正确的是（　）', '[["A","应当在行为作出满1年后提出"],["B","没有任何期限限制"],["C","可在知道该具体行政行为之日起60日内提出行政复议申请"],["D","只能在3日内口头提出"]]', '["C"]', '《行政复议法》规定，公民、法人或其他组织认为具体行政行为侵犯其合法权益的，可以自知道或应当知道该具体行政行为之日起60日内提出行政复议申请。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (793, 4, 73, 'single', 1.0, '郑老师从教多年，始终把“学高为师，身正为范”作为座右铭，言行一致、举止文明，注意自己的言行对学生的影响。这集中体现了《中小学教师职业道德规范》中的（　）', '[["A","关爱学生"],["B","终身学习"],["C","爱岗敬业"],["D","为人师表"]]', '["D"]', '为人师表要求教师坚守高尚情操、知荣明耻，严于律己、以身作则，言行举止文明规范，自觉抵制有偿家教等。郑老师以“身正为范”律己、注意示范，体现的是为人师表。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (794, 4, 74, 'single', 1.0, '周老师面对新形势下的信息化教学，主动学习微课制作、钻研线上线下融合教学，不断更新知识结构。这主要体现了师德规范中的（　）', '[["A","依法执教"],["B","廉洁从教"],["C","终身学习"],["D","团结协作"]]', '["C"]', '终身学习要求教师崇尚科学精神，树立终身学习理念，拓宽知识视野、更新知识结构，潜心钻研业务、不断提高专业素养和教育教学水平。周老师主动学习新技术新方法，体现了终身学习。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (795, 4, 75, 'single', 1.0, '教师节来临，家长将购物卡夹在贺卡中送给吴老师，吴老师发现后婉言谢绝，并向家长说明依规不能收受礼品礼金。吴老师的行为直接体现了（　）', '[["A","加强安全防范"],["B","坚守廉洁自律"],["C","规范师生关系"],["D","坚持言行雅正"]]', '["B"]', '《新时代中小学教师职业行为十项准则》要求教师坚守廉洁自律，严于律己、清廉从教，不得收受学生及家长财物，不得参加由学生及家长付费的宴请、旅游等活动。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (796, 4, 76, 'single', 1.0, '某校组织教师开展安全教育和应急演练，要求教师在课堂、活动中切实履行安全提醒和看护职责，遇到危险优先保护学生人身安全。这对应《新时代中小学教师职业行为十项准则》中的（　）', '[["A","规范从教行为"],["B","坚守廉洁自律"],["C","秉持公平诚信"],["D","加强安全防范"]]', '["D"]', '“加强安全防范”要求教师增强安全意识，加强安全教育，保护学生人身安全，在危险来临之时优先救护学生。学校的安全教育和演练部署对应这一准则。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (797, 4, 77, 'single', 1.0, '新课程改革要求改变过于强调接受学习、死记硬背、机械训练的状况，倡导的新型学习方式是（　）', '[["A","自主学习、合作学习、探究学习"],["B","背诵学习、训练学习、考试学习"],["C","被动学习、统一学习、封闭学习"],["D","竞争学习、个体学习、重复学习"]]', '["A"]', '新课改倡导学生主动参与、乐于探究、勤于动手，逐步实现学习方式的转变，倡导自主、合作、探究的学习方式，培养学生搜集处理信息、获取新知识、分析解决问题以及交流合作的能力。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (798, 4, 78, 'single', 1.0, '周老师在新课改背景下重新定位自己的角色：她不再只是知识的传授者，还成为学生学习的促进者、课程的建设者和教育教学的研究者。这种转变属于新课改倡导的（　）', '[["A","学生观转变"],["B","考试评价制度转变"],["C","教师观与教师角色转变"],["D","课程管理制度转变"]]', '["C"]', '新课改下的教师观强调，教师是学生学习的促进者、教育教学的研究者、课程的建设者和开发者、社区型开放教师，要从“教书匠”转变为研究者、引导者。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (799, 4, 79, 'single', 1.0, '教师开展教学工作、衡量教学质量的直接依据，以及教材编写、教学、评估和考试命题的基本依据是（　）', '[["A","学生升学需求"],["B","教学参考书"],["C","教辅资料"],["D","课程标准"]]', '["D"]', '课程标准是国家课程的基本纲领性文件，规定学科的课程性质、目标、内容框架和教学、评价建议，是教材编写、教学、评估和考试命题的依据，也是国家管理和评价课程的基础。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (800, 4, 80, 'single', 1.0, '2025年，党中央、国务院印发了面向2035年、系统部署教育强国建设的纲领性文件。这份文件是（　）', '[["A","《义务教育课程方案》"],["B","《国家中长期教育改革和发展规划纲要》"],["C","《教育强国建设规划纲要（2024—2035年）》"],["D","《中国教育现代化2035》"]]', '["C"]', '《教育强国建设规划纲要（2024—2035年）》是新时代新征程推动教育高质量发展、建设教育强国的总体规划和行动纲领，对建成教育强国作出战略安排。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (801, 4, 81, 'multi', 1.6, '周老师上好一节公开课，往往要做许多工作。下列属于教师备课基本内容的有（　）', '[["A","钻研课程标准和教科书"],["B","研究教法、设计教学"],["C","了解研究学生"],["D","上课后立即布置大量惩罚性抄写"],["E","制订学期、单元和课时教学计划"]]', '["A","B","C","E"]', '备课要做好“三备”：备教材（钻研课程标准、教科书及有关参考资料）、备学生（了解学生原有知识水平、兴趣、方法和习惯等）、备教法（设计如何把内容教给学生），并写好学期（学年）教学进度计划、单元计划和课时计划（教案）。D是上课之后的错误做法。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (802, 4, 82, 'multi', 1.6, '郑老师做班主任工作讲究方法。下列做法中，有利于培养良好班集体的有（　）', '[["A","建立健全班纪班规"],["B","组织丰富多彩的班级活动"],["C","只信任少数尖子生、疏远后进生"],["D","确立共同的奋斗目标"],["E","选拔和培养班干部、形成领导核心"]]', '["A","B","D","E"]', '组织和培养良好班集体通常要：确立共同奋斗目标、选拔和培养班干部形成坚强领导核心、建立严明的纪律和健全规章制度、组织形式多样的教育活动、培养正确舆论和良好班风。C厚此薄彼、歧视后进生，不利于班集体团结。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (803, 4, 83, 'multi', 1.6, '小学阶段的儿童在认知、社会性等方面有其典型特点。下列关于小学生心理发展特点的表述，正确的有（　）', '[["A","无注意过仍起重要作用，有注意注意步发展"],["B","已完全具备成人水平的辩证逻辑思维"],["C","自我意识逐步发展，开始能进行一定的自我评价"],["D","同伴关系和集体生活的影响日益增强"],["E","思维由具体形象思维向抽象逻辑思维过渡"]]', '["A","C","D","E"]', '小学生思维发展的基本特点是由具体形象思维逐步向抽象逻辑思维过渡，但仍需要具体形象支持；注意发展中无意注意仍占重要地位，有意注意随年龄增长；同伴交往和班集体对其社会性发展影响越来越大；自我意识和自我评价能力逐步发展。B错误，辩证逻辑思维要到青少年期乃至更晚才逐步发展。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (804, 4, 84, 'multi', 1.6, '吴老师想在课堂上有效运用强化。下列做法符合操作性条件作用原理的有（　）', '[["A","不分场合一律用物质奖励，且不断加码"],["B","对反复出现的扰乱行为，在保证安全前提下不予关注促其消退"],["C","学生改正错误后及时撤销之前的限制性安排以鼓励进步"],["D","学生主动回答问题后及时给予表扬"],["E","对学生的良好行为运用普雷马克原理（用高频活动强化低频行为）"]]', '["B","C","D","E"]', '及时表扬属于正强化；用喜欢的活动作为强化物是普雷马克原理（祖母法则）；对意在博取关注的不良行为不予强化可使其消退；学生改正后撤去厌恶刺激（限制）属负强化。A滥用物质刺激、不断加码，会削弱内部动机并使强化失效。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (805, 4, 85, 'multi', 1.6, '郑老师要培养和激发学生的学习动机。下列措施恰当的有（　）', '[["A","创设问题情境，启发学生求知欲"],["B","设置具体、明确、难度适中的学习目标"],["C","妥善进行奖惩、及时反馈学习结果"],["D","只用频繁考试和排名来刺激学生"],["E","引导学生把成败归因于努力等可控因素"]]', '["A","B","C","E"]', '激发学习动机可从以下入手：创设问题情境激发兴趣；设置具体明确、难度适中（“跳一跳够得着”）的目标；充分利用学习结果的反馈；妥善运用表扬与批评；引导学生进行积极归因；组织竞赛与合作等。D频繁考试排名会加重焦虑、违背“双减”，不是科学的激发动机方式。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (806, 4, 86, 'multi', 1.6, '为促进学生“举一反三、触类旁通”，周老师在教学中可以采取的促进迁移的措施有（　）', '[["A","精选教材，突出基本概念和原理"],["B","教给学生学习方法，提高概括水平"],["C","让学生死记孤立结论，避免联系生活实际"],["D","注意新旧知识的联系，提供多样化练习与变式"],["E","合理编排教学内容，促进知识结构化"]]', '["A","B","D","E"]', '促进有效迁移的教学包括：精选教材、重视基础知识和基本原理；合理编排内容，形成清晰的认知结构；合理安排程序，加强新旧知识联系；提供多样化的练习和变式，促进概括；教授学习策略和方法。C死记孤立结论、脱离实际，反而阻碍迁移。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (807, 4, 87, 'multi', 1.6, '豆豆学习时常感到“记不住、不会学”。下列属于学习策略训练中资源管理策略的有（　）', '[["A","遇到困难时善于向老师、同学求助"],["B","把材料反复朗读直到机械背诵"],["C","选择安静适宜的学习环境"],["D","制订学习计划、合理安排学习时间"],["E","调节学习心境、进行自我激励"]]', '["A","C","D","E"]', '资源管理策略是辅助学生管理可用的环境和资源的策略，主要包括时间管理、学习环境管理、努力与心境管理、学业求助等策略。B单纯反复朗读属认知策略中的复述策略。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (808, 4, 88, 'multi', 1.6, '某小学发生学生伤害事故后，各方对处理方式争执不下。依据《学生伤害事故处理办法》及相关法律，下列说法正确的有（　）', '[["A","处理事故应当遵循依法、客观公正、合理适当的原则"],["B","学校对学生伤害事故负有责任的，应根据责任大小适当予以经济赔偿"],["C","事故责任人承担责任不解决户口、住房、就业等与救助无关的事宜"],["D","协商不成的，当事人可书面请求主管部门调解或提起诉讼"],["E","无论学校有无过错，都须解决受害学生升学、户口等全部要求"]]', '["A","B","C","D"]', '《学生伤害事故处理办法》要求处理事故遵循依法、客观公正、合理适当的原则，及时妥善处理；学校负有责任的，根据责任大小予以适当经济赔偿；不承担解决户口、住房、就业等与救助受伤害学生、赔偿相应经济损失无直接关系的其他事项；双方可协商解决，协商不成可请求教育行政部门调解或向法院起诉。E于法无据。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (809, 4, 89, 'multi', 1.6, '依法办学、依法执教是对学校和教师的基本要求。学校及教师应当履行的法定义务包括（　）', '[["A","对学生进行安全教育、保护学生人身安全"],["B","贯彻国家教育方针，执行国家教育教学标准"],["C","维护受教育者、教师的合法权益"],["D","可以根据成绩对学生公开排名、分快慢班"],["E","尊重学生人格尊严，不得实施体罚或变相体罚"]]', '["A","B","C","E"]', '学校应贯彻教育方针、执行国家标准、保证教育教学质量，维护师生合法权益；教师应遵守职业道德、尊重学生人格、保护学生安全、制止侵害行为。D公开排名、按成绩分快慢班，违反“双减”和义务教育均衡发展要求。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (810, 4, 90, 'multi', 1.6, '师德是教师立身之本。下列属于《中小学教师职业道德规范》（2008）内容的有（　）', '[["A","爱国守法、爱岗敬业"],["B","关爱学生、教书育人"],["C","为人师表、终身学习"],["D","团结协作、尊重家长"],["E","按学生家庭背景区别对待学生"]]', '["A","B","C"]', '2008年《中小学教师职业道德规范》共六条：爱国守法、爱岗敬业、关爱学生、教书育人、为人师表、终身学习。“团结协作、尊重家长”是1997年规范中的内容，属易混项；E按家庭背景区别对待学生，违背教育公平和关爱学生。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (811, 5, 1, 'judge', 0.6, '高中政治组教研时，朱老师说：“动物也会哺育幼崽，所以人对人的教育在动物界早就有了。”', '[["A","正确"],["B","错误"]]', '["B"]', '朱老师持生物起源说，把教育起源归于动物的本能活动，否认了教育是人类所特有的有目的、有意识的社会活动。教育起源于人类适应社会生活需要的生产劳动（劳动起源说）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (812, 5, 2, 'judge', 0.6, '孙老师带高一数学，先补初中衔接内容再讲函数，从不跳跃赶进度。这种安排符合个体身心发展的顺序性。', '[["A","正确"],["B","错误"]]', '["A"]', '个体身心发展是一个由低级到高级、由量变到质变的连续过程，具有顺序性，教育应循序渐进。孙老师先衔接、后提高，由浅入深，符合顺序性要求。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (813, 5, 3, 'judge', 0.6, '林老师认为学生“齐步走才公平”，布置作业、确定目标全班一刀切，不许任何人特殊。', '[["A","正确"],["B","错误"]]', '["B"]', '个体身心发展具有个别差异性，学生在兴趣、能力、基础等方面各不相同，教育应因材施教。公平不等于平均划一，“一刀切”恰恰忽视差异、损害了真正的教育公平。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (814, 5, 4, 'judge', 0.6, '朱老师常用“熬过高考、进了大学就不用再学了”激励高三学生。这符合终身教育的理念。', '[["A","正确"],["B","错误"]]', '["B"]', '终身教育思想认为教育应贯穿人的一生，学习不受年龄、阶段限制，学校教育只是终身学习的一个阶段。把学习止于高考或大学的说法与终身教育理念背道而驰。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (815, 5, 5, 'judge', 0.6, '林老师要求学生早读不碰手机，自己却常在自习课刷短视频，已被学生看到多次。', '[["A","正确"],["B","错误"]]', '["B"]', '教师劳动具有强烈的示范性，教师的言行举止都是学生学习的榜样，身教重于言教。林老师要求学生做到的自己却做不到，言行不一，会削弱教育威信与教育效果。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (816, 5, 6, 'judge', 0.6, '孙老师课后主动找考试失利的宇航谈心，先听他讲难处，再一起分析失分原因。', '[["A","正确"],["B","错误"]]', '["A"]', '建立良好师生关系要求教师热爱、尊重和理解学生，发扬教育民主，善于与学生沟通。孙老师主动关心、耐心倾听、共同分析，体现了对学生的尊重与理解，有利于增进师生信任。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (817, 5, 7, 'judge', 0.6, '物理课上林老师不急于报答案，而是层层追问，让学生自己推出受力分析的结论。这体现了启发性原则。', '[["A","正确"],["B","错误"]]', '["A"]', '启发性原则要求教师调动学生主动性，引导他们独立思考、积极探究，自觉地掌握知识。林老师以追问代替直接灌输，让学生自己推出结论，正体现了启发性原则。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (818, 5, 8, 'judge', 0.6, '嘉豪默写屡次不过关，朱老师当众骂他“笨得像木头”，还说这样严格都是为他好。', '[["A","正确"],["B","错误"]]', '["B"]', '尊重学生与严格要求相结合原则要求把对学生的严格要求建立在尊重信任学生人格的基础上。当众辱骂损害学生人格尊严，也违背关爱学生的师德要求。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (819, 5, 9, 'judge', 0.6, '孙老师把讨论中“优生垄断发言”的难题当课题，边实践边调整规则。这种在自己课堂里做研究的方式值得提倡。', '[["A","正确"],["B","错误"]]', '["A"]', '教育行动研究是教师针对教育教学中的实际问题，在真实情境中系统地研究并改进实践、促进专业成长的研究方式。孙老师从自己的课堂难题出发、边研究边改进符合行动研究的精神。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (820, 5, 10, 'judge', 0.6, '高一学生能离开具体器材，对“假如没有摩擦会怎样”提出假设并推理验证。这表明他们已进入形式运算阶段。', '[["A","正确"],["B","错误"]]', '["A"]', '形式运算阶段的个体思维已超越对具体事物的依赖，能够进行抽象逻辑思维和假设一演绎推理。高中生能围绕假设展开推理验证，符合形式运算阶段的特征。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (821, 5, 11, 'judge', 0.6, '朱老师给思琪布置比她现有水平稍难的阅读题，并在她卡壳时给出提示。这种做法契合最近发展区理论。', '[["A","正确"],["B","错误"]]', '["A"]', '维果斯基认为教学要着眼于学生的最近发展区，即现有水平与在他人帮助下所能达到的水平之间的区域，教学应走在发展的前面。朱老师提供稍难任务并适时搭支架。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (822, 5, 12, 'judge', 0.6, '俊杰为引起老师注意一讲怪话，林老师便不动声色不予关注，几次后他自觉没趣不再闹腾。', '[["A","正确"],["B","错误"]]', '["A"]', '消退是指有机体做出以前曾被强化过的反应，如果这一反应之后不再有强化物相伴，该反应在将来发生的概率便降低。对为博取关注的捣乱行为不予理睬，不给予其想要的关注，可使行为逐渐消退。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (823, 5, 13, 'judge', 0.6, '讲电化学前，朱老师先呈现一段“氧化还原反应与电流关系”的概括性导读材料。这就是先行组织者策略。', '[["A","正确"],["B","错误"]]', '["A"]', '先行组织者是先于学习任务本身呈现的一种抽象、概括和综合水平较高的引导性材料，能在新旧知识之间架起桥梁，促进有意义学习。朱老师课前呈现概括性导读材料。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (824, 5, 14, 'judge', 0.6, '林老师坚信知识只能由老师讲清楚，学生只要认真听、记得牢就算真正学会了。', '[["A","正确"],["B","错误"]]', '["B"]', '建构主义学习理论认为，学习不是知识由教师向学生的简单传递，而是学生基于已有经验主动建构意义的过程。林老师把学生视为被动接受的容器，与建构主义及新课改倡导的主动学习相违背。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (825, 5, 15, 'judge', 0.6, '梦洁考差后怪自己“天生不是学理科的料”，孙老师引导她从努力程度上找原因。', '[["A","正确"],["B","错误"]]', '["A"]', '韦纳成败归因理论把能力视为内部、稳定、不可控因素，把努力视为内部、不稳定、可控因素。将失败归因于能力易导致习得性无助，归因于努力则能增强后续坚持性。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (826, 5, 16, 'judge', 0.6, '雅雯演讲前总怕忘词，林老师先让她在小组内成功试讲几次，再上台她就镇定多了。', '[["A","正确"],["B","错误"]]', '["A"]', '自我效能感指个体对自己能否成功完成某一任务的信念，个人自身行为的成败经验是其最重要、最有力的来源。成功试讲的经验提高了雅雯的自我效能感。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (827, 5, 17, 'judge', 0.6, '朱老师要求学生当天晚自习先回顾白天新课再做练习，说“趁热打铁忘得慢”。这符合艾宾浩斯遗忘规律。', '[["A","正确"],["B","错误"]]', '["A"]', '艾宾浩斯遗忘曲线表明遗忘在学习之后立即开始，进程不均衡，先快后慢、先多后少。因此学习后要及时复习，在大量遗忘开始前巩固。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (828, 5, 18, 'judge', 0.6, '林老师说：“记笔记、找联系都是花架子，把原文逐字背熟才算真会。”', '[["A","正确"],["B","错误"]]', '["B"]', '记笔记、类比、用自己的话复述等精加工策略能加深对材料的理解、建立知识间联系，画线整理结构图等组织策略也有助于系统掌握。只靠机械背诵否定精加工与组织的作用，既不利于理解也不利于迁移。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (829, 5, 19, 'judge', 0.6, '朱老师断定：高中生做好事大多还停留在“怕被大人批评”的水平，对他们不必讲什么责任与良知。', '[["A","正确"],["B","错误"]]', '["B"]', '“怕被批评、怕受惩罚”属于科尔伯格所说的前习俗水平中的惩罚与服从定向阶段。多数青少年已发展到习俗水平，部分人可达后习俗水平，能够理解责任、原则与良知。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (830, 5, 20, 'judge', 0.6, '班里逐渐形成一条不成文规矩：别人发言时谁也不插嘴。孙老师说这种“大家共同守住的约定”比罚站更管用。', '[["A","正确"],["B","错误"]]', '["A"]', '集体促成的纪律是指由同伴群体形成的群体规范和集体压力所促成的行为准则。学生共同认可“别人发言不插嘴”并自觉遵守，比外部惩罚更具约束力。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (831, 5, 21, 'judge', 0.6, '嘉豪连续几次考砸后干脆书都不翻，说“再学也没用”，林老师便认定他态度不端、无可救药。', '[["A","正确"],["B","错误"]]', '["B"]', '个体长期反复经历失败、认为结果无法由自己控制而产生的无能为力状态称为习得性无助。教师应帮助这类学生获得成功体验、进行努力归因训练，而非简单贴“态度不端”的标签、放弃教育。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (832, 5, 22, 'judge', 0.6, '孙老师把含全班家庭住址和家长手机号的值日表，直接发到了有陌生商家的家长大群。', '[["A","正确"],["B","错误"]]', '["B"]', '学生家庭住址、家长联系方式等属于不愿为他人知悉的个人信息和隐私。教师未经同意将其公开到人员混杂的群中，增加信息泄露风险，侵犯学生及家长的隐私权和个人信息权益。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (833, 5, 23, 'judge', 0.6, '学校以人手紧为由不批准林老师参加省里组织的脱产培训，林老师认为自己的法定权利受到了侵犯。', '[["A","正确"],["B","错误"]]', '["A"]', '《教师法》规定教师享有参加进修或者其他方式培训的权利。学校应创造条件保障教师的进修培训权，仅以人手紧为由不予准假，构成对该权利的侵害。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (834, 5, 24, 'judge', 0.6, '朱老师嫌俊杰上课总接话，令他搬桌椅到走廊站着听，一连三天不许进教室，说站着听也算听课。', '[["A","正确"],["B","错误"]]', '["B"]', '受教育权是学生最主要的权利，教师不得擅自责令学生停课、离开教室。朱老师将学生逐出教室长达三天，直接剥夺其正常上课机会，侵犯受教育权。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (835, 5, 25, 'judge', 0.6, '操场篮球架螺丝松动多日未修，体育课上嘉豪扣篮时架体倾倒砸伤同学，家长要求学校赔偿。', '[["A","正确"],["B","错误"]]', '["A"]', '学校对校舍、场地、设施设备负有安全检查与维护义务。篮球架隐患多日未修，说明学校未尽管理职责、主观上有过错，由此造成学生伤害，学校应依法承担相应赔偿责任。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (836, 5, 26, 'judge', 0.6, '某省规定与教育部规章对同一件事要求不一，朱老师说：“省里的文件离得近，当然听省里的。”', '[["A","正确"],["B","错误"]]', '["B"]', '地方性法规与部门规章对同一事项规定不一致、不能确定如何适用时，不能简单以谁“离得近”决定，应依法立法由国务院提出意见：认为适用地方性法规则适用之，认为适用部门规章则提请全国人大常委会裁决。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (837, 5, 27, 'judge', 0.6, '孙老师被学校扣发绩效，他在接到通知之日起三十日内向教育局提出了申诉。这符合教师申诉的时限规定。', '[["A","正确"],["B","错误"]]', '["A"]', '教师对学校或其他教育机构侵犯其合法权益的行为，可向主管的教育行政部门提出申诉。教师申诉应当在知道权益受损之日起三十日内提出，孙老师在法定期限内向教育局申诉。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (838, 5, 28, 'judge', 0.6, '“平均分上不去，搞活动、抓习惯都是白搭”，高三林老师把班会和体锻时间全挪来讲题。', '[["A","正确"],["B","错误"]]', '["B"]', '教书育人要求教师遵循教育规律、实施素质教育，培养学生良好品行、促进学生全面发展，不以分数作为评价学生的唯一标准。挤占班会、体锻一味追分，违背教书育人与全面发展要求。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (839, 5, 29, 'judge', 0.6, '俊杰曾因违纪出名，朱老师却相信他能变好，让他负责运动会器材，他果然十分负责。这说明学生是发展中的人。', '[["A","正确"],["B","错误"]]', '["A"]', '新课改学生观认为学生是发展的人、独特的人和具有独立意义的人，学生身心尚未成熟，具有巨大的发展潜能和可塑性。朱老师不被旧印象定型、给机会促其进步。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (840, 5, 30, 'judge', 0.6, '孙老师把“我来讲”改成“你们先想、先辩”，课堂上学生质疑和辩论明显多了。', '[["A","正确"],["B","错误"]]', '["A"]', '新课改教学观强调教学从“教育者为中心”转向“学习者为中心”，从“教会学生知识”转向“教会学生学习”，从重结论转向重结论同时重过程。孙老师让学生先想先辩，正体现这一转向。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (841, 5, 31, 'single', 1.0, '高三某班学生在讨论“学习到底图什么”时，孙老师没有直接给结论，而是让大家结合社会需要和个人兴趣去辩论。孙老师这一做法最能说明教育具有（　）', '[["A","相对独立性"],["B","历史性"],["C","永恒性"],["D","阶级性"]]', '["B"]', '教育的历史性指教育在不同的社会或同一社会的不同历史阶段，其性质、目的、内容等各不相同。让学生结合所处时代的社会需要与个人发展思考教育的意义，正体现教育受具体历史条件制约的历史性。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (842, 5, 32, 'single', 1.0, '高一选科指导时，朱老师发现嘉豪逻辑推理强、坐得住，但当众表达容易紧张。朱老师据此帮他扬长避短，而不是让他照搬别人的选法。这主要依据个体身心发展的（　）', '[["A","不平衡性"],["B","顺序性"],["C","个别差异性"],["D","阶段性"]]', '["C"]', '个别差异性指不同个体在发展速度、优势领域、个性特点等方面存在差异，教育应因材施教。朱老师针对嘉豪的独特条件帮助其选择，依据正是个别差异性。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (843, 5, 33, 'single', 1.0, '有人对孙老师说：“孩子考不上好大学，这辈子就全完了，你再努力教也没用。”孙老师不认同这种看法。从影响人发展的因素看，这句话错在忽视了（　）', '[["A","早期教育具有不可替代性"],["B","学校教育和个体主观能动性的作用"],["C","环境对人的单向决定作用"],["D","遗传决定人的发展水平"]]', '["B"]', '人的发展是遗传、环境、教育和个体主观能动性共同作用的结果，学校教育在其中起主导作用，个体主观能动性是发展的内在动力。“一次考试定终身、教育无用”的观点否认了后续教育的主导作用和学生自身的能动性。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (844, 5, 34, 'single', 1.0, '高考百日誓师后，学校标语写着“为中华之崛起而读书，也为成就更好的自己而拼搏”。这一表述试图调和的教育目的价值取向是（　）', '[["A","内在目的与外在目的"],["B","个人本位与社会本位"],["C","生活本位与文化本位"],["D","宗教本位与自然本位"]]', '["B"]', '社会本位论主张教育应根据社会需要、为社会培养合格成员；个人本位论主张教育应满足个人发展需要、增进个人价值。标语兼顾国家社会需要与个人自我实现，是在个人本位与社会本位之间寻求统一。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (845, 5, 35, 'single', 1.0, '高三复习最紧时，林老师仍坚持每天一节体育课照常上，并组织心理减压活动。他这样做主要是为了（　）', '[["A","降低学校的升学考核压力"],["B","提高智育在五育中的比重"],["C","落实全面发展教育，使学生身心协调发展"],["D","用体育和德育取代文化课"]]', '["C"]', '全面发展教育由德、智、体、美、劳五育构成，五育相互依存、相互促进，不可偏废。紧张复习中坚持体育与心理调节，正是为促进学生身心协调、实现全面发展。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (846, 5, 36, 'single', 1.0, '孙老师常说：“做班主任，我是踩着星光进校门、披着夜色回家，但看到学生进步就觉得值。”这最能体现教师劳动的（　）', '[["A","长期性与间接性"],["B","复杂性与创造性"],["C","主体性与示范性"],["D","连续性与广延性"]]', '["D"]', '教师劳动的连续性指劳动时间没有上下班的严格界限，广延性指劳动空间延伸到校外、家庭。从清晨到深夜持续投入，集中体现了连续性与广延性。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (847, 5, 37, 'single', 1.0, '面对“学生犯错到底该不该罚”的争论，孙老师说：“罚不是目的，但规则面前人人要担责，关键是让他明白为什么。”这一态度最符合（　）', '[["A","民主型师生关系，严格要求与尊重理解相结合"],["B","友谊型师生关系，教师与学生完全平等无差别"],["C","放任型师生关系，学生可自行其是"],["D","专制型师生关系，以服从为前提"]]', '["A"]', '民主型师生关系以开放、平等、互助为主要特征，教师尊重学生、听取意见，同时又有明确要求和规则意识。孙老师既坚持规则责任、又注重讲道理和理解，正是民主型。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (848, 5, 38, 'single', 1.0, '学校开设“人工智能基础”课，不按传统学科知识体系编排，而是让学生围绕真实项目去动手、合作完成任务。从课程类型看，这类课程更接近（　）', '[["A","潜在课程"],["B","活动课程"],["C","学科课程"],["D","必修课程"]]', '["B"]', '活动课程又称经验课程，以儿童的兴趣、需要和经验为中心，通过学生亲身实践的活动来学习，主张在“做中学”。围绕真实项目动手合作的课程更接近活动课程。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (849, 5, 39, 'single', 1.0, '朱老师设计校本课程时，先确定学生通过课程应达到的目标，再据此选择内容、组织活动、设计评价。他遵循的课程开发模式是（　）', '[["A","目标模式"],["B","实践折中模式"],["C","过程模式"],["D","情境模式"]]', '["A"]', '以泰勒为代表的目标模式主张以目标为课程开发的核心和出发点，按“确定目标—选择经验—组织经验—评价结果”的程序进行。朱老师先定目标再安排内容与评价，遵循目标模式。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (850, 5, 40, 'single', 1.0, '高二选科后，同一教室坐着选不同组合的学生，学校将相同科目按水平重新编班上课，上完各回原班参加班级活动。这种做法属于（　）', '[["A","复式教学"],["B","班级授课制"],["C","个别教学"],["D","分组教学"]]', '["D"]', '分组教学是按学生的能力或学习成绩把他们分为水平不同的组进行教学。按科目水平重新组班上课后再回原班属于分组教学（走班制下的分层教学）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (851, 5, 41, 'single', 1.0, '化学课上，朱老师把生活中铁锅生锈、铜器发绿的例子和氧化还原反应的讲解结合起来，学生觉得抽象的方程式变“接地气”了。朱老师这一做法的主要特点是（　）', '[["A","用反复抄写方程式的方式加深记忆"],["B","从生活现象入手帮助学生理解书本上的反应原理"],["C","只讲结论，省去对生活实例的分析"],["D","借助考试排名督促学生背诵概念"]]', '["B"]', '理论联系实际原则要求从学生熟悉的铁锅生锈、铜器发绿等生活现象出发，帮助学生理解抽象的氧化还原原理，并引导用所学解释生活问题，体现了书本理论与生活实际相结合。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (852, 5, 42, 'single', 1.0, '朱老师课前认真研读课标教材、了解学生，上课时围绕目标组织教学，课后及时批阅作业并对有困难的学生进行辅导。从教学工作的基本环节看，其中处于中心环节的是（　）', '[["A","上课"],["B","作业的布置与批改"],["C","课外辅导"],["D","备课"]]', '["A"]', '教学工作包括备课、上课、作业布置与批改、课外辅导、学业成绩的检查与评定五个基本环节。其中上课是教学工作的中心环节，是提高教学质量的关键。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (853, 5, 43, 'single', 1.0, '针对梦洁等几名学生只关心分数、不愿帮助同学的问题，班主任没有简单批评，而是组织“互助之星”评选，引导学生在合作中体会帮助他人的快乐。这里主要运用的德育原则是（　）', '[["A","疏导原则"],["B","因材施教原则"],["C","长善救失原则"],["D","导向性原则"]]', '["A"]', '疏导原则指进行德育要循循善诱、以理服人，从提高学生认识入手，调动学生主动性，使他们积极向上。班主任不简单压制批评，而是借助活动引导学生自己体会助人的意义，重在疏通引导，符合疏导原则。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (854, 5, 44, 'single', 1.0, '高二（5）班从最初一盘散沙、各顾各的，到能围绕运动会共同分工、为班级荣誉互相鼓劲，这说明该班集体正处于（　）', '[["A","解散阶段"],["B","核心初步形成阶段"],["C","发展阶段（自主活动阶段）"],["D","组建阶段"]]', '["C"]', '班集体的形成一般经历组建、核心初步形成、发展（自主活动）和成熟等阶段。在发展阶段，班集体已成为教育主体，多数学生能相互严格要求、自主开展活动并认同共同目标。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (855, 5, 45, 'single', 1.0, '思琪习惯自己对着教材和提纲独立复习，人多讨论反而让她理不清思路；嘉豪则喜欢和同学一起讨论着学。这种差异主要属于（　）', '[["A","智力水平差异"],["B","性格类型差异"],["C","学习需要差异"],["D","认知方式（认知风格）差异"]]', '["D"]', '认知方式又称认知风格，是个体偏爱的信息加工方式，如场独立型与场依存型、独立学习与合作学习的偏好等。思琪偏独立、嘉豪偏讨论，体现的是认知方式差异。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (856, 5, 46, 'single', 1.0, '林老师发现，让学生反复做同一套题时学生会厌烦，而把已学公式放到新情境中让学生发现规律，他们反而记得牢、用得活。这种“自己发现”的学习更契合（　）', '[["A","斯金纳的程序教学思想"],["B","巴甫洛夫的经典条件作用理论"],["C","桑代克的试误说"],["D","布鲁纳的认知一结构学习理论"]]', '["D"]', '布鲁纳主张学习的目的在于以发现学习的方式，使学科的基本结构转变为学生头脑中的认知结构，强调主动发现而非被动接受。学生在新情境中自己发现规律，正契合发现学习思想。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (857, 5, 47, 'single', 1.0, '孙老师要求学生在作文中“先学会把一件事说清楚、写具体，再追求立意深刻”，认为只有会区分“写清楚”与“写深刻”的不同要求，水平才能真正提高。这种让学生辨别相似任务间细微差别、避免混淆的训练，依据的是（　）', '[["A","经典条件作用中的分化（辨别）"],["B","操作性条件作用中的惩罚"],["C","经典条件作用中的泛化"],["D","操作性条件作用中的正强化"]]', '["A"]', '分化（辨别）是指通过选择性强化和消退，使有机体学会对条件刺激和与条件刺激相类似的刺激作出不同反应。让学生辨别“写清楚”与“写深刻”这两类相似但不同的要求，正是辨别训练。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (858, 5, 48, 'single', 1.0, '俊杰主动帮老师整理了实验器材，孙老师当众表扬了他，此后他更愿意主动承担班级事务。孙老师运用的是（　）', '[["A","惩罚"],["B","消退"],["C","负强化"],["D","正强化"]]', '["D"]', '正强化是指呈现一个愉快刺激以提高行为发生概率。表扬是学生喜欢的刺激，受表扬后俊杰主动服务的行为增多，属于正强化。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (859, 5, 49, 'single', 1.0, '林老师上课时只给必要的引导和资料，让学生先说出自己的困惑，再围绕困惑共同探讨，他认为“学生不是等待装满的瓶子”。这种以学生为中心、强调无条件积极关注的教学思想来自（　）', '[["A","罗杰斯"],["B","加涅"],["C","布鲁纳"],["D","苛勒"]]', '["A"]', '人本主义心理学家罗杰斯主张以学生为中心的教学，强调教师作为“促进者”，应给予学生无条件积极关注、真诚与移情理解，反对把学生当作接受知识的容器。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (860, 5, 50, 'single', 1.0, '嘉豪家里经济不宽裕，近来总为生活费发愁，上课难以集中注意力。孙老师先帮他解决助学补助问题，再谈学习。这种“先解生活之忧、再谈求知向学”的做法，最契合（　）', '[["A","马斯洛的需要层次理论"],["B","阿特金森的成就动机理论"],["C","班杜拉的自我效能感理论"],["D","韦纳的归因理论"]]', '["A"]', '马斯洛把人的需要由低到高分为生理、安全、归属与爱、尊重和自我实现等层次，认为低层次需要基本满足后才会追求高层次需要。为生活发愁的学生难以产生强烈的求知需要，故先解后顾之忧。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (861, 5, 51, 'single', 1.0, '面对难度较大的压轴题，雅雯愿意主动挑战，认为即使做错也能学到东西；嘉豪却总避开难题，怕暴露自己“不行”。两人的差异主要体现了（　）', '[["A","学习迁移能力的差异"],["B","需要层次的差异"],["C","成就动机水平的差异"],["D","认知风格的差异"]]', '["C"]', '阿特金森认为成就动机由力求成功和避免失败两种倾向组成。力求成功者倾向选择中等难度、有挑战性的任务；避免失败者则倾向回避难题以防失败。雅雯敢挑战、嘉豪怕失败，体现成就动机差异。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (862, 5, 52, 'single', 1.0, '梦洁把目标定为“比上次的自己多拿十分、真正弄懂一个薄弱章节”，而不是只盯着超过某个同学。她的目标定向更偏向（　）', '[["A","外部目标定向"],["B","表现（成绩）目标定向"],["C","掌握（学习）目标定向"],["D","社会目标定向"]]', '["C"]', '掌握目标定向者关注能力的提高、任务的理解和自我进步，把努力和学习本身视为目的；表现目标定向者关注他人评价、显得聪明或胜过他人。梦洁以自我进步和真正弄懂为目标，属掌握目标定向。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (863, 5, 53, 'single', 1.0, '孙老师发现，学生学会了英语的一般疑问句结构后，再学特殊疑问句时常把两种句式搞混，后来者的学习反而受先前内容的拖累。对这种现象最恰当的描述是（　）', '[["A","前后两项学习之间互不影响"],["B","先前学的内容对后来的学习产生了干扰"],["C","后来学的内容巩固了先前的知识"],["D","先前内容帮助后来学习顺利进行"]]', '["B"]', '一般疑问句（先学）对特殊疑问句（后学）产生影响，方向上是先前影响后来（顺向）；造成混淆、起消极作用（负迁移），故选B。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (864, 5, 54, 'single', 1.0, '林老师讲物理时，先让学生做“水下击靶”式的铺垫练习，引导他们概括出“光从一种介质进入另一种介质会折射”的共同原理，学生再解决类似问题就顺利得多。这一教学思路最接近（　）', '[["A","共同要素说"],["B","概括化理论（经验类化说）"],["C","关系转换说"],["D","形式训练说"]]', '["B"]', '贾德的概括化理论（经验类化说）认为，迁移的关键不是两种情境表面相同，而是学习者概括出两类情境所共有的一般原理。“水下击靶”是其经典实验。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (865, 5, 55, 'single', 1.0, '学完“函数”这一大概念后，思琪再学“幂函数”时，把它归入已有的函数知识框架去理解。这种学习属于（　）', '[["A","下位学习（类属学习）"],["B","上位学习"],["C","并列结合学习"],["D","符号学习"]]', '["A"]', '下位学习又称类属学习，是将概括程度较低的新概念，归属于认知结构中原有概括程度较高的概念之下。“幂函数”概括程度低于“函数”，归入已有框架理解，属下位学习。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (866, 5, 56, 'single', 1.0, '背英语单词时，孙老师建议学生把一个新词读到恰能成诵后再适当多读几遍，而不是无限遍数地硬背。这种“达到标准后再增加一定量的学习”称为（　）', '[["A","过度学习"],["B","组块化"],["C","复习"],["D","复述"]]', '["A"]', '过度学习指在达到刚好能背诵（初步掌握）之后继续进行的学习，适度过度学习有利于保持，研究表明过度学习达到 150% 左右时记忆效果较好。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (867, 5, 57, 'single', 1.0, '数学老师要求学生解题时先在头脑中完整演示一遍“审题一找关系一列式一检验”的过程，再动笔。这种在头脑中借助内部言语完成的认知活动方式属于（　）', '[["A","操作技能"],["B","操作模仿"],["C","操作定向"],["D","心智技能"]]', '["D"]', '心智技能也称智力技能，是通过学习而形成的合乎法则的心智活动方式，借助内部言语在头脑中进行，如解题、运算、构思。先在头脑中走一遍解题过程，属于心智技能活动。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (868, 5, 58, 'single', 1.0, '复习时，嘉豪把政治教材中零散的知识点按“是什么一为什么一怎么做”整理成关系图。他运用的学习策略主要是（　）', '[["A","精加工策略"],["B","复述策略"],["C","资源管理策略"],["D","组织策略"]]', '["D"]', '组织策略是整合所学新知识之间、新旧知识之间的内在联系，形成新的知识结构，如列提纲、画关系图、归类。嘉豪整理关系图，属于组织策略。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (869, 5, 59, 'single', 1.0, '同样是“用一根蜡烛和一盒图钉把蜡烛固定在墙上”的任务，被提示过盒子可当容器的学生往往想不到盒子还能当烛台。这一现象说明影响问题解决的因素是（　）', '[["A","原型启发"],["B","正迁移"],["C","功能固着"],["D","动机强度"]]', '["C"]', '功能固着是指人们把某种功能赋予某物体的倾向，即只看到物品通常的用途而看不到它可能有的其他用途。只把盒子当容器、想不到当烛台，正是功能固着。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (870, 5, 60, 'single', 1.0, '雅雯每次大考前都心跳加快、脑子一片空白，明明会做的题也想不起来。最适合帮助她的心理辅导方法是（　）', '[["A","消退法"],["B","系统脱敏法"],["C","惩罚法"],["D","强化法"]]', '["B"]', '系统脱敏法由沃尔帕创立，主要用于治疗恐惧和焦虑反应，通过建立焦虑等级、配合放松训练逐级减轻敏感，是治疗考试焦虑的常用有效方法。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (871, 5, 61, 'single', 1.0, '孙老师并不明说对哪个学生抱多大期望，但她对俊杰的提问更有耐心、反馈更及时，半学期后俊杰的成绩和自信都明显提升。这一现象最能说明（　）', '[["A","学生智力是成绩的唯一决定因素"],["B","课堂纪律越好成绩必然越高"],["C","教师通过态度行为传递的期望会影响学生表现"],["D","教师的成长阶段决定学生成绩"]]', '["C"]', '罗森塔尔效应（皮格马利翁效应、教师期望效应）表明，教师的期望会通过其无意识的态度、提问和反馈传递给学生，学生按教师期望的方向发展，期望成真。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (872, 5, 62, 'single', 1.0, '入职第一年的林老师最担心的是“学生喜不喜欢我、同事怎么看我、领导是否认可我”。按福勒的教师成长阶段理论，他处于（　）', '[["A","关注情境阶段"],["B","关注待遇阶段"],["C","关注学生阶段"],["D","关注生存阶段"]]', '["D"]', '福勒和布朗把教师成长分为关注生存、关注情境和关注学生三个阶段。新教师通常处于关注生存阶段，最关注自己的生存适应性，如学生、同事和领导是否喜欢、认可自己。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (873, 5, 63, 'single', 1.0, '带高三的林老师近一年常觉得“干这行没什么意思”，对学生不冷不热，一想到上班就发忧。从教师心理角度看，他的状态最可能属于（　）', '[["A","认知失调"],["B","职业倦怠"],["C","高原现象"],["D","教师的角色冲突"]]', '["B"]', '职业倦怠是个体在长期工作压力下产生的情绪衰竭、去人性化（对服务对象冷漠疏远）和个人成就感低落的综合征，林老师情绪疲惫、对学生冷漠、怀疑工作意义符合其典型表现。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (874, 5, 64, 'single', 1.0, '某校规定教师必须“自愿”捐款用于校庆，从工资里统一扣除，不愿捐的教师被要求写情况说明。这一做法主要侵犯了教师的（　）', '[["A","学术研究权"],["B","民主管理权"],["C","教育教学权"],["D","获取劳动报酬和享受福利待遇的权利"]]', '["D"]', '教师有权按时获取工资报酬、享受国家规定的福利待遇，任何单位和个人不得克扣、挪用或变相强索。强制“捐款”并从工资中扣除，实质是变相克扣工资，侵犯获取报酬权。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (875, 5, 65, 'single', 1.0, '孙老师在家长会上公布了“倒数后十名”名单，并让这些学生站起来让家长认领。这一做法主要侵犯了学生的（　）', '[["A","受教育权"],["B","财产权"],["C","休息权"],["D","人格尊严"]]', '["D"]', '人格尊严权要求尊重学生人格，不得对学生实施体罚、变相体罚或其他侮辱人格尊严的行为。公布排名并当众点名示众，使学生在家长和同学面前蒙受羞辱，侵犯人格尊严。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (876, 5, 66, 'single', 1.0, '高中生宇航把自己写的科幻小说交给朱老师，朱老师在未署名宇航的情况下，将小说收入自己主编的校本读物出版。朱老师主要侵犯了宇航的（　）', '[["A","著作权（知识产权）"],["B","受教育权"],["C","隐私权"],["D","肖像权"]]', '["A"]', '著作权法保护作者对其创作的文学作品享有的人身权和财产权，作品一经创作完成即受保护，与作者年龄无关。朱老师未署名并将他人作品据为己有出版，侵犯署名权等著作权。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (877, 5, 67, 'single', 1.0, '某机构未经审批擅自举办“高考冲刺学校”并对外招生收费，教育行政部门发现后责令其停止办学。责令停止办学在性质上属于（　）', '[["A","民事调解"],["B","行政许可"],["C","行政强制措施"],["D","行政指导"]]', '["C"]', '责令停止违法办学是行政机关为制止违法行为、防止危害扩大而采取的行政强制措施（行政处理），针对未经许可的办学行为。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (878, 5, 68, 'single', 1.0, '民办学校在具备法定条件后，向审批机关申请、经批准取得办学许可证方可招生。颁发办学许可证属于（　）', '[["A","行政裁决"],["B","行政征收"],["C","行政许可"],["D","行政处罚"]]', '["C"]', '行政许可是行政机关根据公民、法人或其他组织的申请，经依法审查，准予其从事特定活动的行为。取得办学许可证意味着获准从事办学活动，属于行政许可。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (879, 5, 69, 'single', 1.0, '孙老师在家访时发现学生梦洁身上有疑似被家人长期殴打的伤痕，他犹豫“这是别人家事”，但仍在当天就向公安、民政部门反映了情况。对孙老师这一做法评价正确的是（　）', '[["A","做法正确，发现疑似伤害情形立即报告是法律要求做的事"],["B","多此一举，这是别人的家务事，老师不该插手"],["C","应等掌握全部确凿证据后再反映，否则会诬告"],["D","应先征得学校和家长双方同意后再反映"]]', '["A"]', '《未成年人保护法》规定，密切接触未成年人的单位及其工作人员，发现未成年人受到或疑似受到侵害、面临危险的，应当立即向公安、民政、教育等部门报告，不以证据完全确凿或他人同意为前提。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (880, 5, 70, 'single', 1.0, '午休时，校外人员翻墙入校将高一学生嘉豪打伤。经查学校保安脱岗、围墙存在缺口。关于学校的责任，下列说法正确的是（　）', '[["A","应由侵权人承担责任，学校未尽管理职责的承担相应补充责任"],["B","学校应承担全部赔偿责任后再向侵权人追偿"],["C","学校应与侵权人平均分担全部损失"],["D","学校不是侵权人，一律不承担任何责任"]]', '["A"]', '无民事行为能力人或限制民事行为能力人在学校学习、生活期间受到校外第三人人身损害的，由第三人承担侵权责任；学校未尽到管理职责的，承担相应的补充责任，承担后可向第三人追偿。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (881, 5, 71, 'single', 1.0, '朱老师对教育局作出的撤销其“骨干教师”称号的处理不服，认为事实认定有误。他寻求救济时，一般可以（　）', '[["A","只能向原处理人口头申辩"],["B","依法申请行政复议或提起行政诉讼"],["C","直接提起民事诉讼"],["D","向公安机关报案"]]', '["B"]', '公民认为行政机关的具体行政行为侵犯其合法权益，可依法申请行政复议，对复议不服或在法定情形下直接提起行政诉讼。教育局的处理属行政行为，故可走复议或诉讼。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (882, 5, 72, 'single', 1.0, '根据《中华人民共和国义务教育法》，关于适龄儿童少年接受义务教育，下列说法正确的是（　）', '[["A","只招收本地户籍学生"],["B","免试就近入学"],["C","可由学校收取一定学费"],["D","以考试成绩择优录取"]]', '["B"]', '义务教育法规定适龄儿童、少年免试入学，地方各级人民政府应保障其在户籍所在地学校就近入学；义务教育不收学费、杂费，并依法保障随迁子女平等接受义务教育。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (883, 5, 73, 'single', 1.0, '家长悄悄给林老师送来购物卡，希望老师给自家孩子“安排个好座位、多给些机会”。林老师最恰当的处理是（　）', '[["A","婉言谢绝，像对待其他学生一样公平对待这名学生"],["B","先收下礼物，再悄悄给他孩子安排好座位"],["C","收下后在家长群里公开此事"],["D","把购物卡转送给其他老师做人情"]]', '["A"]', '教师应廉洁从教，不利用职务便利收受财物、谋取私利，对所有学生一视同仁，故应婉拒购物卡并公平施教。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (884, 5, 74, 'single', 1.0, '学校推行新课改，孙老师觉得自己教了多年“换汤不换药”，仍按老一套满堂灌，拒绝参加任何培训。孙老师主要违背了（　）', '[["A","终身学习"],["B","关爱学生"],["C","为人师表"],["D","爱国守法"]]', '["A"]', '终身学习要求教师崇尚科学精神，树立终身学习理念，拓宽知识视野、更新知识结构，潜心钻研业务、不断提高专业素养和教育教学水平。孙老师固步自封、拒绝更新，主要违背终身学习。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (885, 5, 75, 'single', 1.0, '某高中教师把所教学科的时间无限加码，认为“只要高考能得分，学生体不体育、快不快乐无关紧要”。这种做法最不符合素质教育所强调的（　）', '[["A","以培养学生应试能力为唯一任务"],["B","按统一标准选拔学生"],["C","以提高国民素质为根本宗旨，促进学生全面发展"],["D","以教师讲授为教学的唯一方式"]]', '["C"]', '素质教育以提高国民素质为根本宗旨，面向全体学生，促进学生德智体美全面发展和主动、活泼地发展，重视创新精神和实践能力。只盯高考分数、忽视身心健康与全面发展，背离素质教育宗旨。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (886, 5, 76, 'single', 1.0, '新课改要求教师不再只是“知识的搬运工”。下列做法最能体现教师作为“学生学习和发展的促进者”这一角色的是（　）', '[["A","以纪律约束保证课堂绝对安静"],["B","把结论直接讲给学生并要求背诵"],["C","创设情境、引导学生自主合作探究并关注其情感发展"],["D","代替学生安排学习中的一切事务"]]', '["C"]', '新课改教师观要求教师从知识传授者转变为学生学习的引导者、促进者和学生发展的引路人，从“教书匠”转变为教育教学的研究者、课程的建设者。创设情境、引导探究并关注情感，正是促进者角色。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (887, 5, 77, 'single', 1.0, '学校安排学生每周走进社区，就居民关注的垃圾分类问题开展调查、设计宣传方案并动手参与志愿服务，全程在真实情境中研究和解决问题。这一安排最符合下列哪类课程的定位？（　）', '[["A","以统一笔试分数作为唯一评价依据的课程"],["B","组织学生围绕真实问题开展调查、设计方案并亲身实践的活动课程"],["C","学校可随意增减课时、随时取消的课程"],["D","教师系统讲授学科概念、学生听讲记笔记的课程"]]', '["B"]', '综合实践活动课程是从小学到高中设置的必修课程，以研究性学习、社区服务与社会实践等为主要内容，强调学生在亲身实践中发展创新精神和实践能力。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (888, 5, 78, 'single', 1.0, '备课中，孙老师反复思考“这门课要教到什么程度、用什么衡量学生是否达到要求”，并据此确定教学的方向和检查依据。这里所依据的、规定学科教学目标与要求的纲领性文件是（　）', '[["A","课程标准"],["B","课程计划"],["C","教科书"],["D","教学参考书"]]', '["A"]', '课程标准是国家课程的基本纲领性文件，规定学科的课程性质、目标、内容标准和实施建议，是教材编写、教学、评估和考试命题的依据。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (889, 5, 79, 'single', 1.0, '某教师在课堂上公然散布贬低国家制度、与课程育人目标相悖的错误言论，学生提出异议反被其嘲讽。根据《新时代中小学教师职业行为十项准则》，该教师首先违背了（　）', '[["A","坚守廉洁自律"],["B","坚定政治方向"],["C","加强安全防范"],["D","秉持公平诚信"]]', '["B"]', '《新时代中小学教师职业行为十项准则》第一条即“坚定政治方向”，要求教师拥护中国共产党的领导、拥护社会主义制度，不得在教育教学活动中及其他场合发表损害党中央权威、违背党的路线方针政策的言论。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (890, 5, 80, 'single', 1.0, '新课改实行国家、地方、学校三级课程管理。孙老师结合学校航天特色和学生兴趣，组织教师开发并实施“航天探秘”校本课程。从课程管理与开发的角度看，开设此类课程最主要体现了学校拥有一定的（　）', '[["A","考试命题权"],["B","课程编制与管理权"],["C","教材审定权"],["D","课程评价权"]]', '["B"]', '三级课程管理在保障国家课程的前提下，赋予地方和学校一定的课程管理权，学校可在落实国家课程、地方课程的基础上，结合实际开发适合本校的校本课程。孙老师组织开发校本课程，正体现学校的课程编制与管理权。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (891, 5, 81, 'multi', 1.6, '孙老师准备一节高二语文公开课。下列做法中，能够体现启发性原则的有（　）', '[["A","学生思考卡壳时给予适当点拨，引导其自己得出结论"],["B","对学生的发言只记结论对错，不作任何追问"],["C","提出有思考空间的问题，给学生留出独立思考的时间"],["D","鼓励学生大胆质疑，允许提出不同看法"],["E","把参考答案先写在黑板上，让学生照着记"]]', '["A","C","D"]', 'C应选：启发性原则强调调动学生思维，提出有价值的问题、留足思考时间是基本做法。B不选：只判对错、不追问，难以激发深度思考。D应选：鼓励质疑、容许多元看法，能培养学生独立思考与批判精神。A应选：适时点拨而非直接告知答案，引导学生自己得出结论。E不选：先公布答案让学生照记，剥夺了思考过程。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (892, 5, 82, 'multi', 1.6, '林老师接手一个班风松散的高二班级，希望通过德育工作改变面貌。下列做法符合德育原则的有（　）', '[["A","发现并放大学生身上的闪光点，用优点带动缺点的改正"],["B","只盯着问题学生反复批评，对多数学生不闻不问"],["C","循循善诱，先讲清道理再提出要求"],["D","充分发挥班集体的教育作用，把个别教育与集体教育结合起来"],["E","争取科任教师和家长形成一致要求，避免各说各话"]]', '["A","C","D","E"]', 'C应选：循循善诱、以理服人体现疏导原则。A应选：依靠积极因素克服消极因素体现长善救失原则。E应选：统一学校、家庭等各方面教育影响，体现教育影响的一致性与连贯性原则。B不选：只盯少数问题学生、忽视面向全体。D应选：通过集体教育个人、又通过个别影响集体，体现集体教育与个别教育相结合原则。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (893, 5, 83, 'multi', 1.6, '为激发学生的学习动机，朱老师尝试了多种办法。下列做法恰当的有（　）', '[["A","只以名次和奖惩刺激学生，制造持续的紧张压力"],["B","引导学生树立掌握目标，关注自身进步而非只盯排名"],["C","帮助学生把学习上的失败多归因于努力程度等可控因素"],["D","创设“跳一跳够得着”的问题情境，使学生获得成功体验"],["E","妥善组织竞赛与合作，使多数学生都有获胜机会"]]', '["B","C","D","E"]', 'C应选：努力是内部、可控、不稳定因素，努力归因能增强坚持性。D应选：难度适中的问题与成功体验可提高自我效能感、激发动机。E应选：合理的竞赛合作、让多数人有机会成功，能调动积极性。A不选：单纯依靠名次奖惩、制造过度紧张，易使学生形成避免失败动机。B应选：掌握目标定向关注理解与自我提高，有利于形成持久的内在动机。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (894, 5, 84, 'multi', 1.6, '复习阶段，孙老师指导学生合理使用学习策略。下列属于元认知策略的有（　）', '[["A","学习前根据任务制定复习计划"],["B","发现注意力涣散时及时调整状态、放慢速度重读"],["C","阅读时监控自己是否真正理解了材料"],["D","对重要内容反复朗读、画线"],["E","把零散知识整理成提纲和关系图"]]', '["A","B","C"]', 'A应选：根据目标任务预先安排学习活动，属元认知计划策略。C应选：对自己理解程度和注意状态的觉察，属元认知监控策略。B应选：根据监控结果采取补救措施、调整学习节奏，属元认知调节策略。D不选：反复朗读、画线是复述策略。E不选：列提纲、画关系图是组织策略。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (895, 5, 85, 'multi', 1.6, '为培养学生的创造性，林老师在教学中可以采取的做法有（　）', '[["A","给学生提供选择和自主决定的空间"],["B","保护学生的好奇心，鼓励质疑问难"],["C","对任何与众不同的答案一律判错以统一标准"],["D","创设宽松、安全的心理氛围，容忍学生“奇怪”的想法"],["E","鼓励学生从多个角度思考同一问题"]]', '["A","B","D","E"]', 'D应选：民主、安全、容许失误的心理环境是创造性产生的重要条件。E应选：引导多角度、发散式思考，有助于思维的流畅性、变通性。A应选：自主性和选择空间能激发内在动机和独创性。C不选：对与众不同的答案一律判错，会压制发散思维和冒险尝试。B应选：好奇心和质疑精神是创造性的重要源泉。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (896, 5, 86, 'multi', 1.6, '课堂上嘉豪经常故意发出怪声、打扰邻座。孙老师处理这一问题行为时恰当的做法有（　）', '[["A","对其积极学习的微小进步及时强化"],["B","先用目光、走近等非言语信号给予提示"],["C","动辄停课训斥并将其赶出教室"],["D","对为博取关注的怪声不予关注，使其得不到想要的强化"],["E","查明行为背后的原因，有针对性地引导"]]', '["A","B","D","E"]', 'B应选：非言语提示既制止行为又不打断教学、保全学生面子。E应选：问题行为背后常有求关注、求发泄等原因，查明原因才能对症下药。A应选：及时强化良好行为，用积极行为替代问题行为。C不选：频繁训斥、赶出教室既侵犯受教育权，也易激化对立。D应选：对以获得关注为目的的行为不给予关注，可使行为因得不到强化而消退。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (897, 5, 87, 'multi', 1.6, '教高三的林老师近来常感到精疲力竭，对学生失去耐心，甚至怀疑工作意义。为走出这种状态，可取的应对办法有（　）', '[["A","必要时寻求专业心理帮助"],["B","合理安排工作与休息，避免长期透支"],["C","重新审视职业意义，建立合理期望"],["D","主动与同事、家人倾诉，寻求社会支持"],["E","把消极情绪随意发泄到学生身上"]]', '["A","B","C","D"]', '题干描述的是教师职业倦怠。B应选：劳逸结合、科学管理时间有助于恢复。D应选：社会支持是缓解倦怠的重要资源。C应选：合理期望、发现工作价值可增强职业认同。E不选：迁怒学生会伤害师生关系，违反关爱学生要求。A应选：难以自我调节时寻求专业帮助是积极负责的做法。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (898, 5, 88, 'multi', 1.6, '某校发生学生伤害事故，各方对责任承担产生分歧。根据教育法律责任的相关知识，下列说法正确的有（　）', '[["A","学校因过错造成损害，主要承担相应的民事赔偿责任"],["B","三种法律责任可以由学校、教师、行政机关等不同主体分别承担"],["C","只要发生伤亡结果，学校一律承担刑事责任"],["D","行为情节严重、构成犯罪的，应依法追究刑事责任"],["E","教育行政机关对违法办学行为可依法追究行政责任"]]', '["A","B","D","E"]', 'A应选：学生伤害事故中学校有过错的，承担以赔偿损失为主的民事责任。E应选：行政机关对违反教育行政管理秩序的行为可给予行政处罚、处分。D应选：严重违法构成犯罪时追究刑事责任。C不选：刑事责任以符合犯罪构成、行为人主观有罪过为前提。B应选：同一事故中可能并存民事、行政、刑事责任。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (899, 5, 89, 'multi', 1.6, '高二体育课篮球赛中，俊杰在正常对抗中被同学撞倒受伤，事后家长认为学校未尽到责任。经查，体育老师事前讲清了规则和安全注意事项，场地器材合格，事故发生后及时送医。关于本案，下列认识正确的有（　）', '[["A","只要学生在校受伤，无论学校有无过错都必须全额赔偿"],["B","学校尽到教育、管理和救助职责的，可依法不承担或减轻责任"],["C","篮球等具有一定风险的文体活动，参加者对正常风险应有一定认知"],["D","学校仍应做好事故处置、沟通和风险防范工作"],["E","对方同学有无故意或重大过失，是判断其是否担责的重要因素"]]', '["B","C","D","E"]', 'C应选：《民法典》规定的自甘风险规则。B应选：学校对限制民事行为能力人受伤承担过错责任，已尽教育管理救助职责则无过错。E应选：其他参加者仅在有故意或重大过失时才担责。A不选：学校责任以过错为前提。D应选：免责不等于免责之外的教育关怀。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (900, 5, 90, 'multi', 1.6, '关于未成年学生的法律保护，下列判断正确的有（　）', '[["A","父母或其他监护人应当履行监护职责和抚养义务"],["B","任何组织或个人不得披露未成年人个人隐私"],["C","对有严重不良行为的未成年人可以放任不管"],["D","学校不得因学生家庭、性别、民族等歧视学生"],["E","公安机关等应为未成年人提供司法保护并保护其名誉隐私"]]', '["A","B","D","E"]', 'A应选：家庭保护要求监护人依法履行监护与抚养义务。D应选：学校保护要求尊重学生人格、平等对待，禁止歧视。B应选：未成年人隐私权和个人信息受法律保护。C不选：对有不良或严重不良行为的未成年人应及时干预、教育矫治。E应选：司法机关办理涉未成年人案件时应照顾其身心特点、保护名誉与隐私。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (901, 6, 1, 'judge', 0.6, '山乡教学点，何老师对罗老师说：“教育是有目的地培养人的社会活动，与人类社会共始终。”', '[["A","正确"],["B","错误"]]', '["A"]', '教育的本质是有目的地培养人的社会活动，且教育具有永恒性，与人类社会共始终。何老师的表述同时准确反映了教育的本质属性和永恒性。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (902, 6, 2, 'judge', 0.6, '高老师常对家长说：“山里娃能不能成才，全看家里的祖坟和天分，学校教不教并不打紧。”', '[["A","正确"],["B","错误"]]', '["B"]', '这种说法片面夸大遗传素质的作用，否认了学校教育在个体身心发展中的主导作用。遗传只是生理前提，为人的发展提供可能性，环境与学校教育（起主导作用）才把可能变为现实。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (903, 6, 3, 'judge', 0.6, '政治学习时，罗老师说：“确定教育目的首先考虑社会需要、个人发展要服从社会要求，这属于个人本位论。”', '[["A","正确"],["B","错误"]]', '["B"]', '从社会需要出发确定教育目的、主张个人发展服从社会要求，是社会本位论的观点；个人本位论主张教育目的应根据个人发展需要制定。罗老师张冠李戴。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (904, 6, 4, 'judge', 0.6, '何老师整理学制沿革时写道：1904年颁布的“癸卯学制”，是我国第一个正式实施的现代学制。', '[["A","正确"],["B","错误"]]', '["A"]', '1902年“壬寅学制”是我国第一个颁布但未实施的现代学制；1904年“癸卯学制”是第一个正式实施的现代学制。何老师表述准确。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (905, 6, 5, 'judge', 0.6, '三年级志强坐得住、爱琢磨，建军爱跑动、手不停，高老师便给两人布置完全相同的抄写任务，认为这样才公平。', '[["A","正确"],["B","错误"]]', '["B"]', '同一年龄阶段的学生在兴趣、性格、能力等方面存在个别差异，教育应因材施教，针对不同学生提出不同要求、采用不同方法。“一刀切”恰恰违背了个别差异性和因材施教原则。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (906, 6, 6, 'judge', 0.6, '读书角挂着名句“道而弗牵，强而弗抑，开而弗达”，何老师说它重在提醒教师引导而不包办。', '[["A","正确"],["B","错误"]]', '["A"]', '“道而弗牵，强而弗抑，开而弗达”意为引导学生而不牵着走、激励学生而不压抑、启发学生而不直接把道理说尽，体现的是启发性教学思想。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (907, 6, 7, 'judge', 0.6, '春燕一学期没交作业，罗老师既不催问也不联系其在外打工的家长，只说“学不学全靠自觉”。', '[["A","正确"],["B","错误"]]', '["B"]', '教师对学生的学习和发展负有教育、管理和保护职责。罗老师对学生长期不交作业不闻不问，属于放任型的师生关系与管理方式，未尽教师职责。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (908, 6, 8, 'judge', 0.6, '何老师带学生上山辨认草药、走访老村医，再回课堂整理成图文笔记。她称这是以学科知识为中心的学科课程。', '[["A","正确"],["B","错误"]]', '["B"]', '该课程从儿童的兴趣和经验出发，以活动为中心组织学习，属于活动课程（经验课程）；学科课程是以学科知识为中心、按学科逻辑编排的课程。何老师判断错误。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (909, 6, 9, 'judge', 0.6, '高老师刚接手新班，学生互不熟悉、大小事务都等她安排，她却判断班级已进入成熟阶段。', '[["A","正确"],["B","错误"]]', '["B"]', '班集体的形成依次经历组建阶段、核心形成阶段、发展阶段（自主活动阶段）和成熟阶段。班级刚组建、依赖班主任安排，属于组建阶段，远未成熟。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (910, 6, 10, 'judge', 0.6, '何老师告诉实习生：教育心理学作为一门独立学科，是以桑代克1903年出版《教育心理学》为标志的。', '[["A","正确"],["B","错误"]]', '["A"]', '1903年桑代克出版《教育心理学》，后扩充为三卷本，奠定了教育心理学的学科基础，被视为教育心理学成为独立学科的标志。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (911, 6, 11, 'judge', 0.6, '志强能把木棍按长短排好，也知道水从矮杯倒进高杯总量没变。高老师据此断定他已进入形式运算阶段。', '[["A","正确"],["B","错误"]]', '["B"]', '守恒和序列化（可逆的逻辑排序）是具体运算阶段（约7—11岁）的典型特征；形式运算阶段以抽象假设推理为标志。志强处于具体运算阶段。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (912, 6, 12, 'judge', 0.6, '罗老师给晓梅布置的任务，总停留在她已经能独立完成的水平上，认为这样最能促进学生发展。', '[["A","正确"],["B","错误"]]', '["B"]', '维果斯基提出“最近发展区”理论，主张教学应着眼于学生现有水平与在成人帮助下可达到水平之间的区域，教学要走在发展的前面。只布置已能独立完成的任务不能有效促进发展。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (913, 6, 13, 'judge', 0.6, '志强说“考砸全怪出题太偏、运气不好”，何老师便用“求诸人不如求诸己”提醒他多从自身努力找原因。', '[["A","正确"],["B","错误"]]', '["A"]', '按韦纳成败归因理论，试题难度、运气都属于外部、不可控因素；把失败归于此类因素会削弱学习动机。教师引导学生转向内部、可控的努力归因，有助于激发后续学习动力。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (914, 6, 14, 'judge', 0.6, '高老师爱搞突然袭击式的随堂默写，认为学生应随时处于待命状态。这违背了桑代克提出的准备律。', '[["A","正确"],["B","错误"]]', '["A"]', '桑代克学习三律中的准备律，指学习者在学习开始前是否有预备状态会影响学习效果与情绪。突袭式默写使学生毫无准备，容易挫伤学习积极性，确属违背准备律。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (915, 6, 15, 'judge', 0.6, '学生一坐好，罗老师就停止对他的批评。她认为这样会减少学生坐好的行为。', '[["A","正确"],["B","错误"]]', '["B"]', '撤销一个厌恶刺激（批评）以增加目标行为（坐好）发生的概率，属于斯金纳操作性条件作用中的负强化，会增加而不是减少该行为。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (916, 6, 16, 'judge', 0.6, '建军看到志强主动帮食堂收碗筷受到大会表扬，第二天也学着帮忙。何老师说这是建军本人直接受到强化的结果。', '[["A","正确"],["B","错误"]]', '["B"]', '观察者因看到榜样的行为受到强化而间接受到强化，班杜拉称之为替代强化。建军是观察榜样受表扬后模仿，并非本人直接受到强化。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (917, 6, 17, 'judge', 0.6, '罗老师认为农村娃见识少、脑袋空，教学就是往空容器里灌知识，灌得越多成绩越好。', '[["A","正确"],["B","错误"]]', '["B"]', '建构主义学习理论认为，学生不是空着脑袋走进教室的，他们在日常生活和已有学习中形成了丰富经验，学习是学生主动建构意义的过程。“空容器灌输”忽视学生的已有经验和主动性。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (918, 6, 18, 'judge', 0.6, '何老师对实习生说：“学生学了汉语拼音后，再读英语字母常把a读成‘啊’，这属于正迁移。”', '[["A","正确"],["B","错误"]]', '["B"]', '一种学习对另一种学习产生干扰、阻碍作用，属于负迁移；起促进作用的才是正迁移。汉语拼音干扰英语字母认读，是负迁移。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (919, 6, 19, 'judge', 0.6, '晓梅初学解应用题时，何老师先带她看老师完整的解题过程、明确每一步先做什么。何老师说这是原型内化阶段。', '[["A","正确"],["B","错误"]]', '["B"]', '心智技能形成包括原型定向、原型操作、原型内化三个阶段。了解、明确心智活动的实践模式（知道先做什么后做什么），属于原型定向阶段，而非原型内化。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (920, 6, 20, 'judge', 0.6, '几次考试接连失败后，秀英干脆放弃努力，认定“再怎么学都没用”。高老师判断这是习得性无助的表现。', '[["A","正确"],["B","错误"]]', '["A"]', '个体多次经历无法控制的失败后，产生无论怎样努力都无法改变结果的无助感，并因此放弃努力，心理学上称为习得性无助。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (921, 6, 21, 'judge', 0.6, '何老师在教研会上说：“教育部制定的规章，效力高于国务院制定的行政法规。”', '[["A","正确"],["B","错误"]]', '["B"]', '根据我国法律规范效力层级，宪法具有最高效力，法律高于行政法规，行政法规高于地方性法规和规章。国务院行政法规的效力高于教育部部门规章。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (922, 6, 22, 'judge', 0.6, '同学在培训班代课，自恃讲得好，没教师资格证也准备长期从教。罗老师告诉他从教须依法取得教师资格。', '[["A","正确"],["B","错误"]]', '["A"]', '《中华人民共和国教师法》规定，国家实行教师资格制度，中国公民在各级各类学校和其他教育机构中专门从事教育教学工作，应当依法取得教师资格。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (923, 6, 23, 'judge', 0.6, '为“教育”学生，高老师把春燕写满家庭隐私的日记本在班会上当众念给全班听。', '[["A","正确"],["B","错误"]]', '["B"]', '日记属于学生个人私密信息，未经允许公开他人日记，侵犯了未成年人的隐私权，也伤害其人格尊严。教师应通过个别谈心等正当方式了解、教育学生。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (924, 6, 24, 'judge', 0.6, '何老师发现建军身上有疑似被家人殴打留下的伤痕，觉得这是“别人家的家务事”，不打算向任何部门反映。', '[["A","正确"],["B","错误"]]', '["B"]', '《中华人民共和国未成年人保护法》规定了强制报告制度：任何组织或者个人发现未成年人身心健康受到侵害、疑似受到侵害的，应当及时向公安、民政、教育等有关部门报告。何老师必须报告。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (925, 6, 25, 'judge', 0.6, '罗老师罚违纪的志强在烈日下跑二十圈致其中暑，她认为这只是“教育方式严格”，无须承担任何法律责任。', '[["A","正确"],["B","错误"]]', '["B"]', '体罚学生或变相体罚学生造成人身伤害的，不仅违反教师职业道德和《义务教育法》《未成年人保护法》，还应根据情节与后果承担相应的行政责任乃至民事、刑事责任。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (926, 6, 26, 'judge', 0.6, '寄宿学生晓梅不适应住校生活，家长申请把她转回本村教学点就读，乡中心校一律不予批准、不办理相关手续。', '[["A","正确"],["B","错误"]]', '["B"]', '《中华人民共和国义务教育法》保障适龄儿童、少年免试就近入学的权利，学生因居住地等情况变化需要转学的，学校和有关部门应依法办理，保障其平等接受义务教育。学校一律不批没有法律依据。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (927, 6, 27, 'judge', 0.6, '何老师在教研组说：“教师职业道德的灵魂是爱岗敬业，课上得好、分数教得高，就算师德高尚。”', '[["A","正确"],["B","错误"]]', '["B"]', '《中小学教师职业道德规范》（2008年）中，关爱学生是师德的灵魂，爱岗敬业是教师职业的本质要求，教书育人是教师的天职。何老师把“灵魂”安错了位置。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (928, 6, 28, 'judge', 0.6, '罗老师认为“为人师表”就是衣着时髦、能说会道，跟家长、学生打交道不必太较真，随和就行。', '[["A","正确"],["B","错误"]]', '["B"]', '为人师表是教师职业的内在要求，要求教师坚守高尚情操、知荣明耻、严于律己、以身作则，衣着得体、语言规范、举止文明，廉洁奉公。罗老师把它狭隘化为外表与“随和”，理解错误。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (929, 6, 29, 'judge', 0.6, '家长群里有人说“送礼请吃饭老师尽管收”，何老师当即明确：礼品礼金不能收，公平施教是教师本分。', '[["A","正确"],["B","错误"]]', '["A"]', '《中小学教师职业道德规范》和《新时代中小学教师职业行为十项准则》均要求教师坚守廉洁自律，不得收受学生及家长财物、不得利用职务谋取私利。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (930, 6, 30, 'judge', 0.6, '罗老师说：“新课改提倡自主学习，就是让学生自己看书、自己做题，老师可以少教甚至不教。”', '[["A","正确"],["B","错误"]]', '["B"]', '自主学习是学生作为学习主体、主动自觉地学习，并不意味着教师退出。教师在自主学习中仍承担组织者、引导者、合作者的角色。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (931, 6, 31, 'single', 1.0, '教学点老教师何老师常说：“育人不能只盯着眼前这几本教材，要先把人立起来。”她推崇孔子“君子不器”的主张。下列最能体现孔子这一教育思想的是（　）', '[["A","教育应完全按学生兴趣自然发展，不需要任何目标"],["B","教育的目的是培养德才兼备、有理想人格的人，而非仅具一技一能的工具"],["C","教育的唯一任务是把生产劳动技能传给学生"],["D","教育只关注社会等级秩序，个人品德无关紧要"]]', '["B"]', '“君子不器”强调君子不能像器具那样只具备某一种用途，孔子主张培养具有完整人格和道德修养的人，教育目标以德行为先、全面发展。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (932, 6, 32, 'single', 1.0, '罗老师带着“生活即教育”“社会即学校”“教学做合一”的理念到乡村任教，带学生在种茶、制茶中学习。最直接提出这些主张的教育家是（　）', '[["A","黄炎培"],["B","陶行知"],["C","蔡元培"],["D","陈鹤琴"]]', '["B"]', '“生活即教育”“社会即学校”“教学做合一”是陶行知生活教育理论的核心命题。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (933, 6, 33, 'single', 1.0, '新教师高老师把山里孩子认作“白纸”，认为社会有什么样的要求，就可以在这张纸上画出什么样的人。这一观点在教育起源或本质问题上最接近（　）', '[["A","教育目的的社会本位取向"],["B","心理起源说"],["C","神话起源说"],["D","生物起源说"]]', '["A"]', '以社会要求规定教育所要培养的人的规格，强调个人是被社会塑造的对象，体现的是社会本位的教育目的取向。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (934, 6, 34, 'single', 1.0, '近年来县财政持续增加对乡村学校的投入，新修宿舍、配备仪器；反过来，学校培养的一批批学生又成为乡村振兴的骨干。这一现象主要说明（　）', '[["A","教育决定生产力发展水平"],["B","生产力发展为教育提供条件，教育又通过培养人才反作用于生产力"],["C","教育与生产力之间彼此独立、互不影响"],["D","只要有了物质投入，教育质量必然提高"]]', '["B"]', '生产力的发展为教育提供物质基础（校舍、设备、经费），教育则通过培养劳动力、传播科学技术促进生产力发展，二者相互制约、相互促进。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (935, 6, 35, 'single', 1.0, '晓梅一年级时对数字特别敏感、学得快，三年级时语言表达又突飞猛进，高老师说“这孩子每个方面都有冒头的时候”。这一说法对应的身心发展规律是（　）', '[["A","不平衡性"],["B","顺序性"],["C","互补性"],["D","阶段性"]]', '["A"]', '个体身心发展的不平衡性表现在同一方面在不同年龄阶段发展速度不均衡，以及不同方面发展的起止时间、成熟进程不同，存在发展的关键期。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (936, 6, 36, 'single', 1.0, '落实“五育并举”，多中心小学既抓文化课，又组织劳动实践、体育锻炼和艺术活动。下列对全面发展教育组成的表述，正确的是（　）', '[["A","乡村学校条件差，只抓智育也符合全面发展要求"],["B","由德育、智育、体育、美育和劳动技术教育构成，各育相互联系、相互促进"],["C","以智育为核心，其余四育可有可无"],["D","五育平均分配时间、内容完全相同才叫全面"]]', '["B"]', '全面发展教育由德育、智育、体育、美育、劳动技术教育有机组成，各有各自的任务又相互依存、相互促进，应坚持“五育并举”。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (937, 6, 37, 'single', 1.0, '某校提出“不求人人升学，但求个个成才”，面向全体学生、促进学生主动活泼地发展，同时尊重学生个性。这一做法集中体现的教育理念是（　）', '[["A","素质教育"],["B","自然教育"],["C","精英教育"],["D","应试教育"]]', '["A"]', '素质教育以提高国民素质为根本宗旨，面向全体学生，促进学生全面发展、主动发展，并以培养创新精神和实践能力为重点，尊重学生个性差异。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (938, 6, 38, 'single', 1.0, '罗老师在备课本上写下：教育要“为一个人的一生做准备”，提倡在学校中系统掌握知识、不断学习以适应社会变化。这一表述最接近的教育理念是（　）', '[["A","终身教育"],["B","义务教育"],["C","双轨教育"],["D","博雅教育"]]', '["A"]', '终身教育思想强调教育贯穿人的一生，主张学校教育应为人的持续学习奠定基础。“为一生做准备、不断学习适应变化”正是终身教育理念。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (939, 6, 39, 'single', 1.0, '教学点只有何老师一位公办教师，却要承担一至三年级复式教学；夜里学生生病，她还要送医陪护。这集中体现教师劳动的（　）', '[["A","主体性和示范性"],["B","长期性和间接性"],["C","连续性和广延性"],["D","复杂性和创造性"]]', '["C"]', '教师劳动时间上没有上下班的严格界限（夜间送医陪护），体现连续性；空间上校内校外、课内课外延伸（复式教学、生活照护），体现广延性。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (940, 6, 40, 'single', 1.0, '何老师带学生研制“校园雨水收集小装置”，先确定目标、选择学习经验、组织经验，再评价结果。她依据的经典课程开发程序提出者是（　）', '[["A","泰勒"],["B","夸美纽斯"],["C","洛克"],["D","杜威"]]', '["A"]', '泰勒在《课程与教学的基本原理》中提出课程开发的目标模式，围绕确定目标、选择经验、组织经验、评价结果四个基本问题展开，被称为“泰勒原理”。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (941, 6, 41, 'single', 1.0, '讲“蒸发”一课时，高老师先做湿手帕变干的演示，再让学生联系晾衣、晒谷的生活经验，最后自己归纳影响蒸发快慢的因素。高老师贯彻的教学原则主要是（　）', '[["A","量力性原则"],["B","巩固性原则"],["C","因材施教原则"],["D","直观性与启发性原则"]]', '["D"]', '通过演示实验提供感性认识，体现直观性原则；不直接灌输结论，让学生观察、联系经验并自己归纳，引导独立思考，体现启发性原则。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (942, 6, 42, 'single', 1.0, '为保证复式班三年级的学习效果，何老师每天课后给学生布置适量、分层的练习，第二天及时批阅、当面订正。这一做法主要体现的教学原则是（　）', '[["A","循序渐进原则"],["B","理论联系实际原则"],["C","巩固性原则"],["D","启发性原则"]]', '["C"]', '通过适量练习、及时批阅订正，帮助学生牢固掌握知识技能，体现巩固性原则（“学而时习之”）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (943, 6, 43, 'single', 1.0, '罗老师讲数学应用题时，先带学生走村串户统计家禽数量、记录集市价格，再回课堂列式求解。她这一做法直接体现的教学原则是（　）', '[["A","直观性原则"],["B","巩固性原则"],["C","理论联系实际原则"],["D","因材施教原则"]]', '["C"]', '把书本上的数学知识与乡村生产生活实际结合，在真实情境中获取数据、解决实际问题，体现理论联系实际原则。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (944, 6, 44, 'single', 1.0, '乡村学校规模小，何老师把不同年级学生安排在同一教室，对一个年级讲课时布置其他年级自学或练习，交替进行。这种教学组织形式是（　）', '[["A","道尔顿制"],["B","复式教学"],["C","分组教学"],["D","个别教学"]]', '["B"]', '复式教学是把两个或两个以上不同年级的学生编在一个教室里，由一位教师在同一课时内分别对不同年级交替进行教学的组织形式，多在学生少、师资少的农村地区采用。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (945, 6, 45, 'single', 1.0, '罗老师发现一年级学生常把玩具当作有生命的伙伴跟它说话，也很难站在别人的角度想问题。按皮亚杰理论，这反映的认知特点是（　）', '[["A","守恒与可逆思维"],["B","命题逻辑思维"],["C","泛灵论与自我中心"],["D","抽象假设推理"]]', '["C"]', '前运算阶段（约2—7岁）儿童具有泛灵论倾向（认为无生命物体也有生命、有意识）和自我中心（难以采择他人观点），“跟玩具说话、不会换位思考”正是其表现。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (946, 6, 46, 'single', 1.0, '高老师给四年级学生讲难题时先搭“脚手架”提示，待学生能自己完成再逐步撤除。这一做法的理论依据是（　）', '[["A","皮亚杰的阶段理论"],["B","奥苏贝尔的接受学习理论"],["C","维果斯基的最近发展区理论"],["D","斯金纳的强化理论"]]', '["C"]', '支架式教学以维果斯基最近发展区理论为基础：在学生现有独立解决水平与潜在发展水平之间，由教师提供支持帮助其完成任务，再逐步撤去支架，让学生独立完成。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (947, 6, 47, 'single', 1.0, '寄宿制学校的初一学生正处在“我是谁、将来要做什么”的困惑期，何老师通过生涯主题班会帮助他们探索自我。按埃里克森理论，这一阶段的发展任务主要是（　）', '[["A","自我同一性对角色混乱"],["B","信任感对不信任感"],["C","亲密感对孤独感"],["D","勤奋感对自卑感"]]', '["A"]', '埃里克森人格发展阶段中，12—18岁处于自我同一性对角色混乱阶段，个体需要把自己的各种形象、愿望和社会角色整合成统一的自我。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (948, 6, 48, 'single', 1.0, '学习几何证明时，志强较少依赖老师提示，喜欢自己分析条件、独立寻找思路；晓梅则更习惯参照老师给出的范例、在明确指导下完成。两人在认知方式上的差异最接近（　）', '[["A","场独立型与场依存型"],["B","辐合型与发散型"],["C","冲动型与沉思型"],["D","具体型与抽象型"]]', '["A"]', '场独立型者倾向于以自身内在标准为参照，独立分析、不易受外部暗示影响；场依存型者较多依赖外部参照和他人提示。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (949, 6, 49, 'single', 1.0, '每次学生答对问题，罗老师就当场表扬、盖奖励章，随后学生回答问题的次数明显增多。若要解释这种“行为之后跟一个好结果，行为就变多”的现象，最贴切的说法是（　）', '[["A","学生头脑中的知识结构被重新组织，主动发现了规律"],["B","新旧材料建立起实质联系，新材料被纳入原有观念"],["C","两个刺激反复配对出现，学生被诱发出相同的被动反应"],["D","学生先有行为，行为后得到令他愉快的结果，使该行为增多"]]', '["D"]', '学生先自发做出回答行为，随后得到表扬、奖励章这一愉快刺激，行为频率随之增加，这是正强化，依据操作性条件作用理论。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (950, 6, 50, 'single', 1.0, '何老师讲“圆的认识”，没有先下定义，而是给学生钟面、锅盖、竹篮等实物，让他们自己观察比较、发现圆的特征后再形成概念。这一教学方法的主要提倡者是（　）', '[["A","班杜拉"],["B","布鲁纳"],["C","苛勒"],["D","华生"]]', '["B"]', '让学生不直接接受结论，而是借助材料主动探索、自己发现知识结构，是布鲁纳倡导的认知一结构学习论（发现学习）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (951, 6, 51, 'single', 1.0, '高老师讲新概念时，先唤起学生已学的相关知识，再用通俗易懂的讲解，把新知识和旧知识按道理本身自然地接上头，而不是靠死记硬背。要概括她这套做法，最恰当的是（　）', '[["A","完全由学生自定步调、自由选择学什么和怎样学"],["B","把信息像流水线一样依次登记、短时存放再长期保存"],["C","用讲解把新材料与学生头脑中已有的恰当观念按内在道理接上"],["D","让学生反复盲目尝试，在一次次出错中碰巧做对"]]', '["C"]', '教师以讲解呈现材料，使新知识与已有观念建立非人为的、实质性联系，这正是有意义接受学习。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (952, 6, 52, 'single', 1.0, '罗老师相信每个孩子内心都有向上成长的力量，因此她从不轻易给学生贴标签，而是真诚相待、无论学生眼下表现如何都给予尊重和接纳，让孩子们在放松、安全的氛围里主动想学。与她这套信念最契合的依据是（　）', '[["A","在迷宫中形成对环境位置的内部认知地图后再行动"],["B","靠铃声与食物反复配对，训练对象产生固定的生理反应"],["C","相信人有自我成长的趋向，靠真诚、尊重和接纳让人主动发展"],["D","给足时间和反馈，使几乎所有学生都达到掌握标准"]]', '["C"]', '相信人有自我实现倾向，以真诚、无条件积极关注和同理心营造自由安全的心理氛围促其自发学习，这是人本主义主张。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (953, 6, 53, 'single', 1.0, '何老师观察到，春燕最需要的是家庭温暖和老师的关心，这些需要基本满足后，她才更安心地投入学习。与这一分析最契合的动机理论是（　）', '[["A","马斯洛需要层次理论"],["B","成就动机理论"],["C","强化理论"],["D","归因理论"]]', '["A"]', '马斯洛将人的需要由低到高分层次排列，缺失需要（生理、安全、归属与爱、尊重）获得基本满足后，个体才更有追求成长（求知、审美、自我实现）的动力。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (954, 6, 54, 'single', 1.0, '面对竞赛题，志强总跃跃欲试，认为有五成把握、值得拼一把；建军则回避有风险的任务，更愿做稳拿分的题。阿特金森认为，两人差异主要源于（　）', '[["A","成就动机中力求成功与避免失败倾向的强弱不同"],["B","智力发展水平的类型不同"],["C","对试题难度的客观测量不同"],["D","师生关系质量不同"]]', '["A"]', '阿特金森成就动机理论认为，个体成就动机由力求成功的动机和避免失败的动机组成。力求成功者偏好成功概率约 50% 的中等难度任务；避免失败者则倾向选择极难或极易的任务来回避失败体验。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (955, 6, 55, 'single', 1.0, '晓梅以前不敢上台发言，何老师先让她在小组里讲，再鼓励她对全班讲。一次次真的讲成了，她心里“这事我能行”的底气越来越足。这种底气主要来自（　）', '[["A","两种任务之间恰好有相同的动作和成分"],["B","物体形状改变时分量保持不变时发现"],["C","自己一次次把这件事做成的亲身经历"],["D","对“记住的东西会随时间先快后慢地丢”的认识"]]', '["C"]', '晓梅通过亲历的一次次成功发言，提高了对自己能否完成发言任务的判断，说明个体自身成败经验是影响“我能不能行”这一信心最有力的因素。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (956, 6, 56, 'single', 1.0, '志强从小在山溪里玩水，学会了踩水。到校上游泳课，老师没让他只模仿几个相同动作，而是引导他把“在水里怎样控制身体、怎样借助水”的共同道理说出来、用到新添姿上，他因此学得最快。最能解释他学得快的原因是（　）', '[["A","他在某个瞬间突然看出两个情境在整体关系上相似"],["B","他反复做枯燥的专门练习，把某种天生官能练强了"],["C","他把两次玩水活动中共同的道理概括出来，并用到新情境"],["D","新旧两种活动里每个具体动作都完全一样"]]', '["C"]', '对两类活动中的共同原理、一般经验进行概括，并把它迁移到新情境，这是概括化（经验类化）说的核心。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (957, 6, 57, 'single', 1.0, '早读时，晓梅先背了一首描写春景的古诗，紧接着背第二首内容相近的，结果第二首开头几句总被第一首的句子“顶”出来。对这种“先学的内容挤掉后学内容”的现象，最准确的解释是（　）', '[["A","刺激过强过久，神经活动转入保护性抑制"],["B","后来记的材料反过来干扰了先前材料"],["C","长时间不用，记忆痕迹自行衰退消失"],["D","先前记的材料干扰了对后来材料的回忆"]]', '["D"]', '先前学习的材料对识记和回忆后学材料的干扰，是前摄抑制。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (958, 6, 58, 'single', 1.0, '何老师教学生写字时，先讲解并示范正确的握笔、坐姿和运笔动作，让学生在头脑中建立起完整的动作映像。按操作技能形成阶段，这属于（　）', '[["A","操作模仿阶段"],["B","操作整合阶段"],["C","操作熟练阶段"],["D","操作定向阶段"]]', '["D"]', '操作定向是操作技能形成的第一阶段，指学习者了解操作活动的结构与要求，在头脑中建立起操作活动的定向映像。讲解示范握笔、坐姿、运笔正属操作定向。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (959, 6, 59, 'single', 1.0, '复习课文时，晓梅给难记的段落编口诀、给生字配上与家乡事物相关的联想。她所使用的学习策略属于（　）', '[["A","组织策略"],["B","精加工策略"],["C","资源管理策略"],["D","复述策略"]]', '["B"]', '精加工策略是把新信息与已有知识联系起来，增加新信息的意义以帮助记忆，如记忆术、口诀、谐音联想、做笔记、提问等。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (960, 6, 60, 'single', 1.0, '做数学题时，建军做到一半自己“察觉”到思路不对，便停下来重读题目、换一种解法，并提醒自己“看清条件再下笔”。他对自己思考过程的这种察看和调整，最准确概括是（　）', '[["A","把零散材料分门别类、编成提纲和网络"],["B","对自己的思考过程保持觉察，并据此调整做法"],["C","安排好学习时间、环境并寻求他人帮助"],["D","给无意义材料人为附加线索帮助记忆"]]', '["B"]', '对自身认知活动的计划、监控（察觉思路出错）与调节（重读、换解法）属于元认知策略。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (961, 6, 61, 'single', 1.0, '在解决“如何把村里散落的竹屑利用起来”这一问题时，志强看到有人用竹屑制炭，受到启发，提出用竹屑制作班级取暖炭包的方案。影响其问题解决的因素主要是（　）', '[["A","酝酿效应"],["B","定势"],["C","功能固着"],["D","原型启发"]]', '["D"]', '原型启发是指在其他事物或现象中获得的信息对解决当前问题的启发，具有启发作用的事物叫原型。由竹屑制炭受到启发提出炭包方案，属原型启发。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (962, 6, 62, 'single', 1.0, '高老师所带班级气氛融洽、学生相互信任，班级决定多由师生共同讨论作出。这种课堂气氛所对应的教师领导方式最接近（　）', '[["A","仁慈专断型"],["B","放任自流型"],["C","强硬专断型"],["D","民主型"]]', '["D"]', '民主型领导方式下，教师与学生共同讨论、集体决定，学生关系融洽、主动性和责任感强，课堂气氛积极。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (963, 6, 63, 'single', 1.0, '新教师罗老师最近总担心：“学生喜欢我吗？同事怎么看我？校长会不会觉得我不行？”按福勒和布朗的教师成长阶段，她主要处在（　）', '[["A","关注生存阶段"],["B","关注自我实现阶段"],["C","关注情境阶段"],["D","关注学生阶段"]]', '["A"]', '福勒和布朗把教师成长分为关注生存、关注情境、关注学生三个阶段。新教师最关注自己的生存适应性，如学生、同事、领导是否喜欢和认可自己。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (964, 6, 64, 'single', 1.0, '何老师对几个内向学生从心里相信“他们能行”，这份相信通过她的眼神、提问机会和耐心一点点传递给学生；一学期后，这些被寄予期待的学生果然更敢表达、表现更好。最能解释这一变化的是（　）', '[["A","教师暗含的期待传递给学生，学生朝着被期待的方向发展"],["B","一扇窗被打破没人管，更多破坏行为随之出现"],["C","条件好的学生获得更多资源，与其他学生差距越来越大"],["D","在场的人越多，个人挺身而出的责任感越弱"]]', '["A"]', '教师的期望或明或暗地传递给学生，学生会按教师期望的方向塑造自己的行为，这是教师期望效应（罗森塔尔效应/皮格马利翁效应）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (965, 6, 65, 'single', 1.0, '处理学校相关纠纷时，何老师注意到法院判决常引用《中华人民共和国宪法》关于受教育权的条款。在我国教育法的渊源中，宪法的地位是（　）', '[["A","效力与一般法律相同"],["B","由全国人大常委会制定，效力低于法律"],["C","国家的根本法，具有最高法律效力，是教育立法的根本依据"],["D","只规定国家机构，与教育无关"]]', '["C"]', '宪法是国家根本法，具有最高的法律地位和效力，一切法律、法规都不得同宪法相抵触；宪法关于公民受教育权等规定是教育立法的最高法律依据。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (966, 6, 66, 'single', 1.0, '县教育局接到群众举报后，对某无证举办的“黑幼儿园”依法予以取缔。这一行为在性质上属于（　）', '[["A","教育行政复议"],["B","教育民事调解"],["C","教育行政许可"],["D","教育行政处罚"]]', '["D"]', '行政机关对违反行政管理秩序的相对人依法给予的制裁，属于行政处罚；取缔无证办学是对违法行为的制裁，属教育行政处罚。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (967, 6, 67, 'single', 1.0, '乡中心小学拟附设幼儿园，需有合格教师、符合标准的场所设施、必备办学资金及组织机构章程。这一要求直接对应（　）', '[["A","教师申诉的程序"],["B","学生转学的条件"],["C","学业证书颁发条件"],["D","学校设立的基本条件"]]', '["D"]', '《中华人民共和国教育法》规定，设立学校及其他教育机构必须具备组织机构和章程、合格的教师、符合规定标准的教学场所及设施设备、必备的办学资金和稳定的经费来源等基本条件。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (968, 6, 68, 'single', 1.0, '寄宿制学校晚自习后，何老师发现社会人员翻越围墙进校骚扰学生，当即制止并报警。学校依法可以采取的管理措施不包括（　）', '[["A","加强门禁与巡查"],["B","拒绝无关人员进入校园"],["C","对入校滋事人员长期限制其人身自由"],["D","对扰乱秩序者予以制止并报警"]]', '["C"]', '学校有权对校园进行管理，拒绝无关人员进入、制止扰乱秩序行为并报警、加强封闭管理和巡查，都是学校履行管理职责的合法措施。但限制公民人身自由属于公安机关等法定机关的强制措施，学校无权长期限制人身自由。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (969, 6, 69, 'single', 1.0, '罗老师利用假期参加学历提升学习，却被学校以“影响工作”为由扣发工资、不准请假。该校直接侵犯了教师的（　）', '[["A","教育教学权"],["B","指导评价权"],["C","民主管理权"],["D","获取劳动报酬权和进修培训权"]]', '["D"]', '《教师法》规定教师享有按时获取工资报酬、享受国家规定福利待遇的权利，以及参加进修或其他方式培训的权利。扣发工资侵犯获取报酬待遇权，不准学历提升学习侵犯进修培训权。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (970, 6, 70, 'single', 1.0, '乡中心小学规定：留守儿童的成绩通知单只发给本人，不经在外务工家长同意，任何人不得查看其心理辅导记录。这一规定主要保护学生的（　）', '[["A","财产权"],["B","著作权"],["C","隐私权"],["D","受教育权"]]', '["C"]', '成绩、心理辅导记录等属于学生个人不愿为他人所知的人信息，未经允许不得查阅、公开。学校限制无关人员查看，保护的是学生的隐私权。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (971, 6, 71, 'single', 1.0, '《义务教育法》明确，实施义务教育不收学费、杂费。对这一规定，下列理解正确的是（　）', '[["A","学校可以通过收取赞助费代替学费"],["B","学校可按成绩向部分学生收取培养费"],["C","寄宿制学校可向学生收取高额住宿费弥补经费"],["D","国家建立义务教育经费保障机制，适龄儿童少年依法平等接受义务教育"]]', '["D"]', '《义务教育法》规定义务教育是国家统一实施的、所有适龄儿童少年必须接受的教育，不收学费、杂费，国家建立经费保障机制保证其实施。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (972, 6, 72, 'single', 1.0, '五年级建军多次强行索要低年级同学的零花钱，学校对其进行训导后仍不改正。依《预防未成年人犯罪法》，下一步较为恰当的做法是（　）', '[["A","让其在家反省一年、不得返校"],["B","在全校大会上公布其身份证信息示众"],["C","直接开除学籍，不再管理"],["D","由公安机关予以矫治教育，学校和家庭相互配合加强管教"]]', '["D"]', '对有严重不良行为的未成年人，法律坚持教育为主、惩罚为辅，由公安机关进行矫治教育，学校、家庭相互配合，不得歧视，更不得随意开除或长期剥夺其受教育权。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (973, 6, 73, 'single', 1.0, '体育课自由活动期间，一名校外人员闯入球场推倒志强致其受伤，经查学校门禁存在明显疏漏。关于赔偿责任，下列说法正确的是（　）', '[["A","全部由志强家长自行承担"],["B","由同班同学共同赔偿"],["C","由闯入的第三人承担侵权责任，学校未尽管理职责的承担相应补充责任"],["D","全部由学校赔偿，第三人无责"]]', '["C"]', '《民法典》规定，无民事行为能力人或限制民事行为能力人在学校学习、生活期间受到第三人人身损害的，由第三人承担侵权责任；学校未尽到管理职责的，承担相应的补充责任，学校承担后可向第三人追偿。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (974, 6, 74, 'single', 1.0, '罗老师被学校无正当理由扣发绩效工资，她先向教育行政部门提出处理请求。该法定救济途径是（　）', '[["A","教师申诉"],["B","商事仲裁"],["C","刑事自诉"],["D","民事诉讼"]]', '["A"]', '《教师法》规定，教师对学校或其他教育机构侵犯其合法权益的行为，或者对其作出的处理不服，可以向教育行政部门提出申诉。此为教师申诉制度。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (975, 6, 75, 'single', 1.0, '何老师从教三十年，始终把“教好书”与“育好人”统一起来：既传授知识，又利用教材中的人物事迹引导学生做人。她最突出践行的师德规范是（　）', '[["A","教书育人"],["B","终身学习"],["C","为人师表"],["D","爱国守法"]]', '["A"]', '《中小学教师职业道德规范》中，教书育人是教师的天职，要求教师遵循教育规律、实施素质教育，循循善诱、诲人不倦，因材施教，培养学生良好品行、激发创新精神、促进学生全面发展。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (976, 6, 76, 'single', 1.0, '为提升乡村教学水平，罗老师坚持阅读专业书刊、参加网络教研，不断更新知识结构、改进教学方法。她所践行的师德规范是（　）', '[["A","关爱学生"],["B","爱岗敬业"],["C","终身学习"],["D","廉洁从教"]]', '["C"]', '终身学习是教师专业发展的不竭动力，要求教师崇尚科学精神，树立终身学习理念，拓宽知识视野、更新知识结构，潜心钻研业务、不断提高专业素养和教育教学水平。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (977, 6, 77, 'single', 1.0, '青山乡中心校组织学习《教育强国建设规划纲要（2024—2035年）》。对照纲要谋划学校长远工作时，下列目标与时间节点对应正确的是（　）', '[["A","到2027年教育强国建设取得重要阶段性成效，到2035年建成教育强国"],["B","到2030年建成教育强国，到2050年再进行巩固提高"],["C","到2035年取得阶段性成效，到本世纪中叶基本建成教育强国"],["D","到2027年全面实现教育现代化，到2035年成为世界教育中心"]]', '["A"]', '纲要明确建设教育强国“两步走”：到2027年教育强国建设取得重要阶段性成效；到2035年建成教育强国。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (978, 6, 78, 'single', 1.0, '某校落实教育部《关于进一步加强中小学日常考试管理的通知》（2025年12月），对成绩反馈方式进行改革。符合通知要求的做法是（　）', '[["A","每周组织一次全校统考并公开排名"],["B","以分数高低给学生排座位、定奖惩"],["C","在校园大屏公布每名学生的原始分数和班级排名"],["D","以等级方式呈现成绩，有针对性地反馈学情，不公布排名"]]', '["D"]', '通知要求改进评价方式，成绩实行等级呈现，淡化分数竞争、不公布排名，减轻学生过重学业负担，使考试回归诊断改进功能。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (979, 6, 79, 'single', 1.0, '落实乡村教育振兴政策，县中在生源和师资稳定、办学条件改善后教育质量逐步回升，让县域学生就近享受到优质高中教育。这直接对应的教育热词是（　）', '[["A","双师课堂"],["B","县中振兴"],["C","强基计划"],["D","学分银行"]]', '["B"]', '“县中振兴”针对县域普通高中优质生源和骨干教师流失、办学质量下滑等问题，通过综合治理和政策扶持提升县中办学水平，让县域学生就近享有优质高中教育。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (980, 6, 80, 'single', 1.0, '何老师所在的乡镇学校与县城实验小学组成“教联体”，开展同步教研、教师轮岗和课程共享。关于“教联体”，下列理解最准确的是（　）', '[["A","以营利为目的的民办教育连锁机构"],["B","基础教育阶段以优质学校为龙头、多校紧密协同的教育联合体"],["C","面向大学生的在线学习平台"],["D","只负责考试命题的行政单位"]]', '["B"]', '教联体是基础教育阶段以优质学校为龙头，由多所学校（含城乡学校）紧密协同组成的教育联合体，通过管理互通、师资共享、资源共建、捆绑考核等方式促进区域教育优质均衡。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (981, 6, 81, 'multi', 1.6, '乡中心小学开展“好课大家评”活动。下列对教学过程基本规律的表述，正确的有（　）', '[["A","教学只重知识传授，学生的思想品德形成与教学无关"],["B","教学只需要发展学生能力，系统知识的学习可以忽略"],["C","教学以传授间接经验为主，同时也以学生的直接经验为基础"],["D","掌握知识与发展能力相互依存、相互促进"],["E","教学过程中教师起主导作用，学生是学习的主体，二者辩证统一"]]', '["C","D","E"]', 'E正确：教学过程是教师主导与学生主体相统一的过程。C正确：学生以学习间接经验为主，又离不开直接经验。D正确：掌握知识是发展能力的基础。A错误：教学具有教育性。B错误：能力发展不能脱离知识学习。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (982, 6, 82, 'multi', 1.6, '高老师接手纪律松散的寄宿班级后，想把学生培养成具有良好品德的人。下列关于德育过程的说法，正确的有（　）', '[["A","学生品德一旦形成就不会再出现反复，德育可一劳永逸"],["B","德育过程是组织学生活动和交往、统一多方面教育影响的过程"],["C","德育过程是促使学生知、情、意、行诸因素统一发展的过程"],["D","德育过程是长期、反复、逐步提高的过程"],["E","德育过程是促进学生思想内部矛盾积极转化的过程"]]', '["B","C","D","E"]', '德育过程的基本规律包括：知、情、意、行统一发展；在活动和交往中形成品德、统一多方影响；教育与自我教育相结合、促进内部矛盾积极转化；长期性、反复性、渐进性。A错误，恰恰否认了长期反复性。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (983, 6, 83, 'multi', 1.6, '罗老师所带班级留守儿童多，她经常和在外务工的家长电话沟通、与科任教师统一要求，并利用村史馆、乡贤榜样开展教育。她的做法直接体现的德育原则有（　）', '[["A","尊重学生与严格要求相结合原则"],["B","因材施教原则"],["C","知行统一原则"],["D","正面教育与纪律约束相结合原则"],["E","教育影响的一致性与连贯性原则"]]', '["A","B","E"]', 'E选：联系家长、与科任教师统一要求，使家庭、学校、社会教育影响一致连贯。B选：针对留守儿童特点采取相应措施，体现因材施教。A选：尊重关爱留守儿童的同时提出明确要求，体现尊重与严格要求相结合。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (984, 6, 84, 'multi', 1.6, '县教育局评估乡村学校办学质量时，下列符合我国教育目的和全面发展教育要求的做法有（　）', '[["A","把学生品德发展和身心健康作为重要评价内容"],["B","要求所有学生平均发展、不得有兴趣特长"],["C","只以升学率和考试分数排名评价学校"],["D","关注劳动教育、艺术教育和体育活动的开展情况"],["E","重视学生创新精神和实践能力的培养"]]', '["A","D","E"]', 'A选：德、体是全面发展的重要组成，理应纳入评价。D选：五育并举，劳动、美育、体育不可偏废。E选：素质教育以培养创新精神和实践能力为重点。C不选：唯分数、唯升学违背教育目的和素质教育导向。B不选：全面发展不是平均发展。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (985, 6, 85, 'multi', 1.6, '针对志强、桂芳等学生的不同情况，何老师采取多种措施激发学习动机。下列措施合理的有（　）', '[["A","用频繁的排名和当众羞辱逼迫学生学习"],["B","创设问题情境，启发学生积极思维"],["C","引导学生对成败作出积极归因"],["D","妥善运用奖惩，及时反馈学习结果"],["E","设置具体、适度、经努力可实现的学习目标"]]', '["B","C","D","E"]', 'BCDE均为激发和培养学习动机的有效措施：明确适度的目标、启发式的问题情境、合理奖惩与及时反馈、积极的努力归因，能增强内部动机与自我效能感。A错误：频繁排名、当众羞辱伤害自尊与人格，反而削弱动机。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (986, 6, 86, 'multi', 1.6, '高老师发现不少学生公式背得熟，一遇到田里测产量、村史馆算面积等真实问题就无从下手。为引导学生实现“为迁移而学”，下列做法与相应迁移理论对应正确的有（　）', '[["A","让学生用语文概括段落大意的方法去梳理历史材料，关注新旧学习间的相互影响——认知结构迁移理论"],["B","让学生先估算自家院落面积，再学村史馆不规则场地的测算，强调两种情境要有共同成分——共同要素说"],["C","反复让学生抄写公式直到一字不差，认为记牢形式本身就能自动解决一切新问题——共同要素说"],["D","引导学生提炼出“分割求和”的一般原理后再解决新问题，认为概括水平越高越易迁移——概括化理论"],["E","每天安排口算、速算等基本功训练，认为心智官能练强了各科都受益——形式训练说"]]', '["A","B","D","E"]', 'E正确：形式训练说以官能心理学为基础，主张通过训练记忆、推理等心智官能使之增强并迁移到其他学习。B正确：共同要素说认为只有当两种情境存在相同要素时迁移才会发生。D正确：概括化理论认为迁移的关键是学习者概括出两类活动间的共同原理。A正确：认知结构迁移理论强调一切有意义学习都受原有认知结构影响。C错误：反复抄写、机械记忆公式属于死记硬背，对应关系不成立。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (987, 6, 87, 'multi', 1.6, '教学点开展“小发明小创造”活动。下列有利于培养学生创造性的做法有（　）', '[["A","组织丰富多彩的课外活动，拓宽知识经验"],["B","对学生任何想法都立刻否定，要求唯一标准答案"],["C","保护好奇心，鼓励学生质疑问难"],["D","开展发散思维训练，鼓励一题多解"],["E","创设宽松民主的心理氛围，鼓励学生标新立异"]]', '["A","C","D","E"]', '创造性的培养需要：EC营造安全心理环境、保护好奇心和求知欲；D加强发散思维和直觉思维训练；A通过活动积累知识经验、提供创造原型。B错误：一味否定、强求唯一答案会压抑独立性和想象力。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (988, 6, 88, 'multi', 1.6, '罗老师拟在乡镇学校长期任教。依照《教师法》，她作为教师应当履行的义务有（　）', '[["A","对学生进行宪法所确定的基本原则和爱国主义、民族团结教育"],["B","贯彻国家教育方针，遵守规章制度，执行学校教学计划，履行教师聘约"],["C","自行决定收费标准并向学生收取教学管理费"],["D","遵守宪法、法律和职业道德，为人师表"],["E","关心爱护全体学生，尊重学生人格，促进学生全面发展"]]', '["A","B","D","E"]', 'D—E均为《教师法》第八条规定的教师义务：守法守德为人师表、履行聘约完成教学工作、开展思想品德教育、关爱尊重学生并制止有害于学生的行为等。C错误：教师个人无权设立收费项目，乱收费违反法律和师德。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (989, 6, 89, 'multi', 1.6, '寄宿制学校夜间安全管理中，学校和教师依法应当履行的职责有（　）', '[["A","提供符合安全标准的校舍、设施和生活条件"],["B","建立健全安全制度，落实值班、巡查和宿舍管理"],["C","发现学生身体受到伤害或疑似伤害时及时救助、报告"],["D","对学生进行安全教育，教授自救自护知识"],["E","与校外人员约定入校开展商业推销活动以补充经费"]]', '["A","B","C","D"]', 'BDCA分别对应安全制度建设、安全教育、及时救助报告和安全保障义务，是学校履行教育、管理、保护职责的法定要求。E错误：让校外人员入校商业推销既扰乱教育教学秩序，也带来安全隐患。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (990, 6, 90, 'multi', 1.6, '学习《新时代中小学教师职业行为十项准则》后，何老师结合乡村学校实际整理要点。下列属于该准则要求的有（　）', '[["A","潜心教书育人，传播优秀文化"],["B","以盈利为目的组织学生参加校内外有偿补课"],["C","加强安全防范，关心爱护学生"],["D","坚定政治方向，自觉爱国守法"],["E","坚守廉洁自律，规范从教行为"]]', '["A","C","D","E"]', '十项准则包括坚定政治方向、自觉爱国守法、传播优秀文化、潜心教书育人、关心爱护学生、加强安全防范、坚持言行雅正、秉持公平诚信、坚守廉洁自律、规范从教行为。DCEA均属其要求。B错误：组织、要求或参与有偿补课是“规范从教行为”明确禁止的。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (991, 7, 1, 'judge', 0.6, '数学课上，张老师讲圆的面积时，先让学生回忆长方形面积公式的推导过程，再引导学生把圆分割拼成近似长方形来推导面积公式。这种由已知到未知、化未知为已知的教学方式主要体现了巩固性原则。', '[["A","正确"],["B","错误"]]', '["B"]', '题干做法是借助已掌握的长方形面积知识，把圆转化为近似长方形来推导新知，引导学生由已知走向未知，主要体现的是循序渐进原则（同时含有启发性因素），而非通过复习、练习来牢固掌握知识的巩固性原则。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (992, 7, 2, 'judge', 0.6, '小学四年级班主任陈老师发现班上小刚经常欺负同学。陈老师没有直接惩罚小刚，而是让他担任班级文明监督员负责维护课间秩序。小刚从此认真负责也不再欺负同学了。陈老师的做法运用了长善救失原则。', '[["A","正确"],["B","错误"]]', '["A"]', '长善救失原则要求调动学生自我教育的积极性，依靠和发扬学生身上的积极因素来克服消极因素。陈老师让小刚担任监督员利用其好胜有责任心的积极面来克服欺负同学的消极面，正是长善救失原则的体现。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (993, 7, 3, 'judge', 0.6, '某中学在期中考试后将成绩排名张榜公布在公告栏并标注每位学生的班级名次和年级名次。学校认为这样能激励学生努力学习。该校的做法符合相关教育法规关于保护学生权益的规定。', '[["A","正确"],["B","错误"]]', '["B"]', '教育部相关规定明确要求学校不得公开学生考试成绩排名。公开排名侵犯了学生的隐私权和人格尊严。学校应以其他方式反馈学业情况而非张榜排名。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (994, 7, 4, 'judge', 0.6, '初二学生小美在物理课上提出了一种与教材不同的解题思路，物理老师王老师认为她是在钻牛角尖，让她别想太多、记住公式就行。王老师的做法有利于培养学生的创新精神。', '[["A","正确"],["B","错误"]]', '["B"]', '新课改强调培养学生的创新精神和实践能力，学生提出不同于教材的解题思路是求异思维和创新意识的萌芽，教师应鼓励、引导而非压制。王老师否定学生的不同思路，会打击其求知欲和创造性，不利于创新精神培养。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (995, 7, 5, 'judge', 0.6, '李老师是一名刚入职的乡村教师，为了节省时间，她只通过电话向家长了解学生情况，从不登门家访，并据此安排班级工作。李老师的这种做法符合作班主任家访工作的基本要求。', '[["A","正确"],["B","错误"]]', '["B"]', '家访是班主任深入了解学生家庭环境与成长背景、沟通家校关系的重要途径。家访的基本要求包括深入学生家庭、与家长面对面交流、全面了解情况并保持联系。只打电话、从不登门，难以全面真切地了解学生。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (996, 7, 6, 'judge', 0.6, '在历史课上赵老师讲授戊戌变法时，先播放了一段历史纪录片片段，再让学生分组扮演维新派和守旧派进行辩论。赵老师在这节课上运用了直观性原则和讨论法相结合的教学方式，这种说法是正确的。', '[["A","正确"],["B","错误"]]', '["A"]', '播放纪录片片段属于视听直观体现了直观性原则；让学生分组扮演并辩论属于讨论法。两种方式结合既有直观感知又有深入思考，符合教学原则的综合运用要求。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (997, 7, 7, 'judge', 0.6, '英语课上新学的单词，小宇当晚背得很熟，第二天默写却错了一大半；他按老师教的方法当天及时复习、之后每隔几天再巩固一次，单词就记得很牢。小宇的这一做法印证了艾宾浩斯遗忘曲线所揭示的遗忘先快后慢规律，这种说法是正确的。', '[["A","正确"],["B","错误"]]', '["A"]', '艾宾浩斯遗忘曲线表明，遗忘在学习之后立即开始，且遗忘的进程是先快后慢、先多后少。因此及时复习、合理分配复习时间是防止遗忘的有效措施。小宇及时复习并间隔巩固后记忆保持良好，正印证了该规律。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (998, 7, 8, 'judge', 0.6, '五年级的刘老师在教学生写作文时先让学生观察校园里的一棵老槐树，然后用自己的话描述它的样子。学生们写出了各不相同但生动真实的描写。刘老师的做法体现了理论联系实际原则。', '[["A","正确"],["B","错误"]]', '["A"]', '理论联系实际原则要求教学以学习基础知识为主引导学生将所学知识运用于实际。刘老师先让学生实地观察再用自己的语言描述，使学生在实践中加深理解，体现了理论联系实际原则。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (999, 7, 9, 'judge', 0.6, '六年级学生小明在数学考试中因粗心丢了几分，他对老师说：“是没看清题目，要是仔细点肯定能考满分。”按照韦纳的归因理论，小明将失败归因于能力这个内部稳定因素。', '[["A","正确"],["B","错误"]]', '["B"]', '韦纳归因理论中粗心属于努力维度是内部不稳定可控的因素，而能力是内部稳定不可控的因素。小明说是因为没看清题目暗示的是不够努力而非能力不足。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1000, 7, 10, 'judge', 0.6, '初一学生小红背英语单词时，不分析单词的发音和结构，只靠一遍遍反复朗读、抄写来记忆。小红使用的这种记忆方法属于精细加工策略。', '[["A","正确"],["B","错误"]]', '["B"]', '小红只是通过反复朗读、抄写来记住单词，没有把新词与已有知识建立意义联系，这属于复述策略。精细加工策略是通过把新信息与已有知识联系起来（如记忆术、做笔记、提问、联系生活情境等）以增加新信息意义的策略。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1001, 7, 11, 'judge', 0.6, '体育课上体育老师示范跳远动作后让小明反复模仿练习。小明通过观察老师的示范动作在头脑中形成了动作表象然后模仿完成。小明这一学习过程仅仅体现了班杜拉观察学习中的保持过程。', '[["A","正确"],["B","错误"]]', '["B"]', '班杜拉的观察学习包括注意、保持、动作再现和动机四个过程。小明观察老师示范并在头脑中形成动作表象，包含注意和保持过程；随后模仿完成跳远动作，则属于动作再现过程。题干称“仅仅体现了保持过程”，以偏概全。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1002, 7, 12, 'judge', 0.6, '初三学生小亮觉得学习就是为了获得好成绩，而好成绩能让父母高兴、给他买想要的东西。根据奥苏贝尔的成就动机理论，小亮的学习动机主要属于附属内驱力。', '[["A","正确"],["B","错误"]]', '["A"]', '附属内驱力是指为了获得家长教师等权威人物的赞许或认可而学习的需要。小亮学习是为了好成绩让父母高兴获得物质奖励本质上是为了获得家长的认可和赞许。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1003, 7, 13, 'judge', 0.6, '小学三年级的孙老师教学生认识分数时，先让学生把一块月饼模型平均分成两份、四份，再引入分数的概念。按照皮亚杰的认知发展阶段理论，三年级学生已普遍进入形式运算阶段，能够脱离具体事物直接理解抽象的数理逻辑。', '[["A","正确"],["B","错误"]]', '["B"]', '小学三年级学生约8至9岁，按照皮亚杰的理论正处于具体运算阶段，能够进行初步的逻辑推理，但思维仍需要具体事物和直观表象的支持，所以孙老师才借助月饼模型施教。形式运算阶段一般在11岁以后才逐步形成。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1004, 7, 14, 'judge', 0.6, '高中生小芳在学习物理时能够用假设演绎的方式思考问题：先假设某种情况成立，再推导出可能的结果，最后通过实验验证。按照皮亚杰的理论小芳已经进入形式运算阶段。', '[["A","正确"],["B","错误"]]', '["A"]', '形式运算阶段的典型特征是能够进行抽象思维和假设演绎推理。小芳能够先提出假设再进行逻辑推演和验证这正是形式运算阶段的核心标志。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1005, 7, 15, 'judge', 0.6, '班主任王老师发现每次在班级公开表扬学习进步的同学后其他同学的学习积极性也会提高。从行为主义的角度看这属于替代强化。', '[["A","正确"],["B","错误"]]', '["A"]', '班杜拉提出替代强化的概念：观察者看到榜样受到强化时自己也倾向于表现出同样的行为。王老师公开表扬进步同学其他同学看到后也受到激励这就是替代强化。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1006, 7, 16, 'judge', 0.6, '自然课上学生已经掌握了"鸟"的概念，知道鸟是卵生、有羽毛的脊椎动物；后来学习到"企鹅虽然不会飞、生活在南极，但同样卵生、有羽毛，属于鸟"。把企鹅这一新例证纳入原有"鸟"概念的学习，属于奥苏贝尔所说的下位学习。', '[["A","正确"],["B","错误"]]', '["A"]', '下位学习（类属学习）是指把概括程度较低的新概念或新例证，归入认知结构中已有的概括程度更高的概念之下。学生先掌握概括程度较高的"鸟"概念，再把企鹅这一具体例证纳入其中，新概念从属于原有概念，属于下位学习中的派生类属学习。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1007, 7, 17, 'judge', 0.6, '期末考试前小红总是感到紧张不安担心自己考不好甚至出现失眠和食欲不振的情况。心理辅导老师让她在考试前先做几次深呼吸然后想象自己在考场上从容答题的场景。这种方法属于系统脱敏法。', '[["A","正确"],["B","错误"]]', '["B"]', '系统脱敏法需要通过建立焦虑等级从最不紧张到最紧张逐步暴露于引起焦虑的刺激。题干中使用的是想象放松法配合深呼吸放松没有建立焦虑等级并逐步暴露不是系统脱敏法。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1008, 7, 18, 'judge', 0.6, '小华在学骑自行车时一开始总是东倒西歪后来通过反复练习逐渐掌握了平衡。从信息加工的角度看小华的学习过程经历了从陈述性知识到程序性知识的转化。', '[["A","正确"],["B","错误"]]', '["A"]', '安德森的技能获得理论认为，技能学习经历认知阶段、联结阶段和自动化阶段。认知阶段获得的主要是陈述性知识，经过反复练习逐步转化为程序性知识。小学学骑车从东倒西歪到熟练掌握平衡，正体现了陈述性知识向程序性知识的转化。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1009, 7, 19, 'judge', 0.6, '某小学一年级学生（7岁）在课间活动时从滑梯上摔下受伤。经调查发现该滑梯的安装高度超过了国家规定的安全标准。对该学生所受的伤害，学校应承担过错推定责任，这种说法是正确的。', '[["A","正确"],["B","错误"]]', '["A"]', '根据民法典第1199条无民事行为能力人不满8周岁在教育机构受到人身损害的教育机构应当承担侵权责任但能证明尽到教育管理职责的不承担。7岁学生属于无民事行为能力人适用过错推定责任原则。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1010, 7, 20, 'judge', 0.6, '某中学教师王某在上课时发现学生小李在座位上睡觉下课后将小李叫到办公室进行体罚。小李的家长向学校投诉。根据教师法的规定学校可以对王某给予行政处分或解聘。', '[["A","正确"],["B","错误"]]', '["A"]', '教师法第三十七条规定教师体罚学生经教育不改的或品行不良侮辱学生影响恶劣的由所在学校给予行政处分或解聘。王某对学生实施体罚学校有权依据教师法给予处分。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1011, 7, 21, 'judge', 0.6, '某初中学校规定所有学生在校期间必须穿校服。一名学生因家庭经济困难无力购买校服学校以未穿校服为由不允许该学生进入教室上课。学校的做法侵犯了学生的受教育权。', '[["A","正确"],["B","错误"]]', '["A"]', '受教育权是宪法赋予公民的基本权利。学校不得以任何理由剥夺学生的受教育权。因未穿校服不让进教室实质是剥夺了学生接受教育的权利。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1012, 7, 22, 'judge', 0.6, '某县教育局在校园安全检查中发现某民办学校使用未经审定的地方课程教材，遂责令该校限期改正并给予警告。县教育局的这一处理没有法律依据，属于超越职权。', '[["A","正确"],["B","错误"]]', '["B"]', '根据《中华人民共和国义务教育法》，国家实行教科书审定制度，教科书须经审定后方可使用，未经审定不得出版、选用；县级以上人民政府教育行政部门负责义务教育实施的日常监督检查，对违规行为有权责令限期改正。故县教育局的处理于法有据。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1013, 7, 23, 'judge', 0.6, '张老师是一名小学教师，他发现班上有一名学生近期经常迟到、旷课，经家访了解到该学生父母离异后无人监管。张老师应当直接向公安机关报案。', '[["A","正确"],["B","错误"]]', '["B"]', '根据未成年人保护法学校发现未成年学生旷课缀学应当及时与其父母或监护人联系；对于监护缺失情况应向教育行政部门或民政部门报告而非直接向公安机关报案。只有在发现未成年人遭受侵害或面临紧急危险时才应立即向公安机关报案。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1014, 7, 24, 'judge', 0.6, '一名初二学生在学校实验室擅自操作化学药品导致手部灼伤。经调查，实验室门未按规定上锁、药品管理存在明显漏洞。对该学生的损害，学校责任的认定应适用无过错责任原则，无论学校有无过错都必须赔偿。', '[["A","正确"],["B","错误"]]', '["B"]', '初二学生属于限制民事行为能力人。根据《中华人民共和国民法典》第一千二百条，限制民事行为能力人在学校或者其他教育机构学习、生活期间受到人身损害的，适用过错责任原则，学校未尽到教育、管理职责的才承担侵权责任，并非无论有无过错都要赔偿的无过错责任。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1015, 7, 25, 'judge', 0.6, '某小学教师李某在家长会上公开说班上小明同学“智商有问题”，建议家长带去做智力测试。小明家长认为李某侵犯了孩子的人格尊严权。家长的主张有法律依据。', '[["A","正确"],["B","错误"]]', '["A"]', '教师公开场合贬损学生智力属于对学生人格的不当贬低。未成年人保护法规定学校教职员工应当尊重未成年人人格尊严不得实施侮辱人格尊严的行为。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1016, 7, 26, 'judge', 0.6, '教师节当天某班家长委员会用班费购买了一张购物卡送给班主任周老师。周老师认为这是家长们的心意收下后将其用于给班上学生购买课外读物。周老师的做法符合教师职业道德规范的要求。', '[["A","正确"],["B","错误"]]', '["B"]', '教师职业道德规范要求教师为人师表不得利用职务之便谋取私利。教育部严禁教师违规收受学生及家长礼品礼金。即使周老师将购物卡用于购买学生读物其收受行为本身已违反职业规范应当当场拒绝。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1017, 7, 27, 'judge', 0.6, '某市教育局在部署教育数字化工作时提出，推进国家教育数字化战略行动，就是要把信息技术简单叠加到传统课堂教学之上，用机器和网络教学全面替代教师的课堂教学，这种认识是正确的。', '[["A","正确"],["B","错误"]]', '["B"]', '国家教育数字化战略行动强调以数字化赋能教育高质量发展，推动信息技术与教育教学深度融合，核心是更新教育理念、变革教学模式、服务个性化学习，而非技术与教学的简单叠加，更不是用机器或网络教学全面替代教师。教师在育人过程中的主导作用不可替代。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1018, 7, 28, 'judge', 0.6, '乡村教师杨老师在偏远山区教学点坚守了20年一个人承担了从语文到数学再到音乐体育的所有课程。杨老师的行为体现了爱岗敬业的职业道德。', '[["A","正确"],["B","错误"]]', '["A"]', '爱岗敬业要求教师忠诚于人民教育事业勤恳敬业甘为人梯乐于奉献。杨老师在偏远山区坚守20年承担所有课程体现了对教育事业的热爱和敬业精神。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1019, 7, 29, 'judge', 0.6, '某中学组织教师参加校本研修要求每位教师每学期至少完成40学时的继续教育培训。该校的做法符合《教师法》关于教师培训进修权利的规定。', '[["A","正确"],["B","错误"]]', '["A"]', '教师法第七条规定教师享有参加进修或者其他方式的培训的权利。学校组织校本研修并规定学时要求既是保障教师进修培训权利的体现也符合教师继续教育的相关规定。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1020, 7, 30, 'judge', 0.6, '班主任吴老师在处理两名学生打架事件时，得知其中一名学生的家长是学校领导，便减轻了对该生的批评，对另一名学生则从严处理。吴老师这种区别对待的做法体现了为人师表的职业道德。', '[["A","正确"],["B","错误"]]', '["B"]', '为人师表要求教师坚守高尚情操、以身作则，平等公正地对待每一名学生。吴老师因学生家长身份不同而宽严不一，既不公正，也损害了教师的示范形象，违背了为人师表（也违背关爱学生中平等公正的要求）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1021, 7, 31, 'single', 1.0, '语文课上周老师在教草船借箭时先让学生自读课文然后提出几个关键问题引导学生思考：诸葛亮为什么要借船？为什么选在大雾天？周老师的做法主要体现了哪种教学原则？', '[["A","巩固性原则"],["B","直观性原则"],["C","启发性原则"],["D","量力性原则"]]', '["C"]', '周老师通过提出关键问题引导学生自己思考和发现正是启发性原则的体现。启发性原则要求教师调动学生学习的主动性引导他们独立思考。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1022, 7, 32, 'single', 1.0, '初三3班班主任赵老师发现班上有几个学生虽然成绩不好但在体育方面很有特长。赵老师安排他们组织一次年级篮球赛让他们负责策划和裁判工作。这几位同学的积极性大大提高学习成绩也开始进步。赵老师的做法主要体现了哪条德育原则？', '[["A","疏导原则"],["B","知行统一原则"],["C","集体教育原则"],["D","依靠积极因素克服消极因素原则"]]', '["D"]', '赵老师利用学生在体育方面的特长来激发自信心和积极性从而促进学习成绩提高正是依靠积极因素克服消极因素原则的体现。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1023, 7, 33, 'single', 1.0, '某小学在开展课后服务时开设了编程书法陶艺舞蹈等多种社团活动供学生自主选择。这主要体现了素质教育理念中的哪个要求？', '[["A","促进学生个性发展"],["B","面向全体学生"],["C","以培养创新精神为重点"],["D","促进学生全面发展"]]', '["A"]', '提供多种社团让学生自主选择尊重了学生的个体差异和兴趣特长体现了促进学生个性发展的要求。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1024, 7, 34, 'single', 1.0, '数学老师张老师在讲授一元二次方程时先给出一个实际问题：一块长方形菜地面积为24平方米长比宽多2米求长和宽。学生们列方程后发现不能用简单方法求解从而产生了学习新知识的需求。张老师运用的导入方式是', '[["A","复习导入"],["B","直接导入"],["C","故事导入"],["D","问题情境导入"]]', '["D"]', '张老师通过设置一个学生现有知识无法直接解决的问题情境引发学生的认知冲突和求知欲从而自然导入新课学习这属于问题情境导入法。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1025, 7, 35, 'single', 1.0, '生物课上，老师先系统讲解了“光合作用”的概念和反应过程，学生主要通过听讲、记笔记获得这一知识，并没有自己独立去发现结论。按照奥苏贝尔对学习的分类，学生的这种学习主要属于', '[["A","接受学习"],["B","试误学习"],["C","发现学习"],["D","观察学习"]]', '["A"]', '奥苏贝尔根据学习进行的方式，把学习分为接受学习和发现学习。接受学习是指学习内容以定论的形式直接呈现，学生通过教师讲授获得现成知识；发现学习则要求学生独立发现、创造经验。老师系统讲授、学生听讲获得现成结论，属于接受学习。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1026, 7, 36, 'single', 1.0, '某校在制定课程计划时将劳动教育纳入必修课每周安排1课时组织学生参与校园卫生社区服务等劳动实践。这一做法的依据是', '[["A","教育要以课堂教学为主"],["B","教育要以教师为中心"],["C","教育要与生产劳动和社会实践相结合"],["D","教育要促进学生的智力发展"]]', '["C"]', '将劳动教育纳入必修课并组织学生参与劳动实践体现了教育要与生产劳动和社会实践相结合的要求这是我国教育方针的重要内容。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1027, 7, 37, 'single', 1.0, '历史课上孙老师讲授完辛亥革命的内容后让学生分两组辩论辛亥革命是成功了还是失败了学生们各持己见据理力争。孙老师运用的教学方法是', '[["A","实验法"],["B","讲授法"],["C","讨论法"],["D","练习法"]]', '["C"]', '让学生分组辩论各抒己见据理力争正是讨论法的典型运用。讨论法是在教师指导下学生围绕某个问题发表和交换意见通过讨论获得知识。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1028, 7, 38, 'single', 1.0, '某中学的校训是博学笃行自强不息该校通过校园环境布置文化长廊主题活动等多种方式让校训精神浸润学生日常。这种德育方法属于', '[["A","品德评价法"],["B","实际锻炼法"],["C","情感陶冶法"],["D","说服教育法"]]', '["C"]', '通过校园环境布置文化长廊等方式让校训精神浸润学生日常属于情感陶冶法。情感陶冶法是通过创设良好的情境使学生潜移默化地受到熏陶和感染。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1029, 7, 39, 'single', 1.0, '小学二年级语文课上王老师让学生用生字卡片摆出不同的词语组合。小明摆出了小鸟飞翔小红摆出了飞翔的小鸟。王老师引导全班同学比较这两个短语有什么不同。王老师的做法最能体现的课程理念是', '[["A","课程即学科知识"],["B","课程即教学内容"],["C","课程即社会改造"],["D","课程即学习经验"]]', '["D"]', '王老师让学生通过动手操作比较发现来建构自己的理解强调的是学生的学习经验和体验过程体现了课程即学习经验的理念。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1030, 7, 40, 'single', 1.0, '在一次教研活动中有老师提出现在的学生越来越难管了应该制定更严格的校规来约束学生。但另一位老师认为与其严管不如引导学生自主管理。后一种观点的理论依据最接近', '[["A","杜威的儿童中心论"],["B","夸美纽斯的班级授课制"],["C","赫尔巴特的教育性教学原则"],["D","凯洛夫的教学中心论"]]', '["A"]', '引导学生自主管理强调以儿童为中心尊重学生的主体地位与杜威的儿童中心论最为接近。赫尔巴特强调教师中心凯洛夫也强调教师和教材中心。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1031, 7, 41, 'single', 1.0, '某市在推进义务教育均衡发展过程中将城区优质学校的骨干教师派往农村学校轮岗支教同时利用网络课堂实现城乡学校同步上课。这些措施主要体现了义务教育的', '[["A","免费性特征"],["B","均衡性要求"],["C","强制性特征"],["D","普及性要求"]]', '["B"]', '骨干教师轮岗支教网络课堂城乡同步都是为了缩小城乡教育差距促进教育公平体现的是义务教育的均衡性要求。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1032, 7, 42, 'single', 1.0, '初中地理课上郑老师在讲中国地形时让学生用沙盘和彩色橡皮泥制作中国地形模型用不同颜色表示不同海拔。郑老师运用的直观手段属于', '[["A","模象直观"],["B","言语直观"],["C","虚拟直观"],["D","实物直观"]]', '["A"]', '让学生用沙盘和橡皮泥制作地形模型模型是对实物的模拟属于模象直观。实物直观是直接观察实物本身模象直观是观察实物的模拟物。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1033, 7, 43, 'single', 1.0, '某小学在期末考试改革中将传统的纸笔考试改为项目展示：学生需要完成一个小课题研究制作一份调查报告并在班级展示。这种评价方式属于', '[["A","表现性评价"],["B","常模参照评价"],["C","终结性评价"],["D","诊断性评价"]]', '["A"]', '让学生完成小课题研究制作报告并展示考查的是学生在真实任务中的综合表现属于表现性评价。表现性评价关注学生在实际任务中的表现过程和能力展示。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1034, 7, 44, 'single', 1.0, '初二学生小强在学完英语过去时后发现之前学的现在时规则也能帮助自己更好地理解过去时的构成。从奥苏贝尔的知识同化理论来看这属于', '[["A","并列结合学习"],["B","上位学习"],["C","机械学习"],["D","下位学习"]]', '["A"]', '现在时和过去时是英语时态系统中两个并列概念它们之间不是上下位关系而是并列关系。学习过去时时借助了现在时的知识这是并列结合学习。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1035, 7, 45, 'single', 1.0, '小学三年级的小美每次做完作业后都会自己检查一遍。她说：“我妈妈每次检查我的作业都会说这里错了、那里也错了，现在我自己先检查一遍，就不用等妈妈来挑毛病了。”从学习策略角度看小美发展出的是', '[["A","复述策略"],["B","精细加工策略"],["C","组织策略"],["D","元认知策略"]]', '["D"]', '小美学会了自已检查作业这是对自身学习过程的监控和调节属于元认知策略中的监控策略。元认知策略包括计划策略、监控策略和调节策略。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1036, 7, 46, 'single', 1.0, '五年级的小刚在参加学校书法比赛时心想我一定要拿第一名不然太没面子了。结果因为过于紧张写出的字反而不如平时练习时好。从动机与效率的关系来看这说明', '[["A","动机越弱效率越高"],["B","中等强度的动机最有利于任务完成"],["C","动机越强效率越高"],["D","动机强度与效率无关"]]', '["B"]', '耶克斯- 多德森定律指出动机强度与工作效率之间呈倒U型关系：中等强度的动机最有利于任务完成。动机过强会导致焦虑和紧张反而降低效率。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1037, 7, 47, 'single', 1.0, '数学老师李老师发现每次用星星贴纸奖励积极发言的学生后全班举手发言的人数都会增加。这种现象可以用桑代克的哪条学习定律来解释？', '[["A","准备律"],["B","效果律"],["C","反射律"],["D","练习律"]]', '["B"]', '桑代克的效果律指出如果学习行为伴随着满足奖励该行为的联结就会增强。老师用星星贴纸奖励学生学生获得了满足感因此积极发言行为增加这正是效果律。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1038, 7, 48, 'single', 1.0, '初二学生小林对班主任说：“我知道上课说话不对，但我就是控制不住自己，一有想法就想说。”从品德心理结构来看小林最需要加强的是', '[["A","道德情感"],["B","道德行为"],["C","道德认识"],["D","道德意志"]]', '["D"]', '小林已经知道上课说话不对道德认识有也觉得不对道德情感有但控制不住自己说明他的道德意志薄弱。道德意志是指克服困难抵制诱惑坚持执行道德决定的心理过程。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1039, 7, 49, 'single', 1.0, '小学生在学乘法时先学2到5的乘法口诀再学6到9的乘法口诀。老师发现学生在学6到9的口诀时能利用已掌握的口诀来推导如6乘7等于5乘7加7。这种迁移属于', '[["A","顺向正迁移"],["B","逆向负迁移"],["C","逆向正迁移"],["D","负迁移"]]', '["A"]', '先学的知识对后学知识的影响是顺向迁移；促进作用是正迁移。先学的2到5口诀帮助学习6到9口诀是顺向正迁移。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1040, 7, 50, 'single', 1.0, '初二学生小芳在一次数学测验中只得了45分。她回到家后说：“我就是没有学数学的天赋，再努力也没用。”按照韦纳的归因理论小芳将失败归因于', '[["A","外部不稳定不可控因素"],["B","内部不稳定不可控因素"],["C","内部不稳定可控因素"],["D","内部稳定不可控因素"]]', '["D"]', '没有学数学的天赋即能力不足。在韦纳归因理论中能力属于内部稳定不可控的因素。小芳认为再努力也没用说明她将失败归因于能力。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1041, 7, 51, 'single', 1.0, '英语老师陈老师把本学期语法学习内容分解成一系列小单元，每学完一个小单元就让学生完成配套练习，答对率达到要求后才进入下一单元，并在练习后及时反馈对错。这种教学安排主要体现了斯金纳的哪一教学思想？', '[["A","非指导性教学"],["B","发现教学"],["C","范例教学"],["D","程序教学"]]', '["D"]', '程序教学由斯金纳基于操作性条件作用理论提出，基本做法是把学习内容分解为小步子，让学生循序渐进地学习，每一步都及时给予强化和反馈，学生自定步调。陈老师分解小单元、练习达标后再前进并及时反馈，正是程序教学的体现。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1042, 7, 52, 'single', 1.0, '小学四年级的数学老师刘老师在教分数加法时发现学生们普遍存在一个错误：把分子和分母分别相加。比如1/3加1/4学生算成了2/7。刘老师决定先让学生用纸条折叠来直观理解分数的含义。刘老师这样做的主要依据是', '[["A","练习可以有效纠正错误概念"],["B","学生正处于具体运算阶段需要借助具体操作来理解抽象概念"],["C","学生正处于形式运算阶段"],["D","学生已经能够完全进行抽象思维"]]', '["B"]', '四年级学生约9- 10岁处于具体运算阶段需要借助具体事物的支持来理解抽象概念。刘老师让学生用纸条折叠来理解分数含义符合这一阶段的认知特点。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1043, 7, 53, 'single', 1.0, '初中生小杰在学习中总是习惯把知识点抄写多遍来记忆。老师建议他尝试用自己的话解释每个知识点的含义，并画出知识点之间的关系图。老师建议的方法分别属于', '[["A","复述策略和组织策略"],["B","复述策略和精细加工策略"],["C","精细加工策略和组织策略"],["D","组织策略和精细加工策略"]]', '["C"]', '用自己的话解释知识点的含义属于精细加工策略（深层加工）；画出知识点之间的关系图属于组织策略（建构知识网络）。老师建议的是用精细加工策略和组织策略来替代单纯的复述策略。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1044, 7, 54, 'single', 1.0, '小学二年级的数学课上赵老师让学生在课堂上玩七巧板用七块板拼出各种图案。学生们玩得不亦乐乎。赵老师最可能运用了', '[["A","接受学习"],["B","发现学习"],["C","机械学习"],["D","程序教学"]]', '["B"]', '让学生通过操作七巧板自主探索拼出各种图案属于发现学习。发现学习强调学生通过自己的探索和发现来获得知识而不是被动接受教师传授的知识。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1045, 7, 55, 'single', 1.0, '高三学生小敏在高考前两个月开始感到极度焦虑。她每天学习到凌晨两点但白天总是犯困效率很低。心理辅导老师分析后认为小敏的问题最可能是', '[["A","智力水平有限"],["B","学习焦虑过高导致认知资源被占用"],["C","学习动机不足"],["D","缺乏正确的学习方法"]]', '["B"]', '小敏的极度焦虑占用了大量认知资源导致学习效率下降这是考试焦虑的典型表现。焦虑过高时认知资源被焦虑情绪占用而非用于学习任务导致效率下降。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1046, 7, 56, 'single', 1.0, '五年级的小明在学习了平行四边形的面积公式后能够推导出三角形和梯形的面积公式。这种学习属于加涅学习结果分类中的', '[["A","言语信息学习"],["B","动作技能学习"],["C","智慧技能学习"],["D","认知策略学习"]]', '["C"]', '运用平行四边形面积公式推导出其他图形面积公式属于运用规则解决问题的能力即智慧技能学习。智慧技能包括辨别、概念、规则和高级规则。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1047, 7, 57, 'single', 1.0, '刚接班时，班主任宣布“上课不许讲话”，学生大多是出于害怕受批评而暂时遵守；经过一段时间的班集体生活，学生逐渐认同班级纪律并愿意主动维护；到了高年级，即使老师不在教室，全班也能自觉保持安静。这一变化过程最能说明态度与品德的形成经历了', '[["A","认知、联结、自动化三个阶段"],["B","注意、保持、再现三个阶段"],["C","依从、认同、内化三个阶段"],["D","定向、模仿、熟练三个阶段"]]', '["C"]', '态度与品德的形成一般经历依从、认同和内化三个阶段：依从是表面上接受规范，具有被动性；认同是在思想、情感、态度上主动接受规范，试图与之保持一致；内化是将规范内化为自己的价值信念，自觉、主动地遵守。学生从害怕批评而守纪，到认同并维护纪律，再到无人监督也自觉遵守，正是依从、认同到内化的过程。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1048, 7, 58, 'single', 1.0, '初一学生小丽在日记中写道：“今天数学老师表扬了我，因为我主动帮同桌讲解了错题。我觉得帮助别人让我很快乐。”从科尔伯格的道德发展阶段来看小丽最可能处于', '[["A","前习俗水平的惩罚与服从定向阶段"],["B","前习俗水平的相对功利定向阶段"],["C","习俗水平的好孩子定向阶段"],["D","后习俗水平的社会契约定向阶段"]]', '["C"]', '小丽因为帮助别人获得快乐和老师表扬而觉得开心这体现了好孩子定向阶段的特点——寻求他人认可和赞赏希望做好孩子。这是习俗水平第三阶段的特征。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1049, 7, 59, 'single', 1.0, '初三学生小杨在准备中考时给自己制定了一份详细的学习计划表精确到每天每个时段复习什么科目。但执行一周后他发现计划太紧张根本完不成于是调整了计划的节奏。从元认知策略来看小杨运用的是', '[["A","计划策略监控策略和调节策略"],["B","监控策略和调节策略"],["C","计划策略和调节策略"],["D","计划策略和监控策略"]]', '["A"]', '制定学习计划是计划策略；执行一周后发现完不成是监控策略；调整计划节奏是调节策略。小杨完整地运用了元认知策略的三个子策略。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1050, 7, 60, 'single', 1.0, '在品德课上，老师讲述了“感动中国人物”张桂梅扎根山区、献身教育的事迹，学生们深受感染，纷纷表示要以她为榜样、好好学习回报社会。从德育方法来看，老师运用的是', '[["A","品德评价法"],["B","榜样示范法"],["C","实际锻炼法"],["D","情感陶冶法"]]', '["B"]', '榜样示范法是以他人的高尚思想、模范行为和卓越成就来影响学生品德的方法。老师讲述张桂梅的先进事迹，让学生以其为榜样，正是运用了榜样示范法。品德评价法是通过表扬、奖励、批评、处分等方式评价学生品德；情感陶冶法侧重以情境潜移默化地熏陶；实际锻炼法强调让学生在实践活动中磨练品德。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1051, 7, 61, 'single', 1.0, '某小学三年级学生小张在体育课跑步时不慎摔倒导致手臂骨折。经调查体育老师事先检查了跑道没有安全隐患上课时也进行了充分的热身活动。关于学校的责任下列说法正确的是', '[["A","学校和学生各承担一半责任"],["B","学校已尽到教育管理职责不承担侵权责任"],["C","学校应承担部分赔偿责任"],["D","学校应承担全部赔偿责任"]]', '["B"]', '三年级学生一般为8- 9岁属于限制民事行为能力人适用过错责任原则。学校已检查跑道无隐患并进行了充分热身尽到了教育管理职责不存在过错因此不承担侵权责任。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1052, 7, 62, 'single', 1.0, '某初中教师赵某在期末考试前将自己编写的复习资料以每本50元的价格强制要求学生购买。学生家长向教育局举报。赵某的行为违反了', '[["A","教育法关于教育投入的规定"],["B","义务教育法关于不得向学生推销商品的规定"],["C","未成年人保护法关于学校保护的规定"],["D","教师法关于教师义务的规定"]]', '["B"]', '义务教育法明确规定学校不得违反国家规定收取费用不得以向学生推销或者变相推销商品服务等方式谋取利益。赵某强制学生购买复习资料违反了此规定。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1053, 7, 63, 'single', 1.0, '某中学的校规中规定：学生在校期间严禁携带手机如被发现一律没收并销毁。该规定的合法性问题在于', '[["A","学校可以没收但销毁学生手机侵犯了学生的财产权"],["B","学校有权制定校规没收手机合法"],["C","只要家长同意就没问题"],["D","学校无权制定任何关于手机的规定"]]', '["A"]', '学校有权制定校规管理学生手机可以暂扣但销毁学生手机侵犯了学生的财产权。学生手机属于学生或其监护人的合法财产学校无权毁损。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1054, 7, 64, 'single', 1.0, '一名15岁的初三学生在学校组织的校外劳动实践中从脚手架上跌落受伤。关于本案的归责原则正确的是', '[["A","适用无过错责任学校必须赔偿"],["B","适用过错推定由学校自证无过错"],["C","适用过错责任需证明学校有过错"],["D","适用公平责任由双方分担损失"]]', '["C"]', '15岁学生属于限制民事行为能力人适用过错责任原则。根据民法典第1200条限制民事行为能力人在教育机构受到人身损害的学校未尽到教育管理职责的承担侵权责任。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1055, 7, 65, 'single', 1.0, '某县教育局决定撤销一名严重违反职业道德的公办学校教师的教师资格。该决定作出的法律依据是', '[["A","教育法"],["B","教师法"],["C","义务教育法"],["D","教师资格条例"]]', '["D"]', '教师资格的取得丧失和撤销依据的是教师资格条例。教师法规定了教师的基本权利义务但教师资格的具体管理由教师资格条例规范。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1056, 7, 66, 'single', 1.0, '学生小王在学校食堂用餐后因食物不洁导致腹泻就医。关于小王的医疗费用承担下列说法正确的是', '[["A","只能由食堂承包方承担"],["B","由学校和食堂承包方平均承担"],["C","只能由小王自己承担"],["D","由学校承担因为学校对食品安全负有管理责任"]]', '["D"]', '学校对校园食品安全负有管理责任。根据侵权责任法和食品安全法的相关规定学校食堂提供的食物导致学生食物中毒学校应当承担相应的赔偿责任。学校赔偿后可向食堂承包方追偿。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1057, 7, 67, 'single', 1.0, '某中学一名教师因学生未完成作业让学生在教室后面罚站一节课。学生的家长得知后向学校反映。该教师的行为主要违反了', '[["A","学生的受教育权"],["B","学生的人格尊严权"],["C","学生的财产权"],["D","学生的隐私权"]]', '["D"]', '罚站一节课属于变相体罚。变相体罚损害了学生的人格尊严违反了未成年人保护法中关于尊重未成年人人格尊严的规定。教师应当以适当方式教育不得实施体罚或变相体罚。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1058, 7, 68, 'single', 1.0, '高三第二次模拟考试前，小林发现白天听课效率下降，便把每晚挑灯夜读的时间提前一小时睡觉，保证第二天精力充沛，还把薄弱科目的复习安排在自己状态最好的上午。从学习策略的分类看，小林主要运用了', '[["A","认知策略"],["B","元认知策略"],["C","资源管理策略"],["D","精细加工策略"]]', '["C"]', '资源管理策略是辅助学生管理可用环境和资源的策略，包括学习时间管理、学习环境管理、努力管理和学业求助等。小林调整作息、合理安排学习时段，属于对时间与精力资源的管理，是资源管理策略。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1059, 7, 69, 'single', 1.0, '科学课上，学生在动手做“溶解”实验时，老师先让学生在小组内尝试完成自己能独立操作的步骤，如取盐、搅拌、观察；对学生无法独立完成的部分，如设计对照实验、分析变量，老师再给予提示和指导，帮助学生完成实验。老师在学生独立操作与需要帮助之间留出的空间，符合维果斯基提出的', '[["A","认知发展阶段理论"],["B","最近发展区理论"],["C","试误—联结理论"],["D","有意义接受学习理论"]]', '["B"]', '维果斯基认为，学生的发展有两种水平：独立完成任务所能达到的现有发展水平，和在成人或更有能力的同伴帮助下所能达到的潜在发展水平，二者之间的差距就是最近发展区。教学应着眼于最近发展区，提供适当支架帮助学生“跳一跳、摘果子”。材料中老师对学生能独立完成的部分放手、对无法独立完成的部分给予提示指导，正是最近发展区理论的运用。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1060, 7, 70, 'single', 1.0, '学校心理辅导室接待了几名家庭经济困难的学生，他们普遍反映最苦恼的是经常感到手头拮据、担心学费和生活费。辅导老师据此先帮助他们申请助学金、解决生活困难，再逐步引导其安心学习、追求更高层次的发展。这一辅导思路最能体现', '[["A","韦纳的成败归因理论"],["B","马斯洛的需要层次理论"],["C","阿特金森的成就动机理论"],["D","班杜拉的自我效能感理论"]]', '["B"]', '马斯洛将人的需要由低到高分为生理需要、安全需要、归属与爱的需要、尊重需要和自我实现需要等，低级需要基本满足后才会追求高级需要。学生为基本生活费用苦恼时难以安心追求发展性需要，老师先帮助解决生活困难再引导其学习发展，正体现了需要层次理论。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1061, 7, 71, 'single', 1.0, '班主任杨老师在批改学生作文时发现一名学生在作文中写道：“我长大后想当一名快递员，因为送快递赚钱多。”杨老师的恰当做法是', '[["A","不予理会因为作文内容不重要"],["B","批评学生的职业观太低"],["C","在班上公开讨论这个学生的职业理想让大家评价"],["D","在作文评语中肯定学生的想法同时引导其认识到每种职业都有价值"]]', '["D"]', '教师应尊重学生的想法同时引导学生树立正确的职业观。快递员的职业同样有价值不应贬低但在肯定学生思考的同时应引导其认识到更多职业选择和社会责任。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1062, 7, 72, 'single', 1.0, '新学年开始，班主任林老师在与原任课教师交接时得知学生小蕾“基础差、反应慢”。但林老师并未因此给小蕾贴上“差生”标签，而是相信她有潜力，课堂上多用鼓励的眼神关注她，提问难度适中的问题，批改作业时写下具体而有期待的评语。一学期后，小蕾果然变得自信、成绩稳步提升。这一现象最适合用下列哪一效应解释？', '[["A","首因效应"],["B","晕轮效应"],["C","罗森塔尔效应（皮格马利翁效应）"],["D","马太效应"]]', '["C"]', '罗森塔尔效应（皮格马利翁效应）是指教师对学生抱有积极期待，并通过态度、关注、评价等方式把期待传递给学生，学生会朝着教师期待的方向发展，使期待最终变为现实。林老师相信小蕾有潜力，并通过关注、鼓励、积极评语传递期待，促使小蕾进步，正是罗森塔尔效应的体现。马太效应指强者愈强、弱者愈弱；晕轮效应指以某一特征推及整体；首因效应指第一印象的深刻影响。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1063, 7, 73, 'single', 1.0, '某校组织新入职教师学习习近平总书记关于弘扬教育家精神的重要论述。张老师在学习笔记中写道，新时代教师应当把教育家精神落实到日常工作中。下列追求与教育家精神核心内涵不相符的是', '[["A","言为士则、行为世范的道德情操"],["B","追求名利地位、看重个人得失"],["C","启智润心、因材施教的育人智慧"],["D","心有大我、至诚报国的理想信念"]]', '["B"]', '教育家精神包括心有大我、至诚报国的理想信念，言为士则、行为世范的道德情操，启智润心、因材施教的育人智慧，勤学笃行、求是创新的躬耕态度，乐教爱生、甘于奉献的仁爱之心，胸怀天下、以文化人的弘道追求。追求名利地位、看重个人得失与教育家精神相悖。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1064, 7, 74, 'single', 1.0, '某小学教师周某在社交媒体上发布了一条贬损某位学生的不当言论被转发后引发社会关注。学校决定对周某进行批评教育并要求其删除相关言论。学校的做法体现了', '[["A","学校履行了保护学生权益和维护教师职业道德的职责"],["B","学校干涉了教师的言论自由"],["C","学校应该直接解聘周某"],["D","学校不应该干预教师个人生活"]]', '["A"]', '教师在网上发布贬损学生的言论违反了教师职业道德损害了学生权益。学校进行批评教育并要求删除相关言论是履行了保护学生权益和维护师德的职责。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1065, 7, 75, 'single', 1.0, '某中学开展了一项创新举措：每学期让学生给老师写匿名评价信作为教师考核的参考之一。这一举措的主要意义在于', '[["A","拓宽学生参与教学反馈的渠道"],["B","建立民主平等的师生关系，促进教学相长"],["C","确立学生在学校管理中的权威地位"],["D","取代教师对学生的日常评价"]]', '["B"]', '让学生给老师写评价信体现了民主平等的师生关系有利于教师了解学生的需求和感受促进教学改进和教学相长。这不是让学生管理老师而是建立双向沟通机制。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1066, 7, 76, 'single', 1.0, '新修订的未成年人保护法于2021年6月1日起施行。该法新增的与学校直接相关的制度是', '[["A","学生欺凌防控制度"],["B","教师资格考试制度"],["C","义务教育免费制度"],["D","教师轮岗制度"]]', '["A"]', '新修订的未成年人保护法明确了学校应当建立学生欺凌防控工作制度这是新增的重要内容。该制度要求学校建立学生欺凌防控工作制度对教职员工学生等开展防治学生欺凌的教育和培训。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1067, 7, 77, 'single', 1.0, '2023年教育部等部门联合印发了新时代基础教育强师计划。该计划的重点任务不包括', '[["A","提升教师思想政治素质和师德素养"],["B","完善教师待遇保障机制"],["C","提高教师培养层次和培养质量"],["D","调整城乡学校布局、撤并小规模学校"]]', '["D"]', '《新时代基础教育强师计划》的重点任务包括提升教师思想政治素质和师德素养、提高教师培养层次和培养质量、完善教师待遇保障机制等。调整城乡学校布局、撤并小规模学校属于学校布局调整范畴，并非该计划的重点任务。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1068, 7, 78, 'single', 1.0, '一位从教30年的老教师在教学研讨会上说：现在的孩子越来越聪明了但我们不能只教知识更重要的是教他们怎么学习怎么思考怎么做人。这位教师的观点最符合', '[["A","社会本位课程观"],["B","学科中心课程观"],["C","知识本位课程观"],["D","核心素养导向的课程观"]]', '["D"]', '这位教师强调不只教知识更重视教学生学会学习学会思考学会做人这正是核心素养导向的课程观。核心素养强调关键能力和必备品格而非单纯的知识传授。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1069, 7, 79, 'single', 1.0, '某中学在心理健康教育活动月中组织了情绪管理工作坊。心理老师让学生在纸上写下最近让自己烦恼的事情然后把纸折成飞机扔出去最后再捡起来分析烦恼是否真的那么严重。这种心理辅导方法属于', '[["A","理性情绪疗法"],["B","系统脱敏法"],["C","自由联想法"],["D","行为契约法"]]', '["A"]', '让学生写下烦恼事情分析其严重程度属于理性情绪疗法。理性情绪疗法的核心是改变不合理认知通过辩论和分析让学生认识到烦恼可能被夸大从而改变情绪反应。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1070, 7, 80, 'single', 1.0, '在班级管理中班主任赵老师采用了班级岗位轮换制让每个学生都有机会担任班长学习委员等职位。这一做法的主要目的是', '[["A","让学生体验不同的学科内容"],["B","减轻班主任的工作负担"],["C","让每位学生得到锻炼机会培养责任感和管理能力"],["D","选拔最优秀的班干部"]]', '["C"]', '班级岗位轮换制让每个学生都有机会担任不同职务目的是让每位学生都得到锻炼培养责任感和管理能力。不是减轻教师负担也不是选拔优秀干部。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1071, 7, 81, 'multi', 1.6, '初一班主任马老师在接手新班后发现班上有几类学生需要特别关注：学习困难但动手能力强的小刚性格内向但成绩优异的小美活泼好动但注意力不集中的小亮。马老师针对不同学生制定了不同的教育方案。马老师的做法体现了下列哪些教育原则？', '[["A","因材施教原则"],["B","循序渐进原则"],["C","长善救失原则"],["D","个别化教育原则"],["E","量力性原则"]]', '["A","C","D"]', '马老师针对不同类型学生制定不同教育方案，体现了因材施教原则（A）和个别化教育原则（D）；针对学生各自的优缺点扬长避短、因势利导，体现了长善救失原则（C）。材料没有体现按照学科逻辑由浅入深的循序渐进原则（B），也没有体现教学要适合学生发展水平的量力性原则（E）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1072, 7, 82, 'multi', 1.6, '某初中对学生综合素质评价办法进行修订：不再以期末一次纸笔测验作为升学评优的唯一依据，而是把课堂观察、作业完成情况、实验操作、社区志愿服务等一并纳入评价，采用“分数加写实评语”的方式记录成长，学科测试每学期只组织一次且不公布排名。下列对这一做法认识正确的有', '[["A","取消教师在评价中的作用，实现了评价主体的多元化"],["B","体现了评价内容的综合化"],["C","体现了评价方式的多样化"],["D","完全取消了考试的作用"],["E","有利于减轻学生的考试压力"]]', '["B","C","E"]', '采用分数加写实评语的方式记录、将课堂表现和实践活动纳入评价，体现了评价内容的综合化（B）和评价方式的多样化（C），也有利于减轻学生的考试压力（E）。评价主体多元化强调教师、学生、家长等多主体共同参与评价，材料并未体现取消教师作用，A表述错误；改革只是改进考试与排名方式，并非完全取消考试的作用，D错误。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1073, 7, 83, 'multi', 1.6, '初二学生小军在物理学习中表现出很强的兴趣。他不仅能准确理解物理概念还能独立设计实验方案验证自己的猜想。在物理竞赛中获得了一等奖。按照加涅的学习结果分类，小军的表现涉及了哪些学习结果？', '[["A","言语信息"],["B","智慧技能"],["C","认知策略"],["D","动作技能"],["E","态度"]]', '["A","B","C","E"]', '小军能准确理解物理概念，涉及言语信息（A）和智慧技能（B）；独立设计实验方案验证猜想，涉及认知策略（C）；对物理学习表现出很强的兴趣并主动投入竞赛准备，加涅所说的态度是个体对人、事物或活动的选择倾向，这种强烈、稳定的学科兴趣与主动趋近正是态度学习结果的体现（E）。材料中没有突出动作技能（D）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1074, 7, 84, 'multi', 1.6, '某中学在处理一起学生打架事件时，班主任的做法如下：先分别听取双方对事件经过的陈述，向双方讲清打架违纪的性质和同学相处应守的规则，再让双方交换位置扮演对方角色、说出如果自己是对方会怎么想，最后引导双方协商出彼此都能接受的和解办法。班主任的做法主要运用了下列哪些德育方法？', '[["A","说服教育法：通过摆事实、讲道理，使学生提高认识、明辨是非"],["B","品德评价法：通过奖励、惩罚、评比等方式对学生品德作出肯定或否定评价"],["C","榜样示范法：以先进人物的模范行为影响和教育学生"],["D","角色扮演法：让学生扮演特定角色，在换位体验中理解他人立场"],["E","实际锻炼法：组织学生参加各种实践活动，在活动中磨炼品德"]]', '["A","D"]', '班主任分别听取陈述、讲清打架违纪性质和相处规则，是通过摆事实、讲道理提高学生认识，运用了说服教育法（A）；让双方交换位置扮演对方、在换位体验中理解对方立场，运用了角色扮演法（D）。材料中没有出现奖励、惩罚、评比等品德评价手段（B不选）；没有以先进人物为典范的榜样示范（C不选）；也没有组织课外实践锻炼活动（E不选）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1075, 7, 85, 'multi', 1.6, '某校心理老师对全校学生进行了一次学习动机调查。调查发现：部分学生只关心考试排名能否超过别人、是否能得到老师表扬和家长奖励，对所学内容本身好不好奇、有没有弄明白并不在意；一旦排名下滑或得不到表扬，他们就不愿再努力。从学习动机不同分类角度综合分析，这些学生明显偏弱或缺失的动机成分是', '[["A","认知内驱力：指向学习任务本身、以求知和理解为目标的内部动机"],["B","自我提高内驱力：通过学业表现赢得相应地位与排名的动机"],["C","附属内驱力：为获得教师、家长等重要他人的赞许和接纳而学习的动机"],["D","近景的直接性学习动机：由近期的、与学习活动直接相连的兴趣所驱动"],["E","远景的间接性学习动机：由指向未来社会意义和个人前途的志向所驱动"]]', '["A","D","E"]', '按奥苏贝尔的成就动机分类，成就动机分为认知内驱力、自我提高内驱力和附属内驱力三种成分；按动机起作用时间长短，又可分为近景的直接性学习动机和远景的间接性学习动机。题干中学生"对所学内容本身好不好奇、有没有弄明白并不在意”，说明指向求知理解本身的认知内驱力偏弱（A应选）；他们非常在意排名和他人赞许，说明自我提高内驱力（B）和附属内驱力（C）反而较强，不属于"偏弱或缺失"。D项近景的直接性学习动机和E项远景的间接性学习动机是按动机起作用时间长短划分的另一种分类：学生只盯着排名、奖励等外部结果，既缺少对学习活动本身的直接兴趣（D偏弱），也缺少指向未来长期发展的远景性动机（E偏弱）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1076, 7, 86, 'multi', 1.6, '某小学教师在教学实践中运用了合作学习法。下列做法符合合作学习基本要求的有', '[["A","将不同水平的学生分在一组，形成异质小组"],["B","设定共同的学习目标，使小组成员积极互赖"],["C","采用同质分组，把学习水平相同的学生固定分在一组"],["D","对小组整体表现进行评价"],["E","组内成员明确分工，各自承担责任"]]', '["A","B","D","E"]', '合作学习的基本要求包括异质分组（A）、积极互赖（B）、个人责任（E）和小组整体评价（D）。把水平相同的学生固定同质分组（C）不利于成员间互助互补，也不符合合作学习异质分组的要求。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1077, 7, 87, 'multi', 1.6, '根据教师法的规定下列属于教师享有的权利有', '[["A","教育教学权"],["B","科学研究权"],["C","指导评价学生权"],["D","获取报酬待遇权"],["E","对违纪学生实施罚款等经济处罚的权力"]]', '["A","B","C","D"]', '《中华人民共和国教师法》第七条规定，教师享有教育教学权（A）、科学研究权（B）、管理学生（指导评价学生）权（C）、获取报酬待遇权（D）等权利。教师没有对学生实施罚款等经济处罚的权力（E），罚款也不属于法定教育惩戒方式，E错误。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1078, 7, 88, 'multi', 1.6, '初二数学老师在讲“用字母表示数”时，先让学生回忆英语中用字母缩写代替冗长词组的经验，再引导学生理解用字母表示数能够简明地表达数量关系。学生因此很快掌握了这一内容。从学习迁移的角度看，学生的学习主要包含', '[["A","正迁移"],["B","负迁移"],["C","逆向迁移"],["D","顺向迁移"],["E","垂直迁移"]]', '["A","D"]', '学生先学的英语字母缩写经验帮助其理解后学的“用字母表示数”，已有经验对新学习起促进作用，属于正迁移（A）；先学内容对后学内容产生影响，属于顺向迁移（D）。起促进作用而非干扰作用，故不是负迁移（B）；是后学受先学影响而非逆向迁移（C）；两类学习处于同一概括层次，不属于垂直迁移（E）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1079, 7, 89, 'multi', 1.6, '在教授光的折射这一课时物理老师王老师做了以下教学设计：先让学生观察筷子插入水中变弯的现象然后提出为什么的问题接着让学生分组做实验探究原因最后总结折射规律。王老师的教学过程中运用了', '[["A","直观性原则"],["B","启发性原则"],["C","探究式教学"],["D","以讲授法为主系统灌输"],["E","实验法"]]', '["A","B","C","E"]', '让学生观察筷子插入水中变弯的现象，体现了直观性原则（A）；提出“为什么”引导学生思考，体现了启发性原则（B）；组织学生分组做实验探究原因，体现了探究式教学（C）和实验法（E）。整个教学以观察、提问、实验探究为主，并非以讲授法系统灌输（D）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1080, 7, 90, 'multi', 1.6, '某中学教师在班级管理中实施了学生成长档案制度。为每位学生建立成长档案记录学生的学业成绩社会实践志愿服务特长发展等方面的信息并定期与学生和家长沟通。这一做法', '[["A","体现了综合素质评价的理念"],["B","体现了发展性评价的理念"],["C","体现了多元评价的理念"],["D","突出了评价的甄别与选拔功能"],["E","有利于促进学生的全面发展"]]', '["A","B","C","E"]', '成长档案记录学业成绩、社会实践、志愿服务、特长发展等多方面信息，并定期与学生、家长沟通，体现了综合素质评价（A）、发展性评价（B）和多元评价（C）的理念，有利于促进学生全面发展（E）。该做法强调激励、反馈与发展，而非突出甄别与选拔功能（D）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1081, 8, 1, 'judge', 0.6, '“音乐课上，陈老师教学生唱歌时，先让学生听一遍范唱，然后跟着旋律轻声哼唱，最后再完整演唱。这种从整体感知到逐步练习的教学方式体现了循序渐进原则。”', '[["A","正确"],["B","错误"]]', '["A"]', '循序渐进则要求教学由浅入深、由易到难、由整体到部分再到整体。陈老师先让学生听范唱整体感知，再轻声哼唱逐步练习，最后完整演唱，符合循序渐进的教学逻辑。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1082, 8, 2, 'judge', 0.6, '“某初中开展班级之间的小组合作竞赛活动，每个小组由不同学科水平、不同性格特点的学生组成，要求每人承担一项任务、共同为小组成绩负责。活动中，过去爱调皮但组织能力强的学生主动维持秩序，胆小但细心的学生负责记录。班主任据此认为，只要善于发现和利用学生身上的积极因素去克服消极因素，每个学生都能得到发展。班主任的这一做法体现了长善救失原则。”', '[["A","正确"],["B","错误"]]', '["A"]', '长善救失原则（依靠积极因素、克服消极因素的原则）要求教师一分为二地看待学生，善于发现学生的优点和闪光点，调动学生自我教育的积极性，依靠和发扬他们自身的积极因素去克服品德上的消极因素。班主任让调皮但组织能力强的学生维持秩序、让细心的学生负责记录，正是长善救失原则的体现。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1083, 8, 3, 'judge', 0.6, '“某小学在一次家长会上，校长介绍说，学校按入学考试成绩把新生分成快慢班，快班集中优质师资加快进度，慢班降低要求、只抓基础，这样能让不同层次的学生都得到适合的教育。校长的这一分层做法体现了因材施教的教育理念。”', '[["A","正确"],["B","错误"]]', '["B"]', '因材施教要求在面向全体学生的前提下，针对学生的差异采取有差异的教学，促进每个学生在原有基础上充分发展。仅凭一次成绩分快慢班、配置不均衡师资，实质是贴标签式的应试分班，违背教育公平和义务教育均衡发展要求，也不符合因材施教面向全体、尊重差异的本意。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1084, 8, 4, 'judge', 0.6, '“化学课上，孙老师在做演示实验前先让学生猜测实验结果，然后做实验验证。学生们发现实验结果和自己的猜测不同时，表现出了强烈的求知欲。孙老师的做法运用的是巩固性教学策略。”', '[["A","正确"],["B","错误"]]', '["B"]', '孙老师让学生先猜测再验证，当结果与猜测不一致时产生认知冲突，从而激发求知欲，这是建构主义教学中常用的引发认知冲突、创设问题情境的启发式策略，与通过复习练习巩固知识的巩固性策略无关。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1085, 8, 5, 'judge', 0.6, '“某中学将每周五下午设为社团活动时间，开设了辩论社、机器人社、文学社等二十多个社团供学生自由选择。这一举措属于课堂教学的有机组成部分。”', '[["A","正确"],["B","错误"]]', '["B"]', '社团活动是在课程计划和学科课程标准之外，由学生自愿参加的课外活动（课外、校外教育）的重要组织形式，不属于课堂教学。它丰富课余生活、促进个性发展，但与课堂教学在组织形式上有明确区别。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1086, 8, 6, 'judge', 0.6, '“在某小学的一次期中考试中，数学老师发现一道应用题全班的正确率只有百分之二十。老师没有责怪学生，而是反思了自己的教学方法，发现讲这道题时没有给足学生自主探究的时间。这种从考试结果反思教学的做法体现了教学评价的反馈功能。”', '[["A","正确"],["B","错误"]]', '["A"]', '教学评价的反馈功能，是指通过评价结果发现教与学中存在的问题，进而调整教学策略。老师从考试结果中发现问题、反思教法并改进教学，正是利用了评价的反馈功能。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1087, 8, 7, 'judge', 0.6, '“某小学在招生时规定，外来务工人员随迁子女除满足基本入学条件外，还必须额外缴纳一笔与本地学生不同的“捐资助学费”，否则不予登记入学。该校的这一做法违反了义务教育法关于免收学费、杂费和保障适龄儿童平等接受义务教育的规定。”', '[["A","正确"],["B","错误"]]', '["A"]', '《中华人民共和国义务教育法》规定，义务教育是国家统一实施的所有适龄儿童、少年必须接受的教育，不收学费、杂费；适龄儿童、少年不分性别、民族、种族、家庭财产状况、宗教信仰等，依法享有平等接受义务教育的权利。随迁子女在流入地依法平等接受义务教育，学校额外收取“捐资助学费”作为入学门槛，违反上述规定。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1088, 8, 8, 'judge', 0.6, '“在一次校本课程开发研讨会上，英语组的老师提出将本地的非物质文化遗产融入英语教学中，让学生在用英语介绍本地文化的同时增强文化自信。这种由学校自主开发、体现地方文化资源特色的课程属于国家课程。”', '[["A","正确"],["B","错误"]]', '["B"]', '这是学校结合本地文化资源自主开发、供本校学生学习的课程，属于校本课程；国家课程是由国家教育行政部门统一制定课程标准、在全国范围内统一实施的课程，不由学校自主开发。题中把校本课程说成国家课程。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1089, 8, 9, 'judge', 0.6, '“小学四年级学生小芳在写作文时，总是先列出提纲，想好每段要写什么内容，再动笔。从学习策略的角度看，小芳运用的是组织策略。”', '[["A","正确"],["B","错误"]]', '["B"]', '此处小芳列提纲是在动笔前对写作过程进行总体规划安排，属于元认知策略中的计划策略。需要辨析：如果是对已有的学习材料列提纲、归类整理、建构知识网络，则属于认知策略中的组织策略。本题题干明确是“写作文前规划每段写什么”，故为计划策略而非组织策略。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1090, 8, 10, 'judge', 0.6, '“英语考试结束后，小宇没有立刻交卷，而是按照老师平时训练的方法，回头检查答题卡是否涂错、时态是否写对、单词拼写是否漏字母。小宇在完成学习任务后对自己的认知活动进行检查和评价，这属于元认知策略中的调节策略。”', '[["A","正确"],["B","错误"]]', '["A"]', '元认知策略包括计划策略、监视（监控）策略和调节策略。学生在完成任务后主动检查、评价自己的认知活动与结果，发现问题及时修正，属于元认知策略中的调节策略。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1091, 8, 11, 'judge', 0.6, '“期末考试时，监考老师刚转身，小刚就想偷看同桌的答案，但一想到被抓到会受到批评和处分，便立刻收回了目光。从科尔伯格的道德发展阶段来看，小刚的道德判断处于前习俗水平。”', '[["A","正确"],["B","错误"]]', '["A"]', '小刚不作弊主要是因为害怕被批评、受处分，即根据行为会不会受到惩罚这一后果来判断对错，属于科尔伯格道德发展阶段理论中前习俗水平的惩罚与服从取向阶段。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1092, 8, 12, 'judge', 0.6, '“初二学生小军在学完浮力的概念后，能够运用浮力知识解释为什么铁块在水中下沉，而铁制的轮船却能浮在水面上。从布鲁姆教育目标分类来看，小军达到的认知层次是应用。”', '[["A","正确"],["B","错误"]]', '["A"]', '布鲁姆（布卢姆）教育目标分类在认知领域从低到高分为知识、领会、应用、分析、综合、评价。小军能把学过的浮力知识运用到新的具体情境中解释现象，不是简单的记忆或领会，属于应用层次。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1093, 8, 13, 'judge', 0.6, '“在体育课上，老师让学生反复练习跳绳动作，直到学生能够不假思索地流畅完成。从动作技能形成的阶段来看，这些学生已经达到了自动化阶段。”', '[["A","正确"],["B","错误"]]', '["A"]', '操作技能（动作技能）的形成一般经历操作定向、操作模仿、操作整合和操作熟练（自动化）阶段。自动化阶段动作流畅、准确、稳定，不需要意识的过多控制。学生能不假思索地流畅完成跳绳动作，说明已达到自动化（熟练）阶段。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1094, 8, 14, 'judge', 0.6, '“复习历史时，小航把零散的知识点按时间顺序整理成时间轴，把同一时期的政治、经济、文化事件归在一起对比记忆。这种对学习材料进行归类整理、构建知识之间内在联系的方法，属于认知策略中的组织策略。”', '[["A","正确"],["B","错误"]]', '["A"]', '组织策略是整合所学新知识之间、新旧知识之间的内在联系，形成新的知识结构的策略，常用方法有列提纲、利用图形和表格、归类等。小航把零散知识整理成时间轴并归类对比，正是组织策略的典型运用。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1095, 8, 15, 'judge', 0.6, '“一位小学老师发现班上有名学生每次举手回答问题时声音都很小。老师没有批评他，而是在他某次回答声音较为洪亮时，及时给予表扬，此后他大声回答问题的次数逐渐增多。这位老师运用的方法是斯金纳操作性条件作用中的惩罚。”', '[["A","正确"],["B","错误"]]', '["B"]', '学生表现出某一行为（大声回答）后，教师给予愉快刺激（表扬），使该行为发生频率提高，这属于正强化。惩罚则是通过呈现厌恶刺激或撤销愉快刺激，使行为发生频率降低。题干中行为次数是增多而非减少，故不是惩罚。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1096, 8, 16, 'judge', 0.6, '初中地理课上，老师要求学生阅读中国地形图，找出主要山脉、河流的位置和走向，然后自己画一幅简化版的中国地形图。从学习方式分类看，学生完成这一任务主要运用的是接受学习，这种说法是错误的。', '[["A","正确"],["B","错误"]]', '["A"]', '接受学习是学习者以定论形式接受教师呈现的现成知识；而学生通过观察地形图、独立寻找山脉河流的位置走向、再自行绘制简化地图，需要自己去发现事物之间的关系、动手建构认知，属于教师指导下的发现学习（探究学习），而非接受学习。因此，题干中主要运用的是接受学习这一说法确系错误，判断为正确。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1097, 8, 17, 'judge', 0.6, '“五年级学生小丽在准备语文考试时，把课文中需要背诵的段落反复朗读了很多遍，直到能一字不差地背出来。小丽运用的记忆策略属于精细加工策略。”', '[["A","正确"],["B","错误"]]', '["B"]', '反复朗读、重复识记直到背诵出来，属于复述策略（重复策略）。复述策略是通过对信息的反复重复来保持记忆；精细加工策略则是把新信息与已有知识建立联系、进行深层意义加工，如记忆术、做笔记、提问、类比等。小丽只是反复朗读背诵，没有对材料进行意义加工，故不属于精细加工策略。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1098, 8, 18, 'judge', 0.6, '“某中学在学期中组织了一次问卷调查，了解学生对各门学科教学的意见和建议，并把汇总结果反馈给任课教师，帮助教师改进后半学期的教学。这种在教学过程中进行、主要用于改进教学而不是评定学生等第的评价，属于形成性评价。”', '[["A","正确"],["B","错误"]]', '["A"]', '形成性评价是在教学过程中为改进和完善教学活动而进行的评价，如课堂提问、单元测验、问卷调查、作业分析等，目的在于及时了解教与学的进展、发现问题并改进教学。学期中通过问卷调查收集意见、反馈改进，符合形成性评价的特点。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1099, 8, 19, 'judge', 0.6, '“学了汉语拼音的小学生，刚开始学习英语字母时，常把英语字母“b”按汉语拼音读成“玻”，干扰了对英语字母读音的掌握。这种已有学习对后继学习产生消极影响的现象，属于负迁移。”', '[["A","正确"],["B","错误"]]', '["A"]', '一种学习对另一种学习产生阻碍、干扰作用，称为负迁移。学生用汉语拼音的读音去套英语字母，影响了新读音的建立，正是先前学习对后继学习的消极影响，属于负迁移。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1100, 8, 20, 'judge', 0.6, '“小学生在学习“白菜、萝卜、西红柿”等具体概念后，把它们归到“蔬菜”这一上位概念之下。这种将下位观念归属于认知结构中原有上位观念的过程，奥苏贝尔称之为下位学习（类属学习）。”', '[["A","正确"],["B","错误"]]', '["A"]', '奥苏贝尔根据新知识与原有认知结构的关系，把知识学习分为下位学习、上位学习和并列结合学习。新学习的概念（白菜、萝卜等）是原有上位概念（蔬菜）的例证，新观念归属于原有上位观念，属于下位学习（类属学习）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1101, 8, 21, 'judge', 0.6, '“一名小学教师发现班上有名学生的作文写得好，准备推荐其参加市级作文比赛。但该学生的家长以影响学习为由不同意孩子参加。教师应该尊重家长的决定，因为这属于家庭教育的范畴。”', '[["A","正确"],["B","错误"]]', '["B"]', '参加有益的教育教学竞赛活动属于学校教育教学安排的一部分，并非纯粹的家庭教育事项。家长有参与、配合学校教育的权利和责任，但不应简单阻止学生参加有利于其发展的正当活动。教师应主动与家长沟通，说明参赛对学生发展的积极意义，争取形成家校共育合力，而不是无条件服从家长决定。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1102, 8, 22, 'judge', 0.6, '“某中学一名学生在课堂上使用手机玩游戏被老师发现，老师没收了手机，并在下课后将手机摔碎以做效尤。该教师的做法虽然出发点是为了维护课堂纪律，但方式不当，侵犯了学生的财产权。”', '[["A","正确"],["B","错误"]]', '["A"]', '教师为维持课堂纪律，可以依照学校管理制度对学生违规使用的手机暂行保管并及时交还监护人，但无权损毁。摔碎手机导致财物灭失，侵犯了学生及其监护人的财产权，教师依法应承担赔偿责任。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1103, 8, 23, 'judge', 0.6, '“某市出台了一项政策，要求全市中小学在每年国家宪法日当天开展宪法主题教育活动。有人认为，这一要求的直接法律依据是《中华人民共和国教师法》。”', '[["A","正确"],["B","错误"]]', '["B"]', '在受教育者中开展宪法、法治教育的直接法律依据是《中华人民共和国教育法》第六条（国家在受教育者中进行法治教育）以及相关普法规划；《中华人民共和国教师法》主要规定教师的权利、义务、资格和待遇，并非学校开展学生法治教育的直接依据。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1104, 8, 24, 'judge', 0.6, '“看完电影后，小红对影片中主人公舍己救人的形象久久不能忘怀，一想到这个人物就心生敬佩。这种伴随着道德认识而产生的内心体验，在品德心理结构中属于道德情感。”', '[["A","正确"],["B","错误"]]', '["A"]', '品德的心理结构包括道德认识、道德情感、道德意志和道德行为（知、情、意、行）。道德情感是伴随着道德认识而产生的一种内心体验，如敬佩、憎恨、责任感等。小红对主人公的敬佩属于道德情感。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1105, 8, 25, 'judge', 0.6, '“某地教育督导机构对学校进行了年度办学水平评估后，将评估结果作为内部资料存档，不向社会公布。这一做法体现了教育督导的公开透明原则。”', '[["A","正确"],["B","错误"]]', '["B"]', '《教育督导条例》规定，教育督导机构应当向社会公布督导报告，接受社会监督。把评估结果仅作内部存档、不向社会公开，违背了督导结果公开的要求，并未体现公开透明原则。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1106, 8, 26, 'judge', 0.6, '“一位从教二十年的老教师王老师认为，自己教学经验已经十分丰富，教材内容也早已烂熟于心，因此没有必要再参加信息技术应用能力培训和各类教研活动。王老师的这种想法符合终身学习的师德规范。”', '[["A","正确"],["B","错误"]]', '["B"]', '《中小学教师职业道德规范》要求教师终身学习，崇尚科学精神，树立终身学习理念，拓宽知识视野，更新知识结构，潜心钻研业务，不断提高专业素养和教育教学水平。教育理念和信息技术不断更新，老教师同样需要持续学习，拒绝培训和教研的想法不符合终身学习要求。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1107, 8, 27, 'judge', 0.6, '“某中学教师孙某在微信朋友圈发布了一条含有商业推广内容的信息，并标注了自己所教学科和任教学校名称。孙某认为，朋友圈是私人空间，教师下班后在网上发布什么内容纯属个人自由，学校无权过问。孙某的这一认识是正确的。”', '[["A","正确"],["B","错误"]]', '["B"]', '《新时代中小学教师职业行为十项准则》要求教师坚守廉洁自律、规范从教行为，自觉维护教师职业形象。教师在公开可传播的社交媒体上标注任教学校和学科身份进行商业推广，已不只是纯粹的私人事务，可能损害为人师表的职业形象和学校声誉，学校有权依规提醒、管理。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1108, 8, 28, 'judge', 0.6, '“物理课上，老师要求学生独立设计实验方案。小军更习惯自己查阅资料、确定思路后再动手，较少受周围同学意见影响；同桌小周则喜欢先和同学讨论，参考他人的想法后再形成自己的方案。小军与小周在认知方式上的差异，分别属于场独立型和场依存型。”', '[["A","正确"],["B","错误"]]', '["A"]', '场独立型的学生在信息加工中更多依赖内在参照，独立判断、不易受外界干扰；场依存型的学生较多依赖外在参照，喜欢在与他人的交流讨论中获得信息、作出判断。小军独立查阅资料、自主确定思路，属于场独立型；小周偏好讨论、参考他人想法，属于场依存型。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1109, 8, 29, 'judge', 0.6, '“某中学初三班主任周老师为提高本班升学率，将班上几名成绩靠后的学生安排在教室最后一排单独就坐，很少提问他们，还在班会上公开说“成绩差的学生考不上高中，坐在教室里也是浪费资源”。周老师认为这是用激将法督促学生进步。周老师的这一做法符合关爱学生的师德要求。”', '[["A","正确"],["B","错误"]]', '["B"]', '《中小学教师职业道德规范》要求教师关爱学生：关心爱护全体学生，尊重学生人格，平等公正对待学生，不讽刺、挖苦、歧视学生。周老师按成绩把学生边缘化、当众贬低“成绩差”的学生，伤害学生人格和自尊，属于教育歧视，与关爱学生背道而驰，也不符合素质教育面向全体学生的要求。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1110, 8, 30, 'judge', 0.6, '“某中学一名班主任发现班上有名学生经常旷课，经多次联系家长均无回应。班主任认为联系不上家长就不必再上报，便没有将情况告诉学校。班主任的做法符合未成年人保护法的相关规定。”', '[["A","正确"],["B","错误"]]', '["B"]', '《中华人民共和国未成年人保护法》和《中华人民共和国预防未成年人犯罪法》规定，学校发现未成年学生旷课、逃学的，应当及时与其父母或者其他监护人取得联系；拒不配合或者联系不上的，学校应当及时向教育行政部门和有关部门报告。班主任联系不上家长后隐瞒不报，违反了强制报告的要求。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1111, 8, 31, 'single', 1.0, '语文课上，刘老师教学生阅读课文时，先让学生通读全文了解大意，再逐段分析，最后总结全文的写作手法。这种从整体到部分再到整体的教学思路体现了', '[["A","巩固性原则"],["B","循序渐进原则"],["C","直观性原则"],["D","启发性原则"]]', '["B"]', '先通读全文整体感知、再逐段细读分析、最后整体总结，是由浅入深、由整体到部分再到整体的有序推进，体现了循序渐进原则。A巩固性原则强调复习巩固，C直观性原则强调感性直观，D启发性原则强调调动学生思维。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1112, 8, 32, 'single', 1.0, '某小学四年级班主任在组织班级活动时采取了这样的方式：让全班同学一起讨论、制定班级公约，每个人都可以提出建议。班主任的这一做法体现了班级管理的', '[["A","教师中心模式"],["B","放任管理模式"],["C","民主管理模式"],["D","权威管理模式"]]', '["C"]', '班主任组织全班共同讨论、共同制定班级公约，人人都可以提出建议，体现了师生共同参与班级事务决策的民主管理模式。教师中心模式、权威管理模式强调教师单方面控制，放任管理模式则放弃必要的引导。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1113, 8, 33, 'single', 1.0, '某中学在推进课程改革时提出，要将学科知识与社会实践紧密结合，要求学生每学期至少完成一次社会调查报告。这一要求主要体现了', '[["A","综合实践活动课程的理念"],["B","学科课程的理念"],["C","活动课程的理念"],["D","隐性课程的理念"]]', '["A"]', '要求学生走进社会、完成社会调查报告，强调在真实社会情境中通过考察、探究、服务等实践活动学习，属于综合实践活动课程的理念。学科课程以系统学科知识为中心，活动课程侧重儿童经验活动，隐性课程是计划外的潜移默化影响。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1114, 8, 34, 'single', 1.0, '学生在学习“浮力”这一概念之前，头脑里已经有“木块能浮在水面上、铁块会沉底”的生活经验。物理老师据此先唤起这些经验，再引导学生理解影响浮力大小的因素。这位老师主要依据的理论是', '[["A","经典性条件作用理论"],["B","需要层次理论"],["C","形式训练说"],["D","建构主义学习理论"]]', '["D"]', '建构主义学习理论强调，学生不是空着脑袋走进教室的，他们在日常生活和先前学习中已形成丰富的经验，教学要把学生现有的知识经验作为新知识的生长点，引导学生从原有经验中“生长”出新的知识经验。教师唤起生活经验再建构浮力概念，正体现了这一理论。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1115, 8, 35, 'single', 1.0, '某市教育局在推进教育公平的过程中采取了以下措施：将城区优质学校的招生名额按比例分配到区域内各初中学校。这一措施的目的是', '[["A","提高优质学校的生源质量"],["B","促进义务教育优质均衡发展，缓解择校热"],["C","增加教育部门的财政收入"],["D","扩大优质学校与薄弱学校的差距"]]', '["B"]', '将优质普通高中招生名额合理分配到区域内各初中（指标到校），是促进义务教育优质均衡发展、遏制择校热、减轻学生过重学业负担的重要举措。其余选项或与政策方向相反（扩大校际差距），或与招生政策无关（增加财政收入）、指向错误（仅提高名校生源）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1116, 8, 36, 'single', 1.0, '物理老师在讲压强概念时，先让学生分别用一根手指和整个手掌按压气球，观察气球的形变程度，然后引导学生分析原因。物理老师运用的教学方法是', '[["A","讲授法"],["B","读书指导法"],["C","实验法"],["D","练习法"]]', '["C"]', '学生在教师指导下亲自动手操作、控制条件（手指与手掌）、观察现象并探究原因，属于实验法。讲授法以教师口头讲述为主，读书指导法侧重阅读指导，练习法侧重巩固性操练。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1117, 8, 37, 'single', 1.0, '某中学的德育主任发现，初二年级学生中出现了小团体现象，这些小团体有自己的规则和核心人物，有时甚至与班级规定冲突。德育主任应该采取的正确做法是', '[["A","立即解散所有小团体，禁止其活动"],["B","只关注小团体的核心人物，对其进行批评"],["C","听之任之，等待小团体自行消退"],["D","了解小团体的性质，因势利导，引导其融入班集体"]]', '["D"]', '学生中的非正式群体（小团体）客观存在、难以禁止。正确做法是了解其性质和形成原因，因势利导，做好核心人物的工作，引导其目标与班集体一致、融入集体。简单取缔、只批评核心人物或放任自流都不恰当。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1118, 8, 38, 'single', 1.0, '数学课上，老师讲完“长方形面积 = 长 × 宽”后，让学生用直尺测量课桌桌面、数学课本封面的长和宽并计算面积。依据加涅对学习结果的分类，学生学会用公式解决这些具体面积计算问题，主要属于', '[["A","言语信息的学习"],["B","智慧技能的学习"],["C","动作技能的学习"],["D","认知策略的学习"]]', '["B"]', '加涅把学习结果分为言语信息、智慧技能、认知策略、动作技能和态度五类。智慧技能是运用符号和规则对外办事、解决“怎么做”的问题，学生运用面积公式（规则）计算具体图形面积，属于规则的运用，是智慧技能的学习。言语信息解决“是什么”，动作技能依靠肌肉动作，态度是习得的内部倾向。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1119, 8, 39, 'single', 1.0, '在第一次家长开放日上，某位家长对校长说：“我的孩子在家从来不看书，怎么到了学校变得这么爱阅读了？”校长回答说：“这是因为学校创设了良好的阅读环境和氛围。”校长的回答强调的影响学生发展的因素是', '[["A","环境"],["B","遗传"],["C","个体主观能动性"],["D","家庭经济条件"]]', '["A"]', '学校创设的阅读环境、图书资源和阅读氛围，属于学生发展所处的环境因素，校长的回答正是强调经过改造的教育环境对人的发展的影响。遗传是生理前提，个体主观能动性是发展的内在动力，家庭经济条件与题意无直接关系。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1120, 8, 40, 'single', 1.0, '某小学开展了一门名为“小小科学家”的课程，让学生自主选择研究课题，在老师指导下进行实验探究，最后撰写研究报告。这种课程属于', '[["A","国家课程"],["B","地方课程"],["C","学科课程"],["D","校本课程"]]', '["D"]', '该课程由学校根据本校办学理念和学生需求自主开发、自主实施，属于校本课程。国家课程由国家统一制定，地方课程由省级教育行政部门规划，学科课程以学科知识体系为中心，均不符合。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1121, 8, 41, 'single', 1.0, '数学课上，李老师发现学生做应用题时经常忽略题目中的关键条件，便在教学中增加审题训练，要求学生读完整题后用笔圈出题目中的关键词和数据。从学习策略的分类看，这种圈点勾画的方法属于', '[["A","元认知策略"],["B","精细加工策略"],["C","资源管理策略"],["D","时间管理策略"]]', '["B"]', '圈点批注、圈画关键词和数据，是对阅读材料进行选择性注意和意义标注，使关键信息更突出，属于认知策略中的精细加工策略（也常与复述策略中的画线相联系）。元认知策略是对自身认知过程的计划、监控和调节；资源管理策略、时间管理策略针对学习资源与时间安排。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1122, 8, 42, 'single', 1.0, '初三学生小芳在考试前总是对自己说：“我已经复习得很充分了，一定能考好。”这种自我暗示的方法属于', '[["A","系统脱敏法"],["B","合理情绪疗法"],["C","自我暗示训练"],["D","自由联想法"]]', '["C"]', '学生通过有意识的内部语言给自己积极提示，以稳定情绪、增强信心，属于心理辅导中的自我暗示（自我指导）训练。系统脱敏通过逐级暴露消除焦虑，合理情绪疗法重在改变不合理信念，自由联想是精神分析技术。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1123, 8, 43, 'single', 1.0, '小学二年级的数学老师让学生在课堂上用小棒摆出不同的加法算式，来理解加法的含义，学生通过动手操作获得了丰富的数学体验。这位老师的做法最符合哪位教育家的思想？', '[["A","杜威"],["B","赫尔巴特"],["C","夸美纽斯"],["D","凯洛夫"]]', '["A"]', '让学生在动手操作、亲身活动中获得经验、理解知识，体现了杜威“教育即生活”“从做中学”的思想。赫尔巴特强调教师、教材、课堂三中心，夸美纽斯侧重班级授课与泛智，凯洛夫强调系统知识传授。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1124, 8, 44, 'single', 1.0, '初二学生小明在学习地理时，对气候类型总是记混。老师建议他把各种气候类型的特点编成顺口溜来帮助记忆。老师建议的方法属于', '[["A","复述策略"],["B","组织策略"],["C","精细加工策略"],["D","元认知策略"]]', '["C"]', '把难记的材料编成顺口溜、口诀，是通过谐音、韵律等方式为新材料附加意义、便于提取，属于精细加工策略中的记忆术。复述侧重简单重复，组织侧重归类建网，元认知侧重对认知的监控调节。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1125, 8, 45, 'single', 1.0, '高中开设法语选修课后，英语成绩较好的小周发现，法语中部分句式结构和词性变化与英语有相通之处，她借助英语语法知识理解法语句子，入门明显比其他同学快。这种现象在学习心理学中属于', '[["A","学习的负迁移"],["B","学习的逆向迁移"],["C","技能的高原现象"],["D","学习的正迁移"]]', '["D"]', '已掌握的英语语法知识对小周学习法语起到了促进作用，一种学习对另一种学习产生积极影响，属于正迁移。负迁移是一种学习对另一种学习的干扰：逆向迁移指后学习的内容对先前学习的影响，题干未强调这一方向：高原现象是技能练习中期出现进步暂时停顿的现象。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1126, 8, 46, 'single', 1.0, '在解答几何证明题时，小刚从要证明的结论出发，反向推导出“要证此结论，需先证什么”，一步步追溯到题目给出的已知条件。这种问题解决策略属于', '[["A","逆向反推法（手段—目标分析中的反推）"],["B","爬山法"],["C","类比启发法"],["D","算法式"]]', '["A"]', '从问题的目标状态出发，逐步反向推导到初始状态（已知条件），属于启发式中的逆向反推法（逆推法），在几何证明等问题中常用。爬山法是逐步降低当前状态与目标的差异，类比启发是借助相似问题的解法，算法式是按固定步骤穷尽求解。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1127, 8, 47, 'single', 1.0, '高一学生小华在学习中遇到不懂的问题时，总是先自己查阅资料、思考解决，实在想不出来才去问老师。从认知风格来看，小华属于', '[["A","场依存型"],["B","冲动型"],["C","场独立型"],["D","沉思型"]]', '["C"]', '小华遇到问题主要依靠自己的内部线索独立思考、自主判断，较少依赖外部提示，属于场独立型认知风格。场依存型倾向于以外在参照为依据；冲动型与沉思型区分的是反应速度与精确度。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1128, 8, 48, 'single', 1.0, '初二学生小红在数学考试中取得了好成绩，她把成功归因于自己这段时间的努力复习。按照韦纳的归因理论，这种归因方式对她后续学习的影响是', '[["A","会降低后续学习动机"],["B","对学习动机没有影响"],["C","会直接导致考试焦虑"],["D","会增强后续学习动机"]]', '["D"]', '在韦纳归因理论中，努力属于内部的、不稳定的、可控的因素。把成功归因于努力，学生会认为继续努力就能继续取得好成绩，从而增强后续学习动机。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1129, 8, 49, 'single', 1.0, '某小学三年级的数学老师发现，学生在学乘法口诀时总是把“六七四十二”和“七八五十六”记混。老师决定把这两组口诀放在一起对比教学，以减少相似材料之间的相互干扰。老师这一做法主要依据的是', '[["A","干扰理论"],["B","同化理论"],["C","强化理论"],["D","需要层次理论"]]', '["A"]', '两组口诀内容相似，学习时容易因前摄抑制、倒摄抑制而相互混淆，这正是干扰理论对遗忘原因的解释。把易混材料放在一起对比、辨析差异，可以提高区分度、减少干扰。同化理论强调新旧知识的相互作用，强化理论强调行为后果，需要层次理论属于动机理论。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1130, 8, 50, 'single', 1.0, '初中生写作文时，老师要求他们先列提纲再写作文。学生列提纲的过程属于写作过程中的', '[["A","翻译（表达）过程"],["B","修改过程"],["C","构思计划过程"],["D","检查过程"]]', '["C"]', '写作过程一般包括计划（构思）、转换（表达、翻译）和修改（检查）三个环节。动笔前列提纲，是对文章立意、选材、结构和顺序进行规划，属于构思计划过程。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1131, 8, 51, 'single', 1.0, '小学四年级的一名学生在做数学题时，总是先估算答案的大致范围，然后再精确计算。这种解题习惯体现了', '[["A","算法式策略"],["B","启发式策略"],["C","功能固着"],["D","逆向搜索"]]', '["B"]', '先凭经验和直觉估算大致范围，用以缩小搜索空间、指引精确计算方向，属于依靠经验规则的启发式策略。算法式是穷尽所有可能步骤保证求解，功能固着是只看到事物惯常用途的思维障碍，逆向搜索是从目标倒推。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1132, 8, 52, 'single', 1.0, '某中学心理老师发现，初一年级学生进入中学后普遍出现适应困难，表现为学习节奏跟不上、人际关系紧张等。心理老师决定开展团体辅导，帮助学生适应新环境。团体辅导最主要的理论依据是', '[["A","精神分析理论"],["B","行为主义理论"],["C","群体动力学理论"],["D","经典性条件作用理论"]]', '["C"]', '团体辅导借助团体成员之间的互动、相互影响和群体动力，促进成员自我认识与成长，其主要理论依据是勒温的群体动力学理论。精神分析侧重潜意识，行为主义和经典性条件作用侧重行为塑造。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1133, 8, 53, 'single', 1.0, '某小学老师在教学生认识分数时，先让学生分苹果，体验“平均分”的过程，再引入分数的概念。按照建构主义学习理论，这种做法的依据是', '[["A","知识是客观的，学习就是被动接受"],["B","学习是学习者基于已有经验主动建构意义的过程"],["C","学习是刺激与反应之间联结的建立"],["D","学习是观察者模仿榜样的过程"]]', '["B"]', '建构主义认为，学习不是知识由教师向学生的传递，而是学生以原有经验为基础，在真实情境和活动中主动建构意义的过程。学生先在“分享果”中获得平均分的经验，再建构分数概念，正体现这一观点。其余选项分别对应客观主义知识观、行为主义联结观和社会学习理论中的观察模仿。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1134, 8, 54, 'single', 1.0, '初三学生小杨在中考前制定了一份详细的复习计划，他根据各科的难易程度和自己的薄弱环节，合理分配每天的学习时间。小杨运用的是', '[["A","复述策略"],["B","组织策略"],["C","资源管理策略中的时间管理策略"],["D","精细加工策略"]]', '["C"]', '根据学科难度和自身薄弱环节统筹安排、合理分配学习时间，属于资源管理策略中的时间管理策略。复述、精细加工、组织策略都属于认知策略，针对信息加工本身，而非时间资源的配置。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1135, 8, 55, 'single', 1.0, '某中学开展了一项为期一学期的阅读计划，要求学生每月阅读一本课外书籍并写读书笔记，学期结束后发现参与学生的语文阅读理解成绩普遍提高。这项研究没有随机分组、也没有设对照组，其研究方法属于', '[["A","实验法"],["B","调查法"],["C","行动研究法"],["D","准实验法"]]', '["D"]', '研究有明确的干预措施（阅读计划）和前后观测，但在真实教育情境中未能随机分配被试、未严格设置对照组，符合准实验法的特征。真实验法要求严格控制和随机分组，调查法以问卷访谈收集资料为主，行动研究强调在实践中边行动边研究。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1136, 8, 56, 'single', 1.0, '初二学生小敏在学习中遇到困难时，总是告诉自己：“这道题虽然难，但我一定能想办法解决。”从自我概念的角度看，小敏表现出较高的', '[["A","学业自我效能感"],["B","学业焦虑"],["C","外部控制点"],["D","习得性无助"]]', '["A"]', '小敏相信自己有能力克服困难、完成学习任务，是对自身能否成功完成某一学习行为的主观判断，属于班杜拉提出的自我效能感（具体表现为学业自我效能感）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1137, 8, 57, 'single', 1.0, '某初中老师在批改学生作业时发现，一道题目的错误率很高。经过分析，老师发现大部分做错的学生都把题目中的隐含条件忽略了，老师据此调整了后续教学，增加了审题训练。老师的做法体现了', '[["A","教学评价的选拔功能"],["B","教学评价的诊断功能"],["C","教学评价的甄别功能"],["D","教学评价的奖惩功能"]]', '["B"]', '教师借助作业评价发现学生错误的具体表现和原因（忽略隐含条件），并据此改进教学，体现了教学评价的诊断功能。选拔、甄别功能侧重分等择优，奖惩功能侧重依据评价结果奖励或处分。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1138, 8, 58, 'single', 1.0, '小学三年级的老师发现，班上有名学生特别害怕在课堂上发言，每次被点名都紧张得说不出话。老师决定先让这名学生在小组内发言，适应后再逐步过渡到在全班发言。老师运用的方法是', '[["A","满灌疗法"],["B","自由联想法"],["C","系统脱敏法"],["D","理性情绪疗法"]]', '["C"]', '把引起焦虑的发言情境按压力大小排成等级（小组发言 → 全班发言），让学生在放松状态下逐级暴露、逐步适应，以消除焦虑反应，属于系统脱敏法。满灌疗法是直接置身最恐惧情境，自由联想属精神分析，理性情绪疗法重在纠正不合理信念。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1139, 8, 59, 'single', 1.0, '某中学的物理老师在教学电磁感应时，先让学生做实验、观察现象，再引导学生总结规律，最后用规律解释新现象。这种教学顺序体现了', '[["A","只归纳不演绎"],["B","归纳与演绎相结合"],["C","只演绎不归纳"],["D","与归纳、演绎均无关的机械记忆"]]', '["B"]', '先从具体实验现象中概括出一般规律，是从个别到一般的归纳；再用所得规律解释新的具体现象，是从一般到个别的演绎。两者前后衔接，体现了归纳与演绎相结合。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1140, 8, 60, 'single', 1.0, '某小学老师在教授古诗时，让学生根据诗句的内容画出画面，再用自己的语言描述画中的场景。这种教学方式的主要目的是', '[["A","培养学生的绘画技能"],["B","增加课堂趣味性、活跃气氛"],["C","降低古诗教学的知识难度"],["D","通过多感官参与和多重编码加深对诗歌内容的理解"]]', '["D"]', '把文字诗句转化为头脑中的画面并动手画出，再用口头语言重新表达，学生在这一过程中进行视觉表象编码和语义编码，多感官参与、多重编码有助于加深对诗歌意境和内容的理解。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1141, 8, 61, 'single', 1.0, '某中学一名学生在参加学校组织的运动会时受伤，经调查发现，学校在运动会前没有对场地器材进行安全检查。关于学校的责任，下列说法正确的是', '[["A","学生自愿参加运动会，风险自担，学校无责"],["B","学校未尽到教育、管理职责，应依法承担相应责任"],["C","应由运动会赞助商承担全部责任，与学校无关"],["D","学校在任何校外活动中都不承担责任"]]', '["B"]', '学校组织学生参加运动会，负有教育、管理和安全保障职责。赛前未对场地器材进行安全检查即存在过错，依据《中华人民共和国民法典》侵权责任编和《学生伤害事故处理办法》，学校应在过错范围内承担相应责任。认为自愿参加即风险自担、由赞助商承担全部责任等说法均不成立。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1142, 8, 62, 'single', 1.0, '教师节当天，有家长把一张面值不低的购物卡夹在孩子的贺卡里送给老师。老师发现后，第二天将卡原样退回，并向家长说明自己的态度。这位老师直接践行的师德规范是', '[["A","爱国守法"],["B","爱岗敬业"],["C","廉洁从教（为人师表）"],["D","关爱学生"]]', '["C"]', '《中小学教师职业道德规范》中“为人师表”要求教师坚守高尚情操、廉洁奉公，自觉抵制有偿家教，不利用职务之便谋取私利；《新时代中小学教师职业行为十项准则》也明确要求坚守廉洁自律。教师退回购物卡，直接践行的是廉洁从教的要求。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1143, 8, 63, 'single', 1.0, '某中学一名教师因与学生家长发生争执，在班级群中发布侮辱性不当言论，造成不良影响。学校对该教师进行了批评教育，并责令其向家长道歉。学校作出处理主要依据的是', '[["A","教师应当遵守职业道德、为人师表的有关规定"],["B","义务教育法中关于教学质量的规定"],["C","教育法中关于教育投入的规定"],["D","学校章程中关于作息时间的规定"]]', '["A"]', '《中华人民共和国教师法》规定教师应当遵守职业道德、为人师表；《中小学教师职业道德规范》《新时代中小学教师职业行为十项准则》也明确要求教师规范言行、尊重家长。该教师在班级群发侮辱性言论违背师德要求，学校据此处理。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1144, 8, 64, 'single', 1.0, '某小学一名学生在课间活动中被另一名同学用铅笔戳伤了眼睛。受伤学生家长下列做法中，最符合法定处理途径的是', '[["A","在学校门口拉横幅、堵门要求学校立即赔偿"],["B","在网络上公布对方学生和教师的个人信息进行声讨"],["C","拒绝任何协商，直接要求公安机关逮捕未成年学生"],["D","先与学校和对方学生监护人协商，协商不成可申请调解或依法提起诉讼"]]', '["D"]', '依据《学生伤害事故处理办法》，学生伤害事故发生后，当事人可以协商解决；协商不成的，可以向教育行政部门申请调解，也可以依法向人民法院提起诉讼。致害学生的监护人依法承担侵权责任，学校有过错的承担相应责任。拉横幅堵门扰乱秩序，公布个人信息侵犯隐私，要求逮捕未成年学生也不符合法律规定。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1145, 8, 65, 'single', 1.0, '某县教育局在校园安全检查中发现，一所学校未按规定配备必要的消防设施和器材，存在安全隐患，遂要求学校限期整改。该局这一要求的主要依据是', '[["A","《中华人民共和国消防法》及学校安全管理的有关规定"],["B","《中华人民共和国教师法》"],["C","《中华人民共和国民办教育促进法》"],["D","《中华人民共和国家庭教育促进法》"]]', '["A"]', '学校属于人员密集的公共场所，《中华人民共和国消防法》要求单位按照国家标准、行业标准配置消防设施和器材并保持完好有效，学校安全管理规定也对校园消防安全提出明确要求。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1146, 8, 66, 'single', 1.0, '某中学学生在学校食堂就餐后出现食物中毒症状，经调查确认是食堂加工的食材不新鲜、操作不规范导致的。关于赔偿责任，下列说法正确的是', '[["A","只能由食堂承包方承担，学校一律免责"],["B","由就餐学生自行承担，就餐出于自愿"],["C","学校应承担相应责任，赔偿后可依法向有过错的承包方追偿"],["D","由教育行政部门代替学校承担赔偿责任"]]', '["C"]', '学校对校内食堂食品安全负有管理责任，因食堂管理不善导致学生食物中毒的，学校应依法承担相应赔偿责任；食堂由第三方承包经营且承包方有过错的，学校赔偿后可依据承包合同和法律规定向其追偿。认为学校一律免责、学生自愿就餐风险自担或由教育行政部门代为赔偿，均不符合法律规定。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1147, 8, 67, 'single', 1.0, '某小学语文教师因几名学生背诵不过关，要求他们放学后把同一篇课文连抄五十遍，抄不完不准回家，致使部分学生写到深夜、手腕酸痛肿胀。该教师的行为', '[["A","是严格要求学生的正当做法，只要出发点是为了学生学习即可"],["B","属于变相体罚，超量罚抄加重了学生身心负担，应依法承担相应责任"],["C","只要没有造成医学上的重伤，就不属于违法"],["D","属于教师的教学自主权，家长和学校均无权干涉"]]', '["B"]', '超量罚抄课文五十遍并限制学生放学回家，使学生写到深夜、手腕酸痛肿胀，已超出正常教学惩戒的必要限度，属于以增加作业负担方式实施的变相体罚。依据《中华人民共和国义务教育法》《中华人民共和国未成年人保护法》和《中小学教育惩戒规则（试行）》，变相体罚学生为法律所禁止，教师应依法承担相应责任。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1148, 8, 68, 'single', 1.0, '某市教育局要求辖区内所有学校建立学生心理健康档案，定期对全体学生进行心理健康测评，并对测评结果严格保密。这一要求的主要依据是', '[["A","《中华人民共和国教师法》"],["B","《中华人民共和国民办教育促进法》"],["C","《中华人民共和国未成年人保护法》和学生心理健康工作的有关政策"],["D","《中华人民共和国学位条例》"]]', '["C"]', '《中华人民共和国未成年人保护法》明确学校应当根据未成年学生身心发展特点进行心理健康辅导、青春期教育和生命教育；教育部等部门关于加强学生心理健康管理工作的文件，要求建立健全学生心理健康档案、规范开展测评并保护隐私。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1149, 8, 69, 'single', 1.0, '课间，几位教师在办公室闲聊，一位教师把自己班级里一名学习困难学生的家庭隐私和成绩排名当笑料大声讲出来，引得旁人发笑，恰好被来送作业的该生听到。这位教师的做法', '[["A","只是同事间私下闲聊，没有在课堂上讲，无关紧要"],["B","不妥，泄露学生隐私、伤害学生自尊，没有起到应有的示范作用"],["C","只要所说内容属实，教师就可以随意谈论学生情况"],["D","有助于提醒其他教师关注该生，是负责任的表现"]]', '["B"]', '教师负有尊重学生人格、保护学生隐私的责任，其一言一行都对学生具有示范意义。把学习困难学生的家庭隐私和成绩排名当作笑料当众谈论，既泄露隐私、损害学生名誉和自尊，也违背为人师表、言行雅正的要求，会被学生直接感知，造成伤害。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1150, 8, 70, 'single', 1.0, '某初级中学以成绩不好为由，拒绝接收一名具有接受普通教育能力的轻度智力障碍适龄儿童入学。该校的做法', '[["A","违反了义务教育法和残疾人教育的有关规定"],["B","合法，学校有权根据成绩选择学生"],["C","只要家长同意，学校拒收就合法"],["D","经教育行政部门口头同意即可拒收"]]', '["A"]', '《中华人民共和国义务教育法》规定，学校不得拒绝接收具有接受普通教育能力的残疾适龄儿童、少年随班就读。该校以成绩为由拒收，违反义务教育法和《残疾人教育条例》关于融合教育的规定。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1151, 8, 71, 'single', 1.0, '某中学一名班主任发现班上有名学生连续三天没来上学，多次联系家长未果，便及时向学校报告，并协助学校上门家访、劝返复学。班主任的做法主要体现了', '[["A","教师的教学研究职责"],["B","教师的财务保管责任"],["C","教师的控辍保学责任"],["D","教师的招生宣传责任"]]', '["C"]', '义务教育阶段实行控辍保学责任制，发现学生无故缺课、辍学，班主任和学校应及时联系监护人、进行家访劝返，联系不上或监护人不配合的，应及时向乡镇人民政府、教育行政部门报告。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1152, 8, 72, 'single', 1.0, '某市教育局在全市中小学推行课后服务全覆盖，要求各学校因地制宜开设作业辅导、体育艺术、科普实践等多样化课后服务项目。这一举措的主要政策背景是', '[["A","落实“双减”政策，缓解家长接送和辅导负担"],["B","提高学校的升学率"],["C","增加教师的福利收入"],["D","压缩校外培训机构数量并取而代之"]]', '["A"]', '“双减”政策要求提升学校课后服务水平，满足学生多样化需求，推行课后服务“5+2”全覆盖，旨在减轻学生过重作业负担和校外培训负担，缓解家长接送、辅导难题。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1153, 8, 73, 'single', 1.0, '根据《中华人民共和国义务教育法》，凡年满六周岁的儿童，其父母或者其他法定监护人应当送其入学接受并完成义务教育；条件不具备的地区的儿童，可以推迟到', '[["A","六周岁半"],["B","七周岁"],["C","八周岁"],["D","九周岁"]]', '["B"]', '《中华人民共和国义务教育法》第十一条规定：凡年满六周岁的儿童，其父母或者其他法定监护人应当送其入学接受并完成义务教育；条件不具备的地区的儿童，可以推迟到七周岁。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1154, 8, 74, 'single', 1.0, '某校师德培训中，主讲老师讲到新时代教师队伍建设的根本任务和第一标准。下列说法正确的是：教师立身之本和评价教师队伍素质的第一标准是', '[["A","扎实学识"],["B","教学成绩"],["C","科研水平"],["D","师德师风"]]', '["D"]', '习近平总书记关于教育的重要论述和《关于全面深化新时代教师队伍建设改革的意见》明确，立德树人是教育的根本任务，师德师风是评价教师队伍素质的第一标准，是教师立身之本。扎实学识、教学成绩、科研水平都不是第一标准。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1155, 8, 75, 'single', 1.0, '某小学教师孙老师在课堂上发现一名学生偷偷看课外小说。孙老师没有当场没收训斥，而是在课后找到这名学生，与他聊课外阅读的话题，肯定他的阅读兴趣，并推荐了几本适合的书籍，引导他合理安排阅读时间。孙老师的做法体现了', '[["A","对学生违纪行为的纵容"],["B","关爱学生与教育机智的结合"],["C","对课堂纪律管理的忽视"],["D","只重赏识不加严格要求"]]', '["B"]', '孙老师既尊重、爱护学生，保护其阅读兴趣和自尊心，又善于选择恰当的时机和方式因势利导、规范引导，做到严慈相济，体现了关爱学生的职业道德与灵活处理课堂问题的教育机智。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1156, 8, 76, 'single', 1.0, '某中学一名教师在教学研讨会上提出：“现在的教育不能只关注学生的分数，更要关注学生的品德发展、身心健康和社会适应能力。”这一观点体现了', '[["A","应试教育的理念"],["B","精英教育的理念"],["C","知识本位、分数至上的理念"],["D","素质教育促进学生全面发展的理念"]]', '["D"]', '不只看分数，同时关注品德、身心、社会适应等方面，强调德智体美劳全面发展和全体学生的发展，正是素质教育的基本内涵。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1157, 8, 77, 'single', 1.0, '根据《中华人民共和国教师法》，取得初级中学教师资格应当具备的相应学历是', '[["A","高等师范专科学校或者其他大学专科毕业及其以上学历"],["B","幼儿师范学校毕业及其以上学历"],["C","高等师范院校本科或者其他大学本科毕业及其以上学历"],["D","研究生或者大学本科毕业学历"]]', '["A"]', '《中华人民共和国教师法》第十一条规定：取得初级中学教师、初级职业学校文化、专业课教师资格，应当具备高等师范专科学校或者其他大学专科毕业及其以上学历。取得幼儿园、小学教师资格的学历起点相应降低，取得高级中学教师资格应具备本科毕业及其以上学历，研究生学历对应高等学校教师资格的相应要求。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1158, 8, 78, 'single', 1.0, '初中语文老师陈老师在批改作文时发现，班上有学生为完成读书报告直接抄袭网络文章。陈老师没有简单打低分了事，而是专门安排一节课，和学生讨论“为什么读书要诚实”，引导学生理解抄袭对学风和个人成长的危害，并指导他们重写报告。陈老师的做法主要体现了', '[["A","只关注学生学业成绩、忽视品德引导的应试倾向"],["B","教师对学生错误一味迁就、不作要求的做法"],["C","教师脱离教学内容单独进行空洞说教的做法"],["D","教师在学科教学中渗透品德教育、做到教书育人"]]', '["D"]', '《中小学教师职业道德规范》要求教师教书育人：遵循教育规律，实施素质教育，循循善诱、诲人不倦，因材施教，做到德育与智育相统一。陈老师借助语文作业中的抄袭问题，因势利导地对学生进行诚信教育和学风引导，并指导改正，体现了在学科教学中渗透德育、教书育人。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1159, 8, 79, 'single', 1.0, '某中学开展了为期三个月的班级文化建设活动，各班自主设计班徽、班歌、班训，布置班级文化角。活动后，学生的集体归属感和班级凝聚力明显增强。从德育方法看，这一活动主要运用了', '[["A","情感陶冶法"],["B","说服教育法"],["C","品德评价法"],["D","榜样示范法"]]', '["A"]', '通过营造富有教育意义的班级文化环境和氛围，使学生在耳濡目染、潜移默化中受到熏陶感染，属于情感陶冶法（陶冶教育法）。说服教育法重在讲道理，品德评价法重在表扬批评，榜样示范法重在以模范人物影响学生。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1160, 8, 80, 'single', 1.0, '初中物理老师王老师在教学“光的折射”时，先让学生观察筷子插入水中“变弯”的现象，再提出问题“为什么筷子看起来是弯的”，然后让学生分组设计实验进行验证，教师巡回指导。王老师的这一教学过程主要体现了', '[["A","以传授系统书本知识为唯一任务的规律"],["B","学生可以脱离教师指导自发学习的规律"],["C","课堂只能由教师讲授、学生被动接受的规律"],["D","教师主导作用与学生主体作用相统一的规律"]]', '["D"]', '王老师提出问题、组织活动、巡回指导，发挥了教师的主导作用；学生观察现象、设计实验、合作验证，处于学习的主体地位，二者统一在同一教学过程中。把课堂理解为教师单向灌输、学生被动接受，或认为学生可以脱离教师指导自发学习，均不符合教学过程规律。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1161, 8, 81, 'multi', 1.6, '某校开展"同课异构"观课议课活动，几位青年教师围绕一堂数学课展开讨论。下列说法正确体现教学过程基本规律的有', '[["A","学生主要学习书本间接经验，因此完全不需要借助生活中的直接经验"],["B","整堂课教师精心设计问题、学生主动探究，说明教师主导与学生主体可以统一"],["C","学生只要把数学知识学懂了，思想品德自然就会同步提高"],["D","教师从学生已有的运算水平出发组织教学，学生掌握新知后思维能力也得到发展"],["E","课堂上教师讲得越满、学生记得越多，教学效果就越好"]]', '["B","D"]', '教学过程具有间接经验与直接经验相结合、教师主导与学生主体相统一、掌握知识与发展智力相统一、传授知识与思想品德教育相统一等基本规律。B体现教师主导作用与学生主体作用的辩证统一；D体现掌握知识与发展智力（能力）相互制约、相互促进。A割裂了间接经验与直接经验的联系，学生学习以间接经验为主但离不开直接经验基础；C把知识掌握与思想品德提高看作必然同步，忽视了教育性的自觉引导；E把教学理解为单向灌输，违背学生主体规律。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1162, 8, 82, 'multi', 1.6, '某中学班主任在德育工作中运用了多种德育原则。下列做法与所体现的德育原则对应正确的有', '[["A","对后进生既看到不足又善于发现其闪光点——长善救失原则"],["B","教育学生时做到严慈相济、尊重信任与严格要求相结合——严格要求与尊重信任学生相结合原则"],["C","引导学生在参加志愿服务和班级劳动中锻炼品德——知行统一原则"],["D","对全班学生犯的同一种错误，用同一句话当众训斥解决——因材施教原则"],["E","只要学生成绩好，其品德表现可以不予关注——正面教育与纪律约束相结合原则"]]', '["A","B","C"]', 'A项一分为二看待后进生、发扬优点克服缺点，对应长善救失原则；B项把尊重信任与严格要求结合、严慈相济，对应严格要求与尊重信任学生相结合原则；C项在实际活动中培养道德行为、做到言行一致，对应知行统一原则（理论与实践相结合原则）。用同一方式简单训斥全班并不是因材施教，D对应错误且方法不当；只看成绩忽视品德违背德育要求，与正面教育和纪律约束相结合原则无关，E错误。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1163, 8, 83, 'multi', 1.6, '某中学心理老师在教研中梳理学习迁移的类型。下列关于学习迁移分类的表述，正确的有', '[["A","学会骑自行车后，再学骑三轮车一定只会产生正迁移"],["B","“举一反三”“触类旁通”所说的正是学习中的迁移现象"],["C","掌握了汉语拼音的发音规则，可能促进也可能干扰英语语音学习"],["D","阅读中获得的审题方法迁移到数学应用题审题，属于一般迁移"],["E","英语阅读能力的提高反过来影响先前汉语阅读理解策略，可体现逆向迁移"]]', '["B","C","D","E"]', '学习迁移是一种学习对另一种学习的影响，“举一反三”“触类旁通”是迁移的典型表现，B正确；汉语拼音对英语语音学习既可能有促进（正迁移）也可能有干扰（负迁移），要看具体内容，C正确；一般迁移是将习得的一般原理、方法、策略迁移到新的学习情境，审题方法的迁移属于一般迁移，D正确；逆向迁移指后继学习对先前学习的影响，后学英语对已有汉语阅读策略的影响可体现逆向迁移，E正确。骑自行车与骑三轮车在平衡方式上存在冲突，再学骑三轮车往往受到干扰，“一定只会产生正迁移”的说法绝对化，A错误。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1164, 8, 84, 'multi', 1.6, '班主任李老师在创建新班集体的过程中开展了多项工作。下列做法中，直接有助于形成良好班集体的有', '[["A","开学第一周组织全班讨论，共同制定班级奋斗目标"],["B","指定全班各科成绩最好的一名学生独揽班级全部管理事务"],["C","通过民主选举建立班委会，并定期开展班干部培训"],["D","建立班级常规，制定课堂、卫生、考勤等规章制度"],["E","为提高成绩，按分数把学生分为三六九等并区别对待"]]', '["A","C","D"]', '培养良好班集体需要：确定共同奋斗目标（A）、建立健全组织机构与坚强领导核心（C，民主产生并培养班干部）、建立严格的组织纪律和健全规章制度（D）。让一名成绩好的学生独揽全部管理事务，既不符合民主管理，也不利于形成集体核心，B错误；按分数把学生分等、区别对待，违背教育公平和尊重学生的要求，会破坏集体团结，E错误。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1165, 8, 85, 'multi', 1.6, '新教师小吴想弄清教师教学工作包含哪些基本环节，于是观察指导教师的日常工作。下列做法中，属于教师教学工作基本环节的有', '[["A","研读课程标准和教材、分析学情，撰写课时教案"],["B","按教案组织课堂教学，引导学生学习新知"],["C","学校根据学区划分确定一年级新生的招生名单"],["D","家委会牵头组织学生参加商场开业的商业演出"],["E","总务处采购本学期的粉笔、作业本等办公用品"]]', '["A","B"]', '教师教学工作的基本环节包括备课、上课、作业的布置与批改、课外辅导和学业成绩的检查与评定。A钻研课标教材、分析学情、撰写教案属于备课，B按教案组织课堂教学属于上课，二者都是教学工作基本环节。C招生编班、E物资采购属于学校行政与后勤事务，不是教师教学工作环节；D组织学生参加商业性演出创收违背教育公益性和有关规定。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1166, 8, 86, 'multi', 1.6, '某中学组织教师学习学习动机理论，以改进激发动机的教学。下列关于学习动机理论的表述，正确的有', '[["A","马斯洛需要层次理论认为，较低层次的需要基本满足后，较高层次的需要才会出现"],["B","韦纳归因理论主张，教师应引导学生把失败归因于能力不足以保护其自尊"],["C","班杜拉自我效能感理论认为，成败经验是影响自我效能感最主要的因素"],["D","阿特金森成就动机理论把个体分为力求成功者和避免失败者"],["E","耶克斯—多德森定律表明，动机强度与学习效率之间呈倒U形关系"]]', '["A","C","D","E"]', '马斯洛把需要由低到高分为生理、安全、归属与爱、尊重、认知、审美和自我实现等层次，较低层次需要基本满足后，较高层次需要才会出现，A正确。韦纳归因理论强调教师应引导学生把失败归因于努力等内部、可控因素，而不是归因于稳定、不可控的能力不足——将失败归为能力不足会降低自我效能感、导致习得性无助，B错误。班杜拉认为个体自身的成败经验（直接经验）是影响自我效能感最主要、最有力的因素，C正确。阿特金森把成就动机分为力求成功和避免失败两种倾向，并据此区分个体类型，D正确。耶克斯—多德森定律表明动机强度与工作效率之间呈倒U形关系，中等强度动机效率最高，E正确。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1167, 8, 87, 'multi', 1.6, '家长会上，几位家长围着班主任周老师"取经"。周老师的下列做法中，符合《中小学教师职业道德规范》要求的有', '[["A","对送礼希望多关照自己孩子的家长，当场婉言谢绝并说明会公平对待每一名学生"],["B","利用家长资源请做生意的家长帮忙低价采购自家装修材料"],["C","与家长交流时只谈孩子的进步点和改进建议，不按家庭背景区别对待学生"],["D","应家长再三请求，在周末组织本班学生到自己参股的培训机构有偿补课"],["E","发现学生家长教育方式简单粗暴时，耐心指导其科学的亲子沟通方法"]]', '["A","C","E"]', '《中小学教师职业道德规范》要求教师为人师表、廉洁从教，关心爱护全体学生、平等公正对待学生，尊重家长、主动做好家校沟通。A婉拒礼品、坚持公平对待，体现廉洁从教与公正；C只就学生成长交流、不因家庭背景区别对待，体现平等公正；E指导家长改进教育方式，体现尊重家长、协同育人。B借家长职务便利谋取个人利益，D组织、要求学生参加有偿补课，均违背廉洁从教和规范要求。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1168, 8, 88, 'multi', 1.6, '数学王老师在备"一元一次方程"时，先分析学生独立能完成的题目水平，再据此设计"在同伴或教师提示下能够完成"的变式题，并通过小组互助让学生跨越差距。依据维果斯基的理论，下列分析正确的有', '[["A","学生独立解决问题的实际水平与在他人帮助下解决问题的水平之间存在差距"],["B","这个差距就是\\"最近发展区\\"，教学应当走在发展的前面"],["C","教师提示、同伴互助等支架有助于学生完成尚不能独立完成的任务"],["D","教学只能跟在学生已有发展水平之后，等其完全成熟再进行"],["E","一旦撤除所有帮助，学生的能力会立刻回退到原有水平，支架没有意义"]]', '["A","B","C"]', '维果斯基提出“最近发展区”，即儿童独立解决问题的实际发展水平与在成人指导或同伴合作下解决问题的潜在发展水平之间的差距，A正确；教学应当以最近发展区为依据、走在发展的前面，带动发展，B正确；教师和同伴提供的提示、示范等“支架”能帮助学生完成暂时不能独立完成的任务，并逐步内化、撤除支架，C正确。D主张教学只能消极跟随已有发展、等待成熟，与“教学走在发展前面”相悖；E否认支架在能力内化中的作用，学生借助支架掌握的能力会逐步转化为独立能力，并非撤除即回退。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1169, 8, 89, 'multi', 1.6, '某校依据《中小学教育惩戒规则（试行）》梳理教师实施教育惩戒的边界。下列情形中，教师及其所在学校不得对学生实施的行为有', '[["A","点名批评不服从教育管理的学生"],["B","以击打、刺扎等方式直接造成身体痛苦的体罚"],["C","辱骂或者以歧视性、侮辱性的言行侵犯学生人格尊严"],["D","因学业成绩而教育惩戒学生"],["E","因个人或者少数人违规违纪而惩罚全体学生"]]', '["B","C","D","E"]', '《中小学教育惩戒规则（试行）》明确禁止：以击打、刺扎等方式直接造成身体痛苦的体罚（B）；辱骂或者以歧视性、侮辱性言行侵犯学生人格尊严（C）；因学业成绩而教育惩戒学生（D）；因个人或少数人违规违纪而惩罚全体学生（E），故BCDE均属禁止行为。点名批评属于一般惩戒的法定方式之一，对应选项A不属于禁止行为。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1170, 8, 90, 'multi', 1.6, '体育组教师观察学生学习一套新广播操的过程：先看示范、听讲解记住动作要领；接着跟着模仿，动作僵硬且常有多余动作；反复练习后各节约动作趋于连贯、协调；最终比赛时能在队形、音乐变化中流畅完成。下列分析正确的有', '[["A","看示范、听讲解、记住动作结构与要求，是在头脑中建立操作的定向映象"],["B","跟做初期动作稳定性、准确性、灵活性较差，常出现多余动作"],["C","广播操一旦学会，以后再不练习也能永远保持原有水平"],["D","反复练习后各节动作趋于连贯协调、多余动作减少，属于操作整合"],["E","最终能在队形和音乐变化中流畅完成，说明动作达到高度熟练、具有适应性"]]', '["A","B","D","E"]', '操作技能的形成一般经历操作定向、操作模仿、操作整合、操作熟练四个阶段。A看示范听讲解、建立动作映象属于操作定向；B模仿阶段动作稳定性、准确性、灵活性较差、多余动作多；D整合阶段动作趋于协调连贯、多余动作减少；E熟练阶段动作高度自动化、适应性强，能在条件变化时顺利完成。C否认了技能保持依赖持续练习，技能长期不练会出现退化，故错误。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1171, 9, 1, 'judge', 0.6, '某小学规定，教师备课只需写满规定的课时数即可，教材钻研深不深、学情摸得准不准不作要求。该校的做法有利于提高备课效率，是合理的。', '[["A","正确"],["B","错误"]]', '["B"]', '该说法错误。教师备课要做到“三备”，即钻研教材、了解学生、设计教法，还要写好学期（学年）教学进度计划、课题（单元）计划和课时计划（教案）。只追求课时数量而忽视对教材和学情的深入研究，是典型的形式主义，会直接影响课堂教学质量。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1172, 9, 2, 'judge', 0.6, '王老师在教学中先呈现具体事例，引导学生观察比较，再归纳出一般概念和原理。这种由具体到抽象的做法符合教学的直观性原则。', '[["A","正确"],["B","错误"]]', '["A"]', '该说法正确。直观性原则是指在教学中通过学生观察所学事物或教师语言的形象描述，引导学生形成对所学事物、过程的清晰表象，丰富感性认识，从而能够理解书本知识、发展认识能力。先呈现具体事例帮助学生形成表象，再上升到抽象概念，是直观性与抽象思维相结合的体现。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1173, 9, 3, 'judge', 0.6, '教育能够生产新的科学知识、新的生产力，这体现了教育的经济功能。', '[["A","正确"],["B","错误"]]', '["A"]', '该说法正确。教育的经济功能不仅表现为再生产劳动力，还表现为再生产科学技术知识：高等学校教学与科研相结合，能够生产新的科学知识、创造新的生产力。这正是教育对经济发展能动作用的重要表现。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1174, 9, 4, 'judge', 0.6, '某校地处山区，就以“山里用不上外语”为由停开英语课，把课时全部加给语文、数学。这种做法是从本地实际出发，合理利用教育资源。', '[["A","正确"],["B","错误"]]', '["B"]', '该说法错误。教育必须与社会生产力发展水平相适应，并促进生产力发展。在开放和信息化社会，外语是学生适应现代生产和国际交往需要的基础素养，学校无权擅自停开国家课程方案规定的课程。以“用不上”为由停开英语，既违背课程方案要求，也剥夺了学生全面发展、适应未来社会的机会。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1175, 9, 5, 'judge', 0.6, '通过集体舆论、班风学风来约束和陶冶学生，属于德育方法中的品德评价法。', '[["A","正确"],["B","错误"]]', '["B"]', '该说法错误。品德评价法是教育者根据一定的要求和标准，对学生的品德进行肯定或否定的评价，以促使其发扬优点、克服缺点的方法，主要包括奖励、惩罚、评比和操行评定。题干描述的通过集体舆论、班风学风对学生进行约束和陶冶，属于情感陶冶法（陶冶教育法）中的环境陶冶，二者不能混淆。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1176, 9, 6, 'judge', 0.6, '“一把钥匙开一把锁”体现的德育原则是因材施教原则。', '[["A","正确"],["B","错误"]]', '["A"]', '该说法正确。因材施教原则是指进行德育要从学生品德发展的实际出发，根据学生的年龄特征和个性差异进行不同的教育，使每个学生的品德都能得到最好的发展。“一把钥匙开一把锁”强调针对学生个体差异有的放矢地教育，正是因材施教原则的通俗表达。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1177, 9, 7, 'judge', 0.6, '学校教育在人的身心发展中起主导作用，因此可以决定人的发展。', '[["A","正确"],["B","错误"]]', '["B"]', '该说法错误。学校教育对人的发展特别是对年轻一代的发展起主导作用，但这种主导作用是有条件的，它不能脱离遗传素质提供的生理前提，不能超越环境（特别是社会环境）的制约，也必须通过学生自身的主观能动性才能实现。认为学校教育可以“决定”人的发展，夸大了教育的作用，属于“教育万能论”。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1178, 9, 8, 'judge', 0.6, '无论是制定课程方案、组织课堂教学，还是衡量一所学校的办学质量，最终都要回到“培养什么人、怎样培养人”这一根本问题上来，以国家确立的教育目的作为总依据。', '[["A","正确"],["B","错误"]]', '["A"]', '该说法正确。教育目的是国家对培养人的总的要求，规定着人才的质量和规格，是一切教育工作的出发点和归宿，对教育工作具有全程性的导向、激励和评价作用。课程设置、课堂教学和办学质量评价都要接受教育目的的统领，围绕立德树人、促进学生全面发展来展开。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1179, 9, 9, 'judge', 0.6, '思维定势对问题解决只有消极作用，因此教学中应帮助学生彻底破除一切定势。', '[["A","正确"],["B","错误"]]', '["B"]', '该说法错误。思维定势（心向）对问题解决的作用具有双重性：当问题情境不变时，定势可以使人运用已掌握的方法迅速解决问题，起积极作用；只有当问题情境发生变化、需要新方法时，定势才会束缚思路、妨碍问题解决。教学中应培养学生灵活运用定势、根据情境及时调整的能力，而不是不加区分地“彻底破除”。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1180, 9, 10, 'judge', 0.6, '学生在阅读时遇到不懂的地方会放慢速度、回读，并在头脑中自问“我真的懂了吗”。这属于元认知策略中的调节策略。', '[["A","正确"],["B","错误"]]', '["A"]', '该说法正确。元认知策略包括计划策略、监控策略和调节策略。调节策略是根据对认知活动结果的检查，如发现问题、遇到障碍时，采取相应的补救措施，调整认知活动。遇到不懂处放慢速度、回读重读，是在监控基础上对阅读活动的修正，属于调节策略。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1181, 9, 11, 'judge', 0.6, '5岁的朵朵看到同样多的果汁从细高杯全部倒入矮粗杯后，坚持认为“细高杯里的果汁更多”。按皮亚杰的理论，这说明她已处于具体运算阶段。', '[["A","正确"],["B","错误"]]', '["B"]', '该说法错误。皮亚杰认为，守恒（认识到物体形状或容器改变而总量不变）是具体运算阶段（约7—11岁）才形成的成就；前运算阶段（约2—7岁）儿童的思维具有中心化、不可逆性等特点，容易被高度等单一显著特征“骗过去”，做出细高杯果汁更多的判断。朵朵5岁且不能完成液体守恒任务，正说明她处于前运算阶段，而非具体运算阶段。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1182, 9, 12, 'judge', 0.6, '“温故而知新”体现了教学的巩固性原则。', '[["A","正确"],["B","错误"]]', '["A"]', '该说法正确。巩固性原则是指教学要引导学生在理解的基础上牢固地掌握知识和基本技能，并使其长久地保持在记忆中，能根据需要迅速再现出来，以利于知识技能的运用。“温故而知新”强调通过复习旧知巩固所学、进而获得新的理解，体现了巩固性原则，也包含循序渐进的要求。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1183, 9, 13, 'judge', 0.6, '学生通过反复练习熟练掌握解题技能后，在考场上就能自动、准确地完成同类题目。这种熟练化的活动方式属于操作技能。', '[["A","正确"],["B","错误"]]', '["B"]', '该说法错误。技能按其性质和表现形式可分为操作技能（动作技能）和心智技能（智力技能、认知技能）。操作技能是通过学习而形成的合乎法则的操作活动方式，如体操、骑车、书写等，依赖肌肉骨骼动作，具有客观性、外显性和展开性；心智技能则是借助内部言语在头脑中进行的认知活动方式，如解题、运算、阅读等，具有观念性、内潜性和简缩性。解题的核心是分析、推理、运算等内部思维活动，即使经过反复练习达到自动化、熟练化程度，其性质仍属于心智技能，而非操作技能。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1184, 9, 14, 'judge', 0.6, '某地一家教育咨询公司以“投资回报高、股东可分红”为宣传，称举办面向义务教育阶段学生的学历教育学校也可以像普通企业一样以营利为目的。根据《中华人民共和国教育法》，这一说法是错误的。', '[["A","正确"],["B","错误"]]', '["A"]', '《中华人民共和国教育法》第二十六条规定，以财政性经费、捐赠资产举办或者参与举办的学校及其他教育机构不得设立为营利性组织；面向义务教育阶段的学历教育学校更不得以营利为目的。该公司以"投资回报高、股东可分红"为宣传，把举办义务教育学校等同于普通营利企业，没有任何法律依据，这一说法本身是错误的。题干判断"这一说法是错误的"与法律规定一致，故题干说法正确。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1185, 9, 15, 'judge', 0.6, '学生因屡次违纪被责令在教室外走廊站立一节课。这是教师对学生实施体罚的行为。', '[["A","正确"],["B","错误"]]', '["B"]', '该说法错误。依据《中小学教育惩戒规则（试行）》，体罚是直接造成身体痛苦的行为，如击打、刺扎等，或者超过正常限度的罚站、反复抄写。一节课堂教学时间内的教室内站立，属于规则明确列举的一般教育惩戒方式；但本题责令学生在"教室外走廊"站立，使其脱离正常教学，不符合"教室内站立"的要件，属于教育惩戒方式适用不规范，不能简单等同于体罚。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1186, 9, 16, 'judge', 0.6, '学会了打羽毛球的学生，初次接触网球时常常觉得挥拍发力方式与羽毛球相似，便按羽毛球的动作击球，结果频频下网。这种先前学习对后继学习产生的影响属于逆向迁移。', '[["A","正确"],["B","错误"]]', '["B"]', '该说法错误。先前学会的羽毛球动作对后来网球学习产生影响，是先前学习对后继学习的影响，按迁移作用的方向划分属于顺向迁移；由于错误地套用旧动作、造成了干扰，具体为顺向负迁移。逆向迁移指后继学习对先前学习产生的影响，题干描述的方向恰好相反。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1187, 9, 17, 'judge', 0.6, '教师职业良心是教师在教育实践中形成的对学生和社会的道德责任感与自我评价能力，是教师道德行为的内在调节器。', '[["A","正确"],["B","错误"]]', '["A"]', '该说法正确。教师职业良心是教师个人在自己的教育实践中，对社会向教师提出的一系列道德要求的自觉意识，是教师个人对学生、教师集体和社会自觉履行职责的道德责任感以及对自己教育行为进行道德控制和道德评价的能力，对教师的道德行为起着选择、监督和评价的内在调节作用。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1188, 9, 18, 'judge', 0.6, '教师给学生提供一定的学习支架并随着学生能力提升而逐步撤除支持，体现了“最近发展区”理论的教学主张。', '[["A","正确"],["B","错误"]]', '["A"]', '该说法正确。维果斯基认为，教学应着眼于学生的最近发展区，即学生现有水平与在成人指导或与同伴合作下可能达到的水平之间的差距。据此提出的支架式教学，主张教师在学生需要时提供适当支持，并随着学生独立能力增强而逐渐撤除支架，最终把学习责任转移给学生。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1189, 9, 19, 'judge', 0.6, '学习骑自行车后再学骑三轮车会感到别扭、容易受原有动作习惯干扰，这种现象属于倒摄抑制。', '[["A","正确"],["B","错误"]]', '["B"]', '该说法错误。倒摄抑制是遗忘理论中后学习的材料对回忆先学习材料的干扰作用，属于记忆现象；题干描述的是一种技能学习对另一种技能学习产生阻碍，属于学习迁移中的负迁移（具体为顺向负迁移）。二者一个针对记忆保持，一个针对技能学习，不能混为一谈。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1190, 9, 20, 'judge', 0.6, '教师通过展示实物、直观教具或示范性实验，让学生通过观察获得感性认识。这种教学方法是演示法。', '[["A","正确"],["B","错误"]]', '["A"]', '该说法正确。演示法是教师通过展示实物、直观教具，进行示范性实验或采取现代化视听手段等，指导学生通过观察获得感性认识的教学方法。题干描述的正是演示法。要注意演示法与实验法的区别：演示法以教师操作为主、学生观察；实验法多由学生亲自动手操作。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1191, 9, 21, 'judge', 0.6, '学生把考试成绩不好归因于“题目太偏、运气太差”。这种外部、不稳定、不可控的归因有助于激发后续学习动机。', '[["A","正确"],["B","错误"]]', '["B"]', '该说法错误。依据书纳成败归因理论，任务难度属于外部、稳定、不可控因素，运气属于外部、不稳定、不可控因素。把失败长期归因于任务难、运气差等外部因素，学生容易推卸自身努力的责任、产生听天由命的心态，不利于动机激发。教师应引导学生将失败主要归因于努力这一内部、不稳定、可控因素，增强其可控感和坚持性。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1192, 9, 22, 'judge', 0.6, '依据2016年修正的《中华人民共和国民办教育促进法》，民办学校的举办者都可以从办学结余中取得合理回报。', '[["A","正确"],["B","错误"]]', '["B"]', '该说法错误。2016年修正的《民办教育促进法》确立分类管理制度：民办学校分为非营利性和营利性两类，非营利性民办学校的举办者不得取得办学收益，学校办学结余全部用于办学；只有营利性民办学校的举办者才可以取得办学收益，学校办学结余依照公司法等有关法律、行政法规处理。"合理回报"是该法修正前的旧概念，新法已不再使用。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1193, 9, 23, 'judge', 0.6, '对学生进行思想品德教育只是班主任和思想品德课教师的工作，与其他学科教师关系不大。', '[["A","正确"],["B","错误"]]', '["B"]', '该说法错误。德育途径具有广泛性，思想品德课与其他学科教学是学校德育最基本的途径，各科教材中都包含丰富的德育因素。每一位教师都负有教书育人、在本学科教学中渗透德育的职责。把德育窄化为班主任和德育课教师的专门工作，违背了德育的一致性原则和全员育人要求。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1194, 9, 24, 'judge', 0.6, '新课改背景下的课堂教学中，学生主体地位的发挥并不意味着教师可以放弃主导作用。', '[["A","正确"],["B","错误"]]', '["A"]', '该说法正确。教学过程是教师主导作用与学生主体作用相统一的过程。发挥学生的主动性、让学生自主合作探究，离不开教师的组织、引导和点拨。新课改反对的是教师满堂灌、把学生当成被动接受知识的容器，而不是取消教师主导；放弃主导、放任自流同样违背教学规律。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1195, 9, 25, 'judge', 0.6, '教师的平均工资水平应当不低于当地公务员的平均工资水平。', '[["A","正确"],["B","错误"]]', '["A"]', '该说法正确。《中华人民共和国教师法》第二十五条规定，教师的平均工资水平应当不低于或者高于国家公务员的平均工资水平，并逐步提高；《义务教育法》也规定教师的平均工资水平应当不低于当地公务员的平均工资水平。这是保障教师待遇、稳定教师队伍的重要法律规定。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1196, 9, 26, 'judge', 0.6, '科尔伯格通过"道德两难故事法"研究儿童道德判断的发展，提出了道德发展的三水平六阶段理论，这一说法是正确的。', '[["A","正确"],["B","错误"]]', '["A"]', '该说法正确。科尔伯格采用海因茨偷药等道德两难故事，根据儿童回答的理由而非结论，把道德判断发展划分为前习俗水平（惩罚服从、相对功利）、习俗水平（寻求认可、遵守法规）和后习俗水平（社会契约、普遍伦理）三个水平共六个阶段。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1197, 9, 27, 'judge', 0.6, '教师把主要精力用于钻研教学、对学生提出的问题能耐心解答，这已经全面履行了《中小学教师职业道德规范》。', '[["A","正确"],["B","错误"]]', '["B"]', '该说法错误。《中小学教师职业道德规范（2008年修订）》包括爱国守法、爱岗敬业、关爱学生、教书育人、为人师表、终身学习六项内容。钻研教学、耐心答疑主要体现爱岗敬业和教书育人，不能替代关爱学生、为人师表、终身学习等要求，把部分要求当成全部，是以偏概全。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1198, 9, 28, 'judge', 0.6, '幼儿园老师发现，每当小朋友安静地把玩具收好，老师就当众表扬并贴一枚小红星，此后孩子们主动收拾玩具的次数明显增多。这一做法运用了斯金纳操作性条件作用理论中的正强化，这种说法是正确的。', '[["A","正确"],["B","错误"]]', '["A"]', '该说法正确。正强化是指个体做出某种行为后，通过呈现愉快刺激（如表扬、奖励）来提高该行为在将来发生的频率。老师在孩子收拾玩具这一行为之后及时给予表扬和小红星，使收拾玩具的行为增多，正是正强化的运用，与惩罚（呈现厌恶刺激或撤销愉快刺激以减少行为）有本质区别。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1199, 9, 29, 'judge', 0.6, '某校开展新课改后，把"小组合作学习"固定为每节课必须使用的形式，不管内容是否适合都一律分组讨论。这种做法符合新课改倡导的学习方式变革。', '[["A","正确"],["B","错误"]]', '["B"]', '该说法错误。新课改倡导自主、合作、探究的学习方式，但合作学习有其适用条件，应依据教学目标、内容特点和学生实际灵活选用。不看教学内容、把合作学习形式化、绝对化、"为讨论而讨论"，不仅会降低课堂效率，也背离了新课改转变学习方式的精神，属于典型的形式主义误区。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1200, 9, 30, 'judge', 0.6, '教育行动研究是教师在真实的教育教学情境中，为解决实际问题而进行的反思性研究，具有“为行动而研究、在行动中研究、由行动者研究”的特点。', '[["A","正确"],["B","错误"]]', '["A"]', '该说法正确。教育行动研究是教育实践工作者（主要是教师）在自然、真实的教育环境中，按照一定的操作程序，综合运用多种研究方法与技术，以解决教育实际问题为首要目标的研究模式，其基本特点是为行动而研究、在行动中研究、由行动者研究，强调研究与行动的统一。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1201, 9, 31, 'single', 1.0, '学生的年龄特征中，所指的两个方面是（　）。', '[["A","认识和情感的特征"],["B","气质和能力的特点"],["C","情感和意志的特征"],["D","生理和心理的特征"]]', '["D"]', '学生的年龄特征是指青少年学生在一定社会和教育条件下，不同年龄阶段所形成的一般的、典型的、本质的生理和心理上的特征，包括生理和心理两个方面。认识、情感、意志属于心理过程，气质、能力属于个性心理，都只是年龄特征的部分内容，不能完整概括。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1202, 9, 32, 'single', 1.0, '教师在教育工作中要做到循序渐进，这是因为（　）。', '[["A","学生只有机械记忆的能力"],["B","教育活动必须遵循学生身心发展的顺序性规律"],["C","教师的知识、能力是不一样的"],["D","教育活动完全受到人的遗传素质的制约"]]', '["B"]', '个体身心发展具有顺序性，决定了教育活动必须循序渐进，不能“拔苗助长”、“陵节而施”。A项否认了学生意义记忆等多种记忆能力，错误；C项教师素质差异与循序渐进无因果关系；D项夸大遗传作用、否认教育能动性，错误。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1203, 9, 33, 'single', 1.0, '中国古代的“六艺”——礼、乐、射、御、书、数，其课程类型属于（　）。', '[["A","学科课程"],["B","经验课程"],["C","活动课程"],["D","综合课程"]]', '["A"]', '学科课程是按不同的学科分门别类设置的课程，以系统知识为中心。“六艺”各有独立的知识体系和训练内容，属于典型的学科课程雏形。经验课程（活动课程）以儿童活动和直接经验为中心；综合课程强调打破学科界限，均不符合题意。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1204, 9, 34, 'single', 1.0, '“时过然后学，则勤苦而难成”说明教学工作应遵循的个体身心发展规律是（　）。', '[["A","顺序性"],["B","互补性"],["C","个别差异性"],["D","不平衡性"]]', '["D"]', '“时过然后学，则勤苦而难成”强调错过了适当的学习时机，即使勤苦也难有成就，说明身心有关键期、发展速度不均衡，对应身心发展的不平衡性，教育要抓住关键期。顺序性强调由浅入深、循序渐进；互补性强调机能间的补偿；个别差异性强调因材施教。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1205, 9, 35, 'single', 1.0, '小明读了《西游记》后，在头脑中想象出孙悟空的形象。这种想象属于（　）。', '[["A","创造想象"],["B","再造想象"],["C","无意想象"],["D","幻想"]]', '["B"]', '再造想象是依据词语或符号的描述、示意，在头脑中形成与之相应的新形象的过程。读小说后根据文字描述想象出人物形象，属于再造想象。创造想象是不依据现成描述而独立创造出新形象；无意想象是无预定目的、不自觉的想象；幻想是指向未来并与个人愿望相联系的想法。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1206, 9, 36, 'single', 1.0, '教师上课时“一题多解”，引导学生探寻多种解题思路。这体现了创造性思维的（　）。', '[["A","独创性"],["B","流畅性"],["C","变通性"],["D","序列性"]]', '["C"]', '创造性思维的基本特征包括流畅性、变通性（灵活性）和独创性。流畅性是指在规定时间内产生观念数量的多少；变通性是指思维朝不同方向发散、随机应变的能力；独创性是指观点新颖独特、不落俗套。“一题多解”强调从多个角度、多个方向寻求不同类型的解法，突出的是思维方向的灵活转换，属于变通性。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1207, 9, 37, 'single', 1.0, '“授人以鱼，仅供一饭之需；授人以渔，则终身受用无穷。”这句话强调教学中教师应当重视（　）。', '[["A","传授知识"],["B","培养学生品德"],["C","培养良好习惯"],["D","发展学生能力"]]', '["D"]', '“鱼”是现成的知识，“渔”是获取知识的方法和能力。这句话强调教学不仅要向学生传授知识，更要重视培养学生独立获取知识的能力，体现了掌握知识与发展能力相统一的规律。只重“鱼”理解片面；培养品德、习惯与题意主旨无关。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1208, 9, 38, 'single', 1.0, '学生掌握了大量的词汇，能写出通顺的句子，但在写自己熟悉的题材时仍然写不出高水平的作文。原因是学生缺乏（　）。', '[["A","陈述性知识"],["B","认知策略"],["C","动作技能"],["D","言语信息"]]', '["B"]', '学生掌握词汇、能写通顺句子，说明具备了一定的陈述性知识（言语信息）和基本表达技能；但写不出高水平作文，关键在于缺乏如何构思立意、谋篇布局、自我监控修改的认知策略。认知策略是对内调控自己认知活动的技能，决定了知识运用的水平。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1209, 9, 39, 'single', 1.0, '教师模拟了一场话剧，让学生扮演故事中的角色，体验人物的心路历程。该教师使用的教学方法是（　）。', '[["A","欣赏教学法"],["B","游戏教学法"],["C","情境教学法"],["D","发现教学法"]]', '["C"]', '情境教学法是教师创设具体生动的场景，引导学生通过体验来理解教材、获得发展的方法。模拟话剧、扮演角色、体验人物心理，核心是创设情境让学生身临其境，属于情境教学法。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1210, 9, 40, 'single', 1.0, '陈老师讲化学课“CO₂性质”时，先让学生分组完成CO₂使澄清石灰水变浑浊、使蜡烛熄灭的实验，再引导学生归纳性质。这一做法主要运用的教学方法是（　）。', '[["A","实验法"],["B","演示法"],["C","实习作业法"],["D","练习法"]]', '["A"]', '实验法是学生在教师指导下，利用一定的仪器设备和材料，通过控制条件的操作，引起实验对象发生变化，并从观察这些变化中获得新知识或验证知识的教学方法。学生亲自动手分组操作实验、观察现象、归纳性质，是实验法的典型特征。演示法以教师操作为主、学生观察。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1211, 9, 41, 'single', 1.0, '“柴也愚，参也鲁，师也辟，由也嗟。”教育教学要遵循人身心发展的（　）。', '[["A","顺序性"],["B","阶段性"],["C","个别差异性"],["D","互补性"]]', '["C"]', '孔子评价高柴愚直、曾参迟钝、颛孙师偏激、仲由鲁莽，说明不同学生各有特点。教育要针对每个人的差异因材施教，遵循的是身心发展的个别差异性。顺序性要求循序渐进；阶段性要求有针对性地施教；互补性要求扬长避短、长善救失。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1212, 9, 42, 'single', 1.0, '“双减”政策实施后，某校重新设计课后服务，组织学生参加阅读、科创、艺术、体育等社团活动，并为学习有困难的学生提供免费辅导。这一做法主要体现了“双减”政策的哪一要求？（　）', '[["A","全面压减作业总量和时长，减轻学生过重作业负担"],["B","全面取消校外培训机构，学校承担全部教育责任"],["C","把课后服务办成统一讲授新课的课堂教学延伸"],["D","提升学校课后服务水平，满足学生多样化需求，增强育人功能"]]', '["D"]', '《关于进一步减轻义务教育阶段学生作业负担和校外培训负担的意见》一方面要求压减作业总量和时长、减轻学生过重作业负担，另一方面要求提升学校课后服务水平，开展丰富多彩的科普、文体、艺术、劳动、阅读、兴趣小组及社团活动，并对学习有困难的学生进行辅导答疑。材料中的社团活动与免费答疑直接体现了提升课后服务质量、满足多样化需求的要求。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1213, 9, 43, 'single', 1.0, '学校物质文化是校园文化的空间物态形式，是学校（　）文化的物质载体。', '[["A","组织"],["B","精神"],["C","制度"],["D","观念"]]', '["B"]', '校园文化包括学校物质文化、学校组织和制度文化、学校精神文化。其中学校物质文化是校园文化的空间物态形式，是学校精神文化的物质载体，如校舍建筑、校容校貌、设施设备等都承载着学校的价值追求。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1214, 9, 44, 'single', 1.0, '“出淤泥而不染”“同流而不合污”，说明人的身心发展的源泉和动力在于（　）。', '[["A","社会环境"],["B","主观能动性"],["C","教育"],["D","遗传素质"]]', '["B"]', '同样处在污浊环境中却不被污染，说明环境对人的影响不是被动接受的，人可以发挥主观能动性对环境作出选择和反应。个体的主观能动性是人的身心发展的内在动力，也是促进个体发展从潜在可能状态转向现实状态的决定性因素。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1215, 9, 45, 'single', 1.0, '历史课上，学生把1894年甲午战争爆发编成“一把揪死（1894）”的口诀，把1900年八国联军侵华记成“八国联军一拎就灵（1900）”。这种学习策略属于（　）。', '[["A","复述策略"],["B","组织策略"],["C","精加工策略"],["D","元认知策略"]]', '["C"]', '精加工策略是把新信息与头脑中的旧信息联系起来，从而增加新信息意义的深层加工策略，常见方法有记忆术（如谐音联想法、缩减与编歌诀、位置记忆法）、做笔记、提问、生成性学习等。把抽象的历史年代编成谐音口诀，通过人为联想赋予枯燥数字以生动意义，属于记忆术的运用，是精加工策略。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1216, 9, 46, 'single', 1.0, '学生把已掌握的“阅读时概括段意”的方法，迁移到语文、历史、政治等多门学科的阅读中。这种迁移属于（　）。', '[["A","正迁移"],["B","垂直迁移"],["C","逆向迁移"],["D","一般迁移"]]', '["D"]', '一般迁移（非特殊迁移）是将一种学习中习得的一般原理、方法、策略和态度等迁移到另一种学习中去。把“概括段意”这一阅读方法运用到多门学科，迁移的是一般性的方法策略，属于一般迁移。正迁移按迁移性质划分，强调促进作用，不是最贴切的分类角度；垂直迁移是不同抽象概括水平之间的迁移；逆向迁移是后继学习对先前学习的影响。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1217, 9, 47, 'single', 1.0, '上课时，小明被窗外突然飞来的小鸟吸引，不由自主地转头去看。这种注意属于（　）。', '[["A","有意注意"],["B","有意后注意"],["C","随意注意"],["D","无意注意"]]', '["D"]', '无意注意（不随意注意）是没有预定目的、也不需要意志努力、不由自主地对一定事物发生的注意。窗外突然飞来的小鸟作为新异、突然出现的刺激，自然吸引学生转头去看，无需目的和意志努力，属于无意注意。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1218, 9, 48, 'single', 1.0, '学习新知识“梯形的面积”时，教师先复习“平行四边形的面积”，再把梯形转化为平行四边形推导公式。教师贯彻的教学原则是（　）。', '[["A","巩固性原则"],["B","因材施教原则"],["C","量力性原则"],["D","直观性原则"]]', '["A"]', '巩固性原则要求教学在学生牢固掌握已有知识技能的基础上进行，并不断巩固所学。教师先复习旧知，再以旧知为基础推导新知，既巩固了旧知识，又促进了新理解，贯彻的是巩固性原则。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1219, 9, 49, 'single', 1.0, '小学三年级的乐乐说：“我上课坐得端端正正、作业写得工工整整，就是想让妈妈在家长会上被老师点名表扬，看到她笑得特别开心。”按奥苏贝尔对成就动机的分类，乐乐的学习动机主要属于（　）。', '[["A","认知内驱力"],["B","自我提高内驱力"],["C","附属内驱力"],["D","生理性内驱力"]]', '["C"]', '奥苏贝尔把学校情境中的成就动机分为认知内驱力、自我提高内驱力和附属内驱力。附属内驱力是学生为了获得教师、家长等重要他人的赞许和接纳而努力学习的需要，在年龄较小的儿童身上表现尤为突出。乐乐努力表现是为了让妈妈因老师的表扬而高兴，本质上是在追求家长和教师的赞许。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1220, 9, 50, 'single', 1.0, '小张复习时发现：白天刚背熟的课文，晚上再背一遍用时明显变短，但隔了一周不复习又忘掉大半。这一现象最能说明（　）。', '[["A","遗忘的进程是先慢后快的"],["B","只要过度学习超过 200% 就不会发生遗忘"],["C","遗忘只受材料难度影响，与是否复习无关"],["D","遗忘在学习结束之后立即开始，且进程先快后慢"]]', '["D"]', '艾宾浩斯遗忘曲线表明，遗忘在学习之后立即开始，遗忘的进程是不均衡的，先快后慢、先多后少，呈负加速趋势，到一定程度就几乎不再遗忘。及时复习能迅速恢复、节省再学时间，长期不复习则遗忘量大。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1221, 9, 51, 'single', 1.0, '学生对自己能否在规定时间内完成一篇高质量作文的主观判断，属于班杜拉提出的（　）。', '[["A","自我价值感"],["B","自我效能感"],["C","自我决定感"],["D","自我同一性"]]', '["B"]', '自我效能感由班杜拉提出，是指人们对自己是否能够成功地从事某一成就行为的主观判断。学生判断自己能否完成高质量作文，正是对自身能否成功完成特定写作任务的能力信念，属于自我效能感。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1222, 9, 52, 'single', 1.0, '初中生小强多次拦截、殴打低年级同学并索要财物，学校拟对其进行教育惩戒。依据《中小学教育惩戒规则（试行）》，下列做法合法、适当的是（　）。', '[["A","给予记过、留校察看等纪律处分并永久记入个人学籍档案"],["B","责令其停课停学一学期，回家反省后再复学"],["C","由学校德育工作负责人予以训导，并安排其参加校内公益服务任务"],["D","责令其跑圈、深蹲等以强化体能"]]', '["C"]', '《中小学教育惩戒规则（试行）》规定，对违规违纪情节较重或者经当场教育惩戒拒不改正的学生，学校可以由德育工作负责人予以训导、安排其参加校内公益服务任务等。A项“留校察看”不在规则列举的处分种类内，且“永久记入”表述错误；B项停课停学不得超过一周，一学期明显超限；D项跑圈、深蹲直接造成身体痛苦，属于体罚，违法。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1223, 9, 53, 'single', 1.0, '某民办学校发布招生广告，承诺“入学即签订协议，保证学生初中毕业后直升本校高中部”，并据此提前组织招生。对该做法，下列认识正确的是（　）。', '[["A","民办学校招生应与公办学校同步招生，严禁以承诺升学等方式提前招生、掐尖招生"],["B","民办学校享有完全自主招生权，可以采取任何方式争抢生源"],["C","只有公办学校才受招生纪律约束，民办学校不受限制"],["D","该做法保障了学生升学，属于正当的合同自由"]]', '["A"]', '根据《民办教育促进法实施条例》及招生入学管理规定，民办义务教育学校招生纳入审批地统一管理，与公办学校同步招生，对报名人数超过招生计划的实行电脑随机录取；严禁民办学校通过承诺升学、提前招生、组织考试等方式掐尖抢生源，因此材料中的“协议直升、提前招生”违法。民办学校自主招生必须在统一招生规则和教育法律法规范围内行使；公、民办学校在招生纪律和规范办学上一体适用；违反法律强制性规定的所谓“升学承诺”无效。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1224, 9, 54, 'single', 1.0, '某小学要求家长轮流向交警举报学校周边闯红灯的车辆，并规定举报不足三次的家长其孩子不能参评“三好学生”。学校的这一做法（　）。', '[["A","是加强交通安全教育的合理举措"],["B","没有法律依据，且将家长配合义务与学生荣誉不当挂钩"],["C","属于合理分配社会治理任务的家校合作"],["D","属于学校自主管理权范围内的正常管理"]]', '["B"]', '学校无权向家长摊派举报交通违法的行政协助任务，更不能把家长是否完成摊派任务与学生的评优评先挂钩。该做法既没有法律依据，也违背教育规律，构成对学生受教育评价权的不当限制。学校自主管理权必须在法律框架内行使，不能以家校合作为名为家长和学生设定法外义务。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1225, 9, 55, 'single', 1.0, '某校组织新教师学习《中小学教师职业道德规范（2008年修订）》，要求准确把握六条规范各自的地位。下列表述正确的是（　）。', '[["A","关爱学生是教师职业的本质要求"],["B","爱岗敬业是教师职业的本质要求"],["C","为人师表是师德的灵魂"],["D","教书育人是教师职业的基本要求"]]', '["B"]', '六条规范各有定位：爱国守法是教师职业的基本要求，爱岗敬业是教师职业的本质要求，关爱学生是师德的灵魂，教书育人是教师的天职，为人师表是教师职业的内在要求，终身学习是教师专业发展的不竭动力。A项把本质要求错配给关爱学生；C项把师德的灵魂错配给为人师表；D项把基本要求错配给教书育人，均为张冠李戴。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1226, 9, 56, 'single', 1.0, '2023年9月，习近平总书记致信全国优秀教师代表，深刻阐释了中国特有的教育家精神。下列对教育家精神表述正确的是（　）。', '[["A","心有大我、至诚报国的理想信念，言为士则、行为世范的道德情操，启智润心、因材施教的育人智慧"],["B","只要升学率高、竞赛获奖多，就是践行了教育家精神"],["C","教育家精神是对少数教育家型校长的要求，与普通教师无关"],["D","教育家精神强调安于现状、固守经验，不必终身学习"]]', '["A"]', '中国特有的教育家精神包括：心有大我、至诚报国的理想信念，言为士则、行为世范的道德情操，启智润心、因材施教的育人智慧，勤学笃行、求是创新的躬耕态度，乐教爱生、甘于奉献的仁爱之心，胸怀天下、以文化人的弘道追求。B项把升学率、竞赛成绩当作唯一标准，是片面的应试导向；C项错误，教育家精神是全体教师的共同追求；D项与“勤学笃行、求是创新”相悖。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1227, 9, 57, 'single', 1.0, '为逼问丢失手机的下落，父亲在自己家中用皮带抽打10岁的儿子，致其背部多处瘀伤。邻居报警后，对该父亲的行为，下列说法正确的是（　）。', '[["A","管教亲生子女是家庭内部事务，任何机关都无权过问"],["B","只有造成重伤、死亡后果时，法律才能予以干预"],["C","家长可以采用任何方式管教未成年子女，法律一概不加限制"],["D","该行为属于家庭暴力，公安部门应当依法及时出警处置"]]', '["D"]', '《未成年人保护法》规定，父母或者其他监护人不得实施家庭暴力，不得虐待、遗弃未成年人。家庭暴力不是“家务事”，公安机关接到家庭暴力报案后应当及时出警，制止家庭暴力，按照有关规定调查取证，协助受害人就医、鉴定伤情。A、B、C三项均否认法律对家庭教育行为的必要干预，与《反家庭暴力法》《未成年人保护法》精神相悖。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1228, 9, 58, 'single', 1.0, '初中学生小明在语文课堂上故意把同桌的作业本撕毁，并当众顶撞教师、拒不停止扰乱课堂秩序的行为。依据《中小学教育惩戒规则（试行）》，任课教师当场可以对其实施的惩戒是（　）。', '[["A","点名批评，责令其向同桌赔礼道歉并赔偿损失"],["B","责令一节课的教室内站立，课后由班主任实施体罚"],["C","暂停其本学期参加一切课程学习的资格"],["D","给予不超过一学期的停课停学处分"]]', '["A"]', '《中小学教育惩戒规则（试行）》规定，学生有故意不完成教学任务要求或者不服从教育管理、扰乱课堂秩序等情形的，教师可以当场实施点名批评、责令赔礼道歉、做口头或者书面检讨、适当增加额外班级服务任务等惩戒。B项“教室内站立”须为一节课堂教学时间内，且教师不得实施体罚；C、D两项不属于教师当场可实施的惩戒，停课停学只能由学校对情节严重或影响恶劣的学生决定且不得超过一周。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1229, 9, 59, 'single', 1.0, '乡村教师老杨收到师范大学录取通知，打算利用两个寒暑假攻读在职教育硕士。开学前校长却放出话：“谁想读研先递辞职报告，本校一个在职深造的名额都不批。”对照教师法定权利，校长这一说法直接侵犯了老杨的（　）。', '[["A","参加进修或者其他方式培训的权利"],["B","教育教学与改革实验的权利"],["C","指导学生发展、评定学生品行和学业成绩的权利"],["D","按时获取工资报酬、享受福利待遇的权利"]]', '["A"]', '《教师法》规定，教师享有“参加进修或者其他方式的培训”的权利，这是教师不断提高思想政治觉悟和教育教学业务水平、实现专业发展的重要保障。教师利用寒暑假在职读研，并不影响正常教学，校长以“不批准深造、要读就辞职”相要挟，核心是阻挠教师进修培训。教育教学权、管理学生权均与题意无关；题干没有发生拖欠、扣发工资的事实。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1230, 9, 60, 'single', 1.0, '三年级学生小宇在学校组织的春游途中，不听教师反复强调的安全要求，趁教师清点其他学生人数时独自翻越栏杆拍照，失足摔伤。对小宇所受伤害，下列说法正确的是（　）。', '[["A","学校承担全部赔偿责任"],["B","带队教师个人承担全部责任"],["C","学校已履行相应教育、管理职责，且损害由学生自身过错造成，学校不承担责任"],["D","栏杆若符合安全标准，景区无责"]]', '["C"]', '依据《民法典》和《学生伤害事故处理办法》，学生伤害事故适用过错责任，学校已履行相应教育、管理职责的不承担责任。本题中学校组织春游时反复强调安全要求，损害是学生趁教师清点人数、不听劝阻擅自翻越栏杆造成的，学生自身存在重大过错，学校能够证明已尽到教育、管理职责。A项不问过错一概追责，错误；B项教师属职务行为，个人不对外承担全部责任。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1231, 9, 61, 'single', 1.0, '教师年度考核中，学校把学生满意度测评、教学成绩和教研成果按比例折算计分，对存在严重违反师德行为、被家长查实的教师，仍因“教学成绩突出”考核为优秀。这种做法（　）。', '[["A","正确，成绩好就是好教师"],["B","正确，师德评价只应在评优评先时一票否决，年度考核不必考虑"],["C","正确，师德难以量化，不宜纳入考核"],["D","错误，师德师风是评价教师队伍素质的第一标准，考核必须坚持师德第一标准"]]', '["D"]', '党中央和《关于全面深化新时代教师队伍建设改革的意见》等文件明确，把师德师风作为评价教师队伍素质的第一标准，在教师资格定期注册、业绩考核、职称评聘、评优奖励中首要考察师德表现，对师德失范行为实行“零容忍”和“一票否决”。该教师存在查实的严重违反师德行为，即使成绩突出也不能评为优秀。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1232, 9, 62, 'single', 1.0, '关于教师职业道德与法律，下列说法正确的是（　）。', '[["A","道德调整范围小于法律"],["B","道德调整范围大于法律"],["C","违反职业道德的行为必然构成违法"],["D","法律可以取代道德调节作用"]]', '["B"]', '道德与法律相互联系又相互区别。道德调整的范围比法律更广：法律只规范那些对社会秩序有重要意义的行为，而道德几乎涉及人们社会生活的一切领域，许多不违法的行为仍可能受到道德评价。C项违反职业道德只有同时违反法律规范时才构成违法，二者不必然重合；D项法律和道德各有不可替代的调节功能。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1233, 9, 63, 'single', 1.0, '教师的下列行为中，集中体现“为人师表”这一师德规范要求的是（　）。', '[["A","课上严格要求学生完成作业，课后从不与学生交流"],["B","只关注学生成绩，对学生品行表现不置可否"],["C","把学生分成三六九等，区别对待"],["D","衣着得体、言行雅正，自觉抵制有偿家教，以良好的身教影响学生"]]', '["D"]', '“为人师表”要求教师坚守高尚情操、知荣明耻、严于律己、以身作则，衣着得体、语言规范、举止文明，关心集体、团结协作、尊重家长，作风正派、廉洁奉公，自觉抵制有偿家教。D项从外在形象到内在操守完整体现了为人师表。A项缺少对学生的尊重关爱；B项违背教书育人；C项违背教育公平和关爱学生。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1234, 9, 64, 'single', 1.0, '13岁的初二学生小海多次结伙斗殴、携带管制刀具，经学校和家长多次教育管教仍不改正，已严重扰乱学校和社区秩序。依据《预防未成年人犯罪法》，下列处理方式符合法律规定的是（　）。', '[["A","学校直接将其开除，以维护正常教学秩序"],["B","经专门教育指导委员会评估同意后，由教育行政部门将其送入专门学校接受专门教育"],["C","由公安机关对其判处有期徒刑并收监执行"],["D","责令家长自行管教，任何组织和个人不得介入"]]', '["B"]', '《预防未成年人犯罪法》规定，对有严重不良行为的未成年人，公安机关可以根据具体情况采取矫治教育措施；未成年人有法定严重不良行为、情节恶劣或者造成严重后果，以及多次实施严重不良行为等情形，其父母或者其他监护人、所在学校无力管教或者管教无效的，可以向教育行政部门提出申请，经专门教育指导委员会评估同意后，由教育行政部门决定送入专门学校接受专门教育。A项错误，对接受义务教育的未成年学生不得开除；C项错误，13周岁的人依法不负刑事责任，且定罪量刑是人民法院的职权；D项错误，必要时国家机关应依法介入开展矫治教育。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1235, 9, 65, 'single', 1.0, '学生主动举手回答问题，教师当场给予表扬，此后该生举手更频繁。按照斯金纳操作性条件作用理论，教师运用的手段是（　）。', '[["A","正强化"],["B","负强化"],["C","惩罚"],["D","消退"]]', '["A"]', '斯金纳把强化分为正强化和负强化：正强化是通过呈现愉快刺激（如表扬、奖励）来提高反应发生的概率。学生举手后教师给予表扬，举手行为随之增多，属于正强化。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1236, 9, 66, 'single', 1.0, '下列学习情境中，属于正迁移的是（　）。', '[["A","习惯用方言声调入声朗读普通话，导致普通话发音总带方音"],["B","学会用左手写镜像数字后，正常书写时常把数字写反"],["C","练好了羽毛球的挥拍发力后，学习网球正手击球时上手更快、动作更协调"],["D","先形成的\\"会飞的都是鸟\\"的经验，使学生一度认为蝙蝠也是鸟"]]', '["C"]', '正迁移是指一种学习对另一种学习起到积极的促进作用。C项中羽毛球挥拍发力经验促进了网球正手击球的学习，属于正迁移。A、B两项中已有习惯对新学习造成干扰，D项中旧经验导致错误归类，都属于负迁移。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1237, 9, 67, 'single', 1.0, '学习策略中，学习者对自己学习过程进行自我监控和自我调节的策略是（　）。', '[["A","元认知策略"],["B","资源管理策略"],["C","精加工策略"],["D","组织策略"]]', '["A"]', '元认知策略是学习者对自己认知过程的认知策略，包括计划策略、监控策略和调节策略，核心是对学习过程的自我监控和自我调节。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1238, 9, 68, 'single', 1.0, '晚上刚背诵完一篇文言文就立刻睡觉，比背诵后继续做大量阅读题，第二天回忆文言文的效果通常更好。能够解释这一现象的概念是（　）。', '[["A","前摄抑制"],["B","消退说"],["C","倒摄抑制"],["D","压抑说"]]', '["C"]', '倒摄抑制（倒摄干扰）是指后学习的材料对保持和回忆先学习材料的干扰作用。背诵后立刻睡觉，没有后继活动干扰，文言文材料受倒摄抑制少，回忆效果更好；继续做阅读题则产生倒摄抑制。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1239, 9, 69, 'single', 1.0, '讲完等高线知识，老师带学生登上校园后面的小山坡，让大家亲手辨认山脊、山谷和陡崖，对着地形画草图，回校后再把草图与地形图上的等高线一一比对。这样安排最能体现的教学原则是（　）。', '[["A","量力性原则"],["B","理论联系实际原则"],["C","启发性原则"],["D","循序渐进原则"]]', '["B"]', '理论联系实际原则强调书本知识的讲授要同生活和社会实践结合，引导学生在亲身接触真实事物的过程中理解知识、运用知识。学生学过等高线后到真实山坡上辨认山脊、山谷与陡崖，再把手绘草图同地形图比对，正是带着地理概念回到真实地形中去印证和运用。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1240, 9, 70, 'single', 1.0, '建构主义学习理论认为，学习不是由教师把知识简单地传递给学生的过程，而是学生自己（　）知识的过程。', '[["A","主动建构"],["B","被动接受"],["C","机械记忆"],["D","反复抄写"]]', '["A"]', '建构主义认为，知识不是由教师直接传递给学生的，而是学习者在原有知识经验的基础上，在一定情境即社会文化背景下，借助他人帮助、利用必要学习资料，主动进行意义建构而获得的。被动接受是传统接受学习观；机械记忆、反复抄写是被动学习的外在表现。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1241, 9, 71, 'single', 1.0, '教师对学生持有积极的期待，认为学生有巨大发展潜能，学生往往真的会朝着教师期待的方向发展。这一效应称为（　）。', '[["A","马太效应"],["B","破窗效应"],["C","罗森塔尔效应"],["D","木桶效应"]]', '["C"]', '罗森塔尔效应（皮格马利翁效应、教师期望效应）是指教师的期望或明或暗地被传送给学生，学生会按照教师所期望的方向塑造自己的行为。马太效应指强者愈强、弱者愈弱的分化现象；破窗效应指不良现象如果被放任存在会诱使仿效；木桶效应强调最短板决定整体水平。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1242, 9, 72, 'single', 1.0, '学生已经掌握“哺乳动物”这一概念，知道哺乳动物是体表被毛、胎生哺乳的脊椎动物；后来学习“鲸”时，把鲸归入哺乳动物的类别中，认识到鲸虽生活在水中却不是鱼。从知识学习类型看，这主要属于（　）。', '[["A","上位学习"],["B","并列结合学习"],["C","命题学习"],["D","下位学习"]]', '["D"]', '下位学习（类属学习）是把新的、概括程度较低的观念归属于认知结构中原有概括程度较高的观念之下，并使之相互联系的过程。认知结构中已有概括程度较高的“哺乳动物”概念，新概念“鲸”作为具体例证被纳入其中，属于下位学习。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1243, 9, 73, 'single', 1.0, '班里一名学生腿有残疾、行动不便，个别同学私下给他起侮辱性绰号。班主任白老师在班会上组织“假如我是他”的换位体验，严肃批评起绰号的行为，又安排同学轮流帮他取饭、上下楼梯，并为他争取无障碍改造。白老师的做法集中践行了《中小学教师职业道德规范》中的（　）。', '[["A","终身学习，潜心钻研业务"],["B","依法执教，追究学生责任"],["C","关爱学生，平等公正对待并保护学生安全、人格尊严"],["D","廉洁从教，拒绝家长馈赠"]]', '["C"]', '“关爱学生”要求教师关心爱护全体学生，尊重学生人格，平等公正对待学生，保护学生安全，关心学生健康，维护学生权益，不讽刺、挖苦、歧视学生。白老师制止侮辱性绰号、保护残疾学生人格尊严，又组织同学帮助其在校生活、争取无障碍条件，集中体现了关爱学生。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1244, 9, 74, 'single', 1.0, '根据埃里克森人格发展阶段理论，中学生（青少年期）人格发展的主要任务是（　）。', '[["A","建立同一性，防止角色混乱"],["B","培养勤奋感，克服自卑感"],["C","发展主动性，克服内疚感"],["D","获得亲密感，避免孤独感"]]', '["A"]', '埃里克森认为，12—18岁的青少年期处于自我同一性对角色混乱阶段，发展任务是建立自我同一性、防止角色混乱，中学生正处在这一阶段。勤奋感对自卑感是学龄期（小学阶段）的任务；主动性对内疚感是学前期的任务；亲密感对孤独感是成年早期的任务。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1245, 9, 75, 'single', 1.0, '下列关于注意规律在教学中运用的做法，恰当的是（　）。', '[["A","交替运用讲授、提问、板书、演示和小组讨论，并强调重点内容"],["B","教师整节课用同一音量、同一语速平铺直叙地讲授"],["C","把所有教学用具上课前都堆放在讲台上展示"],["D","在教室四周布置大量鲜艳海报、播放背景音乐以营造氛围"]]', '["A"]', '教学中应正确运用无意注意与有意注意相互转换的规律：既要减少无关刺激的干扰，又要通过变化教学方式、突出重点来吸引和维持学生注意。B项单调刺激易使注意分散、产生疲劳；C项教学用具提前堆砌会引发无关注意；D项过多装饰和背景声音会成为分心刺激。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1246, 9, 76, 'single', 1.0, '班主任周老师发现学生小林近期情绪低落、在作文里多次流露消极念头，便私自将作文拍照发到班级家长群，要求家长“好好管教”。周老师的行为（　）。', '[["A","尽到了及时沟通的义务，并无不当"],["B","属于正常行使教育教学权的行为"],["C","只要情况属实，公开传播就不构成侵权"],["D","侵犯了小林的隐私权，也可能伤害其人格尊严"]]', '["D"]', '学生的作文、日记和内心流露属于个人隐私，未经本人或监护人同意不得公开传播。教师发现学生心理危机，应通过个别谈话、联系心理辅导教师、按规定告知监护人等适当方式审慎处理，拍照发家长群使信息在不特定多数人中扩散，侵犯了学生隐私权，也可能造成二次伤害。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1247, 9, 77, 'single', 1.0, '教师节前夕，某培训机构找到带毕业班的郑老师，提出按所介绍学生缴费金额的 20% 给其“辛苦费”，请他推荐学生参加高价冲刺班。郑老师当场拒绝，并提醒学生和家长警惕夸大宣传。郑老师的做法直接践行了《中小学教师职业道德规范》中的（　）。', '[["A","爱国守法"],["B","关爱学生"],["C","终身学习"],["D","为人师表"]]', '["D"]', '《中小学教师职业道德规范》中"为人师表"要求教师作风正派、廉洁奉公，自觉抵制有偿家教，不利用职务之便谋取私利。郑老师拒绝按人头收受培训机构回扣、不利用教师身份诱导学生参加高价培训，正是廉洁从教、为人师表的体现。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1248, 9, 78, 'single', 1.0, '对待犯错误的学生，李老师不是简单训斥，而是先讲明道理、疏通思想，再因势利导、以表扬激励为主。这体现的德育原则是（　）。', '[["A","疏导原则"],["B","知行统一原则"],["C","正面教育与纪律约束相结合原则"],["D","依靠积极因素克服消极因素原则"]]', '["A"]', '疏导原则是指进行德育要循循善诱、以理服人，从提高学生认识入手，调动学生的主动性，使他们积极向上，其要求包括讲明道理、疏导思想，因势利导、循循善诱，以表扬激励为主、坚持正面教育。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1249, 9, 79, 'single', 1.0, '小学低年级学生学习写汉字时，先要仔细观察范字的间架结构，再一笔一画地模仿，老师常要手把手纠正握笔和运笔动作。按照操作技能形成的一般规律，学生写汉字达到熟练，一般要经历的阶段是（　）。', '[["A","活动定向—物质活动—出声外部言语"],["B","认知阶段—联结阶段—自动化阶段"],["C","原型定向—原型操作—原型内化"],["D","操作定向—操作模仿—操作整合—操作熟练"]]', '["D"]', '我国心理学家通常把操作技能的形成分为操作定向、操作模仿、操作整合和操作熟练四个阶段：先了解活动结构（定向），再仿效示范动作（模仿），然后把各动作要素联结定型（整合），最后达到高度熟练、自动化（熟练）。B项是菲茨与波斯纳提出的三阶段模型；A项是加里培林心智技能形成阶段的表述；C项是心智技能形成的原型三阶段。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1250, 9, 80, 'single', 1.0, '初二年级实行“总分排名榜”，学校要求各科教师把主要精力放在可能考上重点高中的前20名学生身上，对其他学生“只要不违纪就行”。这一做法主要违背了《中小学教师职业道德规范》中的（　）。', '[["A","爱岗敬业要求教师乐于奉献"],["B","教书育人要求教师遵循教育规律、实施素质教育，面向全体学生、因材施教"],["C","为人师表要求教师衣着得体"],["D","终身学习要求教师不断更新知识"]]', '["B"]', '“教书育人”要求教师遵循教育规律、实施素质教育，循循善诱、诲人不倦、因材施教，培养学生良好品行，激发学生创新精神，促进学生全面发展，不以分数作为评价学生的唯一标准。只盯前20名、放弃其他学生，违背了面向全体、全面发展和因材施教的要求。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1251, 9, 81, 'multi', 1.6, '新学期，于老师决定改进作文评讲方式：作文批改后，他先选取两三篇典型习作（含优点明显和问题典型的），在隐去姓名后请全班讨论“好在哪里、怎样改更好”；再引导学生依据课堂共同梳理的评改标准互评同桌作文；对基础薄弱的学生，则单独面批、当面指导。于老师的这一做法体现的教学原则有（　）。', '[["A","因材施教原则，对不同水平学生采用不同指导方式"],["B","直观性原则，通过典型习作让学生获得具体可感的认识"],["C","启发性原则，组织学生讨论、互评，引导学生主动思考"],["D","巩固性原则，通过反复抄写范文巩固写作知识"],["E","理论联系实际原则，把评改标准用于真实作文的评析与修改"]]', '["B","C","E"]', 'B项应选：选取典型习作让学生在真实、具体的例子上感受优缺点，属于通过感性材料帮助理解，体现直观性原则。C项应选：组织讨论、互评，让学生自己发现“好在哪里、怎样改更好”，调动了学生的主动性，体现启发性原则。E项应选：师生共同梳理评改标准后，立即用于评析和修改真实作文，学以致用，体现理论联系实际原则。A项不选：题干中典型习作、互评、面批面向的是同一写作任务，主要不是根据个别差异调整教学要求。D项不选：材料中没有反复抄写范文的做法。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1252, 9, 82, 'multi', 1.6, '某地教育局组织新任校长培训，围绕学校日常管理中经常涉及的教育法律规范和教育法律关系进行研讨。下列参训人员的说法，正确的有（　）。', '[["A","教育法律规范由假定、处理和制裁三要素构成"],["B","教育法律关系的主体只包括学校和教师两类"],["C","教育法律关系是以教育法律规范为前提而形成的社会关系"],["D","学生可以作为教育法律关系的主体享有权利、承担义务"],["E","教育法律关系的客体包括物、行为和精神产品等"]]', '["A","C","D","E"]', 'A项正确：教育法律规范在逻辑结构上通常由假定（适用条件）、处理（行为模式）、制裁（法律后果）三部分构成。C项正确：教育法律关系是教育法律规范在调整人们有关教育活动的行为过程中形成的权利和义务关系。D项正确：学生是重要的教育法律关系主体。E项正确：教育法律关系客体主要包括物、行为以及精神产品等。B项错误：教育法律关系主体范围广泛，并非只有学校和教师两类。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1253, 9, 83, 'multi', 1.6, '教师在教学中运用有意注意的规律组织教学，正确的做法有（　）。', '[["A","尽量让课堂保持完全安静，禁止学生任何形式的讨论和走动"],["B","明确学习的目的任务，增强学生学习的自觉性"],["C","把教学目标主要定在追求热闹有趣上，以娱乐代替教学"],["D","合理组织教学活动，把智力活动与实际操作结合起来"],["E","培养学生的间接兴趣和坚强的意志品质"]]', '["B","D","E"]', '运用有意注意规律组织教学的要求包括：明确学习的目的和任务，提高学生的自觉性；合理组织教学活动，把智力活动与实际操作结合起来，防止单调疲劳；培养学生的间接兴趣和意志品质。A项错误：完全禁止讨论和走动既不现实也不科学。C项错误：只追求热闹有趣会削弱教学目的性。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1254, 9, 84, 'multi', 1.6, '某中学体育课上，学生小林在分组足球比赛中争顶头球时与同学发生合理身体碰撞后倒地，造成手臂骨折。事后家长要求学校赔偿。关于本次事故中各方责任的认定，下列表述正确的有（　）。', '[["A","若经查明学校提供的球门、场地存在安全隐患且与本次损害存在因果关系，学校应依法承担相应责任"],["B","只要伤害发生在校园内、上课期间，无论学校有无过错都必须承担全部赔偿责任"],["C","若学校在赛前进行了安全教育、检查了场地器材，事故后又及时救助、通知家长，可依法减轻或免除其责任"],["D","足球等对抗性体育活动本身具有一定人身风险，在学校无过错的情况下，对该固有风险造成的损害可依法不承担或减轻责任"],["E","事故发生后学校立即将小林送医并通知其家长，属于及时履行救助与告知义务的表现"]]', '["A","C","D","E"]', 'A正确：学校设施不符合安全标准并与损害有因果关系的，应承担相应责任。B错误：学校对学生伤害事故承担的是过错责任，并非只要在校受伤就一律全赔。C正确：学校尽到安全教育、管理和及时救助义务的，可以减轻或免除责任。D正确：对抗性体育活动中，学生自愿参加即应承担一定的固有风险。E正确：及时救助受伤害学生并及时告知监护人是学校的法定义务。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1255, 9, 85, 'multi', 1.6, '学习“功 = 力 × 距离”公式时，老师让学生回忆自己提水上楼和沿平地行走的体验，比较哪种情况下“累”与做功的关系，再归纳出做功的两个必要因素。学生由此对公式的理解明显加深。下列学习规律在该教学中得到体现的有（　）。', '[["A","正迁移：生活经验促进了对抽象公式的理解"],["B","负迁移：原有经验必然干扰科学概念的形成"],["C","教学必须完全脱离学生的日常经验，以防止错误概念"],["D","只要积累生活经验，无须教师引导就能自发形成科学概念"],["E","感性经验是理解抽象知识的基础"]]', '["A","E"]', 'A项应选：学生把提水上楼、平地行走的生活经验用于理解“做功”，已有经验对新学习起了积极促进作用，属于正迁移。E项应选：借助具体体验获得感性认识，再归纳出做功的必要因素，说明感性经验是理解抽象知识的基础。B项不选：原有经验并非必然起干扰作用。C项不选：教学恰恰要利用和改造学生的已有经验。D项不选：科学概念的形成离不开教师的引导和抽象概括。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1256, 9, 86, 'multi', 1.6, '考试临近，部分学生出现不同反应：有的越临近考试越能集中精力复习，效率反而提高；有的则出现失眠、食欲下降，一进考场就大脑空白。下列说法正确的有（　）。', '[["A","适度的焦虑和紧张有利于唤起注意、提高学习效率"],["B","焦虑水平越高，考试成绩一定越好"],["C","只要消除一切紧张情绪，就能保证考试正常发挥"],["D","过度考试焦虑会影响记忆提取和思维活动，需要进行调节"],["E","考试焦虑完全由考试难度决定，与个人认知评价无关"]]', '["A","D"]', 'A项正确：依据耶克斯—多德森定律，适度的动机和焦虑水平有利于唤起注意、集中精力，提高作业效率。D项正确：过度焦虑会引起生理唤醒过强、注意狭窄、记忆提取困难，需要通过认知调节、放松训练等加以疏导。B项错误：焦虑水平与成绩呈倒 U 型关系。C项错误：完全消除紧张既不可能也无必要。E项错误：考试焦虑与个人对考试的认知评价、归因方式密切相关。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1257, 9, 87, 'multi', 1.6, '某县几所小学在招生和管理中出现若干做法。依据《中华人民共和国义务教育法》，下列做法中属于违法、应当承担法律责任的有（　）。', '[["A","一所中心小学把重点初中升学率作为考核教师的唯一指标并对外公开排名"],["B","某小学拒绝接收本服务区内一名具有接受普通教育能力的残疾适龄儿童随班就读"],["C","某小学将校内运动场出租给商业机构开办周末收费培训班，影响学生体育课使用"],["D","某小学责令一名经常扰乱课堂秩序的学生停课转学，否则不予注册学籍"],["E","某小学对违反学校管理制度的学生给予批评教育，并通知家长配合加强教育"]]', '["A","B","C","D"]', '依据《义务教育法》：A项把升学率作为考核教师的唯一指标并公开排名，属片面追求升学率的应试导向做法，违法；B项拒绝接收具有接受普通教育能力的残疾适龄儿童随班就读，违法；C项将运动场出租给商业机构办收费培训班、影响体育课正常使用，属侵占、破坏学校教育教学设施，违法；D项责令学生停课转学、否则不予注册学籍，属于变相开除，违反《义务教育法》第二十七条，违法；E项对违纪学生给予批评教育并通知家长配合加强教育，是法律允许的正当教育管理措施，不承担法律责任，不选。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1258, 9, 88, 'multi', 1.6, '15岁的初中生小浩父母长期在外务工，跟随祖父母生活。他在校多次无故殴打同学、索要零花钱，学校和班主任的下列做法中，符合现行法律规定的有（　）。', '[["A","为防止其继续伤人，经校长决定长期将其单独关在器材室反省"],["B","对其进行批评教育和心理辅导，并及时联系其父母及受委托照护的祖父母"],["C","因小浩系留守儿童，学校对其欺凌行为一律不予过问，交由家庭自行处理"],["D","组织其与被欺凌学生的家长依法处理民事赔偿等事宜"],["E","对欺凌行为及时调查处置，必要时依法给予相应的教育惩戒或纪律处分"]]', '["B","D","E"]', '依据《未成年人保护法》《预防未成年人犯罪法》和《中小学教育惩戒规则（试行）》，学校对学生欺凌行为应当立即制止、调查认定，及时联系双方父母或其他监护人，依法予以教育、惩戒或处分，并做好心理辅导和民事赔偿协调工作。B项批评辅导并联系监护人、D项协调民事赔偿、E项调查处置并依法惩戒处分，均正确。A项长期单独关在器材室属于体罚、变相体罚甚至非法拘禁，违法。C项留守儿童不是学校免责理由。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1259, 9, 89, 'multi', 1.6, '某校在日常管理中的下列做法，符合《中华人民共和国未成年人保护法》关于学校保护要求的有（　）。', '[["A","为加强管理，对有违纪记录的学生统一在校园显著位置张榜公布其姓名和违纪事实"],["B","因学生家长未按要求参加家长会，暂停该生到校上课一周"],["C","建立学生欺凌防控工作制度，对教职员工、学生开展防治学生欺凌的教育和培训"],["D","建立安全管理制度，对未成年人进行安全教育，完善安保设施、配备安保人员"],["E","保障未成年学生受教育权，不得违反国家规定开除、变相开除未成年学生"]]', '["C","D","E"]', 'C项正确：学校应建立学生欺凌防控工作制度，开展教育培训。D项正确：学校应当建立安全管理制度，开展安全教育，完善安保设施、配备安保人员。E项正确：学校应尊重和保护未成年学生的受教育权，不得违反国家规定开除或者变相开除学生。A项张榜公布违纪学生姓名侵犯学生人格尊严和隐私。B项因家长未参加家长会而停学生的课，侵犯学生受教育权。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (1260, 9, 90, 'multi', 1.6, '李老师每次讲完一个单元后，都会用思维导图把本单元的核心概念及其关系画在黑板上，再让学生仿照绘制自己的知识结构图，考前还指导学生按知识网络进行回忆和查漏补缺。关于这一做法，下列说法正确的有（　）。', '[["A","绘制知识结构图属于学习策略中的组织策略"],["B","按知识网络回忆、查漏补缺属于元认知监控与调节的运用"],["C","该做法有助于知识的系统化，促进陈述性知识的保持与提取"],["D","组织策略只适用于文科知识的学习，不适用于理科"],["E","教师示范思维导图后，学生无须独立练习即可自动形成组织策略"]]', '["A","B","C"]', 'A项正确：组织策略是整合所学新知识之间、新旧知识之间的内在联系，形成新的知识结构的策略，归类、纲要、思维导图等是其典型方法。B项正确：学生按知识网络自我回忆、发现漏洞并及时补救，属于元认知策略的运用。C项正确：结构化、网络化的知识更有利于长时保持和需要时的检索提取。D项错误：组织策略在数理学科中同样广泛适用。E项错误：策略的掌握需要学生在教师示范基础上反复独立练习、反思和迁移。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2341, 52, 1, 'judge', 0.6, '某校清末以培养“忠君尊孔”之士为目标，今天以培养社会主义建设者和接班人为目标。这说明教育具有历史性。', '[["A","正确"],["B","错误"]]', '["A"]', '教育随社会历史发展而变化，不同历史时期教育的性质与目的各不相同，这正是教育社会属性中历史性的体现。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2342, 52, 2, 'judge', 0.6, '某校引进境外课程时全盘照搬，认为外来文化一律先进。这种做法忽视了教育对文化的选择与批判作用。', '[["A","正确"],["B","错误"]]', '["A"]', '教育对文化既有传递功能，也有选择和批判功能，引进外来文化应取其精华、去其糟粕。题干准确指出其忽视选择批判作用。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2343, 52, 3, 'judge', 0.6, '学生在“校园责任田”里劳作，同时做节气观察、写观察日记。这体现了劳动教育的综合育人价值。', '[["A","正确"],["B","错误"]]', '["A"]', '劳动教育与自然观察、语言表达相结合，学生在出力流汗中树德、增智、强体、育美，发挥了以劳树德、以劳增智的综合育人价值。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2344, 52, 4, 'judge', 0.6, '年过五旬的王老师认为快退休了，再学信息技术没有必要。这一看法符合终身教育理念。', '[["A","正确"],["B","错误"]]', '["B"]', '终身教育主张教育贯穿人的一生，任何年龄阶段都应继续学习。临近退休不等于学习终结，该看法违背终身教育理念。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2345, 52, 5, 'judge', 0.6, '李老师常把备课、批改作业带回家完成，周末还和家长沟通学生情况。这体现了教师劳动的长期性。', '[["A","正确"],["B","错误"]]', '["B"]', '工作延续到下班之后、家庭之中，体现的是教师劳动时间上的连续性和空间上的广延性；长期性指人才培养周期长、影响具有迟效性，题干未体现。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2346, 52, 6, 'judge', 0.6, '新课程方案下发后，陈老师结合本校器材条件调整了实验安排再上课。这属于课程实施的相互适应取向。', '[["A","正确"],["B","错误"]]', '["A"]', '课程实施有忠实、相互调适、创生三种取向。教师结合本校实际调整方案后再推行，正是计划与实际相互调适的相互适应取向。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2347, 52, 7, 'judge', 0.6, '新教师小周认为教学质量主要取决于课件是否精美，课堂组织好坏无足轻重。这一认识是正确的。', '[["A","正确"],["B","错误"]]', '["B"]', '教学工作包括备课、上课、作业布置与批改、课外辅导、学业成绩检查评定等环节，其中上课（课堂教学）是中心环节，课件只是辅助手段，本末倒置的认识不正确。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2348, 52, 8, 'judge', 0.6, '赵老师把一学期转化后进生的经历、反思和学生变化写成教育故事加以总结。这属于教育叙事研究。', '[["A","正确"],["B","错误"]]', '["A"]', '教育叙事研究是教师以叙事、讲故事的方式记述有意义的教育教学事件并加以反思的研究方法，与题干做法吻合。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2349, 52, 9, 'judge', 0.6, '心理学史课上讲，1903年桑代克出版《教育心理学》，这是世界上最早专门论述教育问题的著作。', '[["A","正确"],["B","错误"]]', '["B"]', '1903年桑代克《教育心理学》标志着教育心理学成为一门独立学科，但世界上最早专门论述教育教学问题的著作是中国的《学记》，题干把二者混为一谈。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2350, 52, 10, 'judge', 0.6, '十个月大的婴儿见玩具被毛巾盖住后不再寻找，只会盯着空处哭闹。这说明婴儿已获得客体永久性。', '[["A","正确"],["B","错误"]]', '["B"]', '客体永久性指儿童知道不在眼前的物体仍然存在，获得它的标志是主动寻找被藏起来的物体。婴儿不再寻找，说明客体永久性尚未真正建立。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2351, 52, 11, 'judge', 0.6, '白鼠走迷宫实验中，无奖组在第十天获得食物后成绩迅速追上受奖组。这说明没有强化就不会发生学习。', '[["A","正确"],["B","错误"]]', '["B"]', '该潜伏学习实验恰恰表明，无强化期间学习已经发生（动物形成了认知地图），只是潜伏着，获得强化后才表现出来，说明强化不是学习发生的必要条件。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2352, 52, 12, 'judge', 0.6, '小琳说参加物理竞赛不是为拿名次，而是想把没搞懂的力学问题真正弄明白。这是一种掌握目标定向。', '[["A","正确"],["B","错误"]]', '["A"]', '掌握目标（学习目标）定向者以掌握知识、提高能力为目的，成绩目标定向者以超过他人、获得名次为目的。小琳为弄懂知识而参赛，属于掌握目标定向。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2353, 52, 13, 'judge', 0.6, '高二学生学完有机化学后，回过头对高一学过的无机反应规律理解得更深了。这是一种逆向迁移。', '[["A","正确"],["B","错误"]]', '["A"]', '后继学习对先前学习产生影响称为逆向迁移。后学的有机化学加深了对先学无机化学的理解，方向上属于逆向迁移（且为逆向正迁移）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2354, 52, 14, 'judge', 0.6, '早读时小周发现课文开头结尾记得牢、中间最易忘，便认定中间内容不重要、不必再复习。这一推论正确。', '[["A","正确"],["B","错误"]]', '["B"]', '开头结尾记得牢属于系列位置效应，只说明中间部分受首因、近因效应影响更易遗忘，因而更应合理分配复习、及时巩固，不能推出内容不重要。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2355, 52, 15, 'judge', 0.6, '学生初学多位数除法要念出步骤，后来逐渐默念，最后能在头脑中不出声地完成。这属于原型内化。', '[["A","正确"],["B","错误"]]', '["A"]', '心智技能形成经历原型定向、原型操作、原型内化三阶段，出声的外部言语向内部言语转化、最终在头脑中简缩完成，正是原型内化阶段。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2356, 52, 16, 'judge', 0.6, '几何题卡住时，小吴不假思索就把同学的答案抄过来交差。这属于学业求助策略的合理运用。', '[["A","正确"],["B","错误"]]', '["B"]', '学业求助策略是经独立思考后仍无法解决时，主动请他人讲清思路、点拨方法，目的是学会学习；不经思考直接照抄答案属于依赖和抄袭，不是合理的学业求助。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2357, 52, 17, 'judge', 0.6, '讨论校本课程方案时，秦主任鼓励大家先多提设想、暂不互相评头论足。这符合头脑风暴法的要求。', '[["A","正确"],["B","错误"]]', '["A"]', '头脑风暴法遵循延迟评判、以量求质、自由畅想等原则，先大量提出设想、不急于批评否定，有利于产生创造性方案。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2358, 52, 18, 'judge', 0.6, '口吃学生被同学模仿而哭泣，周老师说“换作是我，也会很难受”，学生感到被理解。这种回应有助于疏导情绪。', '[["A","正确"],["B","错误"]]', '["A"]', '教师设身处地体验学生内心感受并把理解传达给学生，能让学生感到被接纳，有利于建立信任的辅导关系、疏导情绪，这是辅导中共情技术的作用。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2359, 52, 19, 'judge', 0.6, '《义务教育法》规定适龄儿童、少年“应当”入学并完成义务教育。该规定在类型上属于授权性规范。', '[["A","正确"],["B","错误"]]', '["B"]', '授权性规范是规定人们“可以”作出某种行为的规范；“应当”“必须”规定的是必须履行的行为，属于义务性规范。题干混淆两类规范。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2360, 52, 20, 'judge', 0.6, '县教育督导机构对学校督导后，可直接撤销其认为不称职的校长职务。这符合教育督导的权限规定。', '[["A","正确"],["B","错误"]]', '["B"]', '教育督导重在监督、检查、评估和指导，督导机构可提出奖惩建议，但无权直接撤销校长职务，校长任免应按干部管理权限由有关部门依法办理。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2361, 52, 21, 'judge', 0.6, '初一学生小林课间翻越护栏摔伤，学校已尽到教育管理和救助职责。家长坚持“在校受伤，学校就得赔”。', '[["A","正确"],["B","错误"]]', '["B"]', '八周岁以上未成年学生在校受伤适用过错责任原则，学校尽到教育、管理职责的不承担责任。小林违反规定自行翻越护栏致伤，不能仅以在校受伤为由要求赔偿。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2362, 52, 22, 'judge', 0.6, '13岁的小冯多次结伙殴打同学、抢夺财物。公安机关可直接决定将其送入专门学校矫治。', '[["A","正确"],["B","错误"]]', '["B"]', '对有严重不良行为的未成年人送专门学校接受专门矫治教育，须经专门教育指导委员会评估同意，由教育行政部门会同公安机关依法决定，公安机关不能单方直接决定。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2363, 52, 23, 'judge', 0.6, '春游时有人向学生兜售低俗书刊，带队白老师怕惹麻烦视而不见。这表明他履行了教师的法定义务。', '[["A","正确"],["B","错误"]]', '["B"]', '教师法规定教师有义务制止有害于学生的行为、批评和抵制有害于学生健康成长的现象。白老师视而不见，属于不履行法定义务。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2364, 52, 24, 'judge', 0.6, '对学校处分不服，家长既不申诉也不复议，却直接以学校为被告起诉，法院应直接受理。', '[["A","正确"],["B","错误"]]', '["B"]', '对学校等内部管理行为不服提起行政诉讼，法律、法规规定应先经行政审批、行政复议等前置程序的，须先履行前置程序，法院不直接受理。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2365, 52, 25, 'judge', 0.6, '两位科任老师因占自习课起争执，最终依据团结协作要求协商化解。这体现了教师职业道德的调节功能。', '[["A","正确"],["B","错误"]]', '["A"]', '教师职业道德通过规范要求调节教师之间、教师与集体之间的关系，引导教师以团结协作化解矛盾，这正是师德调节功能的体现。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2366, 52, 26, 'judge', 0.6, '支教教师杨老师所在村小条件艰苦，她仍认真备好每节课，还走山路逐一家访。这集中体现了爱岗敬业。', '[["A","正确"],["B","错误"]]', '["A"]', '忠诚于人民教育事业、勤恳敬业、甘为人梯、乐于奉献是爱岗敬业的要求，杨老师在艰苦条件下仍高度负责，集中体现了爱岗敬业。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2367, 52, 27, 'judge', 0.6, '班主任蒋老师在朋友圈点名嘲讽某家长“素质差”，且全班家长可见。这属私人表达，不违反职业行为准则。', '[["A","正确"],["B","错误"]]', '["B"]', '新时代教师职业行为十项准则要求教师坚持言行雅正、规范网络言行，不得损害学生和家长的名誉与合法权益。公开嘲讽家长已越过私人空间边界，违反准则。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2368, 52, 28, 'judge', 0.6, '独自印制期末试卷时，鲁老师面对密封试题自觉回避，不偷看、不泄露一题。这体现了师德修养中的慎独。', '[["A","正确"],["B","错误"]]', '["A"]', '慎独是指在无人监督、独处之时仍能坚守道德准则、严格自律。鲁老师在无人知晓的情况下自觉保守试题秘密，正是慎独的表现。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2369, 52, 29, 'judge', 0.6, '校长号召大家学习“心有大我、至诚报国”的理想信念，指出它是中国特有的教育家精神的首要内容。', '[["A","正确"],["B","错误"]]', '["A"]', '2023年教师节习近平总书记提出中国特有的教育家精神，第一条即“心有大我、至诚报国的理想信念”，题干表述准确。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2370, 52, 30, 'judge', 0.6, '2025年6月起，某民办园面试选拔幼儿、教拼音算术，这些做法均违法。', '[["A","正确"],["B","错误"]]', '["A"]', '《学前教育法》于2025年6月1日起施行，规定学前儿童入园不得组织任何形式的考试或者测试，幼儿园不得采用小学化的教育方式、不得教授小学阶段的课程，故面试选拔、教拼音算术均违法。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2371, 52, 31, 'single', 1.0, '一位教育史研究者梳理发现：孔子兴办私学、古希腊智者学派授徒，都与当时新兴阶层参与社会生活、需要读写辩论等能力密切相关。这一研究最适合用来说明（　）', '[["A","教育起源于动物界的生存本能"],["B","教育起源于生产劳动和社会生活的需要"],["C","教育起源于儿童对成人的无意识模仿"],["D","教育起源于神和上天的意志安排"]]', '["B"]', '教育与社会生产生活需要相联系，是劳动起源说（社会起源说）的观点；生物起源说把教育归于动物本能，心理起源说归于无意识模仿，神话起源说归于神的意志，均与题干不符。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2372, 52, 32, 'single', 1.0, '历史课讲到“清末废科举、兴学堂”，教师引导学生分析：新式学堂引进西学、培养了大批科技和实业人才，推动了民族工业发展；而旧学内容空疏、与社会需求脱节，逐渐被淘汰。这种“教育的内容与功能随社会变迁而调整”的现象，最直接地体现了（　）', '[["A","教育能够超越并决定社会发展方向"],["B","教育是独立于社会之外的自足系统"],["C","教育受社会发展制约并反作用于社会"],["D","教育的发展完全不受政治经济影响"]]', '["C"]', '社会变迁提出新的人才需求，促使教育内容调整，而新教育又培养人才推动社会发展，体现教育受社会制约并对社会有反作用。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2373, 52, 33, 'single', 1.0, '同卵双胞胎兄弟智商相近，哥哥随父母在城市长大，广泛参加科技馆和各类实践活动；弟弟在偏远山村由祖辈照看，少有些类机会。中学阶段两人在科学探究和表达自信上差异明显。这一对比主要说明（　）', '[["A","环境为个体发展提供了多种可能"],["B","遗传素质决定了人的发展水平"],["C","学校教育对人的发展不起作用"],["D","个体差异完全由基因决定"]]', '["A"]', '遗传相近而后天环境和活动机会不同导致发展差异，说明环境把发展的可能性变为现实、提供多种条件；遗传决定论和否定学校教育作用均错误。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2374, 52, 34, 'single', 1.0, '某校在制定育人目标时提出：“要让学生既掌握扎实学识，又涵养家国情怀、强健体魄和劳动习惯，成为能担当民族复兴大任的时代新人。”这一目标设计坚持的基本要求是（　）', '[["A","只重视智育，用分数衡量学生"],["B","以特长培养取代基本素养"],["C","统一规格、消除学生个性差异"],["D","德智体美劳全面发展"]]', '["D"]', '目标涵盖知识、品德、体魄、劳动等方面，指向德智体美劳全面发展的社会主义建设者和接班人。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2375, 52, 35, 'single', 1.0, '学校劳动周里，学生在木工房学习使用工具、按图样完成一件简易书架，并在校园“跳蚤市场”学习记账与交换。这一活动最直接承担的任务是（　）', '[["A","培养学生正确的劳动观点和基本劳动技能，养成劳动习惯"],["B","以系统文化科学知识武装学生、发展智力"],["C","增强学生体质、传授运动与卫生保健知识"],["D","提高学生感受美、鉴赏美和创造美的能力"]]', '["A"]', '动手使用工具、完成作品并参与劳动交换，最直接承担的是劳动技术教育的任务，即培养正确劳动观点、掌握基本劳动知识技能、养成劳动习惯。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2376, 52, 36, 'single', 1.0, '新入职的尤老师发现，面对课堂上的突发状况，老教师往往凭经验迅速判断、巧妙化解，而自己却常常手忙脚乱。这种在长期教育教学实践中积累的、难以从书本直接获得的经验与智慧，属于教师的（　）', '[["A","实践性知识"],["B","本体性知识"],["C","条件性知识"],["D","一般文化知识"]]', '["A"]', '教师在真实教育情境中积累的、应对具体问题的经验与智慧属于实践性知识；本体性知识是学科知识，条件性知识是教育学心理学知识。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2377, 52, 37, 'single', 1.0, '学校课程委员会讨论时形成两种意见：一方主张课程应由学科专家按严密的知识体系预先设定，学校和教师负责忠实执行；另一方则强调课程不是现成产品，而应在师生具体活动中不断生成和创造。后者的课程观属于（　）', '[["A","忠实取向"],["B","相互调适取向"],["C","创生取向"],["D","目标取向"]]', '["C"]', '课程创生取向把课程视为师生在具体情境中共同创造经验的过程，课程在实施中不断生成；忠实取向强调照搬预设方案，相互调适取向强调计划与实际相互调整。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2378, 52, 38, 'single', 1.0, '数学课上，华老师没有先讲结论，而是抛出问题：“周长相等的长方形和正方形，面积一定相等吗？”让学生用铁丝围一围、算一算，在争论中自己发现规律。从教学方法看，华老师主要运用了（　）', '[["A","讲授法"],["B","读书指导法"],["C","发现法"],["D","演示法"]]', '["C"]', '教师不直接呈现结论，而是创设问题情境，引导学生独立探究、自己发现知识，这是发现法（探究法）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2379, 52, 39, 'single', 1.0, '初一（3）班几个男生因打游戏发生口角，眼看要动手。班主任成老师没有简单各打五十大板，而是先让大家冷静，分别倾听各方想法，再一起约定处理同学矛盾的规则，引导大家学会换位思考。这一做法主要贯彻的德育原则是（　）', '[["A","知行统一原则"],["B","疏导原则"],["C","长善救失原则"],["D","严格要求原则"]]', '["B"]', '教师循循善诱、以理服人，通过倾听、沟通和引导把学生的思想行为引导到正确方向，体现疏导原则。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2380, 52, 40, 'single', 1.0, '接手纪律松散的班级后，祁老师先和学生共同制定班规、明确共同目标，又有意识地培养班干部和积极分子，组织了几次增强凝聚力的集体活动，班级很快形成了正确舆论和良好班风。这一过程主要反映了（　）', '[["A","学科课堂的常规管理"],["B","学校行政组织的建设"],["C","家庭教育指导的实施"],["D","班集体的形成与培养"]]', '["D"]', '确立共同目标、健全组织与核心队伍、建立正常秩序和正确舆论、开展活动，正是班集体形成与培养的基本环节。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2381, 52, 41, 'single', 1.0, '学校对学生的评价不再只看期末一张试卷，而是平时记录课堂表现、收集作业和项目作品、记录实践活动，期末结合多方表现用描述性语言反馈学生的进步。下列做法与这一评价理念相一致的是（　）', '[["A","建立学生成长档案，综合课堂表现、作业成果与实践记录等多方情况作发展性评价"],["B","依据期末一次考试成绩把学生排队分等"],["C","只按学生在班级中的相对名次确定优劣"],["D","主要凭教师日常印象给出等第"]]', '["A"]', '重视学习过程、采用成长记录等多元方式、以促进发展为目的的评价，属于发展性评价（过程性评价）；以甄别选拔为目的、只看相对名次的评价强调区分排名，凭印象打分的评价缺乏客观依据。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2382, 52, 42, 'single', 1.0, '林同学认为，心理学课本里讲的定律都来自精心设计的实验，而不是研究者的主观猜想。她还知道，教育心理学作为独立学科，与一部以教育心理学命名、后扩展为三卷本的著作直接相关。这部著作的作者是（　）', '[["A","乌申斯基"],["B","卡普捷列夫"],["C","桑代克"],["D","冯特"]]', '["C"]', '1903年桑代克出版《教育心理学》，后扩充为《人的本性》《学习心理》《个性差异与测量》三卷，标志教育心理学成为独立学科。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2383, 52, 43, 'single', 1.0, '幼儿安安把家里的白猫叫“喵喵”，第一次在公园看见白色的小狗，也喊“喵喵”；妈妈告诉她这是“汪汪”后，她慢慢能把猫和狗分开。从“凡白色小动物都叫喵喵”到“猫和狗是两回事”，这一认知变化中，后一步主要属于（　）', '[["A","图式"],["B","顺应"],["C","同化"],["D","平衡"]]', '["B"]', '改变原有认知结构、建立新概念以适应新信息的过程是顺应；把新事物直接纳入已有图式不改变结构是同化。安安经调整区分猫狗则是顺应。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2384, 52, 44, 'single', 1.0, '初二学生小钟遇到问题时，不再只凭眼前的具体事实，而能提出多种假设，像“如果改变这个条件，结果会怎样”，并系统地逐一验证，还能思考“思考本身”是否严密。这一思维特征最符合（　）', '[["A","感知运动阶段"],["B","前运算阶段"],["C","具体运算阶段"],["D","形式运算阶段"]]', '["D"]', '能进行假设一演绎推理、抽象逻辑思维和对思维的反省（元认知），是形式运算阶段的典型特征，初中生开始进入该阶段。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2385, 52, 45, 'single', 1.0, '小学生做数学题时，小蕾喜欢老师先把步骤讲清楚、按示范一步步做；同桌小杰则更愿意自己摸索，不受外界暗示影响，即使老师不给框架也能独立形成思路。这种在感知和思考时“是否依赖外部线索”的差异，反映的是（　）', '[["A","场依存型与场独立型"],["B","沉思型与冲动型"],["C","辐合型与发散型"],["D","外倾型与内倾型"]]', '["A"]', '以外部参照为信息加工依据、易受暗示是场依存型；以内部参照为主、独立判断是场独立型。题干区分的正是认知方式中的场依存与场独立。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2386, 52, 46, 'single', 1.0, '实验室里，狗在多次听到铃声后得到食物，逐渐一听到铃声就分泌唾液。研究者认为，铃声原本与唾液无关，是因为反复与食物配对才获得了引发反应的力量。这一现象所依据的学习理论是（　）', '[["A","操作性条件作用理论"],["B","经典条件作用理论"],["C","社会学习理论"],["D","认知—发现说"]]', '["B"]', '中性刺激（铃声）与无条件刺激（食物）反复结合而成为条件刺激、引起条件反应，是巴甫洛夫经典条件作用的核心。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2387, 52, 47, 'single', 1.0, '自习课上，每当学生主动安静下来，龚老师就投以赞许的目光；而对个别学生故意说笑逗乐、博人关注的行为，她既不批评也不回应，一段时间后这类行为反而消失了。龚老师对后一种行为所运用的原理是（　）', '[["A","及时给予愉快刺激，使良好行为增多"],["B","撤销厌恶刺激，使行为得到加强"],["C","对原本靠关注维持的行为不再给予任何强化，使其逐渐减弱"],["D","施加厌恶刺激，以压制不良行为"]]', '["C"]', '有机体做出某行为后不再伴随强化物，该行为发生概率逐渐下降，这是消退。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2388, 52, 48, 'single', 1.0, '老师让学生先把新知识与自己熟悉的内容挂钩：学英文单词“family”时联想“Father And Mother I Love You”，学历史年代时编口诀。这些给材料补充意义、建立联系以加深记忆的做法，属于（　）', '[["A","复述策略"],["B","组织策略"],["C","资源管理策略"],["D","精加工策略"]]', '["D"]', '通过记忆术、谐音联想、口诀等给学习材料增添信息、建立深层联系以促进理解记忆，属于精加工策略。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2389, 52, 49, 'single', 1.0, '考试失利后，小贾想：“这次没考好是因为题目太难、运气不好，再努力也没用。”此后他越来越不愿付出努力，甚至认为自己天生不是学习的料，面对简单任务也消极放弃。这种长期把失败归于不可控因素而形成的无力、放弃状态，称为（　）', '[["A","习得性无助"],["B","自我效能感"],["C","成就动机"],["D","认知内驱力"]]', '["A"]', '个体反复经历失败并把失败归因于能力等不可控因素，产生无论怎样努力都无法改变结果的信念，进而放弃努力，这是习得性无助。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2390, 52, 50, 'single', 1.0, '小林解数学题时总要把已知条件列成清单、一步步推导，擅长分析但缺乏灵感；同桌小王则能从多个角度大胆联想，常提出出人意料又合理的解法。心理学上常用来衡量后者这种思维品质的三个主要指标是（　）', '[["A","广阔性、深刻性、敏捷性"],["B","流畅性、变通性、独创性"],["C","自觉性、果断性、坚韧性"],["D","选择性、整体性、理解性"]]', '["B"]', '发散思维是创造性思维的核心，其主要特征为流畅性（数量多）、变通性（角度广）和独创性（新颖独特）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2391, 52, 51, 'single', 1.0, '面对“把蜡烛固定在墙上并让蜡油不滴到桌上”的任务，很多人只想到盒子是装图钉的容器，想不到它还能当烛台用。这种只看到事物的通常用途、看不到其他新用途而阻碍问题解决的现象是（　）', '[["A","原型启发"],["B","定势"],["C","功能固着"],["D","酝酿效应"]]', '["C"]', '把某种功能赋予某物体后难以看出它的其他功能，称为功能固着（邓克尔蜡烛实验）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2392, 52, 52, 'single', 1.0, '学英语初期，学生把英语字母“t”读成汉语拼音“t（特）”，干扰了英语发音；经过练习，后来又能用英语的拼读规则反过来帮助理解汉语拼音的系统性。前一种干扰和后一种促进，在迁移方向上依次属于（　）', '[["A","逆向负迁移与顺向正迁移"],["B","水平迁移与垂直迁移"],["C","一般迁移与具体迁移"],["D","顺向负迁移与逆向正迁移"]]', '["D"]', '先学的拼音干扰后学的英语，是先前学习对后继学习的消极影响，属顺向负迁移；后学的英语反过来促进对先学拼音的理解，是后继学习对先前学习的积极影响，属逆向正迁移。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2393, 52, 53, 'single', 1.0, '背诵一篇课文后，小唐发现：刚背完时开头几段印象很深，隔两天再回忆，结尾几段反而记得清楚，中间最模糊。教师解释这与记忆材料所处位置及前后干扰有关。下列对此分析正确的是（　）', '[["A","开头只受（或主要受）倒摄抑制，结尾只受（或主要受）前摄抑制"],["B","开头受倒摄抑制影响大，结尾受前摄抑制影响大"],["C","开头结尾都只受前摄抑制"],["D","开头结尾都只受倒摄抑制"]]', '["A"]', '开头内容前面没有材料，只受后面材料的倒摄抑制；结尾内容后面没有材料，只受前面材料的前提抑制；中间同时受两种抑制，故遗忘最多。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2394, 52, 54, 'single', 1.0, '小邵学骑自行车，最初需握紧车把、默念“看前方、保持平衡”，动作紧张且顾此失彼；反复练习后，动作逐渐连贯、轻松；最后能一边骑车一边留意路况、与人交谈。这种动作技能从依靠视觉控制、动作紧张到动觉控制增强、动作熟练自动化的发展，属于（　）', '[["A","操作定向阶段"],["B","操作熟练阶段"],["C","操作整合阶段"],["D","操作模仿阶段"]]', '["B"]', '操作熟练阶段动作高度协调、自动化，动觉控制增强、视觉注意范围扩大，能在骑车时兼顾路况和交谈；题干描述的终点状态符合熟练阶段特征。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2395, 52, 55, 'single', 1.0, '阅读时，小聂会根据材料难易调整速度，遇到难懂处主动放慢、回读，并在心里问自己“我真的懂了吗”；发现理解有偏差，就重新调整策略。这种对自身认知过程的计划、监视和调节，属于（　）', '[["A","认知策略"],["B","资源管理策略"],["C","元认知策略"],["D","精细加工策略"]]', '["C"]', '对认知的认知，包括计划、监控（自我提问、觉察理解程度）和调节（回读、调整策略），属于元认知策略。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2396, 52, 56, 'single', 1.0, '品德课上，学生对“海因茨该不该偷药救妻”展开讨论。有学生说“不能偷，偷药会被抓去坐牢，会受到惩罚”；有的说“可以偷，因为丈夫有责任救妻子，这样大家才会说他是好丈夫”。以“是否受惩罚”为取向的阶段，在科尔伯格理论中属于（　）', '[["A","前习俗水平-惩罚与服从定向"],["B","前习俗水平-相对功利定向"],["C","习俗水平-寻求认可定向"],["D","后习俗水平-普遍伦理定向"]]', '["A"]', '以行为是否受到惩罚来判断对错、为逃避惩罚而服从权威，是前习俗水平的惩罚与服从定向阶段；“好丈夫”评价对应寻求认可定向。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2397, 52, 57, 'single', 1.0, '学生小白一到重大考试就心慌、出汗、头脑空白，复习好的知识难以提取。心理老师建议：先教她放松肌肉，然后在想象中从“听到考试”到“走进考场”逐级接触焦虑情境，放松与焦虑不能并存，逐级减轻对考试的恐惧。这种方法是（　）', '[["A","强化法"],["B","理性情绪疗法"],["C","来访者中心疗法"],["D","系统脱敏法"]]', '["D"]', '建立焦虑等级，在放松状态下逐级接触引起焦虑的刺激，以放松抑制焦虑，是沃尔普系统脱敏法的典型程序。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2398, 52, 58, 'single', 1.0, '教师在心中对某些学生形成了“很有潜力”的期待，于是不知不觉中给他们更多提问、等待和鼓励的机会；这些学生也因此更自信、成绩提高，教师最初的期待似乎“应验”了。这一由教师期望引起学生相应发展的效应是（　）', '[["A","首因效应"],["B","罗森塔尔效应"],["C","晕轮效应"],["D","刻板印象"]]', '["B"]', '教师的期望或明或暗地传递给学生，学生会按教师期望的方向塑造自己的行为，这是教师期望效应，即罗森塔尔效应（皮格马利翁效应）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2399, 52, 59, 'single', 1.0, '教幼儿数概念时，岳老师发现直接讲抽象数字孩子难以理解，便先让孩子数积木、分水果，借助这些实物和动作帮助儿童获得数概念。她这样做，主要是考虑到这一阶段儿童的思维具有（　）', '[["A","具体形象性"],["B","抽象逻辑性"],["C","假设演绎性"],["D","系统反思性"]]', '["A"]', '幼儿期儿童处于前运算阶段，思维以具体形象为主，需借助具体事物和表象进行思考，故教师采用直观操作帮助其建立数概念。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2400, 52, 60, 'single', 1.0, '面对一道复杂应用题，学生能回忆起公式却不知何时用、如何分步；另一些学生则能迅速识别题型、调用相应解法。加涅把学生在学习中习得的、用于支配自身学习、记忆和思维的内部组织起来的技能（如学习和思考的方法）称为（　）', '[["A","言语信息"],["B","智慧技能"],["C","认知策略"],["D","动作技能"]]', '["C"]', '加涅学习结果分类中，认知策略是调节和支配自身注意、学习、记忆和思维的内部过程的技能；言语信息是陈述观念，智慧技能是运用符号对外办事。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2401, 52, 61, 'single', 1.0, '维果斯基认为，儿童独立解决问题所达到的水平，与在成人或更有能力的同伴帮助下所能达到的水平之间存在差距，教学应着眼于这一差距、走在发展前面。这个“差距”被称为（　）', '[["A","关键期"],["B","认知发展阶段"],["C","图式"],["D","最近发展区"]]', '["D"]', '维果斯基把儿童现有发展水平与潜在发展水平（在指导下所能达到的水平）之间的区域称为最近发展区，主张教学创造最近发展区、走在发展前面。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2402, 52, 62, 'single', 1.0, '小组合作中，教师不直接给答案，而是先提供问题支架和示范，随着学生能力增强逐步撤除帮助，让学生独立完成。这种“根据学生水平给予适当支持、再逐渐放手”的教学方式，其直接理论依据是（　）', '[["A","程序教学"],["B","支架式教学"],["C","非指导性教学"],["D","掌握学习"]]', '["B"]', '在最近发展区内提供支架、帮助学生完成独立时不能完成的任务，再随能力提高逐步撤去支架，这是基于维果斯基理论的支架式教学。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2403, 52, 63, 'single', 1.0, '学生小王说：“我努力学习，既因为对知识本身好奇，也希望认为我操劳的父母高兴，还想在班级中证明自己的能力。”奥苏贝尔把学生课堂学习中“想获得知识、解决问题”的那种需要（指向学习任务本身的内驱力）称为（　）', '[["A","认知内驱力"],["B","自我提高内驱力"],["C","附属内驱力"],["D","外部动机"]]', '["A"]', '奥苏贝尔将学校情境中的成就动机分为认知内驱力（求知、指向学习任务本身）、自我提高内驱力（赢得地位与威望）和附属内驱力（获得他人赞许）。题干所问指向任务本身的是认知内驱力。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2404, 52, 64, 'single', 1.0, '课后，一个学生总被同学嘲笑“爱打小报告”，其实他只是如实反映影响集体的问题，内心很委屈。班主任引导他换个角度看：在不同情境中，坚持原则和注意沟通方式可以兼顾。这种引导学生站在他人立场、理解他人想法和感受的能力培养，属于（　）', '[["A","自我中心"],["B","道德实在论"],["C","观点采择"],["D","泛灵化"]]', '["C"]', '观点采择（角色采择）是指采取他人的观点来理解他人思想与情感的能力，是克服自我中心、促进道德和社会性发展的重要能力。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2405, 52, 65, 'single', 1.0, '某小学门口文具店向学生兜售“三无”辣条和仿真刀具，家长举报后，市场监管和公安等专门机关依据国家有关规定分别予以查处，经营者受到相应追究。与依靠舆论、信念维持的道德和学校内部规定相比，这类规范最本质的特征是（　）', '[["A","依靠社会舆论和教师内心信念来维系"],["B","由国家制定或认可、以国家强制力保证实施"],["C","只约束学校内部成员"],["D","仅靠人们自觉遵守"]]', '["B"]', '由国家制定或认可、以国家强制力保证实施、规范教育领域行为的规范属于教育法律规范，相关部门依法查处体现其国家强制性。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2406, 52, 66, 'single', 1.0, '某校与一家企业签订校企合作协议，企业出资建设实验室，学校按约定培养技能人才。协议中明确双方权利义务，双方地位平等、协商一致。这种学校在民事活动中与企业形成的、地位平等的法律关系，属于（　）', '[["A","教育行政法律关系"],["B","教育民事法律关系"],["C","教育刑事法律关系"],["D","教育宪法关系"]]', '["B"]', '平等主体之间基于自愿、等价有偿形成的财产关系和人身关系由民法调整，属于教育民事法律关系；行政法律关系中双方地位不平等。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2407, 52, 67, 'single', 1.0, '家长会上，有家长提出让正在读初二、成绩不好的孩子辍学去打工挣钱。班主任明确告知：送适龄子女入学是父母的法定义务，辍学打工违法。这一义务直接规定在（　）', '[["A","《中华人民共和国义务教育法》"],["B","《中华人民共和国教师法》"],["C","《中华人民共和国学位条例》"],["D","《中华人民共和国职业教育法》"]]', '["A"]', '《义务教育法》规定，适龄儿童、少年的父母或其他法定监护人应当依法保证其按时入学接受并完成义务教育。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2408, 52, 68, 'single', 1.0, '某区新建居民小区入住人口激增，区教育局根据片区适龄儿童数量和学校布局，划定各小学招生服务范围，户籍在片区内的适龄儿童均可就近登记入学，学校不得另行组织选拔考试。这一制度直接保障了适龄儿童的（　）', '[["A","人格尊严权"],["B","人身自由权"],["C","免试就近入学的权利"],["D","获得公正评价的权利"]]', '["C"]', '按户籍和居住地划片、就近登记入学且不组织选拔考试，直接保障的是适龄儿童、少年免试就近入学的权利。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2409, 52, 69, 'single', 1.0, '某民办小学在招生时要求家长提供学生的血型、家庭收入及父母婚姻状况等与入学无关的信息，并在家长群公开。学校的这一做法主要侵犯了学生及家庭的（　）', '[["A","受教育权"],["B","生命健康权"],["C","肖像权"],["D","隐私权和个人信息权益"]]', '["D"]', '收集与入学无关的个人信息并予以公开，违反未成年人保护法关于保护未成年人隐私和个人信息的规定，侵犯隐私权和个人信息权益。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2410, 52, 70, 'single', 1.0, '体育课上，教师反复强调投掷区安全规则后组织铅球练习。学生小赵趁教师指导他人时擅自闯入投掷区，被同学投出的铅球砸伤。事后查明器材合格、教师已尽安全教育和现场管理职责，并及时送医。对小赵的损害，依法应（　）', '[["A","由学校承担全部赔偿责任"],["B","由小赵及其监护人自行承担相应责任，学校无过错不担责"],["C","由任课教师个人承担全部责任"],["D","由投掷学生承担全部责任"]]', '["B"]', '限制民事行为能力人在校受伤适用过错责任，学校已尽教育、管理职责且及时救助，不承担责任；小赵违反安全规则擅自进入投掷区有过错，损害由其一方自行承担。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2411, 52, 71, 'single', 1.0, '教师古老师在教育教学中可以开展课程改革实验、对学校工作提出建议，并在学术团体中从事研究、交流。这些权利在教师法上被概括为（　）', '[["A","教育教学权与科学研究权"],["B","管理学生权与获取报酬权"],["C","民主管理权与进修培训权"],["D","指导评价权与申诉权"]]', '["A"]', '进行教育教学活动、开展教学改革实验是教育教学权；从事科学研究、学术交流、参加专业学术团体是科学研究权（学术自由权），与题干对应。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2412, 52, 72, 'single', 1.0, '学生小吕多次扰乱课堂、辱骂同学。班主任按规定让其在教室内站立反省一节课，并要求其课后写反思、向同学道歉。该措施没有超过正常教育限度，属于（　）', '[["A","体罚"],["B","变相体罚"],["C","一般教育惩戒"],["D","行政处罚"]]', '["C"]', '根据《中小学教育惩戒规则（试行）》，点名批评、责令站立、课后教导等属于学校、教师可当场实施的一般教育惩戒；一节课课堂教学时间内的教室内站立是明确允许的方式，不是体罚。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2413, 52, 73, 'single', 1.0, '某校为整顿考风，对一名被认定考试作弊的学生当场宣布“勒令退学”，不给学生陈述和申辩机会，也未履行校内审核程序。该处理在程序上主要违反了（　）', '[["A","诚实信用原则"],["B","等价有偿原则"],["C","罪刑法定原则"],["D","正当程序原则"]]', '["D"]', '对学生作出不利处分，应履行告知、听取陈述申辩、按规定审核等程序，保障其救济权利，这是正当程序原则的要求；当场勒令退学且不给申辩机会程序违法。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2414, 52, 74, 'single', 1.0, '教师尤老师因对学校年度考核中“基本合格”的等次有异议，认为认定所依据的考勤记录有误，拟通过法定专门途径向主管教育行政部门请求重新处理。他应采取的救济途径是（　）', '[["A","民事诉讼"],["B","教师申诉"],["C","刑事自诉"],["D","行政仲裁"]]', '["B"]', '教师对学校或其他教育机构侵犯其合法权益，或对其作出的处理不服，可以向教育行政部门提出申诉，这是教师法规定的教师申诉制度。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2415, 52, 75, 'single', 1.0, '教龄三十年的向老师深受学生爱戴：她从不按成绩把学生分三六九等，尤其关心家庭困难和学习暂时落后的学生，严慈相济，平等公正对待每一个人。这集中体现的师德规范是（　）', '[["A","关爱学生"],["B","爱国守法"],["C","终身学习"],["D","廉洁从教"]]', '["A"]', '关心爱护全体学生、尊重学生人格、平等公正对待学生、严慈相济、维护学生权益，是“关爱学生”的核心要求，与题干高度契合。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2416, 52, 76, 'single', 1.0, '某培训机构高薪聘请在职教师蓝老师利用周末到机构讲授教材同步课，并以其名义招生宣传。按新时代教师职业行为十项准则，这种行为（　）', '[["A","属于教师正常的兼职自由"],["B","只要教学质量好就可以接受"],["C","违反规范从教行为、不得有偿补课的要求"],["D","只要不影响周一上课即允许"]]', '["C"]', '十项准则要求教师规范从教行为，自觉抵制有偿补课，不得组织、推荐或参与校外培训机构及他人组织的有偿补课，不论是否影响本职工作均在禁止之列。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2417, 52, 77, 'single', 1.0, '备课时，符老师不愿照搬往年的旧教案，坚持每节课后写反思札记，还主动参加教研和培训，把学到的新方法带回课堂反复打磨。她常说：“教师不能只守着一桶水，得让自己成为常换常新的活水。”这体现的师德规范是（　）', '[["A","为人师表"],["B","终身学习"],["C","团结协作"],["D","依法执教"]]', '["B"]', '崇尚科学精神、树立终身学习理念、不断更新知识、潜心钻研业务，是“终身学习”的要求；反思、培训、更新知识结构正体现这一点。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2418, 52, 78, 'single', 1.0, '学校在教师考核中实行师德“一票否决”：凡出现严重违反教师职业行为准则情形的，年度考核直接定为不合格，评优评先、职称晋升一票否决。这一做法强调（　）', '[["A","教学成绩是教师评价的唯一标准"],["B","科研能力比师德更重要"],["C","教师考核只需看师德一项"],["D","师德是教师评价的第一标准和首要内容"]]', '["D"]', '师德师风是评价教师队伍素质的第一标准，师德考核不合格者年度考核定为不合格，并在教师资格注册、评优评先、职务晋升中一票否决，体现师德首要地位。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2419, 52, 79, 'single', 1.0, '2025年秋季开学，某公办幼儿园在招生中组织家长带孩子参加“识字闯关”和算术口试，按成绩择优录取；园内大班还统一安排拼音书写和20以内加减法作业。家长质疑时，园方称“为孩子上小学打基础”。依据2025年6月1日起施行的《中华人民共和国学前教育法》，下列判断正确的是（　）', '[["A","组织“识字闯关”择优录取是保证生源质量的合理做法"],["B","大班教授拼音和加减法，有利于幼小衔接、法律予以鼓励"],["C","该法对幼儿园教育方式只作倡导，没有强制性规定"],["D","入园不得组织考试或测试，幼儿园也不得教授小学阶段课程，园方做法违法"]]', '["D"]', '《学前教育法》明确规定，学前儿童入园不得组织任何形式的考试或者测试；幼儿园不得采用小学化的教育方式，不得教授小学阶段的课程，小学坚持按课程标准零起点教学。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2420, 52, 80, 'single', 1.0, '教师使用智能工具批改作文时，可借助其快速找出共性问题、生成初步评语，但对学生的最终评价结论，仍由教师结合平时观察作出，特别是在价值观引导、情感培养等环节坚持教师主导。这符合《教师生成式人工智能应用指引（第一版）》倡导的（　）', '[["A","技术替代、效率至上"],["B","一切评价结论都由人工智能直接给出"],["C","人工智能仅作辅助、教师发挥育人主导作用"],["D","禁止教师使用任何智能工具"]]', '["C"]', '该《指引》引导教师愿用、会用、善用AI，明确AI仅作辅助工具，在价值观引导等关键育人环节教师必须主导，不得将AI对作文等的自动批改结果直接作为最终评价。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2421, 52, 81, 'multi', 1.6, '成都某小学与本地蜀绣工坊合作，把非遗传承人请进课堂，师生共同整理老绣样、改编成适合儿童学习的纹样课程，还通过校园开放日向社区和结对学校展示。从教育与文化的关系看，这一做法体现了教育对文化的（　）', '[["A","传承和保存优秀传统文化"],["B","选择、整理并提升文化"],["C","传播、交流并促进文化融合"],["D","直接决定社会的政治经济制度走向"],["E","从根本上消除不同文化之间的差异与冲突"]]', '["A","B","C"]', '把蜀绣引入课堂并整理老绣样，体现对优秀传统文化的传承保存与选择整理（A、B）；向社区和结对学校展示，促进文化的传播交流与融合（C）。教育影响但不能“直接决定”政治经济制度，D夸大了教育的社会作用；教育促进文化理解但不可能从根本上消除文化差异和冲突，E表述绝对化。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2422, 52, 82, 'multi', 1.6, '区教研活动中，数学组王老师上《函数的概念》公开课。下列王老师课堂上的做法，值得肯定的有（　）', '[["A","先给出“打车费用随里程变化”的现象，让学生先猜想再抽象概括"],["B","为基础薄弱的学生提供带分步提示的分层任务卡"],["C","概念归纳后立即让学生用新概念解释一个新的生活现象"],["D","把回答错误的学生罚站一整节课以示警醒"],["E","学生思路卡壳时耐心等待并连续追问，直到学生自己说出关键一步"]]', '["A","B","C","E"]', '由生活现象引导学生猜想概括，调动独立思考（A）；分层任务卡照顾不同水平学生（B）；学完即用新概念解决新问题，利于理解与巩固（C）；等待并追问促使学生自己突破，尊重学生认识过程（E）。罚站一整节课属于变相体罚，既伤害学生又违背依法执教要求，D错误。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2423, 52, 83, 'multi', 1.6, '某小学课程表中既有语文、数学等国家课程，也有学校自编的《川剧赏析》校本课程，还安排了研学旅行、劳动与技术等综合实践活动。关于这些课程类型，下列说法正确的有（　）', '[["A","国家课程体现国家对学生发展的统一基本要求"],["B","校本课程由学校自主开发，可充分利用本地特色资源"],["C","综合实践活动是国家规定的必修课程"],["D","学校可用自编的校本课程随意替代国家课程"],["E","地方课程和校本课程都是可开可不开的随意性课程"]]', '["A","B","C"]', '国家课程体现国家统一的基本质量要求（A）；校本课程由学校结合实际自主开发，可利用地方特色资源（B）；综合实践活动是国家规定、地方指导、学校实施的必修课程（C）。校本课程是对国家课程的补充而不能替代国家课程，D错误；地方课程和校本课程的实施同样具有规范性，并非学校可随意取舍，E错误。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2424, 52, 84, 'multi', 1.6, '小林因羡慕同桌的新钢笔而偷偷拿回家，班主任李老师没有当众揭穿，私下了解到他想练好字却不敢开口借，便先肯定他上进的愿望，再严肃指出错处，指导他主动归还，并约定连续一周自己检查书桌物品。李老师的做法主要贯彻了（　）', '[["A","尊重信任学生与严格要求相结合"],["B","循循善诱、以理服人的疏导原则"],["C","针对学生特点进行教育的因材施教原则"],["D","以公开点名和惩罚为主的教育原则"],["E","借班会公开其行为以警示全班的集体教育原则"]]', '["A","B","C"]', '不当众揭穿、肯定其上进愿望，体现尊重信任；严肃指出错处、要求归还和自查，体现严格要求（A）。讲清错处、引导其主动改正，属于疏导（B）。针对小林想练字又羞怯的具体情况个别处理，体现因材施教（C）。公开点名惩罚为主既不符合疏导也伤害人格，D错误；材料采用的是个别保密教育，班会公开其行为既无依据也会伤害学生，E错误。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2425, 52, 85, 'multi', 1.6, '学校拟开设机器人、版画、球类等一批课外兴趣小组，面向全体学生自愿报名。下列组织方式中，符合课外校外教育基本要求的有（　）', '[["A","学生根据兴趣自主选报，教师只做引导，尊重学生的主体地位"],["B","活动兼顾知识性、趣味性与实践性，让学生动手又动脑"],["C","纳入学校整体计划、专人负责，保证时间、场地和安全落实"],["D","为提高竞赛成绩，只允许相关学科成绩前 10% 的学生报名"],["E","活动内容完全照搬课堂教材，按统一进度讲授和考试"]]', '["A","B","C"]', '课外校外教育具有自愿性、自主性、灵活性、实践性和广泛性等特点：应尊重学生兴趣与自主选择，发挥学生主体作用（A）；内容生动活泼、形式多样，兼顾知识性、趣味性与实践性（B）；并纳入学校教育计划、加强组织管理与安全保障（C）。以成绩设门槛违背自愿性与全员性（D错）；照搬课堂、统一讲授考试，丧失课外活动灵活自主的特点（E错）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2426, 52, 86, 'multi', 1.6, '某校研讨“五育并举”时，老师们对德智体美劳之间的关系发表了看法。下列说法正确的有（　）', '[["A","五育各有相对独立性，又相互联系、相互促进"],["B","德育为其他各育保持正确方向提供保证"],["C","体育为学生的全面发展提供唯一的物质基础"],["D","五育并举就是把时间和精力在五育间平均分配"],["E","智育抓好了，其余各育就会自然而然地发展"]]', '["A","B"]', '五育各有特定任务又相互依存、相互促进（A）；德育对各自起方向和动力保证作用（B）。“体育为学生的全面发展提供唯一的物质基础”表述绝对化，体育主要是增强体质、促进健康，物质基础的形成还与营养、睡眠、环境等多种因素有关，不能说体育是“唯一”的物质基础，C错误。五育并举强调协调发展而非时间精力上的平均分配，D错误；各育不能相互替代，E错误。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2427, 52, 87, 'multi', 1.6, '期末复习时，同宿舍同学交流各自的记忆方法。下列做法中，属于精加工策略的有（　）', '[["A","用“山巅一寺一壶酒”的谐音来记圆周率"],["B","反复大声朗读单词表，连读十遍"],["C","读完每段后自问“这一段是为了证明什么”"],["D","用自己的话把课文内容讲给同桌听"],["E","把教材中零散概念按层级整理成概念图"]]', '["A","C","D"]', '谐音记忆属于记忆术（A），阅读中自我提问（C）、用自己的话复述讲解属于生成性学习（D），三者都是把新信息与已有知识建立深层联系的精加工策略。单纯反复朗读属于复述策略（B错）；按层级整理概念、画思维导图属于组织策略（E错）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2428, 52, 88, 'multi', 1.6, '体育课跳高练习中，八年级学生小周落地姿势不当导致小腿骨折。事发后，学校下列做法中符合法定要求的有（　）', '[["A","立即停止练习，由校医做初步固定并迅速送医院救治"],["B","第一时间通知小周的家长（监护人）"],["C","按规定时限和程序向主管教育行政部门报告"],["D","为尽快息事宁人，当场要求家长签署学校“概不负责”协议"],["E","保护现场，保存器材检查记录和监控视频，配合调查"]]', '["A","B","C","E"]', '发生伤害事故后，学校应当及时救助受伤害学生（A）、及时告知未成年学生的监护人（B）、按规定及时向主管教育行政部门报告（C），并注意保存证据、配合调查处理（E）。在责任未经依法认定前，以“概不负责”协议推诿、胁迫家长了结，既不符合及时救助与依法处理的要求，也不能免除学校依法应承担的责任，D错误。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2429, 52, 89, 'multi', 1.6, '针对学生课堂违纪，下列教师的处理方式中，符合《中小学教育惩戒规则（试行）》规定的有（　）', '[["A","对故意起哄扰乱课堂的学生点名批评，令其站立清醒后即坐下"],["B","要求未完成作业的学生把课文逐字抄写五十遍"],["C","课后对打架学生进行批评教育，责令其向被打同学赔礼道歉"],["D","当着全班同学扇学生耳光，以做效尤"],["E","班主任自行决定责令违纪学生停课一周、回家反省"]]', '["A","C"]', '点名批评，以及一节课堂教学时间内的教室内站立，属于规则允许的一般惩戒（A）；课后教导、责令赔礼道歉属于合法的教育惩戒措施（C）。超量重复抄写属于变相体罚（B错）；扇耳光是体罚，为法律明确禁止（D错）；停课、停学属于须经法定程序由学校决定的较重或严重惩戒，班主任个人无权自行责令停课一周（E错）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2430, 52, 90, 'multi', 1.6, '班主任黎老师发现班里部分学生偏科明显：数理成绩突出的学生轻视体育美和劳动，几名学科后进生则因常被忽视而渐渐厌学。黎老师据此调整带班思路。下列做法中，体现“教书育人”要求的有（　）', '[["A","不以分数作为评价学生的唯一标准，为偏科学生设置学科均衡进步的小目标"],["B","尊重学生差异，在班级活动中让学科后进生也能展示体艺、组织等方面的长处"],["C","利用班会开展生涯启蒙，引导学生把个人兴趣与社会责任、全面发展结合起来"],["D","对数理尖子生减免其全部体育美和值日劳动，以便集中精力冲刺竞赛"],["E","把每次月考排名张贴在教室墙面上，用名次压力倒逼偏科学生补差"]]', '["A","B","C"]', '“教书育人”要求教师遵循教育规律、实施素质教育，不以分数作为评价学生的唯一标准，注重学生全面发展（A）；尊重学生差异、因材施教，为不同学生创造发展空间，正是育人的体现（B）；面向全体学生、开展生涯与社会责任引导，促进学生全面而有个性地发展（C）。为冲竞赛减免体育美与劳动，违背全面发展（D错）；按考试成绩公开排名、唯分数论，与素质教育和不以分数为唯一标准的要求相悖（E错）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2431, 53, 1, 'judge', 0.6, '虞老师讲遗传变异时，穿插袁隆平一生扎根稻田的事迹，学生既学知识又受触动。这体现了教学的教育性规律。', '[["A","正确"],["B","错误"]]', '["A"]', '传授遗传变异知识的同时进行价值观引导，把教书与育人统一起来，正体现赫尔巴特“教育性教学”思想和教学过程中掌握知识与提高思想相统一的规律。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2432, 53, 2, 'judge', 0.6, '教研讨论时，卫老师引用杜威的话说“教育不是为未来生活做准备，教育本身就是生活”。', '[["A","正确"],["B","错误"]]', '["A"]', '“教育即生活”“学校即社会”是杜威实用主义教育思想的核心命题，强调教育与当下生活的内在统一。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2433, 53, 3, 'judge', 0.6, '卓老师要求刚升入初中的学生直接按成人标准制定备考计划，认为这样能“一步到位”。这遵循了身心发展规律。', '[["A","正确"],["B","错误"]]', '["B"]', '不同年龄阶段有不同的身心发展特征，教育必须从学生实际出发、分阶段提出要求。让初一学生套用成人标准，违背了个体身心发展的阶段性规律。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2434, 53, 4, 'judge', 0.6, '童老师抓住儿童口语发展敏感期加强听说训练，认为“当其可之谓时”，错过则勤苦而难成。', '[["A","正确"],["B","错误"]]', '["A"]', '口语敏感期是某方面机能发展最快、最适宜的时期，在此时施加相应教育事半功倍，体现了个体身心发展不平衡性规律所要求的抓关键期。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2435, 53, 5, 'judge', 0.6, '应老师把高中议论文写作任务直接布置给四年级学生，认为“高标准才有高产出”。这符合量力性原则。', '[["A","正确"],["B","错误"]]', '["B"]', '量力性原则要求教学难度适合学生的发展水平，是学生经过努力能够达到的。高中议论文远超四年级学生接受能力，属于拔苗助长，违背量力性原则。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2436, 53, 6, 'judge', 0.6, '学校组织学生到劳动实践基地采茶，边劳动边学习茶叶分级和外贸常识。这体现了教育与生产劳动相结合。', '[["A","正确"],["B","错误"]]', '["A"]', '学生在真实的生产劳动中获得直接经验并学习相关知识，把教育同生产劳动和社会实践结合起来，是我国教育目的和全面发展教育的要求。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2437, 53, 7, 'judge', 0.6, '物理课上，学生分组连接电路验证欧姆定律。这属于教师通过实验引导学生获得知识的实验法。', '[["A","正确"],["B","错误"]]', '["A"]', '学生在教师指导下利用一定仪器设备，通过控制条件、动手操作引起事物变化并观察验证规律，属于实验法。它强调学生亲自动手操作、探究验证，区别于教师示范、学生观察的演示法。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2438, 53, 8, 'judge', 0.6, '苏老师设节气展板、课间放古琴曲，学生耳濡目染变得沉静有礼。这靠环境熏陶而非讲道理。', '[["A","正确"],["B","错误"]]', '["A"]', '创设富有教育意义的情境，使学生在潜移默化中受到熏陶感染，属于情感陶冶；它与教师直接摆事实、讲道理的说服教育路径不同。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2439, 53, 9, 'judge', 0.6, '小学美术课上，老师让学生用树叶自由拼贴并互评。这有助于学生摆脱功能固着。', '[["A","正确"],["B","错误"]]', '["A"]', '功能固着是指个体在解决问题时往往只看到事物的惯常用途，而难以发现它的其他新用途。用树叶进行自由拼贴创作，能引导学生跳出树叶"只是植物叶片、会腐烂掉落"的常规功能认知，发现其形状、色彩、纹理等可用于艺术表达的新功能，有助于打破思维定势、摆脱功能固着。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2440, 53, 10, 'judge', 0.6, '宫老师独自拟定班级公约，写好后直接张贴要求执行，认为“学生只管遵守即可”。', '[["A","正确"],["B","错误"]]', '["B"]', '班级公约和班级活动应发动学生共同参与设计、讨论和制定，以发挥学生的主体性。班主任一手包办违背了班级活动的民主性与学生主体原则。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2441, 53, 11, 'judge', 0.6, '新教师请教带班秘诀，校长只说一句：“教，上所施，下所效也。”这句话强调了教师劳动的示范性。', '[["A","正确"],["B","错误"]]', '["A"]', '“教，上所施，下所效也”意为上位者怎么做，下位者就跟着仿效，说明学生具有向师性，教师的言行本身就是教育手段，体现教师劳动的示范性。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2442, 53, 12, 'judge', 0.6, '学校用成长记录袋留存学生平时作品，但学期评优仍只看一次统考分数。这符合发展性评价理念。', '[["A","正确"],["B","错误"]]', '["B"]', '成长记录袋属于关注过程与进步的过程性评价，而评优只认一次统考分数仍是甄别选拔式的终结性评价，二者割裂，违背发展性评价重过程、重发展的理念。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2443, 53, 13, 'judge', 0.6, '三年级学生能借助学具理解长度守恒，却难以离开具体事物进行纯假设演绎推理。', '[["A","正确"],["B","错误"]]', '["A"]', '三年级学生多处于皮亚杰所说的具体运算阶段，思维具有守恒性、可逆性，但仍需具体事物支持，抽象的假设一演绎推理要到形式运算阶段才成熟。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2444, 53, 14, 'judge', 0.6, '幼儿园的禾禾把掉在地上的布偶捡起来哄，说“它摔疼了，想妈妈了”。这是泛灵论的表现。', '[["A","正确"],["B","错误"]]', '["A"]', '前运算阶段儿童认为无生命的物体也和人一样有生命、有情感、有意图，这种“万物有灵”的思维即泛灵论。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2445, 53, 15, 'judge', 0.6, '“授人以鱼不如授人以渔”，说明教学应注重方法传授。这体现了形式训练说的迁移主张。', '[["A","正确"],["B","错误"]]', '["B"]', '该古语强调教给学生学习方法、发展其自主学习能力；而形式训练说主张通过训练记忆、推理等心理官能实现迁移，二者并非同一主张。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2446, 53, 16, 'judge', 0.6, '小部练二胡半年，中间有三周越练越没进步，调整动作后又明显提高。这种停滞属于练习高原现象。', '[["A","正确"],["B","错误"]]', '["A"]', '操作技能练习到一定阶段常出现成绩暂时停滞甚至下降的“平台期”，即高原现象；改进方法后可继续进步。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2447, 53, 17, 'judge', 0.6, '杭杭能把蛙泳动作要领背得一字不差，下水却不会游。他掌握的主要是程序性知识。', '[["A","正确"],["B","错误"]]', '["B"]', '能背诵“是什么”的动作要领属于陈述性知识；会实际操作、知道“怎么做”的游泳技能才是程序性知识。该生恰恰缺乏程序性知识。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2448, 53, 18, 'judge', 0.6, '甘恬恬把复习任务按重要紧急排序，固定每晚七点到九点专项攻坚。这属于资源管理策略。', '[["A","正确"],["B","错误"]]', '["A"]', '合理安排学习时间、建立时间表、设置学习优先级，属于学习策略中资源管理策略下的时间管理策略。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2449, 53, 19, 'judge', 0.6, '宓淼逢人就说垃圾分类很重要，自己却从不分类。这说明其态度的认知成分与行为成分出现脱节。', '[["A","正确"],["B","错误"]]', '["A"]', '态度由认知、情感和行为倾向三种成分构成。口头认同属于认知层面，实际不分类反映行为倾向缺失，二者不一致即知行脱节。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2450, 53, 20, 'judge', 0.6, '晚自习同学讨论得很热烈，澹台磊却能不受干扰，按自己的计划专注复习。这属于自我促成的纪律。', '[["A","正确"],["B","错误"]]', '["A"]', '当外部规则内化为学生自觉的行为准则，能自我约束、自我管理时形成的纪律即自我促成的纪律，是课堂纪律发展的最高水平。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2451, 53, 21, 'judge', 0.6, '既然教师期望能影响学生发展，那么学生最终成为什么样的人完全取决于教师的期望。', '[["A","正确"],["B","错误"]]', '["B"]', '罗森塔尔效应表明教师的积极期望对学生有重要促进作用，但学生发展还受遗传、环境、个人努力等多因素影响，“完全取决于”夸大了期望的作用。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2452, 53, 22, 'judge', 0.6, '屠远近一个月持续情绪低落、失眠、对任何事都提不起兴趣，班主任认为只是“青春期闹情绪”，未予关注。', '[["A","正确"],["B","错误"]]', '["B"]', '持续两周以上的情绪低落、兴趣减退、睡眠障碍是心理问题的重要预警信号，教师不能简单归为青春期情绪，应及时关注并转介专业辅导。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2453, 53, 23, 'judge', 0.6, '《教师法》规定教师“应当制止”侵犯学生合法权益的行为，该条文属于义务性规范。', '[["A","正确"],["B","错误"]]', '["A"]', '“应当”“必须”等表述要求主体做出一定行为，属于义务性规范；“不得”“禁止”为禁止性规范，“可以”为授权性规范。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2454, 53, 24, 'judge', 0.6, '某培训机构宣称可自行组织“国家学历认定考试”，成绩合格者颁发国家承认的文凭。', '[["A","正确"],["B","错误"]]', '["B"]', '国家教育考试由国家批准的教育考试机构依法承办，学历文凭的颁发有严格的法定主体和程序，培训机构无权自行组织国家学历考试并颁发国家承认文凭。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2455, 53, 25, 'judge', 0.6, '学生因被老师当众训斥后自伤，学校主张“老师发现后已制止，学校无需承担任何责任”。', '[["A","正确"],["B","错误"]]', '["B"]', '教师当众训斥本身存在教育管理不当、侵害学生人格尊严的过错，与学生自伤存在关联。学校不能仅以事后制止为由一概免责，应根据其过错承担相应责任。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2456, 53, 26, 'judge', 0.6, '中学生桑渺多次夜不归宿并参与赌博，学校发现后认为“管不了”，便不再过问。', '[["A","正确"],["B","错误"]]', '["B"]', '夜不归宿、参与赌博属于未成年人不良行为，学校负有及时制止、加强管教并与监护人联系的法定职责，放任不管构成失职。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2457, 53, 27, 'judge', 0.6, '丰老师对同事说：“只要我班考试成绩高，师德好坏无所谓。”', '[["A","正确"],["B","错误"]]', '["B"]', '师德是教师考核的首要内容，实行师德失范“一票否决”，教学成绩不能替代师德要求，该观点错误。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2458, 53, 28, 'judge', 0.6, '看到邻班两名学生在走廊推搡，瞿老师以“不是我班学生”为由绕道离开。', '[["A","正确"],["B","错误"]]', '["B"]', '教育学生是全体教师的共同职责，教师应相互尊重、团结协作、全员育人。对学生危险行为视而不见，违背团结协作和关爱学生的要求。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2459, 53, 29, 'judge', 0.6, '某小学规定只要家长同意，可给一、二年级学生布置抄写类书面家庭作业，以巩固当日所学。', '[["A","正确"],["B","错误"]]', '["B"]', '按“双减”和义务教育作业管理要求，小学一、二年级不布置家庭书面作业，学校应建立作业总量调控和质量审核制度，家长同意也不能突破规定。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2460, 53, 30, 'judge', 0.6, '学校在职称评审中设置师德红线，凡查实师德失范者当年一律不得申报。', '[["A","正确"],["B","错误"]]', '["A"]', '现行政策明确把师德作为教师评价的第一标准，在职称评聘、评优奖励中实行师德失范“一票否决”，学校做法于规有据。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2461, 53, 31, 'single', 1.0, '新教师培训中，主讲人把一本书称为“科学教育学的奠基之作”，说作者首次明确主张教育学应以心理学为基础、以伦理学为目的。这本书是（　）', '[["A","赫尔巴特《普通教育学》"],["B","杜威《民主主义与教育》"],["C","夸美纽斯《大教学论》"],["D","昆体良《雄辩术原理》"]]', '["A"]', '赫尔巴特《普通教育学》被公认为第一本现代教育学著作、科学教育学的奠基之作，并率先把心理学和伦理学作为教育学的理论基础。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2462, 53, 32, 'single', 1.0, '备课组长介绍班级授课制的由来，说最早系统论述这种集体教学制度、并提出“把一切知识教给一切人”泛智思想的教育家是（　）', '[["A","洛克"],["B","卢梭"],["C","夸美纽斯"],["D","裴斯泰洛齐"]]', '["C"]', '夸美纽斯在《大教学论》中系统论述了班级授课制，并提出泛智教育思想，主张把一切知识教给一切人。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2463, 53, 33, 'single', 1.0, '语文教研时，欧阳老师引用“道而弗牵，强而弗抑，开而弗达”来说明课堂提问应引而不发。这句教育名言出自（　）', '[["A","《论语》"],["B","《孟子》"],["C","《师说》"],["D","《学记》"]]', '["D"]', '“道而弗牵，强而弗抑，开而弗达”出自《学记》，强调启发诱导而不包办代替，是世界上最早的教育专著中的启发性思想。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2464, 53, 34, 'single', 1.0, '某县把川剧变脸、蜀绣等本土非遗编进校本课程，请老艺人进校园授课，使濒于失传的技艺在青少年中重新焕发生机。这最能说明教育具有（　）', '[["A","保存劳动力的经济功能"],["B","传递和活化文化的功能"],["C","决定政治方向的功能"],["D","控制人口数量的功能"]]', '["B"]', '教育通过筛选、传递和创新使文化得以延续和活化，非遗进校园正体现教育对文化的传承与活化功能。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2465, 53, 35, 'single', 1.0, '学校运动会专门设立“两人三足”“集体跳长绳”等全班必须参加的项目，保证体育薄弱、平时很少上场的学生也能代表班级参赛。这体现素质教育（　）', '[["A","以培养创新精神为唯一重点"],["B","只关注有特长的学生"],["C","把考试成绩放在首位"],["D","面向全体学生"]]', '["D"]', '设置人人参与的集体项目，让体育薄弱的学生也不被落下，体现素质教育面向全体学生、不是面向少数尖子生。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2466, 53, 36, 'single', 1.0, '工作三年的闻老师坚持每节课后写教学札记，记录课堂得失并在教研组分享改进。这种促进教师专业发展的主要途径是（　）', '[["A","学历进修"],["B","外出支教"],["C","岗位调动"],["D","教学反思"]]', '["D"]', '教师对自己教学实践进行回顾、审视并寻找改进对策的活动属于教学反思，是教师专业发展最直接、最有效的途径之一。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2467, 53, 37, 'single', 1.0, '区教研室下发的《义务教育科学课程标准》中，规定了学生经过学习应达成的科学探究要求。按古德莱德的课程层次理论，这属于（　）', '[["A","领悟的课程"],["B","经验的课程"],["C","正式的课程"],["D","运作的课程"]]', '["C"]', '由教育行政部门规定、列入正式文件的课程计划、课程标准和教材属于“正式的课程”；教师头脑中理解的是领悟的课程，课堂上实际实施的是运作的课程，学生实际体验到的是经验的课程。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2468, 53, 38, 'single', 1.0, '盖老师设计研学课程时不预设统一的行为化目标，而强调在过程中依据“程序原则”不断调整，与学生共同探究。这种课程开发取向更接近（　）', '[["A","泰勒的目标模式"],["B","斯腾豪斯的过程模式"],["C","夸美纽斯的班级授课模式"],["D","施瓦布的实践模式"]]', '["B"]', '斯腾豪斯反对把预设行为目标作为课程开发的唯一依据，主张课程是在教育过程中通过教师研究不断展开的过程模式。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2469, 53, 39, 'single', 1.0, '数学老师把“鸡兔同笼”分成画圈、列表、假设三步，控制难度，保证多数中等生“跳一跳、够得着”。这主要体现（　）', '[["A","巩固性原则"],["B","因材施教原则"],["C","量力性原则"],["D","直观性原则"]]', '["C"]', '量力性原则（可接受性原则）要求教学的难度、分量适合学生身心发展水平，是学生经过努力可以掌握的。分层递进、让学生“跳一跳够得着”正是量力性的典型表述。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2470, 53, 40, 'single', 1.0, '学完百分数后，荀老师让学生回家计算超市折扣和银行利率，再回课堂交流自己的算法。这一做法主要体现（　）', '[["A","循序渐进原则"],["B","直观性原则"],["C","启发性原则"],["D","理论联系实际原则"]]', '["D"]', '把书本上的百分数知识运用于折扣、利率等真实生活情境，以实际问题巩固和深化理论，体现理论联系实际原则。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2471, 53, 41, 'single', 1.0, '物理课上，简老师先规范演示马德堡半球实验，再让学生观察现象、解释原理。这种以教师展示直观教具或实验为主的教学方法是（　）', '[["A","演示法"],["B","练习法"],["C","读书指导法"],["D","讨论法"]]', '["A"]', '教师通过展示实物、教具或进行示范性实验，引导学生观察获得知识的方法是演示法。练习法重在学生反复操作，读书指导法重在阅读，讨论法重在学生间研讨。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2472, 53, 42, 'single', 1.0, '班级设立“进步星”“助人星”，每周民主评议并在成长册上记录，学期末据此公开表彰。这主要运用的德育方法是（　）', '[["A","实际锻炼法"],["B","品德评价法"],["C","情感陶冶法"],["D","说服教育法"]]', '["B"]', '通过表扬、奖励、评比、操行评定等方式对学生品德给予肯定或否定评价，以促其进步的方法是品德评价法。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2473, 53, 43, 'single', 1.0, '德育处挑选校园“文明之星”拍成微视频，组织学生观看并讨论、模仿其待人接物的行为。这体现的德育模式是（　）', '[["A","体谅模式"],["B","价值澄清模式"],["C","认知发展模式"],["D","社会模仿模式"]]', '["D"]', '班杜拉社会学习理论认为，儿童通过观察模仿榜样习得态度和行为。树立“文明之星”作榜样让学生观察模仿，正是社会模仿模式。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2474, 53, 44, 'single', 1.0, '攻读教育心理学的桑老师要确定学位论文的核心研究范畴。下列选题最契合本学科研究对象的是（　）', '[["A","白鼠按压杠杆的条件反射机制"],["B","计算机下棋的信息加工过程"],["C","学校情境中学与教的基本心理规律"],["D","精神障碍患者的异常心理"]]', '["C"]', '教育心理学是研究学校教育情境中学与教相互作用的基本心理规律的科学，学生、教师、教学内容、教学媒体和教学环境是其五大要素。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2475, 53, 45, 'single', 1.0, '做数学应用题时，凌澜总要依赖题目给出的现成条件，一旦条件不足、需要联系生活常识补充，她就无从下手；同桌则习惯从已有经验出发自主拓展。据此判断，凌澜更可能属于（　）', '[["A","冲动型"],["B","场依存型"],["C","沉思型"],["D","辐合型"]]', '["B"]', '场依存型的人较多依赖外部线索和现成信息，受环境影响大；场独立型则更多依赖内在参照、独立判断。波澜依赖题目现成条件、不善自主补充，是场依存型表现，与反应快慢的冲动/沉思型不同。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2476, 53, 46, 'single', 1.0, '迷笼里的小猫经过多次“乱按按钮—偶然得到食物”，逐渐学会一进笼就准确按下机关取食。支持该实验结论的学习理论是（　）', '[["A","苛勒的顿悟说"],["B","布鲁纳的认知发现说"],["C","奥苏贝尔的接受学习说"],["D","桑代克的试误说"]]', '["D"]', '桑代克通过饿猫开迷笼实验提出学习是刺激与反应之间经反复尝试错误而形成联结的过程，即试误说，并总结出准备律、练习律、效果律。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2477, 53, 47, 'single', 1.0, '针对转学后沉默寡言、害怕发言的余笙，班主任营造安全接纳的氛围，相信她具有自我成长的潜能，尽量减少外部强迫与单纯奖惩。这一做法主要吸收了（　）', '[["A","人本主义学习理论"],["B","行为主义学习理论"],["C","经典条件作用理论"],["D","认知结构学习理论"]]', '["A"]', '罗杰斯的人本主义强调以学生为中心，尊重学生、无条件积极关注，相信人有自我实现的潜能，主张建立良好师生关系促进学习。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2478, 53, 48, 'single', 1.0, '学生谷峻解出难题后最得意的是“我又弄懂了一种新方法”，而不只是分数超过了别人。他的成就目标更倾向于（　）', '[["A","害怕在别人面前暴露自己无能"],["B","以超过同伴、显示聪明为目标"],["C","以提高能力、真正掌握知识为目标"],["D","只为获得家长许诺的物质奖励"]]', '["C"]', '以掌握知识、提高能力为取向的属于掌握目标（学习目标）定向，关注“我有没有学会”；以超过他人、证明聪明或回避显笨为取向的是成绩目标。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2479, 53, 49, 'single', 1.0, '实验中，学生在估计100平方厘米面积上接受训练后，估计相近面积的成绩明显提高，而估计形状、大小迥异的面积时帮助很小。这一结果支持的迁移理论是（　）', '[["A","形式训练说"],["B","共同要素说"],["C","关系转换说"],["D","认知结构迁移理论"]]', '["B"]', '桑代克的共同要素说认为，只有当两种情况存在相同要素（共同成分）时才发生迁移，共同成分越多迁移越大。面积估计在相似任务上迁移明显、相异任务上很小，正支持共同要素说。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2480, 53, 50, 'single', 1.0, '学生能把课堂上反复演练的防震疏散流程近乎自动地用到突发地震演习中，但面对一种新型消防情境时却不能灵活改造原有做法。前者所体现的迁移类型主要是（　）', '[["A","高通路迁移"],["B","逆向迁移"],["C","负迁移"],["D","低通路迁移"]]', '["D"]', '低通路迁移指经过大量练习的技能在相似情境中近乎自动、不需太多意识参与的迁移；高通路迁移则需要有意识地抽象概括并灵活迁移到新情境。熟练流程自动用于相似演习属低通路迁移。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2481, 53, 51, 'single', 1.0, '劳老师在教学目标中写明“学生能够区分论点与论据，并对同伴观点提出有依据的质疑”。按加涅的学习结果分类，这一目标主要属于（　）', '[["A","智慧技能"],["B","言语信息"],["C","动作技能"],["D","态度"]]', '["A"]', '加涅把学习结果分为言语信息、智慧技能、认知策略、动作技能和态度。运用概念、规则对外办事，进行辨别、分析、论证的能力属于智慧技能；陈述事实是言语信息，熟练动作是动作技能，好恶倾向是态度。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2482, 53, 52, 'single', 1.0, '复习时，莘晓先列出整章框架，再给易混概念编口诀，遇到难题先做标记后回看，还把手机锁进柜子里减少干扰。这一整套做法统称为（　）', '[["A","复述策略"],["B","精加工策略"],["C","学习策略"],["D","资源管理策略"]]', '["C"]', '学习策略是学习者为提高学习效率而采用的所有规则、方法、技巧及其调控的总和，包括认知策略、元认知策略和资源管理策略。题干中的列框架、编口诀、做标记、管理干扰分属不同子类，总称应为学习策略。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2483, 53, 53, 'single', 1.0, '在“用蜡烛、火柴、一盒图钉把蜡烛固定在墙上照明"的实验中，多数被试想不到装图钉的纸盒还能当作烛台使用。造成这一困难的主要心理原因是（　）', '[["A","缺少相似原型的启发"],["B","已有经验在此产生了负迁移"],["C","当时过度紧张、动机过强"],["D","只看到纸盒的惯常用途，想不到它的新用途"]]', '["D"]', '邓克尔蜡烛实验表明，个体把某种功能赋予某物体后，难以看出它的其他用途，这就是功能固着。被试只把纸盒看作容器，想不到它可作烛台，正是功能固着的典型表现。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2484, 53, 54, 'single', 1.0, '刚上一年级的步凡每天盼着上学，主要是因为“老师会夸我、好好表现爸妈就给我买文具”。他此时占优势的内驱力是（　）', '[["A","附属内驱力"],["B","自我提高内驱力"],["C","认知内驱力"],["D","生理内驱力"]]', '["A"]', '奥苏贝尔把学校情境中的成就动机分为认知内驱力、自我提高内驱力和附属内驱力。为获得教师、家长等长者的赞许和接纳而努力，是附属内驱力，在儿童早期最为突出。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2485, 53, 55, 'single', 1.0, '起初对垃圾分类不以为然的学生，参加志愿宣讲后开始认同其意义，最终坚持自觉分类、还提醒家人。这一态度变化的顺序对应（　）', '[["A","认同—依从—内化"],["B","内化—依从—认同"],["C","依从—认同—内化"],["D","依从—内化—认同"]]', '["C"]', '态度与品德学习一般经历依从、认同、内化三个阶段：先表面顺从，再因认同榜样或观点而主动接受，最后将外在要求内化为稳定的价值观念并自觉践行。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2486, 53, 56, 'single', 1.0, '心理教师为克服一名学生怕狗的反应，先让他远远看狗的图片，再听狗叫声、看笼中幼犬，最后在陪伴下抚摸温顺的狗，逐步消除恐惧。这种方法是（　）', '[["A","合理情绪疗法"],["B","系统脱敏法"],["C","强化法"],["D","来访者中心疗法"]]', '["B"]', '系统脱敏法由沃尔普创立，按焦虑等级让来访者在放松状态下逐级接触恐惧刺激，使恐惧反应逐渐消退。由图片、声音到实物逐级暴露正是系统脱敏。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2487, 53, 57, 'single', 1.0, '英语教研组用“记忆—理解—运用—分析—评价—创造”六个层次的动词设计单元目标。这一目标分类的提出者是（　）', '[["A","布卢姆"],["B","加涅"],["C","奥苏贝尔"],["D","布鲁纳"]]', '["A"]', '布卢姆等人将认知领域目标由低到高分为知识（记忆）、领会（理解）、运用、分析、综合、评价，修订版改为记忆、理解、运用、分析、评价、创造。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2488, 53, 58, 'single', 1.0, '班规《自习公约》经全班讨论通过后，即使老师不在教室，多数同学也能自觉保持安静、独立完成作业。这一纪律类型主要属于（　）', '[["A","教师促成的纪律"],["B","集体促成的纪律"],["C","任务促成的纪律"],["D","自我促成的纪律"]]', '["D"]', '当外部纪律要求被个体内化，能自觉约束自己时形成自我促成的纪律，是纪律发展的最高水平。公约虽由集体讨论产生，但题眼在“老师不在也能自觉”，强调个体自律。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2489, 53, 59, 'single', 1.0, '学生上课反复发出怪声，班主任起初每次都当众制止，怪声反而更频繁；后来班主任不再理会，只在其安静时及时表扬，怪声逐渐消失。后半段做法运用了（　）', '[["A","消退与正强化"],["B","惩罚"],["C","经典条件反射的消退"],["D","负强化"]]', '["A"]', '撤销原先对不良行为的关注这种强化物，使行为减少，是消退；在学生表现出安静等良好行为时给予表扬以增加该行为，是正强化。二者结合改善了课堂行为。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2490, 53, 60, 'single', 1.0, '舒老师相信“只要方法对、肯下功夫，班里每个学生都能学好”，因此即使学生反复出错，她仍坚持耐心辅导。这种稳定信念属于（　）', '[["A","教师的教学效能感"],["B","罗森塔尔效应"],["C","教师的职业倦怠"],["D","习得性无助"]]', '["A"]', '教师对自己能否成功完成教学、促进学生发展的主观判断和信念称为教学效能感，它影响教师的坚持性和投入。罗森塔尔效应是教师期望对学生产生的实际影响，侧重学生变化。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2491, 53, 61, 'single', 1.0, '临考一周，蔚迟珊总担心考不好，出现心慌、出汗、看不进书，老师教她腹式呼吸、合理定位并做积极自我暗示。这属于（　）', '[["A","考试焦虑的调节"],["B","学习策略训练"],["C","道德情感培养"],["D","创造性思维训练"]]', '["A"]', '考前过度担忧、伴有生理唤起和注意涣散属于考试焦虑。通过放松训练、调整期望、积极自我暗示等方法缓解，正是考试焦虑的调节。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2492, 53, 62, 'single', 1.0, '多次努力仍考砸后，郎戈认为“再学也没用”，遇到简单题也不愿尝试，成绩越来越差。这种心理状态是（　）', '[["A","自我效能感提高"],["B","习得性无助"],["C","高原现象"],["D","认知失调"]]', '["B"]', '个体在反复经历无法控制的失败后，形成无论怎样努力都无法改变结果的消极期待，进而放弃尝试，称为习得性无助。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2493, 53, 63, 'single', 1.0, '《义务教育法》中关于“凡年满六周岁的儿童……应当入学接受并完成义务教育”的规定，以“应当”为行为模式。该规范属于（　）', '[["A","授权性规范"],["B","任意性规范"],["C","义务性规范"],["D","准用性规范"]]', '["C"]', '“应当”“必须”要求主体作出一定行为，属于义务性规范；“可以”“有权”是授权性规范，“不得”“禁止”是禁止性规范。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2494, 53, 64, 'single', 1.0, '某外来务工人员到政务大厅申请设立一所面向随迁子女的民办小学。负责审批的机关首先应审查其是否具备法定的办学条件，其中不包括（　）', '[["A","组织机构和章程"],["B","合格的教师"],["C","符合标准的教学场所及设施"],["D","举办者本人须具有本地户籍"]]', '["D"]', '设立学校及其他教育机构应具备组织机构和章程、合格教师、符合规定标准的教学场所设施设备、必备办学资金和稳定经费来源，法律并未要求举办者必须具有本地户籍，且该要求与平等保护相抵触。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2495, 53, 65, 'single', 1.0, '应届毕业生乐瑶已通过教师资格考试和面试，向有关部门申请认定教师资格。按照《教师法》，被撤销教师资格的，自撤销之日起一定期限内不得重新申请，该期限是（　）', '[["A","3年"],["B","5年"],["C","终身不得"],["D","1年"]]', '["B"]', '依照《教师资格条例》，被撤销教师资格的，自撤销之日起5年内不得重新申请认定教师资格；受到剥夺政治权利或故意犯罪受到有期徒刑以上刑事处罚的，不能取得教师资格。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2496, 53, 66, 'single', 1.0, '学生上课用手机玩游戏，班主任将其手机没收后带回自己家中长期使用，学期末仍以“替你保管”为由拒不归还。对该行为评价正确的是（　）', '[["A","教师依规可暂管影响教学的物品，但应妥善保管并及时归还或交监护人"],["B","没收不还、据为己用，侵犯了学生的财产权"],["C","学生物品一旦带入学校即归学校所有"],["D","为严格管理，教师可将没收物品自行使用或丢弃"]]', '["B"]', '学生的合法财产受法律保护。教师对影响课堂教学的物品可依规暂时收管，但应妥善保管，课后及时归还或交监护人；拒不归还甚至自行使用，构成对学生财产权的侵犯。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2497, 53, 67, 'single', 1.0, '高中生自发组织篮球友谊赛，比赛中一名同学在正常对抗中与他人相撞受伤。学校已按规定开放场地、进行了安全教育，对此次伤害（　）', '[["A","一律承担全部赔偿责任"],["B","应承担无过错的补充责任"],["C","在无过错的情况下不承担侵权责任"],["D","由参赛学生平均分担学校的责任"]]', '["C"]', '《民法典》规定，自愿参加具有一定风险的文体活动，因其他参加者的行为受到损害的，受害人不得请求其他参加者承担侵权责任，但故意或重大过失除外。学校尽到教育管理职责、无过错的，不承担责任，即自甘风险规则。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2498, 53, 68, 'single', 1.0, '校外人员翻墙进入校园将学生打伤，经查学校门卫脱岗、监控损坏多日未修。对学生的损害，应由（　）', '[["A","侵权人承担责任，学校不承担任何责任"],["B","学校承担全部责任，侵权人免责"],["C","侵权人承担侵权责任，学校承担相应的补充责任"],["D","学生自行承担"]]', '["C"]', '《民法典》规定，无民事行为能力人或限制民事行为能力人在学校受到第三人人身损害的，由第三人承担侵权责任；学校未尽到管理职责的，承担相应的补充责任，事后可向第三人追偿。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2499, 53, 69, 'single', 1.0, '13岁的初中生骆某多次结伙欺凌同学、强行索要财物，属于有严重不良行为的未成年人，其父母或监护人、所在学校均无力管教。依据《预防未成年人犯罪法》，对其可以采取的专门教育矫治措施是（　）', '[["A","由学校直接予以开除，取消其学籍"],["B","经专门教育指导委员会评估同意后，送入专门学校接受专门教育"],["C","由公安机关决定长期羁押于看守所"],["D","责令家长写保证书后即可不作任何干预"]]', '["B"]', '对有严重不良行为、父母或监护人及学校无力管教或管教无效的未成年人，经专门教育指导委员会评估同意，教育行政部门会同公安机关可以决定将其送入专门学校接受专门教育（专门矫治教育）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2500, 53, 70, 'single', 1.0, '教师对县教育局作出的处理决定不服，于收到决定书后第50天才申请行政复议。按照一般规定，行政复议的法定申请期限是知道具体行政行为之日起（　）', '[["A","60日内"],["B","30日内"],["C","6个月内"],["D","15日内"]]', '["A"]', '《行政复议法》规定，公民、法人申请行政复议的一般期限为知道具体行政行为之日起60日内（法律另有规定超过60日的除外）。6个月是行政诉讼起诉期限，注意区分。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2501, 53, 71, 'single', 1.0, '某高校查实一名毕业生的学位论文存在严重代写、抄袭，属于学位申请中的严重舞弊。根据2025年1月1日起施行的《中华人民共和国学位法》，学校可依法（　）', '[["A","撤销已授予的学位"],["B","只能口头批评"],["C","由公安机关处以刑罚"],["D","无权处理，须由教育部直接撤销"]]', '["A"]', '《学位法》规定，学位申请人在学位授予过程中有严重舞弊、作伪证等行为的，学位授予单位可以不授予或撤销学位；已经获得学位的，依法撤销并宣告学位证书无效。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2502, 53, 72, 'single', 1.0, '连续暴雨导致偏远教学点屋顶漏水，危老师冒雨转移学生后，又利用周末和工友一起检修、搬运物资，确保周一正常复课。这集中体现了教师职业道德规范中的（　）', '[["A","爱岗敬业"],["B","终身学习"],["C","廉洁从教"],["D","尊重家长"]]', '["A"]', '爱岗敬业要求教师忠诚于人民教育事业，勤恳敬业、乐于奉献、对工作高度负责。危老师为保障学生安全和正常教学冒雨转移、利用周末抢修，是爱岗敬业的集中体现。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2503, 53, 73, 'single', 1.0, '有家长以“孩子自己不愿学”为由，要求正在义务教育阶段的孩子辍学帮忙照看生意。班主任明确反对并协助劝学复学。班主任维护的是（　）', '[["A","教师的专业自主"],["B","学生的受教育权"],["C","学校的财产权"],["D","家长的教育选择权"]]', '["B"]', '义务教育是国家统一实施、所有适龄儿童少年必须接受的教育，具有强制性。让接受义务教育的学生辍学侵犯其受教育权，教师劝学、督促复学是依法履职、爱国守法的体现。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2504, 53, 74, 'single', 1.0, '放学前突发地震警报，和老师没有先去抢救自己放在讲台的贵重物品，而是按预案组织学生抱头避险、有序撤离，最后一个离开教室。这直接体现了十项准则中的（　）', '[["A","加强安全防范"],["B","坚持廉洁自律"],["C","传播优秀文化"],["D","秉持公平诚信"]]', '["A"]', '《新时代中小学教师职业行为十项准则》要求教师加强安全防范，增强安全意识，加强安全教育，保护学生免受事故伤害。危急时刻优先组织学生避险撤离，正体现加强安全防范。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2505, 53, 75, 'single', 1.0, '学校年度考核方案规定：凡查实存在有偿补课、体罚学生等师德失范行为的，年度考核直接定为不合格、取消当年评优评职资格。这一做法体现了（　）', '[["A","以升学率为核心的评价导向"],["B","重业务、轻师德的考核思路"],["C","师德作为考核首要内容、失范一票否决"],["D","师德表现仅供参考"]]', '["C"]', '现行教师考核评价政策把师德师风作为第一标准，师德考核不合格者年度考核定为不合格，并在教师资格定期注册、职务（职称）评审、岗位聘用和评优奖励等环节实行“一票否决”。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2506, 53, 76, 'single', 1.0, '生物课上，郜老师把“本地水质调查”交给各小组，由学生自己提出问题、分工采样、查阅资料并汇报结论，教师只在关键处点拨。这一学习方式主要是（　）', '[["A","被动接受学习"],["B","机械学习"],["C","自主、合作、探究学习"],["D","个别化死记硬背"]]', '["C"]', '学生以问题为载体，自主提出方案、分工合作、动手探究并得出结论，集中体现新课程倡导的自主、合作、探究学习方式，与被动接受、机械记忆相对。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2507, 53, 77, 'single', 1.0, '某中学从七年级起开设劳动实践、研学旅行等课程，列入课表、计算学时、有专门教师指导。按照新课程结构，这类课程属于（　）', '[["A","课外自愿参加的兴趣小组"],["B","从小学到高中设置的必修课程"],["C","仅在高中开设的选修课程"],["D","学科课程的课后作业"]]', '["B"]', '《基础教育课程改革纲要（试行）》规定，从小学至高中设置综合实践活动并作为必修课程，内容包括信息技术教育、研究性学习、社区服务与社会实践以及劳动与技术教育。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2508, 53, 78, 'single', 1.0, '备课会上，宿老师强调：“课程标准是国家对学生在某学段应达到的学业成就的统一要求，是教材编写、教学和考试命题的直接依据。”这主要说明课程标准具有（　）', '[["A","强制性和法定依据作用"],["B","可有可无的参考作用"],["C","仅约束学生的作用"],["D","替代一切教学计划的作用"]]', '["A"]', '课程标准是国家课程的基本纲领性文件，规定课程性质、目标、内容和学业质量，是教材编写、教学、评估和考试命题的依据，体现国家意志，具有权威性和约束力。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2509, 53, 79, 'single', 1.0, '某校每周开设一节科学创新课，配备实验箱和人工智能学习平台，组织学生开展机器人、气象观测等项目，并鼓励大胆提问、容忍试错。这一举措直接服务于（　）', '[["A","加强新时代中小学科学教育"],["B","增加学科考试科目"],["C","提前分流学生"],["D","以竞赛成绩替代教学"]]', '["A"]', '近年来国家连续部署加强新时代中小学科学教育，要求强化科学课程实施、实验教学与科普资源供给，培养学生科学兴趣、创新精神和实践能力。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2510, 53, 80, 'single', 1.0, '学校要求各学科统筹作业总量，鼓励布置分层、弹性和实践性作业，严禁布置重复性、惩罚性作业，教师对作业全批全改。这落实的是（　）', '[["A","义务教育学校作业管理要求"],["B","高校学分制改革"],["C","教师资格定期注册"],["D","学校办学体制改革"]]', '["A"]', '“双减”配套的义务教育学校作业管理要求明确：调控作业结构和总量、提高作业设计质量、布置分层弹性和实践性作业、不得布置重复性惩罚性作业、教师认真批改反馈。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2511, 53, 81, 'multi', 1.6, '某地在落实课程管理改革时，允许县教研室结合本地竹资源开发地方乡土课程，允许学校在保证国家课程实施的前提下自主开发《竹编与生活》校本课程，同时报上级教育行政部门备案。对这一课程管理体制理解正确的有（　）', '[["A","国家、地方、学校共同参与，体现三级课程管理"],["B","学校在执行国家课程和地方课程的同时可开发校本课程"],["C","校本课程应结合本校传统、学生需求和当地资源优势"],["D","学校可以用自编校本课程取代国家课程"],["E","校本课程可以不经论证随意开设"]]', '["A","B","C"]', '我国基础教育实行国家、地方、学校三级课程管理，学校在保证国家课程和地方课程有效实施的前提下，可结合学校传统、学生需要和当地资源开发或选用校本课程，并履行相应审议备案程序；校本课程是对国家课程的补充而非替代，更不能不经论证随意开设。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2512, 53, 82, 'multi', 1.6, '化学老师在“质量守恒”单元后，没有让学生重复刷题，而是带学生分析蜡烛燃烧、铁生锈等不同现象，引导他们提炼出“透过表面变化找不变量”的一般思路，并迁移到陌生方程式计算中。能合理解释其做法的迁移理论与策略有（　）', '[["A","提炼一般原理和方法，与概括化理论（经验类化说）相吻合"],["B","不同情境间存在共同的分析要素，可借助共同要素说促进迁移"],["C","教会学生识别可迁移的一般思路，比死记单一结论更重要"],["D","反复背诵固定结论形成定势，是提高迁移能力的根本途径"],["E","只在高难度偏题上反复训练，迁移能力自然形成"]]', '["A","B","C"]', '概括化理论认为对原理、方法的概括水平越高越易迁移，A正确；共同要素说认为新旧情境间存在共同成分时迁移更易发生，B正确；教学应帮助学生形成可迁移的一般思路而非记住单一结论，C正确；机械背诵形成的僵化定势和一味钻偏题难题都不利于广泛、灵活的迁移，D、E错误。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2513, 53, 83, 'multi', 1.6, '班里几名留守学生刚住校时拘谨不安，郦老师先安排好食宿、指定伙伴帮助融入，常与他们谈心。依据需要层次理论，当归属与爱的需要基本满足后，个体更可能进一步追求的是（　）', '[["A","归属与爱的需要本身"],["B","尊重的需要"],["C","自我实现的需要"],["D","生理需要"],["E","安全需要"]]', '["B","C"]', '马斯洛将需要由低到高分为生理、安全、归属与爱、尊重、自我实现等层次，低层次需要基本满足后会追求更高层次需要。归属与爱之后主要指向尊重需要和自我实现需要；生理、安全需要层次更低，归属与爱本身是当前正在满足的需要。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2514, 53, 84, 'multi', 1.6, '数学老师发现，学生练熟一类题型后再做同类题很快，可一旦题目换个角度设问，不少人仍套用旧思路、反复出错。关于这种现象，下列分析正确的有（　）', '[["A","反复形成的固定思路属于定势，解决同类问题时可能提高效率"],["B","当问题情境变化时，定势可能束缚思路、妨碍灵活解题"],["C","定势对问题解决既有积极作用也有消极作用，具有双重性"],["D","为避免定势，教学中应只练一种标准题型"],["E","定势一旦形成就永远无法改变"]]', '["A","B","C"]', '定势是由先前经验形成的心理准备状态。遇到同类或常规问题时，定势可帮助快速套用方法（A）；当条件或设问角度改变时，旧定势会束缚思维、产生消极影响（B），因此定势具有积极与消极的双重作用（C）。只练单一标准题型反而强化僵化定势（D错），定势可通过变式训练、发散思考加以改变，并非不可改变（E错）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2515, 53, 85, 'multi', 1.6, '新入职的单老师课后总在想“学生喜不喜欢我”“同事和领导怎么看我”，花很多精力经营人际关系、适应岗位。关于该教师所处成长阶段，判断正确的有（　）', '[["A","处于关注生存阶段"],["B","关注焦点是人际关系与职业适应"],["C","处于关注学生阶段"],["D","主要关注教学情境和教学方法"],["E","已能自觉依据学生差异因材施教"]]', '["A","B"]', '福勒和布朗把教师成长分为关注生存、关注情境、关注学生阶段。新教师最担心自己能否立足，关注领导、同事和学生是否接纳自己，属于关注生存阶段；关注教学情境是第二阶段，关注学生差异因材施教是成熟阶段的标志。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2516, 53, 86, 'multi', 1.6, '某中学在学生信息管理中采取了一系列做法。下列做法中，符合学生隐私权与个人信息保护要求的有（　）', '[["A","心理普查结果单独建档，仅限心理教师在辅导需要时查阅"],["B","处分决定仅在法定范围内、向相关人员告知，不在校园公众号公开"],["C","宣传学生获奖时，事先征得学生及监护人同意并隐去家庭住址等信息"],["D","为方便家校沟通，将全班学生身份证号、家庭住址群发至所有家长"],["E","安装校园监控时避开更衣室、卫生间内部等私密空间"]]', '["A","B","C","E"]', '心理档案、处分信息属于学生隐私与个人信息，应限制知悉范围、单独妥善保管（A、B）；公开使用学生肖像和信息应征得同意并作必要脱敏（C）；监控不得覆盖更衣、如厕等私密空间（E）。将身份证号、家庭住址向全体家长群发，超范围收集、公开个人信息，违反最小必要和保密要求（D错）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2517, 53, 87, 'multi', 1.6, '某校在安全检查中发现多起问题：教师体罚学生被给予记过；某培训机构违规招生被罚款并没收违法所得；学校设施缺陷致学生受伤被判赔偿医疗费；一名教职工伤害学生情节严重被追究刑罚。关于这些责任的类型，对应正确的有（　）', '[["A","教师被记过属于行政处分"],["B","培训机构被罚款属于行政处罚"],["C","学校赔偿医疗费属于民事责任"],["D","教职工被判刑属于刑事责任"],["E","上述处理都属于同一种纪律责任"]]', '["A","B","C","D"]', '教育法律责任包括行政、民事、刑事三类。对内部教师的记过是行政处分，对行政相对人的罚款没收是行政处罚，二者同属行政责任；赔偿损失是民事责任；情节严重构成犯罪被判刑是刑事责任。四种情形责任性质不同，E错误。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2518, 53, 88, 'multi', 1.6, '教师合法权益受到侵害时，可以选择的法定救济渠道有（　）', '[["A","向主管教育行政部门提出教师申诉"],["B","依法申请行政复议"],["C","依法提起行政诉讼"],["D","通过调解等方式解决纠纷"],["E","组织学生家长集体上访施压"]]', '["A","B","C","D"]', '教师维权可依法通过教师申诉、行政复议、行政诉讼以及调解等渠道进行；组织、煽动学生家长集体上访施压既不合法也损害教育秩序，不是正当救济途径。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2519, 53, 89, 'multi', 1.6, '依据《教师法》，下列各项中属于教师应当履行义务的有（　）', '[["A","遵守宪法、法律和职业道德，为人师表"],["B","贯彻国家教育方针，完成教育教学工作任务"],["C","关心爱护全体学生，尊重学生人格"],["D","自定标准向学生收取资料费"],["E","在课堂上随意发表不负责任的言论"]]', '["A","B","C"]', '《教师法》规定教师应遵守法律法规和职业道德、贯彻教育方针完成教学任务、关心爱护尊重学生等义务；违规收费侵害学生权益，课堂上发表违法或不负责任言论违背教师义务。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2520, 53, 90, 'multi', 1.6, '班主任连续发现本班一名学生手臂有不明伤痕、神情恐惧，经耐心询问，学生哭诉遭家庭成员严重殴打。依法，下列认识正确的有（　）', '[["A","发现未成年人疑似遭受家庭暴力，学校、教师负有强制报告义务"],["B","应当及时向公安机关等有关部门报告，不得因“家务事”隐瞒"],["C","报告时应注意保护学生安全，避免其再次受到伤害"],["D","这是别人家事，教师只需私下劝诫家长即可"],["E","知情不报造成严重后果的，相关责任人可能被追责"]]', '["A","B","C","E"]', '《未成年人保护法》确立强制报告制度：任何组织或个人发现未成年人身心健康受到侵害、疑似受到侵害或面临其他危险情形，都有权劝阻、制止或向公安、民政、教育等部门报告；密切接触未成年人的单位及其工作人员负有强制报告义务，不得视为“家务事”而隐瞒，失职造成严重后果要担责。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2521, 54, 1, 'judge', 0.6, '《学记》提出“杂施而不孙，则坏乱而不修”，这启示教学不能超越学生接受顺序、盲目施教。', '[["A","正确"],["B","错误"]]', '["A"]', '“杂施而不孙”意为教学杂乱而不依顺序，就会使学生头脑混乱而难有成效，这正体现了循序渐进教学原则的要求，教学应按学科逻辑和学生认识发展顺序由浅入深进行。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2522, 54, 2, 'judge', 0.6, '体育课上，钟老师未带学生热身就直接进行八百米限时测试。这一安排违背了桑代克的准备律。', '[["A","正确"],["B","错误"]]', '["A"]', '桑代克提出学习三定律，其中准备律指导者在学习开始时的预备定势：有准备且给以活动则满意，无准备被迫活动则烦恼。突然袭击式的测验使学生毫无心理准备，违背准备律。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2523, 54, 3, 'judge', 0.6, '某小学以“影响班级成绩”为由，拒绝片区内一名轻度智力障碍适龄儿童随班就读，并称招生由学校自主决定。', '[["A","正确"],["B","错误"]]', '["B"]', '普通学校应当接收具有接受普通教育能力的残疾适龄儿童、少年随班就读，并为其学习、康复提供帮助。学校无权以影响成绩为由拒绝符合条件的残疾儿童入学，该做法侵犯其平等受教育权。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2524, 54, 4, 'judge', 0.6, '墨子以“染于苍则苍，染于黄则黄”喻人，有老师据此断言：学生发展完全由环境决定，与主观努力无关。', '[["A","正确"],["B","错误"]]', '["B"]', '“染丝”之喻说明环境对人的发展有重要影响，但环境只是外部条件，个体的主观能动性才是发展的内在动力和决定性因素。把环境作用绝对化为“环境决定论”、否定主观努力，是错误的。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2525, 54, 5, 'judge', 0.6, '放学后，何老师放下没批完的作业去做直播带货，对学生线上提问一律不回，这有悖爱岗敬业的要求。', '[["A","正确"],["B","错误"]]', '["A"]', '爱岗敬业要求教师忠诚于教育事业、勤恳敬业、对工作高度负责，认真备课上课、批改作业、辅导学生。何老师把主要精力放在直播带货上，荒废本职、对学生提问不理不问，违背了爱岗敬业的师德规范。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2526, 54, 6, 'judge', 0.6, '物理组教研时，新教师小秦认为学生掌握学科基本结构的最好方式是听教师系统讲授。', '[["A","正确"],["B","错误"]]', '["B"]', '布鲁纳的认知一结构学习理论强调“不论我们教什么学科，务必使学生理解学科的基本结构”，并主张掌握学科基本结构的最佳方式是发现学习，让学生独立思考、自行发现知识之间的结构与规律，而非单纯被动听讲。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2527, 54, 7, 'judge', 0.6, '教完《狼牙山五壮士》，宋老师带学生到烈士陵园祭扫，在真实场景中感悟课文，这体现了理论联系实际原则。', '[["A","正确"],["B","错误"]]', '["A"]', '理论联系实际原则要求教学以基础知识为主导，从理论与实际的联系上去理解知识，并运用知识去分析解决问题。宋老师把书本知识与祭扫烈士、实地感悟结合起来，使学生在实际情境中深化理解，体现了该原则。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2528, 54, 8, 'judge', 0.6, '化学课上，老师未讲操作规程就让学生自行点燃酒精灯，致一名学生烧伤，该教师未尽到管理与保护职责。', '[["A","正确"],["B","错误"]]', '["A"]', '教师对学生负有教育、管理和保护的法定义务，组织危险实验时应事先讲清操作规程、采取安全防护措施并全程指导。该教师未尽必要的安全教育与管理义务，对事故发生存在过错。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2529, 54, 9, 'judge', 0.6, '校运会报名时，小磊专挑胜负难料、需奋力一搏的项目，不愿参加稳赢或必输的项目，他更像力求成功者。', '[["A","正确"],["B","错误"]]', '["A"]', '阿特金森成就动机理论认为，力求成功者最有可能选择成功概率约为 50%、有一定挑战性的任务，因为这种任务能带来最大的现实挑战和成就满足；避免失败者则倾向选择极难或极易的任务以防自尊受损。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2530, 54, 10, 'judge', 0.6, '为提高成绩，江老师让学生把同一篇范文反复抄写背诵，认为这样就能提升阅读理解和写作能力。', '[["A","正确"],["B","错误"]]', '["B"]', '教学过程具有掌握知识与发展能力相统一的规律，知识是能力形成的基础，但知识不等于能力，能力需要在主动理解、迁移运用中发展。机械抄背只重记忆、不重理解与运用，难以真正提高阅读和写作能力。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2531, 54, 11, 'judge', 0.6, '支教老师认为，对刚解决温饱的学生，应把赢得尊重和自我实现安排得比安全、温饱等需要更优先。', '[["A","正确"],["B","错误"]]', '["B"]', '马斯洛需要层次理论把需要由低到高分为生理需要、安全需要、归属与爱的需要、尊重需要和自我实现需要，低级需要至少部分满足后人才会追求高级需要。对刚解决温饱的学生，应先保障其生理、安全等基本需要，再逐步引导高级需要。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2532, 54, 12, 'judge', 0.6, '许老师指定几名班干部后从不改选，也不许学生评议，认为这样最有利于班集体核心的形成与巩固。', '[["A","正确"],["B","错误"]]', '["B"]', '班干部是班集体的核心，培养班集体要善于发现和培养积极分子，并实行班干部轮换、民主选举与民主评议，让更多学生得到锻炼。教师长期指定且不许评议，不利于学生主体作用发挥和班集体健康发展。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2533, 54, 13, 'judge', 0.6, '发现初中生逃学夜不归宿，班主任文老师当晚联系其父母并会同加强管教，没有听之任之。', '[["A","正确"],["B","错误"]]', '["A"]', '旷课、逃学、夜不归宿属于未成年人的不良行为。学校对有不良行为的未成年学生应当加强管理教育，不得歧视，并应及时与其父母或者其他监护人取得联系，共同加强管教。文老师的做法符合法律规定。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2534, 54, 14, 'judge', 0.6, '有老师认为，既然新课改要求教师做学生学习的促进者，就可以放弃知识传授，只当课堂“旁观者”。', '[["A","正确"],["B","错误"]]', '["B"]', '新课改下教师由知识的传授者转变为学生学习的促进者，强调教师是学生学习能力的培养者和人生的引路人，但这并不意味着取消教师的知识传授责任、放任自流。教师仍要发挥主导作用，在关键处讲解、点拨和引导。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2535, 54, 15, 'judge', 0.6, '英语老师要求学生学完新词后在后续阅读、写作中多次运用，在运用中巩固所学。', '[["A","正确"],["B","错误"]]', '["A"]', '巩固性原则要求教学要引导学生在理解的基础上牢固掌握知识和技能，并能在需要时及时再现、加以运用。该老师让学生在阅读、写作等新情境中反复运用新词，在运用中加深理解和保持，符合巩固性原则。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2536, 54, 16, 'judge', 0.6, '小芳多次成功完成难度递增的物理实验后，反而越发怀疑自己的动手能力，上课不敢碰实验器材。', '[["A","正确"],["B","错误"]]', '["B"]', '班杜拉自我效能感理论指出，个人自身行为的成败经验是影响自我效能感最主要、最可靠的因素，不断成功会提高效能感，反复失败则会降低。小芳多次成功完成难度递增的实验，正常情况下应增强而非削弱其动手的自我效能感。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2537, 54, 17, 'judge', 0.6, '“要给学生一碗水，教师得有一桶水”，有教师据此认为只要学科知识扎实就能胜任教学，不必再学其他。', '[["A","正确"],["B","错误"]]', '["B"]', '教师职业素养是多方面的，除学科专业知识外，还需具备教育理论素养、教育教学能力、职业道德和健康心理等，且“一桶水”本身也需不断更新。只凭学科知识扎实就认为能胜任教学、放弃持续学习，是片面的。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2538, 54, 18, 'judge', 0.6, '历史课上记住“公元前221年秦统一六国”这一史实，在奥苏贝尔的分类中属于符号（代表性）学习。', '[["A","正确"],["B","错误"]]', '["A"]', '奥苏贝尔将有意义学习由简到繁分为符号学习、概念学习和命题学习。符号学习指学习单个符号或一组符号的意义，包括词汇学习和非语言符号、事实性知识的学习。历史年代、历史事件等事实性知识的学习属于符号学习。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2539, 54, 19, 'judge', 0.6, '某校规定损坏教室财物的学生按原价十倍缴“罚款”，校方称这是其自主管理权范围内的合法处罚。', '[["A","正确"],["B","错误"]]', '["B"]', '学校不是行政机关，不具有行政处罚权，无权对学生设定和收取“罚款”；损坏公物可依法照价赔偿，但十倍“罚款”没有法律依据，且侵犯学生及其家长的财产权。家长有权拒绝并向教育行政部门反映。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2540, 54, 20, 'judge', 0.6, '贺老师备课只钻研教材、设计教法，从不去了解学生的知识基础和学习习惯，认为这样也能上好课。', '[["A","正确"],["B","错误"]]', '["B"]', '备课是上好课的前提，教师备课要做到“三备”：钻研教材、了解学生、设计教法。了解学生已有知识基础、认知特点和学习习惯是确定教学起点、增强教学针对性的必要条件。只备教材和教法而不备学生，难以保证教学效果。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2541, 54, 21, 'judge', 0.6, '班主任只按分数排座位，把学生分三六九等，从不过问品行习惯，这偏离了既教书又育人的本分。', '[["A","正确"],["B","错误"]]', '["A"]', '教书育人是教师的天职，要求教师遵循教育规律、实施素质教育，不以分数作为评价学生的唯一标准，培养学生良好品行。该班主任唯分数是从、按分排座、忽视品德培养，违背了教书育人的要求。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2542, 54, 22, 'judge', 0.6, '师范生小苏练板书起初进步很快，苦练两周后停滞不前，再练一段又有提高，中间的停滞属高原现象。', '[["A","正确"],["B","错误"]]', '["A"]', '高原现象是指在操作技能形成过程中，练习到一定阶段出现的进步暂时停顿、甚至略有下降的现象，渡过这一阶段后成绩仍可继续提高。小苏“进步一停滞一再提高”的练习曲线正是高原现象的典型表现。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2543, 54, 23, 'judge', 0.6, '班规全部由班主任一人拟定后张贴执行，有老师认为这样令行禁止，比让学生参与制定更能培养自我教育能力。', '[["A","正确"],["B","错误"]]', '["B"]', '班级管理应发挥学生主体作用，实行民主管理，组织学生共同参与班规制定和执行，才能增强规则认同、培养自我教育与自我管理能力。班主任独断制定班规，学生只是被动服从，反而不利于自我教育能力发展。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2544, 54, 24, 'judge', 0.6, '小郑做惯了“求周长”的题，考试遇到“求面积”也按周长的思路列式，这体现了定势对问题解决的消极影响。', '[["A","正确"],["B","错误"]]', '["A"]', '定势是由先前活动形成的、影响后续活动趋势的心理准备状态。当问题情境发生变化时，原有思维方式会束缚新思路，对问题解决产生消极影响。小郑不区分周长与面积、机械套用旧思路，正是定势消极作用的表现。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2545, 54, 25, 'judge', 0.6, '为提高统考成绩，某校把综合实践活动课时全部调给语文、数学，这一做法符合国家课程实施要求。', '[["A","正确"],["B","错误"]]', '["B"]', '综合实践活动是从小学到高中设置的必修课程，任何学校和教师不得随意占用、挪用其课时。把综合实践活动课全部调给考试科目，既违反课程方案、挤占必修课程，也违背素质教育和“五育并举”要求。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2546, 54, 26, 'judge', 0.6, '为防作弊，某校考试一律双人全程监考，从不安排无人监考等自我约束环节，认为这最能培养诚信品质。', '[["A","正确"],["B","错误"]]', '["B"]', '诚信品德的形成离不开学生自我教育能力的培养。道德修养法（指导自我教育法）强调引导学生通过无人监考等形式进行自我约束、自我评价和自我监督。一味靠外部严防死守，忽视自我教育，难以真正形成自觉的诚信品质。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2547, 54, 27, 'judge', 0.6, '对小学低年级学生安排长时间静坐听讲、抽象讲解，忽视了这一年龄阶段学生身心发展的特点。', '[["A","正确"],["B","错误"]]', '["A"]', '个体身心发展具有阶段性，不同年龄阶段有不同的总体特征和主要矛盾，教育必须从学生实际出发，针对不同年龄阶段学生采用不同内容和方法。低年级学生以具体形象思维为主、注意力持续时间短，长时间静坐听讲和抽象讲解违背阶段性要求。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2548, 54, 28, 'judge', 0.6, '家长重金奖励原本爱读书的孩子，停奖后孩子反而不再主动阅读，这说明不当外部奖励可能削弱内部动机。', '[["A","正确"],["B","错误"]]', '["A"]', '当个体原本对活动本身具有兴趣（内部动机）时，不恰当的外部物质奖励可能使其把行为归因于奖励而非兴趣，一旦外部奖励撤除，行为反而减少，即外部奖励对内部动机产生侵蚀（过当效应）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2549, 54, 29, 'judge', 0.6, '苏霍姆林斯基说真正的教育在于激发自我教育。某班主任事事包办、不给学生自主管理空间，与此理念相悖。', '[["A","正确"],["B","错误"]]', '["A"]', '苏霍姆林斯基高度重视学生的自我教育，认为真正的教育是能激发学生自我教育的教育。班主任事事包办代替，学生缺乏自主管理、自我锻炼的机会，其主动性和自我教育能力无法生长，与这一理念相悖。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2550, 54, 30, 'judge', 0.6, '校运动会上，吴老师只安排几名体育特长生参赛，其余学生一律当观众，这符合素质教育面向全体的要求。', '[["A","正确"],["B","错误"]]', '["B"]', '素质教育是面向全体学生的教育，强调为每个学生提供适合的教育、让每个学生都得到发展，而非只关注少数尖子生。运动会只让特长生上场、其余学生当观众，把多数学生排除在活动之外，违背了素质教育面向全体学生的要求。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2551, 54, 31, 'single', 1.0, '李老师发现，学生的身高体重在低年级变化不明显，进入初中后却突然蹿高；而语言能力在学前期发展最快。她据此提出应抓住各方面发展最快的时期重点培养。这一认识主要依据个体身心发展的（　）', '[["A","不平衡性"],["B","顺序性"],["C","互补性"],["D","个别差异性"]]', '["A"]', '不平衡性表现在同一方面发展速度在不同年龄阶段不均衡、不同方面发展不同步，要求教育抓住关键期及时而教。学生身高和语言能力在不同时期发展速度不同，正是不平衡性的体现。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2552, 54, 32, 'single', 1.0, '数学老师给学生布置独立完成有困难、但在同伴互助和教师点拨下能够完成的探究任务，他主张教学应走在发展前面，为学生搭建“脚手架”。这种做法的理论依据是（　）', '[["A","皮亚杰认知发展阶段论"],["B","维果斯基最近发展区理论"],["C","埃里克森人格发展阶段论"],["D","加涅信息加工理论"]]', '["B"]', '最近发展区是儿童独立解决问题的现有水平与在成人或同伴帮助下可能达到的水平之间的区域，教学应着眼最近发展区、适当走在发展前面，并通过“支架”促进发展。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2553, 54, 33, 'single', 1.0, '暑假期间，某校强制要求全体教师无偿参加与教学无关的商业宣传活动，不参加就扣发绩效。教师拒绝该安排，主要是在维护《教师法》赋予的（　）', '[["A","指导评价学生的权利"],["B","进修培训的权利"],["C","获取工资报酬和享受寒暑假带薪休假的权利"],["D","参与学校民主管理的权利"]]', '["C"]', '教师享有按时获取工资报酬、享受国家规定的福利待遇以及寒暑假期带薪休假的权利。学校无偿占用教师假期、以扣绩效相威胁的做法侵犯该项权利。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2554, 54, 34, 'single', 1.0, '备课组讨论如何对待有过错和基础薄弱的学生，组长引用“自行束脩以上，吾未尝无悔焉”表明态度。这一主张出自（　）', '[["A","孟子"],["B","荀子"],["C","墨子"],["D","孔子"]]', '["D"]', '“自行束脩以上，吾未尝无诲焉”出自《论语·述而》，体现孔子“有教无类”、扩大教育对象范围的思想。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2555, 54, 35, 'single', 1.0, '教龄八年的喻老师不再只盯着“这节课能不能按教案讲完”，开始琢磨不同层次学生的学习效果，并主动依据学情调整教学。按福勒和布朗的相关研究，她最可能处于（　）', '[["A","只关心自己能否在新环境站稳脚跟的阶段"],["B","真正关注不同学生学习需要的阶段"],["C","只关心教学内容和授课技巧的阶段"],["D","师范学习时的虚拟关注阶段"]]', '["B"]', '福勒和布朗把教师成长分为关注生存、关注情境和关注学生三阶段：关注生存在意自我胜任与人际接纳，关注情境在意教学内容与课堂组织，关注学生才真正因材施教、关注学生差异与发展。喻老师关注不同层次学生的学习效果，属关注学生阶段。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2556, 54, 36, 'single', 1.0, '放学后突降暴雨，寄宿学生小林发烧，班主任周老师冒雨背她就医、垫付医药费，并一直陪护到家长赶来。这一行为最直接体现的师德规范是（　）', '[["A","教书育人"],["B","为人师表"],["C","关爱学生"],["D","终身学习"]]', '["C"]', '关爱学生要求关心爱护全体学生、保护学生安全、关心学生健康、维护学生权益。雨夜送医、陪护学生直接体现关爱学生。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2557, 54, 37, 'single', 1.0, '公开课上有老师提出“既然要突出学生主体，教师就该少讲甚至不讲”。评课专家指出，发挥学生主动性不等于削弱教师作用，二者是统一的。这体现的教学过程规律是（　）', '[["A","教师主导作用与学生主体作用相统一"],["B","掌握知识与发展能力相统一"],["C","直接经验与间接经验相统一"],["D","传授知识与思想品德教育相统一"]]', '["A"]', '教学过程是教师主导作用与学生主体作用的辩证统一：教师是教学活动的组织者和领导者，学生是学习和发展的主体，二者不可偏废。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2558, 54, 38, 'single', 1.0, '体育组研讨时，把“学生能在比赛情境中判断传球时机并组织有效进攻”单列，区别于“记住战术规则”。按布卢姆教学目标分类，前者属于（　）', '[["A","知识（识记）层次"],["B","运用及以上的高阶认知目标"],["C","接受（注意）层次"],["D","知觉层次"]]', '["B"]', '布卢姆将认知目标由低到高分为知识、领会、运用、分析、综合、评价。能在真实比赛情境中判断时机并组织进攻，需要将规则用于新情境，属于运用及以上的高阶目标。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2559, 54, 39, 'single', 1.0, '午休时，社会青年唐某趁学校电动门故障敞开之际闯入，将学生小周推倒致伤；经查该校门禁坏了半个月未修，保安也未在岗巡查。对小周所受伤害，下列认定正确的是（　）', '[["A","由唐某与学校平均分担赔偿"],["B","唐某下落不明时由班主任赔偿"],["C","学校不承担任何责任"],["D","由唐某赔偿，学校承担相应的补充责任"]]', '["D"]', '校外第三人侵权造成学生人身损害的，由第三人承担赔偿责任；学校未尽到管理职责的，承担相应的补充责任。围墙失修、门卫脱岗表明学校存在过错。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2560, 54, 40, 'single', 1.0, '新教师文婷发现自己班上的课堂讨论总冷场，于是设计了三轮提问方式调整方案，边实施边记录、边反思改进，最终解决了问题。她采用的研究方法属于（　）', '[["A","教育行动研究"],["B","教育实验法"],["C","历史研究法"],["D","问卷调查法"]]', '["A"]', '行动研究是教师在真实教育情境中，为解决自身实际问题，按“计划—行动—观察—反思”循环开展、边做边改的研究方法。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2561, 54, 41, 'single', 1.0, '学习经验分享会上，小蒋介绍自己每学完一章就画思维导图梳理知识关系，考前还会制订复习时间表并自我检查。她介绍的这些方法总体上属于（　）', '[["A","学习策略"],["B","学习习惯"],["C","学习动机"],["D","学习迁移"]]', '["A"]', '学习策略是学习者为提高学习效果和效率而有目的、有意识地制订的有关学习过程的复杂方案，包括认知策略、元认知策略和资源管理策略。画思维导图、自我计划与检查均属学习策略。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2562, 54, 42, 'single', 1.0, '教研组为帮助青年教师成长，安排骨干教师与其结对，通过随堂听课、磨课、课后研讨进行“传帮带”。这种教师专业发展途径属于（　）', '[["A","职前师范教育"],["B","入职辅导（师徒结对）"],["C","教师的自我教育"],["D","在职脱产学历教育"]]', '["B"]', '新教师入职后由经验丰富的骨干教师以师徒结对方式进行现场指导、听课磨课，属于入职辅导途径，是促进新教师角色适应的重要方式。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2563, 54, 43, 'single', 1.0, '课改培训中，主讲人强调知识不能由教师“装进”学生头脑，而要由学生借助原有经验，在真实任务和同伴协作中主动建构。这一观点主要属于（　）', '[["A","建构主义学习理论"],["B","行为主义学习理论"],["C","精神分析理论"],["D","经典条件反射理论"]]', '["A"]', '建构主义强调学习的主动建构性、社会互动性和情境性，主张学生在原有经验基础上，通过协作和真实情境建构意义。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2564, 54, 44, 'single', 1.0, '某省人大常委会制定了一部有关义务教育的地方性法规，其中某条款与全国人大常委会制定的法律相抵触。依法应优先适用（　）', '[["A","该地方性法规"],["B","全国人大常委会制定的法律"],["C","教育部规章"],["D","由省教育厅裁定适用"]]', '["B"]', '宪法具有最高法律效力，法律的效力高于行政法规、地方性法规和规章。下位法不得与上位法相抵触，抵触的条款无效或不予适用。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2565, 54, 45, 'single', 1.0, '小林做作业时，旁边同学讨论什么她就容易被什么带偏；同桌小郑却能在嘈杂环境中专注完成任务，较少受外界干扰。小郑的认知风格更偏向（　）', '[["A","场依存型"],["B","冲动型"],["C","场独立型"],["D","沉思型"]]', '["C"]', '场独立型的人不易受外界因素干扰，能依据自身内在标准知觉和判断；场依存型者易受周围环境和他人影响；冲动型与沉思型区分的是反应速度与准确率。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2566, 54, 46, 'single', 1.0, '某校科学课让学生围绕“小区垃圾分类现状”分组调查、实验、讨论，自己寻找证据得出结论，而不是只听老师讲结论。这种学习方式主要是（　）', '[["A","接受学习"],["B","机械学习"],["C","个体孤立学习"],["D","自主、合作、探究学习"]]', '["D"]', '新课程倡导学生主动参与、乐于探究、勤于动手，在真实问题中开展自主学习、合作学习和探究学习，改变单一接受式学习。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2567, 54, 47, 'single', 1.0, '修小家电时，老吴先判断故障出在哪里，再根据经验列出几种可能原因，选定最可能的一种先试修。他“列出并选定可能原因”处于问题解决过程的（　）', '[["A","发现问题阶段"],["B","理解问题阶段"],["C","提出假设阶段"],["D","检验假设阶段"]]', '["C"]', '问题解决一般经历发现问题、理解问题、提出假设、检验假设四阶段。提出假设就是提出解决问题的可能途径、方法和策略，列出并选定可能原因正属于提出假设。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2568, 54, 48, 'single', 1.0, '比较教育课上，老师展示了一种近代学制：一轨为资产阶级子女设立，自上而下通向大学；另一轨为劳动人民子女设立，自下而上只到职业学校，两轨互不相通。该学制是（　）', '[["A","单轨学制"],["B","双轨学制"],["C","分支型学制"],["D","壬戌学制"]]', '["B"]', '双轨学制以近代西欧为代表，一轨学术、一轨职业，两轨平行互不相通，具有明显阶级性；单轨制以美国为代表，分支型以苏联为代表。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2569, 54, 49, 'single', 1.0, '自习课上两名学生小声争吵影响纪律，老师没有中断全班、当众训斥，而是走到桌边轻敲桌面、用眼神示意，两人随即安静。该教师运用的问题行为矫正策略是（　）', '[["A","非言语线索提示"],["B","惩罚"],["C","消退"],["D","直接请家长到校"]]', '["A"]', '对轻微课堂问题行为，教师可运用目光接触、手势、走近学生等非言语线索及时提示，既纠正行为，又避免中断教学、伤害学生自尊。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2570, 54, 50, 'single', 1.0, '某县规定，本县小学毕业生须通过统一选拔考试，按成绩分流入读不同初中。该规定直接违反了义务教育（　）', '[["A","免试就近入学及强制性、普及性要求"],["B","免费性要求"],["C","统一性要求"],["D","终身性要求"]]', '["A"]', '义务教育是所有适龄儿童少年必须接受的教育，具有强制性、免费性、普及性，适龄儿童少年免试就近入学，学校不得分重点校、重点班，不得组织选拔考试。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2571, 54, 51, 'single', 1.0, '为帮助好动的孩子安静坐好，妈妈规定他每安静写完二十分钟作业就盖一个小印章，集满五个可兑换一次周末出游。妈妈运用的原理是（　）', '[["A","经典条件反射"],["B","操作性条件作用中的正强化"],["C","观察学习"],["D","顿悟学习"]]', '["B"]', '斯金纳操作性条件作用理论认为，通过给予愉快刺激（印章、出游）来增加良好行为发生的概率，属于正强化。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2572, 54, 52, 'single', 1.0, '特级教师常说教学要量一量学生的“火候”，既不能让学生踮起脚也够不着，也不能不费力气就学会。这强调的教学原则是（　）', '[["A","因材施教原则"],["B","巩固性原则"],["C","量力性（可接受性）原则"],["D","直观性原则"]]', '["C"]', '量力性原则又称可接受性原则，指教学内容、方法和分量、进度要适合学生发展水平，既有一定难度、需要努力，又能为学生所接受并促进发展。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2573, 54, 53, 'single', 1.0, '老师发现，背诵类简单任务时学生适当紧张一点成绩更好，而解答高难度综合题时过度焦虑反而发挥失常。这一现象可用下列哪一原理解释（　）', '[["A","耶克斯一多德森定律"],["B","艾宾浩斯遗忘曲线"],["C","皮格马利翁效应"],["D","首因效应"]]', '["A"]', '耶克斯一多德森定律指出最佳动机（唤醒）水平随任务性质变化：较易任务最佳水平较高，困难复杂任务最佳水平较低，动机过高反而降低效率，二者呈倒U形关系。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2574, 54, 54, 'single', 1.0, '高二学生小柯在体育课组织的班级篮球赛正常拼抢中，被同学小冯撞倒受伤；课前老师讲过规则与安全要求，赛中全程在场组织，场地器材合格。家长要求学校全额赔偿。依法下列处理正确的是（　）', '[["A","学校和小冯各承担一半赔偿"],["B","由体育老师个人赔偿"],["C","学校应全额赔偿"],["D","属对抗性比赛中的正常风险，学校已尽职责，不承担责任"]]', '["D"]', '篮球等具有一定风险的对抗性体育活动中，自愿参加者因其他参加者非故意或非重大过失行为受损的，不得请求其他参加者承担侵权责任；学校尽到教育、管理职责的，不承担责任。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2575, 54, 55, 'single', 1.0, '玩游戏时，十岁的小宇开始认为规则不是绝对不变的，如果大家同意，可以修改游戏规则以更公平。按皮亚杰儿童道德发展阶段理论，他处于（　）', '[["A","自我中心阶段"],["B","可逆性（自律道德）阶段"],["C","权威（他律道德）阶段"],["D","公正阶段"]]', '["B"]', '皮亚杰认为约8—10岁儿童进入可逆性阶段，认识到规则是同伴间共同约定、可以改变的，开始以是否公平来判断行为，标志着由他律道德向自律道德转化。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2576, 54, 56, 'single', 1.0, '学生小温爱给同学起侮辱性外号，班主任没有简单压服，而是先耐心听他想法，再讲明尊重他人的道理，引导他主动认错改正。该做法体现的德育原则是（　）', '[["A","知行统一原则"],["B","长善救失原则"],["C","疏导原则"],["D","严格要求原则"]]', '["C"]', '疏导原则要求德育循循善诱、以理服人，坚持正面教育，把疏通思想、讲明道理与因势利导结合起来，不能简单压制或体罚。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2577, 54, 57, 'single', 1.0, '老师鼓励学生把数学上学到的“认真审题、规范验算”的态度和方法用到物理、化学学习中。这种将一般原理、方法、态度迁移到具体学习中的迁移属于（　）', '[["A","一般迁移"],["B","具体迁移"],["C","负迁移"],["D","垂直迁移"]]', '["A"]', '一般迁移（非特殊迁移）指引得的一般原理、方法、策略或态度等迁移到其他具体情境中；具体迁移是把具体经验要素重新组合直接迁移。审题、验算的方法态度属一般迁移。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2578, 54, 58, 'single', 1.0, '班主任未经学生同意，在家长群公开张贴全班学生的心理测评结果和家庭收入情况。这一行为主要侵犯了学生的（　）', '[["A","隐私权和个人信息权益"],["B","受教育权"],["C","财产权"],["D","著作权"]]', '["A"]', '学生的心理测评结果、家庭收入等属于不愿为他人知晓的个人隐私和个人信息，未经本人或监护人同意不得公开披露，否则侵犯隐私权和个人信息权益。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2579, 54, 59, 'single', 1.0, '学生初学多位数除法时要边念叨步骤边算，练熟后能迅速、自动地完成，无需再逐句回想法则。按加里培林心智技能形成阶段，熟练后的状态处于（　）', '[["A","活动的定向阶段"],["B","物质活动或物质化活动阶段"],["C","出声的外部言语阶段"],["D","内部言语阶段"]]', '["D"]', '加里培林将心智技能形成分为活动定向、物质或物质化、出声外部言语、无声外部言语和内部言语等阶段；高度简缩、自动化、无需外显言语支持对应内部言语阶段。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2580, 54, 60, 'single', 1.0, '针对教师使用生成式人工智能，下列做法符合现行规范导向的是（　）', '[["A","让AI直接生成学生评语并原样发出"],["B","用AI辅助备课，但教师审核把关、对内容负责"],["C","把全班作业交给AI评分后不再复核"],["D","让学生用AI代写研究性学习报告"]]', '["B"]', '生成式人工智能只能作为教育教学辅助工具，教师应坚持育人主体地位，对AI生成内容进行甄别、审核和修正并承担相应责任，不能让其代替教师的教育判断与评价。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2581, 54, 61, 'single', 1.0, '小学生小宇上课与老师顶嘴，任课教师令其“马上出去，这学期别来上我的课”，并把他推出教室。该教师行为（　）', '[["A","合法，是维护课堂纪律的正当惩戒"],["B","合法，教师有处分学生的自由"],["C","不合法，侵犯受教育权，不得随意停课逐出"],["D","不合法，但因学生先有错，教师无需担责"]]', '["C"]', '受教育权是学生最基本的权利，教师不得以任何理由随意将学生停课、逐出教室或剥夺其上课权利。对违纪学生应依法依规实施教育惩戒，而不是剥夺其受教育机会。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2582, 54, 62, 'single', 1.0, '心理老师在辅导中不替学生做决定，也不简单评判“你不该这样想”，而是尊重学生感受，帮助其自己找到解决办法。这主要遵循了学校心理辅导的（　）', '[["A","保密性原则"],["B","整体性原则"],["C","预防与发展相结合原则"],["D","尊重理解学生与学生主体性原则"]]', '["D"]', '学校心理辅导强调尊重与理解学生，把学生当作辅导活动的主体，启发引导学生自助，而不是包办代替或简单说教评判。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2583, 54, 63, 'single', 1.0, '新教师问：“国家以纲要形式编订的、规定某门学科的课程性质、目标、内容要求和教学实施建议，并作为教材编写、教学、评价和考试命题直接依据的文件是什么？”应回答（　）', '[["A","课程标准"],["B","课程计划"],["C","教科书"],["D","教学参考书"]]', '["A"]', '课程标准是课程计划的分科展开，规定学科课程性质、目标、内容与实施建议，是教材编写、教学、评估和考试命题的依据，也是国家管理和评价课程的基础。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2584, 54, 64, 'single', 1.0, '新学期第一次政治学习，支教刚满一年的黎老师在笔记本上写下自己的职业规划：希望到国家“建成教育强国”那年，自己已成长为骨干。按《教育强国建设规划纲要（2024—2035年）》确定的时间节点，她这一目标大致应定在（　）', '[["A","2027年，该年即宣告建成教育强国"],["B","2035年，与基本实现社会主义现代化的时间节点一致"],["C","2049年，届时才开始部署教育强国建设"],["D","没有明确时间安排，只能建成科技强国后再谈教育"]]', '["B"]', '《教育强国建设规划纲要（2024—2035年）》明确，到2027年教育强国建设取得重要阶段性进展，到2035年建成教育强国，这一时间节点与我国基本实现社会主义现代化相同步。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2585, 54, 65, 'single', 1.0, '开学第一周，学校对新入职教师进行职业行为提醒。下列被明确指出不能做的行为是（　）', '[["A","课下为学习困难学生免费答疑"],["B","与同事集体备课、相互听课"],["C","组织、要求学生参加校内外有偿补课"],["D","主动学习并使用现代信息技术手段教学"]]', '["C"]', '《新时代中小学教师职业行为十项准则》要求坚守廉洁自律、规范从教行为，不得组织、要求学生参加校内外有偿补课，或与校外培训机构合作从中牟利；免费答疑、集体备课、学习信息技术均属正当从教行为。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2586, 54, 66, 'single', 1.0, '发散思维测试中，老师让学生尽量多列举“砖头”的用途。小琪答“盖房、砌墙、铺路”；小帆答“盖房、当哑铃练臂力、压住腌菜坛子、磨成粉做颜料”。小帆的答案更突出的创造性思维特征是（　）', '[["A","流畅性"],["B","独创性"],["C","聚合性"],["D","变通性（灵活性）"]]', '["D"]', '变通性（灵活性）指面对同一问题能跨类别提出不同类型的设想。小帆的答案跨建筑、健身、生活、材料多个类别，变通性强；流畅性强调单位时间内答案数量，独创性强调新奇独特。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2587, 54, 67, 'single', 1.0, '课改中某校把大量时间用于让学生“亲身试错”，几乎不讲系统知识，认为只有自己发现的才是真知识。专家指出，学生认识世界主要以掌握人类长期积累的科学文化知识为中介。专家强调的教学过程规律是（　）', '[["A","以间接经验为主、直接经验为基础相统一"],["B","学生获得经验只能靠亲身发现"],["C","学习应当完全排除书本知识"],["D","掌握知识与发展能力没有关系"]]', '["A"]', '学生认识客观世界以学习间接经验为主，这是认识的捷径；同时要以个人直接经验为基础，二者辩证统一。事事亲身试错既无必要也不经济，不能因此否定系统知识。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2588, 54, 68, 'single', 1.0, '小薇几次数学没考好后说“我天生就不是学数学的料，再努力也没用”，逐渐放弃学习。老师引导她把没考好归因于“方法不对、练习量不够”，并带她改进方法，她又重拾信心。老师的做法属于（　）', '[["A","强化训练"],["B","归因训练（可控因素归因引导）"],["C","消退训练"],["D","系统脱敏"]]', '["B"]', '韦纳归因理论认为，把失败稳定地归于能力不足等不可控因素易导致习得性无助；教师应引导学生归因于努力、学习方法等可控因素，通过归因训练增强坚持性和自我效能感。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2589, 54, 69, 'single', 1.0, '教师老唐9月1日收到学校作出的处分决定后不服，拟申请行政复议。除法律另有规定外，他一般应在知道该具体行政行为之日起多少日内提出（　）', '[["A","10日"],["B","15日"],["C","30日"],["D","60日"]]', '["D"]', '《行政复议法》规定，公民、法人或者其他组织认为具体行政行为侵犯其合法权益的，可以自知道该具体行政行为之日起六十日内提出行政复议申请，法律另有规定的除外。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2590, 54, 70, 'single', 1.0, '妹妹把同一块橡皮泥先搓成球、再压成饼，问哥哥“哪块橡皮泥多”。上小学的哥哥回答“一样多，只是形状变了”。按皮亚杰理论，哥哥已获得（　）', '[["A","客体永久性"],["B","自我中心性"],["C","守恒概念"],["D","假设演绎推理能力"]]', '["C"]', '具体运算阶段（约7—11岁）儿童获得守恒概念，能认识物体形态改变而质量、体积等保持不变，思维具有可逆性并逐渐去自我中心。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2591, 54, 71, 'single', 1.0, '下列做法中，属于国家政策明确要求的、为中小学教师减轻非教育教学负担的是（　）', '[["A","向学校摊派招商引资任务并纳入教师考核"],["B","要求教师反复填报与教育教学无关的各类表格"],["C","抽调教师长期参与征地拆迁等社会事务"],["D","清理精简督查检查评比考核和随意进校园的社会事务"]]', '["D"]', '国家持续推进减轻中小学教师非教育教学负担，要求清理精简各类督查检查评比考核事项、规范社会事务进校园，严禁随意抽调中小学教师承担与教育教学无关的事务。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2592, 54, 72, 'single', 1.0, '体育课上学生小甘突发晕厥，体育老师立即按预案处置、拨打120并通知家长，学校在送医、场地设施等方面均无过错；经查小甘系自身先天疾病导致。对该损害，学校（　）', '[["A","应承担全部责任"],["B","不承担责任"],["C","应由体育老师个人赔偿"],["D","应承担一半责任"]]', '["B"]', '学生有特异体质、特定疾病，学校不知道或难以知道，且突发后学校已及时采取救助措施、尽到教育管理职责的，学校无过错，依法不承担事故责任。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2593, 54, 73, 'single', 1.0, '看完成边英雄的报道，小峰内心涌起强烈的崇敬与感动，立志将来也要报效国家。这种“崇敬与感动”在品德心理结构中主要属于（　）', '[["A","道德认识"],["B","道德意志"],["C","道德情感"],["D","道德行为"]]', '["C"]', '品德由道德认识、道德情感、道德意志和道德行为构成。伴随道德认识产生的崇敬、爱慕、憎恨、羞耻等内心体验属于道德情感，它是道德认识转化为道德行为的催化剂。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2594, 54, 74, 'single', 1.0, '青年教师小裴因体罚学生、情节严重，被依法撤销教师资格。依据《教师资格条例》，关于该后果的说法，正确的是（　）', '[["A","自撤销之日起3年内不得重新申请认定教师资格"],["B","自撤销之日起5年内不得重新申请认定教师资格"],["C","自撤销之日起2年内不得重新申请认定教师资格"],["D","只要接受处分期满，当年即可重新申请认定"]]', '["B"]', '《教师资格条例》规定，被撤销教师资格的，自撤销之日起5年内不得重新申请认定教师资格；情节严重构成犯罪的，依法追究刑事责任。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2595, 54, 75, 'single', 1.0, '奥苏贝尔提倡在教师指导下，学习者以接受方式学习以结论形式呈现的材料，但强调新材料必须与原有观念建立非人为的、实质性的联系。这种学习称为（　）', '[["A","有意义接受学习"],["B","机械发现学习"],["C","试误学习"],["D","观察学习"]]', '["A"]', '奥苏贝尔按学习方式把学习分为接受学习与发现学习，按新旧知识关系分为机械学习与有意义学习，他倡导有意义的接受学习，主张利用先行组织者促进认知结构同化。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2596, 54, 76, 'single', 1.0, '新学期，施老师给自己定下“三新”计划：学一项新的课堂技术、读两本学科前沿专著、改掉一个旧教法。她这样做所体现的师德规范是（　）', '[["A","为人师表"],["B","终身学习"],["C","廉洁从教"],["D","依法执教"]]', '["B"]', '终身学习要求教师崇尚科学精神、树立终身学习理念，拓宽知识视野、更新知识结构，潜心钻研业务、不断提高专业素养和教育教学水平。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2597, 54, 77, 'single', 1.0, '大考临近，学生小芸出现持续紧张、心慌出汗、复习时脑子空白、一进考场就想逃避等反应。她最可能存在的心理问题是（　）', '[["A","抑郁症"],["B","强迫症"],["C","场所恐怖症"],["D","考试焦虑"]]', '["D"]', '考试焦虑是在一定的应试情境下激发，以紧张担忧为基本特征、伴生理唤醒增强和注意难以集中、回避等反应的情绪状态，可通过认知调整、放松训练和系统脱敏等干预。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2598, 54, 78, 'single', 1.0, '下列各项中，属于《教师法》规定的教师应当履行的义务的是（　）', '[["A","参加进修或者其他方式的培训"],["B","对学校教育教学、管理工作提出意见和建议"],["C","参与学校的民主管理"],["D","关心爱护全体学生，尊重学生人格"]]', '["D"]', '关心爱护全体学生、尊重学生人格，促进学生在品德、智力、体质等方面全面发展，是教师的法定义务；进修培训、提出意见建议、参与民主管理属于教师的权利。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2599, 54, 79, 'single', 1.0, '教研组长乔老师平时业务过硬，但近一年在办公室和家长群里多次发布、转发损害党中央权威的言论，造成不良影响。依据《新时代中小学教师职业行为十项准则》，乔老师的行为主要违反了（　）', '[["A","加强安全防范的要求"],["B","坚持廉洁自律的要求"],["C","坚定政治方向的要求"],["D","规范从教行为的要求"]]', '["C"]', '《新时代中小学教师职业行为十项准则》把“坚定政治方向”列为首要准则，要求教师不得在教育教学活动及其他场合发表、转发损害党中央权威、违背党的路线方针政策的言论。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2600, 54, 80, 'single', 1.0, '教育心理学复习课上，老师让学生按年龄先后排列皮亚杰提出的认知发展四个阶段。下列排列正确的是（　）', '[["A","具体运算 → 前运算 → 感知运动 → 形式运算"],["B","形式运算 → 具体运算 → 前运算 → 感知运动"],["C","前运算 → 感知运动 → 形式运算 → 具体运算"],["D","感知运动 → 前运算 → 具体运算 → 形式运算"]]', '["D"]', '皮亚杰认知发展四阶段依次为感知运动阶段（0—2岁）、前运算阶段（2—7岁）、具体运算阶段（7—11岁）、形式运算阶段（11岁以后）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2601, 54, 81, 'multi', 1.6, '某校推进科学教育，组织学生观察校园植物、做水质小实验、参与科普展讲解。下列做法体现科学性与思想性相统一原则的有（　）', '[["A","实验前讲清科学严谨、实事求是、不得编造数据的要求"],["B","借我国科学家攻坚克难的事例渗透科学精神与家国情怀"],["C","对学生观察中记录的错误数据一律批评、不许重新验证"],["D","让学生先背熟结论、不做实验"],["E","保证所讲知识科学准确，并结合知识引导学生形成正确价值观"]]', '["A","B","E"]', '科学性与思想性相统一原则要求保证教学内容和方法科学的科学正确，同时结合知识教学对学生进行思想品德和正确价值观教育。A项体现科学态度要求，B项借科学家事迹渗透思想教育，E项保证知识科学准确，均当选；C项违背实事求是的科学态度，D项违背科学性与探究精神，均排除。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2602, 54, 82, 'multi', 1.6, '为激发学生学习物理的动机，下列做法中属于培养与激发学生内部学习动机的有（　）', '[["A","创设有趣的实验情境，引发学生的好奇心和求知欲"],["B","帮助学生在物理学习中不断获得成功体验"],["C","使学生认识到学好物理对理解生活和科技发展的意义"],["D","以考分排名作为唯一激励手段，公开张榜"],["E","单纯以现金重奖考试名次靠前的学生"]]', '["A","B","C"]', '内部动机源于对学习活动本身的兴趣、求知欲和成就感。A项利用好奇心激发认知内驱力，B项通过成功体验增强自我效能感，C项引导学生认识学习本身的意义，均有助于激发内部动机；D项唯分数排名、E项单纯现金重奖都主要依靠外部诱因，且易导致学生把学习归因于外部奖励，反而侵蚀内部动机，均排除。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2603, 54, 83, 'multi', 1.6, '某校违法向学生收取“择校费”，且拒不改正。对此，教育行政等部门可依法采取的处理措施有（　）', '[["A","责令退还所收费用"],["B","对学校给予通报批评"],["C","对直接负责的主管人员和其他直接责任人员依法给予处分"],["D","吊销学校办学资格、没收全部校舍"],["E","对在校所有学生一律取消学籍"]]', '["A","B","C"]', '学校违反国家规定收取费用的，由县级人民政府教育行政部门责令退还所收费用，对学校、教师可依法给予通报批评等处理，对直接负责的主管人员和其他直接责任人员依法给予处分。D项随意没收全部校舍、E项株连式取消全体学生学籍均无法律依据，侵犯学生合法权益，均排除。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2604, 54, 84, 'multi', 1.6, '一年级老师在班级管理中运用行为主义原理塑造学生良好习惯。下列做法与原理对应正确的有（　）', '[["A","主动问好即贴小红花——正强化"],["B","按时完成作业可免一次值日——负强化"],["C","打人后取消本周评优资格——取消性惩罚"],["D","上课走神时给予额外罚抄作业——正强化"],["E","对良好行为长期不予任何回应，以使其自然巩固——消退"]]', '["A","B","C"]', '给予愉快刺激增加行为概率是正强化（A项小红花）；撤销厌恶刺激增加行为概率是负强化（B项免除值日）；取消愉快刺激以减少不良行为是取消性惩罚（C项取消评优资格）；D项罚抄是给予厌恶刺激，属呈现性惩罚而非正强化；E项消退是对以前被强化的行为不再强化，使其逐渐减少，并非巩固良好行为的手段，均排除。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2605, 54, 85, 'multi', 1.6, '中学生进入形式运算阶段后，思维较前运算、具体运算阶段出现明显发展。下列表现属于形式运算阶段特点的有（　）', '[["A","具有典型的自我中心性，认为外界万物都有生命"],["B","思维具有可逆与补偿能力"],["C","能进行抽象逻辑思维和命题间推理"],["D","思维活动完全局限于眼前可感知的具体事物"],["E","能进行假设—演绎推理"]]', '["B","C","E"]', '形式运算阶段（约11岁以后）个体能摆脱具体事物束缚，进行抽象逻辑思维、命题推理和假设一演绎推理，思维具有可逆、补偿和系统组合等特点。B项思维可逆与补偿、C项抽象逻辑思维与命题推理、E项假设一演绎推理均为形式运算阶段特征，当选。A项泛灵论和自我中心性主要属于前运算阶段，D项局限于具体可感事物是具体运算阶段之前的特征，均排除。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2606, 54, 86, 'multi', 1.6, '某校开展师德师风自查自纠，下列两位教师的做法被认定存在问题的有（　）', '[["A","邢老师多次在班上把成绩靠后的学生称作“脑子进水”“拖油瓶”"],["B","家长符某送来两千元购物卡请多关照，庞老师收下并把其子调到第一排"],["C","闵老师发现学生课堂上突发腹痛，立即送医并联系家长"],["D","郦老师利用假期参加骨干教师研修，更新教学设计"],["E","侯老师按课程标准备好每一节课并全批全改作业"]]', '["A","B"]', '十项准则要求关心爱护学生、坚守廉洁自律。A项用侮辱性语言辱骂、贬低学生，损害学生人格尊严，违背关心爱护学生的要求；B项收受家长大额财物并以礼调座，属于以职谋私，违背廉洁自律，两项均当选。C项及时救助突发疾病学生、D项参加研修提升专业水平、E项依标备课和批改作业，都是教师应有的正当行为，不选。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2607, 54, 87, 'multi', 1.6, '学生在校期间发生伤害事故，下列情形中，学校已依法履行相应职责、行为并不当而无须承担责任的有（　）', '[["A","对抗性篮球赛正常拼抢中，非因故意或重大过失造成同伴受伤"],["B","学生有特异体质但学校不知道也难以知道，发病后学校及时救助"],["C","放学离校后学生自行到校，翻越封闭围墙摔伤"],["D","教学楼楼梯扶手锈蚀断裂，学校长期未修致学生坠落"],["E","体育课上教师组织危险动作却不讲解安全要求、擅离职守"]]', '["A","B","C"]', 'A项属自甘风险，其他参加者非故意或非重大过失、学校尽到组织管理职责的不担责；B项特异体质学校不知道或难以知道且已及时救助的免责；C项学生在自行上学、放学、返校、离校途中，或在放学后、节假日等学校工作时间以外自行到校发生事故，学校无过错的不担责。D项设施不安全、E项教师未尽安全教育与管理职责，学校均存在过错，应承担责任，排除。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2608, 54, 88, 'multi', 1.6, '高三学生小钟复习时间紧，他给自己定下一套“备战规矩”：把最清醒的两个小时留给数学薄弱章节，手机锁进宿舍柜子只在午休查看，周末固定约同学在自习室互讲难题，累了就按计划休息十分钟再继续。上述做法中，属于资源管理策略的有（　）', '[["A","根据各科薄弱程度排定每周复习时间表"],["B","选择安静的自习环境，减少手机干扰"],["C","遇到难题先向老师、同学请教并讨论"],["D","用列提纲的方式梳理章节知识结构"],["E","对反复做错题的原因进行自我监控和归因"]]', '["A","B","C"]', '资源管理策略是辅助学生管理可用环境和资源的策略，包括时间管理（A项排时间表）、环境管理（B项选择学习环境）、学业求助（C项向师生请教）和努力管理等。D项列提纲属于认知策略中的组织策略，E项自我监控、归因属于元认知策略，均不属于资源管理策略，排除。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2609, 54, 89, 'multi', 1.6, '为维护未成年学生的人格尊严，下列做法为法律所禁止的有（　）', '[["A","对违纪学生实施体罚或变相体罚"],["B","依法对学生进行处分并告知其申辩权利"],["C","私拆学生信件、公开其不愿公开的个人信息"],["D","对违纪学生进行必要的批评教育和教育惩戒"],["E","当众辱骂、讽刺、歧视学生"]]', '["A","C","E"]', '法律保护未成年学生的人格尊严，禁止对未成年人实施体罚、变相体罚以及其他侮辱人格尊严的行为，不得辱骂、歧视，不得侵犯隐私和个人信息。A项体罚或变相体罚、C项私拆信件公开个人信息、E项当众辱骂讽刺歧视学生，均为法律所禁止，当选。B项依法对学生进行处分并告知其申辩权利、D项符合规定的批评教育和教育惩戒，都是学校依法管理教育的正当行为，不侵犯人格尊严，排除。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2610, 54, 90, 'multi', 1.6, '青年教师读书会上，大家围绕维果斯基的理论讨论教学。下列说法正确的有（　）', '[["A","合作学习、支架式教学有助于学生跨越最近发展区"],["B","教学可以适当走在发展的前面，帮助学生达到在成人或更有能力同伴帮助下可能达到的水平"],["C","儿童的发展只能依靠自身独立成熟，成人和同伴的帮助没有意义"],["D","教学只能被动跟在发展后面，不能对发展起促进作用"],["E","语言和符号只是表达工具，与高级心理机能的形成无关"]]', '["A","B"]', '维果斯基认为教学应着眼最近发展区、适当走在发展前面，学生在成人或更有能力同伴帮助下可能达到的水平与独立完成水平之间的区域就是最近发展区，合作学习、支架式教学有助于跨越这一区域，故A、B项正确。C项否认社会互动和他人帮助，D项把发展与教学割裂、否认教学对发展的促进，E项否认语言符号在高级心理机能形成中的中介作用，均与该理论不符，排除。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2612, 56, 1, 'judge', 0.6, '妞妞觉得自己走月亮也跟着走，还把布娃娃当活人。她处在思维具有自我中心特征的阶段。', '[["A","正确"],["B","错误"]]', '["A"]', '幼儿认为月亮跟着自己走、把布娃娃当活人（泛灵论），是皮亚杰所说前运算阶段自我中心思维的典型表现。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2613, 56, 2, 'judge', 0.6, '活动前老师总先摇铃，后来铃声一响孩子就停止吵闹望老师。这与巴甫洛夫的信号学习机制一致。', '[["A","正确"],["B","错误"]]', '["A"]', '铃声反复作为活动开始的信号出现，最终铃声单独引起儿童的定向反应，属于经典性条件作用中的信号学习，与巴甫洛夫的理论一致。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2614, 56, 3, 'judge', 0.6, '妈妈约定：小卓先读完当天英语，才可以去做他喜欢的航模。这是用高频活动强化低频活动。', '[["A","正确"],["B","错误"]]', '["A"]', '用学生喜爱的高频活动（做航模）作为完成低频活动（读英语）的强化物，符合普雷马克原理（祖母法则）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2615, 56, 4, 'judge', 0.6, '看到同桌积极发言被表扬，小航也开始举手。这种因他人受奖而改变行为的现象属于自我强化。', '[["A","正确"],["B","错误"]]', '["B"]', '看到榜样（同桌）受表扬而模仿其行为，属于班杜拉所说的替代强化：自我强化是个体依据自定标准对自己进行奖励。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2616, 56, 5, 'judge', 0.6, '分进快班后小蕾自认“聪明”，不用功也比人强，学习劲头反降。这可用习得性无助解释。', '[["A","正确"],["B","错误"]]', '["B"]', '外部标签（评价）反而削弱了内在学习动力，应用德西效应（外部奖赏削弱内部动机）解释；习得性无助是多次失败后产生的无能为力感，与题干情境不符。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2617, 56, 6, 'judge', 0.6, '几次大考失利后，小蕊认定“再努力也没用”，简单题也不做。这是习得性无助。', '[["A","正确"],["B","错误"]]', '["A"]', '多次失败后形成“无论怎样努力都无法改变结果”的信念，进而放弃尝试，正是塞利格曼提出的习得性无助。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2618, 56, 7, 'judge', 0.6, '会骑自行车后，阿哲学骑三轮车总用保持两轮平衡的方式，结果频频跑偏。这是逆向迁移。', '[["A","正确"],["B","错误"]]', '["B"]', '已掌握的骑自行车技能对其后学习骑三轮车产生干扰，是先前学习对后继学习的消极影响，属于顺向负迁移；逆向迁移指后学习对先学习的影响，方向被颠倒。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2619, 56, 8, 'judge', 0.6, '小哈把按词根词缀归类的方法，用到按区域特征整理地理知识上。这属于一般迁移。', '[["A","正确"],["B","错误"]]', '["A"]', '把归类、组织等一般方法、策略迁移到另一类学习内容上，属于一般迁移（普遍迁移）而非局限于具体经验的具体迁移。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2620, 56, 9, 'judge', 0.6, '小卓练字先进步很快，随后越写越差，老师说这是无法逾越的阶段。老师的说法正确。', '[["A","正确"],["B","错误"]]', '["B"]', '练习中期出现进步暂时停顿属高原现象，但高原现象并非不可逾越，改进方法、调整状态后仍可继续提高，“无法逾越”的说法错误。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2621, 56, 10, 'judge', 0.6, '模考前，小宇计划好各题型用时，卡壳先跳过。这属于资源管理策略。', '[["A","正确"],["B","错误"]]', '["A"]', '根据考试任务预先规划、合理分配时间并管理自己的学习努力，属于资源管理策略中的时间管理与学习努力管理策略。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2622, 56, 11, 'judge', 0.6, '秦老师坚信调皮学生将来也可能有出息，常用信任目光鼓励后进生，多名学生明显转变。这是教师期望效应。', '[["A","正确"],["B","错误"]]', '["A"]', '教师对学生抱有积极期望并通过态度、行为传递给学生，促使学生朝期望方向发展，属于罗森塔尔（教师期望）效应。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2623, 56, 12, 'judge', 0.6, '历史课白老师严格按时间脉络由远及近编排，从不跳章。这符合身心发展的阶段性规律。', '[["A","正确"],["B","错误"]]', '["B"]', '由远及近、由浅入深、不凌节而施地安排教学内容，体现的是循序渐进原则所依据的个体身心发展顺序性规律，而非不同年龄段特征不同的阶段性规律。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2624, 56, 13, 'judge', 0.6, '温老师认为教育起源于人们共同劳动、交往中传递生产生活经验的需要。这属于心理起源说。', '[["A","正确"],["B","错误"]]', '["B"]', '认为教育起源于人类劳动和社会交往中经验传递的需要，属于劳动起源说（马克思主义观点）；心理起源说认为教育起源于儿童对成人的无意识模仿。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2625, 56, 14, 'judge', 0.6, '某校为提高升学率取消全部劳动课和实践活动，让学生集中刷题。这符合全面发展的培养要求。', '[["A","正确"],["B","错误"]]', '["B"]', '我国教育目的要求坚持教育与生产劳动、社会实践相结合，促进学生全面发展；取消劳动课程、片面追求升学率违背了这一要求。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2626, 56, 15, 'judge', 0.6, '裴老师把走廊布置成名人名言墙，让学生在潜移默化中受熏陶。这是一种正式的学科课程。', '[["A","正确"],["B","错误"]]', '["B"]', '名人名言墙通过校园环境潜移默化地影响学生，属于隐性课程（潜在课程），并非以学科内容为中心、列入课表系统传授的正式学科课程。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2627, 56, 16, 'judge', 0.6, '甘老师要求学生做到的自己先做到，用言行带动全班。这体现了榜样示范法身教重于言教的道理。', '[["A","正确"],["B","错误"]]', '["A"]', '教师以身作则、以自身高尚行为作学生表率，是榜样示范法（身教）的体现，符合“其身正，不令而行”的教育要求。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2628, 56, 17, 'judge', 0.6, '舒老师认为省政府规章与教育部规章效力相同，冲突时任选其一适用。', '[["A","正确"],["B","错误"]]', '["B"]', '部门规章与地方政府规章具有同等效力，在各自权限范围内施行；二者规定不一致时应依法由国务院裁决，不能任选适用。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2629, 56, 18, 'judge', 0.6, '学校要求教师无偿占用周末带队参加商业庆典，教师有权拒绝。', '[["A","正确"],["B","错误"]]', '["A"]', '依法保障教师教育教学自主权，任何组织和个人不得强制要求教师从事与教育教学无关的活动，占用休息时间承担商业庆典属违规摊派，教师有权拒绝。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2630, 56, 19, 'judge', 0.6, '初三学生小袁多次严重违纪，班主任劝其退学，校方也停了他的课。学校做法于法有据。', '[["A","正确"],["B","错误"]]', '["B"]', '义务教育阶段不得开除未成年学生，也不得劝退、责令退学或随意停课剥夺其受教育机会，对违纪学生应批评教育、依规惩戒。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2631, 56, 20, 'judge', 0.6, '课间两生追逐，教师甘某已制止，学生仍跑跳致一人摔伤，甘某不应担责。', '[["A","正确"],["B","错误"]]', '["A"]', '教师发现危险行为后已及时口头制止，学生不听劝阻继续追逐致害，学校、教师已尽到教育、管理职责，对损害没有过错，依法不承担赔偿责任。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2632, 56, 21, 'judge', 0.6, '四年级学生体育课受伤索赔，应由家长举证学校有过错，学校不须先自证无过错。', '[["A","正确"],["B","错误"]]', '["A"]', '四年级学生一般已年满8周岁，属限制民事行为能力人，在校受到人身损害适用过错责任原则，由受害方举证学校未尽教育管理职责，不适用过错推定。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2633, 56, 22, 'judge', 0.6, '学生上课睡觉，老师令其后排站两节课并当众挖苦。这属正常惩戒，不侵权。', '[["A","正确"],["B","错误"]]', '["B"]', '罚站一节课可作为教育惩戒，但长时间罚站并当众挖苦侮辱，超出必要限度，属于变相体罚和侮辱人格尊严，侵犯学生人身权，并非合法惩戒。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2634, 56, 23, 'judge', 0.6, '教师对学校处分不服，可向教育行政部门申诉，教育行政部门应在三十日内处理。', '[["A","正确"],["B","错误"]]', '["A"]', '《教师法》规定，教师对学校或其他教育机构作出的处理不服的，可以向教育行政部门提出申诉，教育行政部门应当在接到申诉的三十日内作出处理。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2635, 56, 24, 'judge', 0.6, '有人说教师是“铁饭碗”，签了聘用合同，学校在任何情况下都不能解聘。', '[["A","正确"],["B","错误"]]', '["B"]', '教师实行聘任制，教师有体罚学生经教育不改、故意不完成教学任务造成损失、品行不良侮辱学生等法定情形的，学校可依法给予行政处分或解聘。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2636, 56, 25, 'judge', 0.6, '围墙开裂，学校只在台账记“下学期再修”，不警示不隔离，砸伤学生后主张免责。', '[["A","正确"],["B","错误"]]', '["B"]', '校舍存在明显安全隐患，学校未及时维修、未设置警示或采取隔离措施，属于未尽管理职责，不能仅凭“已列入维修计划”免责，应依法承担相应责任。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2637, 56, 26, 'judge', 0.6, '快退休的向老师主动报名AI助教工作坊，回校后还把所学做成微课分享给青年教师。这符合终身学习规范。', '[["A","正确"],["B","错误"]]', '["A"]', '临近退休仍主动学习新技术、钻研新方法并带动同事共同提高，体现了崇尚科学精神、树立终身学习理念、不断更新知识结构和教育教学方法的要求。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2638, 56, 27, 'judge', 0.6, '家长多次发红包请惠老师给孩子调换“黄金座位”，惠老师推辞不过便收下。这不违反师德。', '[["A","正确"],["B","错误"]]', '["B"]', '利用职务之便收受家长财物、为个别学生谋取特殊关照，违背为人师表、坚守廉洁自律（廉洁从教）的要求，必须坚决拒绝。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2639, 56, 28, 'judge', 0.6, '邢老师把关注点从“我讲了多少”转到“学生学会了多少”，围绕学生的学设计课堂。这体现以学习者为中心。', '[["A","正确"],["B","错误"]]', '["A"]', '从关注教师的“教”转向关注学生的“学”，教学从“教育者为中心”转向“学习者为中心”，正是新课改教学观转变的体现。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2640, 56, 29, 'judge', 0.6, '卓老师说：“我把知识点讲到位就行，学生品德好不好主要是家长和社会的事。”这符合教书育人要求。', '[["A","正确"],["B","错误"]]', '["B"]', '教书育人要求教师遵循教育规律、实施素质教育，既教书又育人，德育是教师的重要职责，不能把学生品德培养完全推给家庭和社会。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2641, 56, 30, 'judge', 0.6, '嵇老师常对质疑的学生说“教学相长，你也帮老师把问题想透了”，并据此修正讲法。', '[["A","正确"],["B","错误"]]', '["A"]', '教师在与学生交流中受到启发、改进教学，学生也在质疑探究中获得发展，体现了教学相长、师生平等互动共同成长的理念。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2642, 56, 31, 'single', 1.0, '新教师观摩老教师的课时发现：同一篇课文，不同班级、不同年份的上法都不一样，教师要随课堂生成不断调整；但“借助语言文字培养学生理解与表达能力”这一追求始终未变。这主要说明教育具有（　）', '[["A","永恒的育人属性与具体历史形态相统一的特点"],["B","可以完全脱离社会独立存在的特点"],["C","与人类社会共始终、一成不变的特点"],["D","只随政治制度变化而变化的特点"]]', '["A"]', '教育既有永恒的育人属性（传承经验、培养人），又在不同社会历史条件下表现出具体形态，二者统一。“育人追求始终未变”与“具体上法随情境而变”正体现这一特点。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2643, 56, 32, 'single', 1.0, '某市推进产业升级后，财政对教育投入逐年增加，学校新建了人工智能实验室，家长也更愿意为孩子的教育付费；同时产业发展对劳动者素质提出新要求，倒逼学校调整课程。这一系列变化主要说明（　）', '[["A","教育只能被动适应，对生产力毫无作用"],["B","生产力发展制约教育发展的规模、速度与内容"],["C","教育决定生产力的发展方向"],["D","政治制度决定教育的领导权"]]', '["B"]', '生产力发展水平制约教育发展的规模、速度，影响人才培养规格、课程设置和教学内容，并为教育提供物质条件。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2644, 56, 33, 'single', 1.0, '在学校“为谁培养人”的讨论中，党支部书记指出：课程开设、教材审定、重要岗位干部任免都由国家掌握，培养什么人首先是个政治方向问题。这强调的是（　）', '[["A","人口决定教育规模"],["B","文化决定教育内容"],["C","政治经济制度决定教育的领导权和受教育权"],["D","生产力决定教育发展速度"]]', '["C"]', '政治经济制度决定教育的领导权、受教育权、教育目的和思想品德教育内容。掌握课程开设、教材审定、干部任免等，正是掌握教育领导权的表现。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2645, 56, 34, 'single', 1.0, '新生入学第一周，乔老师发现有的孩子擅长语言表达，有的动手能力突出，有的则安静专注、长于观察，于是为不同孩子设计了分层任务卡。乔老师遵循的身心发展规律是（　）', '[["A","不均衡性"],["B","连续性"],["C","阶段性"],["D","个别差异性"]]', '["D"]', '不同儿童在语言表达、动手操作、观察专注等方面各有所长，体现了个体身心发展的个别差异性，教育应因材施教、分层设计任务。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2646, 56, 35, 'single', 1.0, '老校长在校训讨论中强调：“办学就是为社会培养合格建设者，个人的志愿应当服从国家和社会的需要。”这种教育目的价值取向更接近（　）', '[["A","社会本位论"],["B","文化本位论"],["C","生活本位论"],["D","个人本位论"]]', '["A"]', '社会本位论主张教育目的应根据社会需要确定，个人发展应服从社会需要，强调培养合格的社会成员。“个人志趣应服从国家和社会需要”正是这一取向。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2647, 56, 36, 'single', 1.0, '科技节上，班主任发现不少学生只顾备赛拿奖，忽视体育锻炼和班级公益劳动，便提醒大家：“先要做完整发展的人，再做某一方面冒尖的人；哪一育都不能替代另一育。”班主任强调的是（　）', '[["A","五育各有独立任务，可以彼此替代"],["B","五育相互联系、相互促进，应坚持全面发展"],["C","只要身体好，其他方面自然会好"],["D","智育最重要，其他各育只是陪衬"]]', '["B"]', '全面发展教育由德、智、体、美、劳五育构成，五育各有独特作用、不可相互替代，又相互联系、相互促进，统一于学生发展之中，应坚持五育并举。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2648, 56, 37, 'single', 1.0, '一位退休教师收到三十年前学生的来信，信中说：正是当年老师一句“你观察事物很仔细”的鼓励，让他日后选择了科研道路，受益终身。这最能说明教师劳动（　）', '[["A","每节课都必须当堂完成全部教育任务"],["B","培养学生主要依靠标准化流程"],["C","影响显现的周期长，育人效果具有滞后性"],["D","各科教师应按同一模式工作"]]', '["C"]', '教师劳动具有长期性（迟效性、滞后性），人才培养周期长，教师对学生的影响往往要经过很长时间才显现并持续终生。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2649, 56, 38, 'single', 1.0, '课程开发研讨中，温老师主张：“课程应围绕学生的兴趣和经验来组织，让学生在亲身活动中获得直接体验，而不是只按学科逻辑灌输现成结论。”这一主张更接近（　）', '[["A","永恒主义课程论"],["B","学科中心课程论"],["C","社会中心课程论"],["D","学生中心（活动）课程论"]]', '["D"]', '学生中心（活动）课程论以杜威等为代表，主张课程以儿童兴趣、需要和活动为中心，重视直接经验。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2650, 56, 39, 'single', 1.0, '备课组讨论教学难度时，柳老师说：“要让学生跳一跳，够得着”，太浅了没劲，太难了又学不会。”这体现的教学原则是（　）', '[["A","量力性（可接受性）原则"],["B","因材施教原则"],["C","直观性原则"],["D","巩固性原则"]]', '["A"]', '量力性原则（可接受性原则）要求教学适合学生发展水平，既不要过易也不要过难，使学生经过努力能够掌握，即“跳一跳，够得着”。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2651, 56, 40, 'single', 1.0, '某山区教学点只有一位教师、三个年级十余名学生。同一节课里，教师轮流给不同年级布置任务、分别讲解和辅导。这种教学组织形式是（　）', '[["A","设计教学法"],["B","复式教学"],["C","道尔顿制"],["D","分组教学"]]', '["B"]', '复式教学是把两个或两个以上不同年级的学生编在一个教室里，由一位教师在同一节课内分别对不同年级学生交替进行教学的组织形式，常见于学生少、师资少的偏远地区。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2652, 56, 41, 'single', 1.0, '单元教学中，盛老师每节课用三分钟小测、巡视观察学生练习情况，并据此调整第二天的讲法，而不是只等期末排名次。盛老师主要运用的评价是（　）', '[["A","终结性评价"],["B","相对性评价"],["C","形成性评价"],["D","诊断性评价"]]', '["C"]', '形成性评价是在教学过程中为改进和完善教学活动而进行的、对学生学习过程与结果的评价，如课堂小测、巡视观察并据此调整教学。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2653, 56, 42, 'single', 1.0, '后进生小宇爱惹是生非，但组织能力强、重义气。班主任让他担任“路队纪律监督员”，把他的长处用在正地方，一学期后他的违纪明显减少。班主任贯彻的德育原则是（　）', '[["A","严格要求与尊重信任相结合"],["B","正面教育与纪律约束相结合"],["C","知行统一原则"],["D","长善救失原则"]]', '["D"]', '长善救失原则要求教育者善于依靠、发扬学生自身的积极因素（组织能力强、重义气），调动其自我教育的积极性，克服消极因素（违纪）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2654, 56, 43, 'single', 1.0, '邢老师发现自己班的课堂讨论总是“优生一言堂”，便和教研组反复试验“轮流主持十组间互评”，边实施边修改，一学期后形成了成熟的合作讨论流程。这种研究方式属于（　）', '[["A","行动研究法"],["B","教育测量法"],["C","实验室实验法"],["D","历史研究法"]]', '["A"]', '行动研究法是教育实践工作者（教师）在真实教育教学情境中，为解决实际问题，按“计划—行动—观察—反思”循环开展、边实践边改进的研究方式。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2655, 56, 44, 'single', 1.0, '新教师小贺给班里基础最弱的学生补课时，先摸清他“独立能做到哪一步”，再在他快要够不着时搭一把“脚手架”，帮其完成原本做不出的任务。小贺的做法依据的理论是（　）', '[["A","应让学生完全自学以激发出本能"],["B","教学应着眼于学生的潜在发展水平，在最近发展区内提供支架"],["C","应按统一标准要求所有学生齐步走"],["D","发展只能等待生理成熟，教育应耐心等待"]]', '["B"]', '维果斯基提出最近发展区，指儿童独立解决问题的现有发展水平与在成人指导下解决问题的潜在发展水平之间的差距；教学应走在发展前面，在最近发展区内提供“支架”帮助学生。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2656, 56, 45, 'single', 1.0, '小学阶段的小川特别在意“老师有没有表扬我”“我在小组里有没有用”，总认真完成任务来证明自己能干。按埃里克森的人格发展阶段理论，这一阶段儿童的主要发展任务是获得（　）', '[["A","信任感"],["B","自主感"],["C","勤奋感"],["D","自我同一性"]]', '["C"]', '埃里克森认为6—12岁（小学阶段）处于勤奋感对自卑感阶段，儿童通过完成任务、获得肯定来体验能力与勤奋，特别在意教师和同伴是否认可自己“有用、能干”。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2657, 56, 46, 'single', 1.0, '做同样的阅读题，小唐喜欢独立钻研、不易受周围讨论干扰，小沈则爱和大家一起讨论、在互动中理清思路。这两种偏好主要反映了学生的（　）', '[["A","气质类型差异"],["B","品德水平差异"],["C","智力高低差异"],["D","认知风格差异"]]', '["D"]', '场独立型学生倾向独立思考、不易受外界暗示，场依存型学生倾向在与他人交往讨论中学习；二者属于认知风格（认知方式）差异，无好坏之分。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2658, 56, 47, 'single', 1.0, '两位同龄教师，一位学新教学软件明显更快、反应灵敏；另一位凭借多年积累的教学经验，处理课堂突发事件更老到、判断更准。后者占明显优势的主要是（　）', '[["A","晶体智力"],["B","模仿能力"],["C","流体智力"],["D","创造能力"]]', '["A"]', '卡特尔把智力分为流体智力和晶体智力：流体智力依赖先天生理素质，成年后随年龄增长而下降；晶体智力是通过后天学习和经验获得的语言、知识、判断力，随经验积累而增长。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2659, 56, 48, 'single', 1.0, '体育老师临时宣布明天进行事先没有通知的仰卧起坐达标测试，学生既无心理准备也没练习，成绩普遍不理想，还产生了畏难情绪。这主要违背了桑代克学习规律中的（　）', '[["A","效果律"],["B","准备律"],["C","练习律"],["D","近因律"]]', '["B"]', '桑代克提出准备律、练习律、效果律。准备律指学习者在学习开始时的预备定势，有准备且给以活动则满意，无准备而强制活动或有准备而不活动都会烦恼。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2660, 56, 49, 'single', 1.0, '经过训练，导盲犬能辨别十字路口不同节奏的提示音并作出不同反应；学生在阅读中也逐渐能分清“踌躇”“踟蹰”等形近近义词的不同用法。这类现象属于（　）', '[["A","消退"],["B","高级条件作用"],["C","刺激分化"],["D","刺激泛化"]]', '["C"]', '刺激分化是指通过选择性强化和消退，使有机体学会对条件刺激和与条件刺激相类似的刺激作出不同反应，即辨别相似刺激。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2661, 56, 50, 'single', 1.0, '生物老师先讲清“细胞”的概念，再依次讲“组织”“器官”“系统”，引导学生把新概念与已掌握的旧概念建立起非人为的、实质性的联系。按奥苏贝尔的理论，这种学习属于（　）', '[["A","观察学习"],["B","机械的发现学习"],["C","试误学习"],["D","有意义的接受学习"]]', '["D"]', '奥苏贝尔有意义学习的实质是符号所代表的新知识与学习者认知结构中已有的适当观念建立非人为的、实质性的联系；通过教师系统讲授获得概念属于有意义的接受学习。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2662, 56, 51, 'single', 1.0, '物理课上，舒老师不直接给公式，而是提供器材和问题，让学生自己测量数据、寻找变量关系，最后归纳出结论。这种教学方式集中体现了（　）', '[["A","布鲁纳倡导的发现学习"],["B","斯金纳设计的程序教学"],["C","巴甫洛夫的条件反射训练"],["D","奥苏贝尔主张的接受学习"]]', '["A"]', '布鲁纳提倡认知—发现学习，主张让学生独立思考、主动发现知识的结构和原理，教师提供材料和问题情境引导学生自己得出结论。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2663, 56, 52, 'single', 1.0, '心理咨询室里，文老师不急着给来访学生建议，而是真诚倾听、无条件接纳其感受，相信学生有自我成长的力量，靠安全信任的氛围促进学生自我理解。这一助人理念集中体现了（　）', '[["A","巴甫洛夫的条件反射训练"],["B","罗杰斯的来访者中心（非指导性）思想"],["C","斯金纳的行为矫正技术"],["D","艾利斯的理性情绪疗法"]]', '["B"]', '罗杰斯的来访者中心（非指导性）疗法/教学强调真诚一致、无条件积极关注和共情理解，相信人有自我实现的潜能，教育者主要营造安全信任的氛围而非直接灌输或矫正。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2664, 56, 53, 'single', 1.0, '走迷宫实验中，前期没有食物奖励的一组小白鼠，出错次数下降不明显；可一旦在终点放上食物，它们的成绩立刻追上甚至超过一直有奖的组。这一现象对教学的主要启示是（　）', '[["A","学习成绩必须与即时的物质奖励严格挂钩"],["B","没有奖励的学习毫无价值，应取消一切无强化练习"],["C","探索过程本身就可能带来学习，不必每一步都立刻给外部奖励"],["D","迷宫式训练不适合迁移到任何学科"]]', '["C"]', '托尔曼的潜伏学习实验表明，白鼠在无奖励期间也在探索、形成认知地图，学习发生了但未在行为上表现，一旦有强化便迅速表现出来，说明强化不是学习产生的必要条件。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2665, 56, 54, 'single', 1.0, '大考越近，小越越看不进书，连简单默写都手心出汗、频频卡壳。老师告诉她：面对难题要把唤起水平调到适中偏低，简单熟练的任务才适合较高的紧张度。老师运用的规律是（　）', '[["A","归因理论"],["B","成就动机理论"],["C","自我效能感理论"],["D","耶克斯一多德森定律"]]', '["D"]', '耶克斯一多德森定律指出动机（唤醒）的最佳水平随任务性质不同而不同：较复杂困难的任务，最佳动机水平应适当偏低；较简单熟练的任务，最佳水平可较高；总体呈倒U型关系。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2666, 56, 55, 'single', 1.0, '面对难度适中的学科竞赛，小健倾向选择“拼一把、约有五成把握”的项目；小安却只报“几乎不可能获奖”或“闭着眼都能赢”的项目。按阿特金森的理论，二人可被区分为（　）', '[["A","追求成功者与避免失败者"],["B","内控型与外控型"],["C","场独立型与场依存型"],["D","高焦虑者与低焦虑者"]]', '["A"]', '阿特金森成就动机理论把个体分为力求成功者和避免失败者：前者倾向选择成功概率约 50%、有一定挑战的任务；后者因害怕失败，倾向选择极难或极易的任务以避免“显得无能”。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2667, 56, 56, 'single', 1.0, '小柯把考试失利归因为“我根本就不是读书的料”，从此越来越自卑、不愿努力。班主任引导他把失利主要归因为“复习方法和努力程度可以改进”，他的成绩与信心逐步回升。班主任主要是在改变学生的（　）', '[["A","气质类型"],["B","归因方式"],["C","认知风格"],["D","生理成熟水平"]]', '["B"]', '韦纳归因理论把成败归因于能力、努力、任务难度、运气等维度，把失败归于内部、稳定、不可控的“能力低”会降低动机，归于内部、不稳定、可控的“努力”和可改变的方法则有助于激发动机。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2668, 56, 57, 'single', 1.0, '小茹更在意“我有没有真正理解、有没有比过去进步”，遇到难题把它当成锻炼机会；同桌却最担心“考差了被人看不起”，一遇难题就回避。小茹的目标定向更偏向（　）', '[["A","成绩—回避目标"],["B","外部目标"],["C","掌握（学习）目标"],["D","附属目标"]]', '["C"]', '德韦克等的目标定向理论区分掌握目标（学习目标，关注能力增长、理解与进步，把困难视为挑战）和成绩目标（关注显得聪明或避免显得愚笨）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2669, 56, 58, 'single', 1.0, '学会了三角形面积公式后，学生再推导梯形面积公式时更加顺畅；先掌握“三角形”概念也有助于理解“等腰三角形”。这两类学习之间的迁移分别属于（　）', '[["A","一般迁移与具体迁移"],["B","逆向迁移与水平迁移"],["C","正迁移与负迁移"],["D","水平迁移与垂直迁移"]]', '["D"]', '水平迁移（横向迁移）指同一抽象概括水平的经验之间的影响，如三角形面积公式到梯形面积公式；垂直迁移（纵向迁移）指不同抽象概括水平的经验之间的影响，如由“三角形”到“等腰三角形”的下位概念学习。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2670, 56, 59, 'single', 1.0, '学习《岳阳楼记》时，小岚在通读的基础上逐段概括大意、列结构图，又把“先天下之忧而忧”与作者生平背景联系起来理解。她主要运用了（　）', '[["A","精加工与组织策略"],["B","时间管理策略"],["C","复述策略"],["D","元认知策略"]]', '["A"]', '精加工策略是把新信息与已有知识联系起来增加意义（联系背景、作解释），组织策略是按内在关系整合构建结构（列提纲、结构图、归类）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2671, 56, 60, 'single', 1.0, '做数学综合题时，小航知道自己几何证明是强项、概率计算是弱项，会主动多检查概率题，并在考试时合理分配时间。这种对自身认知特点的认识与计划安排属于（　）', '[["A","具体的复述策略"],["B","元认知知识与元认知监控"],["C","问题表征能力"],["D","资源管理中的努力管理"]]', '["B"]', '元认知是对认知的认知，包括元认知知识（知道自己擅长什么、薄弱在哪）、元认知体验和元认知监控调节（计划、监视、调整时间与检查）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2672, 56, 61, 'single', 1.0, '手工课上，老师让学生想办法找出一张圆形纸片的中心点，小卓拿直尺在圆内横七竖八地量，越量越乱；同桌提醒他先把纸片对折两次，他立刻找到了圆心。小卓此前受阻主要是因为（　）', '[["A","功能固着"],["B","动机水平过高"],["C","对问题情境的表征方式不当"],["D","原型启发不足"]]', '["C"]', '问题解决受个体对问题情境表征方式的影响。小卓一直用尺子在圆内无序测量，说明他没有建立“圆心是两条直径交点、对折可得直径”的恰当表征。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2673, 56, 62, 'single', 1.0, '头脑风暴课上，多数同学的设想都围绕“给杯子加把手、换材质”打转，小越却一口气提出可折叠杯、自带净水功能杯、可种植绿植的纪念杯等多种不同类别的点子。这突出体现了其思维的（　）', '[["A","流畅性"],["B","独创性"],["C","敏感性"],["D","变通性（灵活性）"]]', '["D"]', '发散思维具有流畅性（数量多少）、变通性/灵活性（类别多少、能否触类旁通）、独创性（新颖独特）三个主要特征。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2674, 56, 63, 'single', 1.0, '小安每次当众发言前都极度紧张，老师先陪她练习在空教室讲话，再到三五人小组中发言，最后在全班面前讲话；每当她放松下来就给予肯定，逐级消除恐惧。老师采用的方法是（　）', '[["A","系统脱敏法"],["B","强化法"],["C","来访者中心疗法"],["D","认知失调法"]]', '["A"]', '系统脱敏法由沃尔帕提出，通过建立焦虑等级，让来访者在放松状态下逐级接触焦虑刺激，逐步消除恐惧和焦虑。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2675, 56, 64, 'single', 1.0, '一次考试失利后，小宁反复想“我必须次次都考好，一次失败就说明我一无是处，所有人都会瞧不起我”，情绪越来越低落。心理老师帮她识别并驳斥这些绝对化、灾难化的信念。老师运用的是（　）', '[["A","代币奖励法"],["B","理性—情绪疗法"],["C","集体心理辅导"],["D","肌肉放松法"]]', '["B"]', '艾利斯理性一情绪疗法（ABC理论）认为情绪困扰不是由事件本身而是由个体对事件的不合理信念引起，治疗关键是识别并驳斥不合理信念、建立合理信念。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2676, 56, 65, 'single', 1.0, '入职三年的应老师备课时最常琢磨：“这届学生和上届有什么不同？怎样设计活动他们才真正参与得进来？”相比刚入职时只担心“自己能不能把课讲完”，她的关注重心已转向（　）', '[["A","关注情境中的自我形象"],["B","关注生存"],["C","关注学生"],["D","关注工资待遇"]]', '["C"]', '福勒和布朗把教师成长分为关注生存、关注情境、关注学生三个阶段。新教师首先关注自己能否生存，随后关注教学情境，成熟教师更多关注学生差异和学习需求。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2677, 56, 66, 'single', 1.0, '教师办公室里，舒老师发现教育部规章与某省政府规章对同一事项规定不一致，几位教师各执一词。关于二者关系，下列说法正确的是（　）', '[["A","以颁布时间先后决定适用哪一个"],["B","地方政府规章在本地效力高于部门规章"],["C","部门规章效力当然高于地方政府规章"],["D","二者具有同等效力，在各自权限范围内施行，冲突时依法由国务院裁决"]]', '["D"]', '根据立法法，部门规章与地方政府规章具有同等效力，在各自的权限范围内施行；部门规章之间、部门规章与地方政府规章之间对同一事项规定不一致时，由国务院裁决。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2678, 56, 67, 'single', 1.0, '外来务工人员带适龄子女到城区就学，被告知因无本地户籍、无房产，不能进入公办学校，只能自行想办法。该做法（　）', '[["A","违法，适龄儿童少年在其父母工作、居住地依法享有平等接受义务教育的权利"],["B","合理，教育资源有限应优先本地户籍儿童"],["C","合法，是否接收由学校自主决定"],["D","合法，但应建议其回户籍所在地入学"]]', '["A"]', '《义务教育法》规定，适龄儿童、少年不分性别、民族、种族、家庭财产状况、宗教信仰等，依法享有平等接受义务教育的权利；父母或者其他法定监护人在非户籍所在地工作或者居住的，当地人民政府应当为其提供平等接受义务教育的条件。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2679, 56, 68, 'single', 1.0, '班主任为“震慑”家长，把若干学生的成绩单、家庭住址、父母离异等信息直接发到有商家和无关人员的家长群。该行为主要侵犯了学生的（　）', '[["A","财产权"],["B","隐私权"],["C","受教育权"],["D","名誉权"]]', '["B"]', '隐私权指未成年人的个人信息、私人生活安宁不受非法侵扰，成绩、家庭住址、父母婚姻状况等属不愿公开的个人信息，教师擅自公开发布构成侵犯隐私权。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2680, 56, 69, 'single', 1.0, '晚自习时，唐老师发现小柯把手机夹在课本里刷短视频。依据教育惩戒与学生财物管理的有关要求，唐老师最恰当的做法是（　）', '[["A","让小柯停晚自习回家，第二天写检讨"],["B","把视频投屏到一体机让全班围观取笑"],["C","把手机摔在讲台上砸毁，以做效尤"],["D","按校规暂行保管并告知家长，课后返还时配合批评教育"]]', '["D"]', '依据《中小学教育惩戒规则（试行）》，对学生违规携带的物品，教师可依法依规暂行保管并通知家长，妥善保管、适时返还，同时进行教育引导；不得损毁财物、不得随意停课或侮辱学生。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2681, 56, 70, 'single', 1.0, '学生在体育课上突发疾病，任课教师不闻不问、继续组织其他学生活动，延误救治致损害扩大。对扩大的损害，学校（　）', '[["A","不承担责任，因疾病属学生自身原因"],["B","由体育教师个人承担全部赔偿责任"],["C","承担全部责任，学生自身疾病与损害无关"],["D","应承担相应责任，学校未履行及时救助义务"]]', '["D"]', '学生在校期间突发疾病，学校发现或应当发现后负有及时救助、通知监护人并采取相应措施的义务；教师不闻不问、延误救治导致损害扩大的，学校对扩大部分应承担相应责任。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2682, 56, 71, 'single', 1.0, '教师惠某认为学校的职称评审结果不公、侵犯其合法权益。依法她可以首先（　）', '[["A","向教育行政部门提出教师申诉"],["B","直接拒绝承担学校安排的教学任务"],["C","自行组织教师集体罢课施压"],["D","到法院起诉职称评审委员会"]]', '["A"]', '《教师法》规定，教师对学校或者其他教育机构侵犯其合法权益的，或者对学校或其他教育机构作出的处理不服的，可以向教育行政部门提出申诉。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2683, 56, 72, 'single', 1.0, '某教育行政机关对违规补课的教师作出罚款等具体行政行为，该教师拟申请行政复议。依法他应自知道该处理决定之日起的法定期限内提出，该期限一般为（　）', '[["A","2年"],["B","60日"],["C","15日"],["D","6个月"]]', '["B"]', '《行政复议法》规定，公民、法人或者其他组织认为具体行政行为侵犯其合法权益的，可以自知道或者应当知道该具体行政行为之日起六十日内提出行政复议申请。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2684, 56, 73, 'single', 1.0, '对有严重不良行为、监护人无力管教的未成年学生，依法可按规定将其送入（　）', '[["A","普通学校随班就读即可，无须专门措施"],["B","工读学校强制劳动改造"],["C","专门学校接受专门教育，必要时进行专门矫治教育"],["D","少年监狱执行刑罚"]]', '["C"]', '《预防未成年人犯罪法》规定，对有严重不良行为的未成年人，未成年人的父母或者其他监护人、所在学校无力管教或者管教无效的，可以向教育行政部门提出申请，经专门教育指导委员会评估同意后，由教育行政部门决定送入专门学校接受专门教育；对符合法定情形的，进行专门矫治教育。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2685, 56, 74, 'single', 1.0, '学生阿凯因家庭原因屡次违纪，鲁老师没有急于贴标签，而是先家访了解情况，发现他要照顾生病的奶奶。老师据此调整帮助方式，同时守住纪律底线。鲁老师主要践行了（　）', '[["A","爱岗敬业"],["B","廉洁从教"],["C","终身学习"],["D","关爱学生，严慈相济"]]', '["D"]', '关爱学生要求教师关心爱护全体学生、尊重学生人格、严慈相济，了解学生、循循善诱。鲁老师先家访弄清学生违纪背后的家庭原因，再有针对性地帮助，同时不放松纪律要求，正体现关爱学生、严慈相济。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2686, 56, 75, 'single', 1.0, '新课改听评课中，评价一节课不再主要看“教师讲得是否精彩、环节是否完整”，而更看重学生是否真正发生了学习、获得了发展。这种课堂评价导向体现了（　）', '[["A","以学论教、以学习者为中心"],["B","以教定学、以教师为中心"],["C","唯分数、唯升学的导向"],["D","重结果轻过程的甄别评价"]]', '["A"]', '新课改教学观强调教学从“教育者为中心”转向“学习者为中心”，从“教会学生知识”转向“教会学生学习”，关注人的发展；课堂评价由“以教定学”转向“以学论教”，以学生是否真正学习和发展为根本尺度。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2687, 56, 76, 'single', 1.0, '“双减”后，某名校教师仍组织、推荐学生参加校外有偿补课，或为校外培训机构介绍生源、提供学生信息。对照新时代教师职业行为准则，这主要违反了（　）', '[["A","加强安全防范"],["B","坚守廉洁自律，不得组织、参与有偿补课"],["C","潜心教书育人中的作业批改要求"],["D","规范从教行为中的着装要求"]]', '["B"]', '《新时代中小学教师职业行为十项准则》要求教师坚守廉洁自律，不得组织、参与有偿补课，不得为校外培训机构和他人介绍生源、提供相关信息。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2688, 56, 77, 'single', 1.0, '学校要求班主任把每个学生的考试成绩排名在教室外公示，并据此排座位。从教育评价改革和学生观的角度，这种做法（　）', '[["A","有利于激发竞争，应全面推广"],["B","只要家长同意就完全合法"],["C","不恰当，应扭转唯分数倾向，注重综合素质评价、保护学生自尊"],["D","是提高升学率最有效的办法"]]', '["C"]', '新课改学生观把学生看成发展的人、独特的人、具有独立意义的人；教育评价改革强调扭转唯分数、唯升学倾向，健全综合素质评价，保护学生人格尊严和隐私。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2689, 56, 78, 'single', 1.0, '备课时，卓老师用生成式人工智能检索资料、辅助设计练习，但对生成内容逐条核实，坚持自己设计教学思路、对最终课堂负责，还向学生说明工具使用边界。这体现了人工智能时代教师应（　）', '[["A","只凭经验教学，拒绝任何工具"],["B","把备课全部交给人工智能以减负"],["C","禁止学生接触一切新技术"],["D","理性利用人工智能辅助教学，坚持育人主体责任与内容审核"]]', '["D"]', '人工智能可以作为备课、资源生成、个性化辅导的辅助工具，但教师是育人主体，必须对教学内容的科学性、价值观导向和学生发展负责，对生成内容负有审核、甄别、修订之责。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2690, 56, 79, 'single', 1.0, '特级教师嵇老师从教四十年，始终把“心有大我、至诚报国”作为人生追求，扎根山区、淡泊名利、甘为人梯。他的事迹最集中地诠释了（　）', '[["A","心有大我、至诚报国的理想信念"],["B","启智润心、因材施教的育人智慧"],["C","言为士则、行为世范的道德情操"],["D","教育家精神中的勤学求是"]]', '["A"]', '中国特有的教育家精神包含心有大我、至诚报国的理想信念，言为士则、行为世范的道德情操，启智润心、因材施教的育人智慧，勤学笃行、求是创新的躬耕态度，乐教爱生、甘于奉献的仁爱之心，胸怀天下、以文化人的弘道追求。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2691, 56, 80, 'single', 1.0, '新教师在教育教学中应坚持“五育并举”，落实立德树人根本任务。下列做法最能体现把德育融入学科教学、实现“课程育人”的是（　）', '[["A","班主任把德育完全推给思政课教师"],["B","语文教师借《岳阳楼记》引导学生体会家国情怀与社会责任"],["C","数学教师认为德育与己无关，只讲公式定理"],["D","体育教师以不影响训练为由取消品德教育活动"]]', '["B"]', '课程育人（学科德育）要求把立德树人融入思想道德教育、文化知识教育、社会实践教育各环节，各学科教师都负有德育责任，要结合学科特点有机渗透。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2692, 56, 81, 'multi', 1.6, '新教师试讲《圆的认识》时：先让学生摸圆形学具、举例生活中的圆，再引导归纳半径直径关系，练习后又让学生用圆规画“规定大小”的圆，并提问“车轮为什么是圆的”。这节课较突出地体现了（　）', '[["A","让学生在感知具体事物基础上认识抽象知识的做法"],["B","学懂后及时安排练习巩固的做法"],["C","把书本知识与生活实际相联系的做法"],["D","一节课中应完全由学生自由探索、教师不讲授"],["E","只重视结论记忆、不需要学生动手操作"]]', '["A","B","C"]', '摸学具、举例生活中的圆，借助直接经验认识抽象概念，体现直观性原则，A当选；归纳后及时安排画圆等练习，体现巩固性原则，B当选；由“车轮为什么是圆的”联系生活实际，体现理论联系实际原则，C当选。D否定教师讲授的价值，属于放任自流，错误；E否认动手操作与感性认识，错误。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2693, 56, 82, 'multi', 1.6, '备课组设计“课后服务作业套餐”，允许学生在基础任务之外，按兴趣选做实验探究、社会调查或作品创作，还可与同学合作完成。这一设计体现的理念有（　）', '[["A","承认并尊重学生的兴趣与个别差异"],["B","倡导自主、合作、探究的学习方式"],["C","作业必须全班统一，差异会造成不公平"],["D","探究性活动会冲击学习，应一律取消"],["E","作业只服务于考试分数，不必考虑学生意愿"]]', '["A","B"]', '分层、可选的作业尊重学生兴趣和个别差异，A当选；允许选做探究、调查并与同学合作，体现自主、合作、探究的学习方式，B当选。C用“必须统一”否定差异，D把探究活动与学习对立，E把作业室化为应试工具，均不符合新课改理念。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2694, 56, 83, 'multi', 1.6, '班主任接手乱班后，和学生共商班规、张贴每周进步榜，让小字等“刺头”负责运动会项目，出现问题先讲清道理、对事不对人，还坚持开展志愿服务。其转化班级的做法体现了（　）', '[["A","尊重学生与严格要求相结合"],["B","依靠积极因素克服消极因素"],["C","注重实践、在活动中培养品德"],["D","学生难管时应体罚立威"],["E","对违纪学生应一律劝退以净化班风"]]', '["A","B","C"]', '共商班规、先讲道理、对事不对人体现尊重学生与严格要求相结合，A当选；让“刺头”负责运动会项目是依靠积极因素克服消极因素（长善救失），B当选；开展志愿服务体现知行统一、在实践活动中培养品德，C当选。体罚立威、劝退违纪学生均违背德育原则和法律规定，D、E错误。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2695, 56, 84, 'multi', 1.6, '学校开发“岷江竹编”校本课程时，教师走访非遗传承人、收集本地竹编资料，和学生一起编印学习手册，并在实施中根据学情不断调整内容。关于该校本课程，下列说法正确的有（　）', '[["A","教师是课程的建设者和开发者"],["B","课程内容可结合本地资源在实施中不断生成"],["C","校本课程必须由校外专家独家开发"],["D","课程一经编印就不能作任何修改"],["E","校本课程只能讲授书本理论，不能利用社区资源"]]', '["A","B"]', '教师走访传承人、收集资料、编印手册，表明教师不只是课程执行者，更是课程的建设者和开发者，A当选；结合本地竹编资源、在实施中依学情调整，体现校本课程立足学校实际、在开发实施中不断生成，B当选。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2696, 56, 85, 'multi', 1.6, '为了解“小组合作学习”的真实效果，青年教师对全班进行一学期跟踪：课堂录像编码、访谈不同层次学生、比较前后测成绩，并据此写成反思报告改进教学。该教师综合运用了（　）', '[["A","观察法"],["B","访谈法"],["C","凭主观印象给学生贴标签"],["D","只做一次测验就对学生下最终结论"],["E","把学生成绩排名公开作为唯一研究结论"]]', '["A","B"]', '课堂录像编码属于观察法，A当选；访谈不同层次学生属于访谈法，B当选；前后测比较还涉及测验等方法。主观贴标签、一次测验下结论、以排名为唯一结论都违背教育研究的客观性、发展性要求，C、D、E错误。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2697, 56, 86, 'multi', 1.6, '区教研提出课堂转型要求：变“教师一讲到底”为组织学生探究，变“只看分数”为记录学生点滴进步，变“只盯少数尖子”为关注每一个学生。这些要求体现了（　）', '[["A","教学从以教育者为中心转向以学习者为中心"],["B","评价关注过程、发挥发展性功能"],["C","教育要面向全体学生"],["D","评价应坚持甄别选拔功能至上"],["E","教学的核心是教师完成讲授任务，学生学会与否无关紧要"]]', '["A","B","C"]', '组织学生探究体现教学从以教育者为中心转向以学习者为中心，A当选；记录点滴进步体现过程性、发展性评价，B当选；关注每一个学生体现教育面向全体，C当选。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2698, 56, 87, 'multi', 1.6, '针对把失败归于“笨”的学生，心理老师引导他们：考后把错题归因到“这道题的方法没用对、还可以再练”，并帮其制订可操作的小目标，每完成一步都让他们看到“努力一进步”的关系。这种辅导的合理之处在于（　）', '[["A","引导学生把失败归因于不稳定、可改变的因素"],["B","通过成功体验增强自我效能感"],["C","把大目标分解为可达成的近期目标"],["D","反复强调“脑子笨”以激发知耻后勇"],["E","用统一名次比较让学生认清差距"]]', '["A","B","C"]', '把失败归因于方法、努力等内部不稳定可控因素，有助于改变“我笨”的消极归因，A当选；通过完成小目标体验成功可以增强自我效能感，B当选；把大目标分解为可操作的近期目标符合目标设置要求，C当选。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2699, 56, 88, 'multi', 1.6, '期末复习时，小晗用思维导图梳理章节结构，对重难点自问自答，主动向老师请教卡住的问题，并按考试时间安排各科复习。她运用了（　）', '[["A","组织策略"],["B","元认知（自我提问与计划）策略"],["C","学业求助与时间管理策略"],["D","遇到难题独自硬扛、拒绝任何求助"],["E","复习只靠反复机械抄写，不做任何整理"]]', '["A","B","C"]', '思维导图梳理章节结构是组织策略，A当选；自问自答和计划安排体现元认知策略中的监控与计划，B当选；主动向老师请教属学业求助策略，按考试时间安排各科复习属时间管理策略，C当选。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2700, 56, 89, 'multi', 1.6, '学生在课堂上突然起哄、扔纸条。教师下列处理中恰当的有（　）', '[["A","先用眼神、走近等非言语方式提示，尽量不中断教学"],["B","查明原因、就事论事，必要时按规则实施适当惩戒"],["C","课后沟通、了解学生行为背后的需要"],["D","立即停课清查全班，整节课罚站所有学生"],["E","当众公布学生家庭隐私以使其羞愧"]]', '["A","B","C"]', '处理课堂问题行为应遵循最少干预、就事论事原则：A以眼神、走近等非言语方式提示，恰当；B查明原因、就事论事，恰当；C课后沟通、了解行为背后的需要，恰当。D、E均属扩大化的变相体罚和侵犯隐私。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2701, 56, 90, 'multi', 1.6, '体育课上，学生在教师组织的自由活动时间擅自闯入未开放、设有警示标志的器材仓库攀爬器材，不慎跌落受伤。关于学校责任，下列说法正确的有（　）', '[["A","学校无论有无过错都应承担全部赔偿责任"],["B","学校已设警示标志并限制进入，对擅自进入的学生可相应减责"],["C","应结合学校是否尽到管理职责、学生年龄和过错程度综合认定责任"],["D","学生受伤一律由学校和教师承担连带责任"],["E","学生自身违反管理规定、擅自进入危险区域，对损害发生有过错，应自行承担相应责任"]]', '["B","C"]', '学生伤害事故责任以过错责任为主，责任承担应结合学校是否尽到教育管理职责、学生年龄认知能力与学生自身过错综合认定。B学校已设警示标志并限制进入，对擅自进入的学生可相应减轻责任，正确；C综合认定学校过错、学生年龄与过错程度，符合责任认定原则，正确。A、D均属绝对化归责。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2702, 57, 1, 'judge', 0.6, '宋老师给幼儿园幼儿讲分数通分，认为抽象知识学得越早越好。这违背了个体发展的阶段性要求。', '[["A","正确"],["B","错误"]]', '["A"]', '幼儿园幼儿处于前运算阶段，以具体形象思维为主，抽象逻辑思维尚未发展。讲授分数通分并要求书面练习超出该年龄段发展水平，违背个体身心发展的阶段性规律。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2703, 57, 2, 'judge', 0.6, '参观古人类展示到儿童模仿成人捕鱼学得技能，沈老师据此赞成教育起源于无意识模仿的观点。', '[["A","正确"],["B","错误"]]', '["A"]', '心理起源说的代表人物孟禄认为教育起源于日常生活中儿童对成人的无意识模仿。展览中儿童通过模仿成人捕鱼而习得劳动技能的场景，正对应心理起源说。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2704, 57, 3, 'judge', 0.6, '别的学校推行什么新模式秦校长就照搬，校训校歌也一年一换。这体现了教育的历史继承性。', '[["A","正确"],["B","错误"]]', '["B"]', '教育具有相对独立性，历史继承性是其重要表现：每一时代的教育都在以往教育基础上发展，学校长期积淀的校训、传统应批判继承。秦校长盲目跟风、频繁抛弃本校传统，恰恰忽视而非体现了教育的历史继承性。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2705, 57, 4, 'judge', 0.6, '小学低年级开英语口语和视唱练耳课，抓住语言听觉敏感期施教，符合“当其可之谓时”。', '[["A","正确"],["B","错误"]]', '["A"]', '同一方面的发展在不同年龄阶段速度不均衡，存在发展的关键期（敏感期），关键期内施教效果最好。语言听觉在低年级正处敏感期，学校此时开设口语与视唱练耳课抓住了关键期。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2706, 57, 5, 'judge', 0.6, '初三复习时韩老师取消全部劳动课改上刷题，说这就是教育与生产劳动相结合。', '[["A","正确"],["B","错误"]]', '["B"]', '教育与生产劳动和社会实践相结合是我国教育目的的基本精神之一，劳动实践课程具有独立育人价值，不能被文化课挤占。韩老师取消劳动课、把刷题等同于教劳结合，既违背教育方针，也不利于学生全面发展。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2707, 57, 6, 'judge', 0.6, '学校把师生书画、科技节照片布置在走廊墙面。程老师认为这些墙面布置属于学科课程。', '[["A","正确"],["B","错误"]]', '["B"]', '走廊墙面的书画、照片以隐蔽、间接的方式对学生产生熏陶作用，没有明确的课程标准和教学计划，属于隐性课程（潜在课程），而非以学科内容为中心、有目的有计划开设的显性（学科）课程。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2708, 57, 7, 'judge', 0.6, '学生指出板书中的史实错误，孔老师核实后致谢并带全班订正。这体现了教学相长。', '[["A","正确"],["B","错误"]]', '["A"]', '教学相长是指教师的教与学生的学相互促进，教师可以向学生学习，学生也能促进教师提高。孔老师面对学生指出的错误不护短，当场核实并致谢订正，正是教学相长的体现。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2709, 57, 8, 'judge', 0.6, '教务主任把数学、物理、化学三节高难度课连排在上午，称这样安排最符合用脑卫生。', '[["A","正确"],["B","错误"]]', '["B"]', '科学安排课表应遵循大脑皮层活动规律，把难易不同、抽象与形象、文理学科交替编排，避免同类刺激长时间单调重复造成疲劳。三节高难度理科连排会使神经活动超限抑制、降低效率，不符合用脑卫生。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2710, 57, 9, 'judge', 0.6, '四岁的朵朵安慰掉在地上的布偶“摔疼了”。这是前运算阶段儿童思维的典型表现。', '[["A","正确"],["B","错误"]]', '["A"]', '皮亚杰认为2—7岁儿童处于前运算阶段，思维具有泛灵论（万物有灵论）特点，倾向于认为外界事物都是有生命、有情感的。朵朵认为布偶会“摔疼”，正是泛灵论的典型表现。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2711, 57, 10, 'judge', 0.6, '小豆独立只能做60分难度的题，经点拨能做80分难度的题，这两个水平间的区域正是教学应着眼处。', '[["A","正确"],["B","错误"]]', '["A"]', '维果斯基把儿童独立解决问题的现有水平与在成人或同伴帮助下所能达到的潜在水平之间的差距称为最近发展区，教学应走在发展前面，着眼于最近发展区。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2712, 57, 11, 'judge', 0.6, '学生被某教师体罚后，见到所有老师都紧张。何老师说这是操作性条件作用中惩罚的效果。', '[["A","正确"],["B","错误"]]', '["B"]', '学生由对某位教师的恐惧泛化到对所有任课教师的恐惧，是先有刺激（体罚情境）引起恐惧反应、相似刺激（其他教师）也诱发同一反应，属于巴甫洛夫经典性条件作用中的刺激泛化。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2713, 57, 12, 'judge', 0.6, '班长因主动整理器材受表扬，几个马虎同学随后也悄悄把器材归位。榜样受奖带动了观察者效仿。', '[["A","正确"],["B","错误"]]', '["A"]', '班杜拉社会学习理论把强化分为直接强化、替代强化和自我强化。观察者因看到榜样的行为受到强化而增强自己做出该行为的倾向，就是替代强化。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2714, 57, 13, 'judge', 0.6, '接力赛前小魏回想自己成功交接棒的画面，紧张减轻。他在借自身成功经验增强完成任务的信心。', '[["A","正确"],["B","错误"]]', '["A"]', '自我效能感是个体对自己能否成功完成某一任务的主观判断，其最重要、最有力的信息来源是个体自身行为的成败经验。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2715, 57, 14, 'judge', 0.6, '学了汉语拼音后认读英语单词明显加快，吕老师判断这属于垂直迁移。', '[["A","正确"],["B","错误"]]', '["B"]', '垂直迁移是处于不同抽象、概括水平的经验之间（上位概念与下位概念之间）的相互影响。汉语拼音与英语单词认读属于同一抽象层次的两种语言技能之间的影响，是水平（横向）迁移。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2716, 57, 15, 'judge', 0.6, '早读时排在最前面背诵的篇目往往记得最牢，蒋老师解释说这是因为没有前摄抑制。', '[["A","正确"],["B","错误"]]', '["A"]', '先学材料对回忆后学材料的干扰叫前摄抑制，后学材料对保持回忆先学材料的干扰叫倒摄抑制。排在最前面背诵的内容之前没有其他识记材料，故不存在前摄抑制，只受后续材料的倒摄抑制影响，因而往往记得较牢。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2717, 57, 16, 'judge', 0.6, '信息课上蔡老师只让学生反复看编程演示视频，从不上机，说看熟了自然就会编程。', '[["A","正确"],["B","错误"]]', '["B"]', '心智技能的形成要经历原型定向、原型操作、原型内化三个阶段，原型操作要求学生借助物质或外显形式亲自进行实践活动。只看不做，学生无法经历原型操作阶段，编程这类心智技能便难以真正形成。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2718, 57, 17, 'judge', 0.6, '证明题卡住时，余小川先翻笔记回忆定理，再向同学请教思路而不照抄。这属于学业求助策略。', '[["A","正确"],["B","错误"]]', '["A"]', '学业求助策略是资源管理策略的一种，指导习遇到困难时善于向他人或工具寻求帮助，关键是借助帮助学会独立解决问题而非简单抄袭。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2719, 57, 18, 'judge', 0.6, '学生只想到杯子能喝水，想不到倒扣可当支架。余老师据此断定他们创造性水平低下。', '[["A","正确"],["B","错误"]]', '["B"]', '人们把某种功能赋予某物体后难以想到它的其他新功能，这是功能固着，是影响问题解决的一种定势现象，与创造性水平高低不能直接画等号。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2720, 57, 19, 'judge', 0.6, '曹阳主动捡走廊垃圾，说“维护校园卫生是学生应尽的本分”。该理由处于习俗水平。', '[["A","正确"],["B","错误"]]', '["A"]', '科尔伯格把道德判断分为前习俗、习俗、后习俗三个水平。习俗水平的个体以维护社会秩序、规则和履行个人责任为判断依据。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2721, 57, 20, 'judge', 0.6, '学生倾诉自伤念头，心理老师当即将其姓名和情况发到班级群提醒大家。这符合保密要求。', '[["A","正确"],["B","错误"]]', '["B"]', '心理辅导应遵循保密原则，对来访学生的个人信息和倾诉内容严格保密；涉及自伤等危机情形应按危机干预流程向专业人员和监护人报告，而不是公开扩散。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2722, 57, 21, 'judge', 0.6, '入职第五年的田老师备课重点关注学困生能否跟上、学优生能否吃饱，据此设计分层任务。', '[["A","正确"],["B","错误"]]', '["A"]', '福勒和布朗把教师成长分为关注生存、关注情境、关注学生三个阶段。关注学生阶段的教师能考虑学生个别差异，根据不同学生的水平和需求进行教学。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2723, 57, 22, 'judge', 0.6, '任老师认为，省政府制定的规章效力高于全国人大常委会制定的法律。', '[["A","正确"],["B","错误"]]', '["B"]', '我国教育法渊源效力依次为：宪法最高，其次是全国人大及其常委会制定的法律，再次是国务院行政法规，之后才是地方性法规和规章。省政府规章属于地方政府规章，效力低于法律。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2724, 57, 23, 'judge', 0.6, '家长要让满六周岁的孩子推迟入学，称晚点开窍更好。学校告知家长应按时送其入学。', '[["A","正确"],["B","错误"]]', '["A"]', '《义务教育法》规定，凡年满六周岁的儿童，其父母或者其他法定监护人应当送其入学接受并完成义务教育；条件不具备的地区可推迟到七周岁并依法办理缓学手续。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2725, 57, 24, 'judge', 0.6, '丁老师不服学校扣发绩效工资，他认为只能先申请仲裁，无权向教育行政部门申诉。', '[["A","正确"],["B","错误"]]', '["B"]', '《教师法》第三十九条规定，教师对学校侵犯其合法权益或对学校作出的处理不服的，可以向教育行政部门提出申诉，教育行政部门应在接到申诉三十日内作出处理。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2726, 57, 25, 'judge', 0.6, '学生多次扰乱课堂且提醒无效，魏老师责令其教室内站立不超一节课，课后再谈话。这是合规一般惩戒。', '[["A","正确"],["B","错误"]]', '["A"]', '《中小学教育惩戒规则（试行）》规定的一般惩戒包括“一节课堂教学时间内的教室内站立”以及课后教导，且不得超过正常限度、不得实施体罚或变相体罚。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2727, 57, 26, 'judge', 0.6, '初二两学生课间追逐撞倒同学致伤，学校已尽教育管理职责。依法学校仍应承担侵权责任。', '[["A","正确"],["B","错误"]]', '["B"]', '《民法典》第一千二百条规定，限制民事行为能力人在学校学习、生活期间受到人身损害，学校未尽到教育、管理职责的才承担侵权责任，即适用过错责任原则。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2728, 57, 27, 'judge', 0.6, '下班后沈老师把作文抱回家逐本批注，还为请假学生整理补课笔记。这体现了爱岗敬业。', '[["A","正确"],["B","错误"]]', '["A"]', '《中小学教师职业道德规范》要求教师忠诚于人民教育事业，勤恳敬业、乐于奉献，对工作高度负责，认真批改作业、辅导学生。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2729, 57, 28, 'judge', 0.6, '家长寄来土特产请多关照，姜老师收下并答应该生长期固定坐前排。该做法符合为人师表要求。', '[["A","正确"],["B","错误"]]', '["B"]', '《中小学教师职业道德规范》要求教师为人师表、廉洁从教，不利用职务之便谋取私利；排座位应公平公正、面向全体学生。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2730, 57, 29, 'judge', 0.6, '董老师不给成绩落后的学生贴“差生”标签，而发现其编程特长委以电教任务。这符合学生是发展中的人。', '[["A","正确"],["B","错误"]]', '["A"]', '新课改学生观认为学生是发展的人、独特的人和具有独立意义的人，学生有巨大发展潜能、处于发展过程中，应用发展的眼光看待。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2731, 57, 30, 'judge', 0.6, '2025年6月1日起施行的学前教育领域专门法律是《中华人民共和国学前教育条例》。', '[["A","正确"],["B","错误"]]', '["B"]', '2024年11月8日全国人大常委会通过、自2025年6月1日起施行的学前教育领域专门法律是《中华人民共和国学前教育法》，属全国人大常委会制定的法律；“条例”一般是行政法规或地方性法规的名称。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2732, 57, 31, 'single', 1.0, '新学期教研会上，刚入职的乔老师问：“咱们现在用的班级授课制，最早是在哪部著作中被系统论述的？”教研组长给出的正确回答是（　）', '[["A","杜威的《民主主义与教育》"],["B","赫尔巴特的《普通教育学》"],["C","夸美纽斯的《大教学论》"],["D","昆体良的《雄辩术原理》"]]', '["C"]', '17世纪夸美纽斯在《大教学论》中系统论述了班级授课制，奠定了近代教学组织形式的基础。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2733, 57, 32, 'single', 1.0, '高新区新建一所公办初中，资金主要来自财政拨款，教师纳入编制管理，学校不得拒绝服务区内符合条件的适龄儿童入学。这些特征表明该校属于（　）', '[["A","以营利为目的的民办学校"],["B","由企业举办、主要面向本企业职工子女的学校"],["C","主要依靠社会力量捐资举办的学校"],["D","由政府举办、面向社会提供公共教育服务的学校"]]', '["D"]', '学校由政府利用财政性教育经费举办、教师纳入编制、面向辖区适龄儿童提供免费义务教育，符合《教育法》中“以财政性经费举办、面向社会提供公共教育服务”的公办学校特征。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2734, 57, 33, 'single', 1.0, '同一所中学里，同龄人中有人擅长抽象推理，有人动手操作能力突出；同一个学生在数学和音乐上的发展也明显不均衡。要据此安排教育教学，主要应依据个体身心发展的（　）', '[["A","个别差异性"],["B","阶段性"],["C","互补性"],["D","顺序性"]]', '["A"]', '不同个体之间以及同一个体不同方面发展速度、水平和优势领域的不同，是个别差异性的表现，要求因材施教。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2735, 57, 34, 'single', 1.0, '课后服务中，学校开设了机器人、泥塑、校园广播等社团，学生自愿报名，在活动中自主设计作品。这一做法直接体现了我国教育目的所强调的（　）', '[["A","统一考试升学导向"],["B","培养学生创新精神和实践能力"],["C","以学科成绩为唯一评价标准"],["D","压缩课外活动时间增加课时"]]', '["B"]', '素质教育以培养学生创新精神和实践能力为重点。学生在机器人、泥塑、广播等社团中自主选择、动手设计，正是培养创新精神和实践能力的重要途径。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2736, 57, 35, 'single', 1.0, '某区规定：各学校课程方案中除国家课程外，还必须留出一定比例由学校结合本地竹编技艺和水乡文化自主开发实施。这一规定对应的课程是（　）', '[["A","国家课程"],["B","地方课程与校本课程"],["C","学科课程"],["D","必修课程"]]', '["B"]', '国家课程由国家统一制定；地方课程由省级教育行政部门规划、反映地方需求；校本课程由学校以学校为基地自主开发。结合本地竹编、水乡文化由学校自主开发实施的课程，属于地方与校本课程范畴。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2737, 57, 36, 'single', 1.0, '综合实践活动课上，钟老师没有先讲结论，而是带学生到社区调查垃圾分类执行情况，再回班整理数据、讨论改进建议。这门课程按内容组织方式划分，主要属于（　）', '[["A","分科课程"],["B","隐性课程"],["C","学科课程"],["D","活动课程"]]', '["D"]', '活动课程（经验课程）以儿童从事某种活动的兴趣和动机为中心组织课程，强调在做中学、直接经验。综合实践活动以学生亲历的调查、实践为主要方式，按内容组织方式属于活动课程。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2738, 57, 37, 'single', 1.0, '物理课讲“浮力”，穆老师先把不同物体逐一放入水槽让学生观察沉浮，再引出阿基米德原理。他遵循的教学原则主要是（　）', '[["A","直观性原则"],["B","巩固性原则"],["C","因材施教原则"],["D","量力性原则"]]', '["A"]', '直观性原则要求通过学生观察所学事物或教师语言形象描述，引导学生形成清晰表象、丰富感性认识。穆老师用实物演示沉浮，为抽象的浮力原理提供感性材料，体现直观性原则。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2739, 57, 38, 'single', 1.0, '语文组备课讨论《社戏》，有老师主张逐句串讲，蓝老师坚持设计“童年伙伴”话题，让学生结合自身体验先聊再读。蓝老师的主张更能体现（　）', '[["A","逐句串讲，把课文结论直接告诉学生"],["B","先组织学生围绕话题谈自身体验，再引导回到课文研读"],["C","整节课放任学生漫谈，不作任何方向引导"],["D","用反复抄写代替对文本的理解和讨论"]]', '["B"]', '教学过程是教师主导与学生主体相统一的过程：教师负责组织引导，学生是认识和发展的主体。蓝老师设计话题、调动学生体验主动参与，同时仍围绕课文目标展开。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2740, 57, 39, 'single', 1.0, '地理课上，游老师把“等高线地形图判读”分解为识别等高距、判断疏密、辨认部位、综合判读四个阶梯，学生每完成一步再进入下一步。这一教学策略最能体现（　）', '[["A","程序教学思想"],["B","非指导性教学"],["C","设计教学法"],["D","文纳特卡制"]]', '["A"]', '程序教学由斯金纳提出，把学习内容分解为一系列小步子，按照由易到难的逻辑顺序排列，学生逐步学习并及时获得反馈强化。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2741, 57, 40, 'single', 1.0, '期末，学校不再只发一张分数条，而是从知识掌握、探究表现、合作态度、进步幅度等方面给每个学生写评语，并附学生自评和同伴互评。这种评价属于（　）', '[["A","单一的相对评价"],["B","以甄别选拔为唯一目的的评价"],["C","发展性评价"],["D","只看结果的终结性定量评价"]]', '["C"]', '发展性评价强调立足过程、促进发展，评价主体多元、内容综合、方式多样，重视学生自评互评和进步。题干中多维度评语、自评互评、关注进步，正是发展性评价的表现。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2742, 57, 41, 'single', 1.0, '班会上，虞老师没有简单宣布“禁止带零食”，而是先呈现校门口垃圾问题，组织学生讨论后果、共同制定“文明就餐公约”，之后违规现象明显减少。这一德育模式最接近（　）', '[["A","体谅模式"],["B","价值澄清模式"],["C","社会模仿模式"],["D","认知发展模式"]]', '["B"]', '价值澄清模式主张帮助学生在价值选择与评价过程中澄清自己的价值观，强调选择、珍视、行动三个阶段和学生自主选择。虞老师让学生面对真实问题、讨论后果并自主形成公约，引导学生经过选择认同规则。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2743, 57, 42, 'single', 1.0, '新接班的骆老师发现班级卫生总靠检查前突击，她没有一味批评，而是先和学生一起重排值日岗位、明确标准，再连续两周每天小结表扬进步小组。她在班级管理中主要运用了（　）', '[["A","只靠行政命令的管理方式"],["B","以惩罚为唯一手段的方式"],["C","放任自流、不做要求的方式"],["D","目标管理与正向激励相结合"]]', '["D"]', '班级目标管理是将班级总目标分解为岗位和个人目标、形成目标体系并以评价激励推动落实的管理方式。骆老师与学生明确岗位目标和标准，又通过每日小结、表扬强化良好行为。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2744, 57, 43, 'single', 1.0, '课外活动时，围棋社学生自行商定训练计划、组织内部比赛，甘老师只在遇到规则争议时才出面点拨。甘老师在活动中主要承担的角色是（　）', '[["A","全程包办的控制者"],["B","只负责安全的旁观者"],["C","学生活动的指导者与支持者"],["D","代替学生决定一切的领导者"]]', '["C"]', '课外活动的基本要求是学生自愿参加、自主活动，教师是活动的指导者、组织者和支持者，应尊重学生自主性，在关键处给予指导而非包办代替。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2745, 57, 44, 'single', 1.0, '学校要求教师每学期完成一定量的听评课和课题研究，并把研究成果用于改进课堂。这一要求直接推动教师实现的专业发展途径是（　）', '[["A","只靠学历提升发展"],["B","以教育教学研究促进专业成长"],["C","脱离教学实践的理论学习"],["D","凭借工龄自然成长"]]', '["B"]', '教师专业发展的重要途径包括师范教育、入职辅导、在职培训和自我教育，其中立足教育教学实践开展行动研究、以研促教是在职教师专业成长的关键途径。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2746, 57, 45, 'single', 1.0, '课堂上，当学生提出与预设答案不同的解法时，程老师没有急于否定，而是先请其讲清思路，再引导全班比较两种解法。从师生关系看，程老师的做法有利于（　）', '[["A","建立民主平等、教学相长的师生关系"],["B","维护教师不容置疑的绝对权威"],["C","形成学生无条件服从的关系"],["D","取消教师在教学中的主导地位"]]', '["A"]', '新型师生关系的特征是尊师爱生、民主平等、教学相长、心理相容。程老师尊重学生的不同见解、平等交流并在互动中共同提高，有利于建立民主平等、教学相长的师生关系。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2747, 57, 46, 'single', 1.0, '五岁的宁宁认为：把水从矮胖杯倒入细长杯后水变多了，因为液面“变高了”；他还坚持“月亮在跟着我走”。宁宁的认知发展最可能处于皮亚杰所说的（　）', '[["A","感知运动阶段"],["B","形式运算阶段"],["C","具体运算阶段"],["D","前运算阶段"]]', '["D"]', '前运算阶段（约2—7岁）儿童思维不守恒，只注意到液面高度而不能同时考虑杯身粗细，且具有自我中心和泛灵论倾向。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2748, 57, 47, 'single', 1.0, '解数学应用题时，初一学生还需要画出线段图才能理清数量关系；到了初三，多数学生可以直接在头脑中推演。这种变化主要表明中学生的认知发展（　）', '[["A","不再需要任何直观支持"],["B","由抽象思维退化为动作思维"],["C","已经完全摆脱了具体经验"],["D","由具体形象思维向抽象逻辑思维过渡"]]', '["D"]', '中学生思维发展的总体趋势是从具体形象思维向抽象逻辑思维过渡，初中阶段抽象逻辑思维开始占优势但仍需具体经验支持，到初三逐渐能直接推演。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2749, 57, 48, 'single', 1.0, '丁老师把一道有挑战性的阅读题安排给小航：他独立完成有困难，但在同学讨论和老师追问下能顺利解决。丁老师这一安排主要依据的是（　）', '[["A","维果斯基的最近发展区理论"],["B","皮亚杰的发生认识论"],["C","弗洛伊德的精神分析理论"],["D","埃里克森的人格发展阶段理论"]]', '["A"]', '最近发展区是儿童独立解决问题的现有水平与在成人或同伴帮助下所能达到的潜在水平之间的差距，教学应着眼于该区域、走在发展前面。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2750, 57, 49, 'single', 1.0, '同一个班，小宇喜欢老师给出明确步骤再练，晓岚则偏爱先自己尝试、在探索中归纳。教师据此调整指导方式，是为了适应学生的（　）', '[["A","气质类型差异"],["B","认知方式差异"],["C","性格的态度特征"],["D","智力水平的高低"]]', '["B"]', '场独立与场依存、冲动与沉思等属于认知方式（认知风格）差异，它描述个体加工信息时偏爱的方式，无优劣之分。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2751, 57, 50, 'single', 1.0, '刚上小学的孩子常说“我是小学生了，我要认真完成老师交给我的任务”，做事特别在意能否胜任、是否被表扬。按照埃里克森的理论，这一阶段儿童面临的主要发展任务是（　）', '[["A","确认身边的人是否可靠、能否满足基本需要"],["B","自己吃饭穿衣，凡事希望“我来”"],["C","努力完成学习任务、争取胜任与表扬"],["D","主动发起游戏和提问，又怕闯祸受责备"]]', '["C"]', '埃里克森认为6—12岁（学龄期）的发展任务是培养勤奋感、克服自卑感，儿童在学习和同伴交往中体验完成任务的胜任感。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2752, 57, 51, 'single', 1.0, '数学老师发现：学生一开始把“函数”理解成具体的几个公式，随着学习推进，逐渐能概括出“两个非空数集间的对应关系”这一共同本质特征。按照加涅的层次，这种学习结果属于（　）', '[["A","言语信息"],["B","智慧技能中的概念学习"],["C","动作技能"],["D","态度"]]', '["B"]', '加涅把学习结果分为言语信息、智慧技能、认知策略、动作技能和态度。其中智慧技能包括辨别、具体概念、定义性概念、规则和高级规则。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2753, 57, 52, 'single', 1.0, '实验中，铃声原本与狗分泌唾液无关；反复在铃声后给食物，后来只响铃狗也分泌唾液。教师用这个实验帮助学生理解，铃声在条件作用建立后成为（　）', '[["A","无条件刺激"],["B","无条件反应"],["C","条件刺激"],["D","中性反应"]]', '["C"]', '在巴甫洛夫经典性条件作用中，食物是无条件刺激，能引起无条件反应（分泌唾液）；铃声原本是无关（中性）刺激，与食物多次结合后单独能引起唾液分泌，便转化为条件刺激。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2754, 57, 53, 'single', 1.0, '编程课上，学生每完成一个小模块并通过测试，系统立即给出积分和进度条，学生越做越有劲头。这种安排所依据的学习理论最可能是（　）', '[["A","经典性条件作用理论"],["B","有意义接受学习理论"],["C","认知—结构学习理论"],["D","操作性条件作用理论"]]', '["D"]', '斯金纳操作性条件作用理论认为，行为之后及时给予强化（如奖励、反馈）会提高该行为发生的概率。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2755, 57, 54, 'single', 1.0, '生物课讲“生态系统”，贝老师先呈现几幅真实生态系统图，让学生自己尝试发现组成要素之间的关系，之后才给出概念。这种教学更符合哪位学者的主张（　）', '[["A","布鲁纳的认知—发现学习理论"],["B","奥苏贝尔的有意义接受学习理论"],["C","巴甫洛夫的经典性条件作用理论"],["D","桑代克的试误说"]]', '["A"]', '布鲁纳主张认知—发现学习，强调让学生独立思考、自行发现知识的结构和原理，教师提供材料、引导发现。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2756, 57, 55, 'single', 1.0, '讲授“洋流”前，路老师先在黑板上画出学生已学过的“大气环流”示意图，再把洋流作为新知识挂接到这一框架上。路老师利用的是奥苏贝尔所说的（　）', '[["A","操作性消退"],["B","学习的顿悟"],["C","先行组织者"],["D","替代强化"]]', '["C"]', '先行组织者是奥苏贝尔有意义接受学习理论中的重要概念，指在学习新材料前呈现的、概括和包容水平较高的引导性材料，用以搭建新旧知识联系的桥梁。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2757, 57, 56, 'single', 1.0, '学生晓雯说：“我努力学生物，是因为亲手做实验、弄清生命现象本身就让我特别满足。”从学习动机的来源看，这主要属于（　）', '[["A","内部学习动机"],["B","外部学习动机"],["C","近景的直接性动机中的外部诱因"],["D","由家长物质奖励驱动的动机"]]', '["A"]', '内部学习动机由个体内在需要引起，指向学习活动本身，如求知欲、学习兴趣和探究带来的满足感。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2758, 57, 57, 'single', 1.0, '物理测验后，小晟把错题本推到一边，嘟囔：“我脑子就不是学理科的料，再熬也白搭。”此后遇到稍难的题他都直接空着。按韦纳的归因理论，他主要把失利归因为（　）', '[["A","外部、稳定、不可控的任务难度"],["B","内部、不稳定、可控的努力"],["C","外部、不稳定、不可控的运气"],["D","内部、稳定、不可控的能力"]]', '["D"]', '韦纳把成败归因分为能力、努力、任务难度、运气等维度。“天生不是读书的料”将失败归于能力，能力属于内部、稳定、不可控因素；长期作此归因易形成习得性无助。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2759, 57, 58, 'single', 1.0, '学校把运动会志愿服务、为社区老人读报等活动纳入课程。有学生起初只是为了攒“德育积分”，参加几次后真正体会到帮助他人的快乐而主动坚持。这种从外部要求转向内心认同的过程属于（　）', '[["A","操作技能的迁移"],["B","态度与品德的形成"],["C","知识的遗忘"],["D","元认知的监控"]]', '["B"]', '态度与品德的形成一般经历依从、认同、内化三个阶段。学生最初为获得积分而参加（依从外部要求），后来在活动中产生真实情感、主动坚持，表明行为由外在驱动转为内在认同。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2760, 57, 59, 'single', 1.0, '同一道物理题，刷过大量类似题的小峰能迅速套用题型，而第一次见这类情境的同学则反复读题、尝试多种思路。小峰主要依赖的是（　）', '[["A","陈述性知识"],["B","无意注意"],["C","直觉动作思维"],["D","程序性知识"]]', '["D"]', '陈述性知识回答“是什么”，程序性知识回答“怎么办”，是关于完成某项任务的操作步骤和方法。大量练习后形成的、能够迅速调用的解题套路与操作流程属于程序性知识（技能）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2761, 57, 60, 'single', 1.0, '背诵英语单词时，小芮把一串生词按“校园生活”“环境保护”等主题归类，并在每个词下自编一个例句。她使用的学习策略主要是（　）', '[["A","复述策略"],["B","精细加工策略"],["C","元认知调节策略"],["D","努力管理策略"]]', '["B"]', '精细加工策略是通过把新信息与已有知识建立联系来增加新信息意义的策略，如记忆术、做笔记、生成例句等。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2762, 57, 61, 'single', 1.0, '考前复习，晓彤先列出各科薄弱清单、估算可用时间、排出优先级，复习中发现计划不合理又及时调整。这一系列计划、监控、调整活动属于（　）', '[["A","元认知策略"],["B","认知策略中的复述策略"],["C","资源管理策略中的时间管理"],["D","组织策略"]]', '["A"]', '元认知策略包括计划策略、监控策略和调节策略，指对自身认知过程的认识和调控。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2763, 57, 62, 'single', 1.0, '解放性语文题时，小雅能在短时间内提出多个互不相同、角度新颖的立意。教师据此主要应肯定她思维的（　）', '[["A","深刻性和批判性"],["B","指向性和集中性"],["C","流畅性与独创性"],["D","聚合性"]]', '["C"]', '发散思维是创造性思维的核心，其主要特征是流畅性（短时间内产生观念数量多）、变通性（类型和角度多）和独创性（观念新颖独特）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2764, 57, 63, 'single', 1.0, '考前一周，小唐总觉得心慌、手心出汗、睡不好，一进考场脑子就“一片空白”。心理老师初步判断，他最突出的问题是（　）', '[["A","考试焦虑"],["B","智力低下"],["C","品德不良"],["D","学习迁移"]]', '["A"]', '考试焦虑是个体在应试情境下产生的以担忧为基本特征、伴有紧张、心慌、出汗、失眠及临场思维受阻等生理和情绪反应的心理状态。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2765, 57, 64, 'single', 1.0, '在教育教学活动中，某校与受聘教师围绕“上课、教研、考核”等事项分别享有权利、承担义务。这种由教育法律规范所确认和调整的社会关系，在法学上称为（　）', '[["A","师生朋友关系"],["B","教育法律关系"],["C","行政隶属关系"],["D","民事合同中的买卖关系"]]', '["B"]', '教育法律关系是教育法律规范在调整教育活动过程中形成的权利义务关系，主体包括学校、教师、学生和教育行政机关等。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2766, 57, 65, 'single', 1.0, '某市教育局发布通知，要求辖区中小学严格执行“免试就近入学”，并对违规组织考试选拔的学校责令改正。这一情形主要体现了教育法的（　）', '[["A","指引作用"],["B","教育法不具有任何规范作用"],["C","评价作用的无关性"],["D","强制作用"]]', '["D"]', '法的规范作用包括指引、评价、教育、预测和强制作用。强制作用是指法通过国家强制力制裁、追究违法主体责任、迫使违法者履行义务。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2767, 57, 66, 'single', 1.0, '新学年，有家长联名建议学校按入学测试成绩把同年级学生编入不同“快慢班”、实行差异化师资配置。依据《义务教育法》，学校的正确做法是（　）', '[["A","可以分设重点校和非重点校"],["B","可按成绩公开排名分班"],["C","不得分设重点校和非重点校、重点班和非重点班"],["D","可拒收本服务区内学习困难学生"]]', '["C"]', '《义务教育法》第二十二条规定，县级以上人民政府及其教育行政部门应当促进学校均衡发展，缩小学校之间办学条件的差距，不得将学校分为重点学校和非重点学校；学校不得分设重点班和非重点班。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2768, 57, 67, 'single', 1.0, '教师钟某在教育教学、指导学生发展、参与学校民主管理以及按时获取工资报酬等方面享有的权利，集中规定在（　）', '[["A","《中华人民共和国刑法》"],["B","《中华人民共和国教师法》"],["C","《中华人民共和国公司法》"],["D","《中华人民共和国治安管理处罚法》"]]', '["B"]', '《教师法》第七条系统规定了教师进行教育教学活动、从事科学研究、指导评价学生、按时获取工资报酬、参与学校民主管理、参加进修培训等六项权利。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2769, 57, 68, 'single', 1.0, '某小学要求三年级学生统一购买指定书店的高价教辅，不买就影响作业布置。该做法主要侵犯了学生的（　）', '[["A","生命健康权"],["B","人格尊严权"],["C","受教育权中的教育选择权"],["D","财产权"]]', '["D"]', '学生的财产权包括财产所有权和继承权等，学校、教师不得违反规定向学生收取费用或变相推销商品、服务谋取利益。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2770, 57, 69, 'single', 1.0, '一名七岁的一年级学生在校期间追逐打闹时受伤。关于学校责任，下列说法符合《民法典》规定的是（　）', '[["A","学校无论有无过错都必须全额赔偿"],["B","由受伤学生自己承担全部责任"],["C","学校能够证明尽到教育、管理职责的，不承担侵权责任"],["D","一律由同班同学承担责任"]]', '["C"]', '《民法典》第一千一百九十九条规定，无民事行为能力人（不满八周岁）在幼儿园、学校学习生活期间受到人身损害的，适用过错推定责任，学校应当承担责任，但能够证明尽到教育、管理职责的除外。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2771, 57, 70, 'single', 1.0, '体育课上，教师反复强调按动作要领练习、不得擅自攀爬器械，并在旁组织保护；学生小林仍趁教师指导他人时违规攀爬摔伤。对这起事故，学校责任的认定主要看其（　）', '[["A","是否尽到了教育、管理和保护职责"],["B","学生成绩是否优秀"],["C","班级人数多少"],["D","事故是否发生在校内"]]', '["A"]', '学校对学生伤害事故承担的是与其过错相应的责任，判断关键在于学校是否尽到了教育、管理和保护职责，而不是只看是否发生在校内。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2772, 57, 71, 'single', 1.0, '体育课跳远教学中，教师未检查沙坑便组织练习，学生小满落地时因沙坑板结、石块未清理而摔伤。对学校责任的认定，正确的是（　）', '[["A","学校未尽到教育、管理和安全保障职责，应当依法承担相应责任"],["B","跳远属于正常体育活动，无论学校有无过错都一律免责"],["C","损害发生在学生身上，应由小满及其监护人自行承担全部损失"],["D","应由上课教师个人承担全部赔偿，与学校无关"]]', '["A"]', '学校组织体育教学负有场地器材安全检查等教育、管理职责。沙坑板结、存有石块而未清理，说明学校未尽相应安全保障义务，对损害发生存在过错。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2773, 57, 72, 'single', 1.0, '教师对学校作出的处分不服，向教育行政部门提出申诉。教育行政部门依法应当在接到申诉的一定期限内作出处理，该期限是（　）', '[["A","七日内"],["B","十五日内"],["C","六个月内"],["D","三十日内"]]', '["D"]', '《教师法》第三十九条规定，教师认为学校侵犯其合法权益或对学校处理不服，向教育行政部门提出申诉的，教育行政部门应当在接到申诉的三十日内作出处理。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2774, 57, 73, 'single', 1.0, '家长因孩子被同学打伤，对学校的处理和赔偿方案不服，准备通过法律途径解决。下列属于解决教育法律纠纷、寻求权利救济的合法途径的是（　）', '[["A","在校门口拉横幅围堵校门"],["B","协商、调解、申诉、仲裁和诉讼"],["C","在网络上公布对方未成年人隐私"],["D","以拒绝其他学生上课相要挟"]]', '["B"]', '教育法律救济的主要途径包括协商和解、调解、教育行政申诉、仲裁和诉讼，公民应依法理性维权。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2775, 57, 74, 'single', 1.0, '家长会上，有家长私下递给祁老师一张购物卡，请其对自己孩子“多关照”。祁老师当场婉拒，并表示会公平关爱每一个学生。祁老师践行的师德规范主要是（　）', '[["A","利用职务之便谋取私利"],["B","只关注升学率"],["C","为人师表、廉洁从教"],["D","把学生分成三六九等"]]', '["C"]', '《中小学教师职业道德规范》要求教师为人师表，坚守高尚情操，廉洁奉公，自觉抵制有偿家教，不利用职务之便谋取私利。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2776, 57, 75, 'single', 1.0, '备课时，宗老师不满足于沿用旧教案，主动参加区域教研、学习新的教学方法并尝试改进自己的课堂。这集中体现了《中小学教师职业道德规范》中的（　）', '[["A","有偿补课"],["B","体罚学生"],["C","终身学习"],["D","违规收受礼品"]]', '["C"]', '终身学习要求教师崇尚科学精神，树立终身学习理念，拓宽知识视野、更新知识结构，潜心钻研业务、不断提高专业素养和教育教学水平。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2777, 57, 76, 'single', 1.0, '学校开展师德专题学习，强调教师在教育教学中要把立德树人作为根本任务，自觉做学生健康成长的引路人。“立德树人”是教育的（　）', '[["A","唯一升学率指标"],["B","根本任务"],["C","学校的全部行政事务"],["D","与教师无关的口号"]]', '["B"]', '党的十八大、十九大和全国教育大会反复强调，要全面贯彻党的教育方针，落实立德树人根本任务，培养德智体美劳全面发展的社会主义建设者和接班人。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2778, 57, 77, 'single', 1.0, '2022年颁布、其后持续推进落实的课程方案和课程标准，被一线教师称为“新课标”。与旧课标相比，新课标最突出的标志性变化是（　）', '[["A","取消所有学科知识"],["B","以升学率为唯一导向"],["C","只强调机械记忆"],["D","以核心素养为导向"]]', '["D"]', '2022年版义务教育课程方案和课程标准以核心素养为导向，强化课程育人功能，注重跨学科主题学习和学业质量标准，推动教学从知识本位转向素养本位。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2779, 57, 78, 'single', 1.0, '某校课后服务中引入一款学习软件，能根据学生的答题数据推送分层练习。教师在使用时坚持：技术只用于辅助诊断和推送，学习目标确定、价值引导和情感关怀仍由教师负责。这一做法体现的理念是（　）', '[["A","人工智能辅助教学，教师发挥主导作用"],["B","用人工智能完全取代教师"],["C","技术比教育规律更重要"],["D","学生只与机器交互即可"]]', '["A"]', '推进教育数字化、利用人工智能辅助教学，目的在于赋能教师、因材施教；技术是手段而非目的，育人方向、价值引领和情感沟通必须由教师把握，人工智能不能替代教师。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2780, 57, 79, 'single', 1.0, '“双减”政策实施后，学校提高课堂教学效率、丰富课后服务供给，同时规范作业总量。这一政策的完整名称是（　）', '[["A","取消一切课外学习活动"],["B","减轻学生所有考试负担"],["C","减轻教师全部工作负担"],["D","减轻义务教育阶段学生作业负担和校外培训负担"]]', '["D"]', '2021年中共中央办公厅、国务院办公厅印发的“双减”文件，全称为《关于进一步减轻义务教育阶段学生作业负担和校外培训负担的意见》。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2781, 57, 80, 'single', 1.0, '教师评价改革中，不再简单以升学率和学生考试成绩评价教师，而是突出教书育人实绩和师德师风第一标准。这一导向集中体现了新时代教师队伍建设强调的（　）', '[["A","只看教师论文发表数量"],["B","把分数作为教师考核唯一依据"],["C","把师德师风作为评价教师第一标准"],["D","以升学率高低决定教师去留"]]', '["C"]', '《关于全面深化新时代教师队伍建设改革的意见》等文件强调，把师德师风作为评价教师队伍素质的第一标准，改革唯分数、唯升学的教师评价，突出教书育人实绩。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2782, 57, 81, 'multi', 1.6, '学校组织“走进天府农业园”研学，学生分组观察农作物生长、访谈农技人员、完成小型调查报告，最后回校展示交流。这一活动体现的教学原则有（　）', '[["A","让学生在亲身实践中获得直接经验"],["B","以真实任务为载体，实现理论与实际的联系"],["C","教师在学生遇到困难时给予必要的方法指导"],["D","在调查、访谈、汇报中培养合作与表达能力"],["E","把课堂局限于教材，排斥一切校外资源"]]', '["A","B","C","D"]', '研学活动让学生亲身观察、访谈、调查，体现理论联系实际原则和以直接经验促进理解的要求；分组协作完成任务与展示，有助于培养合作和表达能力；学生自主实践并不排斥教师在方法上的适时指导。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2783, 57, 82, 'multi', 1.6, '某校课程改革中，既保证国家课程开齐开足，又组织教师编写《本地非遗·蜀锦》校本读本，开设跨学科的“城市水环境”主题学习。这些做法体现了（　）', '[["A","国家、地方、学校三级课程管理"],["B","课程内容加强与学生生活和社会实际的联系"],["C","校本课程可取代国家课程的主体地位"],["D","通过跨学科主题学习推进课程综合化"],["E","学校可以任意删减国家规定课程"]]', '["A","B","D"]', '开齐开足国家课程的同时开发校本读本、开展跨学科主题学习，体现三级课程管理体制、课程联系生活实际以及课程综合化方向。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2784, 57, 83, 'multi', 1.6, '班主任发现学生因班干部轮换、座位调整出现小矛盾，便组织“我为班级出主意”讨论，引导学生在倾听、协商中达成共识，并据此完善班规。这一过程体现的德育原则与方法有（　）', '[["A","尊重信任学生与严格要求相结合"],["B","通过集体讨论进行自我教育"],["C","以正面疏导、说服教育为主"],["D","遇到矛盾一律用处分压制解决"],["E","只重口头说教，不让学生参与管理"]]', '["A","B","C"]', '班主任在尊重学生、引导协商的基础上完善规则，体现尊重信任与严格要求相结合；通过集体讨论让学生自我教育，运用了说服与疏导的方法。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2785, 57, 84, 'multi', 1.6, '下列关于教师劳动特点的表述，与“十年树木，百年树人”这一古语所反映的特点相符的是（　）', '[["A","种下树苗要多年才成材，学生成长同样需要长时间培育"],["B","教师今天的教诲，可能影响学生很久以后的人生选择"],["C","学生一毕业，教师的影响就立刻消失"],["D","学生是否成才，只需看一次考试的结果"],["E","教师要年复一年耐心投入，不能追求短期速成"]]', '["A","B","E"]', '“十年树木，百年树人”以种树喻育人，说明人的成长需要长期培育、见效缓慢，教师的教诲对学生影响深远，育人工作必须年复一年耐心投入、不能追求短期速成。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2786, 57, 85, 'multi', 1.6, '学生在物理实验中多次失败后产生畏难情绪，一进实验室就想回避。教师要帮助他重新树立信心、恢复尝试行为，依据行为主义学习理论，可行的做法有（　）', '[["A","先布置他能完成的简单操作，成功后及时肯定"],["B","循序渐进提高任务难度，使其不断获得成功体验"],["C","当众嘲讽其失败，以激发其自尊心"],["D","对任何微小进步都不予反馈"],["E","帮助其在尝试中用新的成功体验替代回避反应"]]', '["A","B","E"]', '依据操作性条件作用和行为塑造原理，应通过小步子任务、及时正强化和连续接近培养目标行为，让学生在成功体验中恢复自信、消退回避反应。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2787, 57, 86, 'multi', 1.6, '面对考试失利，不同学生反应各异。教师运用韦纳归因理论进行引导，下列归因方式中有利于增强后续学习动机的有（　）', '[["A","把成功归于努力，失败时看到努力还不够"],["B","认识到学习方法可以调整改进"],["C","把每次失败都归于自己天生能力差"],["D","认为一切只取决于运气好坏"],["E","把成功稳定地归于题目太简单"]]', '["A","B"]', '韦纳认为努力是内部、不稳定、可控因素，方法策略也可由学生调控，引导学生归因于努力和方法，能增强坚持性和动机。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2788, 57, 87, 'multi', 1.6, '为提高复习效率，晓韵把单元知识画成思维导图，列出知识点间的上下位关系；对易混概念则列表比较异同，并在自测后专门补练错题。她运用的学习策略包括（　）', '[["A","组织策略中的归类和纲要"],["B","对易混内容进行比较的精加工"],["C","自测只是重复记忆，不属于任何学习策略"],["D","不加理解地反复机械抄写"],["E","把全部学习任务交给他人完成"]]', '["A","B"]', '画思维导图、梳理上下位关系属于组织策略；列表比较易混概念以加深理解属于精细加工。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2789, 57, 88, 'multi', 1.6, '学校开展心理健康教育时，下列做法符合科学性与规范性要求的有（　）', '[["A","面向全体学生开设发展性心理健康课程"],["B","对筛查中发现高低估号的学生及时启动危机干预"],["C","严格保护学生在辅导中披露的个人隐私"],["D","把心理测评结果随意公开排名"],["E","用思想品德教育完全替代专业心理辅导"]]', '["A","B","C"]', '学校心理健康教育应面向全体、坚持发展与预防并重，对高危个体及时干预，并严格遵守保密原则。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2790, 57, 89, 'multi', 1.6, '某校规范办学行为时，下列做法中符合现行教育法律法规的有（　）', '[["A","对违规违纪学生以批评教育和合规惩戒相结合"],["B","建立学生申诉渠道，认真听取学生陈述申辩"],["C","因学生成绩差而责令其转学或退学"],["D","公开学生个人及家庭隐私以示惩戒"],["E","对学生实施符合规定限度、不侮辱人格的教育惩戒"]]', '["A","B","E"]', '学校应坚持教育与惩戒相结合、过罚相当，保障学生陈述申辩和申诉权利，惩戒不得侮辱人格尊严。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2791, 57, 90, 'multi', 1.6, '在人工智能教学工具进入校园的背景下，教师恰当使用技术的做法有（　）', '[["A","利用数据分析发现学情，改进因材施教"],["B","坚持由教师把握育人方向和价值引领"],["C","让算法自动生成的评语完全替代师生交流"],["D","以保护学生数据安全和隐私为使用前提"],["E","用技术包办全部教学，放弃专业判断"]]', '["A","B","D"]', '人工智能应服务于学情诊断和因材施教，育人方向、价值引领与情感沟通必须由教师承担，使用过程中还须保护学生数据安全和隐私。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2792, 58, 1, 'judge', 0.6, '加里培林认为，心智技能的形成从活动的定向阶段开始，依次经过物质或物质化活动、出声的外部言语、无声的外部言语，最后达到内部言语阶段。', '[["A","正确"],["B","错误"]]', '["A"]', '加里培林心智技能五阶段：活动定向 → 物质/物质化活动 → 出声外部言语 → 无声外部言语 → 内部言语。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2793, 58, 2, 'judge', 0.6, '《中华人民共和国义务教育法》规定，县级以上人民政府及其教育行政部门应当促进学校均衡发展，缩小学校之间办学条件的差距，不得将学校分为重点学校和非重点学校，学校不得分设重点班和非重点班。', '[["A","正确"],["B","错误"]]', '["A"]', '《义务教育法》第二十二条明确规定，县级以上人民政府及其教育行政部门应当促进学校均衡发展，缩小学校之间办学条件的差距，不得将学校分为重点学校和非重点学校，学校不得分设重点班和非重点班。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2794, 58, 3, 'judge', 0.6, '2026年《政府工作报告》将"劳动年龄人口平均受教育年限达到11.7年"列为"十五五"时期的发展目标之一。', '[["A","正确"],["B","错误"]]', '["A"]', '2026年《政府工作报告》将“劳动年龄人口平均受教育年限达到 11.7 年”列入“十五五”发展目标。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2795, 58, 4, 'judge', 0.6, '科尔伯格将儿童道德发展划分为三水平六阶段，其中前习俗水平以惩罚与服从定向和工具性相对主义定向为特征。', '[["A","正确"],["B","错误"]]', '["A"]', '科尔伯格三水平六阶段：前习俗（惩罚服从、工具性相对主义）、习俗（好孩子、维护权威）、后习俗（社会契约、普遍伦理）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2796, 58, 5, 'judge', 0.6, '《中小学教育惩戒规则（试行）》规定，教师在教育教学管理、实施教育惩戒过程中，不得有以击打、刺扎等方式直接造成身体痛苦的体罚行为。', '[["A","正确"],["B","错误"]]', '["A"]', '《中小学教育惩戒规则（试行）》第十五条明确禁止体罚与变相体罚，规定教师在实施教育惩戒过程中不得有以击打、刺扎等方式直接造成身体痛苦的体罚行为。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2797, 58, 6, 'judge', 0.6, '马斯洛认为，只有当低一级的需要得到完全满足后，高一级的需要才会产生并支配行为。', '[["A","正确"],["B","错误"]]', '["B"]', '马斯洛需要层次为相对优势需要，低一级需要“基本满足”而非“完全满足”后，高一级需要才占主导。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2798, 58, 7, 'judge', 0.6, '桑代克认为，学习是通过尝试与错误逐步建立刺激—反应联结的过程，并提出了效果律、练习律和准备律。', '[["A","正确"],["B","错误"]]', '["A"]', '桑代克试误说：学习是形成刺激—反应联结，三大定律为效果律、练习律、准备律。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2799, 58, 8, 'judge', 0.6, '场依存型认知风格的学习者较多受外部环境、社会线索和同伴影响，对人文学科更感兴趣。', '[["A","正确"],["B","错误"]]', '["A"]', '场依存型易受外部环境与同伴影响，偏好人文社科；场独立型偏好自然科学、善于独立思考。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2800, 58, 9, 'judge', 0.6, '元认知是个体对认知的认知，包括对认知过程的计划、监控和调节。', '[["A","正确"],["B","错误"]]', '["A"]', '元认知即"对认知的认知"，含计划、监控、调节，是元认知策略（如设置目标、自我提问）的基础。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2801, 58, 10, 'judge', 0.6, '陈述性知识回答“怎么做”，程序性知识回答“是什么”。', '[["A","正确"],["B","错误"]]', '["B"]', '陈述性知识回答"是什么"（事实、概念），程序性知识回答"怎么做"（技能、步骤），题干颠倒二者。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2802, 58, 11, 'judge', 0.6, '复述策略是通过反复识记来保持信息，如抄写、画线、背诵等，它能够对学习材料进行深层加工并建立与已有知识的联系。', '[["A","正确"],["B","错误"]]', '["B"]', '复述策略只是在工作记忆中通过重复（抄写、画线、背诵）保持信息，属浅层加工，并不能对材料作深层加工，也不能建立新旧知识之间的联系——那是精细加工策略与组织策略的功能。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2803, 58, 12, 'judge', 0.6, '技能形成过程中，练习到一定阶段常出现成绩暂时停滞不前的“高原现象”，并不意味着能力已达极限。', '[["A","正确"],["B","错误"]]', '["A"]', '高原现象是技能形成中练习到一定阶段成绩暂时停滞，多因方法固定或身心疲劳，调整策略可突破，非能力极限。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2804, 58, 13, 'judge', 0.6, '注意的转移是个体根据任务需要主动将注意从一个对象转向另一个对象，不同于注意的分散。', '[["A","正确"],["B","错误"]]', '["A"]', '注意的转移是主动、有目的调动；注意的分散（分心）是无关刺激干扰下的被动偏离，二者性质不同。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2805, 58, 14, 'judge', 0.6, '《新时代中小学教师职业行为十项准则》要求教师带头践行社会主义核心价值观，不得通过课堂、网络等渠道发表损害党和国家形象的言论。', '[["A","正确"],["B","错误"]]', '["A"]', '《新时代中小学教师职业行为十项准则》"坚定政治方向"要求带头践行社会主义核心价值观，不得发表损害党和国家形象的言论。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2806, 58, 15, 'judge', 0.6, '皮亚杰认为，形式运算阶段的儿童能够进行假设一演绎推理，思维已超越具体事物的束缚。', '[["A","正确"],["B","错误"]]', '["A"]', '形式运算阶段（11 岁以上）能进行假设—演绎推理，思维超越具体事物。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2807, 58, 16, 'judge', 0.6, '埃里克森认为，青少年期（12—18岁）的核心发展任务是形成自我同一性，克服角色混乱。', '[["A","正确"],["B","错误"]]', '["A"]', '埃里克森：青少年期（12—18 岁）核心冲突为自我同一性对角色混乱。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2808, 58, 17, 'judge', 0.6, '维果斯基所说的"最近发展区"，是指儿童目前已经达到的发展水平。', '[["A","正确"],["B","错误"]]', '["B"]', '最近发展区是现有水平与即将达到的潜在水平之间的差距，不是已达到的水平。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2809, 58, 18, 'judge', 0.6, '学习动机越强，学习效果就越好，因此教师应当尽可能激发学生的高动机水平。', '[["A","正确"],["B","错误"]]', '["B"]', '耶克斯—多德森定律：动机强度与效率呈倒 U 型，中等强度最佳，且任务难度不同最佳水平不同。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2810, 58, 19, 'judge', 0.6, '负强化就是向个体施加厌恶刺激以降低反应发生的概率，其实质等同于惩罚。', '[["A","正确"],["B","错误"]]', '["B"]', '负强化是移除厌恶刺激以提高反应概率；惩罚才是降低反应概率。二者性质相反。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2811, 58, 20, 'judge', 0.6, '学习迁移是指一种学习对另一种学习的影响，这种影响总是积极的，能够促进后续学习。', '[["A","正确"],["B","错误"]]', '["B"]', '迁移按效果分为正迁移（促进）与负迁移（干扰），按方向又有顺向与逆向之分，既有积极作用也可能产生干扰。题干以“总是积极的、能够促进后续学习”作单一化断定（以偏概全）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2812, 58, 21, 'judge', 0.6, '奥苏贝尔认为，有意义学习的实质是新知识与学习者认知结构中已有观念建立非人为的、实质性的联系。', '[["A","正确"],["B","错误"]]', '["A"]', '奥苏贝尔：有意义学习的实质是新旧知识建立非人为的、实质性的联系。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2813, 58, 22, 'judge', 0.6, '学校心理辅导的对象应当严格限定为已经出现心理问题的少数学生。', '[["A","正确"],["B","错误"]]', '["B"]', '学校心理辅导面向全体学生，以发展性辅导为主、矫治性辅导为辅。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2814, 58, 23, 'judge', 0.6, '《中华人民共和国预防未成年人犯罪法》规定，未成年人的父母或者其他监护人对未成年人的预防犯罪教育负有直接责任，应当依法履行监护职责。', '[["A","正确"],["B","错误"]]', '["A"]', '《中华人民共和国预防未成年人犯罪法》第十六条规定，未成年人的父母或者其他监护人对未成年人的预防犯罪教育负有直接责任，应当依法履行监护职责、树立优良家风、培养未成年人良好品行。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2815, 58, 24, 'judge', 0.6, '教师对学校处理决定不服提出申诉的，应当向同级人民政府提出。', '[["A","正确"],["B","错误"]]', '["B"]', '教师申诉应向教育行政部门提出，而非向同级人民政府提出。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2816, 58, 25, 'judge', 0.6, '对严重违反校规校纪的义务教育阶段学生，学校经校长办公会讨论后可以给予开除学籍处分。', '[["A","正确"],["B","错误"]]', '["B"]', '义务教育阶段学校不得开除学生，对严重违纪学生以批评教育、专门教育等方式处理。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2817, 58, 26, 'judge', 0.6, '《中小学教育惩戒规则（试行）》明确，教育惩戒是指学校、教师基于教育目的，对违规违纪学生进行管理、训导或者以规定方式予以矫治，促使学生引以为戒、认识和改正错误的教育行为。', '[["A","正确"],["B","错误"]]', '["A"]', '该规则第二条规定，教育惩戒是指学校、教师基于教育目的，对违规违纪学生进行管理、训导或者以规定方式予以矫治，促使学生引以为戒、认识和改正错误的教育行为，其性质是教育行为而非惩罚本身。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2818, 58, 27, 'judge', 0.6, '根据《中华人民共和国民法典》，不满八周岁的未成年人为限制民事行为能力人。', '[["A","正确"],["B","错误"]]', '["B"]', '《民法典》第十九条、第二十条：八周岁以上为限制民事行为能力人，不满八周岁为无民事行为能力人；题干将二者混淆。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2819, 58, 28, 'judge', 0.6, '《中华人民共和国教师法》规定，国家实行教师资格制度；中国公民凡遵守宪法和法律、热爱教育事业、具备相应学历或者经国家教师资格考试合格、有教育教学能力，经认定合格的，可以取得教师资格。', '[["A","正确"],["B","错误"]]', '["A"]', '《中华人民共和国教师法》第十条规定，国家实行教师资格制度；中国公民凡遵守宪法和法律、热爱教育事业、具备相应学历或者经国家教师资格考试合格、有教育教学能力，经认定合格的，可以取得教师资格。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2820, 58, 29, 'judge', 0.6, '关爱学生是教师职业道德的灵魂，要求教师平等公正对待学生，不讽刺、挖苦、歧视学生。', '[["A","正确"],["B","错误"]]', '["A"]', '关爱学生是师德的灵魂，要求平等公正对待学生，不讽刺、挖苦、歧视。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2821, 58, 30, 'judge', 0.6, '《教育强国建设规划纲要（2024—2035年）》提出，实施新时代立德树人工程，健全德智体美劳全面培养体系。', '[["A","正确"],["B","错误"]]', '["A"]', '《教育强国建设规划纲要（2024—2035年）》提出实施新时代立德树人工程，健全德智体美劳全面培养体系。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2822, 58, 31, 'single', 1.0, '小宇背诵英语单词后，第一天就忘掉大半，此后几天遗忘速度明显减慢。依据艾宾浩斯遗忘曲线，其遗忘进程表现为（　）', '[["A","先快后慢、先多后少"],["B","先慢后快、先少后多"],["C","匀速推进、无明显快慢"],["D","仅在睡眠期间发生遗忘"]]', '["A"]', '艾宾浩斯遗忘曲线：遗忘进程不均衡，总体先快后慢、先多后少，后期趋缓；及时复习据此设计。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2823, 58, 32, 'single', 1.0, '小妍在物理测验中遇到难题时，总相信自己换个方法就能解出，因而愿意多花时间钻研。班杜拉认为个体对自己能否成功完成某一任务的信心会影响其学习动机与坚持性，这种信心被称为（　）', '[["A","自我同一性"],["B","自我效能感"],["C","自我概念"],["D","自我监控"]]', '["B"]', '班杜拉社会学习理论。自我效能感——个体对自己能否成功完成某一任务的信心，影响任务选择、学习动机与坚持性。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2824, 58, 33, 'single', 1.0, '李老师在“教育思想史”备课中向学生介绍：在世界教育史上首次明确提出“教育心理学化”主张的教育家是（　）', '[["A","赫尔巴特"],["B","裴斯泰洛齐"],["C","福禄贝尔"],["D","第斯多惠"]]', '["B"]', '裴斯泰洛齐首次明确提出“教育心理学化”；赫尔巴特将其理论化；福禄贝尔为“幼儿园之父”；第斯多惠提出“一个坏的教师奉送真理，一个好的教师教人发现真理”。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2825, 58, 34, 'single', 1.0, '小浩在竞赛报名时，十分犹豫：既渴望获奖带来的荣誉，又担心失利被同学笑话。按阿特金森的成就动机理论，个体的成就动机由哪两种倾向共同决定（　）', '[["A","追求成功的倾向与避免失败的倾向"],["B","生理需要与安全需要"],["C","本我与超我"],["D","同化与顺应"]]', '["A"]', '阿特金森成就动机理论：成就动机由力求成功与避免失败两种倾向合成，此消彼长决定行为表现。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2826, 58, 35, 'single', 1.0, '初二学生小奇多次结伙斗殴、屡教不改，某县教育局拟对其采取专门教育矫治措施。依据《中华人民共和国预防未成年人犯罪法》，应当将其送入的场所是（　）', '[["A","收容教养所"],["B","社区矫正机构"],["C","特殊教育学校"],["D","专门学校"]]', '["D"]', '《预防未成年人犯罪法》规定对有严重不良行为的未成年人送入专门学校进行专门教育矫治；收容教养所已废止。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2827, 58, 36, 'single', 1.0, '张老师课堂上多次当众讽刺、挖苦学习困难的学生，并称“笨得无药可救”，该教师的行为主要违反的准则是（　）', '[["A","关心爱护学生"],["B","坚守廉洁自律"],["C","潜心教书育人"],["D","规范从教行为"]]', '["A"]', '“关心爱护学生”要求平等公正对待学生、不讽刺挖苦歧视；当众羞辱直接违反该准则，亦违背教书育人。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2828, 58, 37, 'single', 1.0, '王老师在教"圆的面积"时，先让学生把圆形纸片剪开、拼成近似的长方形，再引导他们由长方形面积公式推出圆的面积公式。这一做法主要体现的教学原则是（　）', '[["A","启发性原则"],["B","巩固性原则"],["C","直观性原则"],["D","循序渐进原则"]]', '["C"]', '利用实物、模象或语言形象使学生在感知基础上形成表象，属直观性；启发性强调用设问引导思维；巩固性强调复习；循序渐进强调按学科逻辑与学生认识顺序。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2829, 58, 38, 'single', 1.0, '陈老师在化学课上让学生利用仪器设备进行操作、观察现象、获取数据并得出结论，该教师采用的教学方法属于（　）', '[["A","演示法"],["B","实验法"],["C","参观法"],["D","练习法"]]', '["B"]', '实验法——学生在教师指导下操作仪器、观察现象并得出结论；演示法是教师做、学生看；参观法是到实地观察；练习法侧重巩固技能。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2830, 58, 39, 'single', 1.0, '某校实行"大班上课、小班研究、个别作业"相结合的教学组织形式。这一形式被称为（　）', '[["A","道尔顿制"],["B","文纳特卡制"],["C","分组教学制"],["D","特朗普制"]]', '["D"]', '大班上课、小班研究、个别作业相结合即特朗普制；道尔顿制强调学生自学、订立公约；文纳特卡制分个别教学与团体活动两部分；分组教学按能力或兴趣分组。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2831, 58, 40, 'single', 1.0, '李老师在单元教学中进行随堂小测，并据此调整后续教学内容与进度。这种评价属于（　）', '[["A","诊断性评价"],["B","总结性评价"],["C","相对性评价"],["D","形成性评价"]]', '["D"]', '过程中实施、用于调整教学的为形成性评价；诊断性评价在教学前进行（摸底）；总结性评价在教学结束后进行；相对性评价是在群体中比较位置。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2832, 58, 41, 'single', 1.0, '刘老师发现小唐沉迷网络游戏，没有简单禁止，而是让他担任班级“信息技术管理员”，负责维护班级电脑，并逐步引导他把兴趣转向编程学习。刘老师主要贯彻的德育原则是（　）', '[["A","依靠积极因素、克服消极因素（长善救失）"],["B","疏导原则"],["C","严格要求与尊重学生相结合"],["D","知行统一原则"]]', '["A"]', '把学生网络兴趣转化为信息技术特长，是利用积极因素克服消极因素（长善救失）；疏导原则强调因势利导、以理服人，虽相关但本题突出“转化消极因素”，以长善救失为最优。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2833, 58, 42, 'single', 1.0, '某校在国家课程之外，结合本地非物质文化遗产资源开发了“剪纸”“皮影”等课程，供学生自主选择修习。这类课程属于（　）', '[["A","国家课程"],["B","地方课程"],["C","校本课程"],["D","综合课程"]]', '["C"]', '校本课程是以学校为开发主体、结合本校与本地资源自主开发的课程，供学生选择修习；国家课程由中央教育行政部门统一规划，地方课程由省级教育行政部门开发，综合课程按内容整合方式划分。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2834, 58, 43, 'single', 1.0, '周老师在德育课上设置情境，让学生通过角色扮演“设身处地为他人着想”，学会体谅与关心，该教师的做法所依据的德育模式是（　）', '[["A","认知模式"],["B","体谅模式"],["C","社会模仿模式"],["D","价值澄清模式"]]', '["B"]', '麦克费尔的体谅模式以培养体谅他人为核心，采用角色扮演、情境体验；认知模式（皮亚杰、科尔伯格）重道德判断发展；社会模仿模式（班杜拉）重观察学习；价值澄清模式重价值选择与评价。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2835, 58, 44, 'single', 1.0, '班主任工作的中心环节是（　）', '[["A","了解和研究学生"],["B","做好个别教育工作"],["C","组织培养班集体"],["D","协调各方面教育力量"]]', '["C"]', '组织和培养班集体是中心环节；了解和研究学生是前提与基础；个别教育与协调力量是常规工作。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2836, 58, 45, 'single', 1.0, '某班已涌现出一批积极分子，班干部基本能独立主持班级日常工作，班级舆论逐步形成。该班集体发展所处的阶段是（　）', '[["A","组建阶段"],["B","发展阶段"],["C","核心形成阶段"],["D","成熟阶段"]]', '["B"]', '组建阶段（班主任主导）→ 核心形成阶段（积极分子涌现）→ 发展阶段（班干部能独立主持工作、舆论形成）→ 成熟阶段（良好班风稳定）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2837, 58, 46, 'single', 1.0, '课堂上学生突然提出一个预设之外的问题，王老师顺势调整教学思路，将其转化为教学资源，该教师的做法主要体现其专业（　）', '[["A","知识"],["B","理念"],["C","态度与动机"],["D","能力（教育机智）"]]', '["D"]', '王老师顺势转化课堂突发问题，体现教育机智，属专业能力范畴；专业知识指导科与教育理论；专业理念是认识层面；专业态度与动机属情意层面。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2838, 58, 47, 'single', 1.0, '张老师要求学生不迟到，自己却经常踩着铃声进教室，学生渐渐效仿其散漫作风。校长在点评此事时，引用“其身正，不令而行；其身不正，虽令不从”，说明教师劳动具有（　）', '[["A","示范性"],["B","复杂性"],["C","创造性"],["D","长期性"]]', '["A"]', '张老师自身迟到被学生效仿、校长引“其身正”点评，考查示范性即“以身立教”；复杂性指对象与任务多维；创造性指因材施教与教育机智；长期性指人才培养周期长。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2839, 58, 48, 'single', 1.0, '“狼孩”卡玛拉被发现时已七八岁，回到人类社会后经过多年训练仍难以掌握人类语言。这一案例主要说明个体身心发展具有（　）', '[["A","不平衡性（存在发展关键期）"],["B","顺序性"],["C","阶段性"],["D","个别差异性"]]', '["A"]', '狼孩案例说明错过关键期后发展难以弥补，属不平衡性；顺序性强调由低级到高级；阶段性强调年龄特征不同；个别差异性强调人与人不同。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2840, 58, 49, 'single', 1.0, '王老师在讲授科学知识的同时，引导学生形成严谨求实的态度和正确的价值观，该教师的做法体现的教学过程规律是（　）', '[["A","间接性规律（间接经验与直接经验相统一）"],["B","教育性规律（传授知识与思想教育相统一）"],["C","发展性规律（掌握知识与发展能力相统一）"],["D","双边性规律（教师主导与学生主体相统一）"]]', '["B"]', '王老师讲知识的同时引导态度与价值观，考查传授知识与思想教育相统一（教育性）；间接性指以间接经验为主；发展性指掌握知识与发展能力统一；双边性指师生双方作用统一。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2841, 58, 50, 'single', 1.0, '以预先确定的教育目标为中心，通过评价判断实际活动达成目标程度的课程评价模式是（　）', '[["A","目标评价模式"],["B","目的游离评价模式"],["C","CIPP 评价模式"],["D","CSE 评价模式"]]', '["A"]', '泰勒目标评价模式以预定目标为中心；斯克里文目的游离模式关注实际效应而非预期目标；CIPP 含背景、输入、过程、成果四环节；CSE 为加州评价模式。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2842, 58, 51, 'single', 1.0, '某县财政局在编制年度预算时，拟按低于财政经常性收入增长的幅度安排教育经费，被县人大依法纠正。依据《中华人民共和国教育法》，各级人民政府教育财政拨款的增长应当（　）', '[["A","低于财政经常性收入的增长"],["B","与财政经常性收入的增长持平"],["C","高于财政经常性收入的增长"],["D","由学校自主决定，不受财政约束"]]', '["C"]', '《中华人民共和国教育法》第五十五条第二款规定，各级人民政府教育财政拨款的增长应当高于财政经常性收入的增长，并使按在校学生人数平均的教育费用逐步增长。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2843, 58, 52, 'single', 1.0, '某县在编制教育事业发展规划时，需明确我国现行学制所属的形态。从学制形态看，我国现行学制属于（　）', '[["A","双轨制"],["B","分支型学制"],["C","单轨制"],["D","混合制"]]', '["B"]', '我国现行学制属分支型（前段单轨、后段分岔）；双轨制以欧洲传统为代表；单轨制以美国为代表；混合制非规范表述。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2844, 58, 53, 'single', 1.0, '教师在新课开始时，先呈现一段比新知识更上位、更概括的引导性材料，为学习新知识提供“固定点”。这种策略属于（　）', '[["A","支架式教学"],["B","抛锚式教学"],["C","先行组织者"],["D","随机通达教学"]]', '["C"]', '奥苏贝尔提出先行组织者，即先于学习任务呈现的引导性材料；支架式为维果斯基派生的教学支持；抛锚式以真实情境为“锚”；随机通达强调多角度进入同一内容。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2845, 58, 54, 'single', 1.0, '王老师针对本班学生作业拖沓的问题，边教学边研究、持续反思改进并撰写研究日志，该教师的做法属于（　）', '[["A","行动研究法"],["B","实验法"],["C","调查法"],["D","个案法"]]', '["A"]', '行动研究——教师为改进自身实践、边研究边反思；实验法需控制变量；调查法重现状收集；个案法针对单一对象作深入分析。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2846, 58, 55, 'single', 1.0, '小明能够脱离具体事物，对命题本身进行运算，并能进行假设一演绎推理。按皮亚杰的认知发展阶段理论，他处于（　）', '[["A","具体运算阶段"],["B","前运算阶段"],["C","形式运算阶段"],["D","感知运动阶段"]]', '["C"]', '能进行命题运算与假设—演绎推理属形式运算阶段（11岁以上）；具体运算阶段需具体事物支持；前运算阶段以自我中心为特征。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2847, 58, 56, 'single', 1.0, '某教师在课堂上依据学生的即时反应调整讲解的详略和练习的难度，使原定环节有所增删。这种做法主要体现的教学过程规律是（　）', '[["A","预设性与生成性相统一"],["B","间接经验与直接经验相统一"],["C","掌握知识与发展能力相统一"],["D","教师主导与学生主体相统一"]]', '["A"]', '教学既有预设的方案，又在师生互动中生成新的内容与走向。教师依课堂反应即时调整，体现预设性与生成性相统一。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2848, 58, 57, 'single', 1.0, '小宇为了在班级排名中超过同桌，近一个月来主动加练错题、提前预习。按奥苏贝尔的分类，驱动他学习的主要动机属于（　）', '[["A","认知内驱力"],["B","自我提高内驱力"],["C","附属内驱力"],["D","内部动机"]]', '["B"]', '自我提高内驱力——以赢得相应地位与自尊为目的；认知内驱力指向知识本身，附属内驱力指向获得长者赞许，内部动机与外部动机是另一分类维度。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2849, 58, 58, 'single', 1.0, '教师不直接给出结论，而是提供结构化材料，让学生自己探索、发现规律并得出结论。这种学习方式属于（　）', '[["A","接受学习"],["B","机械学习"],["C","程序学习"],["D","发现学习"]]', '["D"]', '布鲁纳倡导发现学习，让学生自主探索发现规律；接受学习（奥苏贝尔）为教师呈现、学生内化；机械学习无实质联系；程序学习靠机器小步子。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2850, 58, 59, 'single', 1.0, '张老师在教研组学习建构主义理论时，梳理出学习环境的四大要素应当是（　）', '[["A","强化、模仿、练习、反馈"],["B","情境、协作、会话、意义建构"],["C","感知、记忆、思维、想象"],["D","动机、兴趣、态度、意志"]]', '["B"]', '建构主义学习环境四大要素为情境、协作、会话、意义建构。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2851, 58, 60, 'single', 1.0, '罗杰斯主张学习应与学习者的个人经验、情感与需要相融合，强调“有意义的自由学习”。这一主张属于（　）', '[["A","行为主义"],["B","认知主义"],["C","建构主义"],["D","人本主义"]]', '["D"]', '罗杰斯“有意义的自由学习”属人本主义；行为主义重强化控制；认知主义重信息加工；建构主义重主动建构。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2852, 58, 61, 'single', 1.0, '小强考试失利后，对同学说“这次是我复习方法不对，下次换个方法再试”。按韦纳归因理论，小强的这一归因属于（　）', '[["A","内部的、不稳定的、可控的"],["B","内部的、稳定的、不可控的"],["C","外部的、不稳定的、不可控的"],["D","外部的、稳定的、可控的"]]', '["A"]', '归因于努力／策略属内部、不稳定、可控；能力为内部稳定不可控；运气为外部不稳定不可控；任务难度为外部稳定不可控。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2853, 58, 62, 'single', 1.0, '某校考核教师时，既看学生学业成绩的提升幅度，也看教师参与教研、开发校本课程以及家校沟通的情况。这种评价做法主要体现的原则是（　）', '[["A","客观性原则"],["B","指导性原则"],["C","全面性原则"],["D","差异性原则"]]', '["C"]', '全面性原则要求评价内容全面、评价主体多元、评价过程完整，不能只以学生学业成绩这一单项指标衡量教师工作。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2854, 58, 63, 'single', 1.0, '学生先掌握了平行四边形面积的计算，再学习三角形面积时发现更容易理解。这种影响属于（　）', '[["A","正迁移"],["B","负迁移"],["C","逆向迁移"],["D","零迁移"]]', '["A"]', '先前学习促进后续学习 = 正迁移；负迁移为干扰；顺向／逆向按方向划分；零迁移为无影响。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2855, 58, 64, 'single', 1.0, '小琳在复习时对材料进行类比、举例并尝试用自己的话重新表述，老师发现她的这种做法所属的学习策略类型是（　）', '[["A","复述策略"],["B","组织策略"],["C","元认知策略"],["D","精细加工策略"]]', '["D"]', '类比、举例、用自己的话重新表述，考查精细加工策略；复述是重复记忆；组织是归类列纲；元认知是对认知的监控调节。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2856, 58, 65, 'single', 1.0, '某校心理辅导教师接待了一名学生：他面对“用蜡烛将图钉固定在墙上”的问题时，始终想不到蜡烛盒本身可以作为平台，辅导教师据此判断这种心理现象属于（　）', '[["A","定势"],["B","原型启发"],["C","功能固着"],["D","迁移"]]', '["C"]', '只看到物体惯常功能、想不到新用途 = 功能固着；定势是先前活动形成的心理准备状态；原型启发是从他物获得解决思路；迁移是已有经验的影响。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2857, 58, 66, 'single', 1.0, '某学生能说出砖头可用于“砌墙”“铺路”“当武器”“做配重”“当垫脚石”等跨越多个类别的用途。这主要反映创造性思维的（　）', '[["A","流畅性"],["B","变通性"],["C","独创性"],["D","敏捷性"]]', '["B"]', '跨越多个类别的用途体现变通性（灵活性）；流畅性指短时间内数量多；独创性指新颖独特；敏捷性非核心特征。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2858, 58, 67, 'single', 1.0, '对害怕当众讲话的学生，辅导教师先教其放松训练，再让其按“在小组内发言一在全班发言一在全校发言”的层级逐步面对。这种方法属于（　）', '[["A","代币奖励法"],["B","系统脱敏法"],["C","榜样示范法"],["D","认知疗法"]]', '["B"]', '放松训练 + 逐级暴露 = 系统脱敏；代币奖励靠强化物积累；榜样示范靠观察学习；认知疗法矫正不合理信念。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2859, 58, 68, 'single', 1.0, '某校在制订育人方案时，校长强调要落实《中华人民共和国教育法》规定的教育方针：教育必须为社会主义现代化建设服务、为人民服务，必须与（　）相结合', '[["A","科学技术与文化传承"],["B","家庭教育与社会教育"],["C","理论教学与技能训练"],["D","生产劳动和社会实践"]]', '["D"]', '《教育法》方针：教育必须为社会主义现代化建设服务、为人民服务，必须与生产劳动和社会实践相结合。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2860, 58, 69, 'single', 1.0, '某小学以"影响班级管理"为由，拒绝接收具有接受普通教育能力的适龄残疾儿童随班就读。该校的做法主要违反了（　）', '[["A","《中华人民共和国教师法》"],["B","《中华人民共和国民法典》"],["C","《中华人民共和国义务教育法》"],["D","《中小学教育惩戒规则（试行）》"]]', '["C"]', '拒绝接收具有接受普通教育能力的适龄残疾儿童随班就读，违反《义务教育法》关于保障适龄儿童少年入学的规定，同时触犯《残疾人保障法》，本题以义务教育法为首要依据。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2861, 58, 70, 'single', 1.0, '某校周老师在参加专业学术团体时，还在学术会议上发表研究成果，校长对此表示支持，该教师行使的权利属于《教师法》规定的（　）', '[["A","教育教学权"],["B","指导评价权"],["C","民主管理权"],["D","科学研究权"]]', '["D"]', '周老师参加学术团体、发表成果获校长支持，考查科学研究权；教育教学权是开展教育教学活动；指导评价权是评价学生品行与成绩；民主管理权是对学校工作提意见。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2862, 58, 71, 'single', 1.0, '某校教师马某多次体罚学生、经教育不改，学校发现后拟依规处理。依据《中华人民共和国教师法》第三十七条，马某可能承担的法律后果是（　）', '[["A","由公安机关给予治安管理处罚"],["B","由所在学校或教育行政部门给予行政处分或者解聘"],["C","一律追究刑事责任"],["D","只需向家长赔礼道歉即可"]]', '["B"]', '《教师法》第三十七条：体罚学生经教育不改被发现，由学校或教育行政部门给予行政处分或者解聘；情节严重构成犯罪的才追究刑事责任；治安处罚与赔礼道歉均不足以覆盖。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2863, 58, 72, 'single', 1.0, '依据《中华人民共和国未成年人保护法》，对未成年人的保护体系包括家庭保护、学校保护、社会保护、网络保护、政府保护和（　）', '[["A","社区保护"],["B","自我保护"],["C","司法保护"],["D","媒体保护"]]', '["C"]', '六大保护 = 家庭、学校、社会、网络、政府、司法保护；社区、自我、媒体保护均非法定表述。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2864, 58, 73, 'single', 1.0, '依据《中小学教育惩戒规则（试行）》，下列属于教师可以当场实施的惩戒措施的是（　）', '[["A","停课一周反省"],["B","罚款充作班费"],["C","一节课堂教学时间内的教室内站立"],["D","责令家长到校陪读"]]', '["C"]', '教师当场实施的惩戒包括点名批评、责令道歉、多次罚站限于一节课堂教学时间内的教室内站立等；停课、罚款、责令家长陪读均不属于合法惩戒。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2865, 58, 74, 'single', 1.0, '校园伤害事故责任认定中，学校承担责任所适用的归责原则是（　）', '[["A","过错责任原则"],["B","无过错责任原则"],["C","公平责任原则"],["D","严格责任原则"]]', '["A"]', '学校有过错才承担责任 = 过错责任原则：无民事行为能力人受侵害时适用过错推定，但本题问一般原则；无过错与严格责任不适用于校园伤害；公平责任为补充。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2866, 58, 75, 'single', 1.0, '某校在开展法治教育时列举了若干学生行为，其中属于《中华人民共和国预防未成年人犯罪法》所称“严重不良行为”的是（　）', '[["A","结伙斗殴、寻衅滋事，扰乱治安"],["B","旷课、逃学"],["C","沉迷网络"],["D","吸烟、饮酒"]]', '["A"]', '结伙斗殴、寻衅滋事扰乱治安属严重不良行为；旷课逃学、沉迷网络、吸烟饮酒属不良行为。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2867, 58, 76, 'single', 1.0, '某县文化执法人员在检查校园周边场所时，就《中华人民共和国未成年人保护法》关于社会保护的规定作出下列判断，其中正确的是（　）', '[["A","营业性歌舞娱乐场所可以在征得未成年人家长同意后接纳未成年人进入"],["B","烟、酒销售网点虽可设在学校周边，但不得向未成年人出售烟酒"],["C","互联网上网服务营业场所经教育主管部门批准后可以接纳未成年人"],["D","博物馆、纪念馆、科技馆、美术馆等场所应当按照有关规定对未成年人免费或者优惠开放"]]', '["D"]', '《中华人民共和国未成年人保护法》第四十四条规定，爱国主义教育基地、图书馆、青少年宫、儿童活动中心、博物馆、纪念馆、科技馆、展览馆、美术馆、文化馆等场所，应当对未成年人免费或者优惠开放，属社会保护的重要内容。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2868, 58, 77, 'single', 1.0, '某校的黄老师只关注考试分数和升学率，对学生的品德养成与身心健康不闻不问，该教师的行为主要违背的师德规范是（　）', '[["A","爱国守法"],["B","终身学习"],["C","教书育人"],["D","为人师表"]]', '["C"]', '黄老师只重考试分数与升学率、忽视品德与身心健康，考查违背教书育人（遵循规律、素质教育、不以分数作为评价学生的唯一标准）；爱国守法侧依法执教；终身学习侧重专业发展。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2869, 58, 78, 'single', 1.0, '《教育强国建设规划纲要（2024—2035年）》提出，到（），教育强国建设取得重要阶段性成效；到2035年，建成教育强国。', '[["A","2029年"],["B","2027年"],["C","2030年"],["D","2035年"]]', '["B"]', '到2027年教育强国建设取得重要阶段性成效，到2035年建成教育强国。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2870, 58, 79, 'single', 1.0, '习近平总书记提出，广大教师要做学生“锤炼品格的引路人、学习知识的引路人、创新思维的引路人、（　）”。', '[["A","健康成长的引路人"],["B","终身学习的引路人"],["C","实践创新的引路人"],["D","奉献祖国的引路人"]]', '["D"]', '做学生锤炼品格、学习知识、创新思维、奉献祖国的引路人。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2871, 58, 80, 'single', 1.0, '某县教育局在部署学前教育普法宣传工作时，需明确《中华人民共和国学前教育法》正式施行的时间是（　）', '[["A","2024年9月1日"],["B","2026年1月1日"],["C","2023年3月1日"],["D","2025年6月1日"]]', '["D"]', '《中华人民共和国学前教育法》自2025年6月1日起施行。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2872, 58, 81, 'multi', 1.6, '依据教育学原理，下列对教学过程本质与规律的阐述能够成立的有（　）', '[["A","教学过程本质上是一种特殊的认识过程"],["B","教学过程须遵循间接经验与直接经验相统一的规律"],["C","教学过程的中心环节是运用知识，巩固知识可有可无"],["D","教学过程须遵循掌握知识与发展能力相统一的规律"],["E","教学过程须遵循传授知识与思想教育相统一的规律"]]', '["A","B","D","E"]', '“特殊的认识过程”、间接经验与直接经验相统一、掌握知识与发展能力相统一、传授知识与思想教育相统一，四项均正确。“巩固知识可有可无”项错：巩固知识是教学过程的基本环节之一。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2873, 58, 82, 'multi', 1.6, '课程存在多种分类维度，下列划分方式与其分类依据对应正确的有（　）', '[["A","隐性课程不属于课程的范畴，只是校园环境影响"],["B","校本课程的开发主体是地方教育行政部门"],["C","按课程内容属性，可分为学科课程与活动课程"],["D","按课程实施要求，可分为必修课程与选修课程"],["E","按课程呈现方式，可分为显性课程与隐性课程"]]', '["C","D","E"]', '按内容属性分学科课程与活动课程、按实施要求分必修与选修、按呈现方式分显性与隐性，三项标准与对应划分均正确。“隐性课程不属于课程范畴”项错；“校本课程开发主体是地方教育行政部门”项错：开发主体是学校。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2874, 58, 83, 'multi', 1.6, '下列学习动机理论的主张中，符合心理学研究结论的有（　）', '[["A","韦纳将成败归因划分为内外源、稳定性、可控性三个维度"],["B","阿特金森将成就动机分为力求成功的倾向与避免失败的倾向"],["C","班杜拉提出的自我效能感会影响个体的任务选择与坚持性"],["D","动机水平越高，学习效率必然越高"],["E","耶克斯一多德森定律表明动机强度与效率之间呈倒U型关系"]]', '["A","B","C","E"]', '韦纳三维归因、阿特金森成就动机二分、自我效能感影响任务选择与坚持性、耶克斯一多德森倒U型关系，四项均正确。“动机水平越高学习效率必然越高”项错。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2875, 58, 84, 'multi', 1.6, '影响学习迁移的主要因素包括（　）', '[["A","教师的学历层次与教龄"],["B","学习材料之间的共同要素"],["C","学习者对知识经验的概括水平"],["D","学校的硬件设施条件"],["E","学习者的认知结构与心向"]]', '["B","C","E"]', '学习材料的共同要素、学习者对知识经验的概括水平、学习者的认知结构与心向，均为公认的主要影响因素。“教师学历层次与教龄”“学校硬件设施条件”两项错。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2876, 58, 85, 'multi', 1.6, '依据《中华人民共和国教师法》，下列属于教师应当履行的义务的有（　）', '[["A","遵守宪法、法律和职业道德，为人师表"],["B","关心、爱护全体学生，尊重学生人格"],["C","参与学校的民主管理与监督"],["D","参加进修或者其他方式的培训"],["E","制止有害于学生的行为或者其他侵犯学生合法权益的行为"]]', '["A","B","E"]', '“遵守宪法、法律和职业道德，为人师表”“关心、爱护全体学生，尊重学生人格”“制止有害于学生的行为或者其他侵犯学生合法权益的行为”，三项均属《教师法》第八条规定的义务。“参与学校的民主管理与监督”与”参加进修或者其他方式的培训”两项错：二者属第七条规定的权利。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2877, 58, 86, 'multi', 1.6, '依据相关教育法律法规，学生依法享有的权利包括（　）', '[["A","参加教育教学计划安排的各种活动，使用教育教学设施"],["B","在学业成绩和品行上获得公正评价"],["C","对学校给予的处分不服，向有关部门提出申诉"],["D","人格尊严不受侵犯，个人隐私受保护"],["E","义务教育阶段学生可因严重违纪被学校开除"]]', '["A","B","C","D"]', '参加教育教学活动并使用设施、获得公正评价、不服处分提出申诉、人格尊严与隐私受保护，四项均属学生法定权利。”义务教育阶段学生可因严重违纪被学校开除”项错：义务教育阶段学校不得开除学生。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2878, 58, 87, 'multi', 1.6, '我国基础教育课程改革的具体目标包括（　）', '[["A","改变课程过于注重知识传授的倾向，强调形成积极主动的学习态度"],["B","改变课程结构过于强调学科本位、科目过多和缺乏整合的现状"],["C","改变课程内容“难、繁、偏、旧”和过于注重书本知识的现状"],["D","改变课程实施过于强调接受学习、死记硬背、机械训练的现状"],["E","改变课程管理过于集中的状况，实行国家、地方、学校三级课程管理"]]', '["A","B","C","D","E"]', '《基础教育课程改革纲要（试行）》从课程功能、结构、内容、实施、评价、管理六方面提出改革目标，前五项分别对应功能、结构、内容、实施、评价的转变，均正确。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2879, 58, 88, 'multi', 1.6, '一个成熟班集体的基本特征包括（　）', '[["A","有明确的共同奋斗目标"],["B","有健全的组织与骨干力量"],["C","学生成绩必须在年级中名列前茅"],["D","有正确的集体舆论和良好的班风"],["E","班主任必须对班级事务包办管理"]]', '["A","B","D"]', '明确的共同奋斗目标、健全的组织与骨干力量、正确的集体舆论与良好班风，三项均为成熟班集体的基本特征。”学生成绩必须在年级中名列前茅”项错；“班主任必须对班级事务包办管理”项错。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2880, 58, 89, 'multi', 1.6, '新课程倡导的学习方式包括（　）', '[["A","自主学习"],["B","合作学习"],["C","接受学习已被全面否定，一律不得使用"],["D","探究学习"],["E","有意义接受学习在当前教学中仍有其价值"]]', '["A","B","D","E"]', '自主学习、合作学习、探究学习为新课改倡导的三大学习方式；“有意义接受学习在当前教学中仍有其价值”表述正确。“接受学习已被全面否定，一律不得使用”项错。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2881, 58, 90, 'multi', 1.6, '关于《教育强国建设规划纲要（2024—2035年）》提出的教育“三大属性”，下列说法正确的有（　）', '[["A","政治属性"],["B","经济属性"],["C","人民属性"],["D","文化属性"],["E","战略属性"]]', '["A","C","E"]', '《教育强国建设规划纲要（2024—2035年）》提出的教育”三大属性”为政治属性、人民属性、战略属性。“经济属性””文化属性”两项错。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2882, 59, 1, 'judge', 0.6, '布鲁姆认知领域的教育目标由低到高依次为记忆、理解、应用、评价、分析、创造。', '[["A","正确"],["B","错误"]]', '["B"]', '布鲁姆认知领域目标由低到高应为记忆、理解、应用、分析、评价、创造，题干颠倒了“分析”与“评价”的先后层级。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2883, 59, 2, 'judge', 0.6, '某校招聘教师时，发现应聘者曾因故意犯罪受到有期徒刑处罚，认定机构据此不受理其教师资格申请。该处理符合《教师资格条例》的规定。', '[["A","正确"],["B","错误"]]', '["A"]', '应聘者曾因故意犯罪受到有期徒刑处罚，属于依法不得取得教师资格的情形，认定机构不予受理符合规定。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2884, 59, 3, 'judge', 0.6, '某小学经家长同意，计划在寒假组织六年级学生集体补课；即使家长同意，该安排仍违反《中华人民共和国未成年人保护法》的相关规定。', '[["A","正确"],["B","错误"]]', '["A"]', '学校不得占用寒暑假组织义务教育阶段未成年学生集体补课，家长同意不能免除学校遵守该禁止性规定的义务。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2885, 59, 4, 'judge', 0.6, '普雷马克原理主张用低频活动强化高频活动，即先安排学生不喜爱的活动，以增加其喜爱活动的发生概率。', '[["A","正确"],["B","错误"]]', '["B"]', '普雷马克原理是用高频、偏好的活动强化低频、不偏好的活动，题干将强化方向倒置。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2886, 59, 5, 'judge', 0.6, '某校发现学生欺凌后，仅对实施欺凌者作口头批评，未启动调查、保护和干预程序。依据《中华人民共和国未成年人保护法》，该做法不符合学校建立欺凌防控机制并及时制止、处理欺凌行为的要求。', '[["A","正确"],["B","错误"]]', '["A"]', '依据《中华人民共和国未成年人保护法》，欺凌防控不仅要求制止行为，还要求依机制开展调查、处理和必要干预；仅作口头批评未履行完整保护职责。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2887, 59, 6, 'judge', 0.6, '加德纳多元智力理论认为各类智力彼此完全独立、不可相互影响，因而学生的智力水平不能通过教育得到发展。', '[["A","正确"],["B","错误"]]', '["B"]', '多元智力“相对独立”不等于彼此完全隔绝，各类智力能够在教育与实践中得到发展。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2888, 59, 7, 'judge', 0.6, '《关于进一步减轻义务教育阶段学生作业负担和校外培训负担的意见》（“双减”）要求提升课堂教学质量、作业设计质量和课后服务水平。', '[["A","正确"],["B","错误"]]', '["A"]', '“双减”减轻义务教育阶段学生作业负担和校外培训负担，要求学校提升课堂教学、作业设计、课后服务“三个水平”。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2889, 59, 8, 'judge', 0.6, '启发性原则等同于减少教师讲授，教师在学生探究过程中不得进行直接讲解和必要点拨。', '[["A","正确"],["B","错误"]]', '["B"]', '启发性原则强调调动主动性和引导独立思考，并不排斥教师必要的讲解、示范与点拨。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2890, 59, 9, 'judge', 0.6, '斯滕伯格三元智力理论中，经验性智力主要负责适应、选择和塑造环境，情境性智力主要负责处理新任务并使信息加工自动化。', '[["A","正确"],["B","错误"]]', '["B"]', '适应、选择和塑造环境属于情境性智力，处理新任务与实现信息加工自动化属于经验性智力，题干将二者对调。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2891, 59, 10, 'judge', 0.6, '聚合性思维是创造性的核心，流畅性、变通性和独创性是聚合性思维的主要特征。', '[["A","正确"],["B","错误"]]', '["B"]', '发散性思维才是创造性的核心，流畅性、变通性和独创性是发散性思维的特征。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2892, 59, 11, 'judge', 0.6, '问题解决的基本过程通常是发现问题、提出假设、明确问题、检验假设。', '[["A","正确"],["B","错误"]]', '["B"]', '问题解决通常经历发现问题、明确问题、提出假设、检验假设，明确问题应先于提出假设。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2893, 59, 12, 'judge', 0.6, '资源管理策略直接用于加工学习材料，主要包括复述、组块和列提纲等方法。', '[["A","正确"],["B","错误"]]', '["B"]', '时间、环境、努力管理和寻求支持属于资源管理策略；复述、组块和列提纲主要是直接加工材料的认知策略。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2894, 59, 13, 'judge', 0.6, '《新时代中小学教师职业行为十项准则》要求教师关心爱护学生，不得歧视、侮辱学生，严禁虐待、伤害学生。', '[["A","正确"],["B","错误"]]', '["A"]', '“关心爱护学生”要求平等公正对待学生、不歧视侮辱、严禁虐待伤害，禁止对学生实施体罚或变相体罚。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2895, 59, 14, 'judge', 0.6, '《新时代中小学教师职业行为十项准则》中“教书育人”要求教师遵循教育规律，实施素质教育，不得唯分数评价学生。', '[["A","正确"],["B","错误"]]', '["A"]', '“教书育人”要求遵循规律、实施素质教育，不以分数作为评价学生的唯一标准，注重全面发展。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2896, 59, 15, 'judge', 0.6, '《教育强国建设规划纲要（2024—2035年）》提出，教育强国应具备思政引领力、人才竞争力、科技支撑力、民生保障力、社会协同力、国际影响力“六力”。', '[["A","正确"],["B","错误"]]', '["A"]', '《教育强国建设规划纲要（2024—2035年）》提出教育强国“六力”：思政引领力、人才竞争力、科技支撑力、民生保障力、社会协同力、国际影响力。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2897, 59, 16, 'judge', 0.6, '《义务教育课程方案（2022年版）》将核心素养导向作为课程实施的基本原则，强调培养正确价值观、必备品格和关键能力。', '[["A","正确"],["B","错误"]]', '["A"]', '2022年版课程方案以核心素养为导向，培养正确价值观、必备品格和关键能力，强化学科实践与跨学科主题学习。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2898, 59, 17, 'judge', 0.6, '《中华人民共和国教师法》规定，学校或者其他教育机构应当对教师的政治思想、业务水平、工作态度和工作成绩进行考核，考核应当客观、公正、准确，充分听取教师本人、其他教师以及学生的意见。', '[["A","正确"],["B","错误"]]', '["A"]', '《中华人民共和国教师法》第二十二、二十三条规定，学校或者其他教育机构应当对教师的政治思想、业务水平、工作态度和工作成绩进行考核；考核应当客观、公正、准确，充分听取教师本人、其他教师以及学生的意见。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2899, 59, 18, 'judge', 0.6, '《中小学教师职业道德规范》将“爱岗敬业”列为教师职业的本质要求，要求教师忠诚于人民教育事业，勤恳敬业、甘为人梯、乐于奉献，对工作高度负责，不得敷衍塞责。', '[["A","正确"],["B","错误"]]', '["A"]', '爱岗敬业是教师职业的本质要求，《中小学教师职业道德规范》要求教师忠诚于人民教育事业，志存高远、勤恳敬业、甘为人梯、乐于奉献，对工作高度负责，不得敷衍塞责。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2900, 59, 19, 'judge', 0.6, '班级授课制是我国学校教学的基本组织形式，其突出优点是可以大面积、高效率地培养人才，但也难以照顾学生的个别差异。', '[["A","正确"],["B","错误"]]', '["A"]', '班级授课制是我国现阶段学校教学的基本组织形式，优在大面积高效培养人才，局限在难顾个别差异；分组教学、个别化教学可作补充。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2901, 59, 20, 'judge', 0.6, '德育过程必须从道德认识开始，并严格按照知、情、意、行的固定顺序推进，才可能形成学生的思想品德。', '[["A","正确"],["B","错误"]]', '["B"]', '德育过程具有多种开端，知、情、意、行相互联系且可从薄弱环节切入，并不存在必须遵循的单向固定顺序。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2902, 59, 21, 'judge', 0.6, '艾宾浩斯遗忘曲线表明，遗忘在学习之后立即开始，其进程是先快后慢、先多后少。', '[["A","正确"],["B","错误"]]', '["A"]', '艾宾浩斯遗忘曲线表明遗忘在学习后立即开始，进程先快后慢、先多后少。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2903, 59, 22, 'judge', 0.6, '广义的课程是指学校为实现培养目标而选择的教育内容及其进程的总和，涵盖了学科课程、活动课程、隐性课程等多种形态。', '[["A","正确"],["B","错误"]]', '["A"]', '广义课程即学校为实现培养目标而选择的教育内容及其进程的总和，含学科课程、活动课程、隐性课程等；课程计划、课程标准、教材是课程的文本载体。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2904, 59, 23, 'judge', 0.6, '加涅按学习结果把学习分为言语信息、智慧技能、认知策略、动作技能和态度五类。', '[["A","正确"],["B","错误"]]', '["A"]', '加涅按学习结果分为言语信息、智慧技能、认知策略、动作技能和态度五类。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2905, 59, 24, 'judge', 0.6, '建构主义学习理论认为知识是学习者主动建构的结果，因此在教学中教师的作用可以完全取消。', '[["A","正确"],["B","错误"]]', '["B"]', '绝对化表述：建构主义强调学生的主动建构，但教师是意义建构的帮助者、促进者，其作用不可替代。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2906, 59, 25, 'judge', 0.6, '班杜拉认为，观察学习由注意、保持、动作再现和动机四个子过程构成。', '[["A","正确"],["B","错误"]]', '["A"]', '班杜拉认为观察学习由注意、保持、动作再现（复制）和动机四个子过程构成。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2907, 59, 26, 'judge', 0.6, '在奥苏贝尔提出的学习动机三种内驱力中，自我提高内驱力在儿童早期最为突出。', '[["A","正确"],["B","错误"]]', '["B"]', '偷换概念：奥苏贝尔认为儿童早期“附属内驱力”（为获得长者赞许而学习）最为突出，自我提高内驱力随年龄增长逐步增强。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2908, 59, 27, 'judge', 0.6, '教学是学校教育的中心工作，学校工作必须以教学为主，同时全面安排其他各项工作，使各育互相渗透、协调发展。', '[["A","正确"],["B","错误"]]', '["A"]', '教学是学校教育的中心工作，须以教学为主、全面安排各项工作，使各育互相渗透、协调发展。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2909, 59, 28, 'judge', 0.6, '《中华人民共和国教师法》规定，取得教师资格的人员首次任教时，应当有试用期。', '[["A","正确"],["B","错误"]]', '["A"]', '《教师法》规定，取得教师资格的人员首次任教时应当有试用期。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2910, 59, 29, 'judge', 0.6, '学校对未成年学生不承担监护职责，但依法负有教育、管理和保护的义务。', '[["A","正确"],["B","错误"]]', '["A"]', '学校对未成年学生不承担监护职责（《学生伤害事故处理办法》第七条），但依法负有教育、管理和保护的义务。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2911, 59, 30, 'judge', 0.6, '《深化新时代教育评价改革总体方案》提出，改进结果评价，强化过程评价，探索增值评价，健全综合评价。', '[["A","正确"],["B","错误"]]', '["A"]', '《深化新时代教育评价改革总体方案》提出“改进结果评价、强化过程评价、探索增值评价、健全综合评价”。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2912, 59, 31, 'single', 1.0, '依据《中华人民共和国教师法》，某校教师陈老师在校本课程开发中，拟根据学生特点自主设计教学方案、开展教学改革实验。陈老师主张行使的教师权利是（　）', '[["A","教育教学权"],["B","科学研究权"],["C","管理学生权"],["D","民主管理权"]]', '["A"]', '依据《中华人民共和国教师法》，教师根据学生特点设计教学方案并开展教育教学改革实验，属于教育教学权；科学研究权侧重学术研究，民主管理权侧重参与学校管理。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2913, 59, 32, 'single', 1.0, '李老师发现部分学生只有获得奖励才愿意学习，便增加任务选择机会、提供适度挑战并营造接纳性的同伴关系，以促进学生把外部要求逐步内化。该做法主要依据的动机理论是（　）', '[["A","自我效能理论"],["B","自我决定理论"],["C","归因理论"],["D","成就动机理论"]]', '["B"]', '增加自主选择、提供适度挑战和营造接纳关系，分别支持自主、胜任、关系三种基本心理需要，符合自我决定理论关于外部动机内化的观点。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2914, 59, 33, 'single', 1.0, '某学生情绪体验强烈、爆发快而平息也快，外向直率但常显粗心冲动。按气质类型划分，该生属于（　）', '[["A","多血质"],["B","粘液质"],["C","胆汁质"],["D","抑郁质"]]', '["C"]', '胆汁质：强而不平衡的高级神经活动，情绪爆发快、外向直率、粗心冲动；多血质灵活、粘液质稳重、抑郁质敏感。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2915, 59, 34, 'single', 1.0, '某校教研活动中，王老师发现学生把一种方法迁移到新任务的效果，取决于两项学习中是否含有相同成分。王老师的判断符合（　）', '[["A","形式训练说"],["B","经验类化说"],["C","关系转换说"],["D","共同要素说"]]', '["D"]', '王老师以两项学习是否含有相同成分解释迁移，符合桑代克、伍德沃斯的共同要素说：经验类化说则强调对原理的概括。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2916, 59, 35, 'single', 1.0, '依据《中华人民共和国预防未成年人犯罪法》，某县在处理一起案件时，发现小周因不满十六周岁不予刑事处罚。依法责令其监护人管教后，评估认为仍有必要进行专门干预。此时可以采取的措施是（　）', '[["A","专门矫治教育"],["B","收容教养"],["C","社区矫正"],["D","工读教育"]]', '["A"]', '依据《中华人民共和国预防未成年人犯罪法》，对不满十六周岁不予刑事处罚的未成年人，在责令监护人管教后确有必要的，可以依法进行专门矫治教育；收容教养、社区矫正和工读教育均不符合现行规定与题设条件。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2917, 59, 36, 'single', 1.0, '依据《中华人民共和国学前教育法》，某幼儿园园长在安排大班一日活动时，把集中识字、练习加减法作为主要内容，并压缩自主活动时间。为纠正小学化倾向，幼儿园最应坚持的活动组织原则是（　）', '[["A","课堂教学为基本活动"],["B","游戏为基本活动"],["C","读写算训练为基本活动"],["D","考试评价为基本活动"]]', '["B"]', '《中华人民共和国学前教育法》要求幼儿园以游戏为基本活动，纠正集中识字、练习加减法和压缩自主活动时间等小学化做法。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2918, 59, 37, 'single', 1.0, '在我国全面发展教育的组成部分中，起物质基础作用、为其他各育提供身体条件保障的是（　）', '[["A","德育"],["B","智育"],["C","美育"],["D","体育"]]', '["D"]', '德育是灵魂与统帅，智育是前提和支持，体育是物质基础，美育是动力，劳动教育是综合育人途径。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2919, 59, 38, 'single', 1.0, '我国近代教育史上，第一个正式颁布并在全国范围内付诸实施的学制是（　）', '[["A","壬寅学制"],["B","癸卯学制"],["C","壬子癸丑学制"],["D","壬戌学制"]]', '["B"]', '癸卯学制（1904）是我国第一个正式颁布并实施的学制；壬寅学制只颁布未实施。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2920, 59, 39, 'single', 1.0, '王老师在入职第三年总结道：“我现在最关心的不是能不能管住学生，而是怎样备好每一节课、让全班同学都真正掌握所学内容。”按福勒与布朗的理论，王老师已处于（　）', '[["A","关注生存阶段"],["B","关注学生阶段"],["C","虚拟关注阶段"],["D","关注情境阶段"]]', '["D"]', '题干强调的是怎样把课上好、让全班都掌握，指向教学情境与效果，属关注情境阶段；关注学生阶段则以关注学生个别差异与情感需要为标志。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2921, 59, 40, 'single', 1.0, '课堂上学生提出一个教师没有预设的问题，教师坦承"这个问题我也没想清楚，我们一起来查资料”，课后师生共同找到了答案。这一情境最能体现的师生关系特征是（　）', '[["A","尊师爱生"],["B","教学相长"],["C","民主平等"],["D","心理相容"]]', '["B"]', '师生共同探究、教师坦诚承认不足并从中获益，体现教学相长（师生相互促进、共同提高）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2922, 59, 41, 'single', 1.0, '某校在课程表中未作安排，但通过校训石、校友长廊、教师日常待人接物的方式持续影响学生。这类课程属于（　）', '[["A","隐性课程"],["B","显性课程"],["C","活动课程"],["D","校本课程"]]', '["A"]', '校训石、校友长廊、教师言行等未在课表中安排却持续影响学生的因素属隐性课程。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2923, 59, 42, 'single', 1.0, '依据《中华人民共和国教育法》，某校在招生时，以学生父母的职业为由拒绝符合入学条件的学生。该校的做法主要侵犯了学生的（　）', '[["A","免试入学的权利"],["B","免费教育的权利"],["C","自主选择学校的权利"],["D","平等的受教育机会"]]', '["D"]', '依据《中华人民共和国教育法》，学校以父母职业为由拒绝符合条件的学生，构成对受教育机会的差别对待，违反公民依法平等享有受教育机会的规定。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2924, 59, 43, 'single', 1.0, '依据《中华人民共和国义务教育法》，某县教育局在审查义务教育学校课程实施方案时，讨论哪些事项应由国务院教育行政部门根据适龄儿童、少年身心发展状况和实际情况统一确定。下列属于其法定职权的是（　）', '[["A","教师工资的具体标准"],["B","学校的行政隶属关系"],["C","教学制度、教育教学内容和课程设置"],["D","教材的出版发行机构"]]', '["C"]', '依据《中华人民共和国义务教育法》，国务院教育行政部门依法根据适龄儿童、少年身心发展状况和实际情况，确定教学制度、教育教学内容和课程设置，并审定教科书。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2925, 59, 44, 'single', 1.0, '某教师在设计单元作业时，先评估学生当前的知识基础与思维水平，据此把作业分为基础巩固、综合应用、拓展探究三个梯度，使每个梯度都落在学生“跳一跳够得着”的范围内。这主要体现的教学原则是（　）', '[["A","循序渐进原则"],["B","量力性原则"],["C","理论联系实际原则"],["D","系统性原则"]]', '["B"]', '量力性原则要求教学的内容、方法与进度适合学生的发展水平，既不能低于也不能远超其可接受程度；“跳一跳够得着”即落在最近发展区内的适度难度。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2926, 59, 45, 'single', 1.0, '物理课上讲“浮力”时，李老师先让学生把橡皮泥捏成球放入水中观察下沉，再捏成船形观察漂浮，最后引导学生归纳出浮力与排开水量的关系。李老师主要贯彻的教学原则是（　）', '[["A","启发性原则"],["B","直观性原则"],["C","巩固性原则"],["D","科学性与思想性相统一原则"]]', '["A"]', '教师不直接给结论，而是设置情境、设置问题引导学生自主归纳，核心是启发性；直观性只是手段。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2927, 59, 46, 'single', 1.0, '张老师讲《孔乙己》时，先让学生通读课文并提出“孔乙己最后为什么再也没有出现”等系列问题，再组织四人小组讨论，最后各组汇报、教师点拨。这一教学过程主要运用的教学方法是（　）', '[["A","讲授法"],["B","讨论法"],["C","谈话法"],["D","读书指导法"]]', '["B"]', '四人小组讨论、各组汇报、教师点拨，是以学生交流为主体的讨论法。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2928, 59, 47, 'single', 1.0, '某校数学组把学生按现有水平分为A、B两层，A层重拓展探究、B层重基础过关，每学期根据测评结果动态调整，但行政班保持不变。这一做法属于（　）', '[["A","班级授课制"],["B","特朗普制"],["C","分组教学"],["D","道尔顿制"]]', '["C"]', '按水平分层、动态调整而保留行政班，属分组教学（内部分组/能力分组）；特朗普制是大班上课+小班研究+个别教学的组合。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2929, 59, 48, 'single', 1.0, '开学第一周，刘老师安排了一次摸底测验，目的是了解学生暑假后的知识基础，以便确定新学期的教学起点。该测验属于（　）', '[["A","诊断性评价"],["B","形成性评价"],["C","总结性评价"],["D","绝对性评价"]]', '["A"]', '开学初摸底以了解起点、确定教学起点为目的，属诊断性评价。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2930, 59, 49, 'single', 1.0, '王老师在设计单元教学时，精选典型材料，引导学生由个别事例把握一般规律，并在掌握知识的同时发展问题解决能力。按照瓦·根舍因的观点，这一设计的核心追求是（　）', '[["A","掌握学科基本结构"],["B","实现教学与教育的统一"],["C","强化操作性条件反射"],["D","提高标准化测验成绩"]]', '["B"]', '王老师通过典型材料使学生由个别把握一般，并兼顾知识掌握与能力发展，体现范例教学追求教学与教育的统一；“掌握学科基本结构”主要对应布鲁纳。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2931, 59, 50, 'single', 1.0, '班主任发现两名学生因误会闹矛盾，没有当众批评，而是让两人分别说说对方的三个优点，再引导他们自己商量解决办法。该做法主要体现的德育原则是（　）', '[["A","正面教育与纪律约束相结合原则"],["B","知行统一原则"],["C","长善救失原则"],["D","教育影响的一致性与连贯性原则"]]', '["A"]', '不批评、发掘优点并引导学生自商办法，坚持以正面引导为主，同时仍以班规约束，属正面教育与纪律约束相结合。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2932, 59, 51, 'single', 1.0, '教师组织学生参观科技馆、参加社区志愿服务，引导学生在实践中形成相应的道德认识。这主要运用的德育方法是（　）', '[["A","说服教育法"],["B","榜样示范法"],["C","实际锻炼法"],["D","情感陶冶法"]]', '["C"]', '组织参观、志愿服务，让学生在实践中形成道德认识与行为习惯，属实际锻炼法。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2933, 59, 52, 'single', 1.0, '某校在制定年度育人方案时，将提高统考成绩作为唯一目标，删减合作学习和实践活动。依据《中华人民共和国未成年人保护法》，该校最应补充的培养要求是（　）', '[["A","培养未成年学生认知能力、合作精神与实践能力"],["B","只抓文化课考试成绩"],["C","按成绩分班教学"],["D","减少体育美育课时"]]', '["A"]', '将成绩作为唯一目标并删减合作、实践活动，不符合立德树人与素质教育要求；学校应注重培养未成年学生的认知能力、合作精神与实践能力。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2934, 59, 53, 'single', 1.0, '李老师入职后，坚持参加政治理论学习并持续研修教学技能。该教师的做法履行了不断提高思想政治觉悟和教育教学业务水平的（　）', '[["A","权利"],["B","自由"],["C","奖励"],["D","义务"]]', '["D"]', '持续提高思想政治觉悟和教育教学业务水平，是教师依法应当履行的义务，不是可自由放弃的权利或奖励。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2935, 59, 54, 'single', 1.0, '某校校长拟直接发布新版校规，未征求学生和家长意见，也未提交相关会议讨论。为使程序符合《中小学教育惩戒规则（试行）》，学校应当（　）', '[["A","仅召开学校行政会议决定"],["B","广泛征求教职工、学生和学生父母或者其他监护人的意见，并提交家长委员会、教职工代表大会讨论"],["C","仅报教育行政部门批准"],["D","仅征求学生代表意见"]]', '["B"]', '学校制定校规校纪应广泛征求教职工、学生及其父母或者其他监护人的意见，并提交家长委员会、教职工代表大会讨论，校长不能以行政决定替代法定参与程序。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2936, 59, 55, 'single', 1.0, '班集体形成过程中，学生开始关心集体荣誉、干部和积极分子能够主动协助班主任开展工作，班级舆论初步形成。这表明班集体已进入（　）', '[["A","组建阶段"],["B","核心初步形成阶段"],["C","发展阶段"],["D","成熟阶段"]]', '["B"]', '班集体发展一般经历组建、核心初步形成、发展、成熟四个阶段；题干描述符合核心初步形成阶段。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2937, 59, 56, 'single', 1.0, '某班本周开展“校园节水”调查，各组须在三日内提交报告。三天里，小组成员主动分工、互相提醒进度，秩序明显好转。该小组表现出的课堂纪律类型是（　）', '[["A","教师促成的纪律"],["B","集体促成的纪律"],["C","自我促成的纪律"],["D","任务促成的纪律"]]', '["D"]', '小组秩序好转源于“三日内提交报告”这一任务本身的要求，而非教师当场管束、集体舆论压力或个人自律，属于任务促成的纪律。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2938, 59, 57, 'single', 1.0, '维果斯基认为，教学应当走在发展的前面，其理论依据是（　）', '[["A","个体的认知发展经历四个有序阶段"],["B","学习是刺激一反应联结的建立"],["C","儿童存在两种发展水平：现有发展水平与可能达到的发展水平"],["D","强化在学习中起决定性作用"]]', '["C"]', '维果斯基提出最近发展区（现有水平与可能达到的水平之间的差距），据此主张教学应走在发展前面。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2939, 59, 58, 'single', 1.0, '根据埃里克森的人格发展阶段理论，小学生（6—12岁）面临的核心冲突是（　）', '[["A","主动感对内疚感"],["B","自我同一性对角色混乱"],["C","亲密感对孤独感"],["D","勤奋感对自卑感"]]', '["D"]', '6—12岁（学龄期）的核心冲突是勤奋感对自卑感；12—18岁为自我同一性对角色混乱。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2940, 59, 59, 'single', 1.0, '某教师组织学生到社区开展垃圾分类现状调查，回校后指导学生整理数据、撰写调查报告，并在班会上交流成果。该教师主要运用的教学方法是（　）', '[["A","讲授法"],["B","讨论法"],["C","调查法"],["D","演示法"]]', '["C"]', '调查法是学生在教师指导下围绕某一问题搜集资料、分析并得出结论的方法，包含实地调查、数据处理与成果表达等环节；讲授法以语言传递为主，讨论法以集体交流为主，演示法以直观展示为主。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2941, 59, 60, 'single', 1.0, '张老师讲授科学概念时，不直接告知结论，而是让学生像科学家一样自行探究并概括知识结构。该做法体现了布鲁纳倡导的（　）', '[["A","接受学习"],["B","机械学习"],["C","观察学习"],["D","发现学习"]]', '["D"]', '张老师让学生自行探究并概括知识结构，符合布鲁纳倡导的发现学习；接受学习侧重由教师呈现定论，机械学习不强调理解结构。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2942, 59, 61, 'single', 1.0, '教师在讲授新知识前，先呈现一段概括性更高、包容性更广的引导性材料，为新知识提供“固定点”。奥苏贝尔把这种做法称为（　）', '[["A","认知同化"],["B","先行组织者"],["C","上位学习"],["D","组块化编码"]]', '["B"]', '奥苏贝尔提出“先行组织者”——先于学习任务呈现的、概括包容性更高的引导性材料。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2943, 59, 62, 'single', 1.0, '学生小李把这次英语考试失利归因于“自己运气不好”。按韦纳的归因理论，这种归因方式属于（　）', '[["A","内部的、稳定的、不可控的"],["B","外部的、稳定的、不可控的"],["C","内部的、不稳定的、可控的"],["D","外部的、不稳定的、不可控的"]]', '["D"]', '韦纳三维度六因素中，“运气”属外部的、不稳定的、不可控的；需与之区分的是任务难度，属外部的、稳定的、不可控的，二者稳定性维度相反。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2944, 59, 63, 'single', 1.0, '学生相信自己有能力完成某项学习任务，这种信念会影响其投入程度与坚持时间。班杜拉称之为（　）', '[["A","自我效能感"],["B","成就动机"],["C","归因倾向"],["D","习得性无助"]]', '["A"]', '班杜拉提出自我效能感，即个体对自己能否成功完成某行为的主观判断，影响其选择与坚持性。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2945, 59, 64, 'single', 1.0, '小雅每次复习前先列出当周的复习任务，按重要和紧急程度排序，并把每天的自习时段固定分配给不同科目。她主要运用的学习策略是（　）', '[["A","认知策略"],["B","资源管理策略"],["C","元认知策略"],["D","精细加工策略"]]', '["B"]', '迈克卡将学习策略分为认知策略、元认知策略与资源管理策略。资源管理策略包括时间管理、学习环境管理、努力管理和学业求助等；题干的任务排序与时段分配属时间管理，归资源管理策略。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2946, 59, 65, 'single', 1.0, '贾德的“水下击靶”实验表明，迁移的关键在于学习者对原理或规则的概括。这一迁移理论是（　）', '[["A","形式训练说"],["B","共同要素说"],["C","经验类化说（概括化理论）"],["D","关系转换说"]]', '["C"]', '贾德“水下击靶”实验支持经验类化说（概括化理论）：迁移的关键是对原理的概括。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2947, 59, 66, 'single', 1.0, '学生在解答数学题时，因受先前做过的同类题目影响而用固定思路套用，导致解题受阻。这种现象属于（　）', '[["A","功能固着"],["B","定势"],["C","原型启发"],["D","酝酿效应"]]', '["B"]', '先前活动形成的心理准备状态影响后继活动，属定势；功能固着指只看到物体惯常功能。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2948, 59, 67, 'single', 1.0, '关于科尔伯格的道德发展阶段理论，下列表述正确的是（　）', '[["A","前习俗水平的个体以惩罚与服从为定向"],["B","道德发展阶段的顺序因文化不同而有显著差异"],["C","习俗水平的个体依据普遍的伦理原则作出判断"],["D","后习俗水平的个体主要关注他人赞许与社会秩序"]]', '["A"]', '科尔伯格：前习俗水平包括惩罚与服从定向、工具性相对主义定向；习俗水平含"好孩子"与维护权威秩序；后习俗水平以普遍伦理原则为定向。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2949, 59, 68, 'single', 1.0, '心理咨询中，辅导教师引导学生识别并改变“我一定考不好”这类不合理信念，帮助其建立合理认知。这一方法属于（　）', '[["A","行为疗法"],["B","来访者中心疗法"],["C","精神分析疗法"],["D","认知疗法"]]', '["D"]', '识别并改变不合理信念、建立合理认知，属认知疗法（如理性情绪疗法）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2950, 59, 69, 'single', 1.0, '教师职业倦怠的三个核心维度是（　）', '[["A","焦虑、抑郁、躯体化"],["B","角色冲突、角色模糊、角色过载"],["C","情绪衰竭、去人性化、低个人成就感"],["D","认知枯竭、意志衰退、行为失范"]]', '["C"]', '玛勒诗等提出职业倦怠三维度：情绪衰竭、去人性化（人格解体）、低个人成就感。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2951, 59, 70, 'single', 1.0, '新教师通过观看优秀教师的课堂录像、自己试讲后回看录像并逐环节分析改进，这种专业成长途径属于（　）', '[["A","职前师范教育"],["B","微格教学"],["C","校本教研"],["D","行动研究"]]', '["B"]', '录像回看、逐环节分析改进，属微格教学；观摩优秀教师录像属"观摩分析"，题干着重自身试讲回看改进。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2952, 59, 71, 'single', 1.0, '《中华人民共和国义务教育法》规定，凡年满六周岁的儿童，其父母或者其他法定监护人应当送其入学接受并完成义务教育；条件不具备的地区的儿童，可以推迟到（　）', '[["A","七周岁"],["B","六周岁半"],["C","八周岁"],["D","由县级人民政府自行确定"]]', '["A"]', '《义务教育法》第十一条：凡年满六周岁送其入学，条件不具备的地区可推迟到七周岁。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2953, 59, 72, 'single', 1.0, '某初中为提高升学率，将年级前60名学生单独编为"励志班”，配备最优师资。该校的做法（　）', '[["A","合法，属于学校内部的教学管理自主权"],["B","合法，但须报县级教育行政部门备案"],["C","违法，学校不得分设重点班和非重点班"],["D","违法，义务教育阶段不得按成绩编班，但可设\\"实验班\\""]]', '["C"]', '《义务教育法》第二十二条：县级以上政府及其教育行政部门应促进学校均衡发展，缩小差距，不得将学校分为重点学校和非重点学校；学校不得分设重点班和非重点班。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2954, 59, 73, 'single', 1.0, '《中华人民共和国教师法》规定，教师对学校或者其他教育机构侵犯其合法权益的，或者对学校作出的处理不服的，可以向教育行政部门提出申诉，教育行政部门应当在接到申诉的（　）内作出处理。', '[["A","十五日"],["B","六十日"],["C","九十日"],["D","三十日"]]', '["D"]', '《教师法》第三十九条：教育行政部门应在接到申诉的三十日内作出处理。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2955, 59, 74, 'single', 1.0, '依据《中小学教育惩戒规则（试行）》，学校应当将学生受到本规则第十条所列教育惩戒和纪律处分的信息报主管教育行政部门备案的时间是（　）', '[["A","每月末"],["B","每季度末"],["C","每学期末"],["D","每学年末"]]', '["C"]', '该规则第十九条规定，每学期末学校应当将学生受到本规则第十条所列教育惩戒和纪律处分的信息报主管教育行政部门备案，以便主管部门掌握实施情况并进行监督。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2956, 59, 75, 'single', 1.0, '某教师因学生上课玩手机，当场没收手机并拒绝归还，还当众翻看学生聊天记录。该教师的做法侵犯了学生的（　）', '[["A","受教育权和人身自由权"],["B","名誉权和荣誉权"],["C","财产权和隐私权"],["D","肖像权和著作权"]]', '["C"]', '没收手机拒不归还侵犯财产权，当众翻看聊天记录侵犯隐私权（通信秘密）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2957, 59, 76, 'single', 1.0, '依据《中华人民共和国未成年人保护法》，下列属于"社会保护"范畴的是（　）', '[["A","爱国主义教育基地、图书馆等场所应当对未成年人免费或者优惠开放"],["B","父母应当关注未成年人的生理、心理状况和情感需求"],["C","学校应当建立学生欺凌防控工作制度"],["D","公安机关应当依法维护校园周边的治安和交通秩序"]]', '["A"]', '场馆免费或优惠开放属社会保护；父母关注身心状况属家庭保护，学校建欺凌防控制度属学校保护，公安机关维护校园周边秩序属政府保护。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2958, 59, 77, 'single', 1.0, '教师张某因故意犯罪被判处有期徒刑，其教师资格（　）', '[["A","自动丧失，五年后可以重新申请"],["B","由学校决定是否撤销"],["C","暂缓注册，期满后可恢复"],["D","自动丧失，不能重新取得"]]', '["D"]', '《教师法》第十四条：受到剥夺政治权利或者故意犯罪受到有期徒刑以上刑事处罚的，丧失教师资格，不能重新取得。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2959, 59, 78, 'single', 1.0, '教师职业道德中，被视为教师职业的内在要求、对社会文明具有示范意义的是（　）', '[["A","为人师表"],["B","爱岗敬业"],["C","关爱学生"],["D","终身学习"]]', '["A"]', '为人师表是教师职业的内在要求；爱岗敬业是本质要求，关爱学生是灵魂，教书育人是根本任务（天职），终身学习是专业发展的不竭动力。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2960, 59, 79, 'single', 1.0, '某校在制订健康学校长期建设方案时，四个备选目标中，符合《教育部关于全面推进健康学校建设的指导意见》目标节点与表述的是（　）', '[["A","到2030年普遍建成更高质量的健康学校"],["B","到2035年所有学校达到完全相同的学生体质标准"],["C","到2035年普遍建成更高质量的健康学校"],["D","到2035年以校园医疗服务替代体育、心理健康和健康教育"]]', '["C"]', '《教育部关于全面推进健康学校建设的指导意见》明确，到2035年普遍建成更高质量的健康学校；该目标强调系统提升学生健康水平，不能简化为单一体质标准或校园医疗服务。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2961, 59, 80, 'single', 1.0, '中国学生发展核心素养以"全面发展的人"为核心，分为文化基础、自主发展、社会参与三个方面。下列属于"自主发展"方面的是（　）', '[["A","健康生活"],["B","人文底蕴"],["C","科学精神"],["D","责任担当"]]', '["A"]', '自主发展含学会学习、健康生活；文化基础含人文底蕴、科学精神；社会参与含责任担当、实践创新。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2962, 59, 81, 'multi', 1.6, '下列教学情境中，教师的做法符合循序渐进原则要求的有（　）', '[["A","温故而知新"],["B","因材施教，各因其材"],["C","学不躐等"],["D","不陵节而施"],["E","杂施而不孙，则坏乱而不修"]]', '["C","D","E"]', '“学不躐等”“不陵节而施”“杂施而不孙，则坏乱而不修”均出自《学记》，体现循序渐进；“温故而知新”体现巩固性，“因材施教”体现从学生实际出发。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2963, 59, 82, 'multi', 1.6, '遗传、环境、学校教育以及个体主观能动性在人的身心发展中的作用，下列判断正确的有（　）', '[["A","遗传素质是个体发展的物质前提，为发展提供了可能性"],["B","学校教育在个体发展中起主导作用"],["C","环境把遗传提供的可能性转化为现实，是决定性因素"],["D","个体主观能动性是推动个体发展的决定性因素"],["E","遗传决定论与环境决定论都否认了个体主观能动性的作用"]]', '["A","B","D","E"]', '遗传是物质前提（提供可能性），环境是外部条件，学校教育起主导作用，个体主观能动性是决定性因素；遗传决定论与环境决定论共同否认主观能动性的作用。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2964, 59, 83, 'multi', 1.6, '元认知策略在学习活动中的具体运用，下列表述能够成立的有（　）', '[["A","元认知知识包括对个人、任务和策略的认识"],["B","元认知监控包括计划、监视和调节等环节"],["C","学生解题前估计题目难度并分配时间，体现了计划策略"],["D","发现原方法无效后调整解题路径，只属于认知策略，与元认知无关"],["E","学生解题过程中检查思路是否有效，体现了监视策略"]]', '["A","B","C","E"]', '元认知知识包括对个人、任务和策略的认识；元认知监控通常包含计划、监视和调节。解题前估计难度、分配时间属于计划，解题中检查思路属于监视；发现方法无效后调整路径属于元认知调节，并非与元认知无关。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2965, 59, 84, 'multi', 1.6, '关于学习动机与学习效果的关系，下列说法正确的有（　）', '[["A","动机强度与学习效率之间呈倒U形曲线关系"],["B","完成简单任务时，动机强度偏高更有利于提高效率"],["C","动机越强效果越好，教师应无止境地激发学生的动机"],["D","完成复杂任务时，中等偏低的动机水平效率最高"],["E","学习动机对学习效果的影响是单向的，效果不会影响动机"]]', '["A","B","D"]', '耶克斯一多德森定律：动机与效率呈倒U形关系，简单任务最佳水平偏高，复杂任务最佳水平偏低；学习动机与学习效果相互影响。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2966, 59, 85, 'multi', 1.6, '下列做法中，主要运用榜样示范法的有（　）', '[["A","教师组织学生到敬老院开展服务活动"],["B","教师讲述科学家钱学森回国报效祖国的事迹"],["C","教师表扬班级中助人为乐的同学并请其介绍想法"],["D","教师对学生的日常行为表现进行加分与扣分"],["E","教师以身作则，要求学生做到的自己先做到"]]', '["B","C","E"]', '讲述科学家事迹与表扬同伴榜样、教师以身作则，均属榜样示范法；组织敬老院服务属实际锻炼，加分扣分属品德评价。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2967, 59, 86, 'multi', 1.6, '依据《学生伤害事故处理办法》，因学生或其监护人过错造成学生伤害事故、应当依法承担相应责任的情形包括（　）', '[["A","学生违反校纪擅自进入明令禁止的危险区域而受到伤害"],["B","学校已尽管理教育职责，损害系不可抗力造成"],["C","学生有特异体质或特定疾病，其监护人知道但未告知学校"],["D","学生或其监护人明知学生有特定疾病仍隐瞒，导致事故发生"],["E","教师在课堂上有序组织活动，学生因自身突发疾病受伤"]]', '["A","C","D"]', '《学生伤害事故处理办法》第十条：学生或其监护人过错致事故应担责，含违反校纪擅入危险区、有特异体质或特定疾病未告知学校等；学校已尽职责且因不可抗力等造成的，学校不担责。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2968, 59, 87, 'multi', 1.6, '依据《中华人民共和国未成年人保护法》，学校在保护未成年学生方面应当履行的职责包括（　）', '[["A","建立学生欺凌防控工作制度，对欺凌行为及时制止和处理"],["B","为保障教学秩序，可以公开学生的考试成绩与名次"],["C","对未成年人开展适合其年龄的性教育，提高防范性侵害的自我保护意识"],["D","应当关心、爱护学生，对品行有缺点、学习有困难的学生耐心教育、帮助"],["E","可以依据校规开除严重违纪的义务教育阶段学生"]]', '["A","C","D"]', '学校保护要求建欺凌防控制度、开展适龄性教育、关心帮助困难学生；公开成绩排名侵犯隐私，义务教育阶段不得开除学生。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2969, 59, 88, 'multi', 1.6, '促进教师专业发展的途径主要包括（　）', '[["A","师范教育与入职培训"],["B","观摩与分析优秀教师的教学活动"],["C","开展微格教学"],["D","进行教学反思与行动研究"],["E","建立教师专业发展档案，并在同伴互助中依据反馈持续改进"]]', '["A","B","C","D","E"]', '教师专业发展途径包括师范教育与入职培训、观摩分析、微格教学、教学反思与行动研究；建立专业发展档案并在同伴互助中依据反馈持续改进，也能促进教师形成持续反思与自主发展的能力。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2970, 59, 89, 'multi', 1.6, '关于《义务教育课程标准（2022年版）》的修订要求，下列说法正确的有（　）', '[["A","取消课程内容的结构化要求，由教师自主确定教学顺序"],["B","各课程标准基于核心素养设计，强调正确价值观、必备品格和关键能力的培养"],["C","设置跨学科主题学习，加强学科间相互关联"],["D","各学科增加学业质量要求，明确“学到什么程度”"],["E","倡导学科实践，注重“做中学”“用中学”“创中学”"]]', '["B","C","D","E"]', '2022 版课标：以核心素养为导向、设置跨学科主题学习、增加学业质量、倡导学科实践，并强调课程内容结构化。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2971, 59, 90, 'multi', 1.6, '关于班主任的个别教育工作，下列说法正确的有（　）', '[["A","个别教育只需针对后进生，其他学生可以不管"],["B","对先进生要防止自满，引导其更高标准地要求自己"],["C","对后进生要尊重信任，发掘其闪光点，持之以恒"],["D","对中等生要重点关注，为其创造展示和锻炼的机会"],["E","个别教育应当与集体教育相结合"]]', '["B","C","D","E"]', '个别教育应面向全体：先进生防自满、后进生重在转化发掘闪光点、中等生要为其创造机会，并与集体教育结合。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2972, 60, 1, 'judge', 0.6, '“教育”一词最早见于《孟子·尽心上》中的“得天下英才而教育之，三乐也”。', '[["A","正确"],["B","错误"]]', '["A"]', '“教育”一词最早见于《孟子·尽心上》：“得天下英才而教育之，三乐也。”');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2973, 60, 2, 'judge', 0.6, '教育只存在于人类社会，动物界不存在教育现象，因此“老鹰教小鹰飞翔”属于教育。', '[["A","正确"],["B","错误"]]', '["B"]', '条件缺失：教育是人类社会特有的有意识活动，“老鹰教小鹰飞翔”属动物本能行为，不构成教育。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2974, 60, 3, 'judge', 0.6, '教育的心理起源说以美国学者孟禄为代表，认为教育起源于儿童对成人的有意识模仿。', '[["A","正确"],["B","错误"]]', '["B"]', '偷换概念：心理起源说认为教育起源于儿童对成人的无意识模仿，“有意识模仿”表述错误。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2975, 60, 4, 'judge', 0.6, '《中华人民共和国教师法》规定，教师应当关心、爱护全体学生，尊重学生人格，促进学生在品德、智力、体质等方面全面发展。', '[["A","正确"],["B","错误"]]', '["A"]', '《教师法》第八条规定，教师应当关心、爱护全体学生，尊重学生人格，促进学生在品德、智力、体质等方面全面发展，这是教师法定义务的重要内容。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2976, 60, 5, 'judge', 0.6, '教育对政治经济制度具有决定作用，教育发展水平决定社会制度的性质。', '[["A","正确"],["B","错误"]]', '["B"]', '因果倒置：社会政治经济制度决定教育的性质与领导权，教育对政治经济制度起反作用而非决定作用。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2977, 60, 6, 'judge', 0.6, '"关键期"这一概念由奥地利动物学家劳伦兹在研究印刻现象时提出。', '[["A","正确"],["B","错误"]]', '["A"]', '“关键期”由奥地利动物学家劳伦兹（洛伦兹）研究印刻现象时提出。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2978, 60, 7, 'judge', 0.6, '遗传素质为人的发展提供了可能性，因而遗传素质对人的发展起决定作用。', '[["A","正确"],["B","错误"]]', '["B"]', '范围扩大：遗传素质是物质前提，提供发展的可能性；个体主观能动性才是决定性因素。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2979, 60, 8, 'judge', 0.6, '学校教育在人的身心发展中起主导作用，这种主导作用是绝对的、无条件的。', '[["A","正确"],["B","错误"]]', '["B"]', '绝对化表述：学校教育的主导作用是有条件的，须遵循学生身心发展规律、与家庭社会协同配合方能实现。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2980, 60, 9, 'judge', 0.6, '先学习的材料对识记和回忆后学习材料所产生的干扰作用，在心理学上称为前摄抑制。', '[["A","正确"],["B","错误"]]', '["A"]', '前摄抑制指先学习的材料对后学习材料的识记和回忆产生干扰；后学习材料对先学材料的干扰称倒摄抑制。二者都属于系列位置效应中的干扰现象，是遗忘的干扰说的重要证据。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2981, 60, 10, 'judge', 0.6, '我国确立教育目的的理论依据是马克思关于人的全面发展学说。', '[["A","正确"],["B","错误"]]', '["A"]', '我国教育目的的理论基础是马克思关于人的全面发展学说。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2982, 60, 11, 'judge', 0.6, '癸卯学制以"中学为体，西学为用"为指导思想，是我国第一个正式实施的学制。', '[["A","正确"],["B","错误"]]', '["A"]', '癸卯学制（1904）以“中学为体，西学为用”为指导思想，是我国第一个正式颁布并实施的学制。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2983, 60, 12, 'judge', 0.6, '教师专业发展就是教师学科专业知识的增长，知识越多专业水平越高。', '[["A","正确"],["B","错误"]]', '["B"]', '以偏概全：教师专业发展包括专业理念、专业知识、专业能力、专业态度与动机等多维度，知识增长不等于专业发展。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2984, 60, 13, 'judge', 0.6, '《中小学教师职业道德规范》要求教师为人师表，以身作则、率先垂范，以自身良好的人格修养和道德情操感染学生。', '[["A","正确"],["B","错误"]]', '["A"]', '《中小学教师职业道德规范》将“为人师表”作为教师职业的内在要求，要求教师以身作则、率先垂范，以良好的人格魅力和道德情操感染学生，衣着得体、语言规范、关心集体、廉洁奉公。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2985, 60, 14, 'judge', 0.6, '《中华人民共和国义务教育法》规定，义务教育实行国务院领导，省、自治区、直辖市人民政府统筹规划实施，县级人民政府为主管理的体制。', '[["A","正确"],["B","错误"]]', '["A"]', '《义务教育法》第七条规定，义务教育实行国务院领导，省、自治区、直辖市人民政府统筹规划实施，县级人民政府为主管理的体制，明确了义务教育的管理权责。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2986, 60, 15, 'judge', 0.6, '教学的任务就是向学生传授科学文化基础知识，发展能力是课外活动的事。', '[["A","正确"],["B","错误"]]', '["B"]', '范围缩小：教学任务包括传授双基、发展能力、培养思想品德与个性，发展能力是教学的重要任务而非课外活动的事。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2987, 60, 16, 'judge', 0.6, '《关于全面加强新时代大中小学劳动教育的意见》指出，劳动教育具有树德、增智、强体、育美的综合育人价值，是国民教育体系的组成部分。', '[["A","正确"],["B","错误"]]', '["A"]', '《关于全面加强新时代大中小学劳动教育的意见》明确劳动教育具有树德、增智、强体、育美的综合育人价值，是国民教育体系的重要组成部分，要求贯通大中小学各学段。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2988, 60, 17, 'judge', 0.6, '依据《中华人民共和国未成年人保护法》，处理涉及未成年人事项，应当给予未成年人特殊、优先保护，并遵循最有利于未成年人的原则。', '[["A","正确"],["B","错误"]]', '["A"]', '《未成年人保护法》第四条规定，保护未成年人应当坚持最有利于未成年人的原则，并明确要求对未成年人给予特殊、优先保护，尊重其人格尊严。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2989, 60, 18, 'judge', 0.6, '德育即道德教育，思想政治教育、法治教育和心理健康教育不属于德育范畴。', '[["A","正确"],["B","错误"]]', '["B"]', '范围缩小：我国学校德育包括思想教育、政治教育、道德教育、法治教育和心理健康教育。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2990, 60, 19, 'judge', 0.6, '品德的心理结构由道德认识、道德情感、道德意志和道德行为四种心理成分构成。', '[["A","正确"],["B","错误"]]', '["A"]', '品德心理结构由道德认识、道德情感、道德意志、道德行为四要素构成，其中道德认识是基础，道德行为是衡量品德的重要标志。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2991, 60, 20, 'judge', 0.6, '《中华人民共和国教育法》规定，学校及其他教育机构中的教学辅助人员和其他专业技术人员，实行专业技术职务聘任制度。', '[["A","正确"],["B","错误"]]', '["A"]', '《教育法》第三十六条规定，学校及其他教育机构中的教学辅助人员和其他专业技术人员，实行专业技术职务聘任制度，依法保障其合法权益。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2992, 60, 21, 'judge', 0.6, '注意的分散是指注意不随意地离开当前应当指向和集中的对象，转而指向无关刺激，属于注意的被动减弱。', '[["A","正确"],["B","错误"]]', '["A"]', '注意的分散又称分心，是注意不随意地离开当前应当指向和集中的对象而转向无关刺激，属于被动、消极的注意减弱，会降低学习效率。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2993, 60, 22, 'judge', 0.6, '短时记忆的容量为7±2个组块，且在不复述的条件下可保持数分钟之久。', '[["A","正确"],["B","错误"]]', '["B"]', '条件错误：短时记忆容量为7±2组块，保持时间约20—30秒，不经复述会迅速遗忘，不能保持数分钟。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2994, 60, 23, 'judge', 0.6, '对遗忘原因的解释只有衰退说一种，即记忆痕迹得不到强化而逐渐减弱。', '[["A","正确"],["B","错误"]]', '["B"]', '绝对化表述：遗忘原因除衰退说外，还有干扰说（前摄抑制、倒摄抑制）、压抑说（动机性遗忘）、提取失败说等。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2995, 60, 24, 'judge', 0.6, '桑代克通过“饿猫开笼”实验提出试误说，认为学习的实质是形成刺激一反应的联结。', '[["A","正确"],["B","错误"]]', '["A"]', '桑代克通过饿猫开笼实验提出试误说，认为学习是刺激—反应联结的建立与巩固。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2996, 60, 25, 'judge', 0.6, '苛勒的黑猩猩接杆实验支持完形一顿悟说，认为学习是对情境中各要素关系的顿悟。', '[["A","正确"],["B","错误"]]', '["A"]', '苛勒的黑猩猩接杆实验支持完形—顿悟说，认为学习是对情境关系的顿悟而非盲目尝试。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2997, 60, 26, 'judge', 0.6, '学习动机是激发个体进行学习活动、维持已引起的学习活动，并使行为朝向一定学习目标的内部启动机制。', '[["A","正确"],["B","错误"]]', '["A"]', '学习动机是激发、维持学习活动并使之朝向学习目标的内部启动机制，由学习需要与诱因共同构成。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2998, 60, 27, 'judge', 0.6, '学校心理健康教育的重点是矫治已经出现心理疾病的学生，其余学生无需关注。', '[["A","正确"],["B","错误"]]', '["B"]', '以偏概全：学校心理健康教育面向全体学生，以预防和发展为主要任务，辅以个别辅导与转介。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (2999, 60, 28, 'judge', 0.6, '《中华人民共和国教育法》规定，教育活动必须符合国家和社会公共利益。', '[["A","正确"],["B","错误"]]', '["A"]', '《教育法》第八条规定，教育活动必须符合国家和社会公共利益。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3000, 60, 29, 'judge', 0.6, '义务教育阶段学校可以根据办学成本向学生收取适当的学费和杂费。', '[["A","正确"],["B","错误"]]', '["B"]', '《义务教育法》第二条：实施义务教育不收学费、杂费。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3001, 60, 30, 'judge', 0.6, '终身学习是教师专业发展的不竭动力，要求教师拓宽知识视野、更新知识结构。', '[["A","正确"],["B","错误"]]', '["A"]', '终身学习是教师专业发展的不竭动力，要求教师拓宽视野、更新知识结构、潜心钻研业务。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3002, 60, 31, 'single', 1.0, '某校通过教职工代表大会，组织教师对学校教育教学、管理工作和教育行政部门的工作提出意见和建议。依据《中华人民共和国教师法》，该校上述做法所保障的教师权利是（　）', '[["A","教育教学权"],["B","指导评价权"],["C","科学研究权"],["D","民主管理权"]]', '["D"]', '《教师法》第七条赋予教师民主管理权，即教师有权通过教职工代表大会等形式对学校教育教学、管理工作和教育行政部门的工作提出意见和建议、参与民主管理。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3003, 60, 32, 'single', 1.0, '某县在调整教师工资时提出，教师工资可低于当地公务员水平以节约财政开支。该方案违反《中华人民共和国教师法》关于教师工资水平应当（　）的规定。', '[["A","不低于或者高于国家公务员的平均工资水平，并逐步提高"],["B","由学校自行决定，无需参照公务员标准"],["C","低于公务员工资水平以节约财政开支"],["D","仅按教龄长短确定，与职务和考核无关"]]', '["A"]', '《教师法》第二十五条规定，教师的平均工资水平应当不低于或者高于国家公务员的平均工资水平，并逐步提高，以依法保障教师的工资报酬与福利待遇。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3004, 60, 33, 'single', 1.0, '某学生情绪体验深刻持久、行为孤僻迟缓、多愁善感、观察细致入微。按气质类型划分，该生属于（　）', '[["A","胆汁质"],["B","多血质"],["C","粘液质"],["D","抑郁质"]]', '["D"]', '抑郁质表现为情绪体验深刻持久、行为孤僻迟缓、多愁善感、观察细致，是四种典型气质类型之一，气质无优劣之分，教育应因材施教、扬长避短。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3005, 60, 34, 'single', 1.0, '在学校文化的构成中，居于核心地位、决定学校文化整体性质的是（　）', '[["A","学校精神文化"],["B","学校物质文化"],["C","学校制度文化"],["D","学校行为文化"]]', '["A"]', '学校精神文化（办学理念、校风学风等）是学校文化的核心与灵魂。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3006, 60, 35, 'single', 1.0, '某小学班主任在教研会上提出，学生的口头语言能力在幼儿期发展最快，一旦错过便难以弥补，教育应当抓住这一时期。该班主任主张教育要抓住“关键期”，其依据是个体身心发展的（　）', '[["A","不平衡性"],["B","顺序性"],["C","阶段性"],["D","个别差异性"]]', '["A"]', '同一方面在不同年龄阶段发展速度不同（或不同方面发展不同步），属不平衡性，据此提出抓住关键期。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3007, 60, 36, 'single', 1.0, '某县教育局为控制辍学，对拒不送适龄子女入学的监护人依法下达责令限期改正通知书，并督促其送子女入学。该县的做法最能体现义务教育的（　）', '[["A","普及性"],["B","免费性"],["C","强制性"],["D","基础性"]]', '["C"]', '义务教育三特征：强制性（最本质）、普及性（普遍性）、免费性。县教育局对拒不送子女入学的监护人责令改正并督促入学，体现的正是强制性。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3008, 60, 37, 'single', 1.0, '初中生小杰是一名网络游戏玩家，某网络游戏服务提供者在每日二十二时至次日八时仍允许小杰登录并为其提供游戏服务。依据《中华人民共和国未成年人保护法》，该服务提供者的做法违反了对未成年人的（　）', '[["A","网络保护"],["B","学校保护"],["C","社会保护"],["D","政府保护"]]', '["A"]', '《未成年人保护法》设立“网络保护”专章，规定网络游戏服务提供者不得在每日二十二时至次日八时向未成年人提供网络游戏服务，旨在防范网络沉迷、保护未成年人身心健康。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3009, 60, 38, 'single', 1.0, '某班班主任李老师坚持课后为学习吃力的学生单独答疑，从不当众公布学生的成绩排名，也不因成绩差别而区别对待。李老师的做法最符合下列哪一项师德规范要求（　）', '[["A","对学习困难学生耐心辅导、一视同仁，并保护其自尊心"],["B","为督促学习，当众公布全班学生的成绩排名"],["C","对违纪学生罚站一整节课以做效尤"],["D","优先关注成绩优异的学生，课余只为优生答疑"]]', '["A"]', '“关爱学生”要求教师关心爱护全体学生、尊重学生人格、平等公正对待学生、保护学生安全与健康、维护学生权益，不讽刺挖苦、不歧视学生。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3010, 60, 39, 'single', 1.0, '某校新入职的王老师在日常工作中，既要承担学科教学，又要管理班级、开展家访与心理健康辅导，还要参与教研与课题研究，同事们说他“身兼数职”。这体现了教师职业角色的（　）特点。', '[["A","专业化"],["B","权威化"],["C","多样化"],["D","单一化"]]', '["C"]', '教师同时承担传道者、授业解惑者、示范者、管理者、朋友、研究者等角色，体现职业角色的多样化。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3011, 60, 40, 'single', 1.0, '某班课堂上学生可以自由发表意见、师生共同商定班级规则，学习氛围活跃而有序。该班班主任的做法所体现的师生关系类型属于（　）', '[["A","专制型"],["B","民主型"],["C","放任型"],["D","对立型"]]', '["B"]', '师生共同商定规则、氛围活跃且有序，属民主型师生关系。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3012, 60, 41, 'single', 1.0, '《义务教育课程方案（2022年版）》在课程设置上的重要变化之一是，将（　）从综合实践活动课程中独立出来并设置独立课时。', '[["A","劳动与信息科技"],["B","语文与数学"],["C","体育与健康"],["D","道德与法治"]]', '["A"]', '《义务教育课程方案（2022年版）》优化课程设置，将劳动、信息科技从综合实践活动课程中独立出来并设置独立课时，同时强化课程的综合性与实践性。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3013, 60, 42, 'single', 1.0, '进入青春期后，小敏开始关注自己的内心世界，常思考“我是怎样的人”“我将来要成为什么样的人”，并依据内在的价值标准评价自己。按自我意识发展的阶段划分，小敏此时的自我意识发展处于（　）', '[["A","生理自我"],["B","心理自我"],["C","社会自我"],["D","理想自我"]]', '["B"]', '自我意识发展经历生理自我、社会自我、心理自我三阶段：生理自我形成于婴幼儿期，社会自我在儿童期至青春期前发展，心理自我于青少年期逐步确立，表现为关注内心世界、依据内在价值标准评价自己，标志自我意识的成熟。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3014, 60, 43, 'single', 1.0, '某教材对“分数”的安排在二年级初步认识、五年级系统学习、六年级拓展应用，内容逐步加深。这种课程内容组织方式属于（　）', '[["A","直线式"],["B","横向组织"],["C","螺旋式"],["D","逻辑顺序"]]', '["C"]', '同一内容在不同学段重复出现并逐步加深，属螺旋式组织。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3015, 60, 44, 'single', 1.0, '某区教育局在招生工作中要求，适龄儿童、少年应当在（　）学校就近入学，地方各级人民政府应当依法保障其免试入学的权利。这一要求符合《中华人民共和国义务教育法》的规定。', '[["A","父母工作单位所在地"],["B","任意选择的"],["C","户籍所在地"],["D","成绩最优秀的"]]', '["C"]', '《义务教育法》第十二条规定，适龄儿童、少年在户籍所在地学校就近入学；父母或者其他法定监护人在非户籍所在地工作或者居住的，当地人民政府应当为其提供平等接受义务教育的条件。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3016, 60, 45, 'single', 1.0, '语文教师李老师在讲《岳阳楼记》时，既讲清文言知识，又引导学生体会“先天下之忧而忧”的家国情怀。李老师的做法体现的教学原则是（　）', '[["A","理论联系实际原则"],["B","科学性与思想性相统一原则"],["C","启发性原则"],["D","循序渐进原则"]]', '["B"]', '既讲知识（科学性）又育情怀（思想性），体现科学性与思想性相统一。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3017, 60, 46, 'single', 1.0, '心理学中的“感觉阈限”是指刚刚能够引起感觉的最小刺激量，它反映的是人的（　）', '[["A","知觉的选择性"],["B","短时记忆的容量"],["C","思维的敏捷性"],["D","感受性（感觉阈限越低，感受性越强）"]]', '["D"]', '绝对感觉阈限是刚刚能引起感觉的最小刺激量；与之相对，差别感觉阈限是刚刚能引起差别感觉的刺激物间的最小差异量。二者分别从“有无”与“差异”两个维度刻画感受性，阈限越低感受性越强。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3018, 60, 47, 'single', 1.0, '某校鼓励教师参加进修或者其他方式的培训，并在课务安排上予以支持。依据《中华人民共和国教师法》，该校上述做法所保障的教师权利，旨在（　）', '[["A","允许教师脱离教学岗位长期休假"],["B","帮助教师不断更新知识、提升专业素质"],["C","免除教师的考核与评价"],["D","保证教师优先评聘高级职称"]]', '["B"]', '《教师法》第七条明确教师享有进修培训权，即参加进修或者其他方式的培训，旨在帮助教师不断更新知识、提升专业素质，以适应教育教学发展的需要。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3019, 60, 48, 'single', 1.0, '某中学在落实作业管理有关要求时，对学生每天书面作业的平均完成时间作出了上限规定，不得超过（　）', '[["A","60 分钟"],["B","120 分钟"],["C","30 分钟"],["D","90 分钟"]]', '["D"]', '教育部《关于加强义务教育学校作业管理的通知》规定，小学一、二年级不布置家庭书面作业，小学其他年级平均完成时间不超过60分钟，初中每天书面作业平均完成时间不超过90分钟。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3020, 60, 49, 'single', 1.0, '某小学科学课上，王老师先播放一段“货轮触礁”的真实视频，再让学生围绕救援方案自主探究、协作交流、建构认识并评价效果。王老师采用的教学模式是（　）', '[["A","抛锚式（情境一探究式）"],["B","传递一接受式"],["C","自学一辅导式"],["D","示范一模仿式"]]', '["A"]', '抛锚式（情境一探究）教学以真实情境中的“锚”为起点，经历探究、协作、建构与评价。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3021, 60, 50, 'single', 1.0, '某班班主任刘老师发现，同一名学生在作文里写下的自我评价，与他在班会讨论、社团活动、班级值日中的实际表现常常对不上。刘老师由此判断：要了解学生的真实品德水平，不能只看他怎么说，更要看他在与同学相处、参与集体事务时怎么做。刘老师这一判断所依据的德育过程规律是（　）', '[["A","学生的知、情、意、行统一发展"],["B","学生思想内部矛盾转化"],["C","学生在活动和交往中形成思想品德"],["D","学生思想品德形成的长期性与反复性"]]', '["C"]', '德育过程的基本规律之一：学生的思想品德在活动和交往中形成，又在活动和交往中表现并接受检验。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3022, 60, 51, 'single', 1.0, '某校八年级学生小杰课间在楼道奔跑时撞伤同学，家长要求学校全额赔偿。经查，该校对未成年学生的安全教育、设施维护与课间巡查均符合规定。依据《学生伤害事故处理办法》，下列认定正确的是（　）', '[["A","凡发生在校园内的学生伤害事故，学校均应承担赔偿责任"],["B","只要事故发生在校期间，学校即必然承担主要责任"],["C","学校已履行相应职责、行为并无不当的，不承担法律责任"],["D","学生伤害事故一律由致害学生的监护人承担全部责任"]]', '["C"]', '《学生伤害事故处理办法》规定，学生伤害事故的责任应当根据相关当事人的行为与损害后果之间的因果关系依法确定；学校已履行相应职责、行为并无不当的，不承担法律责任。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3023, 60, 52, 'single', 1.0, '班主任陈老师注重营造温馨的班级氛围，以自身人格魅力感染学生，使学生在潜移默化中受到教育。该班主任主要运用的德育方法是（　）', '[["A","说服教育法"],["B","情感陶冶法"],["C","自我教育指导法"],["D","品德评价法"]]', '["B"]', '通过人格感化、环境熏陶、艺术感染使学生在潜移默化中受教育，属情感陶冶法。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3024, 60, 53, 'single', 1.0, '班主任对一个学期以来学生在思想品德、学业、身心等方面的表现作出综合评价。这一工作环节属于（　）', '[["A","建立学生成长档案"],["B","个别教育"],["C","家校联系"],["D","操行评定"]]', '["D"]', '操行评定是班主任对学生一学期思想品德、学业、身心等表现的综合性评价。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3025, 60, 54, 'single', 1.0, '小辉的数学成绩在多次努力后仍无明显起色，此后他上课不再听讲、作业也不完成，常说“再怎么学也没用”。班主任发现这一情况后，判断小辉表现出的心理现象是（　）', '[["A","被动、绝望、放弃尝试的心理状态"],["B","更强的成就动机与掌控感"],["C","对任务难度的准确判断能力"],["D","自动化的高效学习策略"]]', '["A"]', '塞利格曼通过狗的电击实验提出“习得性无助”：当个体反复经历无法控制的不利事件后，会形成被动、绝望、放弃尝试的心理状态。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3026, 60, 55, 'single', 1.0, '某班课堂上学生情绪低落、注意力涣散，对教师的提问反应冷淡，师生互动明显减少。班主任观察到这一情况后，判断该班的课堂气氛属于（　）', '[["A","积极的"],["B","对抗的"],["C","民主的"],["D","消极的"]]', '["D"]', '消极课堂气氛表现为学生紧张拘谨、反应冷淡、注意力涣散、互动减少。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3027, 60, 56, 'single', 1.0, '班主任在处理学生问题时坚持“对事不对人”，同样的违纪行为给予同样的处理。这体现的班主任工作原则是（　）', '[["A","学生主体原则"],["B","民主公正原则"],["C","因材施教原则"],["D","以身作则原则"]]', '["B"]', '民主公正原则要求班主任公平对待每一位学生，处理问题对事不对人。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3028, 60, 57, 'single', 1.0, '幼童小轩头脑中已有"鸟"的图式，第一次见到麻雀时，把它归入"鸟”，后来见到鸵鸟又修正了原有的认识。按皮亚杰的理论，这两个过程依次属于（　）', '[["A","平衡与失衡"],["B","泛化与分化"],["C","正迁移与负迁移"],["D","同化与顺应"]]', '["D"]', '同化是把新刺激纳入已有图式，顺应是改变图式以适应新刺激，二者共同促进认知平衡。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3029, 60, 58, 'single', 1.0, '王老师发现，班上的学生王芳做题速度慢但错误率低，善于对多种可能进行权衡后再作答。王芳的认知风格属于（　）', '[["A","场依存型"],["B","场独立型"],["C","冲动型"],["D","沉思型"]]', '["D"]', '沉思型认知风格：反应慢但错误少，倾向于权衡多种可能后再作答。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3030, 60, 59, 'single', 1.0, '奥苏贝尔根据学习进行的方式和学习材料与学习者原有知识的关系，把学习划分为（　）', '[["A","接受学习与发现学习、机械学习与有意义学习"],["B","信号学习、连锁学习、辨别学习等八类"],["C","知识学习、技能学习、行为规范学习"],["D","言语信息、智慧技能、认知策略等五类"]]', '["A"]', '奥苏贝尔从两个维度划分：按进行方式分接受学习与发现学习，按材料与原有知识关系分机械学习与有意义学习。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3031, 60, 60, 'single', 1.0, '在程序教学中，学生每答对一步即得到反馈，学习内容按小步子编排、学生自定步调推进。这一设计直接依据的理论是（　）', '[["A","经典性条件作用理论"],["B","社会学习理论"],["C","认知发现理论"],["D","操作性条件作用理论"]]', '["D"]', '程序教学以小步子、及时强化（反馈）为原则，直接依据斯金纳的操作性条件作用理论。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3032, 60, 61, 'single', 1.0, '布鲁纳认为，学习的最好动机来自学生对所学材料本身的兴趣。他提出的内在动机不包括（　）', '[["A","好奇内驱力"],["B","胜任内驱力"],["C","附属内驱力"],["D","互惠内驱力"]]', '["C"]', '布鲁纳提出的三种内在动机为好奇内驱力、胜任内驱力、互惠内驱力：“附属内驱力”属奥苏贝尔的划分。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3033, 60, 62, 'single', 1.0, '有意义学习产生的外部条件是（　）', '[["A","学习者具有有意义学习的心向"],["B","学习材料本身具有逻辑意义"],["C","学习者认知结构中具有适当的观念"],["D","学习者积极主动地进行加工"]]', '["B"]', '有意义学习的外部条件是学习材料本身具有逻辑意义：心向与认知结构属内部条件。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3034, 60, 63, 'single', 1.0, '建构主义学习理论强调学习的主动建构性、社会互动性和（　）', '[["A","接受性"],["B","普遍性"],["C","机械性"],["D","情境性"]]', '["D"]', '建构主义学习观强调主动建构性、社会互动性、情境性。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3035, 60, 64, 'single', 1.0, '罗杰斯主张的"有意义学习"的核心特征是（　）', '[["A","新旧知识建立非人为的、实质性的联系"],["B","通过强化形成刺激—反应联结"],["C","学习内容与学习者的经验、情感、需要相融合"],["D","在教师指导下接受系统知识"]]', '["C"]', '罗杰斯的有意义学习强调学习内容与个体经验、情感、需要相融合，是”全人"参与的学习。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3036, 60, 65, 'single', 1.0, '教师在课堂上设置有梯度的问题情境，使学生产生认知冲突与求知欲。这一做法旨在激发学生的（　）', '[["A","附属内驱力"],["B","自我提高内驱力"],["C","认知内驱力"],["D","替代性强化"]]', '["C"]', '创设问题情境引发认知冲突与求知欲，旨在激发认知内驱力（求知需要）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3037, 60, 66, 'single', 1.0, '学生能根据阅读进度调整自己的阅读速度、并在不理解时回看。这属于（　）', '[["A","认知策略"],["B","元认知策略"],["C","精加工策略"],["D","复述策略"]]', '["B"]', '根据监控结果调整阅读速度、回看，属元认知策略中的调节（监控）策略。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3038, 60, 67, 'single', 1.0, '下列做法中，最有利于促进学习迁移的是（　）', '[["A","大量机械重复同一类型的练习题"],["B","只讲结论不讲推导过程，以节省课堂时间"],["C","讲清基本原理与规则，提高学生的概括化水平"],["D","忽视学生原有认知结构，直接讲授新知识"]]', '["C"]', '促进迁移的关键在于讲清原理、提高概括化水平，并合理安排练习；机械重复、忽视认知结构均不利于迁移。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3039, 60, 68, 'single', 1.0, '问题解决的首要环节是（　）', '[["A","理解问题"],["B","发现问题"],["C","提出假设"],["D","检验假设"]]', '["B"]', '问题解决的一般过程：发现问题—理解问题—提出假设—检验假设，发现问题是首要环节。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3040, 60, 69, 'single', 1.0, '关于创造性的培养，下列做法不恰当的是（　）', '[["A","创设宽松的心理环境，允许学生标新立异"],["B","只奖励标准答案，对非常规答案一律否定"],["C","注重培养学生的发散思维与想象力"],["D","开设创造性课程，训练创造性技法"]]', '["B"]', '只奖励标准答案、否定非常规答案会压抑创造性，是不恰当做法。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3041, 60, 70, 'single', 1.0, '学生品德的形成一般经历依从、认同和（　）三个阶段。', '[["A","服从"],["B","模仿"],["C","内化"],["D","习惯"]]', '["C"]', '态度与品德形成经历依从（从众、服从）—认同—内化三个阶段，内化是最高阶段。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3042, 60, 71, 'single', 1.0, '某校心理咨询室既面向全体学生开设心理健康活动课、有计划地开展预防性教育，又对个别有需要的学生进行辅导与转介。该校的上述做法体现的学校心理辅导原则是（　）', '[["A","个别化原则"],["B","预防与发展相结合原则"],["C","保密性原则"],["D","医学化原则"]]', '["B"]', '面向全体、预防与发展相结合是学校心理辅导的基本原则（以发展性辅导为主）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3043, 60, 72, 'single', 1.0, '波斯纳提出的教师成长公式是（　）', '[["A","教师成长 = 经验 + 反思"],["B","教师成长 = 知识 + 技能"],["C","教师成长 = 教学 + 科研"],["D","教师成长 = 学历 + 教龄"]]', '["A"]', '波斯纳提出教师成长公式：经验 + 反思 = 成长，教学反思是专业成长的核心机制。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3044, 60, 73, 'single', 1.0, '《中华人民共和国教育法》规定的教育方针中，教育必须（　）', '[["A","为经济建设服务，与科学研究相结合"],["B","为提高升学率服务，与考试评价相结合"],["C","为人的个性发展服务，与兴趣培养相结合"],["D","为社会主义现代化建设服务、为人民服务，与生产劳动和社会实践相结合"]]', '["D"]', '《教育法》第五条规定的教育方针：教育必须为社会主义现代化建设服务、为人民服务，必须与生产劳动和社会实践相结合，培养德智体美劳全面发展的社会主义建设者和接班人。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3045, 60, 74, 'single', 1.0, '某中学教师张某在教学中把主要精力放在学业优秀的学生身上，对学习有困难的学生降低要求、不予辅导。该教师的做法违反《中华人民共和国义务教育法》关于教师在教育教学中应当（　）的规定。', '[["A","优先关注学业优秀学生，确保升学率"],["B","对学习困难学生降低要求，保证其顺利毕业"],["C","按学生家庭背景区别对待"],["D","平等对待学生，关注学生个体差异，因材施教，促进学生的充分发展"]]', '["D"]', '《义务教育法》第二十九条：教师在教育教学中应当平等对待学生，关注学生的个体差异，因材施教，促进学生的充分发展。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3046, 60, 75, 'single', 1.0, '某中学为提高升学率，占用休息日和寒暑假期组织义务教育阶段未成年学生集体补课，并大幅增加作业量。依据《中华人民共和国未成年人保护法》，该校的做法（　）', '[["A","违反法律关于合理安排学生学习时间、保障其休息娱乐和体育锻炼时间的规定"],["B","属于学校自主安排教学进度，法律不予干预"],["C","只要征得家长同意即为合法"],["D","属于提高教学质量的正当举措，应予鼓励"]]', '["A"]', '《未成年人保护法》规定，学校应当与未成年学生的父母或者其他监护人互相配合，合理安排未成年学生的学习时间，保障其休息、娱乐和体育锻炼的时间；不得占用国家法定节假日、休息日及寒暑假期组织义务教育阶段的未成年学生集体补课。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3047, 60, 76, 'single', 1.0, '某中学对有严重不良行为的学生小磊实施管理教育，校长拟定的下列措施中，不符合《中华人民共和国预防未成年人犯罪法》规定的是（　）', '[["A","予以训导"],["B","责令其退学"],["C","要求遵守特定的行为规范"],["D","要求参加特定的专题教育"]]', '["B"]', '学校对有严重不良行为的学生可采取训导、要求遵守特定行为规范、参加专题教育、校内服务等措施，但不得责令退学（义务教育阶段不得剥夺受教育权）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3048, 60, 77, 'single', 1.0, '某中学八年级学生小磊多次在课堂上扰乱秩序、顶撞教师，学校拟对其实施较重惩戒。依据《中小学教育惩戒规则（试行）》，该校拟采取的下列措施中，属于较重惩戒的是（　）', '[["A","由科任教师点名批评"],["B","由学校德育工作负责人予以训导，并安排其承担校内公益服务任务"],["C","责令其在教室内站立一节课"],["D","责令其向被顶撞的教师赔礼道歉并作书面检讨"]]', '["B"]', '《中小学教育惩戒规则（试行）》分层设定惩戒：点名批评、责令赔礼道歉或作口头（书面）检讨、一节课堂教学时间内的教室内站立等属教师可当场实施的惩戒；由学校德育工作负责人训导、承担校内公益服务任务、安排接受专门校规校纪教育、暂停或限制参加校外集体活动等属较重惩戒，由学校实施。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3049, 60, 78, 'single', 1.0, '《新时代中小学教师职业行为十项准则》要求教师"不得组织、参与有偿补课，或为校外培训机构和他人介绍生源、提供相关信息”。这属于（　）的要求。', '[["A","规范从教行为"],["B","关心爱护学生"],["C","坚守廉洁自律"],["D","坚持言行雅正"]]', '["A"]', '“规范从教行为”要求教师不得组织参与有偿补课、不得为校外培训机构介绍生源或提供相关信息。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3050, 60, 79, 'single', 1.0, '"双减"政策的核心目标是（　）', '[["A","减轻义务教育阶段学生作业负担和校外培训负担"],["B","减轻教师工作负担和家长经济负担"],["C","减少考试次数和课程门类"],["D","减少学生在校时间，提前放学"]]', '["A"]', '“双减”指减轻义务教育阶段学生过重作业负担和校外培训负担。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3051, 60, 80, 'single', 1.0, '2022年版义务教育课程标准强调核心素养导向。下列关于核心素养的表述正确的是（　）', '[["A","核心素养是知识与技能的简单叠加"],["B","核心素养只适用于高中阶段，义务教育阶段仍以双基为主"],["C","核心素养是课程育人价值的集中体现，是学生通过课程学习逐步形成的正确价值观、必备品格和关键能力"],["D","核心素养由考试命题决定，与教学过程无关"]]', '["C"]', '核心素养是课程育人价值的集中体现，是学生通过课程学习逐步形成的正确价值观、必备品格和关键能力，义务教育各学科均以核心素养为导向。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3052, 60, 81, 'multi', 1.6, '教师备课需要做好的工作包括（　）', '[["A","钻研教材（课程标准与教科书）"],["B","只需写教案，其余工作可由教务处代劳"],["C","了解学生（知识基础、能力水平、学习需要）"],["D","设计教法与学法"],["E","制定学期（学年）教学进度计划、单元计划与课时计划"]]', '["A","C","D","E"]', '备课要做好钻研教材、了解学生、设计教法三项工作，并制定学期（学年）进度计划、单元计划和课时计划（教案）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3053, 60, 82, 'multi', 1.6, '依据《中华人民共和国教育法》，学校及其他教育机构按照国家有关规定，享有的自主管理权利包括（　）', '[["A","依法按学校章程实行自主管理"],["B","自主组织实施教育教学活动"],["C","拒绝任何国家机关依法进行的监督检查"],["D","自行设定并收取与教学无关的赞助费"],["E","依法依规招收学生和其他受教育者"]]', '["A","B","E"]', '《教育法》第二十九条规定学校及其他教育机构享有按章程自主管理、组织实施教育教学活动、招收学生或者其他受教育者、聘任教师及职工并实施奖励处分等权利；拒绝依法监督检查、擅自收取无关赞助费均属违法。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3054, 60, 83, 'multi', 1.6, '创造性思维的主要特征包括（　）', '[["A","流畅性"],["B","敏捷性"],["C","稳定性"],["D","变通性"],["E","独创性"]]', '["A","D","E"]', '创造性思维三大特征：流畅性、变通性（灵活性）、独创性。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3055, 60, 84, 'multi', 1.6, '依据《中华人民共和国教师法》，教师享有的权利包括（　）', '[["A","进行教育教学活动，开展教育教学改革和实验"],["B","从事科学研究、学术交流，参加专业的学术团体"],["C","指导学生的学习和发展，评定学生的品行和学业成绩"],["D","按时获取工资报酬，享受国家规定的福利待遇以及寒暑假期的带薪休假"],["E","对学校教育教学、管理工作和教育行政部门的工作提出意见和建议，通过教职工代表大会等形式参与学校的民主管理"]]', '["A","B","C","D","E"]', '《教师法》第七条规定教师享有教育教学权、科研学术权、指导评价权、获取报酬权、民主管理权、进修培训权六项权利，本题所列五项均属教师依法享有的权利。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3056, 60, 85, 'multi', 1.6, '学生在学校享有的人身权主要包括（　）', '[["A","身心健康权"],["B","选举权与被选举权"],["C","人身自由权"],["D","人格尊严权"],["E","隐私权"]]', '["A","C","D","E"]', '学生人身权包括身心健康权、人身自由权、人格尊严权、隐私权、名誉权、肖像权等；选举权属政治权利，未成年人尚不具备。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3057, 60, 86, 'multi', 1.6, '关于新课程改革提出的"三维目标"，下列说法正确的有（　）', '[["A","\\"知识与技能\\"是基础性目标"],["B","\\"过程与方法\\"强调让学生经历学习过程并掌握学习方法"],["C","三维目标是彼此割裂的三块，可以分别单独培养"],["D","\\"情感态度与价值观\\"关注学生在学习中的体验与价值形成"],["E","三维目标已被核心素养目标完全取代，教学中不再需要参考"]]', '["A","B","D"]', '三维目标三位一体、相互融合，而非割裂并列；核心素养是在三维目标基础上的发展与升华，三维目标仍具参考价值。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3058, 60, 87, 'multi', 1.6, '学校实施德育的途径包括（　）', '[["A","仅靠思想品德课即可，其他学科不必承担德育任务"],["B","思想品德课（道德与法治课）与其他学科教学"],["C","社会实践活动与课外校外活动"],["D","共青团、少先队、学生会组织的活动"],["E","班主任工作与校园文化环境"]]', '["B","C","D","E"]', '德育途径包括思想品德课与其他学科教学（基本途径）、社会实践活动、团队组织活动、班主任工作、校园文化等，各学科均须承担育人任务。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3059, 60, 88, 'multi', 1.6, '迈克卡等人把学习策略分为（　）', '[["A","认知策略"],["B","复述策略"],["C","元认知策略"],["D","资源管理策略"],["E","组织策略"]]', '["A","C","D"]', '迈克卡把学习策略分为认知策略、元认知策略、资源管理策略三类；复述策略、组织策略属认知策略的下位概念。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3060, 60, 89, 'multi', 1.6, '关于皮亚杰的认知发展阶段理论，下列说法正确的有（　）', '[["A","感知运动阶段（0—2岁）儿童主要通过感觉和动作认识世界，末期出现客体永久性"],["B","前运算阶段（2—7岁）儿童思维具有自我中心性、不可逆性"],["C","各阶段的发展顺序可以跨越，教育的超前训练能改变阶段次序"],["D","具体运算阶段（7—11岁）儿童能进行逻辑推理，但需借助具体事物支持"],["E","形式运算阶段（11岁以上）儿童能进行假设—演绎推理"]]', '["A","B","D","E"]', '皮亚杰四阶段依次为感知运动、前运算、具体运算、形式运算，顺序不可跨越，教育只能加速而不能改变阶段次序。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3061, 60, 90, 'multi', 1.6, '依据《教师资格条例》及《中华人民共和国教师法》，下列情形中，将丧失教师资格或者不得申请认定教师资格的有（　）', '[["A","故意犯罪受到有期徒刑以上刑事处罚"],["B","弄虚作假、骗取教师资格后被撤销"],["C","品行不良、侮辱学生，影响恶劣被撤销教师资格"],["D","因身体原因暂时不能上岗任教"],["E","教龄不足五年"]]', '["A","B","C"]', '依据《教师法》第十四条及《教师资格条例》，故意犯罪受到有期徒刑以上刑事处罚、弄虚作假骗取教师资格被撤销、品行不良侮辱学生影响恶劣被撤销的，丧失教师资格或不得申请认定；身体原因与教龄长短并非法定丧失事由。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3062, 61, 1, 'judge', 0.6, '塞利格曼的习得性无助实验表明，个体在经历多次无法控制的失败后会形成“无论如何努力都无济于事”的预期，进而放弃尝试。', '[["A","正确"],["B","错误"]]', '["A"]', '塞利格曼的习得性无助实验表明，反复的失控性失败会使个体产生“努力也无用”的预期，进而降低动机、放弃尝试，教育应帮助学生体验可控的成功。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3063, 61, 2, 'judge', 0.6, '前摄抑制是指后学习的材料对先学材料的保持所产生的干扰作用，倒摄抑制则指先学习的材料对后学材料的干扰作用。', '[["A","正确"],["B","错误"]]', '["B"]', '概念颠倒：前摄抑制是先前学习的材料对后继学习材料的干扰，倒摄抑制是后继学习材料对先前学习材料的干扰；题干把两者的方向说反了。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3064, 61, 3, 'judge', 0.6, '苏格拉底倡导的“产婆术”，是指教师把现成结论直接讲授给学生，学生只需接受和记忆。', '[["A","正确"],["B","错误"]]', '["B"]', '概念颠倒：苏格拉底的“产婆术”是通过问答引导学生自己得出结论，属启发式而非直接灌输。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3065, 61, 4, 'judge', 0.6, '感受性是感觉器官对适宜刺激的感觉能力，感觉阈限是刚刚引起感觉的最小刺激量，二者在数值上成正比关系。', '[["A","正确"],["B","错误"]]', '["B"]', '关系颠倒：感受性与感觉阈限在数值上成反比——感受性越高，感觉阈限越低；题干说成正比，故错误。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3066, 61, 5, 'judge', 0.6, '自我意识是个体对自己的身心状况以及自己与周围环境关系的主观认识，一般包括自我认识、自我体验和自我调节三个成分。', '[["A","正确"],["B","错误"]]', '["A"]', '自我意识是个体对自身的认识，包含自我认识（认知成分）、自我体验（情感成分，如自尊）和自我调节（意志成分）三方面，是人格调控的核心。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3067, 61, 6, 'judge', 0.6, '奥尔波特将人格特质划分为共同特质与个人特质，其中个人特质又包括首要特质、中心特质和次要特质。', '[["A","正确"],["B","错误"]]', '["A"]', '奥尔波特将人格特质分为共同特质（群体共有）与个人特质；个人特质又包括首要特质、中心特质和次要特质，用以解释个体独特性。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3068, 61, 7, 'judge', 0.6, '加涅将学习过程视为信息加工的过程，并把学习按顺序分为动机、领会、习得、保持、回忆、概括、作业、反馈八个阶段。', '[["A","正确"],["B","错误"]]', '["A"]', '加涅用信息加工观点解释学习，将学习过程分为动机、领会、习得、保持、回忆、概括、作业、反馈八个阶段，对各阶段教学有对应策略。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3069, 61, 8, 'judge', 0.6, '知识学习一般要经历知识的理解、巩固与应用三个基本环节，其中理解是形成理性认识的中心环节。', '[["A","正确"],["B","错误"]]', '["A"]', '知识学习一般经历理解、巩固、应用三个基本环节；理解是把握事物本质与规律、形成理性认识的中心环节。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3070, 61, 9, 'judge', 0.6, '福勒与布朗将教师的专业发展划分为关注情境、关注生存和关注学生三个阶段，新任教师走上岗位后通常最先进入关注情境阶段。', '[["A","正确"],["B","错误"]]', '["B"]', '顺序错位：福勒与布朗的阶段顺序为关注生存 → 关注情境 → 关注学生，新教师最先处于关注生存阶段（在意能否被接纳），而非关注情境阶段。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3071, 61, 10, 'judge', 0.6, '《深化新时代教育评价改革总体方案》提出，坚决克服唯分数、唯升学、唯文凭、唯论文、唯帽子的顽瘴痼疾，树立科学的教育评价导向。', '[["A","正确"],["B","错误"]]', '["A"]', '该方案明确提出坚决克服“五唯”顽瘴痼疾，改进结果评价、强化过程评价、探索增值评价、健全综合评价，树立科学的教育评价导向。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3072, 61, 11, 'judge', 0.6, '《义务教育课程方案（2022年版）》规定，小学一年级设置过渡性活动课程，注重做好幼小衔接。', '[["A","正确"],["B","错误"]]', '["A"]', '《义务教育课程方案（2022年版）》设置过渡性活动课程，强调小学低年级做好幼小衔接，帮助儿童平稳适应小学学习生活。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3073, 61, 12, 'judge', 0.6, '《教育强国建设规划纲要（2024—2035年）》将全面提升国民素养、促进人的全面发展作为教育强国建设的重要目标，并对加快建设高质量教育体系作出部署。', '[["A","正确"],["B","错误"]]', '["A"]', '《教育强国建设规划纲要（2024—2035年）》将促进人的全面发展、提升国民素养作为教育强国建设的重要目标，部署加快建设高质量教育体系。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3074, 61, 13, 'judge', 0.6, '《中华人民共和国学前教育法》规定，学前教育实行政府主导、社会参与、公民办并举的办园体制，大力发展普惠性学前教育。', '[["A","正确"],["B","错误"]]', '["A"]', '《中华人民共和国学前教育法》确立政府主导、社会参与、公民办并举的办园体制，明确大力发展普惠性学前教育。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3075, 61, 14, 'judge', 0.6, '《中共中央 国务院关于全面加强新时代大中小学劳动教育的意见》指出，劳动教育应贯通大中小学各学段，与德育、智育、体育、美育相融合。', '[["A","正确"],["B","错误"]]', '["A"]', '《全面加强新时代大中小学劳动教育的意见》要求劳动教育贯通各学段，与德智体美融合实施，强调动手实践与价值体认。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3076, 61, 15, 'judge', 0.6, '教育部《关于加强义务教育学校作业管理的通知》要求小学一、二年级不布置家庭书面作业，其他年级控制书面作业总量与时长。', '[["A","正确"],["B","错误"]]', '["A"]', '教育部《关于加强义务教育学校作业管理的通知》明确小学一、二年级不布置家庭书面作业，其他年级严控书面作业总量与时长。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3077, 61, 16, 'judge', 0.6, '《新时代中小学教师职业行为十项准则》要求教师坚守廉洁自律，不得索要、收受学生及家长的礼品、礼金。', '[["A","正确"],["B","错误"]]', '["A"]', '《新时代中小学教师职业行为十项准则》要求教师坚守廉洁自律，严禁索要、收受学生及家长礼品礼金，维护清正师风。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3078, 61, 17, 'judge', 0.6, '《中小学教育惩戒规则（试行）》规定，对违规违纪情节严重或者经教育拒不改正的义务教育阶段学生，学校可以给予不超过一周的停课停学。', '[["A","正确"],["B","错误"]]', '["A"]', '《中小学教育惩戒规则（试行）》规定，对违规违纪情节严重或经教育拒不改正的学生，学校可实施不超过一周的停课停学等较重以上惩戒。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3079, 61, 18, 'judge', 0.6, '《中华人民共和国未成年人保护法》规定，学校不得对未成年学生实施体罚、变相体罚或者其他侮辱人格尊严的行为。', '[["A","正确"],["B","错误"]]', '["A"]', '《中华人民共和国未成年人保护法》明确禁止学校对未成年学生实施体罚、变相体罚或者其他侮辱人格尊严的行为，违者依法追责。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3080, 61, 19, 'judge', 0.6, '《教师资格条例》规定，被撤销教师资格的，自撤销之日起五年内不得重新申请认定教师资格。', '[["A","正确"],["B","错误"]]', '["A"]', '《教师资格条例》第十九条规定，被撤销教师资格的，自撤销之日起五年内不得重新申请认定教师资格。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3081, 61, 20, 'judge', 0.6, '“晓之以理、动之以情、持之以恒、导之以行”分别对应道德认识、道德情感、道德意志和道德行为。', '[["A","正确"],["B","错误"]]', '["A"]', '“晓之以理—道德认识、动之以情—道德情感、持之以恒—道德意志、导之以行—道德行为”。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3082, 61, 21, 'judge', 0.6, '班集体的教育作用仅限于维持课堂纪律，与学生的社会性发展无关。', '[["A","正确"],["B","错误"]]', '["B"]', '以偏概全：班集体具有培养学生的集体意识、交往能力、自我教育能力和社会责任感等重要教育作用。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3083, 61, 22, 'judge', 0.6, '班主任的个别教育工作只需针对少数后进生，其他学生无需个别关注。', '[["A","正确"],["B","错误"]]', '["B"]', '范围缩小：个别教育应面向全体学生，包括先进生（防自满）、中等生（促发展）、后进生（促转化）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3084, 61, 23, 'judge', 0.6, '从记忆提取的角度看，再认比回忆（再现）更为容易。', '[["A","正确"],["B","错误"]]', '["A"]', '再认（事物再度出现时能认出）比回忆（事物不在眼前时重现）容易。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3085, 61, 24, 'judge', 0.6, '艾宾浩斯在研究遗忘时以有意义的诗歌为识记材料，绘制出遗忘曲线。', '[["A","正确"],["B","错误"]]', '["B"]', '条件替换：艾宾浩斯以无意义音节为材料研究遗忘，绘制出遗忘曲线。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3086, 61, 25, 'judge', 0.6, '课程计划的核心是课程标准，课程标准的核心是教科书，三者属于同一层级的课程文件。', '[["A","正确"],["B","错误"]]', '["B"]', '层级错位：课程计划的核心是课程设置（学科设置与课时安排），课程标准的核心是课程目标，教科书是教材的主要形式。三者层级由高到低，并非同一层级。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3087, 61, 26, 'judge', 0.6, '德育在学校工作中居于首要地位，因此德育应当取代教学成为学校的中心工作。', '[["A","正确"],["B","错误"]]', '["B"]', '定位混淆：德育居于首要地位，教学是学校的中心工作，二者是“首位”与“中心”的不同定位，不能相互取代。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3088, 61, 27, 'judge', 0.6, '我国的学制体系只包括初等教育和中等教育两个阶段，学前教育与高等教育不属于学制的范畴。', '[["A","正确"],["B","错误"]]', '["B"]', '范围遗漏：我国现行学制纵向分为学前教育、初等教育、中等教育和高等教育四个层次，各级各类学校均属学制范畴。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3089, 61, 28, 'judge', 0.6, '智力属于一般能力，其发展水平通常用智商（IQ）来表示。', '[["A","正确"],["B","错误"]]', '["A"]', '智力是一般能力（观察、记忆、思维、想象等），其发展水平常用智商表示。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3090, 61, 29, 'judge', 0.6, '《中华人民共和国未成年人保护法》要求学校建立学生欺凌防控工作制度，对教职员工、学生开展防治学生欺凌的教育和培训。', '[["A","正确"],["B","错误"]]', '["A"]', '《未成年人保护法》要求学校建立学生欺凌防控制度，对教职员工、学生开展防治欺凌的教育和培训。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3091, 61, 30, 'judge', 0.6, '根据《中华人民共和国民法典》，限制民事行为能力人在学校学习、生活期间受到人身损害，无论学校是否尽到教育、管理职责，学校都应当承担侵权责任。', '[["A","正确"],["B","错误"]]', '["B"]', '归责错误：《民法典》第一千二百条规定，限制民事行为能力人在学校或者其他教育机构学习、生活期间受到人身损害，学校未尽到教育、管理职责的才应当承担侵权责任，属过错责任而非无过错责任。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3092, 61, 31, 'single', 1.0, '某中学的马老师发现，学生小李多次考试失利后常说“再怎么努力也没用”，上课不再举手、作业敷衍应付。依据班杜拉的理论，马老师要帮助小李重建“我能行”的信念，最可靠的做法是让他获得（　）', '[["A","教师和同伴反复的言语劝说"],["B","观察到与自己水平相当的同学获得成功"],["C","平静而积极的情绪唤醒状态"],["D","通过自身努力取得看得见的学习进步"]]', '["D"]', '小李反复失利后认定"努力也没用"，是自我效能感低落的表现。班杜拉认为四类信息源中个体自身的成败经验最具决定性，故让他通过努力获得看得见的进步最可靠。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3093, 61, 32, 'single', 1.0, '某县一所小学要求教师在课堂上使用本地方言授课，认为这样“更接地气”。依据《中华人民共和国教育法》，该校的做法（　）', '[["A","合法，学校有权自主决定教学语言"],["B","合法，报县级教育行政部门备案后即可实施"],["C","不合法，学校教学应当推广使用全国通用的普通话和规范汉字"],["D","合法，方言教学属于地方课程特色"]]', '["C"]', '《中华人民共和国教育法》规定学校及其他教育机构进行教学，应当推广使用全国通用的普通话和规范汉字；要求教师一律用方言授课违反该项规定。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3094, 61, 33, 'single', 1.0, '学生小涛每次考试失利都说“自己脑子笨”，渐渐不肯再努力。任课老师拟对他进行归因训练，采取的核心做法应是引导其把失败归于（　）', '[["A","能力高低（稳定、不可控）"],["B","努力程度（内部、可控）"],["C","任务难度（稳定、外部）"],["D","运气好坏（外部、不稳定）"]]', '["B"]', '小涛把失败归于"脑子笨"即能力归因（稳定、不可控），会削弱坚持性；归因训练的核心是引导其归于努力这一内部可控因素。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3095, 61, 34, 'single', 1.0, '学期末，某中学的周老师为学生逐一撰写操行评语并评定其学业成绩。依据《中华人民共和国教师法》，该教师行使的这一权利是（　）', '[["A","教育教学权"],["B","指导评价权"],["C","科学研究权"],["D","民主管理权"]]', '["B"]', '周老师撰写操行评语、评定学业成绩，《中华人民共和国教师法》把这一项列为"指导学生的学习和发展，评定学生的品行和学业成绩"的权利，即指导评价权，区别于进行课堂教学的教育教学权。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3096, 61, 35, 'single', 1.0, '李老师在班会上表扬了拾金不味的小浩后，班上主动归还失物的行为明显增多。依据班杜拉的强化分类，其他学生行为增加的原因是（　）', '[["A","替代性强化"],["B","直接强化"],["C","自我强化"],["D","负强化"]]', '["A"]', '小浩（榜样）受表扬后，观察到这一结果的其他学生同类行为增多，属替代性强化；被强化的是观察者，而非榜样本人，故不是直接强化。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3097, 61, 36, 'single', 1.0, '放学时，某小学的陈老师看到校外人员在门口推搡本校学生，立即上前制止并报警。依据《中华人民共和国教师法》，陈老师的行为属于（　）', '[["A","可自主选择、可做可不做的事"],["B","学校临时指派的工作任务"],["C","应当履行的法定义务"],["D","受家长委托代为照管的职责"]]', '["C"]', '《中华人民共和国教师法》规定教师有义务制止有害于学生的行为或侵犯学生合法权益的行为，陈老师上前制止并报警是依法履行义务，可做可不做的说法错误。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3098, 61, 37, 'single', 1.0, '课堂上，吴老师总是耐心倾听小雯的发言，真诚接纳她不成熟甚至有偏差的想法，鼓励她按自己的节奏表达。依据罗杰斯的人本主义学习理论，该教师的角色应定位为（　）', '[["A","知识的权威灌输者"],["B","学生学习的促进者与帮助者"],["C","严格的行为监督者"],["D","置身事外的旁观者"]]', '["B"]', '罗杰斯主张以学生为中心，营造真诚、尊重、同感的心理氛围，教师是学生学习的促进者、帮助者，而非权威灌输者或旁观者。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3099, 61, 38, 'single', 1.0, '某县拟出台文件，把县域内义务教育学校教师的薪酬核定为低于当地公务员的平均水平。依据《中华人民共和国义务教育法》，该县的做法（　）', '[["A","合法，县域内教师的薪酬标准可由县级政府结合财力自行确定"],["B","合法，义务教育阶段教师不适用这一规定"],["C","不合法，教师工资必须高于同级公务员一倍以上"],["D","不合法，教师的平均工资水平应当不低于当地公务员的平均工资水平"]]', '["D"]', '《中华人民共和国义务教育法》规定教师平均工资水平应当不低于当地公务员的平均工资水平；该县把教师薪酬核定为低于当地公务员平均水平，违反上述规定。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3100, 61, 39, 'single', 1.0, '小满在学习“鲸鱼不是鱼”时，先试图把它纳入自己关于“鱼”的认识框架，解释不通后又调整了自己的认识结构。按皮亚杰的理论，该生适应环境所依靠的两种机制是（　）', '[["A","强化与消退"],["B","观察与模仿"],["C","同化与顺应"],["D","练习与反馈"]]', '["C"]', '小满先试图把“鲸鱼”纳入关于“鱼”的已有认识框架（同化），解释不通后调整认识结构（顺应），两种机制共同实现适应。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3101, 61, 40, 'single', 1.0, '某短视频平台拟面向未成年用户上线青少年模式时，需要依法设置相应功能。依据《中华人民共和国未成年人保护法》“网络保护”的要求，该平台应当设置（　）', '[["A","依据用户画像无限推送的功能"],["B","时间管理、权限管理、消费管理等功能"],["C","代写作业与自动答题的功能"],["D","无需监护人确认即可付费的功能"]]', '["B"]', '《中华人民共和国未成年人保护法》设网络保护专章，要求网络产品、服务提供者针对未成年人设置时间管理、权限管理、消费管理等功能；推送、代写作业、免确认付费均非法定要求。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3102, 61, 41, 'single', 1.0, '班主任方老师每天早自习前到宿舍看看住校学生的冷暖，悄悄为家庭困难的学生垫付书本费，对全班每一名学生都平等公正对待。每当发现学生情绪低落，她都会及时谈心疏导。方老师的这些行为集中体现的职业道德要求是（　）', '[["A","爱国守法"],["B","教书育人"],["C","关爱学生"],["D","终身学习"]]', '["C"]', '方老师关心学生冷暖与健康、维护学生权益、对每一名学生一视同仁，集中体现“关爱学生”这一职业道德要求。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3103, 61, 42, 'single', 1.0, '某县一所公办初中拟邀请社会人员每周进校，在课外活动时间组织学生诵读宗教典籍、开展宗教礼仪活动。依据《中华人民共和国教育法》，该校的这一做法（　）', '[["A","合法，课外活动内容由学校自主决定"],["B","合法，只要不占用课时且学生自愿参加"],["C","合法，但应当提前告知家长并取得同意"],["D","不合法，任何组织和个人不得利用宗教进行妨碍国家教育制度的活动"]]', '["D"]', '《中华人民共和国教育法》规定教育活动必须符合国家和社会公共利益，实行教育与宗教相分离，任何组织和个人不得利用宗教进行妨碍国家教育制度的活动；进校组织诵读宗教典籍、开展宗教礼仪违法。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3104, 61, 43, 'single', 1.0, '吴老师从不收受家长的礼品礼金，也不参加家长的宴请；衣着整洁得体、言谈文明，坚持以正直的言行影响身边的学生。学校在师德考核中号召全体教师学习吴老师的做法，其体现的师德要求是（　）', '[["A","为人师表"],["B","爱岗敬业"],["C","关爱学生"],["D","教书育人"]]', '["A"]', '吴老师不收礼品礼金、衣着得体、语言文明、以身作则，《中小学教师职业道德规范》把这一类要求归入“为人师表”。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3105, 61, 44, 'single', 1.0, '某县在审查一份关于在学校校门旁设立酒吧和网吧的申请时，拟直接予以批准。依据《中华人民共和国未成年人保护法》，该县的做法（　）', '[["A","合法，属于正常的市场准入"],["B","合法，责令经营者加装“未成年人禁止入内”标识即可"],["C","不合法，学校、幼儿园周边不得设置营业性娱乐场所、酒吧、互联网上网服务营业场所"],["D","合法，只要该场所不与校门同侧即可"]]', '["C"]', '《中华人民共和国未成年人保护法》规定，学校、幼儿园周边不得设置营业性娱乐场所、酒吧、互联网上网服务营业场所；仅张贴标识或换个方位均不能使这种设置合法化。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3106, 61, 45, 'single', 1.0, '我国《义务教育法》颁布于（　）', '[["A","1985 年"],["B","1986 年"],["C","1993 年"],["D","1995 年"]]', '["B"]', '《中华人民共和国义务教育法》1986年通过，2006年修订（全面修订），2015年、2018年两次修正。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3107, 61, 46, 'single', 1.0, '周老师在学期初依据课程标准自行设计单元教学方案、选择教学方法并组织实施时，学校不予干预。该校尊重的是教师最基本、最能体现职业特点的权利，该项权利是（　）', '[["A","科学研究权"],["B","教育教学权"],["C","获取报酬权"],["D","民主管理权"]]', '["B"]', '依课标自主设计单元方案、选择教学方法并组织实施，正是教育教学权的内容，该项权利是教师最基本、最能体现职业特点的权利。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3108, 61, 47, 'single', 1.0, '刘老师发现，同样一句话由周老师讲出来，学生格外信服。原来周老师从不大声训斥学生，却因其正直、真诚而深受敬佩。这种由教师的思想品质、道德情操和人格魅力所形成的威信属于（　）', '[["A","人格威信"],["B","学识威信"],["C","情感威信"],["D","权力威信"]]', '["A"]', '由教师的思想品质、道德情操、人格魅力所形成的威信是人格威信；依靠专业学识建立的才是学识威信。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3109, 61, 48, 'single', 1.0, '七年级的小磊这次月考失利后，班主任郑老师没有给他贴上“差生”标签，而是与他一起分析原因、制定改进计划，并告诉他“你还有很大进步空间”。郑老师据此采取的教育行为，符合学生的哪一本质属性？（　）', '[["A","学生是发展中的人"],["B","学生是被动接受教育的客体"],["C","学生是基本定型的社会成员"],["D","学生是完全由成人塑造的个体"]]', '["A"]', '郑老师不给学生贴"差生"标签、相信其仍有进步空间，体现了把小磊看作发展中的人——有巨大发展潜能与发展需要。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3110, 61, 49, 'single', 1.0, '某校在修订课程方案时提出，课程应以学科的基本概念和基本原理为主线，让学生掌握学科的基本结构。这一主张所依据的课程理论流派是（　）', '[["A","经验主义课程论"],["B","社会改造主义课程论"],["C","存在主义课程论"],["D","学科中心课程论"]]', '["D"]', '以学科基本概念原理为主线、让学生掌握学科基本结构，是学科中心课程论的基本主张；经验主义强调学生经验，社会改造主义强调社会问题。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3111, 61, 50, 'single', 1.0, '某区教研室在指导学校编制课程目标时提出，目标的确定不能只看教材，还要系统地做好三方面的研究。这三方面应当是（　）', '[["A","对教材的研究、对教法的研究、对学法的研究"],["B","对社会的研究、对学科的研究、对学生的研究"],["C","对教师的研究、对学校的研究、对家庭的研究"],["D","对目标的研究、对过程的研究、对结果的研究"]]', '["B"]', '课程目标的确定依据通常表述为对学生的研究、对社会的研究和对学科的研究三方面的研究，教材教法只是其中一环。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3112, 61, 51, 'single', 1.0, '教师在课程实施过程中根据实际情境对课程方案加以调整、改造，这种取向属于（　）', '[["A","忠实取向"],["B","相互调适取向"],["C","创生取向"],["D","技术取向"]]', '["B"]', '相互调适取向认为课程实施是课程方案与实际情况相互调整的过程；创生取向强调师生共同创造新的经验。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3113, 61, 52, 'single', 1.0, '泰勒提出的课程评价模式强调以目标为中心，判断教育目标的实现程度。该模式被称为（　）', '[["A","目标评价模式"],["B","CIPP 评价模式"],["C","目的游离评价模式"],["D","外观评价模式"]]', '["A"]', '泰勒的目标评价模式以预定目标为中心，判断目标达成程度。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3114, 61, 53, 'single', 1.0, '我国中小学教学的首要任务是（　）', '[["A","传授系统的科学文化基础知识和基本技能"],["B","发展学生的智力和体力"],["C","培养学生的审美情趣"],["D","形成学生的职业技能"]]', '["A"]', '教学的首要任务是传授系统的科学文化基础知识和基本技能（双基）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3115, 61, 54, 'single', 1.0, '教学过程的基本规律中，“教师主导作用与学生主体作用相统一”要求教师（　）', '[["A","一切由学生自主决定，教师只需旁观"],["B","严格掌控课堂，学生只需被动接受"],["C","只关注教学进度，不必顾及学生反应"],["D","充分发挥引导作用，同时调动学生的主动性与积极性"]]', '["D"]', '教师主导与学生主体相统一：既要发挥教师的引导作用，又要调动学生的主动性、积极性。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3116, 61, 55, 'single', 1.0, '李老师对学生禀赋各异的情形采取不同的引导方式：对退缩迟缓的加以鼓励，对冲动好胜的加以抑制。这与孔子“求也退，故进之；由也兼人，故退之”的做法一脉相承，李老师遵循的教学原则是（　）', '[["A","启发性原则"],["B","循序渐进原则"],["C","因材施教原则"],["D","巩固性原则"]]', '["C"]', '李老师针对票赋差异采取不同引导，与孔子"求也退，故进之；由也兼人，故退之"一脉相承，属因材施教原则。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3117, 61, 56, 'single', 1.0, '体育课上，秦老师在讲解示范后，安排学生反复完成投篮练习并逐个纠正动作，直至动作稳定、发力协调。秦老师主要运用的教学方法是（　）', '[["A","讲授法"],["B","演示法"],["C","讨论法"],["D","练习法"]]', '["D"]', '讲解示范之后让学生反复练习并逐个纠正动作，以实际训练为特征，属练习法；讲授、演示、讨论分属语言传递与直观感知类。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3118, 61, 57, 'single', 1.0, '班级授课制由夸美纽斯在理论上加以论证，其基本特征不包括（　）', '[["A","完全实行个别化，无固定进度"],["B","以班为单位集体授课"],["C","按课教学，以课时为单位"],["D","按学科和学年划分教学内容"]]', '["A"]', '班级授课制特征：班、课、时；“完全个别化、无固定进度"与之相反。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3119, 61, 58, 'single', 1.0, '道尔顿制的主要特点是（　）', '[["A","教师系统讲授，学生静听"],["B","大班上课、小班研究、个别教学相结合"],["C","按能力分组，各组进度相同"],["D","学生按合同自学，实验室作业，教师个别辅导"]]', '["D"]', '道尔顿制（帕克赫斯特）主张学生按合同自学、在实验室作业、教师个别辅导。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3120, 61, 59, 'single', 1.0, '学校德育内容的核心是（　）', '[["A","爱国主义教育"],["B","心理健康教育"],["C","劳动教育"],["D","法治教育"]]', '["A"]', '学校德育内容以爱国主义教育为核心，还包括理想、集体主义、劳动、法治、心理健康等。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3121, 61, 60, 'single', 1.0, '学生思想品德的形成具有长期性、反复性的特点，这要求德育工作（　）', '[["A","一次讲清即可，不必重复"],["B","只在出问题时进行教育"],["C","反复抓、抓反复，持之以恒"],["D","主要依靠制度约束，无需引导"]]', '["C"]', '品德形成具有长期性、反复性，德育要反复抓、抓反复，持之以恒。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3122, 61, 61, 'single', 1.0, '某校在联合社区和家长制定学生行为习惯培养方案时，要求学校、家庭、社区三方的标准保持一致、前后连贯。该校遵循的德育原则是（　）', '[["A","教育影响的一致性与连贯性原则"],["B","知行统一原则"],["C","长善救失原则"],["D","疏导原则"]]', '["A"]', '学校、家庭、社区三方要求一致并前后连贯，体现教育影响的一致性与连贯性原则。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3123, 61, 62, 'single', 1.0, '班主任钱老师在设计系列德育活动时，把专家报告会、主题班会讨论以及参观法治教育实践基地安排在同一单元。钱老师运用最多的德育方法是（　）', '[["A","榜样示范法"],["B","说服教育法"],["C","实际锻炼法"],["D","情感陶冶法"]]', '["B"]', '专家报告会、主题班会讨论、参观法治教育实践基地均以语言说理与事实说服为主，都属说服教育法。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3124, 61, 63, 'single', 1.0, '班级管理的功能主要包括社会化功能、个性化功能、（　）和管理功能。', '[["A","教育功能"],["B","选拔功能"],["C","惩罚功能"],["D","监督功能"]]', '["A"]', '班级管理的功能：社会化功能、个性化（选择）功能、教育功能、管理功能。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3125, 61, 64, 'single', 1.0, '班主任工作计划一般包括（　）和具体执行计划。', '[["A","教学计划"],["B","学期（或学年）计划"],["C","教研计划"],["D","培训计划"]]', '["B"]', '班主任工作计划一般包括学期（或学年）计划与具体执行计划（月、周计划）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3126, 61, 65, 'single', 1.0, '某校编排课程表时，把语文、数学等基础学科与体育、艺术、劳动课程统筹配置，避免任何一类课程被挤占。这主要体现的课程结构要求是（　）', '[["A","均衡性"],["B","综合性"],["C","选择性"],["D","系统性"]]', '["A"]', '义务教育课程方案要求课程结构体现均衡性、综合性和选择性。均衡性指各类课程比例适当、不被相互挤占。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3127, 61, 66, 'single', 1.0, '某校在学期初用一套测验了解学生已有的知识准备情况，据此调整教学计划与进度。这种做法体现的教学评价类型是（　）', '[["A","形成性评价"],["B","总结性评价"],["C","诊断性评价"],["D","相对性评价"]]', '["C"]', '诊断性评价在教学活动开始前进行，用于摸清学生的知识基础与准备状态；形成性评价在教学过程中进行，总结性评价在活动结束后进行。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3128, 61, 67, 'single', 1.0, '复习课上，刘老师发现不少学生看书“一视同仁”，便建议他们用红笔把关键处划出来再读。学生这样做主要利用了知觉的（　）', '[["A","整体性"],["B","理解性"],["C","恒常性"],["D","选择性"]]', '["D"]', '用红笔划出关键处，使关键处成为知觉对象、其余成为背景，利用了知觉的选择性。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3129, 61, 68, 'single', 1.0, '试卷发下来后，多数考生虽然背过公式却一时想不起用法，小阳却能迅速检索出解题所需的知识并熟练作答。小阳表现突出的是记忆品质中的（　）', '[["A","记忆速度的快慢"],["B","保持时间的长短"],["C","能否迅速、灵活地从记忆中提取所需知识"],["D","记忆内容的准确程度"]]', '["C"]', '小阳胜在能迅速、灵活地从记忆中提取解题所需知识，属记忆的准备性；记忆快慢是敏捷性，保持久智是持久性，是否精确是准确性。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3130, 61, 69, 'single', 1.0, '思维的品质不包括（　）', '[["A","冲动性与随意性"],["B","广阔性与深刻性"],["C","独立性与批判性"],["D","灵活性与敏捷性"]]', '["A"]', '思维品质包括广阔性、深刻性、独立性、批判性、灵活性、敏捷性、逻辑性；冲动性、随意性不是思维品质。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3131, 61, 70, 'single', 1.0, '"鱼和熊掌不可兼得"所描述的心理冲突属于（　）', '[["A","双避冲突"],["B","双趋冲突"],["C","趋避冲突"],["D","多重趋避冲突"]]', '["B"]', '两个都想要而只能取其一，属双趋冲突。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3132, 61, 71, 'single', 1.0, '学生考试前适度紧张有利于提高注意力与思维效率，过度紧张则可能发挥失常。这说明情绪具有（　）', '[["A","适应功能"],["B","感染功能"],["C","动机功能"],["D","信号功能"]]', '["C"]', '适度紧张提高活动效率、过度紧张降低效率，体现情绪对行为的动机（唤醒）功能，与耶克斯一多德森定律一致。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3133, 61, 72, 'single', 1.0, '气质类型中，表现为精力旺盛、直率热情、脾气急躁的是（　）', '[["A","多血质"],["B","胆汁质"],["C","黏液质"],["D","抑郁质"]]', '["B"]', '胆汁质：精力旺盛、直率热情、急躁冲动；多血质活泼好动、善交际；黏液质安静稳重；抑郁质敏感细腻。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3134, 61, 73, 'single', 1.0, '桑代克提出的学习三大定律是（　）', '[["A","准备律、练习律、效果律"],["B","近因律、频因律、效果律"],["C","强化律、消退律、泛化律"],["D","获得律、保持律、再现律"]]', '["A"]', '桑代克三大定律：准备律、练习律、效果律。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3135, 61, 74, 'single', 1.0, '韦纳归因理论中的"能力"属于（　）维度。', '[["A","内部的、不稳定的、可控的"],["B","外部的、稳定的、不可控的"],["C","外部的、不稳定的、不可控的"],["D","内部的、稳定的、不可控的"]]', '["D"]', '韦纳归因理论中能力属内部的、稳定的、不可控的维度。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3136, 61, 75, 'single', 1.0, '数学课上，宋老师在学生已经掌握"平行四边形"概念之后，再讲授"菱形是有一组邻边相等的平行四边形”。按奥苏贝尔的同化理论，学生此时的学习属于（　）', '[["A","上位学习"],["B","并列结合学习"],["C","下位学习"],["D","符号学习"]]', '["C"]', '学生已掌握上位的“平行四边形”概念，再学习其特例“菱形”，属下位学习中的派生类属。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3137, 61, 76, 'single', 1.0, '初二学生小阳在进行投篮技能练习时，前两周成绩稳步上升，第三周却连续多日不再进步甚至有所下滑。小阳遇到的这种现象称为（　）', '[["A","遗忘现象"],["B","定势现象"],["C","高原现象"],["D","迁移现象"]]', '["C"]', '练习到一定阶段出现暂时停顿甚至下降的现象称高原现象，多因动作或认知结构改组，坚持并调整练习方式可以突破。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3138, 61, 77, 'single', 1.0, '学期初，某小学要求新生统一到指定书店购买指定品牌的教辅资料和学习用具，学校按销售码洋收取返点。依据《中华人民共和国义务教育法》，该校的做法（　）', '[["A","合法，属于学校为学生统一提供便利"],["B","不合法，学校不得以向学生推销商品、服务等方式谋取利益"],["C","合法，属于正常的教辅采购"],["D","不合法，仅因指定书店购买侵犯了家长的自主选择权"]]', '["B"]', '《中华人民共和国义务教育法》规定学校不得违反国家规定收取费用，不得以向学生推销或者变相推销商品、服务等方式谋取利益；指定购买并按码洋收返点属变相推销牟利。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3139, 61, 78, 'single', 1.0, '某校学生小林在校期间突发疾病，任课教师发现后立即将其送医并通知家长，学校和教师的行为均无不当。依据《学生伤害事故处理办法》，该校的责任认定应当是（　）', '[["A","只要发生在校园内，学校就必须承担全部赔偿责任"],["B","学校已尽到相应职责、行为并无不当，不承担事故责任"],["C","学校虽无过错，仍应按公平原则全额补偿"],["D","由任课教师个人承担全部赔偿责任"]]', '["B"]', '《学生伤害事故处理办法》：学校已尽到相应职责、行为并无不当的不承担事故责任。小林突发疾病时教师及时送医、通知家长即属已尽职责。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3140, 61, 79, 'single', 1.0, '校长在组织师德学习时，要求教师逐条辨析《中小学教师职业道德规范》各条目的边界。下列表述中，不属于“教书育人”要求的是（　）', '[["A","遵循教育规律，实施素质教育"],["B","循循善诱，诲人不倦，因材施教"],["C","培养学生良好品行，激发学生创新精神"],["D","自觉抵制有偿家教，不利用职务之便谋取私利"]]', '["D"]', '“自觉抵制有偿家教，不利用职务之便谋取私利”属“为人师表”的要求，不属“教书育人”。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3141, 61, 80, 'single', 1.0, '期末家长会上，班主任把每位学生的进步幅度、课堂参与和作业习惯一并反馈给家长，明确表示不再按分数给学生排队，也不以分数作为评价学生的唯一标准。该班主任的做法体现的是（　）', '[["A","爱国守法"],["B","爱岗敬业"],["C","为人师表"],["D","教书育人"]]', '["D"]', '“不以分数作为评价学生的唯一标准”是规范中“教书育人”条目的明确规定，该班主任的做法正与之相符。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3142, 61, 81, 'multi', 1.6, '下列关于学生自我意识发展的表述中，正确的有（　）', '[["A","自我意识一般包括自我认识、自我体验和自我调节三个成分"],["B","新生儿即已具备完整的自我概念，自我意识的发展先于生理自我"],["C","青春期是自我意识发展的第二个飞跃期，独立性与自主性明显增强"],["D","自我意识一旦形成便固定不变，不受教育与交往活动的影响"],["E","自我体验是自我意识的情感成分，如自尊、自信与羞愧"]]', '["A","C","E"]', '自我意识一般包括自我认识、自我体验和自我调节；青春期是自我意识发展的第二飞跃期；自我体验如自尊、自信、羞愧。新生儿并不具备完整自我概念，自我意识也随年龄、教育与交往不断发展，并非固定不变。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3143, 61, 82, 'multi', 1.6, '气质与性格既密切联系又相互区别，下列对其关系的判断能够成立的有（　）', '[["A","气质较多地受神经系统活动类型的制约，具有较强的先天性"],["B","性格主要在后天环境与教育的影响下形成，具有较大的可塑性"],["C","气质决定性格的发展方向，性格对气质不产生任何影响"],["D","同一种气质类型的人可以形成很不相同的性格特征"],["E","气质类型本身并无好坏之分，各种气质都可以培养积极的品质"]]', '["A","B","D","E"]', '气质较多地受神经系统活动类型制约，具先天性且无好坏之分；性格主要在后天环境与教育中形成，可塑性大；同一种气质可以形成很不相同的性格。气质并不决定性格的方向，性格反过来也会影响气质的表现方式。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3144, 61, 83, 'multi', 1.6, '《中华人民共和国义务教育法》就教师的工资待遇与从业资格作出明确规定，下列表述中与之相符的有（　）', '[["A","学校可以根据生源情况自行决定聘用无教师资格的人员任教"],["B","教师的平均工资水平应当不低于当地公务员的平均工资水平"],["C","教师在教育教学中应当平等对待学生，关注个体差异，因材施教"],["D","教师应当尊重学生的人格，不得歧视学生，不得体罚或变相体罚"],["E","教师必须取得教师资格，国家实行教师资格制度"]]', '["B","C","D","E"]', '《义务教育法》有关教师的规定包括：平均工资水平不低于当地公务员、平等对待并因材施教、尊重人格且不得体罚、必须取得教师资格。生源紧张不能成为聘用无资格人员任教的理由。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3145, 61, 84, 'multi', 1.6, '同伴关系会深度介入学生的学习与发展，下列对其作用的分析能够成立的有（　）', '[["A","良好的同伴关系有助于满足学生的归属与爱的需要"],["B","同伴接纳程度高的学生往往具有更积极的自我概念"],["C","同伴间的模仿与竞争既可能促进也可能干扰学习"],["D","教师的片面评价可能加剧同伴关系中的排斥现象"],["E","同伴关系只影响社交表现，对学业成绩没有任何作用"]]', '["A","B","C","D"]', '良好同伴关系满足归属与爱的需要、促进积极自我概念；同伴间的模仿与竞争具有双向作用；教师的片面评价可能加剧同伴排斥。同伴关系也会通过动机、情绪与学习机会影响学业，并非与成绩无关。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3146, 61, 85, 'multi', 1.6, '《中华人民共和国预防未成年人犯罪法》确立了预防未成年人犯罪的教育矫治体系，下列表述中符合该法的有（　）', '[["A","学校应当将预防犯罪教育纳入学校教学计划，并及时制止、纠正学生的不良行为"],["B","对有严重不良行为的未成年人，可按照国家有关规定送入专门学校接受专门矫治教育"],["C","为警示他人，公安机关可以对有不良行为的未成年人予以公开披露"],["D","未成年人的父母或者其他监护人对未成年人的预防犯罪教育负有直接责任"],["E","任何单位和个人不得教唆、胁迫、引诱未成年人实施不良行为或严重不良行为"]]', '["A","B","D","E"]', '《预防未成年人犯罪法》要求学校把预防犯罪教育纳入教学计划、及时制止纠正不良行为；对严重不良行为的可送专门学校矫治；监护人对预防犯罪教育负直接责任；任何人不得教唆、胁迫、引诱未成年人实施不良行为。公开披露有不良行为的未成年人不利于教育挽救。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3147, 61, 86, 'multi', 1.6, '下列关于复述策略、精细加工策略与组织策略的表述，正确的有（　）', '[["A","复述策略旨在维持对材料的注意与保持，如重复、划线"],["B","精细加工策略通过新旧知识联系促进理解，如记忆术、做笔记"],["C","元认知策略不属于学习策略，应与学习策略单列分开"],["D","组织策略重在整合知识结构，如提纲、图表、归类"],["E","资源管理策略用于管理时间、环境与努力，如时间计划、求助"]]', '["A","B","D","E"]', '麦基奇将学习策略分为认知策略（复述、精细加工、组织）、元认知策略与资源管理策略；元认知策略是学习策略的重要组成部分，并非独立于其外。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3148, 61, 87, 'multi', 1.6, '心理学把下列因素视为影响问题解决的主要变量，其中应当纳入的有（　）', '[["A","问题情境与表征方式"],["B","定势与功能固着"],["C","原型启发"],["D","个体已有的知识经验与认知结构"],["E","动机强度、情绪状态与个性特征"]]', '["A","B","C","D","E"]', '影响问题解决的因素包括问题情境与表征方式、定势与功能固着、原型启发、个体已有的知识经验与认知结构，以及动机强度、情绪状态与个性特征，五项均属主要变量。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3149, 61, 88, 'multi', 1.6, '《中小学教育惩戒规则（试行）》对教育惩戒的实施作出了系统规范，下列表述中符合该规则的有（　）', '[["A","教育惩戒是学校和教师依法履行教育职责、纠正学生违规行为的必要手段"],["B","一般教育惩戒包括点名批评、责令赔礼道歉、一节课堂教学时间内的教室内站立等"],["C","较重教育惩戒由学校决定并实施，如由学校德育工作负责人予以训导"],["D","教师可以对违规学生当场处以罚款，以强化纪律意识"],["E","严禁因个别学生违规而惩罚全体学生，也不得因学业成绩惩罚学生"]]', '["A","B","C","E"]', '《中小学教育惩戒规则（试行）》明确教育惩戒是依法履行教育职责的手段；一般惩戒含点名批评、责令赔礼道歉、一节课堂教学时间内的教室内站立，较重惩戒由学校实施；严禁因个别学生违规惩罚全体、因学业成绩惩罚学生，更不得罚款。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3150, 61, 89, 'multi', 1.6, '某中学组织学生到校外基地开展研学活动，途中一名学生因学校租用的大巴车况不良发生事故受伤；同日，另一名学生放学后自行滞留教室攀爬窗台摔伤。依据《学生伤害事故处理办法》，下列判断正确的有（　）', '[["A","车辆由租车公司提供，学校对大巴车况不良致伤不承担任何责任"],["B","学生放学后自行滞留学校期间受伤，学校行为并无不当的不承担事故责任"],["C","学校组织校外活动未在可预见的范围内采取必要安全措施的，应承担相应责任"],["D","因学校教职工在履行职务中的重大过失造成事故，学校赔偿后可向有关责任人员追偿"],["E","学校对未成年学生不承担监护职责，但依法负有教育、管理和保护的义务"]]', '["B","C","D","E"]', '依据《学生伤害事故处理办法》，学校组织校外活动未在可预见范围内采取必要安全措施的应承担相应责任；学生在放学后自行滞留学校期间受伤、学校行为并无不当的不承担事故责任；学校对未成年学生不承担监护职责，仅负教育、管理和保护职责；因教职工履行职务中的重大过失造成事故，学校赔偿后可向有关责任人员追偿。租用车辆车况不良仍属学校应尽的安全保障义务范围。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3151, 61, 90, 'multi', 1.6, '新课程改革倡导的教学观转变包括（　）', '[["A","从“教育者为中心”转向“学习者为中心”"],["B","从“启发式”转向“灌输式”"],["C","从\\"教会学生知识\\"转向\\"教会学生学习\\""],["D","从\\"重结论轻过程\\"转向\\"重结论更重过程\\""],["E","从\\"关注学科\\"转向\\"关注人\\""]]', '["A","C","D","E"]', '新课改教学观四项转变：由教育者中心转向学习者中心、由教会知识转向教会学习、由重结论轻过程转向重结论更重过程、由关注学科转向关注人。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3152, 62, 1, 'judge', 0.6, '斯金纳的操作性条件反射理论认为，可变比率强化程式比固定比率强化更能抵抗行为的消退。', '[["A","正确"],["B","错误"]]', '["A"]', '斯金纳操作性条件反射指出，间歇（可变比率、可变时距）强化比连续强化更能维持行为、抵抗消退，因为个体无法预测下一次强化何时出现。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3153, 62, 2, 'judge', 0.6, '依据耶克斯一多德森定律，学习动机强度与学习效率之间呈倒U形关系，中等强度的动机最有利于学习效率的提高，且最佳动机水平随任务难度的不同而变化。', '[["A","正确"],["B","错误"]]', '["A"]', '耶克斯一多德森定律表明，动机强度与学习效率呈倒U形关系：动机过弱或过强都不利于效率提高，中等强度的动机最有利于学习；且任务难度不同，最佳动机水平也不同。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3154, 62, 3, 'judge', 0.6, '塞利格曼（Seligman）的习得性无助实验表明，当个体反复经历无法控制的负面事件后，可能放弃尝试，产生“做什么都没用”的无助感。', '[["A","正确"],["B","错误"]]', '["A"]', '塞利格曼以狗为对象的实验发现，反复遭受不可控电击且无法逃避的狗，后来即使能轻易逃避也不再尝试，表现出习得性无助；该概念后被用于解释学生的无力感与动机缺失。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3155, 62, 4, 'judge', 0.6, '形式训练说认为，迁移能否发生取决于两种学习情境是否存在共同要素，而迁移是具体的、有条件的。', '[["A","正确"],["B","错误"]]', '["B"]', '张冠李戴：形式训练说以官能心理学为依据，主张心理官能经训练改善后可普遍迁移；“迁移取决于两种情境是否存在共同要素、迁移是具体有条件的”是桑代克共同要素说的主张。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3156, 62, 5, 'judge', 0.6, '罗森塔尔（Rosenthal）的实验表明，教师对学生的期望会通过态度与行为传递给学生，并可能使学生的表现朝期望方向发展；这种皮格马利翁效应往往借助教师不同的“强化”方式影响学生的自我效能。', '[["A","正确"],["B","错误"]]', '["A"]', '罗森塔尔效应（皮格马利翁效应）说明教师期望具有自我实现预言作用：教师对高期望学生给予更多关注、鼓励与“强化”，学生因而更自信、表现更好，形成良性循环。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3157, 62, 6, 'judge', 0.6, '在创造性解决问题时，从其他事物（原型）中获得启发、找到解决途径的心理机制称为原型启发，如鲁班受草叶划伤启发而发明锯子。', '[["A","正确"],["B","错误"]]', '["A"]', '原型启发是创造性思维的重要机制，指从自然界或生活中的“原型”获得启示，迁移到当前问题的解决方案；鲁班受草叶边缘小齿划伤手启发发明锯，即典型例子。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3158, 62, 7, 'judge', 0.6, '学生在学校享有受教育权、人身权和财产权等基本权利。', '[["A","正确"],["B","错误"]]', '["A"]', '学生依法享有受教育权、人身权（人格尊严、隐私、身心健康等）和财产权。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3159, 62, 8, 'judge', 0.6, '《中华人民共和国教师法》规定，教师的医疗同当地国家公务员享受同等的待遇，并定期对教师进行身体健康检查。', '[["A","正确"],["B","错误"]]', '["A"]', '《教师法》第二十九条规定，教师的医疗同当地国家公务员享受同等的待遇，定期对教师进行身体健康检查，并因地制宜安排教师进行休养。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3160, 62, 9, 'judge', 0.6, '《中华人民共和国义务教育法》规定，适龄儿童、少年的父母或者其他监护人无正当理由未送其入学接受义务教育的，由公安机关给予治安管理处罚。', '[["A","正确"],["B","错误"]]', '["B"]', '法律后果张冠李戴：《义务教育法》第五十八条规定，父母或者其他监护人无正当理由未送适龄儿童、少年入学接受义务教育的，由当地乡镇人民政府或者县级人民政府教育行政部门给予批评教育、责令限期改正，而非由公安机关给予治安管理处罚。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3161, 62, 10, 'judge', 0.6, '《中华人民共和国未成年人保护法》（社会保护）规定，营业性歌舞娱乐场所、酒吧、互联网上网服务营业场所等不适宜未成年人活动的场所，不得允许未成年人进入。', '[["A","正确"],["B","错误"]]', '["A"]', '《未成年人保护法》（社会保护）第五十八条等规定，营业性歌舞娱乐场所、酒吧、互联网上网服务营业场所等不适宜未成年人活动的场所，不得允许未成年人进入，并应在显著位置设置未成年人禁入标志。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3162, 62, 11, 'judge', 0.6, '依据《教师资格条例》，参加教师资格考试有作弊行为的，其考试成绩作废，且1年内不得再次参加教师资格考试。', '[["A","正确"],["B","错误"]]', '["B"]', '年限设错：《教师资格条例》第二十条规定，参加教师资格考试有作弊行为的，其考试成绩作废，3年内不得再次参加教师资格考试，题干“1年”错误。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3163, 62, 12, 'judge', 0.6, '《中小学教师职业道德规范》要求教师为人师表，以身作则、言传身教，自觉抵制社会不良风气影响，不利用职务之便谋取私利。', '[["A","正确"],["B","错误"]]', '["A"]', '《中小学教师职业道德规范》之“为人师表”要求教师以身作则、言传身教，自觉抵制社会不良风气影响，不利用职务之便谋取私利，作风正派、廉洁奉公。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3164, 62, 13, 'judge', 0.6, '《新时代中小学教师职业行为十项准则》要求教师增强安全意识，加强安全教育，保护学生安全，在教育教学活动中遇突发事件、面临危险时，不得不顾学生安危、擅离职守。', '[["A","正确"],["B","错误"]]', '["A"]', '“加强安全防范”是十项准则之一：要求教师增强安全意识、加强安全教育、保护学生安全、防范事故风险，在教育教学活动中遇突发事件、面临危险时，不得不顾学生安危、擅离职守、自行逃离。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3165, 62, 14, 'judge', 0.6, '中共中央办公厅、国务院办公厅2021年印发的"双减"文件，要求全面压减作业总量和时长，提升学校课后服务水平，不再审批新的面向义务教育阶段学生的学科类校外培训机构。', '[["A","正确"],["B","错误"]]', '["A"]', '“双减”政策核心在减轻过重作业负担与校外培训负担，提升学校教育教学质量与课后服务水平。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3166, 62, 15, 'judge', 0.6, '教育部印发的《中小学德育工作指南》明确，中小学德育的主要内容包括理想信念教育、社会主义核心价值观教育、中华优秀传统文化教育、生态文明教育和心理健康教育。', '[["A","正确"],["B","错误"]]', '["A"]', '教育部2017年印发的《中小学德育工作指南》明确德育内容包括理想信念教育、社会主义核心价值观教育、中华优秀传统文化教育、生态文明教育、心理健康教育五大板块。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3167, 62, 16, 'judge', 0.6, '教育目的只对学校层面的培养目标起指导作用，对课程目标和教学目标没有约束力。', '[["A","正确"],["B","错误"]]', '["B"]', '作用窄化：教育目的贯穿教育活动的全过程，对培养目标、课程目标、教学目标均具有导向、调控和评价作用。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3168, 62, 17, 'judge', 0.6, '学校教育制度简称学制，它规定各级各类学校的性质、任务、入学条件、修业年限以及它们之间的关系。', '[["A","正确"],["B","错误"]]', '["A"]', '学制是各级各类学校的总体系，规定学校的性质、任务、入学条件、修业年限及其相互关系。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3169, 62, 18, 'judge', 0.6, '遗忘的进程受学习材料的性质、学习程度、材料所处位置等因素影响。', '[["A","正确"],["B","错误"]]', '["A"]', '影响遗忘进程的因素是多方面的，题干列举的几项均为常见变量。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3170, 62, 19, 'judge', 0.6, '研究表明，过度学习达到 150%（即恰能背诵后再学习 50%）时保持效果最好，因此过度学习的程度越高（如达到 200%、300%），保持效果就越好，也不会出现疲劳与厌烦。', '[["A","正确"],["B","错误"]]', '["B"]', '推论过度：过度学习达到 150% 时保持效果最佳，但超过这一限度后保持效果不再显著提高，还可能出现疲劳、厌烦等“报酬递减”现象。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3171, 62, 20, 'judge', 0.6, '教学中既要传授知识，又要进行思想品德教育，这一要求体现的是理论联系实际原则。', '[["A","正确"],["B","错误"]]', '["B"]', '原则混淆：传授知识与思想品德教育相统一是科学性与思想性相统一原则的要求；理论联系实际原则强调以实际为出发点、学以致用。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3172, 62, 21, 'judge', 0.6, '班主任了解学生最常用、最基本的方法是问卷法，观察法只在特殊情况下使用。', '[["A","正确"],["B","错误"]]', '["B"]', '方法错位：观察法是班主任了解学生最常用、最基本的方法，可在自然状态下获取真实信息；问卷法、谈话法等为辅助手段。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3173, 62, 22, 'judge', 0.6, '气质类型没有好坏之分，而性格则有优劣之别。', '[["A","正确"],["B","错误"]]', '["A"]', '气质无好坏之分（类型差异），性格有优劣之别（受社会评价）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3174, 62, 23, 'judge', 0.6, '学习仅仅是外在行为的改变，不需要个体内部的信息加工过程。', '[["A","正确"],["B","错误"]]', '["B"]', '条件缺失：学习是由经验引起的行为或行为潜能的相对持久变化，包含个体内部的信息加工过程。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3175, 62, 24, 'judge', 0.6, '正迁移就是顺向迁移，二者是按照同一标准划分出来的同一类迁移。', '[["A","正确"],["B","错误"]]', '["B"]', '概念混淆：正/负迁移按“效果”划分，顺向/逆向迁移按“方向”划分，划分标准不同，不能等同。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3176, 62, 25, 'judge', 0.6, '学习策略是先天具备的，教师无法通过教学加以培养。', '[["A","正确"],["B","错误"]]', '["B"]', '绝对化表述：学习策略是可以教授和训练的，是学习策略教学的核心观点。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3177, 62, 26, 'judge', 0.6, '学校心理健康教育就是开设一门心理健康课，其余工作由专业机构承担。', '[["A","正确"],["B","错误"]]', '["B"]', '以偏概全：心理健康教育应面向全体、渗透于学科教学与班级管理、辅以个别辅导与转介，不能只靠一门课。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3178, 62, 27, 'judge', 0.6, '《中华人民共和国义务教育法》规定，义务教育是国家统一实施的所有适龄儿童、少年必须接受的教育。', '[["A","正确"],["B","错误"]]', '["A"]', '《义务教育法》第二条：义务教育是国家统一实施的所有适龄儿童、少年必须接受的教育，是国家必须予以保障的公益性事业。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3179, 62, 28, 'judge', 0.6, '学校不得聘用因故意犯罪受到有期徒刑以上刑事处罚的人员担任教职工。', '[["A","正确"],["B","错误"]]', '["A"]', '《教师法》第十四条：受到剥夺政治权利或者故意犯罪受到有期徒刑以上刑事处罚的，不能取得教师资格，已取得的丧失教师资格；《义务教育法》第二十四条第三款、《未成年人保护法》第六十二条另有从业禁止与入职查询规定。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3180, 62, 29, 'judge', 0.6, '教师职业道德修养的最终目的在于养成良好的职业道德行为习惯。', '[["A","正确"],["B","错误"]]', '["A"]', '教师职业道德修养的最终目的在于养成良好的职业道德行为习惯，实现知行统一。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3181, 62, 30, 'judge', 0.6, '《义务教育课程方案（2022年版）》提出，劳动、综合实践活动、地方课程与校本课程的课时可统筹使用。', '[["A","正确"],["B","错误"]]', '["A"]', '2022年版课程方案提出劳动、综合实践活动、地方课程与校本课程课时可统筹使用，并强调劳动课程独立设置。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3182, 62, 31, 'single', 1.0, '在自由回忆实验中，被试对词表开头和结尾部分的记忆较好、中间部分记忆较差。这种"记忆"中的现象被称为（　）', '[["A","前摄抑制"],["B","系列位置效应"],["C","倒摄抑制"],["D","刻板效应"]]', '["B"]', '系列位置效应指在自由回忆中，开头（首因效应，因更多复述进入长时记忆）与结尾（近因效应，仍在短时记忆）的项目回忆率高于中间项目；中间部分受前摄抑制与倒摄抑制双重干扰。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3183, 62, 32, 'single', 1.0, '学生上课时一边听讲一边记笔记，还能兼顾观察板书，几项活动在同一时间内同时进行。上述表现属于注意品质中的（　）', '[["A","广度"],["B","稳定性"],["C","分配"],["D","转移"]]', '["C"]', '注意的分配指在同一时间内把注意指向两种或两种以上对象/活动；边听讲边记笔记同时进行，依赖注意分配。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3184, 62, 33, 'single', 1.0, '学生在复习时把零散知识点按逻辑关系画成思维导图、列提纲，这类学习策略属于（　）', '[["A","组织策略"],["B","复述策略"],["C","精细加工策略"],["D","资源管理策略"]]', '["A"]', '组织策略是对相关内容进行归类、整理以形成清晰结构的策略，如列提纲、画图表、构建网络关系。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3185, 62, 34, 'single', 1.0, '在问题解决中，反复思考一道难题久未解决，搁置一段时间后再回来却豁然开朗。这种“悬而不决—中断—突现”的现象称为（　）', '[["A","功能固着"],["B","酝酿效应"],["C","定势"],["D","原型启发"]]', '["B"]', '酝酿效应指问题暂时搁置后，由于潜意识仍在加工、或脱离僵化思路，重新面对时突然找到解法。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3186, 62, 35, 'single', 1.0, '奥苏贝尔认为，在儿童早期，学生努力学习往往是为了得到家长或老师的赞许与认可。这种学习动机属于（　）', '[["A","附属内驱力"],["B","认知内驱力"],["C","自我提高内驱力"],["D","成就内驱力"]]', '["A"]', '奥苏贝尔将学校情境中的成就动机分为认知内驱力（求知欲）、自我提高内驱力（赢得地位）和附属内驱力（获长者赞许）；儿童早期附属内驱力最突出。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3187, 62, 36, 'single', 1.0, '某校在组织教师业务培训时，培训专家指出：“成年教师随着年龄增长，其运用已有知识经验去解决问题的能力仍可持续提升。”依据卡特尔（Cattell）的智力理论，专家所描述的智力成分是（　）', '[["A","流体智力"],["B","晶体智力"],["C","一般智力"],["D","多元智力"]]', '["B"]', '卡特尔将智力分为流体智力（依赖先天禀赋与加工速度）与晶体智力（依赖知识经验与文化积累，随年龄增长仍可持续提升）；题干指向晶体智力。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3188, 62, 37, 'single', 1.0, '为增加学生举手发言的频率，教师在该生发言后当即给予表扬。依据操作性条件反射，这种在行为之后呈现愉快刺激、以提高该行为发生频率的做法属于（　）', '[["A","负强化"],["B","惩罚"],["C","正强化"],["D","消退"]]', '["C"]', '正强化是在期望行为之后施加愉快刺激（如表扬）以提高其发生频率；负强化是通过移除厌恶刺激来增强行为。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3189, 62, 38, 'single', 1.0, '某教师完整示范了“如何用刻度尺测量物体长度”，随后让学生复述操作步骤、在脑中回放示范动作，再动手反复练习。按班杜拉的理论，这一教学过程依次对应的观察学习子过程是（　）', '[["A","注意一保持一动作再现"],["B","保持一注意一动作再现"],["C","动作再现一注意一保持"],["D","注意一动作再现一保持"]]', '["A"]', '班杜拉把观察学习分为注意、保持、动作再现和动机四个子过程。示范—复述回放—动手练习的顺序与注意—保持—动作再现一一对应。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3190, 62, 39, 'single', 1.0, '维果斯基理论在教学上的重要应用是“支架式教学”：教师先在学生学习中提供临时性支持，待其能力增长后逐步撤去。这里的“支架”喻指（　）', '[["A","最终要学生独立完成的作业"],["B","教师提供的临时性支持与引导"],["C","固定的知识框架模板"],["D","同伴之间的竞争压力"]]', '["B"]', '支架式教学源于维果斯基“最近发展区”：教师在学习初期提供提示、示范、分解任务等临时性支持（支架），随着学生能力提高逐步撤去。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3191, 62, 40, 'single', 1.0, '某校在制定育人方案时，校长提出“学校的一切工作都应围绕升学率展开，劳动与实践活动可以全部取消”。依据《中华人民共和国教育法》规定的教育方针，该校的育人方案应当坚持（　）', '[["A","与生产劳动和社会实践相结合"],["B","与宗教相结合"],["C","与市场经济相结合"],["D","与家庭教育相脱离"]]', '["A"]', '《教育法》第五条规定的教育方针要求教育必须为社会主义现代化建设服务、为人民服务，必须与生产劳动和社会实践相结合。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3192, 62, 41, 'single', 1.0, '《中华人民共和国义务教育法》规定，教师在教育教学中应当关心、爱护学生，尊重学生的人格，不得对学生实施体罚、变相体罚或者其他侮辱人格尊严的行为。这一规定的直接目的是（　）', '[["A","提高学生的考试成绩"],["B","维护学生的人格尊严与合法权益"],["C","减轻教师工作负担"],["D","便于学校统一管理"]]', '["B"]', '《义务教育法》第二十九条要求教师关心爱护学生、尊重人格，不得实施体罚、变相体罚或侮辱人格尊严的行为；这是教师法定义务，直接目的是维护学生的人格尊严与合法权益。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3193, 62, 42, 'single', 1.0, '某中学初二学生小涛多次违纪，班主任向学校建议“干脆让他回家反省，以免影响班级”。依据《中华人民共和国未成年人保护法》（学校保护），学校对品行有缺点、学习有困难的学生应当耐心教育、帮助，不得违反法律和国家规定（　）：该班主任的建议如被采纳，即属此类。', '[["A","要求其参加课外辅导"],["B","调整其座位"],["C","开除未成年学生"],["D","与其家长沟通"]]', '["C"]', '《未成年人保护法》（学校保护）规定，学校应当关心、爱护学生，对品行有缺点、学习有困难的学生耐心教育、帮助，不得违反法律和国家规定开除未成年学生。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3194, 62, 43, 'single', 1.0, '某校教师刘某在校门口发现有人向学生兜售含有淫秽、恐怖内容的出版物。依据《中华人民共和国教师法》规定的教师义务，刘某应当（　）', '[["A","制止有害于学生的行为，批评和抵制有害于学生健康成长的现象"],["B","视而不见，校外行为不属教师职责范围"],["C","直接对兜售者实施罚款并没收出版物"],["D","只在本班家长群中提醒，无需向学校报告"]]', '["A"]', '《教师法》第八条将“制止有害于学生的行为或者其他侵犯学生合法权益的行为，批评和抵制有害于学生健康成长的现象”列为教师义务。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3195, 62, 44, 'single', 1.0, '某县因财政紧张，拟将本县教师工资与当地企业职工平均工资挂钩，并暂缓教师晋级增薪。依据《中华人民共和国教师法》，该县的做法（　）', '[["A","合法，教师工资标准可由县级人民政府根据财力自行确定"],["B","合法，只要教师平均工资不低于当地最低工资标准即可"],["C","不合法，教师的平均工资水平应当不低于或者高于国家公务员的平均工资水平，并逐步提高"],["D","不合法，但法律仅要求教师工资与公务员持平，并未要求逐步提高"]]', '["C"]', '《教师法》第二十五条规定，教师的平均工资水平应当不低于或者高于国家公务员的平均工资水平，并逐步提高。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3196, 62, 45, 'single', 1.0, '某县教育局在新设公办初中配备校长时，明确校长由县教育局依法聘任、学校日常事务由校长全面负责。依据《中华人民共和国义务教育法》，该校实行的领导体制是（　）', '[["A","党委领导下的校长负责制"],["B","教师委员会集体负责制"],["C","董事会领导下的校长负责制"],["D","校长负责制"]]', '["D"]', '《义务教育法》第二十六条规定，学校实行校长负责制；校长由县级人民政府教育行政部门依法聘任，负责学校的教育教学和行政管理工作。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3197, 62, 46, 'single', 1.0, '某小学六年级未成年学生小浩周六自行到校玩耍，攀爬体育器械时，不慎摔伤；学校已履行相应职责、行为并无不当。依据《学生伤害事故处理办法》，对该事故（　）', '[["A","学校应当承担全部赔偿责任"],["B","学校行为并无不当，不承担事故责任"],["C","学校应当承担一半责任"],["D","由班主任个人承担赔偿"]]', '["B"]', '《学生伤害事故处理办法》第十三条规定，在放学后、节假日或假期等学校工作时间以外，学生自行滞留学校或自行到校发生事故的，学校已履行相应职责、行为并无不当的，不承担事故责任。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3198, 62, 47, 'single', 1.0, '某中学教师郑某因故意犯罪被判处有期徒刑三年，学校拟作出处理。依据《中华人民共和国教师法》《教师资格条例》，该教师的教师资格应当（　）', '[["A","丧失，且不能重新取得"],["B","保留，待其刑满释放后继续有效"],["C","由所在学校决定暂停或者恢复"],["D","暂缓注册，五年后自动恢复"]]', '["A"]', '《教师法》第十四条与《教师资格条例》规定，受到剥夺政治权利或者故意犯罪受到有期徒刑以上刑事处罚的，不能取得教师资格，已经取得的丧失教师资格且不能重新取得。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3199, 62, 48, 'single', 1.0, '某校教师冯老师多次在节假日组织学生有偿补课，并通过家长群推销教辅资料获利。依据《新时代中小学教师职业行为十项准则》，冯老师的行为主要违背的准则是（　）', '[["A","坚定政治方向"],["B","自觉爱国守法"],["C","潜心教书育人"],["D","为人师表（坚守廉洁自律）"]]', '["D"]', '“坚守廉洁自律”要求教师不得索要、收受学生及家长财物，“规范从教行为”要求自觉抵制有偿补课；组织有偿补课并借家长群推销教辅获利，集中违背为人师表。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3200, 62, 49, 'single', 1.0, '某校教师钱老师只按考试成绩排座位、只关注前几名学生，对后进生放任不管。依据《中小学教师职业道德规范》中“教书育人”的要求，钱老师的做法主要违背了（　）', '[["A","遵循教育规律，实施素质教育，不以分数作为评价学生的唯一标准"],["B","只关注学生的考试成绩"],["C","按家长要求布置作业"],["D","优先培养少数尖子生"]]', '["A"]', '“教书育人”要求遵循教育规律实施素质教育，循循善诱、因材施教，不以分数作为评价学生的唯一标准；按成绩排座位、只关注尖子生并放任后进生，均违背该要求。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3201, 62, 50, 'single', 1.0, '某中学学生小宇经常旷课、顶撞教师，班主任多次教育时，他仍不改正。依据《中华人民共和国教育法》，受教育者应当履行的义务是（　）', '[["A","遵守法律、法规，遵守学生行为规范，尊敬师长，努力学习，完成规定的学习任务"],["B","参加教育教学计划安排的各种活动，使用教育教学设施、设备、图书资料"],["C","按照国家有关规定获得奖学金、贷学金、助学金"],["D","在学业成绩和品行上获得公正评价，完成规定学业后获得相应证书"]]', '["A"]', '《教育法》规定受教育者应当履行下列义务：遵守法律、法规；遵守学生行为规范，尊敬师长，养成良好的思想品德和行为习惯；努力学习，完成规定的学习任务。B、C、D属受教育者的权利而非义务。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3202, 62, 51, 'single', 1.0, '某县在落实“双减”工作中拟采取一系列措施。下列措施中，属于“双减”政策治理重点的是（　）', '[["A","减少学校课程门类和课时"],["B","取消所有考试与作业"],["C","减轻学生过重作业负担和校外培训负担"],["D","降低教师待遇"]]', '["C"]', '“双减”即减轻义务教育阶段学生过重作业负担和校外培训负担，目标是提升学校教育教学质量、作业设计质量与课后服务水平。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3203, 62, 52, 'single', 1.0, '某校在组织劳动教育周时，安排学生到校内种植园翻地播种、走进社区敬老院开展志愿服务，并向家长发放家务劳动清单。依据《关于全面加强新时代大中小学劳动教育的意见》，该校安排的劳动教育内容涵盖（　）', '[["A","日常起居事务"],["B","纯理论讲座"],["C","商业经营活动"],["D","日常生活劳动、生产劳动和服务性劳动"]]', '["D"]', '《关于全面加强新时代大中小学劳动教育的意见》明确劳动教育内容为日常生活劳动、生产劳动和服务性劳动三类。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3204, 62, 53, 'single', 1.0, '按照课程资源的功能特点，可将其划分为（　）', '[["A","校内课程资源与校外课程资源"],["B","素材性课程资源与条件性课程资源"],["C","显性课程资源与隐性课程资源"],["D","自然课程资源与社会课程资源"]]', '["B"]', '按功能特点，课程资源分为素材性资源（知识、经验等）与条件性资源（人力、物力、财力等）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3205, 62, 54, 'single', 1.0, '下列因素中，不属于影响课程实施的因素的是（　）', '[["A","学生家庭的经济收入水平"],["B","课程方案本身的特征"],["C","教师的特征与态度"],["D","学校的支持与外部评价环境"]]', '["A"]', '影响课程实施的因素包括课程方案特征、教师特征、学校支持与外部环境，家庭经济收入属校外环境中较间接的因素。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3206, 62, 55, 'single', 1.0, '关于教学与教育、智育的关系，下列说法正确的是（　）', '[["A","教学等于教育，二者没有区别"],["B","教学是实施全面发展教育的基本途径，智育主要通过教学来实现"],["C","教学是智育的唯一途径"],["D","教育与智育是同一概念"]]', '["B"]', '教学是实施全面发展教育的基本途径；智育主要通过教学实现，但还有其他途径。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3207, 62, 56, 'single', 1.0, '“温故而知新”学而时习之”体现的教学原则是（　）', '[["A","巩固性原则"],["B","量力性原则"],["C","因材施教原则"],["D","直观性原则"]]', '["A"]', '“温故而知新”学而时习之”体现巩固性原则。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3208, 62, 57, 'single', 1.0, '教师选择教学方法时需要考虑的首要依据是（　）', '[["A","教师个人的喜好"],["B","教学目标与任务"],["C","学校的硬件条件"],["D","家长的期望"]]', '["B"]', '选择教学方法的首要依据是教学目标与任务，同时兼顾内容、学生与条件。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3209, 62, 58, 'single', 1.0, '班级授课制的特殊形式是（　）', '[["A","现场教学"],["B","个别辅导"],["C","分组教学"],["D","复式教学"]]', '["D"]', '复式教学是班级授课制的特殊形式（把不同年级编在一个班教学）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3210, 62, 59, 'single', 1.0, '一堂好课的基本要求不包括（　）', '[["A","目标明确、重点突出"],["B","内容正确、方法得当"],["C","板书越多越好、教师讲得越满越好"],["D","表达清晰、气氛热烈"]]', '["C"]', '好课标准重在教学有效，“板书越多越好、讲得越满越好”属错误认识。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3211, 62, 60, 'single', 1.0, '某中学在月考后按成绩对学生排名并张榜公布，据此调整分层编班。按评价所参照的标准划分，该校采用的评价属于（　）', '[["A","相对性评价"],["B","绝对性评价"],["C","个体内差异评价"],["D","诊断性评价"]]', '["A"]', '相对性评价以被评价者在群体中的相对位置为参照标准；该校按成绩排名并据此分层编班，即属相对性评价。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3212, 62, 61, 'single', 1.0, '德育过程与学生品德形成过程的关系是（　）', '[["A","二者完全等同"],["B","品德形成过程属于教育过程的一部分"],["C","德育过程是教育者有目的的培养过程，品德形成过程是学生个体自我发展的过程"],["D","二者互不相关"]]', '["C"]', '德育过程是教育者有目的、有计划的培养过程，品德形成过程是学生个体内部的发展过程，二者相互联系但性质不同。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3213, 62, 62, 'single', 1.0, '马卡连柯说"要尽量多地要求一个人，也要尽可能地尊重一个人”。这体现的德育原则是（　）', '[["A","疏导原则"],["B","长善救失原则"],["C","知行统一原则"],["D","严格要求与尊重学生相结合原则"]]', '["D"]', '“尽量多地要求、尽可能地尊重”体现严格要求与尊重学生相结合原则。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3214, 62, 63, 'single', 1.0, '某班班主任在期末给学生写操行评语，对表现突出的学生颁发"文明之星”奖状，对违纪学生给予批评。该班主任采用的德育方法是（　）', '[["A","说服教育法"],["B","榜样示范法"],["C","品德评价法"],["D","情感陶冶法"]]', '["C"]', '表扬与奖励、批评与处分、操行评定均属品德评价法（奖惩法）。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3215, 62, 64, 'single', 1.0, '某校在德育研讨中，有教师提出：“德育的关键在于引导学生运用道德推理处理两难情境，通过提高其道德判断水平来促进品德发展。”这一主张所依据的德育模式是（　）', '[["A","体谅模式"],["B","社会模仿模式"],["C","价值澄清模式"],["D","认知性道德发展模式"]]', '["D"]', '认知性道德发展模式（皮亚杰、科尔伯格）以道德认知发展为基础，借助道德两难问题讨论提高学生的道德判断能力。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3216, 62, 65, 'single', 1.0, '某班班主任李老师凡事亲力亲为，班干部形同虚设，班级活动全由其一手安排。下列做法中，不属于培养和建设班集体一般方法的是（　）', '[["A","确立共同的奋斗目标"],["B","由班主任包办一切班级事务"],["C","选拔和培养学生干部"],["D","开展丰富多彩的集体活动"]]', '["B"]', '培养班集体需确立目标、培养干部、开展活动、形成舆论班风、健全制度，并发挥学生主体作用；由班主任包办一切班级事务不利于班集体形成。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3217, 62, 66, 'single', 1.0, '班主任组织家长会时，下列做法最恰当的是（　）', '[["A","只通报学生成绩排名，便于家长比较"],["B","点名批评成绩落后学生及其家长"],["C","介绍班级情况与教育要求，同时倾听家长意见"],["D","只与优生家长交流，其余家长不必参加"]]', '["C"]', '家长会应介绍班级情况与教育要求，同时倾听家长意见，避免排名与点名批评。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3218, 62, 67, 'single', 1.0, '某校为帮助新入职教师尽快胜任教学，安排骨干教师与其结对，定期听课评课、共同备课、共同打磨教学设计。这种促进教师专业发展的途径属于（　）', '[["A","自我教育"],["B","学历进修"],["C","脱产培训"],["D","师徒结对"]]', '["D"]', '师徒结对（导师制）通过资深教师传帮带，在日常教学实践中促进新教师成长，是校本培训的主要形式之一。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3219, 62, 68, 'single', 1.0, '学生初学某项内容时需要注意努力维持注意，熟练后不需意志努力也能专注。这时的注意属于（　）', '[["A","无意注意"],["B","有意注意"],["C","有意后注意"],["D","转移中的注意"]]', '["C"]', '有意后注意是有目的但不需要意志努力的注意，常见于熟练活动。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3220, 62, 69, 'single', 1.0, '某校教师何老师在复习指导时，让学生把"及时复习""分散复习""尝试回忆与反复阅读相结合"结合起来。该教师这样做主要是为了（　）', '[["A","增加作业数量"],["B","减少教学时间"],["C","提高记忆效果，克服遗忘"],["D","降低学习难度"]]', '["C"]', '及时复习、分散复习、尝试回忆与反复阅读相结合，都是提高记忆效果、克服遗忘的有效策略。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3221, 62, 70, 'single', 1.0, '学生根据课文描述在头脑中再现"草原"的画面，这属于（　）', '[["A","创造想象"],["B","幻想"],["C","表象记忆"],["D","再造想象"]]', '["D"]', '依据语言描述在头脑中再现相应形象，属再造想象。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3222, 62, 71, 'single', 1.0, '解决问题时，把总目标分解为一系列子目标，通过逐步缩小差距达到总目标。这种策略称为（　）', '[["A","爬山法"],["B","手段一目的分析法"],["C","逆向搜索法"],["D","类比法"]]', '["B"]', '手段一目的分析法：把总目标分解为子目标，逐步缩小当前状态与目标状态的差距。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3223, 62, 72, 'single', 1.0, '学生因考试失败而长期情绪低落、失眠、注意力无法集中，班主任最恰当的做法是（　）', '[["A","劝其\\"想开点”，不必过多关注"],["B","耐心倾听、给予支持，必要时转介学校心理辅导教师"],["C","当众鼓励其\\"下次一定行\\""],["D","直接要求家长带其就医"]]', '["B"]', '班主任应耐心倾听、提供支持，并在必要时转介专业心理辅导。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3224, 62, 73, 'single', 1.0, '意志行动的心理过程一般分为（　）两个阶段。', '[["A","动机斗争与目的确立"],["B","制定计划与检查结果"],["C","尝试错误与顿悟"],["D","采取决定与执行决定"]]', '["D"]', '意志行动分为采取决定（动机斗争、确定目的、选择方法）与执行决定两个阶段。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3225, 62, 74, 'single', 1.0, '性格的结构特征中，表现为个体对自己、对他人、对集体、对劳动的态度方面的是（　）', '[["A","态度特征"],["B","意志特征"],["C","情绪特征"],["D","理智特征"]]', '["A"]', '性格的态度特征表现为对自己、他人、集体、劳动、学习的态度。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3226, 62, 75, 'single', 1.0, '托尔曼通过白鼠走迷宫实验提出，学习是对情境形成"认知地图”，这一理论被称为（　）', '[["A","试误说"],["B","顿悟说"],["C","观察学习理论"],["D","符号学习理论（认知一目的说）"]]', '["D"]', '托尔曼提出符号学习理论（认知一目的说），认为学习形成“认知地图”。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3227, 62, 76, 'single', 1.0, '某校教师吕老师在学生完成练习后，当天批改并逐一告知结果、提出改进建议。该教师这样做主要满足了学习动机激发中的（　）', '[["A","惩罚与威胁"],["B","增加作业量"],["C","及时反馈与评价"],["D","提高考试难度"]]', '["C"]', '及时告知结果并提出改进建议属于反馈与评价，可让学生看到进步与不足，是激发动机的重要措施。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3228, 62, 77, 'single', 1.0, '为促进迁移而进行的教学，关键在于（　）', '[["A","加大练习量，反复训练同一题型"],["B","精选教材、合理编排内容、教授学习策略"],["C","只讲结论，节省时间"],["D","减少知识间的联系，避免干扰"]]', '["B"]', '促进迁移的教学策略：精选教材、合理编排教学内容、教授学习策略与迁移方法。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3229, 62, 78, 'single', 1.0, '某校体育教师宋老师在指导学生练习广播体操时发现，学生的动作逐渐协调连贯，视觉控制减弱、动觉控制增强。该阶段属于操作技能形成的（　）', '[["A","操作定向"],["B","操作模仿"],["C","操作整合"],["D","操作熟练"]]', '["C"]', '操作整合阶段动觉控制增强、视觉控制减弱，动作趋于协调连贯，多余动作减少。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3230, 62, 79, 'single', 1.0, '某中学将七年级新生按入学成绩分为“实验班”与“普通班”，配备不同师资与教室。依据《中华人民共和国义务教育法》，该校的做法（　）', '[["A","属于学校自主管理范围，合法有效"],["B","只要报县级教育行政部门备案即可实施"],["C","只要家长同意，法律不予禁止"],["D","学校不得分设重点班和非重点班，该校做法违反法律规定"]]', '["D"]', '《义务教育法》第二十二条规定，学校不得分设重点班和非重点班；以入学成绩划分“实验班”“普通班”并配置不同师资与教室，违反该规定。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3231, 62, 80, 'single', 1.0, '当前推进的教育数字化战略，其核心指向是（　）', '[["A","以数字技术赋能教育高质量发展，扩大优质教育资源覆盖面"],["B","以线上教学全面替代课堂教学"],["C","取消教师讲授，全部由学生自学"],["D","用技术设备数量衡量教育现代化水平"]]', '["A"]', '教育数字化以技术赋能教育高质量发展、扩大优质资源覆盖面为核心，不是替代课堂教学。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3232, 62, 81, 'multi', 1.6, '感觉记忆、短时记忆与长时记忆构成三级信息加工系统，下列描述符合该理论的有（　）', '[["A","瞬时记忆（感觉记忆）保持时间极短，容量较大"],["B","短时记忆容量约为7±2个组块"],["C","长时记忆保持时间长久，容量几乎无限"],["D","短时记忆中的信息若不复述，会迅速遗忘"],["E","瞬时记忆中的信息若受到注意可转入短时记忆，未受到注意则迅速消失"]]', '["A","B","C","D","E"]', '记忆按信息加工分为瞬时记忆（容量较大、保持极短，受注意可转入短时记忆，未受注意则迅速消失）、短时记忆（7±2 组块，需复述方能转入长时）、长时记忆（容量近乎无限、保持长久）；五项表述均正确。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3233, 62, 82, 'multi', 1.6, '操作技能与心智技能在形成过程和特点上存在差异，下列判断正确的有（　）', '[["A","心智技能只能通过口头讲授获得，无需练习"],["B","操作技能依赖骨骼肌肉运动，心智技能依赖头脑中的认知活动"],["C","操作技能的形成一般经过操作定向、模仿、整合、熟练等阶段"],["D","心智技能按加里培林观点经历从外部言语到内部言语的阶段"],["E","二者都通过练习形成，都是程序性知识的应用"]]', '["B","C","D","E"]', '操作技能依赖肌肉运动、心智技能依赖认知活动，二者均经练习形成、属程序性知识应用；操作技能经历定向一模仿一整合一熟练，心智技能按加里培林观点经历从外部言语到内部言语阶段。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3234, 62, 83, 'multi', 1.6, '《中华人民共和国教育法》对教育经费投入与办学条件保障作出的规定包括（　）', '[["A","学校可以自行决定扣减教师工资用于基建开支"],["B","国家建立以财政拨款为主、其他多种渠道筹措教育经费为辅的体制"],["C","义务教育阶段不收学费、杂费，国家建立义务教育经费保障机制"],["D","税务机关依法足额征收教育费附加，专项用于教育事业"],["E","国家鼓励境内外社会组织和个人捐资助学"]]', '["B","C","D","E"]', '《教育法》规定国家建立以财政拨款为主、其他多种渠道筹措教育经费为辅的体制；义务教育阶段不收学费杂费、建立经费保障机制；税务机关依法足额征收教育费附加专项用于教育；国家鼓励境内外组织和个人捐资助学。学校擅自扣减教师工资违法。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3235, 62, 84, 'multi', 1.6, '某校拟修订校规校纪中的教育惩戒条款，并就“哪些行为属于惩戒禁区、学生和家长不服时如何救济”征求教师意见。依据《中小学教育惩戒规则（试行）》，下列判断正确的有（　）', '[["A","学校可以对违规学生处以罚款，罚款收入纳入学校公用经费"],["B","教师不得以击打、刺扎等方式直接造成身体痛苦，不得以歧视性、侮辱性的言行侵犯学生人格尊严"],["C","教师不得因个人情绪或者好恶，实施或者选择性实施教育惩戒"],["D","学生或者家长对学校实施的较重教育惩戒、纪律处分不服的，可以依法向学校提起申诉"],["E","学校拟实施较重教育惩戒或者给予纪律处分的，应当听取学生的陈述和申辩"]]', '["B","C","D","E"]', '《中小学教育惩戒规则（试行）》第十二条列举教师实施惩戒的禁止行为：体罚、变相体罚、侮辱歧视、因个人情绪好恶选择性实施惩戒等；第十四条要求学校拟实施较重惩戒或纪律处分时听取学生陈述和申辩；第十七条规定学生及家长不服的可依法申诉。学校无权对违规学生处以罚款。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3236, 62, 85, 'multi', 1.6, '教学过程的基本阶段包括（　）', '[["A","教师备课与编写教案"],["B","激发学习动机"],["C","领会知识"],["D","巩固知识"],["E","检查知识"]]', '["B","C","D","E"]', '教学过程的基本阶段包括：激发学习动机、领会知识（中心环节）、巩固知识、运用知识、检查知识；“教师备课与编写教案”属于教学工作的基本环节，不属于课堂教学“教学过程”的基本阶段。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3237, 62, 86, 'multi', 1.6, '德育过程的基本规律包括（　）', '[["A","学生的知、情、意、行统一发展"],["B","学生思想品德一旦形成便不会倒退或反复"],["C","学生在活动和交往中形成思想品德"],["D","德育过程只能在课堂内完成"],["E","学生思想内部矛盾转化"]]', '["A","C","E"]', '德育规律：知情理意行统一发展、在活动和交往中形成、思想内部矛盾转化，均正确；“一旦形成便不反复”违背长期性与反复性规律；“只能在课堂内完成”亦错。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3238, 62, 87, 'multi', 1.6, '良好的记忆品质包括（　）', '[["A","敏捷性"],["B","持久性"],["C","易变性"],["D","冲动性"],["E","准确性"]]', '["A","B","E"]', '良好记忆品质：敏捷性、持久性、准确性，均正确；“易变性”非记忆品质；“冲动性”亦非记忆品质。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3239, 62, 88, 'multi', 1.6, '影响遗忘进程的因素主要有（　）', '[["A","学习材料的性质与数量"],["B","学习程度（过度学习的程度）"],["C","识记材料的系列位置（首因效应、近因效应）"],["D","识记者的态度与需要"],["E","识记时的天气状况"]]', '["A","B","C","D"]', '影响遗忘的因素包括材料性质与数量、学习程度、系列位置、识记者态度与需要、识记方法等。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3240, 62, 89, 'multi', 1.6, '依据《中华人民共和国家庭教育促进法》，未成年人的父母或者其他监护人实施家庭教育时，应当关注的内容包括（　）', '[["A","教育未成年人爱党、爱国、爱人民、爱集体、爱社会主义，培养家国情怀"],["B","只需关注学业成绩，其他方面可暂不涉及"],["C","教育未成年人崇德向善，培养家庭美德与个人品德，增强法治意识"],["D","树立正确劳动观念，培养生活自理能力与吃苦耐劳品质"],["E","家庭教育由学校统一安排，家长无需主动实施"]]', '["A","C","D"]', '《家庭教育促进法》第十六条规定家庭教育应关注家国情怀培养、崇德向善与法治意识、正确成才观与身心健康、劳动观念与生活自理能力等方面；“只需关注学业成绩”“由学校统一安排、家长无需主动实施”均违背父母或其他监护人的家庭教育主体责任。');
INSERT INTO `questions` (`id`, `paper_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`) VALUES (3241, 62, 90, 'multi', 1.6, '某市教研室组织教师集中研读《义务教育课程方案（2022年版）》及各学科课程标准。关于该方案对各学校课程实施、学段衔接与评价改革提出的要求，下列说法正确的有（　）', '[["A","各学科课程标准以核心素养为纲，强化学科实践与综合性学习"],["B","跨学科主题学习由学校自行决定是否开设，方案不作统一要求"],["C","方案要求加强学段衔接，合理设计不同学段的学习内容与要求"],["D","该方案取消了综合实践活动课程，课时全部并入语文、数学、英语等学科"],["E","学校应因地制宜统筹实施综合实践活动、劳动、地方课程与校本课程"]]', '["A","C","E"]', '2022版课程方案要求各学科课程标准以核心素养为纲、强化学科实践与综合性学习，加强学段衔接，学校因地制宜统筹实施综合实践活动、劳动、地方课程与校本课程；跨学科主题学习有明确的课时比例要求，综合实践活动课程亦未被取消。');
